import { type ComponentPropsWithRef, type CSSProperties, type ReactElement, type ReactNode } from 'react';

import { createPortal } from 'react-dom';

import { cn } from '#/utils/Styles/cn';

type DawContextMenuSurfaceProps = ComponentPropsWithRef<'div'> & {
    x: number;
    y: number;
    children?: ReactNode;
    xClampOffset?: number;
    yClampOffset?: number;
    anchorY?: 'down' | 'up' | 'auto';
    backdrop?: boolean;
    portal?: boolean;
    onClose?: () => void;
    style?: CSSProperties;
};

export const DawContextMenuSurface = ({
    x,
    y,
    children,
    xClampOffset = 200,
    yClampOffset = 400,
    anchorY = 'down',
    backdrop = false,
    portal = true,
    onClose,
    className,
    style,
    ...props
}: DawContextMenuSurfaceProps): ReactElement => {
    const useBottomAnchor = anchorY === 'up' || (anchorY === 'auto' && y > window.innerHeight - yClampOffset);
    const positionStyle: CSSProperties = useBottomAnchor
        ? {
              left: Math.min(x, window.innerWidth - xClampOffset),
              bottom: Math.max(8, window.innerHeight - y),
          }
        : {
              left: Math.min(x, window.innerWidth - xClampOffset),
              top: Math.min(y, window.innerHeight - yClampOffset),
          };

    const surface = (
        <>
            {backdrop && onClose ? <div className="fixed inset-0 z-40" onClick={onClose} /> : null}
            <div
                className={cn('daw-floating-surface fixed z-50 rounded-md py-1', className)}
                style={{ ...positionStyle, ...style }}
                {...props}
            >
                {children}
            </div>
        </>
    );

    if (!portal) {
        return <>{surface}</>;
    }

    return createPortal(surface, document.body);
};

import { type ReactElement, type PointerEvent, useState, useRef } from 'react';

import { cn } from '#/utils/Styles/cn';

type Tone =
    | 'neutral'
    | 'amber'
    | 'cyan'
    | 'peach'
    | 'lavender'
    | 'mint'
    | 'steel'
    | 'danger'
    | 'rose'
    | 'indigo'
    | 'sage'
    | 'copper';

const TONE_CLASS_NAMES: Record<Tone, string> = {
    neutral: 'bg-white/50',
    amber: 'bg-[var(--color-accent-amber)]',
    cyan: 'bg-[var(--color-accent-cyan)]',
    peach: 'bg-[var(--color-accent-peach)]',
    lavender: 'bg-[var(--color-accent-lavender)]',
    mint: 'bg-[var(--color-accent-mint)]',
    steel: 'bg-[var(--color-accent-steel)]',
    danger: 'bg-[var(--color-state-danger)]',
    rose: 'bg-[var(--color-accent-rose)]',
    indigo: 'bg-[var(--color-accent-indigo)]',
    sage: 'bg-[var(--color-accent-sage)]',
    copper: 'bg-[var(--color-accent-copper)]',
};

type FaderProps = {
    value: number;
    onChange: (val: number) => void;
    min?: number;
    max?: number;
    step?: number;
    fineStep?: number;
    defaultValue?: number;
    bipolar?: boolean;
    height?: number;
    showScale?: boolean;
    className?: string;
    /** Color tone for the active cap indicator */
    tone?: Tone;
};

/** dB marks for the fader scale */
const DB_MARKS = [6, 0, -6, -12, -24, -48] as const;

/**
 * Fader
 * Vertical mixer fader with metallic cap, groove track, and dB scale.
 * Drag cap to slide, Shift for fine mode, double-click to reset.
 */
export const Fader = ({
    value,
    onChange,
    min = -70,
    max = 6,
    step = 0.5,
    fineStep = 0.1,
    defaultValue = 0,
    bipolar = false,
    height = 150,
    showScale = false,
    className,
    tone = 'cyan',
}: FaderProps): ReactElement => {
    const [isDragging, setIsDragging] = useState(false);
    const draggingRef = useRef(false);
    const trackRef = useRef<HTMLDivElement>(null);
    const startY = useRef(0);
    const startValue = useRef(value);

    const normalized = Math.max(0, Math.min(1, (value - min) / (max - min)));

    const clampAndSnap = (value1: number) => {
        let clamped = Math.max(min, Math.min(max, value1));
        if (bipolar && Math.abs(clamped - defaultValue) < (max - min) * 0.05) {
            clamped = defaultValue;
        }
        return clamped;
    };

    const handlePointerDown = (event: PointerEvent<HTMLDivElement>) => {
        if (event.button !== 0 || !trackRef.current) {
            return;
        }
        if (event.altKey) {
            onChange(defaultValue);
            return;
        }
        if (typeof event.currentTarget.setPointerCapture === 'function') {
            event.currentTarget.setPointerCapture(event.pointerId);
        }
        draggingRef.current = true;
        setIsDragging(true);

        const capEl = event.currentTarget.querySelector('[data-role="fader-cap"]');
        const isCapClick = capEl?.contains(event.target as Node);

        if (!isCapClick) {
            const rect = trackRef.current.getBoundingClientRect();
            const percent = 1 - (event.clientY - rect.top) / rect.height;
            const newValue = clampAndSnap(min + percent * (max - min));
            onChange(newValue);
            startValue.current = newValue;
            startY.current = event.clientY;
        } else {
            startValue.current = value;
            startY.current = event.clientY;
        }
    };

    const handlePointerMove = (event: PointerEvent<HTMLDivElement>) => {
        if (!draggingRef.current) {
            return;
        }
        const deltaY = startY.current - event.clientY;
        const currentStep = event.shiftKey ? fineStep : step;
        const pxPerUnit = height / (max - min);
        let sensitivity = 1 / pxPerUnit;
        if (event.shiftKey) {
            sensitivity *= 0.1;
        }
        let newValue = startValue.current + deltaY * sensitivity;
        newValue = Math.round(newValue / currentStep) * currentStep;
        onChange(clampAndSnap(newValue));
    };

    const handlePointerUp = (event: PointerEvent<HTMLDivElement>) => {
        draggingRef.current = false;
        setIsDragging(false);
        if (typeof event.currentTarget.releasePointerCapture === 'function') {
            event.currentTarget.releasePointerCapture(event.pointerId);
        }
    };

    const handleDoubleClick = () => {
        onChange(defaultValue);
    };

    const capBottomPct = normalized * 100;
    const unityPct = Math.max(0, Math.min(100, ((defaultValue - min) / (max - min)) * 100));

    return (
        <div
            className={cn('relative flex items-center select-none group', className)}
            style={{ height }}
            onPointerDown={handlePointerDown}
            onPointerMove={handlePointerMove}
            onPointerUp={handlePointerUp}
            onDoubleClick={handleDoubleClick}
        >
            {/* dB scale marks (left side) */}
            {showScale ? (
                <div className="pointer-events-none absolute -left-6 top-0 bottom-0 flex w-5 flex-col justify-between">
                    {DB_MARKS.map((db) => {
                        const pct = ((db - min) / (max - min)) * 100;
                        return (
                            <span
                                key={db}
                                className={cn(
                                    'absolute right-0 font-mono text-[8px] leading-none tracking-[0.08em]',
                                    db === 0 ? 'text-text-primary' : 'text-text-disabled'
                                )}
                                style={{ bottom: `${pct}%`, transform: 'translateY(50%)' }}
                            >
                                {db > 0 ? `+${db}` : String(db)}
                            </span>
                        );
                    })}
                </div>
            ) : null}

            {/* Track groove */}
            <div
                ref={trackRef}
                className="daw-inset-surface absolute top-0 bottom-0 left-1/2 w-[5px] -translate-x-1/2 overflow-hidden rounded-full"
                style={{
                    background:
                        'linear-gradient(90deg, rgba(255,255,255,0.012) 0%, rgba(255,255,255,0.02) 48%, rgba(0,0,0,0.16) 100%), linear-gradient(90deg, #070707 0%, #0b0b0b 44%, #080808 100%)',
                }}
            >
                {/* Unity gain line */}
                <div
                    className="absolute w-full h-px z-0"
                    style={{
                        bottom: `${unityPct}%`,
                        background: 'rgba(255,255,255,0.15)',
                    }}
                />

                {/* Tick marks at the right side for visual reference */}
                {showScale
                    ? DB_MARKS.map((db) => {
                          const pct = ((db - min) / (max - min)) * 100;
                          return (
                              <div
                                  key={db}
                                  className="absolute right-0 w-[2px] h-px bg-white/10"
                                  style={{ bottom: `${pct}%` }}
                              />
                          );
                      })
                    : null}
            </div>

            {/* Fader cap */}
            <div
                data-role="fader-cap"
                className={cn(
                    'absolute w-8 h-10 left-1/2 -ml-4 rounded-sm z-10',
                    'transition-all duration-instant',
                    isDragging ? 'cursor-grabbing' : 'cursor-grab',
                    'flex flex-col items-center justify-center gap-[2px]'
                )}
                style={{
                    bottom: `calc(${capBottomPct}% - 20px)`,
                    background: isDragging
                        ? 'linear-gradient(180deg, #484848 0%, #373737 24%, #2d2d2d 52%, #252525 76%, #1e1e1e 100%)'
                        : 'linear-gradient(180deg, #545454 0%, #3e3e3e 25%, #353535 50%, #2b2b2b 75%, #222 100%)',
                    border: '1px solid rgba(255,255,255,0.05)',
                    borderTopColor: isDragging ? 'rgba(255,255,255,0.04)' : 'rgba(255,255,255,0.12)',
                    borderLeftColor: isDragging ? 'rgba(255,255,255,0.03)' : 'rgba(255,255,255,0.06)',
                    borderBottomColor: 'rgba(0,0,0,0.4)',
                    borderRightColor: 'rgba(0,0,0,0.2)',
                    boxShadow: isDragging
                        ? 'inset 0 2px 4px rgba(0,0,0,0.6)'
                        : 'inset 0 1px 0 rgba(255,255,255,0.08), inset 0 -1px 0 rgba(0,0,0,0.24), 0 2px 4px rgba(0,0,0,0.6)',
                }}
            >
                {/* Center groove marks */}
                <div className={cn('w-4 h-px', isDragging ? TONE_CLASS_NAMES[tone] : 'bg-white/10')} />
                <div className="w-5 h-px bg-white/15" />
                <div className={cn('w-4 h-px', isDragging ? TONE_CLASS_NAMES[tone] : 'bg-white/10')} />
            </div>
        </div>
    );
};

import { type ReactElement, type ButtonHTMLAttributes, type Ref } from 'react';

import { cn } from '#/utils/Styles/cn';

type LatchButtonProps = ButtonHTMLAttributes<HTMLButtonElement> & {
    active?: boolean;
    variant?: 'cyan' | 'mint' | 'amber' | 'red' | 'neutral';
    size?: 'xs' | 'sm' | 'md' | 'lg' | 'icon' | 'icon-sm';
    ref?: Ref<HTMLButtonElement>;
};

/**
 * LatchButton
 *
 * A tactile DAW toggle that physically "sinks" into the panel when active.
 * Uses inverted shadows + reversed gradient + translateY(1px) for realism.
 * Built for React 19 (no forwardRef).
 */
export function LatchButton({
    active = false,
    variant = 'neutral',
    size = 'md',
    className,
    children,
    ref,
    ...props
}: LatchButtonProps): ReactElement {
    // Variant mapping for the active localized glow and text color
    const activeStyles = {
        cyan: 'text-accent-cyan drop-shadow-[0_0_4px_var(--color-accent-cyan)]',
        mint: 'text-accent-mint drop-shadow-[0_0_4px_var(--color-accent-mint)]',
        amber: 'text-state-solo drop-shadow-[0_0_4px_var(--color-state-solo)]',
        red: 'text-state-record drop-shadow-[0_0_5px_var(--color-state-record)]',
        neutral: 'text-text-primary',
    };

    // Active colored glow box-shadows per variant (adds halo around the button itself)
    const activeGlowShadow: Record<string, string> = {
        cyan: ', 0 0 8px rgba(127,184,196,0.3)',
        mint: ', 0 0 8px rgba(125,184,160,0.3)',
        amber: ', 0 0 8px rgba(247,167,56,0.3)',
        red: ', 0 0 8px rgba(255,64,50,0.35)',
        neutral: '',
    };

    const sizeStyles = {
        xs: 'h-5 px-1.5 text-[10px] rounded-micro',
        sm: 'h-6 px-2 text-[10px] rounded-sm',
        md: 'h-8 px-3 text-xs rounded-sm',
        lg: 'h-10 px-4 text-sm rounded-md',
        icon: 'size-6 flex items-center justify-center rounded-sm p-0',
        'icon-sm': 'size-5 flex items-center justify-center rounded-sm p-0',
    };

    return (
        <button
            ref={ref}
            type="button"
            data-active={active}
            className={cn(
                // Base structure & smooth DAW transitions
                'relative inline-flex items-center justify-center font-medium select-none overflow-hidden cursor-pointer',
                'transition-[color,background,border-color,box-shadow,transform,filter] duration-fast easing-press',
                'focus:outline-none focus-visible:ring-1 focus-visible:ring-border-focus',
                'disabled:opacity-50 disabled:pointer-events-none',

                // Hardware layout size
                sizeStyles[size],

                className
            )}
            style={
                active
                    ? {
                          // Reversed gradient + deep inset — sinks INTO the panel
                          background: 'linear-gradient(180deg, #111 0%, #181818 50%, #1c1c1c 100%)',
                          boxShadow: `inset 0 2px 4px rgba(0,0,0,0.6), inset 0 1px 1px rgba(0,0,0,0.4)${
                              activeGlowShadow[variant]
                          }`,
                          border: '1px solid rgba(0,0,0,0.6)',
                          borderTopColor: 'rgba(0,0,0,0.8)',
                          borderBottomColor: 'rgba(255,255,255,0.03)',
                          transform: 'translateY(1px)',
                      }
                    : {
                          // Raised with NW light model, darkened slightly
                          background: 'linear-gradient(180deg, #1d1d1d 0%, #171717 42%, #111111 100%)',
                          boxShadow:
                              '0 2px 4px rgba(0,0,0,0.5), inset 0 1px 0 rgba(255,255,255,0.08), inset 0 -1px 0 rgba(0,0,0,0.24)',
                          border: '1px solid var(--color-border-soft)',
                          borderTopColor: 'var(--color-light-edge)',
                          borderLeftColor: 'rgba(255,255,255,0.04)',
                          borderBottomColor: 'rgba(0,0,0,0.3)',
                      }
            }
            {...props}
        >
            <span
                className={cn(
                    'flex items-center gap-1.5',
                    active ? activeStyles[variant] : 'text-text-secondary hover:text-text-primary'
                )}
            >
                {children}
            </span>
        </button>
    );
}

import { type MouseEvent, type ReactElement, type PointerEvent, useRef } from 'react';

import { useStore } from '#/infra/store/useStore';
import { midiLearnStore, type MidiLearnState } from '#/modules/MIDI/stores';
import { startMidiLearn } from '#/modules/MIDI/useCases';
import { cn } from '#/utils/Styles/cn';

const defaultMidiLearnState: MidiLearnState = {
    mappings: [],
    isLearning: false,
    learningTarget: null,
};

type Tone =
    | 'neutral'
    | 'amber'
    | 'cyan'
    | 'peach'
    | 'lavender'
    | 'mint'
    | 'steel'
    | 'danger'
    | 'rose'
    | 'indigo'
    | 'sage'
    | 'copper';

const TONE_COLORS: Record<Tone, string> = {
    neutral: 'rgba(255, 255, 255, 0.5)',
    amber: 'rgba(196, 170, 95, 0.62)',
    cyan: 'rgba(127, 184, 196, 0.62)',
    peach: 'rgba(201, 160, 122, 0.62)',
    lavender: 'rgba(168, 155, 196, 0.62)',
    mint: 'rgba(125, 184, 160, 0.62)',
    steel: 'rgba(106, 138, 168, 0.62)',
    danger: 'rgba(192, 96, 96, 0.62)',
    rose: 'rgba(192, 96, 112, 0.62)',
    indigo: 'rgba(74, 96, 160, 0.62)',
    sage: 'rgba(138, 168, 138, 0.62)',
    copper: 'rgba(184, 136, 104, 0.62)',
};

type ModulationHalo = {
    /** Fraction of full sweep (-1 to +1) representing modulation depth */
    amount: number;
    /** CSS color string for this modulation source */
    color: string;
};

type RotaryKnobProps = {
    value: number;
    onChange: (val: number) => void;
    min?: number;
    max?: number;
    step?: number;
    fineStep?: number;
    defaultValue?: number;
    bipolar?: boolean;
    scale?: 'linear' | 'log';
    size?: 'sm' | 'md' | 'lg' | 'xl';
    className?: string;
    /** Label rendered below the knob. When set, the component expands its min-width to prevent label overlap. */
    label?: string;
    paramId?: string;
    targetType?: 'trackGain' | 'trackPan' | 'deviceParam' | 'fermenterGlobalParam';
    trackId?: string;
    deviceId?: string;
    /** Color tone for the value arc */
    tone?: Tone;
    /**
     * R-C1: Active modulation sources displayed as colored conic-gradient halo arcs.
     * Each entry represents one modulator connected to this parameter.
     */
    modulations?: ModulationHalo[];
};

const SIZES = { sm: 24, md: 32, lg: 40, xl: 72 } as const;

/**
 * RotaryKnob
 * Skeuomorphic metallic dome with conic value arc.
 * Vertical drag sets value. Shift for fine control. Double-click resets.
 *
 * Performance: dragging state is tracked via refs, not React state,
 * so pointer-move never triggers re-renders on its own — only `onChange` does.
 */
export const RotaryKnob = ({
    value,
    onChange,
    min = 0,
    max = 100,
    step: stepProp,
    fineStep: fineStepProp,
    defaultValue = 50,
    bipolar = false,
    size = 'md',
    className,
    label,
    paramId,
    targetType = 'fermenterGlobalParam', // Default to fermenterGlobalParam for now
    trackId,
    deviceId,
    tone = 'cyan',
    modulations,
    scale = 'linear',
}: RotaryKnobProps): ReactElement => {
    const midiLearnState = useStore<MidiLearnState>(midiLearnStore, defaultMidiLearnState);
    const isLearningThis = Boolean(
        midiLearnState.isLearning &&
        midiLearnState.learningTarget &&
        midiLearnState.learningTarget.paramId === paramId &&
        paramId !== undefined
    );
    const isMapped = Boolean(midiLearnState.mappings.some((message) => message.paramId === paramId));
    // Derive sensible defaults from range when not explicitly provided
    const step = stepProp ?? Math.max(0.001, (max - min) / 200);
    const fineStep = fineStepProp ?? step / 10;
    const draggingRef = useRef(false);
    const startY = useRef(0);
    const startValue = useRef(value);
    const rootRef = useRef<HTMLDivElement>(null);
    const px = SIZES[size];

    const clamp = (value1: number): number => {
        let clamped = Math.max(min, Math.min(max, value1));
        if (bipolar && Math.abs(clamped - defaultValue) < (max - min) * 0.01) {
            clamped = defaultValue;
        }
        return clamped;
    };

    const handlePointerDown = (event: PointerEvent<HTMLDivElement>) => {
        if (event.button !== 0) {
            return;
        }
        if (event.altKey) {
            onChange(defaultValue);
            return;
        }
        if (typeof event.currentTarget.setPointerCapture === 'function') {
            event.currentTarget.setPointerCapture(event.pointerId);
        }
        draggingRef.current = true;
        startY.current = event.clientY;
        startValue.current = value;
        rootRef.current?.setAttribute('data-dragging', '');
    };

    const normalized =
        scale === 'log' && min > 0
            ? Math.max(0, Math.min(1, (Math.log(value) - Math.log(min)) / (Math.log(max) - Math.log(min))))
            : Math.max(0, Math.min(1, (value - min) / (max - min)));

    const handlePointerMove = (event: PointerEvent<HTMLDivElement>) => {
        if (!draggingRef.current) {
            return;
        }
        const deltaY = startY.current - event.clientY;
        const sweepPx = 150;

        let raw: number;
        if (scale === 'log' && min > 0) {
            const startNorm = (Math.log(startValue.current) - Math.log(min)) / (Math.log(max) - Math.log(min));
            let sensitivityNorm = 1 / sweepPx;
            if (event.shiftKey) {
                sensitivityNorm *= 0.1;
            }
            const newNorm = Math.max(0, Math.min(1, startNorm + deltaY * sensitivityNorm));
            raw = min * Math.exp(newNorm * (Math.log(max) - Math.log(min)));
        } else {
            let sensitivity = (max - min) / sweepPx;
            if (event.shiftKey) {
                sensitivity *= 0.1;
            }
            raw = startValue.current + deltaY * sensitivity;
        }

        const currentStep = event.shiftKey ? fineStep : step;
        const quantized = Math.round(raw / currentStep) * currentStep;
        onChange(clamp(quantized));
    };

    const handlePointerUp = (event: PointerEvent<HTMLDivElement>) => {
        draggingRef.current = false;
        if (typeof event.currentTarget.releasePointerCapture === 'function') {
            event.currentTarget.releasePointerCapture(event.pointerId);
        }
        rootRef.current?.removeAttribute('data-dragging');
    };

    const handleDoubleClick = () => {
        onChange(defaultValue);
    };

    const handleContextMenu = (event: MouseEvent<HTMLDivElement>) => {
        if (paramId && targetType) {
            event.preventDefault();
            startMidiLearn({
                targetType,
                paramId,
                trackId: trackId ?? 'global',
                deviceId,
            });
        }
    };

    const rotation = -135 + normalized * 270;

    // Conic arc gradient for the value ring
    const arcAngleDeg = normalized * 270;
    const arcColor = TONE_COLORS[tone];
    const arcBg = bipolar
        ? buildBipolarArc(normalized, arcColor)
        : `conic-gradient(from 225deg, ${arcColor} 0deg, ${arcColor} ${arcAngleDeg}deg, transparent ${arcAngleDeg}deg, transparent 270deg, transparent 270deg)`;

    return (
        <div
            ref={rootRef}
            className={cn(
                'group/knob relative flex flex-col items-center select-none touch-none cursor-ns-resize',
                label && 'min-w-fit',
                className
            )}
            onPointerDown={handlePointerDown}
            onPointerMove={handlePointerMove}
            onPointerUp={handlePointerUp}
            onDoubleClick={handleDoubleClick}
            onContextMenu={handleContextMenu}
        >
            {isLearningThis ? (
                <div className="absolute inset-[-4px] rounded-full border border-dashed border-[var(--color-accent-lavender)] animate-pulse pointer-events-none z-10" />
            ) : null}
            {isMapped && !isLearningThis ? (
                <div className="absolute top-0 right-0 size-2 rounded-full bg-[var(--color-accent-lavender)]/80 pointer-events-none z-10" />
            ) : null}
            {/* Outer bezel (well) */}
            <div
                className={cn(
                    'relative rounded-full bg-bg-panelInset flex items-center justify-center p-[2px] channel-inset'
                )}
                style={{ width: px, height: px }}
            >
                {/* Value arc ring */}
                <div
                    className="absolute inset-0 rounded-full pointer-events-none"
                    style={{
                        background: arcBg,
                        mask: 'radial-gradient(circle, transparent 55%, black 57%)',
                        WebkitMask: 'radial-gradient(circle, transparent 55%, black 57%)',
                    }}
                />

                {/* R-C1: Modulation halo arcs — one layer per connected modulator */}
                {modulations?.map((mod, idx) => {
                    const amountDeg = mod.amount * 270;
                    let haloBg: string;
                    if (amountDeg >= 0) {
                        const lo = arcAngleDeg;
                        const hi = Math.min(lo + amountDeg, 270);
                        haloBg = `conic-gradient(from 225deg, transparent 0deg, transparent ${lo}deg, ${mod.color} ${lo}deg, ${mod.color} ${hi}deg, transparent ${hi}deg)`;
                    } else {
                        const hi = arcAngleDeg;
                        const lo = Math.max(0, hi + amountDeg);
                        haloBg = `conic-gradient(from 225deg, transparent 0deg, transparent ${lo}deg, ${mod.color} ${lo}deg, ${mod.color} ${hi}deg, transparent ${hi}deg)`;
                    }
                    return (
                        <div
                            key={idx}
                            className="absolute inset-0 rounded-full pointer-events-none"
                            style={{
                                background: haloBg,
                                mask: 'radial-gradient(circle, transparent 55%, black 57%)',
                                WebkitMask: 'radial-gradient(circle, transparent 55%, black 57%)',
                                opacity: 0.8,
                            }}
                        />
                    );
                })}

                {/* Metallic dome cap — no CSS transition on transform for instant response */}
                <div
                    className={cn(
                        'relative h-full w-full rounded-full border border-border-soft transition-[filter,box-shadow] group-hover/knob:brightness-[1.03]'
                    )}
                    style={{
                        background:
                            'radial-gradient(ellipse 60% 40% at 45% 32%, rgba(255,255,255,0.18) 0%, transparent 65%), radial-gradient(circle at 50% 40%, #474747 0%, #323232 36%, #1e1e1e 78%, #1a1a1a 100%)',
                        boxShadow:
                            'inset 0 1px 0 rgba(255,255,255,0.09), inset 0 -1px 0 rgba(0,0,0,0.28), 0 1px 3px rgba(0,0,0,0.6)',
                        transform: `rotate(${rotation}deg)`,
                    }}
                >
                    {/* Position indicator line */}
                    <div
                        className="absolute left-1/2 -translate-x-1/2 rounded-full"
                        style={{
                            top: '12%',
                            width: px >= 72 ? 3 : 2,
                            height: px >= 72 ? '25%' : '28%',
                            background: 'linear-gradient(180deg, #ccc 0%, #888 100%)',
                            boxShadow: '0 0 2px rgba(255,255,255,0.15)',
                        }}
                    />
                </div>
            </div>
            {label ? (
                <span className="mt-0.5 whitespace-nowrap text-[7px] leading-none tracking-[0.12em] text-text-tertiary uppercase">
                    {label}
                </span>
            ) : null}
        </div>
    );
};

/** Build a bipolar conic arc that fills outward from center (50% = 135deg from start) */
function buildBipolarArc(normalized: number, color: string): string {
    const centerDeg = 135; // 50% of 270° sweep
    const valueDeg = normalized * 270;
    if (valueDeg >= centerDeg) {
        // Fill from center to value (clockwise)
        return `conic-gradient(from 225deg, transparent 0deg, transparent ${centerDeg}deg, ${color} ${centerDeg}deg, ${color} ${valueDeg}deg, transparent ${valueDeg}deg)`;
    }
    // Fill from value to center (counter-clockwise visual)
    return `conic-gradient(from 225deg, transparent 0deg, transparent ${valueDeg}deg, ${color} ${valueDeg}deg, ${color} ${centerDeg}deg, transparent ${centerDeg}deg)`;
}

import { type ReactElement, type PointerEvent, useRef, useState } from 'react';

import { cn } from '#/utils/Styles/cn';

type ValueFieldProps = {
    value: number;
    onChange: (val: number) => void;
    min?: number;
    max?: number;
    step?: number;
    fineStep?: number;
    unit?: string;
    label?: string;
    onReset?: () => void;
    className?: string;
};

/**
 * ValueField / ScrubField
 * Drag to scrub vertically/horizontally, double-click to reset,
 * Shift-drag for fine tuning.
 */
export const ValueField = ({
    value,
    onChange,
    min = -100,
    max = 100,
    step = 1,
    fineStep = 0.1,
    unit = '',
    label,
    onReset,
    className,
}: ValueFieldProps): ReactElement => {
    const [isDragging, setIsDragging] = useState(false);
    const draggingRef = useRef(false);
    const startY = useRef(0);
    const startValue = useRef(value);

    const handlePointerDown = (event: PointerEvent<HTMLDivElement>) => {
        if (event.button !== 0) {
            return;
        } // Only left click
        if (typeof event.currentTarget.setPointerCapture === 'function') {
            event.currentTarget.setPointerCapture(event.pointerId);
        }
        draggingRef.current = true;
        setIsDragging(true);
        startY.current = event.clientY;
        startValue.current = value;
    };

    const handlePointerMove = (event: PointerEvent<HTMLDivElement>) => {
        if (!draggingRef.current) {
            return;
        }

        const deltaY = startY.current - event.clientY;
        const currentStep = event.shiftKey ? fineStep : step;

        // Scalar sensitivity
        const sensitivity = event.shiftKey ? 0.05 : 0.5;
        let newValue = startValue.current + deltaY * sensitivity * currentStep;

        // Clamp
        if (min !== undefined) {
            newValue = Math.max(min, newValue);
        }
        if (max !== undefined) {
            newValue = Math.min(max, newValue);
        }

        // Snap to nearest step
        newValue = Math.round(newValue / currentStep) * currentStep;

        onChange(newValue);
    };

    const handlePointerUp = (event: PointerEvent<HTMLDivElement>) => {
        draggingRef.current = false;
        setIsDragging(false);
        if (typeof event.currentTarget.releasePointerCapture === 'function') {
            event.currentTarget.releasePointerCapture(event.pointerId);
        }
    };

    const handleDoubleClick = () => {
        if (onReset) {
            onReset();
        }
    };

    return (
        <div className={cn('flex flex-col items-center gap-0.5 group', className)}>
            {label ? (
                <span className="mb-0.5 text-[9px] font-semibold uppercase tracking-[0.16em] text-text-disabled">
                    {label}
                </span>
            ) : null}
            <div
                onPointerDown={handlePointerDown}
                onPointerMove={handlePointerMove}
                onPointerUp={handlePointerUp}
                onDoubleClick={handleDoubleClick}
                className={cn(
                    'daw-inset-surface flex cursor-ns-resize items-center justify-center rounded-micro px-1.5 py-0.5 font-mono tabular-nums select-none',
                    'transition-[color,box-shadow,border-color,filter] duration-fast',
                    isDragging
                        ? 'text-accent-cyan ring-1 ring-border-focus'
                        : 'text-text-primary hover:text-accent-cyan hover:border-border-soft',
                    'text-[10px]'
                )}
            >
                {Math.round(value * 100) / 100}
                {unit}
            </div>
        </div>
    );
};

import { render, screen, fireEvent } from '@testing-library/react';
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';

import { Fader } from '../Fader';

describe('Fader', () => {
    let getBoundingClientRectSpy: ReturnType<typeof vi.spyOn>;

    beforeEach(() => {
        getBoundingClientRectSpy = vi.spyOn(Element.prototype, 'getBoundingClientRect').mockReturnValue({
            x: 0,
            y: 0,
            width: 40,
            height: 100,
            top: 0,
            left: 0,
            right: 40,
            bottom: 100,
            toJSON: (): void => {},
        } as DOMRect);
    });

    afterEach(() => {
        getBoundingClientRectSpy.mockRestore();
    });

    it('should reset to default on double click', () => {
        const onChange = vi.fn();
        const { container } = render(<Fader value={-10} onChange={onChange} defaultValue={0} min={-70} max={6} />);
        const root = container.firstChild as HTMLElement;
        fireEvent.doubleClick(root);
        expect(onChange).toHaveBeenCalledWith(0);
    });

    it('should render dB scale when showScale is true', () => {
        render(<Fader value={0} onChange={vi.fn()} showScale />);
        expect(screen.getByText('+6')).toBeInTheDocument();
        expect(screen.getAllByText('0').length).toBeGreaterThan(0);
    });

    it('should jump to value when pointer down hits track outside cap', () => {
        const onChange = vi.fn();
        const { container } = render(<Fader value={-70} onChange={onChange} min={-70} max={6} height={100} />);
        const root = container.firstChild as HTMLElement;
        fireEvent.pointerDown(root, {
            button: 0,
            pointerId: 1,
            clientY: 50,
            clientX: 20,
            bubbles: true,
        });
        expect(onChange).toHaveBeenCalled();
    });

    it('should ignore non-left pointer down', () => {
        const onChange = vi.fn();
        const { container } = render(<Fader value={0} onChange={onChange} min={-70} max={6} />);
        const root = container.firstChild as HTMLElement;
        fireEvent.pointerDown(root, { button: 2, pointerId: 1, clientY: 0 });
        fireEvent.pointerMove(root, { pointerId: 1, clientY: 10 });
        expect(onChange).not.toHaveBeenCalled();
    });

    it('should drag from cap and apply shift fine mode', () => {
        const onChange = vi.fn();
        const { container } = render(<Fader value={0} onChange={onChange} min={-70} max={6} fineStep={0.1} />);
        const root = container.firstChild as HTMLElement;
        const cap = root.querySelector('[data-role="fader-cap"]') as HTMLElement;
        fireEvent.pointerDown(cap, { button: 0, pointerId: 2, clientY: 100, clientX: 0 });
        fireEvent.pointerMove(root, { pointerId: 2, clientY: 90, shiftKey: true });
        fireEvent.pointerUp(root, { pointerId: 2 });
        expect(onChange).toHaveBeenCalled();
    });

    it('should snap toward default when bipolar near center', () => {
        const onChange = vi.fn();
        const { container } = render(
            <Fader value={0.1} onChange={onChange} bipolar defaultValue={0} min={-10} max={10} step={0.5} />
        );
        const root = container.firstChild as HTMLElement;
        const cap = root.querySelector('[data-role="fader-cap"]') as HTMLElement;
        fireEvent.pointerDown(cap, { button: 0, pointerId: 3, clientY: 50 });
        fireEvent.pointerMove(root, { pointerId: 3, clientY: 50.1 });
        fireEvent.pointerUp(root, { pointerId: 3 });
        expect(onChange).toHaveBeenCalled();
    });

    it('should use tone classes on cap groove when dragging', () => {
        const onChange = vi.fn();
        const { container } = render(<Fader value={0} onChange={onChange} min={-70} max={6} tone="amber" />);
        const root = container.firstChild as HTMLElement;
        const cap = root.querySelector('[data-role="fader-cap"]') as HTMLElement;
        fireEvent.pointerDown(cap, { button: 0, pointerId: 4, clientY: 40 });
        const grooves = cap.querySelectorAll('div');
        expect(grooves.length).toBeGreaterThan(0);
        fireEvent.pointerUp(root, { pointerId: 4 });
        expect(onChange).not.toHaveBeenCalled();
    });

    it('should apply every tone variant while dragging', () => {
        const tones = [
            'neutral',
            'amber',
            'cyan',
            'peach',
            'lavender',
            'mint',
            'steel',
            'danger',
            'rose',
            'indigo',
            'sage',
            'copper',
        ] as const;
        for (const tone of tones) {
            const onChange = vi.fn();
            const { container, unmount } = render(
                <Fader value={0} onChange={onChange} min={-70} max={6} tone={tone} />
            );
            const root = container.firstChild as HTMLElement;
            const cap = root.querySelector('[data-role="fader-cap"]') as HTMLElement;
            fireEvent.pointerDown(cap, { button: 0, pointerId: 10, clientY: 40 });
            fireEvent.pointerUp(root, { pointerId: 10 });
            unmount();
        }
    });
});

/**
 * ADSR Envelope — Canvas2D amplitude envelope visualization.
 *
 * Draws the attack/decay/sustain/release shape with interactive
 * breakpoints and a filled gradient area. Updates in real-time
 * as knob values change.
 */
import { type ReactElement, useRef, useEffect } from 'react';

import { resolveToken } from '#/utils/UI/resolveToken';

type ADSREnvelopeProps = {
    attack: number; // seconds (0–2)
    decay: number; // seconds (0–2)
    sustain: number; // level (0–1)
    release: number; // seconds (0–3)
    /** Accent color token or hex */
    color?: string;
    width?: number;
    height?: number;
    onParamChange?: (paramId: string, value: number) => void;
};

type BreakpointId = 'attack' | 'decay' | 'sustain' | 'release';

export const ADSREnvelope = ({
    attack,
    decay,
    sustain,
    release,
    color,
    width = 200,
    height = 80,
    onParamChange,
}: ADSREnvelopeProps): ReactElement => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const isDragging = useRef(false);
    const activeBreakpoint = useRef<BreakpointId | null>(null);
    const isInteractive = !!onParamChange;

    // Store computed breakpoint positions for hit testing
    const breakpointsRef = useRef<{ id: BreakpointId; x: number; y: number }[]>([]);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) {
            return;
        }
        const ctx = canvas.getContext('2d');
        if (!ctx) {
            return;
        }

        const dpr = window.devicePixelRatio || 1;
        canvas.width = width * dpr;
        canvas.height = height * dpr;
        ctx.scale(dpr, dpr);

        const pad = 6;
        const plotW = width - pad * 2;
        const plotH = height - pad * 2;

        ctx.clearRect(0, 0, width, height);

        // Background
        ctx.fillStyle = resolveToken('--color-bg-tray', '#0a0a0a');
        ctx.beginPath();
        ctx.roundRect(0, 0, width, height, 4);
        ctx.fill();

        // Normalize time segments to fit the plot width
        const totalTime = Math.max(0.01, attack + decay + 0.4 + release); // 0.4 = sustain hold
        const sustainHold = 0.4;
        const aX = pad + (attack / totalTime) * plotW;
        const dX = aX + (decay / totalTime) * plotW;
        const sX = dX + (sustainHold / totalTime) * plotW;
        const rX = sX + (release / totalTime) * plotW;

        const topY = pad + 2;
        const bottomY = pad + plotH;
        const sustainY = bottomY - sustain * (plotH - 4);

        const rawColor = color ?? resolveToken('--color-accent-teal', '#4CB8B8');
        // Resolve CSS variable references (e.g. 'var(--color-accent-mint)') to hex for canvas
        const accent = rawColor.startsWith('var(') ? resolveToken(rawColor.slice(4, -1), '#4CB8B8') : rawColor;

        // Store breakpoint positions for hit testing
        breakpointsRef.current = [
            { id: 'attack', x: aX, y: topY },
            { id: 'decay', x: dX, y: sustainY },
            { id: 'sustain', x: sX, y: sustainY },
            { id: 'release', x: rX, y: bottomY },
        ];

        // Grid lines
        ctx.strokeStyle = 'rgba(255,255,255,0.05)';
        ctx.lineWidth = 0.5;
        for (let index = 0; index <= 4; index++) {
            const y = pad + (plotH / 4) * index;
            ctx.beginPath();
            ctx.moveTo(pad, y);
            ctx.lineTo(width - pad, y);
            ctx.stroke();
        }

        // Envelope fill
        ctx.beginPath();
        ctx.moveTo(pad, bottomY);
        ctx.lineTo(aX, topY); // Attack
        ctx.lineTo(dX, sustainY); // Decay
        ctx.lineTo(sX, sustainY); // Sustain hold
        ctx.lineTo(rX, bottomY); // Release
        ctx.lineTo(pad, bottomY);
        ctx.closePath();

        const gradient = ctx.createLinearGradient(0, topY, 0, bottomY);
        gradient.addColorStop(0, `${accent}25`);
        gradient.addColorStop(1, `${accent}05`);
        ctx.fillStyle = gradient;
        ctx.fill();

        // Envelope line
        ctx.beginPath();
        ctx.moveTo(pad, bottomY);
        ctx.lineTo(aX, topY);
        ctx.lineTo(dX, sustainY);
        ctx.lineTo(sX, sustainY);
        ctx.lineTo(rX, bottomY);
        ctx.strokeStyle = accent;
        ctx.lineWidth = 2;
        ctx.lineJoin = 'round';
        ctx.stroke();

        // Breakpoint dots
        const dots = [
            { x: pad, y: bottomY },
            { x: aX, y: topY },
            { x: dX, y: sustainY },
            { x: sX, y: sustainY },
            { x: rX, y: bottomY },
        ];
        const dotRadius = isInteractive ? 6 : 3;
        const innerRadius = isInteractive ? 3 : 1.5;
        for (const dot of dots) {
            ctx.beginPath();
            ctx.arc(dot.x, dot.y, dotRadius, 0, Math.PI * 2);
            ctx.fillStyle = accent;
            ctx.fill();
            if (isInteractive) {
                ctx.strokeStyle = '#ffffff';
                ctx.lineWidth = 1;
                ctx.stroke();
            }
            ctx.beginPath();
            ctx.arc(dot.x, dot.y, innerRadius, 0, Math.PI * 2);
            ctx.fillStyle = '#000';
            ctx.fill();
        }

        // Phase labels
        ctx.fillStyle = resolveToken('--color-text-disabled', '#3a3a3a');
        ctx.font = '7px monospace';
        ctx.textAlign = 'center';

        const labelY = height - 1;
        ctx.fillText('A', (pad + aX) / 2, labelY);
        ctx.fillText('D', (aX + dX) / 2, labelY);
        ctx.fillText('S', (dX + sX) / 2, labelY);
        ctx.fillText('R', (sX + rX) / 2, labelY);

        // Sustain level label
        ctx.fillStyle = `${accent}80`;
        ctx.font = '8px monospace';
        ctx.textAlign = 'right';
        ctx.fillText(`${(sustain * 100).toFixed(0)}%`, width - pad, sustainY - 4);

        // "drag to adjust" hint
        if (isInteractive && !isDragging.current) {
            ctx.fillStyle = 'rgba(255,255,255,0.25)';
            ctx.font = '7px monospace';
            ctx.textAlign = 'center';
            ctx.fillText('drag to adjust', width / 2, pad + 10);
        }
    }, [attack, decay, sustain, release, color, width, height, isInteractive]);

    const handlePointerDown = (event: React.PointerEvent<HTMLCanvasElement>) => {
        if (!onParamChange) {
            return;
        }
        const canvas = canvasRef.current;
        if (!canvas) {
            return;
        }
        const rect = canvas.getBoundingClientRect();
        const mx = event.clientX - rect.left;
        const my = event.clientY - rect.top;

        // Find closest breakpoint within hit radius
        const hitRadius = 16;
        let closest: BreakpointId | null = null;
        let closestDist = Infinity;
        for (const bp of breakpointsRef.current) {
            const dx = mx - bp.x;
            const dy = my - bp.y;
            const dist = Math.sqrt(dx * dx + dy * dy);
            if (dist < hitRadius && dist < closestDist) {
                closestDist = dist;
                closest = bp.id;
            }
        }

        if (!closest) {
            return;
        }

        isDragging.current = true;
        activeBreakpoint.current = closest;
        canvas.setPointerCapture(event.pointerId);
        canvas.style.cursor = 'grabbing';
    };

    const handlePointerMove = (event: React.PointerEvent<HTMLCanvasElement>) => {
        if (!onParamChange || !isDragging.current || !activeBreakpoint.current) {
            return;
        }
        const canvas = canvasRef.current;
        if (!canvas) {
            return;
        }
        const rect = canvas.getBoundingClientRect();
        const pad = 6;
        const plotW = width - pad * 2;
        const plotH = height - pad * 2;
        const mx = event.clientX - rect.left;
        const my = event.clientY - rect.top;

        const bp = activeBreakpoint.current;

        if (bp === 'sustain') {
            // Vertical drag only -> sustain level (0-1)
            const bottomY = pad + plotH;
            const topY = pad + 2;
            const ratio = 1 - (my - topY) / (bottomY - topY);
            const clamped = Math.max(0, Math.min(1, ratio));
            onParamChange('sustain', clamped);
        } else {
            // Horizontal drag -> time parameter
            const xRatio = Math.max(0, Math.min(1, (mx - pad) / plotW));
            const totalTime = Math.max(0.01, attack + decay + 0.4 + release);
            const mappedTime = xRatio * totalTime;

            if (bp === 'attack') {
                const val = Math.max(0.001, Math.min(2, mappedTime));
                onParamChange('attack', val);
            } else if (bp === 'decay') {
                const val = Math.max(0.001, Math.min(2, mappedTime - attack));
                onParamChange('decay', Math.max(0.001, val));
            } else if (bp === 'release') {
                const sustainEnd = attack + decay + 0.4;
                const val = Math.max(0.001, Math.min(5, mappedTime - sustainEnd));
                onParamChange('release', Math.max(0.001, val));
            }
        }
    };

    const handlePointerUp = (event: React.PointerEvent<HTMLCanvasElement>) => {
        if (!onParamChange) {
            return;
        }
        const canvas = canvasRef.current;
        if (!canvas) {
            return;
        }
        isDragging.current = false;
        activeBreakpoint.current = null;
        canvas.releasePointerCapture(event.pointerId);
        canvas.style.cursor = 'grab';
    };

    return (
        <canvas
            ref={canvasRef}
            style={{ width, height, cursor: isInteractive ? 'grab' : undefined }}
            className="rounded border border-border/30"
            aria-label="ADSR envelope shape"
            role="img"
            onPointerDown={isInteractive ? handlePointerDown : undefined}
            onPointerMove={isInteractive ? handlePointerMove : undefined}
            onPointerUp={isInteractive ? handlePointerUp : undefined}
        />
    );
};

/**
 * Compressor Transfer Curve — Canvas2D input/output graph.
 *
 * Draws the static transfer characteristic of a compressor:
 * - Unity line (1:1) in subtle gray
 * - The actual compression curve with threshold, ratio, and knee
 * - Threshold and knee indicators
 * Uses design tokens for consistent DAW aesthetic.
 */
import { type ReactElement, useRef, useEffect } from 'react';

import { resolveToken } from '#/utils/UI/resolveToken';

type CompressorCurveProps = {
    threshold: number; // dB, e.g. -20
    ratio: number; // e.g. 4 (meaning 4:1)
    knee: number; // dB, e.g. 6
    makeup: number; // dB, e.g. 0
    width?: number;
    height?: number;
    onParamChange?: (paramId: string, value: number) => void;
};

const DB_MIN = -60;
const DB_MAX = 0;

/** Compute output dB given input dB, with soft knee */
const computeOutput = (inputDb: number, threshold: number, ratio: number, kneeWidth: number): number => {
    const halfKnee = kneeWidth / 2;
    if (inputDb <= threshold - halfKnee) {
        // Below knee — unity
        return inputDb;
    } else if (inputDb >= threshold + halfKnee) {
        // Above knee — full compression
        return threshold + (inputDb - threshold) / ratio;
    } else {
        // In the knee — quadratic interpolation
        const xPos = inputDb - threshold + halfKnee;
        return inputDb + ((1 / ratio - 1) * xPos * xPos) / (2 * kneeWidth);
    }
};

export const CompressorCurve = ({
    threshold,
    ratio,
    knee,
    makeup,
    width = 120,
    height = 120,
    onParamChange,
}: CompressorCurveProps): ReactElement => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const isDragging = useRef(false);
    const isInteractive = !!onParamChange;

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) {
            return;
        }
        const ctx = canvas.getContext('2d');
        if (!ctx) {
            return;
        }

        const dpr = window.devicePixelRatio || 1;
        canvas.width = width * dpr;
        canvas.height = height * dpr;
        ctx.scale(dpr, dpr);

        const pad = 4;
        const plotW = width - pad * 2;
        const plotH = height - pad * 2;
        const dbToX = (db: number): number => pad + ((db - DB_MIN) / (DB_MAX - DB_MIN)) * plotW;
        const dbToY = (db: number): number => pad + plotH - ((db - DB_MIN) / (DB_MAX - DB_MIN)) * plotH;

        ctx.clearRect(0, 0, width, height);

        // Background — deep gradient
        const bgGrad = ctx.createLinearGradient(0, 0, 0, height);
        bgGrad.addColorStop(0, '#0e0e12');
        bgGrad.addColorStop(1, '#060608');
        ctx.fillStyle = bgGrad;
        ctx.beginPath();
        ctx.roundRect(0, 0, width, height, 4);
        ctx.fill();

        // Grid — subtle dotted
        ctx.strokeStyle = 'rgba(255,255,255,0.04)';
        ctx.lineWidth = 0.5;
        ctx.setLineDash([1, 4]);
        for (const db of [-48, -36, -24, -12, 0]) {
            // Horizontal
            ctx.beginPath();
            ctx.moveTo(pad, dbToY(db));
            ctx.lineTo(width - pad, dbToY(db));
            ctx.stroke();
            // Vertical
            ctx.beginPath();
            ctx.moveTo(dbToX(db), pad);
            ctx.lineTo(dbToX(db), height - pad);
            ctx.stroke();
        }
        ctx.setLineDash([]);

        // Unity line (1:1)
        ctx.beginPath();
        ctx.moveTo(dbToX(DB_MIN), dbToY(DB_MIN));
        ctx.lineTo(dbToX(DB_MAX), dbToY(DB_MAX));
        ctx.strokeStyle = 'rgba(255,255,255,0.12)';
        ctx.lineWidth = 1;
        ctx.setLineDash([3, 3]);
        ctx.stroke();
        ctx.setLineDash([]);

        // Compression curve
        const accentPeach = resolveToken('--color-accent-peach', '#f0944c');
        const curvePoints: [number, number][] = [];
        const steps = plotW;
        for (let index = 0; index <= steps; index++) {
            const inputDb = DB_MIN + (index / steps) * (DB_MAX - DB_MIN);
            const outputDb = Math.min(DB_MAX, computeOutput(inputDb, threshold, ratio, knee) + makeup);
            const xPos = dbToX(inputDb);
            const yPos = dbToY(Math.max(DB_MIN, outputDb));
            curvePoints.push([xPos, yPos]);
        }

        // Fill below curve — gradient
        ctx.beginPath();
        for (let index = 0; index < curvePoints.length; index++) {
            const [xPos, yPos] = curvePoints[index]!;
            if (index === 0) {
                ctx.moveTo(xPos, yPos);
            } else {
                ctx.lineTo(xPos, yPos);
            }
        }
        ctx.lineTo(dbToX(DB_MAX), dbToY(DB_MIN));
        ctx.lineTo(dbToX(DB_MIN), dbToY(DB_MIN));
        ctx.closePath();
        const curveFillGrad = ctx.createLinearGradient(0, pad, 0, pad + plotH);
        curveFillGrad.addColorStop(0, `${accentPeach}25`);
        curveFillGrad.addColorStop(1, `${accentPeach}05`);
        ctx.fillStyle = curveFillGrad;
        ctx.fill();

        // Glow pass
        ctx.beginPath();
        for (let index = 0; index < curvePoints.length; index++) {
            const [xPos, yPos] = curvePoints[index]!;
            if (index === 0) {
                ctx.moveTo(xPos, yPos);
            } else {
                ctx.lineTo(xPos, yPos);
            }
        }
        ctx.strokeStyle = `${accentPeach}28`;
        ctx.lineWidth = 5;
        ctx.stroke();

        // Sharp stroke
        ctx.beginPath();
        for (let index = 0; index < curvePoints.length; index++) {
            const [xPos, yPos] = curvePoints[index]!;
            if (index === 0) {
                ctx.moveTo(xPos, yPos);
            } else {
                ctx.lineTo(xPos, yPos);
            }
        }
        ctx.strokeStyle = accentPeach;
        ctx.lineWidth = 2;
        ctx.stroke();

        // Threshold marker
        const thX = dbToX(threshold);
        const thY = dbToY(computeOutput(threshold, threshold, ratio, knee) + makeup);
        ctx.beginPath();
        ctx.setLineDash([2, 2]);
        ctx.moveTo(thX, pad);
        ctx.lineTo(thX, height - pad);
        ctx.strokeStyle = `${accentPeach}60`;
        ctx.lineWidth = 0.75;
        ctx.stroke();
        ctx.setLineDash([]);

        // Threshold dot
        const dotRadius = isInteractive ? 5 : 3;
        ctx.beginPath();
        ctx.arc(thX, thY, dotRadius, 0, Math.PI * 2);
        ctx.fillStyle = accentPeach;
        ctx.fill();
        if (isInteractive) {
            ctx.strokeStyle = '#ffffff';
            ctx.lineWidth = 1;
            ctx.stroke();
        }

        // Labels — very dim
        ctx.fillStyle = '#383838';
        ctx.font = '7px monospace';
        ctx.textAlign = 'center';
        ctx.fillText('IN', width / 2, height - 1);
        ctx.save();
        ctx.translate(6, height / 2);
        ctx.rotate(-Math.PI / 2);
        ctx.fillText('OUT', 0, 0);
        ctx.restore();

        // Ratio text
        ctx.fillStyle = `${accentPeach}90`;
        ctx.font = '8px monospace';
        ctx.textAlign = 'right';
        ctx.fillText(`${ratio.toFixed(1)}:1`, width - pad, pad + 10);

        // "drag to adjust" hint
        if (isInteractive && !isDragging.current) {
            ctx.fillStyle = 'rgba(255,255,255,0.25)';
            ctx.font = '7px monospace';
            ctx.textAlign = 'center';
            ctx.fillText('drag to adjust', width / 2, pad + 10);
        }
    }, [threshold, ratio, knee, makeup, width, height, isInteractive]);

    const handlePointerDown = (event: React.PointerEvent<HTMLCanvasElement>) => {
        if (!onParamChange) {
            return;
        }
        const canvas = canvasRef.current;
        if (!canvas) {
            return;
        }
        isDragging.current = true;
        canvas.setPointerCapture(event.pointerId);
        canvas.style.cursor = 'grabbing';
    };

    const handlePointerMove = (event: React.PointerEvent<HTMLCanvasElement>) => {
        if (!onParamChange || !isDragging.current) {
            return;
        }
        const canvas = canvasRef.current;
        if (!canvas) {
            return;
        }
        const rect = canvas.getBoundingClientRect();
        const pad = 4;
        const plotH = height - pad * 2;
        // Y position to dB: top = 0 dB, bottom = -60 dB
        const yRatio = (event.clientY - rect.top - pad) / plotH;
        const db = DB_MAX - yRatio * (DB_MAX - DB_MIN);
        const clamped = Math.max(-60, Math.min(0, db));
        onParamChange('comp-threshold', clamped);
    };

    const handlePointerUp = (event: React.PointerEvent<HTMLCanvasElement>) => {
        if (!onParamChange) {
            return;
        }
        const canvas = canvasRef.current;
        if (!canvas) {
            return;
        }
        isDragging.current = false;
        canvas.releasePointerCapture(event.pointerId);
        canvas.style.cursor = 'grab';
    };

    return (
        <canvas
            ref={canvasRef}
            style={{ width, height, cursor: isInteractive ? 'grab' : undefined }}
            className="rounded border border-border/30"
            aria-label="Compressor transfer curve"
            role="img"
            onPointerDown={isInteractive ? handlePointerDown : undefined}
            onPointerMove={isInteractive ? handlePointerMove : undefined}
            onPointerUp={isInteractive ? handlePointerUp : undefined}
        />
    );
};

/**
 * Delay Tap Visualization — Canvas2D tap pattern display.
 *
 * Shows the delay feedback pattern as descending echo taps.
 * Each tap is a vertical bar whose height represents amplitude,
 * spaced by the delay time and decaying by the feedback amount.
 * Uses cyan accent (routing/secondary) for consistency.
 */
import { type ReactElement, useRef, useEffect } from 'react';

import { resolveToken } from '#/utils/UI/resolveToken';

type DelayTapsProps = {
    time: number; // ms, delay time
    feedback: number; // 0–0.95, feedback amount
    mix: number; // 0–1, dry/wet
    width?: number;
    height?: number;
    onParamChange?: (paramId: string, value: number) => void;
};

type DragTarget = 'time' | 'feedback';

export const DelayTaps = ({
    time,
    feedback,
    mix,
    width = 200,
    height = 50,
    onParamChange,
}: DelayTapsProps): ReactElement => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const isDragging = useRef(false);
    const dragTarget = useRef<DragTarget | null>(null);
    const isInteractive = !!onParamChange;

    // Store positions for hit testing
    const firstTapXRef = useRef(0);
    const envelopeYRef = useRef(0);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) {
            return;
        }
        const ctx = canvas.getContext('2d');
        if (!ctx) {
            return;
        }

        const dpr = window.devicePixelRatio || 1;
        canvas.width = width * dpr;
        canvas.height = height * dpr;
        ctx.scale(dpr, dpr);

        ctx.clearRect(0, 0, width, height);

        // Background — deep gradient
        const bgGrad = ctx.createLinearGradient(0, 0, 0, height);
        bgGrad.addColorStop(0, '#0e0e12');
        bgGrad.addColorStop(1, '#060608');
        ctx.fillStyle = bgGrad;
        ctx.beginPath();
        ctx.roundRect(0, 0, width, height, 4);
        ctx.fill();

        const accentCyan = resolveToken('--color-accent-cyan', '#50d0e8');
        const pad = 6;
        const plotW = width - pad * 2;
        const plotH = height - pad * 2;

        // How many taps can we show?
        const maxTaps = Math.min(12, Math.max(2, Math.floor(2000 / time)));
        const totalDuration = time * maxTaps;
        const barWidth = Math.max(2, Math.min(8, (plotW / maxTaps) * 0.4));

        // Draw baseline — subtle dotted
        ctx.strokeStyle = 'rgba(255,255,255,0.04)';
        ctx.lineWidth = 0.5;
        ctx.setLineDash([1, 4]);
        ctx.beginPath();
        ctx.moveTo(pad, pad + plotH);
        ctx.lineTo(pad + plotW, pad + plotH);
        ctx.stroke();
        ctx.setLineDash([]);

        // Dry signal bar
        ctx.fillStyle = 'rgba(255,255,255,0.15)';
        const dryBarH = plotH * 0.9;
        ctx.fillRect(pad, pad + plotH - dryBarH, barWidth, dryBarH);

        // "D" label for dry
        ctx.fillStyle = '#383838';
        ctx.font = '6px monospace';
        ctx.textAlign = 'center';
        ctx.fillText('D', pad + barWidth / 2, pad + plotH - dryBarH - 2);

        // Store first tap position for hit testing
        const firstTapTime = time * 1;
        firstTapXRef.current = pad + (firstTapTime / totalDuration) * plotW;
        const firstTapAmplitude = mix * feedback ** 1;
        envelopeYRef.current = pad + plotH - firstTapAmplitude * plotH;

        // Delay taps
        for (let tap = 1; tap <= maxTaps; tap++) {
            const amplitude = mix * feedback ** tap;
            if (amplitude < 0.01) {
                break;
            }

            const tapTime = time * tap;
            const xPos = pad + (tapTime / totalDuration) * plotW;
            const barH = amplitude * plotH;

            // Gradient per tap: brighter at top
            const grad = ctx.createLinearGradient(0, pad + plotH - barH, 0, pad + plotH);
            grad.addColorStop(
                0,
                `${accentCyan}${Math.round(amplitude * 200)
                    .toString(16)
                    .padStart(2, '0')}`
            );
            grad.addColorStop(1, `${accentCyan}10`);
            ctx.fillStyle = grad;
            ctx.fillRect(xPos - barWidth / 2, pad + plotH - barH, barWidth, barH);

            // Top highlight
            ctx.fillStyle = `${accentCyan}${Math.round(amplitude * 180)
                .toString(16)
                .padStart(2, '0')}`;
            ctx.fillRect(xPos - barWidth / 2, pad + plotH - barH, barWidth, 1);
        }

        // Connecting decay envelope line — glow
        ctx.beginPath();
        ctx.moveTo(pad + barWidth, pad + plotH - mix * plotH);
        for (let tap = 1; tap <= maxTaps; tap++) {
            const amplitude = mix * feedback ** tap;
            if (amplitude < 0.01) {
                break;
            }
            const tapTime = time * tap;
            const xPos = pad + (tapTime / totalDuration) * plotW;
            const yPos = pad + plotH - amplitude * plotH;
            ctx.lineTo(xPos, yPos);
        }
        ctx.strokeStyle = `${accentCyan}20`;
        ctx.lineWidth = 4;
        ctx.stroke();

        // Connecting decay envelope line — sharp
        ctx.beginPath();
        ctx.moveTo(pad + barWidth, pad + plotH - mix * plotH);
        for (let tap = 1; tap <= maxTaps; tap++) {
            const amplitude = mix * feedback ** tap;
            if (amplitude < 0.01) {
                break;
            }
            const tapTime = time * tap;
            const xPos = pad + (tapTime / totalDuration) * plotW;
            const yPos = pad + plotH - amplitude * plotH;
            ctx.lineTo(xPos, yPos);
        }
        ctx.strokeStyle = `${accentCyan}50`;
        ctx.lineWidth = 1;
        ctx.setLineDash([2, 2]);
        ctx.stroke();
        ctx.setLineDash([]);

        // Time label — very dim
        ctx.fillStyle = '#383838';
        ctx.font = '7px monospace';
        ctx.textAlign = 'right';
        ctx.fillText(`${Math.round(time)}ms`, width - pad, height - 2);

        // "drag to adjust" hint
        if (isInteractive && !isDragging.current) {
            ctx.fillStyle = 'rgba(255,255,255,0.25)';
            ctx.font = '7px monospace';
            ctx.textAlign = 'center';
            ctx.fillText('drag to adjust', width / 2, pad + 8);
        }
    }, [time, feedback, mix, width, height, isInteractive]);

    const handlePointerDown = (event: React.PointerEvent<HTMLCanvasElement>) => {
        if (!onParamChange) {
            return;
        }
        const canvas = canvasRef.current;
        if (!canvas) {
            return;
        }
        const rect = canvas.getBoundingClientRect();
        const mx = event.clientX - rect.left;
        const my = event.clientY - rect.top;

        // Determine drag target: near first tap X = time, near envelope line = feedback
        const distToTap = Math.abs(mx - firstTapXRef.current);
        const distToEnvelope = Math.abs(my - envelopeYRef.current);

        // Prefer horizontal (time) if closer to the first tap, vertical (feedback) if closer to envelope
        if (distToTap < 20) {
            dragTarget.current = 'time';
        } else if (distToEnvelope < 20) {
            dragTarget.current = 'feedback';
        } else {
            // Default: pick whichever is closer
            dragTarget.current = distToTap < distToEnvelope ? 'time' : 'feedback';
        }

        isDragging.current = true;
        canvas.setPointerCapture(event.pointerId);
        canvas.style.cursor = 'grabbing';
    };

    const handlePointerMove = (event: React.PointerEvent<HTMLCanvasElement>) => {
        if (!onParamChange || !isDragging.current || !dragTarget.current) {
            return;
        }
        const canvas = canvasRef.current;
        if (!canvas) {
            return;
        }
        const rect = canvas.getBoundingClientRect();
        const pad = 6;
        const plotW = width - pad * 2;
        const plotH = height - pad * 2;

        if (dragTarget.current === 'time') {
            // Map horizontal position to delay time (1-2000ms)
            const mx = event.clientX - rect.left;
            const xRatio = Math.max(0, Math.min(1, (mx - pad) / plotW));
            const newTime = 1 + xRatio * (2000 - 1);
            onParamChange('delay-time', newTime);
        } else {
            // Map vertical position to feedback (0-0.95)
            const my = event.clientY - rect.top;
            const bottomY = pad + plotH;
            const topY = pad;
            const yRatio = 1 - (my - topY) / (bottomY - topY);
            const newFeedback = Math.max(0, Math.min(0.95, yRatio));
            onParamChange('delay-feedback', newFeedback);
        }
    };

    const handlePointerUp = (event: React.PointerEvent<HTMLCanvasElement>) => {
        if (!onParamChange) {
            return;
        }
        const canvas = canvasRef.current;
        if (!canvas) {
            return;
        }
        isDragging.current = false;
        dragTarget.current = null;
        canvas.releasePointerCapture(event.pointerId);
        canvas.style.cursor = 'grab';
    };

    return (
        <canvas
            ref={canvasRef}
            style={{ width, height, cursor: isInteractive ? 'grab' : undefined }}
            className="rounded border border-border/30"
            aria-label="Delay tap pattern"
            role="img"
            onPointerDown={isInteractive ? handlePointerDown : undefined}
            onPointerMove={isInteractive ? handlePointerMove : undefined}
            onPointerUp={isInteractive ? handlePointerUp : undefined}
        />
    );
};

/**
 * DistortionCurve — Canvas2D waveshaper transfer function visualization.
 *
 * Draws the input->output transfer curve for a waveshaper distortion,
 * showing how the drive parameter clips the signal. Higher drive = more
 * aggressive S-curve. Uses 45 degree unity line as reference.
 */
import { type ReactElement, useRef, useEffect } from 'react';

import { resolveToken } from '#/utils/UI/resolveToken';

type DistortionCurveProps = {
    drive: number; // 0–100
    tone: number; // 200–8000 Hz (for display label only)
    mix: number; // 0–1
    width?: number;
    height?: number;
    onParamChange?: (paramId: string, value: number) => void;
};

/** Attempt to match the waveshaper curve used in deviceNodeFactory */
const waveshape = (xPos: number, drive: number): number => {
    const kIndex = drive * 4; // amplify the effect
    if (kIndex === 0) {
        return xPos;
    }
    return Math.tanh(xPos * kIndex) / Math.tanh(kIndex);
};

export const DistortionCurve = ({
    drive,
    tone: _tone,
    mix,
    width = 200,
    height = 120,
    onParamChange,
}: DistortionCurveProps): ReactElement => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const isDragging = useRef(false);
    const lastY = useRef(0);
    const isInteractive = !!onParamChange;

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) {
            return;
        }
        const ctx = canvas.getContext('2d');
        if (!ctx) {
            return;
        }

        const dpr = window.devicePixelRatio || 1;
        canvas.width = width * dpr;
        canvas.height = height * dpr;
        ctx.scale(dpr, dpr);

        ctx.clearRect(0, 0, width, height);

        // Background — deep gradient
        const bgGrad = ctx.createLinearGradient(0, 0, 0, height);
        bgGrad.addColorStop(0, '#0e0e12');
        bgGrad.addColorStop(1, '#060608');
        ctx.fillStyle = bgGrad;
        ctx.beginPath();
        ctx.roundRect(0, 0, width, height, 4);
        ctx.fill();

        const pad = 8;
        const gw = width - pad * 2;
        const gh = height - pad * 2;

        // Grid: unity line (45°)
        ctx.strokeStyle = 'rgba(255,255,255,0.06)';
        ctx.lineWidth = 0.5;
        ctx.setLineDash([2, 3]);
        ctx.beginPath();
        ctx.moveTo(pad, pad + gh);
        ctx.lineTo(pad + gw, pad);
        ctx.stroke();
        ctx.setLineDash([]);

        // Grid: center cross — subtle dotted
        ctx.strokeStyle = 'rgba(255,255,255,0.04)';
        ctx.setLineDash([1, 4]);
        ctx.beginPath();
        ctx.moveTo(pad + gw / 2, pad);
        ctx.lineTo(pad + gw / 2, pad + gh);
        ctx.moveTo(pad, pad + gh / 2);
        ctx.lineTo(pad + gw, pad + gh / 2);
        ctx.stroke();
        ctx.setLineDash([]);

        // Compute transfer curve
        const accPeach = resolveToken('--color-accent-peach', '#f0944c');
        const normalizedDrive = drive / 100; // 0–1
        const points: [number, number][] = [];
        const steps = gw;

        for (let index = 0; index <= steps; index++) {
            const inputNorm = index / steps; // 0–1
            const input = inputNorm * 2 - 1; // -1 to +1
            const shaped = waveshape(input, normalizedDrive);
            // Blend with dry based on mix
            const blended = input * (1 - mix) + shaped * mix;
            const outputNorm = (blended + 1) / 2; // back to 0–1
            const xPos = pad + index;
            const yPos = pad + gh - outputNorm * gh;
            points.push([xPos, yPos]);
        }

        // Fill under curve — gradient
        ctx.beginPath();
        ctx.moveTo(pad, pad + gh);
        for (const [xPos, yPos] of points) {
            ctx.lineTo(xPos, yPos);
        }
        ctx.lineTo(pad + gw, pad + gh);
        ctx.closePath();
        const distFillGrad = ctx.createLinearGradient(0, pad, 0, pad + gh);
        distFillGrad.addColorStop(0, `${accPeach}22`);
        distFillGrad.addColorStop(1, `${accPeach}04`);
        ctx.fillStyle = distFillGrad;
        ctx.fill();

        // Glow pass
        ctx.beginPath();
        for (let index = 0; index < points.length; index++) {
            const [xPos, yPos] = points[index]!;
            if (index === 0) {
                ctx.moveTo(xPos, yPos);
            } else {
                ctx.lineTo(xPos, yPos);
            }
        }
        ctx.strokeStyle = `${accPeach}28`;
        ctx.lineWidth = 5;
        ctx.stroke();

        // Sharp stroke
        ctx.beginPath();
        for (let index = 0; index < points.length; index++) {
            const [xPos, yPos] = points[index]!;
            if (index === 0) {
                ctx.moveTo(xPos, yPos);
            } else {
                ctx.lineTo(xPos, yPos);
            }
        }
        ctx.strokeStyle = accPeach;
        ctx.lineWidth = 1.5;
        ctx.stroke();

        // Labels — very dim
        ctx.fillStyle = '#383838';
        ctx.font = '7px monospace';
        ctx.textAlign = 'left';
        ctx.fillText('IN', pad, pad + gh + 9);
        ctx.textAlign = 'right';
        ctx.fillText('OUT', pad + gw, pad - 2);

        // "drag to adjust" hint
        if (isInteractive && !isDragging.current) {
            ctx.fillStyle = 'rgba(255,255,255,0.25)';
            ctx.font = '7px monospace';
            ctx.textAlign = 'center';
            ctx.fillText('drag to adjust', width / 2, pad + 10);
        }
    }, [drive, mix, width, height, _tone, isInteractive]);

    const handlePointerDown = (event: React.PointerEvent<HTMLCanvasElement>) => {
        if (!onParamChange) {
            return;
        }
        const canvas = canvasRef.current;
        if (!canvas) {
            return;
        }
        isDragging.current = true;
        lastY.current = event.clientY;
        canvas.setPointerCapture(event.pointerId);
        canvas.style.cursor = 'grabbing';
    };

    const handlePointerMove = (event: React.PointerEvent<HTMLCanvasElement>) => {
        if (!onParamChange || !isDragging.current) {
            return;
        }
        const deltaY = lastY.current - event.clientY; // up = positive
        lastY.current = event.clientY;
        // Map vertical drag to drive change: ~0.5 drive units per pixel
        const sensitivity = 0.5;
        const newDrive = Math.max(0, Math.min(100, drive + deltaY * sensitivity));
        onParamChange('dist-drive', newDrive);
    };

    const handlePointerUp = (event: React.PointerEvent<HTMLCanvasElement>) => {
        if (!onParamChange) {
            return;
        }
        const canvas = canvasRef.current;
        if (!canvas) {
            return;
        }
        isDragging.current = false;
        canvas.releasePointerCapture(event.pointerId);
        canvas.style.cursor = 'grab';
    };

    return (
        <canvas
            ref={canvasRef}
            style={{ width, height, cursor: isInteractive ? 'grab' : undefined }}
            className="rounded border border-border/30"
            aria-label="Distortion transfer curve"
            role="img"
            onPointerDown={isInteractive ? handlePointerDown : undefined}
            onPointerMove={isInteractive ? handlePointerMove : undefined}
            onPointerUp={isInteractive ? handlePointerUp : undefined}
        />
    );
};

/**
 * EQ Curve — Interactive 3-band parametric EQ visualization.
 *
 * Drag band dots horizontally to change frequency, vertically to change gain.
 * Log frequency axis (20 Hz – 20 kHz), linear dB axis (±24 dB).
 */
import { type ReactElement, useRef, useEffect } from 'react';

import { resolveToken } from '#/utils/UI/resolveToken';

type EQCurveProps = {
    lowGain: number;
    lowFreq: number;
    lowQ: number;
    midGain: number;
    midFreq: number;
    midQ: number;
    highGain: number;
    highFreq: number;
    highQ: number;
    width?: number;
    height?: number;
    onParamChange?: (paramId: string, value: number) => void;
};

const peakingMag = (freq: number, fc: number, gainDb: number, Q: number): number => {
    if (Math.abs(gainDb) < 0.01) {
        return 0;
    }
    const width = freq / fc;
    const w2 = width * width;
    const bw = width / Q;
    const A = 10 ** (gainDb / 40);
    const num = (1 - w2) ** 2 + (bw * A) ** 2;
    const den = (1 - w2) ** 2 + (bw / A) ** 2;
    return 10 * Math.log10(num / den);
};

const MIN_FREQ = 20;
const MAX_FREQ = 20000;
const DB_RANGE = 24;

const freqToX = (freq: number, width: number): number =>
    (Math.log10(freq / MIN_FREQ) / Math.log10(MAX_FREQ / MIN_FREQ)) * width;

const xToFreq = (xPos: number, width: number): number => MIN_FREQ * (MAX_FREQ / MIN_FREQ) ** (xPos / width);

type BandId = 'low' | 'mid' | 'high';

const BAND_FREQ_PARAMS: Record<BandId, string> = {
    low: 'eq-low-freq',
    mid: 'eq-mid-freq',
    high: 'eq-high-freq',
};
const BAND_GAIN_PARAMS: Record<BandId, string> = {
    low: 'eq-low-gain',
    mid: 'eq-mid-gain',
    high: 'eq-high-gain',
};
const BAND_FREQ_RANGES: Record<BandId, [number, number]> = {
    low: [20, 500],
    mid: [200, 8000],
    high: [2000, 20000],
};
const BAND_COLORS: Record<BandId, string> = {
    low: '#f0944c', // warm orange (saturated)
    mid: '#50d0e8', // cyan (saturated)
    high: '#c488f0', // lavender (saturated)
};

export const EQCurve = ({
    lowGain,
    lowFreq,
    lowQ,
    midGain,
    midFreq,
    midQ,
    highGain,
    highFreq,
    highQ,
    width = 200,
    height = 80,
    onParamChange,
}: EQCurveProps): ReactElement => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const dragBand = useRef<BandId | null>(null);
    const isInteractive = !!onParamChange;

    const bands: Array<{ id: BandId; freq: number; gain: number; q: number }> = [
        { id: 'low', freq: lowFreq, gain: lowGain, q: lowQ },
        { id: 'mid', freq: midFreq, gain: midGain, q: midQ },
        { id: 'high', freq: highFreq, gain: highGain, q: highQ },
    ];

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) {
            return;
        }
        const ctx = canvas.getContext('2d');
        if (!ctx) {
            return;
        }

        const dpr = window.devicePixelRatio || 1;
        canvas.width = width * dpr;
        canvas.height = height * dpr;
        ctx.scale(dpr, dpr);
        ctx.clearRect(0, 0, width, height);

        // Background — deep black with subtle gradient
        const bgColor = resolveToken('--color-bg-tray', '#0a0a0a');
        const bgGrad = ctx.createLinearGradient(0, 0, 0, height);
        bgGrad.addColorStop(0, '#0e0e12');
        bgGrad.addColorStop(1, '#060608');
        ctx.fillStyle = bgGrad;
        ctx.beginPath();
        ctx.roundRect(0, 0, width, height, 4);
        ctx.fill();

        const zeroY = height / 2;

        // Grid — subtle dotted lines
        ctx.strokeStyle = 'rgba(255,255,255,0.05)';
        ctx.lineWidth = 0.5;
        ctx.setLineDash([1, 4]);
        ctx.beginPath();
        ctx.moveTo(0, zeroY);
        ctx.lineTo(width, zeroY);
        ctx.stroke();

        for (const freq of [100, 1000, 10000]) {
            const xPos = freqToX(freq, width);
            ctx.beginPath();
            ctx.moveTo(xPos, 0);
            ctx.lineTo(xPos, height);
            ctx.stroke();
        }
        for (const db of [-12, 12]) {
            const yPos = zeroY - (db / DB_RANGE) * (height / 2);
            ctx.beginPath();
            ctx.moveTo(0, yPos);
            ctx.lineTo(width, yPos);
            ctx.stroke();
        }
        ctx.setLineDash([]);

        // Compute combined curve
        const accentCyan = resolveToken('--color-accent-cyan', '#50d0e8');
        const points: [number, number][] = [];
        for (let index = 0; index <= width; index++) {
            const logFreq = MIN_FREQ * (MAX_FREQ / MIN_FREQ) ** (index / width);
            const totalDb =
                peakingMag(logFreq, lowFreq, lowGain, lowQ) +
                peakingMag(logFreq, midFreq, midGain, midQ) +
                peakingMag(logFreq, highFreq, highGain, highQ);
            const clampedDb = Math.max(-DB_RANGE, Math.min(DB_RANGE, totalDb));
            const yPos = zeroY - (clampedDb / DB_RANGE) * (height / 2);
            points.push([index, yPos]);
        }

        // Fill gradient below curve
        ctx.beginPath();
        ctx.moveTo(0, zeroY);
        for (const [xPos, yPos] of points) {
            ctx.lineTo(xPos, yPos);
        }
        ctx.lineTo(width, zeroY);
        ctx.closePath();
        const fillGrad = ctx.createLinearGradient(0, 0, 0, height);
        fillGrad.addColorStop(0, `${accentCyan}30`);
        fillGrad.addColorStop(1, `${accentCyan}05`);
        ctx.fillStyle = fillGrad;
        ctx.fill();

        // Glow pass — wider stroke, low alpha
        ctx.beginPath();
        for (let index = 0; index < points.length; index++) {
            const [xPos, yPos] = points[index]!;
            if (index === 0) {
                ctx.moveTo(xPos, yPos);
            } else {
                ctx.lineTo(xPos, yPos);
            }
        }
        ctx.strokeStyle = `${accentCyan}30`;
        ctx.lineWidth = 5;
        ctx.stroke();

        // Sharp stroke
        ctx.beginPath();
        for (let index = 0; index < points.length; index++) {
            const [xPos, yPos] = points[index]!;
            if (index === 0) {
                ctx.moveTo(xPos, yPos);
            } else {
                ctx.lineTo(xPos, yPos);
            }
        }
        ctx.strokeStyle = accentCyan;
        ctx.lineWidth = 1.5;
        ctx.stroke();

        // Band dots — colored and larger when interactive
        for (const band of bands) {
            const bx = freqToX(band.freq, width);
            const totalDb =
                peakingMag(band.freq, lowFreq, lowGain, lowQ) +
                peakingMag(band.freq, midFreq, midGain, midQ) +
                peakingMag(band.freq, highFreq, highGain, highQ);
            const by = zeroY - (Math.max(-DB_RANGE, Math.min(DB_RANGE, totalDb)) / DB_RANGE) * (height / 2);

            const dotR = isInteractive ? 6 : 3;
            const color = BAND_COLORS[band.id];

            ctx.beginPath();
            ctx.arc(bx, by, dotR, 0, Math.PI * 2);
            ctx.fillStyle = color;
            ctx.fill();
            if (isInteractive) {
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 1.5;
                ctx.stroke();
            } else {
                ctx.strokeStyle = bgColor;
                ctx.lineWidth = 1;
                ctx.stroke();
            }

            // Band label
            if (isInteractive) {
                ctx.fillStyle = color;
                ctx.font = 'bold 7px monospace';
                ctx.textAlign = 'center';
                ctx.fillText(band.id.toUpperCase()[0]!, bx, by - dotR - 3);
            }
        }

        // Frequency labels — very dim
        ctx.fillStyle = '#383838';
        ctx.font = '7px monospace';
        ctx.textAlign = 'center';
        for (const [label, freq] of [
            ['100', 100],
            ['1k', 1000],
            ['10k', 10000],
        ] as const) {
            ctx.fillText(label, freqToX(freq, width), height - 2);
        }

        if (isInteractive) {
            ctx.fillStyle = 'rgba(255,255,255,0.15)';
            ctx.font = '7px system-ui';
            ctx.textAlign = 'left';
            ctx.fillText('drag bands', 4, 10);
        }
    }, [
        lowGain,
        lowFreq,
        lowQ,
        midGain,
        midFreq,
        midQ,
        highGain,
        highFreq,
        highQ,
        width,
        height,
        isInteractive,
        bands,
    ]);

    const findNearestBand = (xPos: number): BandId | null => {
        let closest: BandId | null = null;
        let minDist = 20; // 20px hit radius
        for (const band of bands) {
            const bx = freqToX(band.freq, width);
            const dist = Math.abs(xPos - bx);
            if (dist < minDist) {
                minDist = dist;
                closest = band.id;
            }
        }
        return closest;
    };

    const handlePointerDown = (event: React.PointerEvent<HTMLCanvasElement>) => {
        if (!onParamChange) {
            return;
        }
        const canvas = canvasRef.current;
        if (!canvas) {
            return;
        }
        const rect = canvas.getBoundingClientRect();
        const xPos = event.clientX - rect.left;
        const band = findNearestBand(xPos);
        if (!band) {
            return;
        }
        dragBand.current = band;
        canvas.setPointerCapture(event.pointerId);
        canvas.style.cursor = 'grabbing';
    };

    const handlePointerMove = (event: React.PointerEvent<HTMLCanvasElement>) => {
        if (!dragBand.current || !onParamChange) {
            return;
        }
        const canvas = canvasRef.current;
        if (!canvas) {
            return;
        }
        const rect = canvas.getBoundingClientRect();
        const xPos = event.clientX - rect.left;
        const yPos = event.clientY - rect.top;
        const band = dragBand.current;

        // Horizontal → frequency (clamped to band range)
        const [minF, maxF] = BAND_FREQ_RANGES[band];
        const freq = Math.max(minF, Math.min(maxF, xToFreq(xPos, width)));
        onParamChange(BAND_FREQ_PARAMS[band], Math.round(freq));

        // Vertical → gain (±24 dB)
        const zeroY = height / 2;
        const db = -((yPos - zeroY) / (height / 2)) * DB_RANGE;
        const clampedDb = Math.max(-DB_RANGE, Math.min(DB_RANGE, Math.round(db * 2) / 2));
        onParamChange(BAND_GAIN_PARAMS[band], clampedDb);
    };

    const handlePointerUp = (event: React.PointerEvent<HTMLCanvasElement>) => {
        dragBand.current = null;
        const canvas = canvasRef.current;
        if (canvas) {
            canvas.releasePointerCapture(event.pointerId);
            canvas.style.cursor = isInteractive ? 'grab' : 'default';
        }
    };

    return (
        <canvas
            ref={canvasRef}
            style={{ width, height, cursor: isInteractive ? 'grab' : 'default' }}
            className="rounded border border-border/30"
            aria-label="EQ frequency response — drag band dots to adjust"
            role="img"
            onPointerDown={handlePointerDown}
            onPointerMove={handlePointerMove}
            onPointerUp={handlePointerUp}
        />
    );
};

/**
 * FilterResponse — Interactive frequency response visualization.
 *
 * Draws the frequency response of LP/HP/BP/Notch filters.
 * Drag the cutoff dot horizontally to change frequency,
 * vertically to change resonance.
 */
import { type ReactElement, useRef, useEffect } from 'react';

import { resolveToken } from '#/utils/UI/resolveToken';

type FilterResponseProps = {
    cutoff: number; // Hz (20–20000)
    resonance: number; // Q (0.1–20)
    filterType: number; // 0=LP, 1=HP, 2=BP, 3=Notch
    width?: number;
    height?: number;
    /** Called when user drags the cutoff dot */
    onParamChange?: (paramId: string, value: number) => void;
};

const MIN_FREQ = 20;
const MAX_FREQ = 20000;
const DB_RANGE = 30;

type FilterTypeLabel = 'LP' | 'HP' | 'BP' | 'Notch';
const FILTER_LABELS: FilterTypeLabel[] = ['LP', 'HP', 'BP', 'Notch'];

const filterMag = (freq: number, fc: number, Q: number, type: number): number => {
    const width = freq / fc;
    const w2 = width * width;
    const inv = 1 / Q;

    switch (type) {
        case 0: {
            const den = Math.sqrt((1 - w2) ** 2 + (width * inv) ** 2);
            return -20 * Math.log10(Math.max(den, 0.0001));
        }
        case 1: {
            const den = Math.sqrt((1 - w2) ** 2 + (width * inv) ** 2);
            return -20 * Math.log10(Math.max(den, 0.0001)) + 20 * Math.log10(Math.max(w2, 0.0001));
        }
        case 2: {
            const den = Math.sqrt((1 - w2) ** 2 + (width * inv) ** 2);
            return -20 * Math.log10(Math.max(den, 0.0001)) + 20 * Math.log10(Math.max(width * inv, 0.0001));
        }
        case 3: {
            const num = Math.sqrt((1 - w2) ** 2);
            const den = Math.sqrt((1 - w2) ** 2 + (width * inv) ** 2);
            return 20 * Math.log10(Math.max(num / den, 0.0001));
        }
        default:
            return 0;
    }
};

const freqToX = (freq: number, width: number): number =>
    (Math.log10(freq / MIN_FREQ) / Math.log10(MAX_FREQ / MIN_FREQ)) * width;

const xToFreq = (xPos: number, width: number): number => MIN_FREQ * (MAX_FREQ / MIN_FREQ) ** (xPos / width);

export const FilterResponse = ({
    cutoff,
    resonance,
    filterType,
    width = 200,
    height = 80,
    onParamChange,
}: FilterResponseProps): ReactElement => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const isDragging = useRef(false);
    const isInteractive = !!onParamChange;

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) {
            return;
        }
        const ctx = canvas.getContext('2d');
        if (!ctx) {
            return;
        }

        const dpr = window.devicePixelRatio || 1;
        canvas.width = width * dpr;
        canvas.height = height * dpr;
        ctx.scale(dpr, dpr);
        ctx.clearRect(0, 0, width, height);

        // Background — deep gradient
        const bgGrad = ctx.createLinearGradient(0, 0, 0, height);
        bgGrad.addColorStop(0, '#0e0e12');
        bgGrad.addColorStop(1, '#060608');
        ctx.fillStyle = bgGrad;
        ctx.beginPath();
        ctx.roundRect(0, 0, width, height, 4);
        ctx.fill();

        const zeroY = height * 0.6;

        // Grid — subtle dotted
        ctx.strokeStyle = 'rgba(255,255,255,0.04)';
        ctx.lineWidth = 0.5;
        ctx.setLineDash([1, 4]);
        ctx.beginPath();
        ctx.moveTo(0, zeroY);
        ctx.lineTo(width, zeroY);
        ctx.stroke();

        for (const freq of [100, 1000, 10000]) {
            const xPos = freqToX(freq, width);
            ctx.beginPath();
            ctx.moveTo(xPos, 0);
            ctx.lineTo(xPos, height);
            ctx.stroke();
        }
        ctx.setLineDash([]);

        // Cutoff vertical marker
        const cutoffX = freqToX(cutoff, width);
        ctx.strokeStyle = 'rgba(255,255,255,0.12)';
        ctx.setLineDash([2, 2]);
        ctx.beginPath();
        ctx.moveTo(cutoffX, 0);
        ctx.lineTo(cutoffX, height);
        ctx.stroke();
        ctx.setLineDash([]);

        // Compute curve
        const accentCyan = resolveToken('--color-accent-cyan', '#50d0e8');
        const type = Math.round(filterType);
        const points: [number, number][] = [];

        for (let index = 0; index <= width; index++) {
            const freq = MIN_FREQ * (MAX_FREQ / MIN_FREQ) ** (index / width);
            const db = filterMag(freq, cutoff, resonance, type);
            const clamped = Math.max(-DB_RANGE, Math.min(DB_RANGE, db));
            const yPos = zeroY - (clamped / DB_RANGE) * zeroY;
            points.push([index, yPos]);
        }

        // Fill gradient
        ctx.beginPath();
        ctx.moveTo(0, zeroY);
        for (const [xPos, yPos] of points) {
            ctx.lineTo(xPos, yPos);
        }
        ctx.lineTo(width, zeroY);
        ctx.closePath();
        const fillGrad = ctx.createLinearGradient(0, 0, 0, height);
        fillGrad.addColorStop(0, `${accentCyan}28`);
        fillGrad.addColorStop(1, `${accentCyan}04`);
        ctx.fillStyle = fillGrad;
        ctx.fill();

        // Glow pass
        ctx.beginPath();
        for (let index = 0; index < points.length; index++) {
            const [xPos, yPos] = points[index]!;
            if (index === 0) {
                ctx.moveTo(xPos, yPos);
            } else {
                ctx.lineTo(xPos, yPos);
            }
        }
        ctx.strokeStyle = `${accentCyan}30`;
        ctx.lineWidth = 5;
        ctx.stroke();

        // Sharp stroke
        ctx.beginPath();
        for (let index = 0; index < points.length; index++) {
            const [xPos, yPos] = points[index]!;
            if (index === 0) {
                ctx.moveTo(xPos, yPos);
            } else {
                ctx.lineTo(xPos, yPos);
            }
        }
        ctx.strokeStyle = accentCyan;
        ctx.lineWidth = 1.5;
        ctx.stroke();

        // Cutoff dot — larger if interactive
        const cutoffDb = filterMag(cutoff, cutoff, resonance, type);
        const dotY = zeroY - (Math.max(-DB_RANGE, Math.min(DB_RANGE, cutoffDb)) / DB_RANGE) * zeroY;
        const dotR = isInteractive ? 5 : 3;
        ctx.beginPath();
        ctx.arc(cutoffX, dotY, dotR, 0, Math.PI * 2);
        ctx.fillStyle = accentCyan;
        ctx.fill();
        if (isInteractive) {
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 1;
            ctx.stroke();
        }

        // Labels — very dim
        ctx.fillStyle = '#383838';
        ctx.font = '7px monospace';
        ctx.textAlign = 'center';
        for (const [label, freq] of [
            ['100', 100],
            ['1k', 1000],
            ['10k', 10000],
        ] as const) {
            ctx.fillText(label, freqToX(freq, width), height - 2);
        }

        // Filter type badge
        const typeLabel = FILTER_LABELS[type] ?? 'LP';
        ctx.fillStyle = accentCyan;
        ctx.font = 'bold 8px monospace';
        ctx.textAlign = 'right';
        ctx.fillText(typeLabel, width - 4, 10);

        // Interaction hint
        if (isInteractive) {
            ctx.fillStyle = 'rgba(255,255,255,0.15)';
            ctx.font = '7px system-ui';
            ctx.textAlign = 'left';
            ctx.fillText('drag to adjust', 4, 10);
        }
    }, [cutoff, resonance, filterType, width, height, isInteractive]);

    const handlePointerDown = (event: React.PointerEvent<HTMLCanvasElement>) => {
        if (!onParamChange) {
            return;
        }
        const canvas = canvasRef.current;
        if (!canvas) {
            return;
        }
        isDragging.current = true;
        canvas.setPointerCapture(event.pointerId);
        canvas.style.cursor = 'grabbing';
    };

    const handlePointerMove = (event: React.PointerEvent<HTMLCanvasElement>) => {
        if (!isDragging.current || !onParamChange) {
            return;
        }
        const canvas = canvasRef.current;
        if (!canvas) {
            return;
        }
        const rect = canvas.getBoundingClientRect();
        const xPos = event.clientX - rect.left;
        const yPos = event.clientY - rect.top;

        // Horizontal → frequency (log scale)
        const freq = Math.max(MIN_FREQ, Math.min(MAX_FREQ, xToFreq(xPos, width)));
        onParamChange('filterCutoff', Math.round(freq));

        // Vertical → resonance (inverted: top = high Q)
        const normalizedY = 1 - Math.max(0, Math.min(1, yPos / height));
        const query = 0.1 + normalizedY * 19.9; // 0.1 to 20
        onParamChange('filterResonance', Math.round(query * 10) / 10);
    };

    const handlePointerUp = (event: React.PointerEvent<HTMLCanvasElement>) => {
        isDragging.current = false;
        const canvas = canvasRef.current;
        if (canvas) {
            canvas.releasePointerCapture(event.pointerId);
            canvas.style.cursor = isInteractive ? 'grab' : 'default';
        }
    };

    return (
        <canvas
            ref={canvasRef}
            style={{ width, height, cursor: isInteractive ? 'grab' : 'default' }}
            className="rounded border border-border/30"
            aria-label="Filter frequency response — drag to adjust cutoff and resonance"
            role="img"
            onPointerDown={handlePointerDown}
            onPointerMove={handlePointerMove}
            onPointerUp={handlePointerUp}
        />
    );
};

