import { describe, it, expect, beforeEach } from 'vitest';

import { Container } from '../Container';
import { inject } from '../inject';
import { resetContainerState } from '../internal/containerState';

describe('inject', () => {
    beforeEach(() => {
        resetContainerState();
        Container.clear();
    });

    it('should resolve plain values correctly', () => {
        const myFn = inject({ value: 42 })((deps) => () => deps.value);
        expect(myFn()).toBe(42);
    });

    it('should resolve class-token dependencies correctly', () => {
        class MyService {
            getValue() {
                return 'hello';
            }
        }
        Container.register(MyService, new MyService());

        const myFn = inject({ service: MyService })((deps) => () => deps.service.getValue());
        expect(myFn()).toBe('hello');
    });

    it('should resolve nested injectables correctly', () => {
        const inner = inject({ val: 10 })((deps) => () => deps.val);
        const outer = inject({ inner })((deps) => () => deps.inner() * 2);

        expect(outer()).toBe(20);
    });

    it('should memoize the factory after first call', () => {
        let factoryCalls = 0;
        const myFn = inject({ val: 1 })((deps) => {
            factoryCalls++;
            return () => deps.val;
        });

        myFn();
        myFn();
        expect(factoryCalls).toBe(1);
    });

    it('should resolve getter-backed dependencies only when lazy injectables are invoked', () => {
        let getterCalls = 0;
        const myFn = inject(
            {
                get value() {
                    getterCalls++;
                    return 42;
                },
            },
            { lazy: true }
        )((deps) => () => deps.value);

        expect(getterCalls).toBe(0);
        expect(myFn()).toBe(42);
        expect(getterCalls).toBe(1);

        myFn();
        expect(getterCalls).toBe(1);
    });

    it('should throw with full chain on circular dependencies', () => {
        const fnB: any = inject({ a: () => fnA })((deps) => {
            deps.a()();
            return () => {};
        });

        const fnA: any = inject({ b: () => fnB })((deps) => {
            deps.b()();
            return () => {};
        });

        expect(() => fnA()).toThrow(/Circular dependency chain detected/);
    });

    it('should reject async dependency values', () => {
        const myFn = inject({ asyncVal: Promise.resolve(1) })((deps) => () => deps.asyncVal);
        expect(() => myFn()).toThrow(/Async dependencies are forbidden/);
    });
});

import { Container } from './Container';
import { registrations, cache, testOverrides } from './internal/containerState';
import { type DependencyKey } from './types';

type ResolveDependency<TDep> = TDep extends new (...args: any[]) => infer TInstance ? TInstance : TDep;

type ResolveDependencies<TDeps extends Record<string, unknown>> = {
    [TKey in keyof TDeps]: ResolveDependency<TDeps[TKey]>;
};

export type InjectOptions = {
    lazy?: boolean;
};

// Internal metadata shape for injectable functions. `unknown` is used rather than `any`
// so downstream consumers must narrow through the well-typed `inject<TDeps>(...)` overloads.
// The runtime `_factory`/`_deps` are kept intentionally loose — they are only read by the
// DI machinery in this file and by test overrides via `Container.setTestOverride`.
// eslint-disable-next-line @typescript-eslint/no-explicit-any -- DI metadata; loose by design
type InjectableCallable = (...args: any[]) => any;

export type InjectableFunction = InjectableCallable & {
    _isInjectable: boolean;
    _deps: Record<string, unknown>;
    _factory: (deps: Record<string, unknown>) => InjectableCallable;
    _options?: InjectOptions;
};

const resolutionStack = new Set<InjectableFunction>();

function getDependencyToken<TDeps extends Record<string, unknown>>(
    deps: TDeps,
    key: keyof TDeps,
    options?: InjectOptions
): unknown {
    if (!options?.lazy) {
        return deps[key];
    }

    return Object.getOwnPropertyDescriptor(deps, key)?.get ?? deps[key];
}

function getDependencyOverride(dependencyToken: unknown): { hasOverride: boolean; override: unknown } {
    if (testOverrides.has(dependencyToken)) {
        return { hasOverride: true, override: testOverrides.get(dependencyToken) };
    }

    return { hasOverride: false, override: undefined };
}

function assertSyncDependency(key: string, resolved: unknown): unknown {
    if (resolved instanceof Promise) {
        throw new TypeError(`Async dependencies are forbidden: ${key}`);
    }

    return resolved;
}

function resolveInjectedDependency(key: string, rawDependency: unknown): unknown {
    let resolved: unknown;
    if (typeof rawDependency === 'function' && (rawDependency as InjectableFunction)._isInjectable) {
        resolved = rawDependency;
    } else if (
        rawDependency !== null &&
        typeof rawDependency === 'object' &&
        (rawDependency as InjectableFunction)._isInjectable
    ) {
        resolved = rawDependency;
    } else if (registrations.has(rawDependency as DependencyKey<unknown>)) {
        resolved = Container.get(rawDependency as DependencyKey<unknown>);
    } else {
        resolved = rawDependency;
    }

    return assertSyncDependency(key, resolved);
}

export function inject<TDeps extends Record<string, unknown>>(
    deps: TDeps
): <TFactoryReturn extends (...args: any[]) => any>(
    factory: (resolvedDeps: ResolveDependencies<TDeps>) => TFactoryReturn
) => TFactoryReturn & InjectableFunction;
export function inject<TDeps extends Record<string, unknown>>(
    deps: TDeps,
    options: InjectOptions
): <TFactoryReturn extends (...args: any[]) => any>(
    factory: (resolvedDeps: ResolveDependencies<TDeps>) => TFactoryReturn
) => TFactoryReturn & InjectableFunction;
export function inject<TDeps extends Record<string, unknown>>(deps: TDeps, options?: InjectOptions) {
    return <TFactoryReturn extends (...args: any[]) => any>(
        factory: (resolvedDeps: ResolveDependencies<TDeps>) => TFactoryReturn
    ): TFactoryReturn & InjectableFunction => {
        const invoker = (...args: any[]) => {
            let cachedInvoker = cache.get(invoker);
            if (!cachedInvoker) {
                if (resolutionStack.has(invoker as InjectableFunction)) {
                    const chain = Array.from(resolutionStack)
                        .map((item) => item.name || 'injectable')
                        .join(' -> ');
                    throw new Error(`Circular dependency chain detected: ${chain}`);
                }
                resolutionStack.add(invoker as InjectableFunction);

                try {
                    const resolvedDeps: Record<string, unknown> = {};
                    for (const key of Object.keys(deps) as Array<keyof TDeps>) {
                        const dependencyToken = getDependencyToken(deps, key, options);
                        const { hasOverride, override } = getDependencyOverride(dependencyToken);
                        if (hasOverride) {
                            resolvedDeps[String(key)] = assertSyncDependency(String(key), override);
                            continue;
                        }

                        const rawDependency = deps[key];
                        resolvedDeps[String(key)] = resolveInjectedDependency(String(key), rawDependency);
                    }

                    cachedInvoker = factory(resolvedDeps as ResolveDependencies<TDeps>);
                    cache.set(invoker, cachedInvoker);
                } finally {
                    resolutionStack.delete(invoker as InjectableFunction);
                }
            }
            return cachedInvoker(...args);
        };

        invoker._isInjectable = true;
        invoker._deps = deps;
        invoker._factory = factory;
        invoker._options = options;

        return invoker as unknown as TFactoryReturn & InjectableFunction;
    };
}

import type { DependencyKey } from '../types';

export const registrations = new Map<DependencyKey<any>, any>();
export const cache = new Map<any, any>();
export const testOverrides = new Map<any, any>();

export const resetContainerState = () => {
    registrations.clear();
    cache.clear();
    testOverrides.clear();
};

import { vi, type Mock } from 'vitest';

export type MockObject<TShape> = {
    [TKey in keyof TShape]: TShape[TKey] extends (...args: any[]) => any ? Mock<TShape[TKey]> : TShape[TKey];
};

export const createMock = <TShape extends Record<string, any>>(overrides?: Partial<TShape>): MockObject<TShape> => {
    const base = overrides ? { ...overrides } : {};
    return new Proxy(base as MockObject<TShape>, {
        get(target, prop) {
            if (prop in target) {
                return target[prop as keyof MockObject<TShape>];
            }
            if (prop === 'then') {
                return undefined;
            }

            const mockFn = vi.fn();
            (target as any)[prop] = mockFn;
            return mockFn;
        },
    });
};

import { Container } from '../Container';
import { testOverrides } from '../internal/containerState';

import type { InjectableFunction } from '../inject';

export const injectDependencies = <TInjectable extends InjectableFunction, TMocks extends Record<string, any>>(
    injectable: TInjectable,
    mocks: TMocks
) => {
    Container.clear();

    for (const key of Object.keys(injectable._deps)) {
        if (!(key in mocks)) {
            throw new Error(`Missing mock for dependency: ${key}`);
        }
    }

    for (const [key, mockValue] of Object.entries(mocks)) {
        const originalDep = injectable._options?.lazy
            ? (Object.getOwnPropertyDescriptor(injectable._deps, key)?.get ?? injectable._deps[key])
            : injectable._deps[key];
        testOverrides.set(originalDep, mockValue);
    }

    return injectable;
};

import { vi, type Mock } from 'vitest';

export type SpyObject<TShape> = {
    [TKey in keyof TShape]: TShape[TKey] extends (...args: any[]) => any ? Mock<TShape[TKey]> : TShape[TKey];
};

export const spy = <TShape extends Record<string, any>>(): SpyObject<TShape> => {
    const spyCache = new Map<string | symbol, any>();
    return new Proxy({} as SpyObject<TShape>, {
        get(_target, prop) {
            if (prop === 'then') {
                return undefined;
            }
            if (!spyCache.has(prop)) {
                spyCache.set(prop, vi.fn());
            }
            return spyCache.get(prop);
        },
    });
};

export type DependencyKey<TValue> = (new (...args: any[]) => TValue) | symbol | string;

export type ContainerApi = {
    register<TValue>(token: DependencyKey<TValue>, value: TValue): void;
    set<TValue>(token: DependencyKey<TValue>, value: TValue): void;
    get<TValue>(token: DependencyKey<TValue>): TValue;
    clear(): void;
};

