/**
 * useVoiceRecording — Manages the voice-to-text lifecycle for the voice command overlay.
 *
 * Detection order:
 *  1. Browser SpeechRecognition API (Chrome/Edge)
 *  2. Whisper native via Tauri IPC (desktop builds, auto-downloads model)
 */

import { useEffect, useRef, useState } from 'react';

import { logger } from '#/infra/logger/appLogger';
import { isTauri as isTauriAvailable } from '#/utils/tauriBridge';

import { voiceStatusStore } from '../../stores/voiceStatusStore';
import { injectPromptCommand } from '../../useCases/promptInjection';
import { ensureWhisperReady } from '../../useCases/voiceDictation/ensureWhisperReady';
import { onDictationResult } from '../../useCases/voiceDictation/onDictationResult';
import { startDictation } from '../../useCases/voiceDictation/startDictation';
import { stopDictation } from '../../useCases/voiceDictation/stopDictation';
import { onVoiceToggle } from '../../useCases/voiceToggle/onVoiceToggle';

// ── Types ───────────────────────────────────────────────────────────────

type SpeechRecognitionInstance = {
    continuous: boolean;
    interimResults: boolean;
    lang: string;
    start(): void;
    stop(): void;
    abort(): void;
    onresult: ((event: { results: SpeechRecognitionResultList }) => void) | null;
    onerror: ((event: { error: string }) => void) | null;
    onend: (() => void) | null;
};

type VoiceMode = 'browser' | 'whisper' | null;

// ── Helpers ─────────────────────────────────────────────────────────────

const getSpeechRecognition = (): SpeechRecognitionInstance | null => {
    const w = window as unknown as Record<string, unknown>;
    const Ctor = w.SpeechRecognition ?? w.webkitSpeechRecognition;
    if (!Ctor) {
        return null;
    }
    return new (Ctor as new () => SpeechRecognitionInstance)();
};

export const isSpeechRecognitionAvailable = (): boolean => {
    const w = window as unknown as Record<string, unknown>;
    return !!(w.SpeechRecognition ?? w.webkitSpeechRecognition);
};

const resolveVoiceMode = (): VoiceMode => {
    if (isSpeechRecognitionAvailable()) {
        return 'browser';
    }
    if (isTauriAvailable()) {
        return 'whisper';
    }
    return null;
};

/** Ensure the Whisper model is downloaded and loaded before first use. */
const ensureWhisperLoaded = async (): Promise<void> => {
    await ensureWhisperReady();
};

// ── Hook return type ────────────────────────────────────────────────────

export type VoiceRecordingState = {
    isListening: boolean;
    interimText: string;
    finalText: string;
    transcribing: boolean;
    errorText: string;
    voiceMode: VoiceMode;
    stopListening: () => void;
    toggleListening: () => void;
};

/**
 * Manages voice recording lifecycle: browser SpeechRecognition or native Whisper.
 * Injects transcribed text into the prompt bar via `injectPromptCommand`.
 */
export const useVoiceRecording = (): VoiceRecordingState => {
    const [isListening, setIsListening] = useState(false);
    const [interimText, setInterimText] = useState('');
    const [finalText, setFinalText] = useState('');
    const [transcribing, setTranscribing] = useState(false);
    const [errorText, setErrorText] = useState('');

    // Sync to voiceStatusStore so VoiceButton can reflect state
    const setListening = (value: boolean): void => {
        setIsListening(value);
        voiceStatusStore.set({ isListening: value, transcribing: voiceStatusStore.value?.transcribing ?? false });
    };
    const setTranscribingAndStore = (value: boolean): void => {
        setTranscribing(value);
        voiceStatusStore.set({ isListening: voiceStatusStore.value?.isListening ?? false, transcribing: value });
    };

    const recognitionRef = useRef<SpeechRecognitionInstance | null>(null);
    const mediaRecorderRef = useRef<MediaRecorder | null>(null);
    const chunksRef = useRef<Blob[]>([]);
    const modeRef = useRef<VoiceMode>(null);
    const isListeningRef = useRef(false);

    // Keep ref in sync with state
    useEffect(() => {
        isListeningRef.current = isListening;
    }, [isListening]);

    // ── Whisper recording ───────────────────────────────────────────────

    const cleanupWhisperRecording = (): void => {
        if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
            mediaRecorderRef.current.stop();
        }
        mediaRecorderRef.current = null;
        chunksRef.current = [];
    };

    const startWhisperRecording = async (): Promise<void> => {
        try {
            // Auto-download and load model on first use
            await ensureWhisperLoaded();

            // Listen for transcription result from Rust
            const unlisten = await onDictationResult((result) => {
                const text = result.text?.trim() ?? '';
                if (text) {
                    setFinalText(text);
                    injectPromptCommand(text);
                }
                setTranscribing(false);
                setIsListening(false);
                unlisten();
            });

            // Start native recording via cpal + whisper inference
            await startDictation();

            modeRef.current = 'whisper';
            setListening(true);
            setFinalText('');
            setInterimText('Recording...');
        } catch (error: unknown) {
            logger.warn(`Whisper recording failed: ${String(error)}`);
            setListening(false);
        }
    };

    // ── Browser SpeechRecognition ────────────────────────────────────────

    const showError = (msg: string): void => {
        setErrorText(msg);
        setListening(true);
        setTimeout(() => {
            setErrorText('');
            setListening(false);
        }, 3000);
    };

    const startBrowserRecognition = (): boolean => {
        if (recognitionRef.current) {
            return true;
        }

        const recognition = getSpeechRecognition();
        if (!recognition) {
            return false;
        }

        recognition.continuous = true;
        recognition.interimResults = true;
        recognition.lang = 'en-US';

        let accumulated = '';
        let hadError = false;

        recognition.onresult = (event) => {
            let finalPart = '';
            let interimPart = '';
            for (let index = 0; index < event.results.length; index++) {
                const result = event.results[index];
                if (!result || result.length === 0 || !result[0]) {
                    continue;
                }
                if (result.isFinal) {
                    finalPart += result[0].transcript;
                } else {
                    interimPart += result[0].transcript;
                }
            }
            accumulated = finalPart;
            setFinalText(finalPart);
            setInterimText(interimPart);
        };

        recognition.onerror = (event) => {
            logger.warn(`Speech recognition error: ${event.error}`);

            if (event.error === 'not-allowed' || event.error === 'service-not-allowed') {
                hadError = true;
                recognitionRef.current = null;
                showError('Microphone access denied. Allow mic in browser settings.');
                if (isTauriAvailable()) {
                    modeRef.current = 'whisper';
                    void startWhisperRecording();
                }
                return;
            }
        };

        recognition.onend = () => {
            recognitionRef.current = null;
            if (hadError) {
                return;
            }
            setIsListening(false);

            const text = accumulated.trim();
            if (text) {
                injectPromptCommand(text);
            }
            setFinalText('');
            setInterimText('');
        };

        try {
            recognition.start();
            recognitionRef.current = recognition;
            modeRef.current = 'browser';
            setListening(true);
            setFinalText('');
            setInterimText('');
            setErrorText('');
            return true;
        } catch {
            return false;
        }
    };

    // ── Start / stop / toggle ───────────────────────────────────────────

    const stopListening = (): void => {
        if (modeRef.current === 'browser' && recognitionRef.current) {
            recognitionRef.current.stop();
            recognitionRef.current = null;
        }
        if (modeRef.current === 'whisper') {
            setTranscribingAndStore(true);
            setInterimText('Transcribing...');
            stopDictation().catch((error: unknown) => {
                logger.warn(`stop_dictation failed: ${String(error)}`);
            });
            // The dictation-result event listener (set in startWhisperRecording) handles the rest
            return;
        }
        setListening(false);
    };

    const startListening = (): void => {
        const mode = resolveVoiceMode();

        if (mode === 'browser') {
            const started = startBrowserRecognition();
            if (!started && isTauriAvailable()) {
                void startWhisperRecording();
            }
            return;
        }

        if (mode === 'whisper') {
            void startWhisperRecording();
            return;
        }

        showError('Voice input not available in this browser');
    };

    const toggleListening = (): void => {
        if (isListening) {
            stopListening();
        } else {
            startListening();
        }
    };

    // ── External toggle event ───────────────────────────────────────────

    useEffect(() => {
        return onVoiceToggle((payload) => {
            if (payload && typeof payload.active === 'boolean') {
                if (payload.active && !isListeningRef.current) {
                    startListening();
                } else if (!payload.active && isListeningRef.current) {
                    stopListening();
                }
            } else {
                toggleListening();
            }
        });
        // eslint-disable-next-line react-hooks/exhaustive-deps -- stable refs, intentional
    }, []);

    // ── Cleanup on unmount ──────────────────────────────────────────────

    useEffect(() => {
        return () => {
            if (recognitionRef.current) {
                recognitionRef.current.abort();
            }
            cleanupWhisperRecording();
        };
    }, []);

    return {
        isListening,
        interimText,
        finalText,
        transcribing,
        errorText,
        voiceMode: modeRef.current,
        stopListening,
        toggleListening,
    };
};

import { type ReactElement, useState } from 'react';

import { History, Undo2, Trash2, ChevronDown, ChevronRight, X, Bot, User } from 'lucide-react';

import { DawEmptyState } from '#/components/daw/DawEmptyState';
import { DawHeaderBand } from '#/components/daw/DawHeaderBand';
import { DawUtilityListRow } from '#/components/daw/DawUtilityListRow';
import { DawUtilityPanel } from '#/components/daw/DawUtilityPanel';
import { Button } from '#/components/ui/button';
import { ScrollArea } from '#/components/ui/scroll-area';
import { useStore } from '#/infra/store/useStore';
import { actionHistoryStore, clearActionHistory } from '#/modules/CrdtDocument/stores';
import { canRevertAction, revertAction } from '#/modules/CrdtDocument/useCases';

import { aiActionHistoryStore, toggleAiHistoryPanel, clearAiHistory } from '../../stores/aiActionHistoryStore';
import { revertAiActionGroup } from '../../useCases/aiHistoryActions';

type AiActionEntryView = { kind: 'appAction'; actionType: string; label: string } | { kind: 'jsonEdit'; label: string };

type AiActionGroupView = {
    id: string;
    prompt: string;
    actions: AiActionEntryView[];
    groupId: string;
    timestamp: number;
    reverted: boolean;
};

type ActionHistoryEntryView = {
    id: string;
    label: string;
    actionKind: string;
    action: { type: string; payload?: unknown };
    inverseAction: { type: string; payload?: unknown } | null;
    source: 'manual' | 'prompt' | 'voice' | 'ai';
    timestamp: number;
    reverted: boolean;
};

const defaultAiState = { groups: [] as AiActionGroupView[], panelOpen: false };
const defaultHistoryState = { entries: [] as ActionHistoryEntryView[] };

type HistoryItem = { kind: 'ai'; group: AiActionGroupView } | { kind: 'action'; entry: ActionHistoryEntryView };

/**
 * Unified Action History — shows all user and AI actions in chronological order.
 * AI actions show as expandable groups with batch revert.
 * User actions show individually with non-linear revert when an inverse exists.
 */
export const AiActionHistoryPanel = (): ReactElement | null => {
    const aiState = useStore(aiActionHistoryStore, defaultAiState);
    const historyState = useStore(actionHistoryStore, defaultHistoryState);

    if (!aiState.panelOpen) {
        return null;
    }

    const items: HistoryItem[] = [];

    for (const group of aiState.groups) {
        items.push({ kind: 'ai', group });
    }

    for (const entry of historyState.entries) {
        if (entry.source !== 'ai') {
            items.push({ kind: 'action', entry });
        }
    }

    items.sort((alpha, b) => {
        const ta = alpha.kind === 'ai' ? alpha.group.timestamp : alpha.entry.timestamp;
        const tb = b.kind === 'ai' ? b.group.timestamp : b.entry.timestamp;
        return tb - ta;
    });

    const visibleItems = items.slice(0, 50);

    const handleClearAll = () => {
        clearAiHistory();
        clearActionHistory();
    };

    return (
        <DawUtilityPanel className="fixed right-4 bottom-16 z-50 flex max-h-[60vh] w-80 flex-col animate-in slide-in-from-right-5">
            <DawHeaderBand
                className="rounded-t-lg px-3 py-2"
                startSlot={<History className="size-3.5 text-[var(--color-accent-lavender)]" />}
                title="Action History"
                titleClassName="text-xs font-medium normal-case tracking-normal text-foreground"
                actions={
                    <div className="flex items-center gap-1">
                        {visibleItems.length > 0 ? (
                            <Button
                                variant="ghost"
                                size="icon-xs"
                                onClick={handleClearAll}
                                title="Clear history"
                                aria-label="Clear action history"
                            >
                                <Trash2 className="size-3" />
                            </Button>
                        ) : null}
                        <Button
                            variant="ghost"
                            size="icon-xs"
                            onClick={toggleAiHistoryPanel}
                            aria-label="Close action history"
                        >
                            <X className="size-3" />
                        </Button>
                    </div>
                }
            />
            <ScrollArea className="flex-1 max-h-[50vh]">
                {visibleItems.length === 0 ? (
                    <div className="p-3">
                        <DawEmptyState
                            compact
                            icon={<History className="size-4" />}
                            title="No actions yet"
                            description="Changes you make will appear here."
                        />
                    </div>
                ) : (
                    visibleItems.map((item, idx) =>
                        item.kind === 'ai' ? (
                            <AiGroupItem key={`ai-${item.group.id}`} group={item.group} />
                        ) : (
                            <ActionItem key={`action-${item.entry.id}-${idx}`} entry={item.entry} />
                        )
                    )
                )}
            </ScrollArea>
        </DawUtilityPanel>
    );
};

const AiGroupItem = ({ group }: { group: AiActionGroupView }): ReactElement => {
    const [expanded, setExpanded] = useState(false);

    return (
        <div className={`border-b border-border/50 last:border-0 ${group.reverted ? 'opacity-40' : ''}`}>
            <DawUtilityListRow
                dimmed={group.reverted}
                startSlot={
                    <div className="flex items-center gap-1.5">
                        <button
                            type="button"
                            onClick={() => setExpanded(!expanded)}
                            className="text-muted-foreground hover:text-foreground"
                        >
                            {expanded ? <ChevronDown className="size-3" /> : <ChevronRight className="size-3" />}
                        </button>
                        <Bot className="size-3 text-[var(--color-accent-lavender)]" />
                    </div>
                }
                title={group.prompt}
                subtitle={`${group.actions.length} change${group.actions.length !== 1 ? 's' : ''} · ${formatTimeAgo(group.timestamp)}`}
                endSlot={
                    !group.reverted ? (
                        <Button
                            variant="ghost"
                            size="icon-xs"
                            onClick={() => void revertAiActionGroup(group)}
                            title="Undo all changes from this AI action"
                        >
                            <Undo2 className="size-3" />
                        </Button>
                    ) : (
                        <span className="text-[8px] italic text-muted-foreground">undone</span>
                    )
                }
            />
            {expanded ? (
                <div className="px-3 pb-1.5 pl-8 space-y-0.5">
                    {group.actions.map((alpha, index) => (
                        <div key={index} className="flex items-center gap-1.5">
                            <span className="size-1 rounded-full bg-[var(--color-accent-lavender)]/40 shrink-0" />
                            <span className="text-[9px] text-muted-foreground truncate">{alpha.label}</span>
                        </div>
                    ))}
                </div>
            ) : null}
        </div>
    );
};

const ActionItem = ({ entry }: { entry: ActionHistoryEntryView }): ReactElement => {
    const revertable = canRevertAction(entry);

    return (
        <DawUtilityListRow
            className="border-b border-border/30 last:border-0"
            dimmed={entry.reverted}
            startSlot={<User className="size-3 text-muted-foreground/50" />}
            title={entry.label}
            subtitle={formatTimeAgo(entry.timestamp)}
            endSlot={(() => {
                if (entry.reverted) {
                    return <span className="text-[8px] italic text-muted-foreground">undone</span>;
                }
                if (revertable) {
                    return (
                        <Button
                            variant="ghost"
                            size="icon-xs"
                            onClick={() => void revertAction(entry.id)}
                            title="Revert this change"
                        >
                            <Undo2 className="size-3 text-muted-foreground/50" />
                        </Button>
                    );
                }
                return null;
            })()}
        />
    );
};

function formatTimeAgo(timestamp: number): string {
    const seconds = Math.floor((Date.now() - timestamp) / 1000);
    if (seconds < 60) {
        return 'just now';
    }
    const minutes = Math.floor(seconds / 60);
    if (minutes < 60) {
        return `${minutes}m ago`;
    }
    const hours = Math.floor(minutes / 60);
    return `${hours}h ago`;
}

import { type ReactElement, useState, useEffect } from 'react';

import { Check, Undo2, X } from 'lucide-react';

import { DawUtilityPanel } from '#/components/daw/DawUtilityPanel';
import { Button } from '#/components/ui/button';

import { undoLastAction } from '../../useCases/aiPanelActions/undoLastAction';
import { type AiChangeNotification, subscribeAiChangeNotification } from '../../useCases/notifyAiChange';

export const AiChangeToast = (): ReactElement | null => {
    const [changes, setChanges] = useState<AiChangeNotification[]>([]);

    useEffect(() => {
        const handler = (change: AiChangeNotification) => {
            setChanges((prev) => [...prev, change]);
        };
        return subscribeAiChangeNotification(handler);
    }, []);

    useEffect(() => {
        if (changes.length === 0) {
            return undefined;
        }
        const timer = setTimeout(() => {
            setChanges((prev) => prev.slice(1));
        }, 5000);
        return () => clearTimeout(timer);
    }, [changes]);

    if (changes.length === 0) {
        return null;
    }

    const latest = changes[0]!;

    return (
        <DawUtilityPanel
            className="fixed bottom-16 right-4 z-50 w-72 p-3 animate-in slide-in-from-right-5"
            role="status"
            aria-live="polite"
        >
            <div className="flex items-start gap-2">
                <div className="mt-0.5 size-5 rounded-full bg-[var(--color-state-success)]/20 flex items-center justify-center shrink-0">
                    <Check className="size-3 text-[var(--color-state-success)]" />
                </div>
                <div className="flex-1 min-w-0">
                    <p className="text-xs font-medium text-foreground">{latest.summary}</p>
                    {latest.details.length > 0 ? (
                        <div className="mt-1 space-y-0.5">
                            {latest.details.map((detail, index) => (
                                <p key={index} className="text-[10px] text-muted-foreground">
                                    {detail}
                                </p>
                            ))}
                        </div>
                    ) : null}
                    <div className="mt-2 flex gap-1">
                        <Button
                            variant="ghost"
                            size="xs"
                            onClick={() => {
                                undoLastAction();
                                setChanges((prev) => prev.slice(1));
                            }}
                        >
                            <Undo2 className="size-3 mr-1" /> Undo
                        </Button>
                        <Button variant="ghost" size="xs" onClick={() => setChanges((prev) => prev.slice(1))}>
                            <X className="size-3 mr-1" /> Dismiss
                        </Button>
                    </div>
                </div>
            </div>
        </DawUtilityPanel>
    );
};

