            { function: { name: 'addTrack', description: 'Add a track', parameters: { type: 'object' } } },
        ]);
        mocks.create.mockResolvedValue({
            content: [
                { type: 'text', text: 'Sure, here are the edits.' },
                { type: 'tool_use', name: 'addTrack', input: { name: 'Vocals', kind: 'audio' } },
