            mocks.isTauri.mockReturnValue(false);
        });

        it('fetches SSE stream and parses tokens', async () => {
            const encoder = new TextEncoder();

            // Create a mock stream chunk reader
            const mockReadChunks = [
                encoder.encode('data: {"choices": [{"delta": {"content": "Hello"}}]}\n\n'),
                encoder.encode('data: {"choices": [{"delta": {"content": " World"}}]}\n\n'),
                encoder.encode('data: [DONE]\n\n'),
            ];

            let readIndex = 0;
            const mockReader = {
                read: vi.fn().mockImplementation(async () => {
                    if (readIndex < mockReadChunks.length) {
                        return { done: false, value: mockReadChunks[readIndex++] };
                    }
                    return { done: true, value: undefined };
                }),
            };

            mocks.fetch.mockResolvedValue({
                ok: true,
                body: { getReader: () => mockReader },
            });

            const tokens: string[] = [];
            function onToken(time: string) {
                tokens.push(time);
            }

            await streamNativeCompletion([{ role: 'user', content: 'hi' }], onToken);

            expect(mocks.fetch).toHaveBeenCalled();
            expect(tokens).toEqual(['Hello', ' World']);
        });

        it('throws an error if fetch fails', async () => {
            mocks.fetch.mockResolvedValue({
                ok: false,
                status: 404,
                text: async () => 'Not Found',
            });

            await expect(streamNativeCompletion([], vi.fn())).rejects.toThrow('llama-server error 404: Not Found');
        });

        it('throws if no body is returned', async () => {
            mocks.fetch.mockResolvedValue({
                ok: true,
                body: null,
            });

            await expect(streamNativeCompletion([], vi.fn())).rejects.toThrow('No response body');
        });
    });
});

/**
 * Native LLM engine lifecycle.
 *
 * In Tauri: loads the model in-process via mistral.rs (auto-downloads from HuggingFace on first use).
 * In browser dev mode: connects to a manually-started llama-server on localhost.
 */

import { inject } from '#/infra/di/inject';
import { logger } from '#/infra/logger/appLogger';
import { isTauri, tauriInvoke } from '#/utils/tauriBridge';

import { llmStatusStore } from '../../stores/llmStatusStore';

export const SIDECAR_PORT = parseInt((import.meta.env.VITE_LLM_SIDECAR_PORT as string | undefined) ?? '8847', 10);
export const BASE_URL = `http://127.0.0.1:${String(SIDECAR_PORT)}`;

// §67.4 — Wrapped in a holder so the module-level binding can't be
// reassigned from outside the file.
const nativeEngineState = { ready: false };

async function checkLlamaServerHealth(): Promise<boolean> {
    try {
        const response = await fetch(`${BASE_URL}/health`, { signal: AbortSignal.timeout(2000) });
        return response.ok;
    } catch {
        return false;
    }
}

export const initNativeEngine = inject({ logger })(
    ({ logger }) =>
        async function initNativeEngine(): Promise<void> {
            if (isTauri()) {
                llmStatusStore.set({
                    state: 'loading',
                    progress: 0,
                    text: 'Starting AI engine…',
                });

                // Listen for real progress events from Rust
                let unlisten: (() => void) | null = null;
                try {
                    const { tauriListen } = await import('#/utils/tauriBridge');
                    unlisten = await tauriListen('llm-progress', (event: unknown) => {
                        const payload = (event as { payload: { progress: number; text: string } }).payload;
                        if (payload) {
                            llmStatusStore.set({
                                state: 'loading',
                                progress: payload.progress,
                                text: payload.text,
                            });
                        }
                    });
                } catch {
                    // Listener setup failed — progress will just stay at initial message
                }

                try {
                    await tauriInvoke('init_native_llm', { modelId: null });
                } catch (error) {
                    if (unlisten) {
                        unlisten();
                    }
                    const msg = error instanceof Error ? error.message : String(error);
                    llmStatusStore.set({ state: 'error', message: msg });
                    throw error;
                }

                if (unlisten) {
                    unlisten();
                }
                nativeEngineState.ready = true;
                logger.info('[Native AI] In-process LLM ready');
                return;
            }

            // Browser dev mode: fall back to external llama-server
            logger.info('[Native AI] Browser mode — checking if llama-server is running...');
            const healthy = await checkLlamaServerHealth();
            if (healthy) {
                nativeEngineState.ready = true;
                logger.info(`[Native AI] Connected to llama-server on port ${String(SIDECAR_PORT)}`);
                return;
            }

            throw new Error(
                `llama-server not reachable at ${BASE_URL}. ` +
                    `Start it manually: llama-server --model <path-to-gguf> --port ${String(SIDECAR_PORT)} --host 127.0.0.1 --n-gpu-layers 99`
            );
        }
);

export const stopNativeEngine = inject({ logger })(
    ({ logger }) =>
        async function stopNativeEngine(): Promise<void> {
            if (isTauri()) {
                await tauriInvoke('unload_native_llm');
            }
            nativeEngineState.ready = false;
            logger.info('[Native AI] Engine stopped');
        }
);

export function isNativeEngineReady(): boolean {
    return nativeEngineState.ready;
}

import { isTauri, tauriInvoke, createChannel } from '#/utils/tauriBridge';

import { BASE_URL } from './lifecycle';

type LlmStreamEvent =
    | { event: 'token'; data: { text: string } }
    | { event: 'done'; data: { totalTokens: number } }
    | { event: 'error'; data: { message: string } };

/**
 * Streaming completion.
 * In Tauri: in-process streaming via mistral.rs + Tauri Channel.
 * In browser dev mode: SSE from localhost llama-server.
 */
export async function streamNativeCompletion(
    messages: Array<{ role: string; content: string }>,
    onToken: (text: string) => void,
    options?: { temperature?: number; maxTokens?: number }
): Promise<void> {
    if (isTauri()) {
        const channel = await createChannel<LlmStreamEvent>();

        // Errors thrown inside onmessage (a synchronous callback) do not propagate
        // to the awaiting tauriInvoke call — capture and rethrow after the invoke.
        const streamState = { error: null as Error | null };
        channel.onmessage = (event: LlmStreamEvent) => {
            if (event.event === 'token') {
                onToken(event.data.text);
            }
            if (event.event === 'error') {
                streamState.error = new Error(event.data.message);
            }
        };

        const systemPrompt = messages.find((message) => message.role === 'system')?.content ?? '';
        const nonSystemMessages = messages.filter((message) => message.role !== 'system');

        await tauriInvoke('stream_native_completion', {
            systemPrompt,
            messages: nonSystemMessages,
            temperature: options?.temperature ?? 0.7,
            maxTokens: options?.maxTokens ?? 2048,
            onEvent: channel,
        });

        if (streamState.error) {
            throw streamState.error;
        }
        return;
    }

    // Browser dev mode: SSE from llama-server
    const response = await fetch(`${BASE_URL}/v1/chat/completions`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
            messages,
            temperature: options?.temperature ?? 0.7,
            max_tokens: options?.maxTokens ?? 2048,
            seed: 0,
            stream: true,
        }),
    });

    if (!response.ok) {
        const text = await response.text();
        throw new Error(`llama-server error ${String(response.status)}: ${text}`);
    }

    const reader = response.body?.getReader();
    if (!reader) {
        throw new Error('No response body');
    }

    const decoder = new TextDecoder();
    let buffer = '';

    while (true) {
        const { done, value } = await reader.read();
        if (done) {
            break;
        }

        buffer += decoder.decode(value, { stream: true });
        const lines = buffer.split('\n');
        buffer = lines.pop() ?? '';

        for (const line of lines) {
            const trimmed = line.trim();
            if (!trimmed.startsWith('data: ')) {
                continue;
            }
            const jsonStr = trimmed.slice(6);
            if (jsonStr === '[DONE]') {
                return;
            }
            try {
                const chunk = JSON.parse(jsonStr) as { choices: Array<{ delta: { content?: string } }> };
                const content = chunk.choices[0]?.delta.content;
                if (content) {
                    onToken(content);
                }
            } catch {
                // Skip malformed SSE chunks
            }
        }
    }
}

