import { inject } from '#/infra/di/inject';
import { logger } from '#/infra/logger/appLogger';

import { DEFAULT_WEBLLM_MODEL_ID } from '../../models/ModelInfo';
import { llmStatusStore } from '../../stores/llmStatusStore';

/**
 * WebLLM engine type — resolved dynamically to avoid loading the 6.2MB
 * WebLLM bundle on the main thread at import time.
 */
type WebLlmEngine = {
    chat: {
        completions: {
            create: (params: Record<string, unknown>) => Promise<unknown>;
        };
    };
};

// §67.2 — Coalesce 4 module-level \`let\`s into one holder so the WebLLM
// engine lifecycle lives behind a single named handle.
const engineState: {
    engine: WebLlmEngine | null;
    initPromise: Promise<WebLlmEngine> | null;
    worker: Worker | null;
    activeModelId: string;
} = {
    engine: null,
    initPromise: null,
    worker: null,
    activeModelId: DEFAULT_WEBLLM_MODEL_ID,
};

export function getActiveModelId(): string {
    return engineState.activeModelId;
}

export const initWebLlmEngine = inject({ logger })(
    ({ logger }) =>
        function initWebLlmEngine(modelId?: string): Promise<WebLlmEngine> {
            const targetModel = modelId ?? engineState.activeModelId;

            // If already loaded with the same model, return immediately
            if (engineState.engine && targetModel === engineState.activeModelId) {
                return Promise.resolve(engineState.engine);
            }

            // If switching models, unload the current one first
            if (engineState.engine && targetModel !== engineState.activeModelId) {
                unloadWebLlmEngine();
            }

            if (engineState.initPromise && targetModel === engineState.activeModelId) {
                return engineState.initPromise;
            }

            engineState.activeModelId = targetModel;

            // WebGPU is required — absent on Linux (WebKitGTK) and older browsers
            if (typeof navigator === 'undefined' || !('gpu' in navigator)) {
                return Promise.reject(
                    new Error('WebGPU not available — WebLLM requires WebGPU. Use native or cloud backend instead.')
                );
            }

            engineState.initPromise = (async () => {
                llmStatusStore.set({ state: 'loading', progress: 0, text: 'Loading AI engine...' });

                // Dynamic import — avoids loading the 6.2MB WebLLM bundle at app startup.
                // The bundle is only fetched when the user actually requests model loading.
                const [{ CreateWebWorkerMLCEngine }, { default: LlmWorker }] = await Promise.all([
                    import('@mlc-ai/web-llm'),
                    import('../llmWorker?worker'),
                ]);

                const worker = new LlmWorker();
                engineState.worker = worker;

                const created = await CreateWebWorkerMLCEngine(
                    worker,
                    targetModel,
                    {
                        initProgressCallback: (report: { progress: number; text: string }) => {
                            llmStatusStore.set({
                                state: 'loading',
                                progress: report.progress,
                                text: report.text,
                            });
                        },
                    },
                    { context_window_size: 8192 }
                );

                engineState.engine = created as unknown as WebLlmEngine;
                llmStatusStore.set({ state: 'ready', modelId: targetModel });
                logger.info(`[AI Engine] WebLLM loaded: ${targetModel}`);
                return engineState.engine;
            })();

            engineState.initPromise.catch((error) => {
                llmStatusStore.set({ state: 'error', message: String(error) });
                engineState.initPromise = null;
                engineState.engine = null;
            });

            return engineState.initPromise;
        }
);

export const unloadWebLlmEngine = inject({ logger })(
    ({ logger }) =>
        function unloadWebLlmEngine(): void {
            if (engineState.worker) {
                engineState.worker.terminate();
                engineState.worker = null;
            }
            engineState.engine = null;
            engineState.initPromise = null;
            logger.info('[AI Engine] WebLLM unloaded from memory');
        }
);

export function isWebLlmLoaded(): boolean {
    return engineState.engine !== null;
}

export function getLlmEngine(): WebLlmEngine | null {
    return engineState.engine;
}

/**
 * Legacy text completion — kept for the chat assistant (non-command use).
 */
export async function generateWebLlmCompletion(
    systemPrompt: string,
    userMessage: string,
    options?: { temperature?: number; maxTokens?: number }
): Promise<string> {
    const eng = await initWebLlmEngine();
    const messages = [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userMessage },
    ];
    const payload: Record<string, unknown> = {
        messages,
        temperature: options?.temperature ?? 0.3,
        max_tokens: options?.maxTokens ?? 2048,
        seed: 0,
    };

    // Log model id + payload keys (never payload contents) so any stray
    // `tools:` attachment on a WebLLM call surfaces as a single structured
    // line instead of an `UnsupportedModelIdError` stack trace. MLC models do
    // not support the native `tools` API; see `supportsToolsApi()` in
    // `#/utils/capabilities`.
    logger.info(`[WebLLM] completion model=${engineState.activeModelId} keys=${Object.keys(payload).sort().join(',')}`);

    const response = (await eng.chat.completions.create(payload)) as {
        choices: Array<{ message: { content: string } }>;
    };

    const raw = response.choices[0]?.message.content ?? '';
    // Qwen3 prefixes answers with <think>...</think> reasoning blocks.
    // Strip them so callers receive only the final output.
    return raw.replaceAll(/<think>[\s\S]*?<\/think>/g, '').trim();
}

/**
 * Lightweight fuzzy search over preset actions.
 *
 * No external dependencies. Scores each preset against user input tokens
 * using substring and prefix matching on label + keywords.
 */

import {
    PRESET_ACTIONS,
    CATEGORY_ORDER,
    type PresetAction,
    type PresetContext,
    type PresetCategory,
} from '../models/presetActions/registry';

export type FuzzyResult = {
    preset: PresetAction;
    score: number;
};

// ── Main search API ─────────────────────────────────────────────────────

/**
 * Search presets by query, returning the top `limit` results ranked by score.
 * Filters out presets whose selection requirements aren't met by the context.
 */
export function searchPresets(query: string, context: PresetContext, limit = 12): FuzzyResult[] {
    const trimmed = query.trim().toLowerCase();

    // Empty query → return all available presets grouped by category
    if (trimmed.length === 0) {
        return getAvailablePresets(context)
            .slice(0, limit)
            .map((preset) => ({
                preset,
                score: 0,
            }));
    }

    const tokens = trimmed.split(/\s+/);
    const results: FuzzyResult[] = [];

    for (const preset of PRESET_ACTIONS) {
        if (!isPresetAvailable(preset, context)) {
            continue;
        }

        const score = scorePreset(preset, tokens, trimmed);
        if (score > 0) {
            results.push({ preset, score });
        }
    }

    results.sort((alpha, b) => b.score - alpha.score);
    return results.slice(0, limit);
}

/**
 * Try to find an exact or near-exact match for execution.
 * Returns the best matching preset if confidence is high enough.
 */
export function findBestMatch(query: string, context: PresetContext): PresetAction | null {
    const results = searchPresets(query, context, 1);
    if (results.length === 0) {
        return null;
    }
    const best = results[0]!;
    // Require a meaningful score threshold for auto-execution
    if (best.score >= 50) {
        return best.preset;
    }
    return null;
}

/**
 * Get all available presets for the current context, grouped by category.
 */
export function getAvailablePresets(context: PresetContext): PresetAction[] {
    const available = PRESET_ACTIONS.filter((param) => isPresetAvailable(param, context));

    // Sort by category order
    const categoryIndex = new Map<PresetCategory, number>();
    for (const [index, cat] of CATEGORY_ORDER.entries()) {
        categoryIndex.set(cat, index);
    }

    available.sort((alpha, b) => {
        const ai = categoryIndex.get(alpha.category) ?? 99;
        const bi = categoryIndex.get(b.category) ?? 99;
        return ai - bi;
    });

    return available;
}

// ── Scoring ─────────────────────────────────────────────────────────────

function scorePreset(preset: PresetAction, tokens: string[], fullQuery: string): number {
    let score = 0;
    const labelLower = preset.label.toLowerCase();
    const allSearchable = [labelLower, ...preset.keywords.map((kIndex) => kIndex.toLowerCase())];

    // Exact label match → highest score
    if (labelLower === fullQuery) {
        return 200;
    }

    // Exact keyword match
    for (const kw of preset.keywords) {
        if (kw.toLowerCase() === fullQuery) {
            return 180;
        }
    }

    // Label starts with query
    if (labelLower.startsWith(fullQuery)) {
        score += 100;
    }

    // Any keyword starts with query
    for (const kw of preset.keywords) {
        if (kw.toLowerCase().startsWith(fullQuery)) {
            score = Math.max(score, 90);
        }
    }

    // Token matching: each token that appears in any searchable string
    let matchedTokens = 0;
    for (const token of tokens) {
        let tokenMatched = false;
        for (const searchable of allSearchable) {
            if (searchable.includes(token)) {
                tokenMatched = true;

                // Bonus for prefix match in a word boundary
                const words = searchable.split(/[\s\-/]+/);
                for (const word of words) {
                    if (word.startsWith(token)) {
                        score += 15;
                        break;
                    }
                }

                score += 10;
                break;
            }
        }
        if (tokenMatched) {
            matchedTokens++;
        }
    }

    // All tokens must match for a meaningful score
    if (matchedTokens < tokens.length) {
        return 0;
    }

    // Bonus for matching most tokens
    if (tokens.length > 1 && matchedTokens === tokens.length) {
        score += 20;
    }

    // Substring match of full query in label
    if (labelLower.includes(fullQuery)) {
        score += 30;
    }

    // Category keyword match (approximate the user's intent)
    const lastToken = tokens[tokens.length - 1]!;
    if (preset.category.toLowerCase().startsWith(lastToken)) {
        score += 5;
    }

    return score;
}

// ── Availability check ──────────────────────────────────────────────────

function isPresetAvailable(preset: PresetAction, context: PresetContext): boolean {
    switch (preset.requiresSelection) {
        case 'track':
            return context.selectedTrackId !== undefined;
        case 'clip':
            return context.selectedClipId !== undefined;
        case 'clipMidi':
            return context.selectedClipId !== undefined && context.selectedClipType === 'midi';
        case 'clipAudio':
            return context.selectedClipId !== undefined && context.selectedClipType === 'audio';
        default:
            return true;
    }
}

/**
 * Pure music-theory helpers used by MIDI pattern templates: scale-pitch
 * generation, snap-to-scale, chord building from scale degrees, and
 * pattern-template filtering.
 *
 * No state, no I/O. Templates and types live in `models/MidiPatternType.ts`;
 * the aggregated catalog lives in `models/midiPatternLibrary.ts`.
 */

import {
    type KeyName,
    type ScaleType,
    type PatternNote,
    type PatternTemplate,
    type PatternFilters,
    KEY_SEMITONES,
    SCALE_INTERVALS,
} from '../models/MidiPatternType';

/** Get MIDI pitches for a scale across a note range */
export function getScalePitches(key: KeyName, scale: ScaleType, low = 36, high = 96): number[] {
    const root = KEY_SEMITONES[key] ?? 0;
    const intervals = SCALE_INTERVALS[scale];
    const pitches: number[] = [];
    for (let midi = low; midi <= high; midi++) {
        if (intervals.includes((midi - root + 120) % 12)) {
            pitches.push(midi);
        }
    }
    return pitches;
}

/** Snap a pitch to the nearest scale tone */
export function snapToScale(pitch: number, scalePitches: number[]): number {
    let best = scalePitches[0]!;
    for (const sp of scalePitches) {
        if (Math.abs(sp - pitch) < Math.abs(best - pitch)) {
            best = sp;
        }
    }
    return best;
}

/**
 * Count how many distinct scale tones fit inside a single octave of a
 * pre-computed `scalePitches` array (diatonic = 7, pentatonic = 5, blues = 6,
 * etc.). Used by {@link chordFromDegrees} to wrap by octave instead of
 * clamping the top index — the old behaviour silently collapsed chord tones
 * that would have landed above the scale range onto the same top pitch.
 */
function detectNotesPerOctave(scalePitches: number[]): number {
    if (scalePitches.length === 0) {
        return 1;
    }
    const first = scalePitches[0]!;
    let count = 0;
    for (const pitch of scalePitches) {
        if (pitch - first >= 12) {
            break;
        }
        count++;
    }
    return count === 0 ? scalePitches.length : count;
}

/** Build chord from scale degrees (0-indexed) at a beat */
export function chordFromDegrees(
    degrees: number[],
    scalePitches: number[],
    octaveBase: number,
    beat: number,
    dur: number,
    vel = 80
): PatternNote[] {
    if (scalePitches.length === 0) {
        return [];
    }
    const notesPerOctave = detectNotesPerOctave(scalePitches);
    return degrees.map((deg) => {
        const absoluteDegree = deg + octaveBase;
        // §14.4 — wrap scale degrees by octave instead of clamping to the top
        // pitch. A chord like `[0, 2, 4, 7]` on a short pentatonic scale near
        // the top of the range used to collapse to four copies of the highest
        // scale tone; now it climbs into the next octave naturally.
        const octavesFromBase = Math.floor(absoluteDegree / notesPerOctave);
        const degreeInOctave = ((absoluteDegree % notesPerOctave) + notesPerOctave) % notesPerOctave;
        const pitch = scalePitches[degreeInOctave]! + 12 * octavesFromBase;
        return { pitch, velocity: vel, startBeat: beat, durationBeats: dur };
    });
}

/** Filter pattern templates by category, genres, tags, and free-text query. */
export function filterTemplates(templates: PatternTemplate[], filters: PatternFilters): PatternTemplate[] {
    return templates.filter((time) => {
        if (filters.category && time.category !== filters.category) {
            return false;
        }
        if (filters.genres && !filters.genres.some((g) => time.genres.includes(g))) {
            return false;
        }
        if (filters.tags && !filters.tags.some((tag) => time.tags.includes(tag))) {
            return false;
        }
        if (filters.query) {
            const query = filters.query.toLowerCase();
            const haystack = [time.name, time.description, ...time.tags, ...time.genres].join(' ').toLowerCase();
            if (!haystack.includes(query)) {
                return false;
            }
        }
        return true;
    });
}

/**
 * Transformers: pure data transformations for mix analysis.
 * No I/O — only derive new data from existing data.
 */

import { type MixIssue, type MixAnalysis } from '../models/MixAnalysis';
import { type FrequencyBands } from '../repositories/mixAnalysis/readFrequencyBalance';

const SILENCE_FLOOR_DB = -100;

// ── Issue Detection ─────────────────────────────────────────────────────

export type DetectIssuesInput = {
    masterLevels: { peakDb: number; rmsDb: number };
    bands: FrequencyBands;
    trackLevels: MixAnalysis['trackLevels'];
};

export function detectIssues({ masterLevels, bands, trackLevels }: DetectIssuesInput): MixIssue[] {
    const issues: MixIssue[] = [];

    for (const tl of trackLevels) {
        if (tl.isClipping) {
            issues.push({
                severity: 'critical',
                category: 'level',
                message: `${tl.trackName} is clipping at ${tl.peakDb.toFixed(1)} dB`,
                trackId: tl.trackId,
            });
        }
    }

    if (masterLevels.peakDb > -3) {
        issues.push({
            severity: 'warning',
            category: 'level',
            message: `Master peak is ${masterLevels.peakDb.toFixed(1)} dB — low headroom`,
        });
    }

    const lowEnergy = (bands.sub + bands.bass) / 2;
    const highEnergy = (bands.mid + bands.high) / 2;
    if (lowEnergy - highEnergy > 6) {
        issues.push({
            severity: 'warning',
            category: 'frequency',
            message: `Mix is muddy — low-end energy exceeds mids/highs by ${(lowEnergy - highEnergy).toFixed(1)} dB`,
        });
    }

    if (bands.highMid - bands.mid > 6) {
        issues.push({
            severity: 'warning',
            category: 'frequency',
            message: `Mix is harsh — high-mid energy exceeds mids by ${(bands.highMid - bands.mid).toFixed(1)} dB`,
        });
    }

    for (const tl of trackLevels) {
        if (tl.isMuted) {
            issues.push({
                severity: 'info',
                category: 'level',
                message: `${tl.trackName} is muted`,
                trackId: tl.trackId,
            });
        }
    }

    const activeTracks = trackLevels.filter(
        (time: MixAnalysis['trackLevels'][number]) => !time.isMuted && time.peakDb > SILENCE_FLOOR_DB
    );
    if (activeTracks.length >= 2) {
        const peaks = activeTracks.map((time: MixAnalysis['trackLevels'][number]) => time.peakDb);
        const maxPeak = Math.max(...peaks);
        const minPeak = Math.min(...peaks);
        if (maxPeak - minPeak > 20) {
            const loudest = activeTracks.find((time: MixAnalysis['trackLevels'][number]) => time.peakDb === maxPeak);
            const quietest = activeTracks.find((time: MixAnalysis['trackLevels'][number]) => time.peakDb === minPeak);
            issues.push({
                severity: 'info',
                category: 'level',
                message: `Track levels differ by ${(maxPeak - minPeak).toFixed(1)} dB (${loudest?.trackName} vs ${quietest?.trackName})`,
            });
        }
    }

    return issues;
}

// ── Suggestion Generation ───────────────────────────────────────────────

export type GenerateSuggestionsInput = {
    masterLevels: { peakDb: number; rmsDb: number };
    bands: FrequencyBands;
    trackLevels: MixAnalysis['trackLevels'];
    issues: MixIssue[];
};

export function generateSuggestions({ masterLevels, bands, trackLevels, issues }: GenerateSuggestionsInput): string[] {
    const suggestions: string[] = [];

    for (const tl of trackLevels) {
        if (tl.isClipping) {
            const overshoot = tl.peakDb + 0.5;
            suggestions.push(`${tl.trackName} is clipping — reduce gain by at least ${overshoot.toFixed(1)} dB`);
        }
    }

    if (masterLevels.peakDb > -3) {
        const reduction = masterLevels.peakDb + 6;
        suggestions.push(
            `Master is hot at ${masterLevels.peakDb.toFixed(1)} dB — reduce by ${reduction.toFixed(1)} dB to leave headroom for mastering`
        );
    }

    const lowEnergy = (bands.sub + bands.bass) / 2;
    const highEnergy = (bands.mid + bands.high) / 2;
    if (lowEnergy - highEnergy > 6) {
        suggestions.push('Consider applying a high-pass filter on non-bass tracks to reduce low-end buildup');
    }

    if (bands.highMid - bands.mid > 6) {
        suggestions.push('Consider a gentle cut around 2–6 kHz on bright tracks to tame harshness');
    }

    if (issues.length === 0) {
        suggestions.push('Mix has good frequency balance and healthy levels');
    }

    return suggestions;
}

/**
 * Transformer: Parse LLM tool call responses.
 * Handles multiple model output formats:
 * - Hermes XML:     <tool_call>{"name":"...","arguments":{...}}</tool_call>
 * - JSON object:    {"actions":[{"name":"...","arguments":{...}}]}
 * - JSON array:     [{"name":"...","arguments":{...}}]
 * - JSONL:          {"name":"...","arguments":{...}}\n{"name":"...","arguments":{...}}
 * - Llama format:   <function>{"name":"...","parameters":{...}}</function>
 */

import { logger } from '#/infra/logger/appLogger';

export type ToolCallResult = {
    name: string;
    arguments: Record<string, unknown>;
};

/**
 * Parse tool calls from model response content.
 * Handles all observed model output formats (see module docstring).
 */
export function parseToolCallXml(content: string): ToolCallResult[] {
    // 1. Try JSON-mode formats first (faster, no XML splitting)
    const jsonResults = tryParseJsonMode(content);
    if (jsonResults.length > 0) {
        return jsonResults;
    }

    // 2. Fall back to XML-based parsing (Hermes / Llama format)
    const results: ToolCallResult[] = [];
    const segments = content.split(/<\/?tool_call>|<\/?function>/);

    for (const segment of segments) {
        const lines = segment.split('\n');

        for (const line of lines) {
            const trimmed = line.trim();
            if (!trimmed.startsWith('{')) {
                continue;
            }
            const parsed = tryParseToolCallJson(trimmed);
            if (parsed) {
                results.push(parsed);
            }
        }
    }

    return results;
}

/**
 * Try to parse JSON-mode responses:
 * - {"actions":[...]} wrapper
 * - Top-level JSON array [...]
 * - Single tool call object {"name":"..."}
 */
function tryParseJsonMode(content: string): ToolCallResult[] {
    const trimmed = content.trim();

    // Try to extract JSON from potential markdown fencing
    const jsonMatch = trimmed.match(/```(?:json)?\s*([\s\S]*?)```/) ?? [null, trimmed];
    const candidate = (jsonMatch[1] ?? trimmed).trim();

    if (!candidate.startsWith('{') && !candidate.startsWith('[')) {
        return [];
    }

    try {
        const parsed = JSON.parse(candidate) as unknown;

        // {"actions":[...]} wrapper
        if (isObject(parsed) && Array.isArray(parsed.actions)) {
            return (parsed.actions as unknown[]).map(coerceToolCall).filter((r): r is ToolCallResult => r !== null);
        }

        // {"tool_calls":[...]} wrapper
        if (isObject(parsed) && Array.isArray(parsed.tool_calls)) {
            return (parsed.tool_calls as unknown[]).map(coerceToolCall).filter((r): r is ToolCallResult => r !== null);
        }

        // Top-level array
        if (Array.isArray(parsed)) {
            return (parsed as unknown[]).map(coerceToolCall).filter((r): r is ToolCallResult => r !== null);
        }

        // Single tool call object
        const single = coerceToolCall(parsed);
        if (single) {
            return [single];
        }
    } catch {
        // Not valid JSON, fall through to XML parsing
    }

    return [];
}

function isObject(val: unknown): val is Record<string, unknown> {
    return typeof val === 'object' && val !== null && !Array.isArray(val);
}

function coerceToolCall(raw: unknown): ToolCallResult | null {
    if (!isObject(raw)) {
        return null;
    }
    const obj = raw;
    const name = obj.name;
    if (typeof name !== 'string' || name.length === 0) {
        return null;
    }
    const args = (obj.arguments ?? obj.parameters ?? {}) as Record<string, unknown>;
    return { name, arguments: args };
}

function tryParseToolCallJson(jsonStr: string | undefined): ToolCallResult | null {
    if (!jsonStr) {
        return null;
    }
    try {
        const parsed = JSON.parse(jsonStr) as unknown;
        return coerceToolCall(parsed);
    } catch {
        logger.warn(`[AI Engine] Failed to parse tool call JSON: ${jsonStr.slice(0, 100)}`);
        return null;
    }
}

