/**
 * DSO Compiler — compiles Domain-Specific Operations into concrete DAW store mutations.
 *
 * Each DSO type maps to specific use case calls. Validation is performed
 * before execution. Human-readable summaries are generated for the action history.
 */
import { logger } from '#/infra/logger/appLogger';
import {
    applyChordProgressionToTrack,
    applyDrumPatternToTrack,
    applyMelodyToTrack,
} from '#/modules/AiGeneration/useCases';
import { trackStore } from '#/modules/Arrangement/stores';
import { addClip, addDevice, addTrack, removeTrack, setSend } from '#/modules/Arrangement/useCases';
import { executeAppAction } from '#/modules/Command/useCases';
import { midiStore } from '#/modules/MIDI/stores';
import { humanizeNotes } from '#/modules/MIDI/useCases';
import { transportStore } from '#/modules/Transport/stores';
import { disableLooping, setLoopRegion } from '#/modules/Transport/useCases';

import { type Dso } from '../../models/DsoTypes';

// Shared style unions live in `AiGeneration/models/GenerationStyles` — a leaf
// module with no runtime imports. Using `import type` keeps this file free of
// any runtime dependency on `AiGeneration/useCases`, which would otherwise
// close a module-init circular dependency. The unions are the single source
// of truth for both the algorithms in `AiGeneration` and the Record-based
// lookup maps below.
import type {
    ChordProgressionStyle,
    ChordVoicing,
    DrumPatternStyle,
    MelodyStyle,
    ScaleType,
} from '#/modules/AiGeneration/models/GenerationStyles';

// ── Safe enum mapping ────────────────────────────────────────────────────────

const NOTE_NAME_TO_MIDI: Record<string, number> = {
    C: 60,
    'C#': 61,
    Db: 61,
    D: 62,
    'D#': 63,
    Eb: 63,
    E: 64,
    F: 65,
    'F#': 66,
    Gb: 66,
    G: 67,
    'G#': 68,
    Ab: 68,
    A: 69,
    'A#': 70,
    Bb: 70,
    B: 71,
};

function noteNameToMidi(name: string): number {
    return NOTE_NAME_TO_MIDI[name] ?? NOTE_NAME_TO_MIDI[name.charAt(0).toUpperCase() + name.slice(1)] ?? 60;
}

// Record-based lookups — values are typed literals, keys are strings the LLM might produce.
// No casts needed: the Record values ARE the correct types.

const MELODY_STYLE_MAP: Record<string, MelodyStyle> = {
    simple: 'simple',
    arpeggiated: 'arpeggiated',
    stepwise: 'stepwise',
    rhythmic: 'rhythmic',
    ambient: 'ambient',
};

const SCALE_MAP: Record<string, ScaleType> = {
    major: 'major',
    minor: 'minor',
    pentatonic: 'pentatonic',
    'minor-pentatonic': 'minor-pentatonic',
    blues: 'blues',
    dorian: 'dorian',
    mixolydian: 'mixolydian',
    lydian: 'lydian',
    phrygian: 'phrygian',
    locrian: 'locrian',
    'harmonic-minor': 'harmonic-minor',
    'melodic-minor': 'melodic-minor',
    'whole-tone': 'whole-tone',
    chromatic: 'chromatic',
};

const CHORD_STYLE_MAP: Record<string, ChordProgressionStyle> = {
    pop: 'pop',
    jazz: 'jazz',
    classical: 'classical',
    edm: 'edm',
    blues: 'blues',
    rnb: 'rnb',
    folk: 'folk',
    cinematic: 'cinematic',
    'neo-soul': 'neo-soul',
    gospel: 'gospel',
    rock: 'rock',
    lofi: 'lofi',
    // Common LLM aliases
    'I-IV-V-I': 'blues',
    'I-V-vi-IV': 'pop',
    'ii-V-I': 'jazz',
    'I-vi-IV-V': 'pop',
    '12-bar-blues': 'blues',
};

const CHORD_VOICING_MAP: Record<string, ChordVoicing> = {
    close: 'close',
    open: 'open',
    spread: 'spread',
    power: 'power',
    basic: 'close',
    drop2: 'open',
};

const DRUM_STYLE_MAP: Record<string, DrumPatternStyle> = {
    rock: 'rock',
    pop: 'four-on-floor',
    hiphop: 'trap',
    jazz: 'jazz',
    blues: 'blues',
    electronic: 'four-on-floor',
    latin: 'latin',
    funk: 'breakbeat',
    'four-on-floor': 'four-on-floor',
    breakbeat: 'breakbeat',
    trap: 'trap',
    dnb: 'dnb',
    'half-time': 'half-time',
    reggae: 'reggae',
    lofi: 'lofi',
    house: 'house',
    techno: 'techno',
    synthwave: 'synthwave',
    afrobeat: 'afrobeat',
    metal: 'metal',
    punk: 'punk',
};

function toMelodyStyle(state: string): MelodyStyle {
    return MELODY_STYLE_MAP[state.toLowerCase()] ?? 'simple';
}

function toScaleType(state: string): ScaleType {
    return SCALE_MAP[state.toLowerCase()] ?? 'major';
}

function toChordStyle(state: string): ChordProgressionStyle {
    return CHORD_STYLE_MAP[state] ?? CHORD_STYLE_MAP[state.toLowerCase()] ?? 'pop';
}

function toChordVoicing(state: string): ChordVoicing {
    return CHORD_VOICING_MAP[state.toLowerCase()] ?? 'close';
}

function toDrumStyle(state: string): DrumPatternStyle {
    return DRUM_STYLE_MAP[state.toLowerCase()] ?? 'rock';
}

/**
 * Per-execution context for a single `executeDsos()` call.
 * Tracks the ID of the most recently inserted device so that the LLM's
 * `device_id: "latest"` sentinel can be resolved to a concrete ID.
 *
 * Held in a local variable inside `executeDsos()` rather than at module
 * scope so concurrent plan executions (e.g. an AI chat response that
 * triggers while a prior AI edit is still mid-execution) cannot clobber
 * each other's in-flight device references.
 */
type DsoExecContext = {
    lastInsertedDeviceId: string | null;
};

// ── Name resolution ──────────────────────────────────────────────────────────
// The LLM outputs human-readable names (e.g. "Drums", "Vocal Clip").
// We resolve them to actual store IDs before validation and execution.

// ── Fuzzy name matching ──────────────────────────────────────────────────────

/**
 * Score how well `query` matches `candidate` (0 = no match, higher = better).
 * Handles typos, partial matches, and case differences.
 */
function fuzzyScore(query: string, candidate: string): number {
    const query1 = query.toLowerCase();
    const context = candidate.toLowerCase();

    // Exact match
    if (query1 === context) {
        return 100;
    }

    // Candidate contains query as substring
    if (context.includes(query1)) {
        return 80;
    }

    // Query contains candidate
    if (query1.includes(context)) {
        return 70;
    }

    // Token overlap (handles "drum bus" matching "Drum Bus Send")
    const qTokens = query1.split(/[\s_-]+/);
    const cTokens = context.split(/[\s_-]+/);
    let tokenHits = 0;
    for (const qt of qTokens) {
        if (qt.length < 2) {
            continue;
        }
        if (cTokens.some((ct) => ct.includes(qt) || qt.includes(ct))) {
            tokenHits++;
        }
    }
    if (tokenHits > 0) {
        return 40 + (tokenHits / Math.max(qTokens.length, 1)) * 30;
    }

    // Levenshtein-based typo tolerance (only for short strings to avoid expense)
    if (query1.length <= 15 && context.length <= 20) {
        const dist = levenshtein(query1, context);
        const maxLen = Math.max(query1.length, context.length);
        const similarity = 1 - dist / maxLen;
        if (similarity > 0.6) {
            return similarity * 50;
        }
    }

    return 0;
}

function levenshtein(alpha: string, b: string): number {
    const message = alpha.length;
    const node = b.length;
    const dp: number[][] = Array.from({ length: message + 1 }, (_, index) =>
        Array.from({ length: node + 1 }, (_, jIndex) => {
            if (index === 0) {
                return jIndex;
            }
            if (jIndex === 0) {
                return index;
            }
            return 0;
        })
    );
    for (let index = 1; index <= message; index++) {
        for (let jIndex = 1; jIndex <= node; jIndex++) {
            dp[index]![jIndex] =
                alpha[index - 1] === b[jIndex - 1]
                    ? dp[index - 1]![jIndex - 1]!
                    : 1 + Math.min(dp[index - 1]![jIndex]!, dp[index]![jIndex - 1]!, dp[index - 1]![jIndex - 1]!);
        }
    }
    return dp[message]![node]!;
}

function bestMatch<T>(query: string, items: T[], getName: (item: T) => string, threshold = 30): T | null {
    let best: T | null = null;
    let bestScore = 0;
    for (const item of items) {
        const score = fuzzyScore(query, getName(item));
        if (score > bestScore && score >= threshold) {
            best = item;
            bestScore = score;
        }
    }
    return best;
}

// ── Name resolution ──────────────────────────────────────────────────────────

/**
 * Resolve name-based references in DSOs to actual store IDs.
 * Uses fuzzy matching to handle typos and partial names.
 * Mutates the DSO objects in-place.
 * Returns unresolved names as errors.
 */
export function resolveDsoNames(dsos: Dso[]): DsoValidationError[] {
    const state = trackStore.value;
    if (!state) {
        return [];
    }

    const errors: DsoValidationError[] = [];
    const allClips = state.tracks.flatMap((time) => time.clips);
    const allDevices = state.tracks.flatMap((time) => time.devices);

    // Keep track of dynamically created tracks during this resolve pass
    const mockTracks: { id: string; name: string }[] = [];

    function findTrackId(nameOrId: string): string | null {
        if (state!.tracks.some((time) => time.id === nameOrId)) {
            return nameOrId;
        }
        if (mockTracks.some((time) => time.id === nameOrId)) {
            return nameOrId;
        }

        let match = bestMatch(nameOrId, state!.tracks, (time) => time.name);
        if (!match) {
            match = bestMatch(nameOrId, mockTracks, (time) => time.name) as any;
        }
        return match?.id ?? null;
    }

    function findClipId(nameOrId: string): string | null {
        if (allClips.some((context) => context.id === nameOrId)) {
            return nameOrId;
        }
        const match = bestMatch(nameOrId, allClips, (context) => context.name);
        return match?.id ?? null;
    }

    function findDeviceId(nameOrId: string): string | null {
        if (nameOrId === 'latest') {
            return 'latest';
        }
        if (allDevices.some((data) => data.id === nameOrId)) {
            return nameOrId;
        }
        const match = bestMatch(nameOrId, allDevices, (data) => data.type);
        return match?.id ?? null;
    }

    let index = 0;
    while (index < dsos.length) {
        const dso = dsos[index]!;

        // Resolve track_id fields
        if ('track_id' in dso && typeof dso.track_id === 'string') {
            const resolved = findTrackId(dso.track_id);
            if (resolved) {
                (dso as Record<string, unknown>).track_id = resolved;
            } else if (!['add_track'].includes(dso.op)) {
                // Check if the LLM meant the selected track
                const selectedTrackId = state.selectedTrackId;
                const selectedTrack = selectedTrackId ? state.tracks.find((time) => time.id === selectedTrackId) : null;
                const lowerName = dso.track_id.toLowerCase();
                const isSelectedRef =
                    lowerName.includes('selected') || lowerName.includes('current') || lowerName.includes('this');

                if (isSelectedRef && selectedTrack) {
                    // Resolve to the actually selected track
                    (dso as Record<string, unknown>).track_id = selectedTrack.id;
                } else {
                    // Fallback: auto-create this track
                    const newId = `track-${crypto.randomUUID().slice(0, 8)}`;
                    const kindFallback =
                        dso.op === 'generate_drums' || lowerName.includes('drum') || lowerName.includes('midi')
                            ? 'midi'
                            : 'audio';

                    dsos.splice(index, 0, {
                        op: 'add_track',
                        name: dso.track_id,
                        kind: kindFallback as any,
                        track_id: newId,
                    } as any);

                    mockTracks.push({ id: newId, name: dso.track_id });
                    (dso as Record<string, unknown>).track_id = newId;
                    index++;
                }
            }
        }

        // Resolve destination_track_id
        if ('destination_track_id' in dso && typeof dso.destination_track_id === 'string') {
            const resolved = findTrackId(dso.destination_track_id);
            if (resolved) {
                (dso as Record<string, unknown>).destination_track_id = resolved;
            } else {
                errors.push({ dso, reason: `Could not find destination track "${dso.destination_track_id}"` });
            }
        }

        // Resolve from_track_id / to_track_id
        if ('from_track_id' in dso && typeof dso.from_track_id === 'string') {
            const resolved = findTrackId(dso.from_track_id);
            if (resolved) {
                (dso as Record<string, unknown>).from_track_id = resolved;
            } else {
                errors.push({ dso, reason: `Could not find source track "${dso.from_track_id}"` });
            }
        }
        if ('to_track_id' in dso && typeof dso.to_track_id === 'string') {
            const resolved = findTrackId(dso.to_track_id);
            if (resolved) {
                (dso as Record<string, unknown>).to_track_id = resolved;
            } else {
                errors.push({ dso, reason: `Could not find target track "${dso.to_track_id}"` });
            }
        }

        // Resolve clip_id fields
        if ('clip_id' in dso && typeof dso.clip_id === 'string') {
            const resolved = findClipId(dso.clip_id);
            if (resolved) {
                (dso as Record<string, unknown>).clip_id = resolved;
            } else {
                errors.push({ dso, reason: `Could not find clip "${dso.clip_id}"` });
            }
        }

        // Resolve device_id fields
        if ('device_id' in dso && typeof dso.device_id === 'string') {
            const resolved = findDeviceId(dso.device_id);
            if (resolved) {
                (dso as Record<string, unknown>).device_id = resolved;
            } else {
                errors.push({ dso, reason: `Could not find device "${dso.device_id}"` });
            }
        }

        index++;
    }

    return errors;
}

// ── Validation ───────────────────────────────────────────────────────────────

export type DsoValidationError = {
    dso: Dso;
    reason: string;
};

export function validateDsos(dsos: Dso[]): DsoValidationError[] {
    const errors: DsoValidationError[] = [];
    const state = trackStore.value;
    const trackIds = new Set(state?.tracks.map((time) => time.id) ?? []);
    const clipIds = new Set(state?.tracks.flatMap((time) => time.clips.map((context) => context.id)) ?? []);
    const deviceIds = new Set(state?.tracks.flatMap((time) => time.devices.map((data) => data.id)) ?? []);

    // Pre-register IDs injected by resolveDsoNames for add_track DSOs so that
    // subsequent DSOs in the same batch that target those new tracks are not
    // incorrectly rejected (the store hasn't been updated yet at validation time).
    for (const dso of dsos) {
        if (dso.op === 'add_track') {
            const injectedId = (dso as Record<string, unknown>).track_id;
            if (typeof injectedId === 'string') {
                trackIds.add(injectedId);
            }
        }
    }

    for (const dso of dsos) {
        switch (dso.op) {
            case 'remove_track':
            case 'rename_track':
            case 'set_track_volume':
            case 'set_track_pan':
            case 'mute_track':
            case 'solo_track':
            case 'arm_track':
            case 'color_track':
            case 'reorder_track':
                if (!trackIds.has(dso.track_id)) {
                    errors.push({ dso, reason: `Track "${dso.track_id}" does not exist` });
                }
                break;

            case 'insert_device':
                if (!trackIds.has(dso.track_id)) {
                    errors.push({ dso, reason: `Track "${dso.track_id}" does not exist` });
                }
                break;

            case 'add_clip':
                if (!trackIds.has(dso.track_id)) {
                    errors.push({ dso, reason: `Track "${dso.track_id}" does not exist` });
                }
                if (dso.end_beats <= dso.start_beats) {
                    errors.push({ dso, reason: `Clip end must be after start` });
                }
                break;

            case 'remove_clip':
            case 'rename_clip':
            case 'split_clip':
            case 'transpose_notes':
            case 'humanize_midi':
                if (!clipIds.has(dso.clip_id)) {
                    errors.push({ dso, reason: `Clip "${dso.clip_id}" does not exist` });
                }
                break;

            case 'move_clip':
            case 'duplicate_clip':
                if (!clipIds.has(dso.clip_id)) {
                    errors.push({ dso, reason: `Clip "${dso.clip_id}" does not exist` });
                }
                if (!trackIds.has(dso.destination_track_id)) {
                    errors.push({ dso, reason: `Destination track "${dso.destination_track_id}" does not exist` });
                }
                break;

            case 'remove_device':
            case 'bypass_device':
                if (!deviceIds.has(dso.device_id)) {
                    errors.push({ dso, reason: `Device "${dso.device_id}" does not exist` });
                }
                break;

            case 'set_tempo':
                if (dso.bpm < 20 || dso.bpm > 999) {
                    errors.push({ dso, reason: `Tempo ${dso.bpm} out of range (20-999)` });
                }
                break;

            case 'set_track_volume':
                if (dso.gain < 0 || dso.gain > 1.5) {
                    errors.push({ dso, reason: `Gain ${dso.gain} out of range (0-1.5)` });
                }
                break;

            case 'set_track_pan':
                if (dso.pan < -50 || dso.pan > 50) {
                    errors.push({ dso, reason: `Pan ${dso.pan} out of range (-50 to 50)` });
                }
                break;

            case 'create_send':
                if (!trackIds.has(dso.from_track_id)) {
                    errors.push({ dso, reason: `Source track "${dso.from_track_id}" does not exist` });
                }
                if (!trackIds.has(dso.to_track_id)) {
                    errors.push({ dso, reason: `Destination track "${dso.to_track_id}" does not exist` });
                }
                break;

            case 'set_device_param':
                if (dso.device_id !== 'latest' && !deviceIds.has(dso.device_id)) {
                    errors.push({ dso, reason: `Device "${dso.device_id}" does not exist` });
                }
                break;

            case 'add_midi_notes':
                if (!clipIds.has(dso.clip_id)) {
                    errors.push({ dso, reason: `Clip "${dso.clip_id}" does not exist` });
                }
                for (let index = 0; index < dso.notes.length; index++) {
                    const node = dso.notes[index]!;
                    if (node.pitch < 0 || node.pitch > 127) {
                        errors.push({ dso, reason: `Note ${index} pitch ${node.pitch} out of range (0-127)` });
                    }
                    if (node.velocity < 0 || node.velocity > 127) {
                        errors.push({ dso, reason: `Note ${index} velocity ${node.velocity} out of range (0-127)` });
                    }
                }
                break;

            case 'set_clip_gain':
                if (!clipIds.has(dso.clip_id)) {
                    errors.push({ dso, reason: `Clip "${dso.clip_id}" does not exist` });
                }
                if (dso.gain < 0 || dso.gain > 2) {
                    errors.push({ dso, reason: `Clip gain ${dso.gain} out of range (0-2)` });
                }
                break;

            case 'generate_melody':
            case 'generate_chords':
            case 'generate_drums':
                if (!trackIds.has(dso.track_id)) {
                    errors.push({ dso, reason: `Track "${dso.track_id}" does not exist` });
                }
                break;
        }
    }

    return errors;
}

// ── Compilation (execution) ──────────────────────────────────────────────────

/** Options passed to executeAppAction for all DSO sub-operations.
 *  skipUndo: the batch undo entry is managed by executeDsoEdit, not per-operation. */
const DSO_EXEC_OPTIONS = { skipUndo: true, source: 'ai' as const };

async function executeSingleDso(dso: Dso, context: DsoExecContext): Promise<void> {
    const state = trackStore.value;
    if (!state) {
        return;
    }

    switch (dso.op) {
        case 'add_track': {
            addTrack({
                id: (dso as any).track_id,
                name: dso.name,
                kind: dso.kind as 'audio' | 'midi' | 'bus' | 'master',
            });
            break;
        }

        case 'remove_track': {
            removeTrack(dso.track_id);
            break;
        }

        case 'rename_track': {
            await executeAppAction(
                { type: 'renameTrack', payload: { trackId: dso.track_id, name: dso.name } },
                DSO_EXEC_OPTIONS
            );
            break;
        }

        case 'set_track_volume': {
            await executeAppAction(
                { type: 'setTrackGain', payload: { trackId: dso.track_id, gain: dso.gain } },
                DSO_EXEC_OPTIONS
            );
            break;
        }

        case 'set_track_pan': {
            await executeAppAction(
                { type: 'setTrackPan', payload: { trackId: dso.track_id, pan: dso.pan } },
                DSO_EXEC_OPTIONS
            );
            break;
        }

        case 'mute_track': {
            await executeAppAction(
                { type: 'muteTrack', payload: { trackId: dso.track_id, muted: dso.muted } },
                DSO_EXEC_OPTIONS
            );
            break;
        }

        case 'solo_track': {
            await executeAppAction(
                { type: 'soloTrack', payload: { trackId: dso.track_id, soloed: dso.soloed } },
                DSO_EXEC_OPTIONS
            );
            break;
        }

        case 'arm_track': {
            await executeAppAction(
                { type: 'armTrack', payload: { trackId: dso.track_id, armed: dso.armed } },
                DSO_EXEC_OPTIONS
            );
            break;
        }

        case 'color_track': {
            await executeAppAction(
                { type: 'setTrackColor', payload: { trackId: dso.track_id, color: dso.color } },
                DSO_EXEC_OPTIONS
            );
            break;
        }

        case 'reorder_track': {
            await executeAppAction(
                { type: 'reorderTrack', payload: { trackId: dso.track_id, newIndex: dso.new_index } },
                DSO_EXEC_OPTIONS
            );
            break;
        }

        case 'add_clip': {
            addClip({
                trackId: dso.track_id,
                name: dso.name,
                type: dso.type,
                startBeat: dso.start_beats,
                endBeat: dso.end_beats,
            });
            break;
        }

        case 'remove_clip': {
            await executeAppAction({ type: 'removeClip', payload: { clipId: dso.clip_id } }, DSO_EXEC_OPTIONS);
            break;
        }

        case 'rename_clip': {
            await executeAppAction(
                { type: 'renameClip', payload: { clipId: dso.clip_id, name: dso.name } },
                DSO_EXEC_OPTIONS
            );
            break;
        }

        case 'move_clip': {
            await executeAppAction(
                {
                    type: 'moveClip',
                    payload: {
                        clipId: dso.clip_id,
                        trackId: dso.destination_track_id,
                        startBeat: dso.destination_start_beats,
                    },
                },
                DSO_EXEC_OPTIONS
            );
            break;
        }

        case 'duplicate_clip': {
            const allClips = state.tracks.flatMap((time) => time.clips);
            const sourceClip = allClips.find((context1) => context1.id === dso.clip_id);
            if (sourceClip) {
                const duration = sourceClip.endBeat - sourceClip.startBeat;
                addClip({
                    trackId: dso.destination_track_id,
                    name: `${sourceClip.name} (copy)`,
                    type: sourceClip.type ?? 'audio',
                    startBeat: dso.destination_start_beats,
                    endBeat: dso.destination_start_beats + duration,
                    audioBufferId: sourceClip.audioBufferId,
                });
            }
            break;
        }

        case 'split_clip': {
            await executeAppAction(
                { type: 'splitClip', payload: { clipId: dso.clip_id, beat: dso.split_at_beats } },
                DSO_EXEC_OPTIONS
            );
            break;
        }

        case 'insert_device': {
            // Capture device count before adding so we can find the new one
            const track = state.tracks.find((time) => time.id === dso.track_id);
            const deviceCountBefore = track?.devices.length ?? 0;

            addDevice(dso.track_id, dso.device_type);

            // Track the newly inserted device ID for "latest" resolution
            const updatedState = trackStore.value;
            const updatedTrack = updatedState?.tracks.find((time) => time.id === dso.track_id);
            if (updatedTrack && updatedTrack.devices.length > deviceCountBefore) {
                const newDevice = updatedTrack.devices[updatedTrack.devices.length - 1];
                if (newDevice) {
                    context.lastInsertedDeviceId = newDevice.id;
                }
            }
            break;
        }

        case 'remove_device': {
            await executeAppAction({ type: 'removeDevice', payload: { deviceId: dso.device_id } }, DSO_EXEC_OPTIONS);
            break;
        }

        case 'bypass_device': {
            await executeAppAction(
                { type: 'bypassDevice', payload: { deviceId: dso.device_id, bypassed: dso.bypassed } },
                DSO_EXEC_OPTIONS
            );
            break;
        }

        case 'set_tempo': {
            await executeAppAction(
                { type: 'setTempo', payload: { bpm: Math.max(20, Math.min(999, dso.bpm)) } },
                DSO_EXEC_OPTIONS
            );
            break;
        }

        case 'set_time_signature': {
            const ts = transportStore.value;
            if (ts) {
                transportStore.set({
                    ...ts,
                    timeSignatureNumerator: Math.max(1, Math.min(32, dso.numerator)),
                    timeSignatureDenominator: Math.max(1, Math.min(32, dso.denominator)),
                });
            }
            break;
        }

        case 'set_loop': {
            if (dso.enabled) {
                setLoopRegion(dso.start_beats, dso.end_beats);
            } else {
                disableLooping();
            }
            break;
        }

        case 'set_device_param': {
            // Resolve "latest" to the tracked ID from the most recent insert_device in this plan
            const resolvedId = dso.device_id === 'latest' ? context.lastInsertedDeviceId : dso.device_id;
            if (!resolvedId) {
                break;
            }
            await executeAppAction(
                {
                    type: 'setDeviceParameter',
                    payload: { deviceId: resolvedId, paramId: dso.param_name, value: dso.value },
                },
                DSO_EXEC_OPTIONS
            );
            break;
        }

        case 'add_midi_notes': {
            const ms = midiStore.value;
            if (ms) {
                // Find the clip's start beat so we can offset relative note positions to absolute
                const clip = state.tracks.flatMap((time) => time.clips).find((context1) => context1.id === dso.clip_id);
                const clipStartBeat = clip?.startBeat ?? 0;

                const existing = ms.notesByClipId[dso.clip_id] ?? [];
                const newNotes = dso.notes.map(
                    (
                        node: { pitch: number; start_beat: number; duration: number; velocity: number },
                        index: number
                    ) => ({
                        id: `note-ai-${Date.now()}-${index}`,
                        pitch: Math.max(0, Math.min(127, node.pitch)),
                        startBeat: Math.max(0, clipStartBeat + node.start_beat),
                        duration: Math.max(0.01, node.duration),
                        velocity: Math.max(1, Math.min(127, node.velocity)),
                    })
                );
                midiStore.set({
                    ...ms,
                    notesByClipId: {
                        ...ms.notesByClipId,
                        [dso.clip_id]: [...existing, ...newNotes],
                    },
                });
            }
            break;
        }

        case 'set_clip_gain': {
            await executeAppAction(
                { type: 'setClipGain', payload: { clipId: dso.clip_id, gain: dso.gain } },
                DSO_EXEC_OPTIONS
            );
            break;
        }

        case 'generate_melody': {
            const key = noteNameToMidi(dso.key);
            const scale = toScaleType(dso.scale);
            const style = toMelodyStyle(dso.style);
            applyMelodyToTrack(
                dso.track_id,
                { style, key, scale, octave: dso.octave, bars: dso.bars, density: dso.density },
                dso.start_beat ?? 0
            );
            break;
        }

        case 'generate_chords': {
            const key = noteNameToMidi(dso.key);
            const style = toChordStyle(dso.progression);
            const voicing = toChordVoicing(dso.voicing);
            applyChordProgressionToTrack(
                dso.track_id,
                { style, key, scale: 'major', bars: dso.bars, voicing },
                dso.start_beat ?? 0
            );
            break;
        }

        case 'generate_drums': {
            const style = toDrumStyle(dso.style);
            applyDrumPatternToTrack(dso.track_id, { style, bars: dso.bars, density: dso.density }, dso.start_beat ?? 0);
            break;
        }

        case 'transpose_notes': {
            await executeAppAction(
                { type: 'transposeNotes', payload: { clipId: dso.clip_id, semitones: dso.semitones } },
                DSO_EXEC_OPTIONS
            );
            break;
        }

        case 'humanize_midi': {
            humanizeNotes(dso.clip_id, dso.timing_amount, dso.velocity_amount);
            break;
        }

        case 'create_send': {
            setSend(dso.from_track_id, dso.to_track_id, dso.gain);
            break;
        }
    }
}

/**
 * Execute a list of validated DSOs against the DAW stores.
 * Returns human-readable summaries of each applied operation.
 */
export async function executeDsos(dsos: Dso[]): Promise<string[]> {
    const context: DsoExecContext = { lastInsertedDeviceId: null };
    const summaries: string[] = [];

    for (const dso of dsos) {
        try {
            await executeSingleDso(dso, context);
            summaries.push(describeDso(dso));
        } catch (error) {
            logger.warn(`Failed to execute DSO ${dso.op}:`, error);
        }
    }

    return summaries;
}

// ── Human-readable summaries ─────────────────────────────────────────────────

function describeDso(dso: Dso): string {
    switch (dso.op) {
        case 'add_track':
            return `Added ${dso.kind} track "${dso.name}"`;
        case 'remove_track':
            return `Removed track`;
        case 'rename_track':
            return `Renamed track to "${dso.name}"`;
        case 'set_track_volume':
            return `Set volume to ${(dso.gain * 100).toFixed(0)}%`;
        case 'set_track_pan':
            return `Set pan to ${dso.pan}`;
        case 'mute_track':
            return dso.muted ? `Muted track` : `Unmuted track`;
        case 'solo_track':
            return dso.soloed ? `Soloed track` : `Unsoloed track`;
        case 'arm_track':
            return dso.armed ? `Armed track` : `Disarmed track`;
        case 'color_track':
            return `Colored track ${dso.color}`;
        case 'reorder_track':
            return `Moved track to position ${dso.new_index}`;
        case 'add_clip':
            return `Added ${dso.type} clip "${dso.name}" at beat ${dso.start_beats}`;
        case 'remove_clip':
            return `Removed clip`;
        case 'rename_clip':
            return `Renamed clip to "${dso.name}"`;
        case 'move_clip':
            return `Moved clip to beat ${dso.destination_start_beats}`;
        case 'duplicate_clip':
            return `Duplicated clip to beat ${dso.destination_start_beats}`;
        case 'split_clip':
            return `Split clip at beat ${dso.split_at_beats}`;
        case 'insert_device':
            return `Added ${dso.device_type}`;
        case 'remove_device':
            return `Removed device`;
        case 'bypass_device':
            return dso.bypassed ? `Bypassed device` : `Enabled device`;
        case 'set_tempo':
            return `Set tempo to ${dso.bpm} BPM`;
        case 'set_time_signature':
            return `Set time signature to ${dso.numerator}/${dso.denominator}`;
        case 'set_loop':
            return dso.enabled ? `Set loop ${dso.start_beats}–${dso.end_beats}` : `Disabled loop`;
        case 'transpose_notes':
            return `Transposed notes ${dso.semitones > 0 ? '+' : ''}${dso.semitones} semitones`;
        case 'humanize_midi':
            return `Humanized MIDI`;
        case 'create_send':
            return `Created send`;
        case 'set_device_param':
            return `Set ${dso.param_name} to ${dso.value}`;
        case 'add_midi_notes':
            return `Added ${dso.notes.length} MIDI note${dso.notes.length !== 1 ? 's' : ''}`;
        case 'set_clip_gain':
            return `Set clip gain to ${(dso.gain * 100).toFixed(0)}%`;
        case 'generate_melody':
            return `Generated ${dso.bars}-bar melody in ${dso.key} ${dso.scale}`;
        case 'generate_chords':
            return `Generated ${dso.bars}-bar ${dso.progression} chord progression in ${dso.key}`;
        case 'generate_drums':
            return `Generated ${dso.bars}-bar ${dso.style} drum pattern`;
        default:
            return `Unknown operation`;
    }
}

/**
 * DSO Edit Orchestrator — single entrypoint for LLM-driven DAW editing.
 *
 * Lifecycle:
 * 1. Serialize logical state (EASE-encoded)
 * 2. Build prompt with project summary + few-shot examples
 * 3. Invoke LLM with schema constraint (Constraint::JsonSchema)
 * 4. Stream response with progressive UI updates
 * 5. Parse EditPlan from response
 * 6. Handle moderation / empty-plan early exits
 * 7. Resolve LLM-emitted names to store IDs
 * 8. Validate DSOs against current state
 * 9. Classify safety (auto-apply / preview / confirmation)
 * 10. Execute with full undo support
 */
import { inject } from '#/infra/di/inject';
import { logger } from '#/infra/logger/appLogger';
import { commitUndoEntry, createUndoEntry, generateGroupId } from '#/modules/Command/useCases';
import { saveSnapshot } from '#/modules/CrdtDocument/useCases';
import { isTauri, tauriInvoke } from '#/utils/tauriBridge';

import { createAiRuntimeError } from '../../errors/AiRuntimeError';
import { type Dso, type EditPlan, EDIT_PLAN_JSON_SCHEMA, classifyEditPlan } from '../../models/DsoTypes';
import { isNativeEngineReady } from '../../repositories/nativeEngine/lifecycle';
import { streamNativeCompletion } from '../../repositories/nativeEngine/streaming';
import { getActiveModelId, getLlmEngine } from '../../repositories/webLlm/engineLifecycle';
import { pushAiActionGroup } from '../../stores/aiActionHistoryStore';
import { appendChatMessage, updateChatMessage, setChatGenerating } from '../../stores/chatStore';
import { llmStatusStore } from '../../stores/llmStatusStore';
import { resolveBackend } from '../llmOrchestration/backendResolution/helpers';
import { isDsoBackendAvailable } from '../llmOrchestration/backendResolution/isDsoBackendAvailable';

import { resolveDsoNames, validateDsos, executeDsos } from './compileDso';
import { buildDsoPrompt } from './dsoPrompt';
import { serializeLogicalState, buildProjectSummary, logEdit } from './serializeLogicalState';

type ExecuteDsosFn = (dsos: Dso[]) => Promise<string[]>;

export type DsoEditResult = {
    success: boolean;
    plan: EditPlan | null;
    summaries: string[];
    error?: string;
};

/**
 * Execute a DSO edit request — the single orchestration entrypoint.
 */
export const executeDsoEdit = inject({ logger })(
    ({ logger }) =>
        async function executeDsoEdit(userRequest: string): Promise<DsoEditResult> {
            const backend = resolveBackend();

            if (!isDsoBackendAvailable()) {
                return {
                    success: false,
                    plan: null,
                    summaries: [],
                    error: 'No DSO-capable backend available (Qwen3-8B required)',
                };
            }

            // 1. Serialize logical state
            const logicalState = serializeLogicalState({ includeNoteCount: true });
            const summary = buildProjectSummary();

            // 2. Build prompt
            const { system, user } = buildDsoPrompt(logicalState, userRequest, summary);

            // 3. Chat UI messages
            appendChatMessage({
                id: `msg-${crypto.randomUUID()}`,
                role: 'user',
                content: userRequest,
                timestamp: Date.now(),
            });

            const assistantMsgId = `msg-${crypto.randomUUID()}`;
            appendChatMessage({
                id: assistantMsgId,
                role: 'assistant',
                content: 'Planning edit...',
                timestamp: Date.now(),
                isStreaming: true,
            });

            setChatGenerating(true);
            llmStatusStore.set({ state: 'generating' });

            try {
                // 4. Invoke LLM — schema-constrained for native, regular for others
                const rawResponse = await invokeLlm(backend, system, user, assistantMsgId);

                // 5. Extract reasoning tokens (Qwen3 uses <think>...</think>) and parse EditPlan
                const { reasoning, cleanResponse } = extractReasoning(rawResponse);
                const plan = parseEditPlan(cleanResponse);

                // 6. Handle moderation
                if (plan.moderation === 'block') {
                    updateChatMessage(assistantMsgId, {
                        content: `Cannot do that: ${plan.intent}`,
                        isStreaming: false,
                        reasoning,
                        isDsoAction: true,
                    });
                    finish();
                    return { success: true, plan, summaries: [] };
                }

                if (plan.dsos.length === 0) {
                    updateChatMessage(assistantMsgId, {
                        content: plan.intent || 'No changes needed.',
                        isStreaming: false,
                        reasoning,
                        isDsoAction: true,
                    });
                    finish();
                    return { success: true, plan, summaries: [] };
                }

                // 7. Resolve names to IDs (LLM outputs human names, we look up the real IDs)
                const resolutionErrors = resolveDsoNames(plan.dsos);
                if (resolutionErrors.length > 0) {
                    const errorText = resolutionErrors.map((event) => event.reason).join('; ');
                    updateChatMessage(assistantMsgId, {
                        content: `Could not resolve references: ${errorText}`,
                        isStreaming: false,
                        error: errorText,
                        reasoning,
                        isDsoAction: true,
                    });
                    finish();
                    return { success: false, plan, summaries: [], error: errorText };
                }

                // 8. Validate DSOs (now with resolved IDs)
                const validationErrors = validateDsos(plan.dsos);
                if (validationErrors.length > 0) {
                    const errorText = validationErrors.map((event) => event.reason).join('; ');
                    updateChatMessage(assistantMsgId, {
                        content: `Edit rejected — ${errorText}`,
                        isStreaming: false,
                        error: errorText,
                    });
                    finish();
                    return { success: false, plan, summaries: [], error: errorText };
                }

                // 9. Classify and execute
                const classification = classifyEditPlan(plan);

                if (classification === 'confirmation_required') {
                    const summaries = await commitDsos(plan, userRequest, assistantMsgId, reasoning, executeDsos);
                    const descriptions = plan.dsos
                        .filter((data) => data.op.startsWith('remove'))
                        .map((data) => data.op.replaceAll('_', ' '));
                    updateChatMessage(assistantMsgId, {
                        content: `Done (destructive): ${summaries.join('. ')}.\n\nRemoved: ${descriptions.join(', ')}. Use Ctrl+Z to undo.`,
                        isStreaming: false,
                        reasoning,
                        isDsoAction: true,
                    });
                    finish();
                    return { success: true, plan, summaries };
                }

                // 10. Execute with undo support
                const summaries = await commitDsos(plan, userRequest, assistantMsgId, reasoning, executeDsos);

                finish();
                return { success: true, plan, summaries };
            } catch (error) {
                const err = error instanceof Error ? error : new Error(String(error));
                logger.error(err);

                updateChatMessage(assistantMsgId, {
                    content: `Edit failed: ${err.message}`,
                    isStreaming: false,
                    error: err.message,
                });

                setChatGenerating(false);
                llmStatusStore.set({ state: 'error', message: err.message });
                return { success: false, plan: null, summaries: [], error: err.message };
            }
        }
);

// ── Helpers ──────────────────────────────────────────────────────────────────

function finish(): void {
    setChatGenerating(false);
    llmStatusStore.set({ state: 'ready', modelId: 'qwen3-8b' });
}

/**
 * Extract Qwen3 reasoning tokens (<think>...</think>) from the response.
 * Returns the reasoning separately and the clean response without think tags.
 */
function extractReasoning(raw: string): { reasoning: string | undefined; cleanResponse: string } {
    const thinkMatch = raw.match(/<think>([\s\S]*?)<\/think>/);
    if (thinkMatch) {
        const reasoning = thinkMatch[1]?.trim();
        const cleanResponse = raw.replace(/<think>[\s\S]*?<\/think>/, '').trim();
        return { reasoning: reasoning || undefined, cleanResponse };
    }
    return { reasoning: undefined, cleanResponse: raw };
}

function parseEditPlan(responseText: string): EditPlan {
    // Strip any residual <think>…</think> that wasn't caught by extractReasoning
    const clean = responseText.replaceAll(/<think>[\s\S]*?<\/think>/g, '').trim();

    // 1. Try direct parse on the clean response
    try {
        const parsed = JSON.parse(clean) as Record<string, unknown>;
        if (parsed.kind === 'edit_plan' && Array.isArray(parsed.dsos)) {
            return parsed as EditPlan;
        }
    } catch {
        // fall through to regex salvage
    }

    // 2. Extract the outermost JSON object that contains "kind":"edit_plan"
    //    Use a greedy match so we get the full JSON including all nested arrays.
    const match = clean.match(/\{[\s\S]*"kind"\s*:\s*"edit_plan"[\s\S]*\}/);
    if (match) {
        try {
            const parsed = JSON.parse(match[0]) as Record<string, unknown>;
            if (parsed.kind === 'edit_plan' && Array.isArray(parsed.dsos)) {
                return parsed as EditPlan;
            }
        } catch (error) {
            const preview = clean.slice(0, 120).replaceAll('\n', ' ');
            throw createAiRuntimeError(
                `LLM returned malformed JSON (${error instanceof Error ? error.message : String(error)}). ` +
                    `Response preview: "${preview}…" — ` +
                    `The model may have run out of tokens mid-response. Try a simpler request or increase max_tokens.`
            );
        }
    }

    const preview = clean.slice(0, 120).replaceAll('\n', ' ');
    throw createAiRuntimeError(`LLM response is not a valid EditPlan. Preview: "${preview}…"`);
}

async function commitDsos(
    plan: EditPlan,
    userRequest: string,
    assistantMsgId: string,
    reasoning: string | undefined,
    runDsos: ExecuteDsosFn
): Promise<string[]> {
    // Binary snapshot of ALL Automerge documents before the edit.
    // Much more compact than structuredClone(store.value) and correctly captures
    // every store — including midiStore — that the DSO may modify.
    const bundleBefore = saveSnapshot();

    // Execute
    const summaries = await runDsos(plan.dsos);

    // Binary snapshot after — used for redo.
    const bundleAfter = saveSnapshot();

    // Undo entry — typed ActionUndoEntry (serializable data, no anonymous closures)
    const { groupId, groupLabel } = generateGroupId(userRequest);
    const undoEntry = createUndoEntry(
        `AI: ${plan.intent}`,
        { type: 'restoreDsoSnapshot', payload: { bundle: bundleAfter } },
        { type: 'restoreDsoSnapshot', payload: { bundle: bundleBefore } },
        'ai'
    );
    undoEntry.groupId = groupId;
    undoEntry.groupLabel = groupLabel;
    commitUndoEntry(undoEntry);

    // Action history
    pushAiActionGroup({
        id: `dso-edit-${Date.now()}`,
        prompt: userRequest,
        actions: summaries.map((state) => ({ kind: 'jsonEdit' as const, label: state })),
        groupId,
        timestamp: Date.now(),
        reverted: false,
    });

    // Log for future prompt context
    for (const state of summaries) {
        logEdit(state);
    }

    // Update chat
    updateChatMessage(assistantMsgId, {
        content: `Done! ${summaries.join('. ')}.`,
        isStreaming: false,
        reasoning,
        isDsoAction: true,
    });

    return summaries;
}

// ── LLM invocation per backend ───────────────────────────────────────────────

async function invokeLlm(backend: string, system: string, user: string, chatMsgId: string): Promise<string> {
    let tokenCount = 0;

    function onProgress(): void {
        tokenCount++;
        if (tokenCount % 15 === 0) {
            updateChatMessage(chatMsgId, { content: `Planning... (${tokenCount} tokens)` });
        }
    }

    // Native (Tauri + mistral.rs): use schema-constrained generation
    if (backend === 'native' && isNativeEngineReady() && isTauri()) {
        return invokeNativeSchemaConstrained(system, user, onProgress);
    }

    // Native fallback (dev mode llama-server): use regular streaming
    if (backend === 'native' && isNativeEngineReady()) {
        let result = '';
        const messages = [
            { role: 'system' as const, content: system },
            { role: 'user' as const, content: user },
        ];
        await streamNativeCompletion(messages, (chunk) => {
            result += chunk;
            onProgress();
        });
        return result;
    }

    // Cloud is NOT used for DSO planning — Qwen3-8B only, no model fallback.

    // WebLLM (browser) — streaming with response_format schema constraint.
    // If grammar-constrained generation fails (smaller models may reject tokens),
    // retry without the constraint and rely on the system prompt alone.
    if (backend === 'webllm') {
        const engine = getLlmEngine();
        if (!engine) {
            throw createAiRuntimeError('WebLLM engine not initialized');
        }
        updateChatMessage(chatMsgId, { content: 'Generating edit plan...' });

        const messages = [
            { role: 'system' as const, content: system },
            { role: 'user' as const, content: user },
        ];

        // First attempt: with schema constraint.
        try {
            let result = '';
            const stream = (await engine.chat.completions.create({
                messages,
                temperature: 0.1,
                max_tokens: 1024,
                stream: true,
                response_format: {
                    type: 'json_object' as const,
                    schema: EDIT_PLAN_JSON_SCHEMA,
                },
            })) as AsyncIterable<{ choices: Array<{ delta?: { content?: string } }> }>;

            for await (const chunk of stream) {
                const delta = chunk.choices[0]?.delta?.content;
                if (delta) {
                    result += delta;
                    onProgress();
                }
            }

            return result;
        } catch (constraintError) {
            // Smaller WebLLM models may reject the grammar-constrained token stream.
            // The system prompt already instructs the model to emit JSON, so retry
            // once without the schema constraint before giving up. If the unconstrained
            // call also fails, surface a clear error including the original failure.
            try {
                let result = '';
                const stream = (await engine.chat.completions.create({
                    messages,
                    temperature: 0.1,
                    max_tokens: 1024,
                    stream: true,
                })) as AsyncIterable<{ choices: Array<{ delta?: { content?: string } }> }>;

                for await (const chunk of stream) {
                    const delta = chunk.choices[0]?.delta?.content;
                    if (delta) {
                        result += delta;
                        onProgress();
                    }
                }

                return result;
            } catch (fallbackError) {
                const activeModel = getActiveModelId();
                const constraintMsg =
                    constraintError instanceof Error ? constraintError.message : String(constraintError);
                const fallbackMsg = fallbackError instanceof Error ? fallbackError.message : String(fallbackError);
                throw createAiRuntimeError(
                    `This edit is too complex for the current model. ` +
                        `Try loading a larger model (Pro) from the AI menu, or simplify your request.\n\n` +
                        `(Grammar-constrained attempt failed on ${activeModel}: ${constraintMsg}. ` +
                        `Unconstrained retry also failed: ${fallbackMsg}.)`
                );
            }
        }
    }

    throw createAiRuntimeError(`No available backend for DSO generation`);
}

/**
 * Invoke mistral.rs with Constraint::JsonSchema for schema-guaranteed output.
 * Uses the schema_constrained_generation Tauri command with a Tauri Channel.
 */
async function invokeNativeSchemaConstrained(system: string, user: string, onProgress: () => void): Promise<string> {
    const { createChannel } = await import('#/utils/tauriBridge');

    type StreamEvent =
        | { event: 'token'; data: { text: string } }
        | { event: 'done'; data: { totalTokens: number } }
        | { event: 'error'; data: { message: string } };

    let result = '';
    let streamError: string | null = null;

    const channel = await createChannel<StreamEvent>();
    channel.onmessage = (event: StreamEvent) => {
        if (event.event === 'token') {
            result += event.data.text;
            onProgress();
        }
        if (event.event === 'error') {
            streamError = event.data.message;
        }
    };

    await tauriInvoke('schema_constrained_generation', {
        systemPrompt: system,
        userMessage: user,
        jsonSchema: EDIT_PLAN_JSON_SCHEMA,
        temperature: 0.1,
        maxTokens: 2048,
        onEvent: channel,
    });

    if (streamError) {
        throw createAiRuntimeError(streamError);
    }

    return result;
}

/**
 * Serialize the project into EASE-encoded logical state for the LLM.
 *
 * EASE encoding: stable ID-keyed maps + explicit order arrays.
 * Only the logical state is sent — no MIDI notes, no automation points,
 * no waveforms, no plugin blobs — unless explicitly requested.
 *
 * Selective state injection: only include domains relevant to the request.
 */
import { trackStore } from '#/modules/Arrangement/stores';
import { midiStore } from '#/modules/MIDI/stores';
import { transportStore } from '#/modules/Transport/stores';
import { workspaceStore } from '#/modules/Workspace/stores';

// ── Types ────────────────────────────────────────────────────────────────────

export type LogicalTrack = {
    name: string;
    kind: string;
    muted: boolean;
    soloed: boolean;
    armed: boolean;
    gain: number;
    pan: number;
    color?: string;
    clip_ids: string[];
    device_ids: string[];
};

export type LogicalClip = {
    name: string;
    type: 'audio' | 'midi';
    track_id: string;
    start_beat: number;
    end_beat: number;
    gain?: number;
    note_count?: number;
};

export type LogicalDevice = {
    name?: string;
    type: string;
    track_id: string;
    bypassed: boolean;
};

export type LogicalState = {
    project_revision: number;
    transport: {
        tempo: number;
        time_signature: [number, number];
        playhead_beat: number;
    };
    tracks: Record<string, LogicalTrack>;
    track_order: string[];
    clips: Record<string, LogicalClip>;
    devices: Record<string, LogicalDevice>;
    selection: {
        track_ids: string[];
        clip_ids: string[];
    };
};

export type ProjectSummary = {
    project_revision: number;
    track_count: number;
    selected_tracks: string[];
    selected_clips: string[];
    tempo: number;
    routing_summary: string;
    recent_edits: string[];
};

// ── Revision + recent edits log ──────────────────────────────────────────────
// Held in a closure so the only way to mutate is via the exported functions.
// HMR resets are acceptable here: the LLM-facing revision counter only needs
// to be monotonic within a session, and recent-edits is a 5-entry history
// that can safely start empty after a reload.

const editLog: { revision: number; entries: string[] } = { revision: 0, entries: [] };

export function getRevision(): number {
    return editLog.revision;
}

export function logEdit(summary: string): void {
    editLog.entries.push(summary);
    if (editLog.entries.length > 5) {
        editLog.entries.shift();
    }
}

function bumpRevision(): number {
    return ++editLog.revision;
}

function getRecentEdits(): string[] {
    return [...editLog.entries];
}

// ── Serialization ────────────────────────────────────────────────────────────

/**
 * Serialize the current project as EASE-encoded logical state.
 *
 * Options:
 * - scopeTrackIds: limit to specific tracks (selective injection)
 * - includeNoteCount: include note counts in clips (for MIDI-related edits)
 */
export function serializeLogicalState(options?: {
    scopeTrackIds?: string[];
    includeNoteCount?: boolean;
}): LogicalState {
    const trackState = trackStore.value;
    const transportState = transportStore.value;
    const workspaceState = workspaceStore.value;
    const midiState = midiStore.value;

    const scopeSet = options?.scopeTrackIds ? new Set(options.scopeTrackIds) : null;

    const revision = bumpRevision();

    const tracks: Record<string, LogicalTrack> = {};
    const trackOrder: string[] = [];
    const clips: Record<string, LogicalClip> = {};
    const devices: Record<string, LogicalDevice> = {};

    for (const track of trackState?.tracks ?? []) {
        if (scopeSet && !scopeSet.has(track.id)) {
            continue;
        }

        const clipIds: string[] = [];
        for (const clip of track.clips) {
            const logicalClip: LogicalClip = {
                name: clip.name,
                type: clip.type ?? 'audio',
                track_id: track.id,
                start_beat: clip.startBeat,
                end_beat: clip.endBeat,
                gain: (clip as Record<string, unknown>).gain as number | undefined,
            };

            if (options?.includeNoteCount && clip.type === 'midi') {
                logicalClip.note_count = midiState?.notesByClipId[clip.id]?.length ?? 0;
            }

            clips[clip.id] = logicalClip;
            clipIds.push(clip.id);
        }

        const deviceIds: string[] = [];
        for (const device of track.devices) {
            devices[device.id] = {
                name: (device as Record<string, unknown>).name as string | undefined,
                type: device.type,
                track_id: track.id,
                bypassed: device.bypassed,
            };
            deviceIds.push(device.id);
        }

        tracks[track.id] = {
            name: track.name,
            kind: track.kind,
            muted: track.muted,
            soloed: track.soloed,
            armed: track.armed,
            gain: track.gain,
            pan: track.pan,
            color: track.color,
            clip_ids: clipIds,
            device_ids: deviceIds,
        };
        trackOrder.push(track.id);
    }

    return {
        project_revision: revision,
        transport: {
            tempo: transportState?.tempo ?? 120,
            time_signature: [
                transportState?.timeSignatureNumerator ?? 4,
                transportState?.timeSignatureDenominator ?? 4,
            ],
            playhead_beat: transportState?.playheadPosition ?? 0,
        },
        tracks,
        track_order: trackOrder,
        clips,
        devices,
        selection: {
            track_ids: trackState?.selectedTrackId ? [trackState.selectedTrackId] : [],
            clip_ids: [...(workspaceState?.selectedClipIds ?? [])],
        },
    };
}

/**
 * Build a compact project summary for prompt context.
 */
export function buildProjectSummary(): ProjectSummary {
    const trackState = trackStore.value;
    const transportState = transportStore.value;
    const workspaceState = workspaceStore.value;

    return {
        project_revision: editLog.revision,
        track_count: trackState?.tracks.length ?? 0,
        selected_tracks: trackState?.selectedTrackId ? [trackState.selectedTrackId] : [],
        selected_clips: [...(workspaceState?.selectedClipIds ?? [])],
        tempo: transportState?.tempo ?? 120,
        routing_summary: buildRoutingSummary(),
        recent_edits: getRecentEdits(),
    };
}

function buildRoutingSummary(): string {
    const trackState = trackStore.value;
    if (!trackState || trackState.tracks.length === 0) {
        return 'Empty project';
    }
    const names = trackState.tracks.slice(0, 8).map((time) => time.name);
    if (trackState.tracks.length > 8) {
        return `${names.join(', ')} +${trackState.tracks.length - 8} more → Master`;
    }
    return `${names.join(', ')} → Master`;
}

import { trackStore } from '#/modules/Arrangement/stores';
import { midiStore } from '#/modules/MIDI/stores';
import { transportStore } from '#/modules/Transport/stores';
import { workspaceStore } from '#/modules/Workspace/stores';

export type ProjectContextClip = {
    id: string;
    name: string;
    type: 'audio' | 'midi';
    startBeat: number;
    endBeat: number;
    noteCount: number;
};

export type ProjectContextDevice = {
    id: string;
    type: string;
    bypassed: boolean;
};

export type ProjectContextTrack = {
    id: string;
    name: string;
    kind: string;
    muted: boolean;
    soloed: boolean;
    armed: boolean;
    gain: number;
    pan: number;
    clipCount: number;
    deviceCount: number;
    clips: ProjectContextClip[];
    devices: ProjectContextDevice[];
};

export type ProjectContext = {
    tempo: number;
    timeSignature: [number, number];
    tracks: ProjectContextTrack[];
    selectedTrackId: string | null;
    selectedClipId: string | null;
    selectedClipIds: string[];
    activeView: 'arrange' | 'automation' | 'clip' | 'mix';
    playheadPosition: number;
};

// §92.2 — Memoize the context by the identity of the four backing store
// values. Stores use immutable replacement (.set(new object)), so
// reference equality is enough: if all four have the same identity as
// the last call, we can return the cached context without rebuilding
// the entire track/clip/device graph for the AI chat pipeline.
const contextCache: {
    track: unknown;
    transport: unknown;
    workspace: unknown;
    midi: unknown;
    context: ProjectContext | null;
} = {
    track: null,
    transport: null,
    workspace: null,
    midi: null,
    context: null,
};

export function getProjectContext(): ProjectContext {
    const trackState = trackStore.value;
    const transportState = transportStore.value;
    const workspaceState = workspaceStore.value;
    // Read once per call instead of once per clip (§92.1). For a 100-track
    // project at ~20 clips each that's 2000 store dereferences → 1.
    const midiState = midiStore.value;
    const notesByClipId = midiState?.notesByClipId;

    if (
        contextCache.context !== null &&
        contextCache.track === trackState &&
        contextCache.transport === transportState &&
        contextCache.workspace === workspaceState &&
        contextCache.midi === midiState
    ) {
        return contextCache.context;
    }

    const selectedTrackId = trackState?.selectedTrackId ?? null;
    const selectedClipId = workspaceState?.selectedClipId ?? null;
    const selectedClipIds = workspaceState?.selectedClipIds ?? [];

    const built: ProjectContext = {
        tempo: transportState?.tempo ?? 120,
        timeSignature: [transportState?.timeSignatureNumerator ?? 4, transportState?.timeSignatureDenominator ?? 4],
        tracks: (trackState?.tracks ?? []).map((time) => ({
            id: time.id,
            name: time.name,
            kind: time.kind,
            muted: time.muted,
            soloed: time.soloed,
            armed: time.armed,
            gain: time.gain,
            pan: time.pan,
            clipCount: time.clips.length,
            deviceCount: time.devices.length,
            clips: time.clips.map((context) => ({
                id: context.id,
                name: context.name,
                type: context.type ?? 'audio',
                startBeat: context.startBeat,
                endBeat: context.endBeat,
                noteCount: context.type === 'midi' ? (notesByClipId?.[context.id]?.length ?? 0) : 0,
            })),
            devices: time.devices.map((data) => ({
                id: data.id,
                type: data.type,
                bypassed: data.bypassed,
            })),
        })),
        selectedTrackId,
        selectedClipId,
        selectedClipIds,
        activeView: workspaceState?.mode ?? 'arrange',
        playheadPosition: transportState?.playheadPosition ?? 0,
    };

    contextCache.track = trackState;
    contextCache.transport = transportState;
    contextCache.workspace = workspaceState;
    contextCache.midi = midiState;
    contextCache.context = built;
    return built;
}

