/**
 * AI Music Mentor lesson generation.
 *
 * Analyzes mix decisions and generates contextual educational lessons
 * explaining WHY certain mixing techniques work.
 */

import { trackStore } from '#/modules/Arrangement/stores';
import { analyzeMixFromTrackLayout } from '#/modules/AudioAnalysis/useCases';

import { type MentorCategory, type MentorLesson } from '../../models/MusicMentorTypes';

let lessonCounter = 0;

const analyzeMix = analyzeMixFromTrackLayout;

let cachedAnalysis: ReturnType<typeof analyzeMix> | null = null;
let cachedTrackStateRef: unknown = null;

function getCachedAnalysis(): ReturnType<typeof analyzeMix> {
    const currentRef = trackStore.value;
    if (cachedAnalysis && cachedTrackStateRef === currentRef) {
        return cachedAnalysis;
    }
    cachedAnalysis = analyzeMix();
    cachedTrackStateRef = currentRef;
    return cachedAnalysis;
}

function createLesson(
    category: MentorCategory,
    title: string,
    observation: string,
    explanation: string,
    advice: string,
    level: MentorLesson['level'],
    relevance: number,
    relatedConcepts: string[]
): MentorLesson {
    return {
        id: `lesson-${++lessonCounter}`,
        category,
        title,
        observation,
        explanation,
        advice,
        level,
        relevance,
        relatedConcepts,
    };
}

/**
 * Analyze the current project and generate contextual lessons.
 */
export function generateMentorLessons(): MentorLesson[] {
    const state = trackStore.value;
    if (!state) {
        return [];
    }

    const analysis = getCachedAnalysis();
    const tracks = state.tracks;
    const lessons: MentorLesson[] = [];

    // ── Gain Staging
    const gains = tracks.filter((time) => time.kind !== 'folder').map((time) => time.gain ?? 0);
    const avgGain = gains.length > 0 ? gains.reduce((alpha, b) => alpha + b, 0) / gains.length : 0;
    const maxGain = gains.length > 0 ? Math.max(...gains) : 0;

    if (maxGain > 0) {
        lessons.push(
            createLesson(
                'gain-staging',
                'Hot Signal Levels',
                `Track "${tracks.find((time) => time.gain === maxGain)?.name}" has gain at +${maxGain.toFixed(1)} dB.`,
                'Positive gain at the track level reduces your headroom and can cause digital clipping at the master bus. Professional mixes typically keep individual tracks well below 0 dBFS to leave room for the sum of all tracks.',
                'Try reducing all track faders by 6–12 dB and adjusting the master bus to compensate. This gives you much more control over the final mix.',
                'beginner',
                0.9,
                ['headroom', 'gain staging', 'digital clipping', 'unity gain']
            )
        );
    }

    if (avgGain < -20) {
        lessons.push(
            createLesson(
                'gain-staging',
                'Very Low Track Levels',
                `Average track gain is ${avgGain.toFixed(1)} dB, which is quite low.`,
                'While low levels prevent clipping, signals that are too quiet can result in a poor signal-to-noise ratio. The mix may sound thin and lack impact compared to professional releases.',
                'Aim for track peaks around -12 to -6 dBFS at the fader. This balances headroom with signal quality.',
                'beginner',
                0.75,
                ['signal-to-noise ratio', 'gain staging', 'metering']
            )
        );
    }

    // ── Panning / Stereo Field
    const pans = tracks.filter((time) => time.kind !== 'folder' && !time.muted).map((time) => time.pan ?? 0);
    const centerTracks = pans.filter((param) => Math.abs(param) < 0.1).length;
    const totalActive = pans.length || 1;

    if (centerTracks / totalActive > 0.7 && totalActive > 3) {
        lessons.push(
            createLesson(
                'stereo-field',
                'Narrow Stereo Image',
                `${centerTracks} out of ${totalActive} tracks are panned near center.`,
                'When too many elements occupy the center of the stereo field, they compete for the same space and can mask each other. Professional mixes strategically spread instruments across the stereo panorama to create width and clarity.',
                'Keep bass and vocals centered, but pan guitars, keyboards, and background elements to create space. Hard-pan doubles left and right for maximum width.',
                'intermediate',
                0.85,
                ['stereo width', 'panning', 'Haas effect', 'mono compatibility', 'frequency masking']
            )
        );
    }

    // ── Track Count / Arrangement
    const trackCount = tracks.filter((time) => time.kind !== 'folder').length;

    if (trackCount > 30) {
        lessons.push(
            createLesson(
                'arrangement',
                'Dense Arrangement',
                `Your project has ${trackCount} tracks, which is a relatively dense arrangement.`,
                'More tracks means more potential for frequency conflicts and a "muddy" mix. Great producers sometimes achieve impact with fewer, well-chosen elements rather than stacking more layers.',
                'Consider muting tracks to hear if any can be removed without losing the musical intent. Focus on contrast — having sections with fewer elements makes the full arrangement feel more powerful.',
                'intermediate',
                0.7,
                ['arrangement', 'less is more', 'frequency masking', 'subtractive mixing']
            )
        );
    }

    if (trackCount < 4 && trackCount > 0) {
        lessons.push(
            createLesson(
                'arrangement',
                'Minimal Arrangement',
                `Your project has only ${trackCount} tracks.`,
                "Minimalist arrangements can sound incredible when each element is carefully crafted, but they also expose every detail. Each instrument needs to be well-produced and well-mixed because there's nowhere to hide.",
                'Focus on making each track sound as polished as possible. Consider adding subtle effects like reverb sends, delays, and gentle compression to fill the space.',
                'beginner',
                0.6,
                ['arrangement', 'sound design', 'reverb', 'space']
            )
        );
    }

    // ── Solo/Mute Hygiene
    const soloedTracks = tracks.filter((time) => time.soloed).length;
    if (soloedTracks > 0) {
        lessons.push(
            createLesson(
                'general',
                'Solo Mode Active',
                `${soloedTracks} track(s) are currently soloed.`,
                'Mixing in solo mode is one of the most common beginner mistakes. A track that sounds great in solo may not sit well in the full mix because mixing is about context and relationships between instruments.',
                'Solo briefly to identify problems, but always make level and EQ decisions in the context of the full mix. Toggle solo on and off frequently to maintain perspective.',
                'beginner',
                0.95,
                ['solo mode', 'contextual mixing', 'critical listening']
            )
        );
    }

    // ── Frequency Balance
    if (analysis.frequencyProfile.bass > 0.8) {
        lessons.push(
            createLesson(
                'frequency-balance',
                'Heavy Low End',
                'The mix has substantial energy in the bass frequencies.',
                'Excessive low-end energy eats up headroom and can make the mix sound boomy and undefined on consumer speakers. Bass frequencies contain the most energy per octave, so small cuts here create big gains in clarity.',
                'Apply a gentle high-pass filter (30–80 Hz) to all non-bass instruments to clean up sub-rumble. Use a reference track to calibrate your bass levels.',
                'intermediate',
                0.8,
                ['high-pass filter', 'bass management', 'low-end clarity', 'headroom']
            )
        );
    }

    // ── Dynamics
    if (analysis.dynamicRange < 5) {
        lessons.push(
            createLesson(
                'dynamics',
                'Limited Dynamic Range',
                `Dynamic range is approximately ${analysis.dynamicRange.toFixed(1)} dB, which is quite compressed.`,
                'Over-compression removes the natural "breathing" of music and leads to listener fatigue. The loudness war has shown that louder is not always better — streaming platforms normalize loudness anyway.',
                'Ease off compressors and limiters. Aim for -14 LUFS integrated loudness (Spotify/YouTube target). Let transients hit and allow the music to breathe.',
                'intermediate',
                0.85,
                ['loudness war', 'dynamic range', 'LUFS', 'compression', 'loudness normalization']
            )
        );
    }

    if (analysis.dynamicRange > 16) {
        lessons.push(
            createLesson(
                'dynamics',
                'Wide Dynamic Range',
                `Dynamic range is approximately ${analysis.dynamicRange.toFixed(1)} dB, which is quite wide.`,
                'While dynamics are musically important, too much variation can make quiet parts inaudible and loud parts jarring, especially in casual listening environments like car stereo or earbuds.',
                'Consider gentle bus compression (2–4 dB gain reduction, slow attack, auto release) to glue the mix together while preserving musicality.',
                'intermediate',
                0.7,
                ['bus compression', 'glue compression', 'mix bus', 'parallel compression']
            )
        );
    }

    return lessons.sort((alpha, b) => b.relevance - alpha.relevance);
}

import { isAppError } from '#/infra/errors/isAppError';
import { describeAction, executeAppAction, generateGroupId } from '#/modules/Command/useCases';

import { createAiRuntimeError } from '../errors/AiRuntimeError';
import { type ChatMessage } from '../models/Chat';
import { CHAT_SYSTEM_PROMPT } from '../models/chatSystemPrompt';
import { type RuntimeAction } from '../models/RuntimeAction';
import { streamCloudChatCompletion } from '../repositories/cloudLlm/cloudInference/streamCloudChatCompletion';
import { isCloudAvailable } from '../repositories/cloudLlm/keyManagement';
import { isNativeEngineReady } from '../repositories/nativeEngine/lifecycle';
import { streamNativeCompletion } from '../repositories/nativeEngine/streaming';
import { getLlmEngine } from '../repositories/webLlm/engineLifecycle';
import { pushAiActionGroup, type AiActionGroup } from '../stores/aiActionHistoryStore';
import {
    chatStore,
    appendChatMessage,
    updateChatMessage,
    setChatGenerating,
    setActiveAborter,
} from '../stores/chatStore';

import { getProjectContext } from './getProjectContext';
import { resolveBackend } from './llmOrchestration/backendResolution/helpers';
import { notifyAiChange } from './notifyAiChange';
import { parsePromptToActions } from './parsePromptToActions';

/** Strip or extract a `<think>…</think>` block from LLM output, including incomplete streaming blocks. */
function extractThinkBlock(raw: string): { reasoning: string | undefined; content: string } {
    // 1. Fully formed block
    const match = raw.match(/^\s*<think>([\s\S]*?)<\/think>\s*/);
    if (match) {
        return {
            reasoning: match[1]?.trim() || undefined,
            content: raw.slice(match[0].length).trim(),
        };
    }

    // 2. Partial (streaming) block without closing tag
    const partialMatch = raw.match(/^\s*<think>([\s\S]*)$/);
    if (partialMatch) {
        return {
            reasoning: partialMatch[1]?.trim() || undefined,
            content: '', // Still thinking! No actual final content yet
        };
    }

    // 3. No think block at all
    return { reasoning: undefined, content: raw };
}

export async function sendChatMessage(userText: string): Promise<void> {
    const backend = resolveBackend();

    // Verify the appropriate engine is available
    if (backend === 'none') {
        throw createAiRuntimeError('No AI backend available. Configure an API key or use a WebGPU-capable browser.');
    }
    if (backend === 'native' && !isNativeEngineReady()) {
        throw createAiRuntimeError('Native AI engine is not running. Load the AI engine first.');
    }
    if (backend === 'webllm' && !getLlmEngine()) {
        throw createAiRuntimeError('AI Engine is not initialized or not supported on this device.');
    }
    if (backend === 'cloud' && !isCloudAvailable()) {
        throw createAiRuntimeError('Cloud AI not configured. Set API key in settings.');
    }

    const state = chatStore.value;
    if (!state || state.isGenerating) {
        return;
    }

    setChatGenerating(true);

    // ── Prompt Command Mode ──────────────────────────────────────────────
    if (state.chatMode === 'prompt') {
        const aborter = new AbortController();
        setActiveAborter(aborter);

        try {
            const context = getProjectContext();
            const result = await parsePromptToActions(userText, context, aborter.signal);

            if (result.actions.length > 0) {
                // Manually inject messages for Fast-Path execution
                const userMsgId = `msg-${crypto.randomUUID()}`;
                appendChatMessage({
                    id: userMsgId,
                    role: 'user',
                    content: userText,
                    timestamp: Date.now(),
                    isDsoAction: true,
                });

                const assistantMsgId = `msg-${crypto.randomUUID()}`;
                appendChatMessage({
                    id: assistantMsgId,
                    role: 'assistant',
                    content: 'Executing...',
                    timestamp: Date.now(),
                    isDsoAction: true,
                });
                const group = generateGroupId(userText);
                const executedLabels: Array<{ action: RuntimeAction; label: string }> = [];

                for (const action of result.actions) {
                    await executeAppAction(action, { ...group, source: 'prompt' });
                    executedLabels.push({ action, label: describeAction(action) });
                }

                const historyGroup: AiActionGroup = {
                    id: group.groupId,
                    prompt: userText,
                    actions: executedLabels.map((length) => ({
                        kind: 'appAction',
                        actionType: length.action.type,
                        label: length.label,
                    })),
                    groupId: group.groupId,
                    timestamp: Date.now(),
                    reverted: false,
                };
                pushAiActionGroup(historyGroup);

                notifyAiChange(
                    `Executed: ${userText}`,
                    result.actions.map((alpha) => alpha.type)
                );

                updateChatMessage(assistantMsgId, {
                    isStreaming: false,
                    content: `Executed:\n\n${executedLabels.map((length) => `- **${length.action.type.replaceAll('_', ' ')}**: ${length.label}`).join('\n')}`,
                });
            } else if (result._jsonEditApplied) {
                // executeDsoEdit already injected the user message and the assistant streaming message.
                // We just need to trigger the toast notification.
                const summary = result._jsonEditSummaries?.join('. ') ?? `Executed: ${userText}`;
                notifyAiChange(summary, []);
            } else if (!result._jsonEditAttempted) {
                appendChatMessage({
                    id: `msg-${crypto.randomUUID()}`,
                    role: 'user',
                    content: userText,
                    timestamp: Date.now(),
                    isDsoAction: true,
                });
                appendChatMessage({
                    id: `msg-${crypto.randomUUID()}`,
                    role: 'assistant',
                    content: 'No actions were matched or executed for your command.',
                    timestamp: Date.now(),
                    error: 'No actions matched',
                });
            }
        } catch (error) {
            appendChatMessage({
                id: `msg-${crypto.randomUUID()}`,
                role: 'user',
                content: userText,
                timestamp: Date.now(),
            });
            appendChatMessage({
                id: `msg-${crypto.randomUUID()}`,
                role: 'assistant',
                content: 'Failed to process prompt command.',
                error: String(error),
                timestamp: Date.now(),
            });
        } finally {
            setActiveAborter(null);
            setChatGenerating(false);
        }
        return;
    }

    // ── Regular Chat Mode ───────────────────────────────────────────────
    const userMsgId = `msg-${crypto.randomUUID()}`;
    appendChatMessage({
        id: userMsgId,
        role: 'user',
        content: userText,
        timestamp: Date.now(),
    });

    const assistantMsgId = `msg-${crypto.randomUUID()}`;
    const initialAssistantMessage: ChatMessage = {
        id: assistantMsgId,
        role: 'assistant',
        content: '',
        timestamp: Date.now(),
        isStreaming: true,
    };
    appendChatMessage(initialAssistantMessage);

    const aborter = new AbortController();
    setActiveAborter(aborter);
    let fullContent = '';

    try {
        const workspaceContext = getProjectContext();

        const systemPrompt = `${CHAT_SYSTEM_PROMPT}\n\nCURRENT DAW CONTEXT:\n${JSON.stringify(workspaceContext)}`;

        // Keep only the last 24 messages (12 user+assistant pairs) to avoid
        // blowing the context window on long conversations.
        const conversationHistory = chatStore
            .value!.messages.filter((message) => message.id !== assistantMsgId && !message.error)
            .slice(-24)
            .map((message) => ({
                role: message.role,
                content: message.content,
            }));

        const completionMessages = [{ role: 'system' as const, content: systemPrompt }, ...conversationHistory].filter(
            (message) => message.role === 'system' || message.role === 'user' || message.role === 'assistant'
        ) as Array<{ role: 'system' | 'user' | 'assistant'; content: string }>;

        if (backend === 'native') {
            // Native: streaming completion via Tauri Channel API
            await streamNativeCompletion(
                completionMessages,
                (token) => {
                    if (aborter.signal.aborted) {
                        throw createAiRuntimeError('AbortedByUser');
                    }
                    fullContent += token;
                    const parsed = extractThinkBlock(fullContent);
                    updateChatMessage(assistantMsgId, { content: parsed.content, reasoning: parsed.reasoning });
                },
                { temperature: 0.7, maxTokens: 2048 }
            );
        } else if (backend === 'cloud') {
            // Cloud: streaming completion via Claude API
            await streamCloudChatCompletion(
                completionMessages,
                (token) => {
                    if (aborter.signal.aborted) {
                        throw createAiRuntimeError('AbortedByUser');
                    }
                    fullContent += token;
                    const parsed = extractThinkBlock(fullContent);
                    updateChatMessage(assistantMsgId, { content: parsed.content, reasoning: parsed.reasoning });
                },
                { temperature: 0.7, maxTokens: 2048 }
            );
        } else {
            // WebLLM: streaming completion via the in-browser engine.
            // Yield to the render loop before starting inference — the first
            // forward pass triggers WebGPU shader compilation which locks the
            // GPU (shared with the compositor). Without this yield, the browser
            // can't paint the "Thinking..." state before the GPU gets busy.
            await new Promise<void>((resolve) => requestAnimationFrame(() => setTimeout(resolve, 0)));

            const engine = getLlmEngine()!;
            const asyncChunkGenerator = (await engine.chat.completions.create({
                messages: completionMessages,
                temperature: 0.7,
                max_tokens: 2048,
                stream: true,
            })) as AsyncIterable<any>;

            for await (const chunk of asyncChunkGenerator) {
                if (aborter.signal.aborted) {
                    break;
                }
                const deltaDesc = chunk.choices[0]?.delta.content;
                if (deltaDesc !== undefined) {
                    fullContent += deltaDesc;
                    const parsed = extractThinkBlock(fullContent);
                    updateChatMessage(assistantMsgId, { content: parsed.content, reasoning: parsed.reasoning });
                }
            }
        }

        // Strip <think>…</think> reasoning block before storing the final message.
        const { reasoning, content: cleanContent } = extractThinkBlock(fullContent);
        updateChatMessage(assistantMsgId, { isStreaming: false, content: cleanContent, reasoning });
    } catch (error) {
        const errorMessage = (() => {
            if (isAppError(error)) {
                return error.message;
            }
            if (error instanceof Error) {
                return error.message;
            }
            return 'An unknown error occurred during generation.';
        })();
        if (errorMessage === 'AbortedByUser' || errorMessage.includes('AbortError')) {
            // Clean abort, leave generated partial content intact and strip parsing blocks
            const parsed = extractThinkBlock(fullContent);
            updateChatMessage(assistantMsgId, {
                isStreaming: false,
                content: parsed.content,
                reasoning: parsed.reasoning,
            });
        } else {
            updateChatMessage(assistantMsgId, {
                isStreaming: false,
                error: errorMessage,
                content: 'Sorry, I encountered an error while thinking about that.',
            });
        }
    } finally {
        setActiveAborter(null);
        setChatGenerating(false);
    }
}

