describe('handleRemoveTrack', () => {
    beforeEach(() => {
        vi.clearAllMocks();
        mocks.automationStoreValue.value = null;
        mocks.midiStoreValue.value = null;
        mocks.takeLaneStoreValue.value = null;
    });

    describe('execute', () => {
        it('calls removeTrack with the provided trackId', () => {
            void handleRemoveTrack.execute({
                type: 'removeTrack',
                payload: { trackId: 't1' },
            });
            expect(mocks.removeTrack).toHaveBeenCalledWith('t1');
        });
    });

    describe('describe', () => {
        it('returns simple label if track is not found', () => {
            mocks.getTrackStoreState.mockReturnValue({ tracks: [] });

            const desc = handleRemoveTrack.describe({
                type: 'removeTrack',
                payload: { trackId: 't1' },
            });

            expect(desc.label).toBe('Remove track');
            expect((desc as any).inverseAction).toBeUndefined();
        });

        it('returns inverse action with full snapshot state', () => {
            mocks.getTrackStoreState.mockReturnValue({
                tracks: [{ id: 't1', name: 'Vocals', clips: [{ id: 'c1' }] }],
            });

            mocks.automationStoreValue.value = {
                lanes: [
                    { trackId: 't1', id: 'l1' },
                    { trackId: 't2', id: 'l2' },
                ],
            };

            mocks.midiStoreValue.value = {
                notesByClipId: { c1: [{ pitch: 60 }] },
                ccByClipId: { c1: [{ value: 10 }] },
                pitchBendByClipId: { c1: [{ value: 0 }] },
                c2: [{ pitch: 64 }],
            };

            mocks.takeLaneStoreValue.value = {
                lanes: [
                    { trackId: 't1', id: 'take1' },
                    { trackId: 't2', id: 'take2' },
                ],
            };

            const desc = handleRemoveTrack.describe({
                type: 'removeTrack',
                payload: { trackId: 't1' },
            });

            expect(desc.label).toBe('Remove track');
            expect(desc.inverseAction).toBeDefined();
            expect(desc.inverseAction?.type).toBe('restoreTrack');

            const payload = desc.inverseAction?.payload;
            expect(payload?.trackId).toBe('t1');
            expect(payload?.trackSnapshot).toEqual({ id: 't1', name: 'Vocals', clips: [{ id: 'c1' }] });
            expect(payload?.automationLaneSnapshots).toEqual([{ trackId: 't1', id: 'l1' }]);
            expect(payload?.takeLaneSnapshots).toEqual([{ trackId: 't1', id: 'take1' }]);

            expect(payload?.midiNotesByClipId).toEqual({ c1: [{ pitch: 60 }] });
            expect(payload?.midiCcByClipId).toEqual({ c1: [{ value: 10 }] });
            expect(payload?.midiPitchBendByClipId).toEqual({ c1: [{ value: 0 }] });
        });
    });

    it('is undoable', () => {
        expect(handleRemoveTrack.undoable).toBe(true);
    });
});

import { describe, it, expect, vi, beforeEach } from 'vitest';

import { handleCreateTrackAlternative } from '../handleCreateTrackAlternative';

const mocks = vi.hoisted(() => ({
    getTrackStoreState: vi.fn(),
    setTrackStoreState: vi.fn(),
}));

vi.mock('../../../useCases/getTrackStoreState', () => ({
    getTrackStoreState: mocks.getTrackStoreState,
}));

vi.mock('../../../useCases/setTrackStoreState', () => ({
    setTrackStoreState: mocks.setTrackStoreState,
}));

describe('handleCreateTrackAlternative', () => {
    beforeEach(() => {
        vi.clearAllMocks();
        // Setup a basic state with one track and one alternative
        mocks.getTrackStoreState.mockReturnValue({
            tracks: [
                {
                    id: 't1',
                    activeAlternativeId: 'alt1',
                    clips: [{ id: 'clip1' }],
                    alternatives: [{ id: 'alt1', name: 'Alt 1', clips: [] }],
                },
            ],
        });
    });

    it('creates a new empty alternative and switches to it', () => {
        void handleCreateTrackAlternative.execute({
            type: 'createTrackAlternative',
            payload: { trackId: 't1', name: 'New Alt', duplicateActive: false },
        });

        expect(mocks.setTrackStoreState).toHaveBeenCalledTimes(1);
        const newState = mocks.setTrackStoreState.mock.calls[0][0];
        const track = newState.tracks[0];

        expect(track.alternatives).toHaveLength(2);
        expect(track.alternatives[1].name).toBe('New Alt');
        expect(track.alternatives[1].clips).toHaveLength(0);
        expect(track.activeAlternativeId).toBe(track.alternatives[1].id);

        // Verify current clips were saved to previous alternative
        expect(track.alternatives[0].clips).toEqual([{ id: 'clip1' }]);
    });

    it('creates a new duplicated alternative and switches to it', () => {
        void handleCreateTrackAlternative.execute({
            type: 'createTrackAlternative',
            payload: { trackId: 't1', name: 'Dupe', duplicateActive: true },
        });

        const newState = mocks.setTrackStoreState.mock.calls[0][0];
        const track = newState.tracks[0];

        expect(track.alternatives).toHaveLength(2);
        expect(track.alternatives[1].clips).toHaveLength(1);
        expect(track.alternatives[1].clips[0].id).toMatch(/^clip-/);
        expect(track.activeAlternativeId).toBe(track.alternatives[1].id);
    });

    it('is undoable', () => {
        expect(handleCreateTrackAlternative.undoable).toBe(true);
    });
});

import { describe, it, expect, vi, beforeEach } from 'vitest';

import { handleDeleteTrackAlternative } from '../handleDeleteTrackAlternative';

const mocks = vi.hoisted(() => ({
    getTrackStoreState: vi.fn(),
    setTrackStoreState: vi.fn(),
}));

vi.mock('../../../useCases/getTrackStoreState', () => ({
    getTrackStoreState: mocks.getTrackStoreState,
}));

vi.mock('../../../useCases/setTrackStoreState', () => ({
    setTrackStoreState: mocks.setTrackStoreState,
}));

describe('handleDeleteTrackAlternative', () => {
    beforeEach(() => {
        vi.clearAllMocks();
    });

    it('deletes the specified alternative', () => {
        mocks.getTrackStoreState.mockReturnValue({
            tracks: [
                {
                    id: 't1',
                    activeAlternativeId: 'alt1',
                    alternatives: [
                        { id: 'alt1', clips: [] },
                        { id: 'alt2', clips: [] },
                    ],
                },
            ],
        });

        void handleDeleteTrackAlternative.execute({
            type: 'deleteTrackAlternative',
            payload: { trackId: 't1', alternativeId: 'alt2' },
        });

        const newState = mocks.setTrackStoreState.mock.calls[0][0];
        expect(newState.tracks[0].alternatives).toHaveLength(1);
        expect(newState.tracks[0].alternatives[0].id).toBe('alt1');
    });

    it('falls back to another alternative if deleting the active one', () => {
        const alt2Clips = [{ id: 'c2' }];
        mocks.getTrackStoreState.mockReturnValue({
            tracks: [
                {
                    id: 't1',
                    activeAlternativeId: 'alt1',
                    clips: [{ id: 'c1' }],
                    alternatives: [
                        { id: 'alt1', clips: [{ id: 'c1' }] },
                        { id: 'alt2', clips: alt2Clips },
                    ],
                },
            ],
        });

        void handleDeleteTrackAlternative.execute({
            type: 'deleteTrackAlternative',
            payload: { trackId: 't1', alternativeId: 'alt1' },
        });

        const newState = mocks.setTrackStoreState.mock.calls[0][0];
        const track = newState.tracks[0];
        expect(track.alternatives).toHaveLength(1);
        expect(track.activeAlternativeId).toBe('alt2');
        expect(track.clips).toEqual(alt2Clips);
    });

    it('refuses to delete if only one alternative remains', () => {
        mocks.getTrackStoreState.mockReturnValue({
            tracks: [{ id: 't1', alternatives: [{ id: 'alt1' }] }],
        });

        void handleDeleteTrackAlternative.execute({
            type: 'deleteTrackAlternative',
            payload: { trackId: 't1', alternativeId: 'alt1' },
        });

        const newState = mocks.setTrackStoreState.mock.calls[0][0];
        expect(newState.tracks[0].alternatives).toHaveLength(1);
    });
});

