import { trackStore } from '../../stores/trackStore';
import { buildTimelineRenderModel } from '../../useCases/buildTimelineRenderModel';
import { acceptGhostClip } from '../../useCases/clip/acceptGhostClip';
import { addClip } from '../../useCases/clip/addClip';
import { duplicateClipCore } from '../../useCases/clip/duplicateClipCore';
import { moveClip } from '../../useCases/clip/moveClip';
import { removeClip } from '../../useCases/clip/removeClip';
import { slipClipContent } from '../../useCases/clipEditing/slipClipContent';
import { toggleInlineEditing } from '../../useCases/clipEditing/toggleInlineEditing';
import { trimClipEnd } from '../../useCases/clipEditing/trimClipEnd';
import { trimClipStart } from '../../useCases/clipEditing/trimClipStart';
import { getTrackStoreState } from '../../useCases/getTrackStoreState';
import { planRippleInsert } from '../../useCases/rippleInsert/planRippleInsert';
import { rippleInsertClip, undoRippleInsertClip } from '../../useCases/rippleInsert/rippleInsertClip';
import { planRippleMove } from '../../useCases/rippleMove/planRippleMove';
import { rippleMoveClip } from '../../useCases/rippleMove/rippleMoveClip';
import { setTrackState } from '../../useCases/setTrackState';
import { beginClipDrag, type DragState } from '../../useCases/timelineInteractions/beginClipDrag';
import { getTrackAtY as getTrackAtYHelper } from '../../useCases/timelineInteractions/getTrackAtY';
import { hitTestClip } from '../../useCases/timelineInteractions/hitTestClip/hitTestClip';
import { hitTestTrack } from '../../useCases/timelineInteractions/hitTestClip/hitTestTrack';
import { hitTestClipEdge } from '../../useCases/timelineInteractions/hitTestClipEdge';
import { setPlayheadFromClick } from '../../useCases/timelineInteractions/setPlayheadFromClick';
import { snapToGrid } from '../../useCases/timelineInteractions/snapToGrid';
import { snapToGridOrClips } from '../../useCases/timelineInteractions/snapToGridOrClips';
import { snapToZeroCrossing } from '../../useCases/timelineInteractions/snapToZeroCrossing';
import { selectTrack } from '../../useCases/toggleTrackState/selectTrack';
import { canvasXToBeat, getContentY } from '../helpers/timelineMouse';
import {
    handleCutTool,
    handleDrawTool,
    handleAutomationTool,
    tryPaintSubLane,
    paintAutoDragPoint,
} from '../helpers/timelineTools';

import { useTimelineFileDrop } from './useTimelineFileDrop';
import { useTimelineGestures } from './useTimelineGestures';

type ClipMenuState = { kind: 'clip'; x: number; y: number; clipId: string; trackId: string; splitBeat: number };
type EmptyMenuState = { kind: 'empty'; x: number; y: number; trackId: string | null; beat: number };
export type ContextMenuState = ClipMenuState | EmptyMenuState | null;

export const useTimelineInteractions = (canvasRef: React.RefObject<HTMLCanvasElement | null>) => {
    const [dragState, setDragState] = useState<DragState | null>(null);
    const [contextMenu, setContextMenu] = useState<ContextMenuState>(null);
    const pointersRef = useRef<Map<number, PointerEvent>>(new Map());
    const loopDragRef = useRef<{ startBeat: number } | null>(null);
    const autoDragRef = useRef<{ laneId: string; trackId: string; points: AutomationPoint[] } | null>(null);
    const drawDragRef = useRef<{ trackId: string; startBeat: number; clipType: 'audio' | 'midi' } | null>(null);
    const slipDragRef = useRef<{
        clipId: string;
        clipType: 'audio' | 'midi';
        startX: number;
        originalOffset: number;
    } | null>(null);
    const noteDragRef = useRef<{
        clipId: string;
        noteId: string;
        originalStartBeat: number;
        originalPitch: number;
        dragStartBeat: number;
        dragStartY: number;
        noteHeight: number;
        trackId: string;
    } | null>(null);
    const [rubberBand, setRubberBand] = useState<{ startX: number; startY: number; endX: number; endY: number } | null>(
        null
    );
    const rubberBandRef = useRef<{ startX: number; startY: number } | null>(null);
    const [hoverCursor, setHoverCursor] = useState<string | null>(null);
    const lastPresenceBroadcastRef = useRef<number>(0);

    useTimelineGestures(canvasRef);

    const getCanvasCoords = (event: MouseEvent<HTMLCanvasElement>): { x: number; y: number } => {
        const rect = canvasRef.current?.getBoundingClientRect();
        if (!rect) {
            return { x: 0, y: 0 };
        }
        return { x: event.clientX - rect.left, y: event.clientY - rect.top };
    };

    const getBeatFromX = (x: number): number => canvasXToBeat(x);

    const { handleFileDrop, isDragOver, setIsDragOver, isImporting } = useTimelineFileDrop({
        getCanvasCoords: (event: DragEvent<HTMLDivElement>): { x: number; y: number } => {
            const rect = canvasRef.current?.getBoundingClientRect();
            if (!rect) {
                return { x: 0, y: 0 };
            }
            return { x: event.clientX - rect.left, y: event.clientY - rect.top };
        },
        getBeatFromX,
    });

    const getActiveTool = () => workspaceStore.value?.activeTool ?? 'select';
    const getScrollY = () => timelineViewStore.value?.scrollY ?? 0;

    // ── Mouse Down ────────────────────────────────────────────────────────────

    const handleMouseDown = (event: MouseEvent<HTMLCanvasElement>) => {
        if (event.button !== 0) {
            return;
        }
        const { x, y } = getCanvasCoords(event);
        const beat = getBeatFromX(x);
        const tool = getActiveTool();

        // Sub-lane paint when automation panel is visible (any tool)
        if (workspaceStore.value?.automationVisibility !== 'hidden') {
            if (tryPaintSubLane(x, y, autoDragRef)) {
                return;
            }
        }

        if (tool === 'cut') {
            handleCutTool(x, y, snapToGrid(beat));
            return;
        }
        if (tool === 'draw') {
            handleDrawTool(x, y, beat, drawDragRef);
            return;
        }
        if (tool === 'automation') {
            handleAutomationTool(x, y, beat, getScrollY(), autoDragRef);
            return;
        }

        // ── Ctrl/Cmd+Shift+drag: slip edit clip content (A10) ──
        if ((event.ctrlKey || event.metaKey) && event.shiftKey) {
            const slipHit = hitTestClip(x, y);
            if (slipHit) {
                const state = trackStore.value;
                const track = state?.tracks.find((time) => time.id === slipHit.trackId);
                const clip = track?.clips.find((context) => context.id === slipHit.clipId);
                if (clip) {
                    slipDragRef.current = {
                        clipId: clip.id,
                        clipType: clip.type,
                        startX: x,
                        originalOffset:
                            clip.type === 'audio' ? (clip.audioOffsetBeats ?? 0) : (clip.midiOffsetBeats ?? 0),
                    };
                    return;
                }
            }
        }

        // ── Select tool: clip hit → select + maybe begin drag ──
        const clipHit = hitTestClip(x, y);
        if (clipHit) {
            // R-A11: If hitting a note in an inline clip, start note drag instead of clip drag
            if (clipHit.noteId) {
                const notes = midiStore.value?.notesByClipId[clipHit.clipId] ?? [];
                const note = notes.find((node) => node.id === clipHit.noteId);
                if (note) {
                    noteDragRef.current = {
                        clipId: clipHit.clipId,
                        noteId: clipHit.noteId,
                        originalStartBeat: note.startBeat,
                        originalPitch: note.pitch,
                        dragStartBeat: beat,
                        dragStartY: y,
                        noteHeight: clipHit.noteHeight ?? 20,
                        trackId: clipHit.trackId,
                    };
                    return;
                }
            }

            // Ghost clip click: accept it immediately (R-E1.2)
            const state = trackStore.value;
            const clipForHit = state?.tracks
                .flatMap((time) => time.clips)
                .find((context) => context.id === clipHit.clipId);
            if (clipForHit?.isGhost) {
                acceptGhostClip(clipHit.clipId);
                return;
            }
            selectTrack(clipHit.trackId);
            if (event.shiftKey || event.metaKey) {
                toggleClipInSelection(clipHit.clipId);
            } else {
                selectClipWithFocus(clipHit.clipId);
            }
        }

        const edgeHit = hitTestClipEdge(x, y);
        let dragMode: 'move' | 'duplicate' | 'stretch' | 'trim-start' = tool === 'stretch' ? 'stretch' : 'move';
        if (edgeHit && edgeHit.edge !== 'body' && tool === 'select') {
            dragMode = edgeHit.edge === 'left' ? 'trim-start' : 'stretch';
        }
        // Alt+drag on a clip: duplicate instead of move (R-B1)
        if (event.altKey && clipHit && dragMode === 'move') {
            dragMode = 'duplicate';
        }

        const drag = beginClipDrag(x, y, dragMode);
        if (drag) {
            // Capture original positions for all selected clips so mousemove can
            // write preview positions without touching any store.
            const selectedIds = workspaceStore.value?.selectedClipIds ?? [];
            const allIds = selectedIds.length > 1 && selectedIds.includes(drag.clipId) ? selectedIds : [drag.clipId];
            const state = trackStore.value;
            if (state) {
                const originals = new Map<string, ClipPreviewPosition>();
                for (const time of state.tracks) {
                    for (const clip of time.clips) {
                        if (allIds.includes(clip.id)) {
                            originals.set(clip.id, {
                                trackId: time.id,
                                startBeat: clip.startBeat,
                                endBeat: clip.endBeat,
                            });
                        }
                    }
                }
                clipDragPreviewRef.current = { positions: new Map(originals), originals };
                previewDirtyFlag.value = true;
            }
            setDragState(drag);
            return;
        }

        if (!clipHit) {
            selectTrack(hitTestTrack(y));
            clearClipSelection();
            rubberBandRef.current = { startX: x, startY: y };
            setPlayheadFromClick(x);
        }
    };

    // ── Mouse Move ────────────────────────────────────────────────────────────

    const handleMouseMove = (event: MouseEvent<HTMLCanvasElement>) => {
        const { x, y } = getCanvasCoords(event);

        if (noteDragRef.current) {
            const drag = noteDragRef.current;
            const deltaBeat = getBeatFromX(x) - drag.dragStartBeat;
            const deltaPitch = Math.round((drag.dragStartY - y) / drag.noteHeight);

            const newStartBeat = snapToGrid(drag.originalStartBeat + deltaBeat);
            const newPitch = Math.max(0, Math.min(127, drag.originalPitch + deltaPitch));

            moveMidiNote(drag.clipId, drag.noteId, newPitch, newStartBeat);
            return;
        }

        // Broadcast cursor presence to collaborators (~10 Hz throttle)
        if (collaborationStore.value?.isEnabled) {
            const now = performance.now();
            if (now - lastPresenceBroadcastRef.current > 100) {
                lastPresenceBroadcastRef.current = now;
                const cursorBeat = getBeatFromX(x);
                const tracks = trackStore.value?.tracks ?? [];
                const contentY = getContentY(y, getScrollY());
                const trackHit = getTrackAtYHelper(tracks, Math.max(0, contentY));
                broadcastPresence({
                    view: 'arrangement',
                    cursorBeat,
                    cursorTrackId: trackHit?.id ?? null,
                    selectedClipIds: [],
                    selectedNoteIds: [],
                    viewportStartBeat: 0,
                    viewportEndBeat: 0,
                    viewportTrackIds: [],
                    action: null,
                    playheadBeat: null,
                });
            }
        }

        // Hover cursor (no active drag)
        if (
            !dragState &&
            !loopDragRef.current &&
            !autoDragRef.current &&
            !drawDragRef.current &&
            !rubberBandRef.current
        ) {
            if (getActiveTool() === 'select') {
                const edgeHit = hitTestClipEdge(x, y);
                setHoverCursor(edgeHit && edgeHit.edge !== 'body' ? 'ew-resize' : null);
            } else {
                setHoverCursor(null);
            }
        }

        if (loopDragRef.current) {
            const currentBeat = getBeatFromX(x);
            const { startBeat } = loopDragRef.current;
            const loopStart = Math.min(startBeat, currentBeat);
            const loopEnd = Math.max(startBeat, currentBeat);
            if (loopEnd - loopStart > 0.25) {
                setLoopRegion(Math.floor(loopStart), Math.ceil(loopEnd));
                if (!getTransportState()?.isLooping) {
                    toggleLoop();
                }
            }
            return;
        }

        if (autoDragRef.current) {
            paintAutoDragPoint(x, y, getScrollY(), autoDragRef);
            return;
        }

        if (drawDragRef.current) {
            return;
        }

        if (slipDragRef.current) {
            const { clipId, clipType, startX, originalOffset } = slipDragRef.current;
            const view = timelineViewStore.value;
            if (view) {
                const deltaBeats = (x - startX) / view.pixelsPerBeat;
                const newOffset = originalOffset + deltaBeats;

                // Update ephemeral preview
                if (!clipDragPreviewRef.current) {
                    const state = trackStore.value;
                    const track = state?.tracks.find((time) => time.clips.some((context) => context.id === clipId));
                    const clip = track?.clips.find((context) => context.id === clipId);
                    if (track && clip) {
                        const pos = {
                            trackId: track.id,
                            startBeat: clip.startBeat,
                            endBeat: clip.endBeat,
                            audioOffsetBeats: clip.audioOffsetBeats,
                            midiOffsetBeats: clip.midiOffsetBeats,
                        };
                        clipDragPreviewRef.current = {
                            positions: new Map([[clipId, { ...pos }]]),
                            originals: new Map([[clipId, { ...pos }]]),
                        };
                    }
                }

                const preview = clipDragPreviewRef.current;
                if (preview) {
                    const current = preview.positions.get(clipId);
                    if (current) {
                        preview.positions.set(clipId, {
                            ...current,
                            audioOffsetBeats: clipType === 'audio' ? newOffset : current.audioOffsetBeats,
                            midiOffsetBeats: clipType === 'midi' ? newOffset : current.midiOffsetBeats,
                        });
                    }
                }
                previewDirtyFlag.value = true;
            }
            return;
        }

        if (rubberBandRef.current) {
            const { startX, startY } = rubberBandRef.current;
            if (Math.abs(x - startX) > 4 || Math.abs(y - startY) > 4) {
                setRubberBand({ startX, startY, endX: x, endY: y });
            }
            return;
        }

        if (!dragState) {
            return;
        }
        if (canvasRef.current) {
            canvasRef.current.style.cursor = 'grabbing';
        }

        const view = timelineViewStore.value;
        if (!view) {
            return;
        }
        const rawBeat = x / view.pixelsPerBeat + view.scrollX / view.pixelsPerBeat;

        if (dragState.mode === 'trim-start') {
            const newStart = Math.max(0, Math.min(dragState.endBeat - 0.25, snapToGrid(rawBeat)));
            const preview = clipDragPreviewRef.current;
            if (preview) {
                const orig = preview.originals.get(dragState.clipId);
                if (orig) {
                    preview.positions.set(dragState.clipId, { ...orig, startBeat: newStart });
                    previewDirtyFlag.value = true;
                }
            }
            return;
        }
        if (dragState.mode === 'stretch') {
            let newEnd = Math.max(dragState.startBeat + 0.25, snapToGrid(rawBeat));

            if (preferencesStore.value?.snapToZeroCrossing) {
                const state = trackStore.value;
                const clip = state?.tracks
                    .flatMap((time) => time.clips)
                    .find((context) => context.id === dragState.clipId);
                if (clip && clip.type === 'audio') {
                    newEnd = snapToZeroCrossing(clip, newEnd);
                }
            }

            const preview = clipDragPreviewRef.current;
            if (preview) {
                const orig = preview.originals.get(dragState.clipId);
                if (orig) {
                    preview.positions.set(dragState.clipId, { ...orig, endBeat: newEnd });
                    previewDirtyFlag.value = true;
                }
            }
            return;
        }

        const contentY = getContentY(y, getScrollY());
        const model = buildTimelineRenderModel();
        const tracks = model?.tracks;
        if (!tracks) {
            return;
        }
        const trackHit = getTrackAtYHelper(tracks, Math.max(0, contentY));
        const targetTrack = trackHit ? tracks[trackHit.index] : null;
        const snapTrackId = targetTrack?.id ?? dragState.sourceTrackId;
        const snappedBeat = Math.max(
            0,
            snapToGridOrClips(rawBeat - dragState.offsetBeat, snapTrackId, dragState.clipId)
        );

        if (targetTrack) {
            const selectedIds = workspaceStore.value?.selectedClipIds ?? [];
            const preview = clipDragPreviewRef.current;
            if (preview) {
                const primaryOrig = preview.originals.get(dragState.clipId);
                if (selectedIds.length > 1 && selectedIds.includes(dragState.clipId) && primaryOrig) {
                    const beatDelta = snappedBeat - primaryOrig.startBeat;
                    for (const id of selectedIds) {
                        const orig = preview.originals.get(id);
                        if (orig) {
                            const newStart = Math.max(0, orig.startBeat + beatDelta);
                            preview.positions.set(id, {
                                trackId: targetTrack.id,
                                startBeat: newStart,
                                endBeat: newStart + (orig.endBeat - orig.startBeat),
                            });
                        }
                    }
                } else if (primaryOrig) {
                    const duration = primaryOrig.endBeat - primaryOrig.startBeat;
                    preview.positions.set(dragState.clipId, {
                        trackId: targetTrack.id,
                        startBeat: snappedBeat,
                        endBeat: snappedBeat + duration,
                    });
                }
                previewDirtyFlag.value = true;
            }
        }
    };

    // ── Mouse Up ──────────────────────────────────────────────────────────────

    const handleMouseUp = (event: MouseEvent<HTMLCanvasElement>) => {
        noteDragRef.current = null;
        if (slipDragRef.current) {
            const { clipId, clipType, startX, originalOffset } = slipDragRef.current;
            slipDragRef.current = null;
            clipDragPreviewRef.current = null;
            previewDirtyFlag.value = true;
            const { x } = getCanvasCoords(event);
            const view = timelineViewStore.value;
            if (view) {
                const deltaBeats = (x - startX) / view.pixelsPerBeat;
                if (Math.abs(deltaBeats) > 0.001) {
                    const newOffset = originalOffset + deltaBeats;
                    slipClipContent(clipId, clipType, newOffset);
                    pushUndoEntry(
                        'Slip clip content',
                        () => slipClipContent(clipId, clipType, originalOffset),
                        () => slipClipContent(clipId, clipType, newOffset)
                    );
                }
            }
            return;
        }

        if (loopDragRef.current) {
            loopDragRef.current = null;
            return;
        }

        if (autoDragRef.current) {
            const { laneId, points: drawnPoints } = autoDragRef.current;
            if (drawnPoints.length > 0) {
                const savedPoints = drawnPoints.map((param) => ({ ...param }));
                pushUndoEntry(
                    `Draw ${savedPoints.length} automation point${savedPoints.length > 1 ? 's' : ''}`,
                    () => {
                        for (const param of savedPoints) {
                            removeAutomationPoint(laneId, param.beat);
                        }
                    },
                    () => {
                        batchAddAutomationPoints(laneId, savedPoints);
                    }
                );
            }
            autoDragRef.current = null;
            return;
        }

        if (drawDragRef.current) {
            const { x } = getCanvasCoords(event);
            const endBeat = Math.ceil(getBeatFromX(x));
            const { startBeat, trackId: drawTrackId, clipType: drawClipType } = drawDragRef.current;
            const state1 = Math.min(startBeat, endBeat);
            const length = Math.max(1, Math.max(startBeat, endBeat) - state1);

            const rippleEnabled = getWorkspaceState()?.rippleEditing ?? false;
            if (rippleEnabled) {
                // Ripple insert: compute plan BEFORE adding the clip so it doesn't include the new clip
                const ripplePlan = planRippleInsert({
                    trackId: drawTrackId,
                    insertBeat: state1,
                    insertDuration: length,
                });
                const clip = addClip({
                    trackId: drawTrackId,
                    startBeat: state1,
                    endBeat: state1 + length,
                    name: `Clip ${state1}`,
                    type: drawClipType,
                });
                if (clip) {
                    if (ripplePlan && ripplePlan.shiftedClips.length > 0) {
                        rippleInsertClip({ trackId: drawTrackId, insertDuration: length, plan: ripplePlan });
                        const clipId = clip.id;
                        const savedPlan = ripplePlan;
                        pushUndoEntry(
                            'Draw clip (ripple)',
                            () => {
                                removeClip(clipId);
                                undoRippleInsertClip({ trackId: drawTrackId, plan: savedPlan });
                            },
                            () => {
                                const redrawn = addClip({
                                    trackId: drawTrackId,
                                    startBeat: state1,
                                    endBeat: state1 + length,
                                    name: `Clip ${state1}`,
                                    type: drawClipType,
                                });
                                if (redrawn) {
                                    rippleInsertClip({ trackId: drawTrackId, insertDuration: length, plan: savedPlan });
                                }
                            }
                        );
                    } else {
                        const clipId = clip.id;
                        pushUndoEntry(
                            'Draw clip',
                            () => removeClip(clipId),
                            () =>
                                addClip({
                                    trackId: drawTrackId,
                                    startBeat: state1,
                                    endBeat: state1 + length,
                                    name: `Clip ${state1}`,
                                    type: drawClipType,
                                })
                        );
                    }
                }
            } else {
                const clip = addClip({
                    trackId: drawTrackId,
                    startBeat: state1,
                    endBeat: state1 + length,
                    name: `Clip ${state1}`,
                    type: drawClipType,
                });
                if (clip) {
                    const clipId = clip.id;
                    pushUndoEntry(
                        'Draw clip',
                        () => removeClip(clipId),
                        () =>
                            addClip({
                                trackId: drawTrackId,
                                startBeat: state1,
                                endBeat: state1 + length,
                                name: `Clip ${state1}`,
                                type: drawClipType,
                            })
                    );
                }
            }
            drawDragRef.current = null;
            return;
        }

        if (rubberBandRef.current && rubberBand) {
            const view = timelineViewStore.value;
            const model = buildTimelineRenderModel();
            if (view && model) {
                const left = Math.min(rubberBand.startX, rubberBand.endX);
                const right = Math.max(rubberBand.startX, rubberBand.endX);
                const sY = view.scrollY ?? 0;
                const top = Math.min(rubberBand.startY, rubberBand.endY) + sY;
                const bottom = Math.max(rubberBand.startY, rubberBand.endY) + sY;
                const leftBeat = left / view.pixelsPerBeat + view.scrollX / view.pixelsPerBeat;
                const rightBeat = right / view.pixelsPerBeat + view.scrollX / view.pixelsPerBeat;

                const hitIds: string[] = [];
                const hitTrackIds: string[] = [];
                let trackYOffset = 0;
                for (const track of model.tracks) {
                    const h = track.height;
                    if (!(trackYOffset + h < top || trackYOffset > bottom)) {
                        hitTrackIds.push(track.id);
                        for (const clip of track.clips) {
                            if (clip.endBeat > leftBeat && clip.startBeat < rightBeat) {
                                hitIds.push(clip.id);
                            }
                        }
                    }
                    trackYOffset += h;
                }

                if (getActiveTool() === 'marquee') {
                    setMarqueeSelection({ startBeat: leftBeat, endBeat: rightBeat, trackIds: hitTrackIds });
                } else {
                    setClipSelection(hitIds);
                    setMarqueeSelection(null);
                }
            }
            rubberBandRef.current = null;
            setRubberBand(null);
            return;
        }
        rubberBandRef.current = null;
        setRubberBand(null);

        // Clicking without dragging using the marquee tool or select tool should clear the marquee selection
        if (!dragState && getActiveTool() === 'marquee') {
            setMarqueeSelection(null);
        }

        if (dragState) {
            const {
                startBeat: origStart,
                endBeat: origEnd,
                sourceTrackId: origTrackId,
                clipId: dragClipId,
                mode: dragMode,
            } = dragState;

            // Commit preview positions to the store in one batch, then clear the ref.
            const preview = clipDragPreviewRef.current;
            clipDragPreviewRef.current = null;
            previewDirtyFlag.value = true;

            if (preview && preview.positions.size > 0) {
                const primaryPos = preview.positions.get(dragClipId);
                const primaryOrig = preview.originals.get(dragClipId);

                if (dragMode === 'duplicate') {
                    // Alt+drag duplicate: originals stay, create copies at drop positions (R-B1)
                    const copiedIds: string[] = [];
                    for (const [clipId, pos] of preview.positions) {
                        duplicateClipCore(clipId, () => pos.startBeat);
                        // Track created clip for undo — duplicateClipCore adds to the track
                        const state = trackStore.value;
                        if (state) {
                            for (const time of state.tracks) {
                                if (time.id === pos.trackId) {
                                    const created = time.clips.at(-1);
                                    if (created && created.id !== clipId) {
                                        copiedIds.push(created.id);
                                    }
                                }
                            }
                        }
                    }
                    if (copiedIds.length > 0) {
                        pushUndoEntry(
                            `Duplicate ${copiedIds.length} clip${copiedIds.length > 1 ? 's' : ''}`,
                            () => {
                                for (const id of copiedIds) {
                                    removeClip(id);
                                }
                            },
                            () => {
                                // Redo: re-run duplication at saved positions
                                for (const [clipId, pos] of preview.positions) {
                                    duplicateClipCore(clipId, () => pos.startBeat);
                                }
                            }
                        );
                    }
                } else if (dragMode === 'move') {
                    const rippleEnabled = getWorkspaceState()?.rippleEditing ?? false;
                    let usedRipple = false;
                    let ripplePlan: ReturnType<typeof planRippleMove> = null;

                    for (const [clipId, pos] of preview.positions) {
                        const orig = preview.originals.get(clipId);
                        if (rippleEnabled && orig && orig.trackId === pos.trackId) {
                            const state = trackStore.value;
                            if (state) {
                                const track = state.tracks.find((time) => time.id === pos.trackId);
                                const clip = track?.clips.find((context) => context.id === clipId);
                                if (clip) {
                                    const duration = clip.endBeat - clip.startBeat;
                                    ripplePlan = planRippleMove({
                                        trackId: pos.trackId,
                                        clipId,
                                        oldStartBeat: orig.startBeat,
                                        newStartBeat: pos.startBeat,
                                        clipDuration: duration,
                                    });
                                    if (ripplePlan) {
                                        rippleMoveClip({
                                            trackId: pos.trackId,
                                            clipId,
                                            newStartBeat: pos.startBeat,
                                            clipDuration: duration,
                                            plan: ripplePlan,
                                        });
                                        usedRipple = true;
                                        continue;
                                    }
                                }
                            }
                        }
                        moveClip(clipId, pos.trackId, pos.startBeat, orig?.startBeat);
                    }

                    if (primaryPos && primaryOrig) {
                        const { trackId: newTrackId, startBeat: newStart } = primaryPos;
                        if (newStart !== primaryOrig.startBeat || newTrackId !== primaryOrig.trackId) {
                            if (usedRipple && ripplePlan) {
                                // Ripple move undo: restore clip and all shifted clips
                                const savedPlan = ripplePlan;
                                const savedDuration = origEnd - origStart;
                                pushUndoEntry(
                                    'Move clip (ripple)',
                                    () => {
                                        // Restore moved clip to original position
                                        moveClip(dragClipId, origTrackId, origStart);
                                        // Restore ripple-shifted clips to original positions
                                        const state2 = getTrackStoreState();
                                        if (state2) {
                                            const allShifted = [
                                                ...savedPlan.gapClosedClips,
                                                ...savedPlan.destinationOpenedClips,
                                            ];
                                            const shiftMap = new Map(
                                                allShifted.map((state1) => [state1.clipId, state1])
                                            );
                                            const updatedTracks = state2.tracks.map((time) => {
                                                if (time.id !== origTrackId) {
                                                    return time;
                                                }
                                                return {
                                                    ...time,
                                                    clips: time.clips.map((context) => {
                                                        const orig2 = shiftMap.get(context.id);
                                                        if (!orig2) {
                                                            return context;
                                                        }
                                                        return {
                                                            ...context,
                                                            startBeat: orig2.origStartBeat,
                                                            endBeat: orig2.origEndBeat,
                                                        };
                                                    }),
                                                };
                                            });
                                            setTrackState({ ...state2, tracks: updatedTracks });
                                        }
                                    },
                                    () => {
                                        const state2 = trackStore.value;
                                        if (state2) {
                                            const track2 = state2.tracks.find((time) => time.id === newTrackId);
                                            const clip2 = track2?.clips.find((context) => context.id === dragClipId);
                                            const dur = clip2 ? clip2.endBeat - clip2.startBeat : savedDuration;
                                            const redoPlan = planRippleMove({
                                                trackId: newTrackId,
                                                clipId: dragClipId,
                                                oldStartBeat: origStart,
                                                newStartBeat: newStart,
                                                clipDuration: dur,
                                            });
                                            if (redoPlan) {
                                                rippleMoveClip({
                                                    trackId: newTrackId,
                                                    clipId: dragClipId,
                                                    newStartBeat: newStart,
                                                    clipDuration: dur,
                                                    plan: redoPlan,
                                                });
                                            } else {
                                                moveClip(dragClipId, newTrackId, newStart);
                                            }
                                        }
                                    }
                                );
                            } else {
                                pushUndoEntry(
                                    'Move clip',
                                    () => moveClip(dragClipId, origTrackId, origStart),
                                    () => moveClip(dragClipId, newTrackId, newStart)
                                );
                            }
                        }
                    }
                } else if (dragMode === 'trim-start' && primaryPos) {
                    trimClipStart(dragClipId, primaryPos.startBeat);
                    if (primaryOrig && primaryPos.startBeat !== primaryOrig.startBeat) {
                        const newStart = primaryPos.startBeat;
                        pushUndoEntry(
                            'Trim clip start',
                            () => trimClipStart(dragClipId, origStart),
                            () => trimClipStart(dragClipId, newStart)
                        );
                    }
                } else if (dragMode === 'stretch' && primaryPos) {
                    trimClipEnd(dragClipId, primaryPos.endBeat);
                    if (primaryOrig && primaryPos.endBeat !== primaryOrig.endBeat) {
                        const newEnd = primaryPos.endBeat;
                        pushUndoEntry(
                            'Trim clip end',
                            () => trimClipEnd(dragClipId, origEnd),
                            () => trimClipEnd(dragClipId, newEnd)
                        );
                    }
                }
            }

            setDragState(null);
            if (canvasRef.current) {
                canvasRef.current.style.cursor = '';
            }
        }
    };

    // ── Double Click ──────────────────────────────────────────────────────────

    const handleDoubleClick = (event: MouseEvent<HTMLCanvasElement>) => {
        const { x, y } = getCanvasCoords(event);
        const hit = hitTestClip(x, y);
        if (hit) {
            const track = trackStore.value?.tracks.find((time) => time.id === hit.trackId);
            const clip = track?.clips.find((context) => context.id === hit.clipId);

            if (clip?.type === 'midi') {
                // R-A11: Toggle inline editing on double click
                toggleInlineEditing(hit.clipId);
            } else {
                // Fallback for audio: open full editor
                selectTrack(hit.trackId);
                selectClip(hit.clipId);
                setWorkspaceMode('clip');
            }
        }
    };

    // ── Context Menu ──────────────────────────────────────────────────────────

    const handleContextMenu = (event: MouseEvent<HTMLCanvasElement>) => {
        event.preventDefault();
        const { x, y } = getCanvasCoords(event);
        const hit = hitTestClip(x, y);
        if (hit) {
            selectTrack(hit.trackId);
            selectClip(hit.clipId);
            setContextMenu({
                kind: 'clip',
                x: event.clientX,
                y: event.clientY,
                clipId: hit.clipId,
                trackId: hit.trackId,
                splitBeat: getBeatFromX(x),
            });
        } else {
            setContextMenu({
                kind: 'empty',
                x: event.clientX,
                y: event.clientY,
                trackId: hitTestTrack(y),
                beat: Math.floor(getBeatFromX(x)),
            });
        }
    };

    // ── Pointer (pinch-zoom) ──────────────────────────────────────────────────

    const handlePointerDown = (event: React.PointerEvent<HTMLCanvasElement>) => {
        pointersRef.current.set(event.pointerId, event.nativeEvent);
    };

    const handlePointerMove = (event: React.PointerEvent<HTMLCanvasElement>) => {
        if (pointersRef.current.size === 2) {
            const prev = pointersRef.current.get(event.pointerId);
            pointersRef.current.set(event.pointerId, event.nativeEvent);
            if (!prev) {
                return;
            }
            const [p1, p2] = [...pointersRef.current.values()];
            if (!p1 || !p2) {
                return;
            }
            const prevOther = [...pointersRef.current.entries()].find(([id]) => id !== event.pointerId)?.[1];
            if (!prevOther) {
                return;
            }
            const prevDist = Math.hypot(prev.clientX - prevOther.clientX, prev.clientY - prevOther.clientY);
            const currDist = Math.hypot(p1.clientX - p2.clientX, p1.clientY - p2.clientY);
            const delta = currDist - prevDist;
            if (Math.abs(delta) > 1) {
                zoomTimeline(delta > 0 ? 2 : -2);
            }
        } else {
            pointersRef.current.set(event.pointerId, event.nativeEvent);
        }
    };

    const handlePointerUp = (event: React.PointerEvent<HTMLCanvasElement>) => {
        pointersRef.current.delete(event.pointerId);
    };

    // ── Cursor ────────────────────────────────────────────────────────────────

    const getCursor = (): string => {
        if (hoverCursor) {
            return hoverCursor;
        }
        switch (getActiveTool()) {
            case 'cut':
                return 'crosshair';
            case 'draw':
                return 'cell';
            case 'automation':
                return 'crosshair';
            case 'stretch':
                return 'ew-resize';
            default:
                return 'default';
        }
    };

    return {
        handleMouseDown,
        handleMouseMove,
        handleMouseUp,
        handleDoubleClick,
        handleContextMenu,
        handlePointerDown,
        handlePointerMove,
        handlePointerUp,
        handlePointerCancel: handlePointerUp,
        handleFileDrop,
        getCursor,
        setIsDragOver,
        isDragOver,
        isImporting,
        rubberBand,
        contextMenu,
        setContextMenu,
    };
};

import { transportStore, timeSignatureMapStore } from '#/modules/Transport/stores';

import { type TimelineRenderer } from '../../models/RendererBackend';
import { type TimelineRenderModel } from '../../models/TimelineRenderModel';
import { takeLaneStore } from '../../stores/takeLaneStore';

import { drawClip } from './clipDrawing';

export function createCanvasRenderer(canvas: HTMLCanvasElement): TimelineRenderer {
    const ctx = canvas.getContext('2d')!;
    let width = canvas.width;
    let height = canvas.height;

    function render(model: TimelineRenderModel): void {
        const dpr = window.devicePixelRatio || 1;
        ctx.clearRect(0, 0, width * dpr, height * dpr);
        ctx.save();
        ctx.scale(dpr, dpr);

        const contentHeight = height;
        ctx.save();
        ctx.beginPath();
        ctx.rect(0, 0, width, contentHeight);
        ctx.clip();
        ctx.translate(0, -model.scrollY);
        drawLoopRegion(ctx, model, contentHeight + model.scrollY);
        drawGrid(ctx, model, width, contentHeight + model.scrollY);
        drawTracks(ctx, model, width);
        drawTakeLanes(ctx, model);
        drawPlayhead(ctx, model, contentHeight + model.scrollY);
        ctx.restore();

        ctx.restore();
    }

    function resize(w: number, h: number): void {
        const dpr = window.devicePixelRatio || 1;
        width = w;
        height = h;
        canvas.width = w * dpr;
        canvas.height = h * dpr;
        canvas.style.width = `${w}px`;
        canvas.style.height = `${h}px`;
    }

    const dispose = (): void => {};

    return { backend: 'canvas2d', render, resize, dispose };
}

function drawGrid(ctx: CanvasRenderingContext2D, model: TimelineRenderModel, width: number, height: number): void {
    const { pixelsPerBeat, viewportStartBeat, timeSignatureNumerator, timeSignatureDenominator } = model;
    const startBeat = Math.floor(viewportStartBeat);
    const tsChanges = timeSignatureMapStore.value?.changes ?? [];

    let barStartBeat = 0;
    let currentNumerator = timeSignatureNumerator;
    for (const change of [...tsChanges].sort((alpha, buffer) => alpha.beat - buffer.beat)) {
        if (change.beat >= startBeat) {
            break;
        }
        const beatsInSegment = change.beat - barStartBeat;
        beatsInSegment;
        barStartBeat = change.beat;
        currentNumerator = change.numerator;
    }

    // Batch beat lines and bar lines separately to minimize strokeStyle changes
    ctx.lineWidth = 1;

    // Draw beat division lines first (#333-equivalent on #1a1a1a)
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.05)';
    ctx.beginPath();
    let tempBarStart = barStartBeat;
    let tempNumerator = currentNumerator;
    for (let beat = startBeat; beat * pixelsPerBeat < width + viewportStartBeat * pixelsPerBeat; beat++) {
        const tsChange = tsChanges.find((context) => context.beat === beat);
        if (tsChange) {
            tempBarStart = beat;
            tempNumerator = tsChange.numerator;
        }
        const isBarLine = (beat - tempBarStart) % tempNumerator === 0;
        if (!isBarLine) {
            const x = (beat - viewportStartBeat) * pixelsPerBeat;
            ctx.moveTo(x, 0);
            ctx.lineTo(x, height);
        }
    }
    ctx.stroke();

    // Draw bar lines (#555-equivalent — brighter)
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.13)';
    ctx.beginPath();
    tempBarStart = barStartBeat;
    tempNumerator = currentNumerator;
    for (let beat = startBeat; beat * pixelsPerBeat < width + viewportStartBeat * pixelsPerBeat; beat++) {
        const tsChange = tsChanges.find((context) => context.beat === beat);
        if (tsChange) {
            tempBarStart = beat;
            tempNumerator = tsChange.numerator;
        }
        const isBarLine = (beat - tempBarStart) % tempNumerator === 0;
        if (isBarLine) {
            const x = (beat - viewportStartBeat) * pixelsPerBeat;
            ctx.moveTo(x, 0);
            ctx.lineTo(x, height);
        }
    }
    ctx.stroke();

    timeSignatureDenominator;
}

const TRACK_KIND_LABELS: Record<string, string> = {
    audio: 'AUDIO',
    midi: 'MIDI',
    bus: 'BUS',
    master: 'MASTER',
    folder: 'FOLDER',
};

function getTrackYOffsets(tracks: { height: number }[]): number[] {
    const offsets: number[] = [];
    let y = 0;
    for (const track of tracks) {
        offsets.push(y);
        y += track.height;
    }
    return offsets;
}

function drawTracks(ctx: CanvasRenderingContext2D, model: TimelineRenderModel, width: number): void {
    const { tracks, selectedTrackId } = model;
    const yOffsets = getTrackYOffsets(tracks);

    for (const track of tracks) {
        const y = yOffsets[track.index]!;
        const isFolder = track.kind === 'folder';
        const h = isFolder ? 26 : track.height;
        const isSelected = track.id === selectedTrackId;
        const isEven = track.index % 2 === 0;

        // Background — #1a1a1a base with subtle alternation
        if (isFolder) {
            ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
        } else if (isSelected) {
            ctx.fillStyle = 'rgba(255, 255, 255, 0.018)';
        } else if (isEven) {
            ctx.fillStyle = 'rgba(255, 255, 255, 0.008)';
        } else {
            ctx.fillStyle = 'rgba(0, 0, 0, 0.04)';
        }
        ctx.fillRect(0, y, width, h);

        // Left accent bar
        if (isFolder) {
            // Amber/gold accent for folder
            ctx.fillStyle = 'rgba(176, 144, 64, 0.4)';
            ctx.globalAlpha = 1;
        } else {
            ctx.fillStyle = track.color;
            ctx.globalAlpha = isSelected ? 0.5 : 0.25;
        }
        ctx.fillRect(0, y, 3, h);
        ctx.globalAlpha = 1;

        if (track.muted) {
            ctx.fillStyle = 'rgba(0, 0, 0, 0.25)';
            ctx.fillRect(0, y, width, h);
        }

        // Bottom separator
        ctx.strokeStyle = isFolder ? 'rgba(255, 255, 255, 0.12)' : 'rgba(255, 255, 255, 0.06)';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(0, y + h);
        ctx.lineTo(width, y + h);
        ctx.stroke();

        if (isSelected) {
            ctx.strokeStyle = 'rgba(255, 255, 255, 0.06)';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(0, y);
            ctx.lineTo(width, y);
            ctx.stroke();
        }

        if (isFolder) {
            // Folder label
            ctx.fillStyle = 'rgba(255, 255, 255, 0.35)';
            ctx.font = '600 9px -apple-system, BlinkMacSystemFont, "SF Pro Text", system-ui, sans-serif';
            ctx.fillText(track.name.toUpperCase(), 10, y + h / 2 + 3);
        } else {
            ctx.fillStyle = 'rgba(255, 255, 255, 0.06)';
            ctx.font = '9px -apple-system, BlinkMacSystemFont, "SF Pro Text", system-ui, sans-serif';
            const kindLabel = TRACK_KIND_LABELS[track.kind] ?? '';
            if (track.clips.length === 0) {
                ctx.fillStyle = 'rgba(153, 153, 153, 0.5)';
                ctx.fillText(`${track.name}  ·  ${kindLabel}`, 8, y + h / 2 + 3);

                ctx.fillStyle = 'rgba(102, 102, 102, 0.4)';
                ctx.font = '8px -apple-system, BlinkMacSystemFont, "SF Pro Text", system-ui, sans-serif';
                ctx.fillText('Drop audio/MIDI here or use Draw tool', 8, y + h / 2 + 14);
            }

            for (const clip of track.clips) {
                drawClip(ctx, clip, model, y, h);
            }

            // H3: Render variation lanes below main clips if expanded
            if (track.variationLanes && track.variationLanes.length > 0) {
                const varLaneHeight = 24;
                for (const [index, lane] of track.variationLanes.entries()) {
                    const ly = y + h + index * varLaneHeight;

                    // Background for variation lane
                    ctx.fillStyle = 'rgba(0, 0, 0, 0.15)';
                    ctx.fillRect(0, ly, width, varLaneHeight);

                    // Lane label
                    ctx.fillStyle = 'rgba(255, 255, 255, 0.2)';
                    ctx.font = '7px system-ui';
                    ctx.fillText(lane.name, 4, ly + 14);

                    for (const clip of lane.clips) {
                        drawClip(ctx, clip, model, ly, varLaneHeight);
                    }

                    // Separator
                    ctx.strokeStyle = 'rgba(255, 255, 255, 0.04)';
                    ctx.beginPath();
                    ctx.moveTo(0, ly + varLaneHeight);
                    ctx.lineTo(width, ly + varLaneHeight);
                    ctx.stroke();
                }
            }
        }
    }
}

function drawPlayhead(ctx: CanvasRenderingContext2D, model: TimelineRenderModel, height: number): void {
    const { playheadPosition, viewportStartBeat, pixelsPerBeat } = model;
    const x = (playheadPosition - viewportStartBeat) * pixelsPerBeat;

    // Playhead line — slightly brighter, clean 1px
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.85)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(x, 0);
    ctx.lineTo(x, height);
    ctx.stroke();

    // Playhead triangle indicator
    ctx.fillStyle = 'rgba(224, 224, 224, 0.95)';
    ctx.beginPath();
    ctx.moveTo(x - 4, 0);
    ctx.lineTo(x + 4, 0);
    ctx.lineTo(x, 6);
    ctx.closePath();
    ctx.fill();
}

function drawTakeLanes(ctx: CanvasRenderingContext2D, model: TimelineRenderModel): void {
    const takeState = takeLaneStore.value;
    if (!takeState || takeState.lanes.length === 0) {
        return;
    }

    const { pixelsPerBeat, viewportStartBeat, tracks } = model;
    const yOffsets = getTrackYOffsets(tracks);

    for (const lane of takeState.lanes) {
        const trackIndex = tracks.findIndex((time) => time.id === lane.trackId);
        if (trackIndex < 0) {
            continue;
        }

        const trackY = yOffsets[trackIndex]!;
        const h = tracks[trackIndex]!.height;
        const laneHeight = 16;

        for (let index = 0; index < lane.takes.length; index++) {
            const take = lane.takes[index]!;
            const x = (take.startBeat - viewportStartBeat) * pixelsPerBeat;
            const w = (take.endBeat - take.startBeat) * pixelsPerBeat;
            const y = trackY + h - laneHeight * (index + 1) - 2;

            ctx.fillStyle = take.selected ? 'rgba(255, 255, 255, 0.08)' : 'rgba(255, 255, 255, 0.03)';
            ctx.fillRect(x, y, w, laneHeight - 1);

            ctx.strokeStyle = take.selected ? 'rgba(255, 255, 255, 0.2)' : 'rgba(255, 255, 255, 0.08)';
            ctx.lineWidth = 1;
            ctx.strokeRect(x, y, w, laneHeight - 1);

            ctx.fillStyle = 'rgba(255, 255, 255, 0.5)';
            ctx.font = '7px system-ui';
            ctx.fillText(take.name, x + 2, y + 10, w - 4);
        }

        for (const region of lane.activeCompRegions) {
            const x = (region.startBeat - viewportStartBeat) * pixelsPerBeat;
            const w = (region.endBeat - region.startBeat) * pixelsPerBeat;

            ctx.fillStyle = 'rgba(80, 160, 110, 0.12)';
            ctx.fillRect(x, trackY, w, h);
        }
    }
}

function drawLoopRegion(ctx: CanvasRenderingContext2D, model: TimelineRenderModel, height: number): void {
    const transport = transportStore.value;
    if (!transport?.isLooping) {
        return;
    }

    const { pixelsPerBeat, viewportStartBeat } = model;
    const x1 = (transport.loopStart - viewportStartBeat) * pixelsPerBeat;
    const x2 = (transport.loopEnd - viewportStartBeat) * pixelsPerBeat;

    ctx.fillStyle = 'rgba(255, 255, 255, 0.03)';
    ctx.fillRect(x1, 0, x2 - x1, height);

    ctx.strokeStyle = 'rgba(255, 255, 255, 0.15)';
    ctx.lineWidth = 1;
    ctx.setLineDash([4, 4]);
    ctx.beginPath();
    ctx.moveTo(x1, 0);
    ctx.lineTo(x1, height);
    ctx.moveTo(x2, 0);
    ctx.lineTo(x2, height);
    ctx.stroke();
    ctx.setLineDash([]);
}

/**
 * WebGPU Automation Renderer.
 * Renders all visible automation lanes in a single unified pipeline.
 * R-F1: Single unified draw call for all automation curves.
 */

const WGSL_SHADER = /* wgsl */ `
struct VertexOut {
    @builtin(position) pos : vec4f,
    @location(0)       col : vec4f,
}

@vertex
fn vs_main(
    @location(0) xy : vec2f,
    @location(1) col: vec4f,
) -> VertexOut {
    var out : VertexOut;
    out.pos = vec4f(xy, 0.0, 1.0);
    out.col = col;
    return out;
}

@fragment
fn fs_main(@location(0) col: vec4f) -> @location(0) vec4f {
    return col;
}
`;

export type AutomationRenderModel = {
    lanes: {
        points: { beat: number; value: number }[];
        ghostPoints?: { beat: number; value: number }[];
        y: number;
        height: number;
        color: string;
        minValue: number;
        maxValue: number;
    }[];
    viewportStartBeat: number;
    pixelsPerBeat: number;
    width: number;
    height: number;
};

export type AutomationRenderer = {
    render(model: AutomationRenderModel): void;
    dispose(): void;
};

function hexToRgb(hex: string): [number, number, number] {
    const r = parseInt(hex.slice(1, 3), 16) / 255;
    const g = parseInt(hex.slice(3, 5), 16) / 255;
    const b = parseInt(hex.slice(5, 7), 16) / 255;
    return isNaN(r) || isNaN(g) || isNaN(b) ? [0.6, 0.5, 1.0] : [r, g, b];
}

export async function createWebGpuAutomationRenderer(canvas: HTMLCanvasElement): Promise<AutomationRenderer | null> {
    if (!navigator.gpu) {
        return null;
    }

    const adapter = await navigator.gpu.requestAdapter();
    if (!adapter) {
        return null;
    }
    const device = await adapter.requestDevice();
    const context = canvas.getContext('webgpu')!;
    const format = navigator.gpu.getPreferredCanvasFormat();
    context.configure({ device, format, alphaMode: 'premultiplied' });

    const shader = device.createShaderModule({ code: WGSL_SHADER });
    const pipeline = device.createRenderPipeline({
        layout: 'auto',
        vertex: {
            module: shader,
            entryPoint: 'vs_main',
            buffers: [
                {
                    arrayStride: 6 * 4,
                    attributes: [
                        { shaderLocation: 0, offset: 0, format: 'float32x2' }, // xy
                        { shaderLocation: 1, offset: 2 * 4, format: 'float32x4' }, // rgba
                    ],
                },
            ],
        },
        fragment: {
            module: shader,
            entryPoint: 'fs_main',
            targets: [
                {
                    format,
                    blend: {
                        color: { srcFactor: 'src-alpha', dstFactor: 'one-minus-src-alpha', operation: 'add' },
                        alpha: { srcFactor: 'one', dstFactor: 'one-minus-src-alpha', operation: 'add' },
                    },
                },
            ],
        },
        primitive: { topology: 'triangle-list' },
    });

    const MAX_VERTICES = 100000;
    const vertexBuffer = device.createBuffer({
        size: MAX_VERTICES * 6 * 4,
        usage: GPUBufferUsage.VERTEX | GPUBufferUsage.COPY_DST,
    });

    const cpuBuf = new Float32Array(MAX_VERTICES * 6);

    function render(model: AutomationRenderModel) {
        let vIdx = 0;
        const { viewportStartBeat, pixelsPerBeat, width, height } = model;

        function addRect(
            x1: number,
            y1: number,
            x2: number,
            y2: number,
            r: number,
            g: number,
            b: number,
            alpha: number
        ) {
            if (vIdx + 36 >= MAX_VERTICES * 6) {
                return;
            }
            const nx1 = (x1 / width) * 2 - 1;
            const nx2 = (x2 / width) * 2 - 1;
            const ny1 = 1 - (y1 / height) * 2;
            const ny2 = 1 - (y2 / height) * 2;

            const verts = [
                nx1,
                ny1,
                r,
                g,
                b,
                alpha,
                nx2,
                ny1,
                r,
                g,
                b,
                alpha,
                nx1,
                ny2,
                r,
                g,
                b,
                alpha,
                nx2,
                ny1,
                r,
                g,
                b,
                alpha,
                nx2,
                ny2,
                r,
                g,
                b,
                alpha,
                nx1,
                ny2,
                r,
                g,
                b,
                alpha,
            ];
            cpuBuf.set(verts, vIdx);
            vIdx += 36;
        }

        for (const lane of model.lanes) {
            const [r, g, b] = hexToRgb(lane.color.startsWith('#') ? lane.color : '#a78bfa');

            // Draw ghost points (faded)
            if (lane.ghostPoints && lane.ghostPoints.length >= 2) {
                for (let index = 0; index < lane.ghostPoints.length - 1; index++) {
                    const p1 = lane.ghostPoints[index]!;
                    const p2 = lane.ghostPoints[index + 1]!;
                    const x1 = (p1.beat - viewportStartBeat) * pixelsPerBeat;
                    const x2 = (p2.beat - viewportStartBeat) * pixelsPerBeat;
                    if (x2 < 0 || x1 > width) {
                        continue;
                    }
                    const v1 = (p1.value - lane.minValue) / (lane.maxValue - lane.minValue);
                    const v2 = (p2.value - lane.minValue) / (lane.maxValue - lane.minValue);
                    const y1 = lane.y + lane.height * (1 - v1);
                    const y2 = lane.y + lane.height * (1 - v2);
                    addRect(x1, y1 - 0.5, x2, y2 + 0.5, r, g, b, 0.25);
                }
            }

            if (lane.points.length < 2) {
                continue;
            }

            for (let index = 0; index < lane.points.length - 1; index++) {
                const p1 = lane.points[index]!;
                const p2 = lane.points[index + 1]!;

                const x1 = (p1.beat - viewportStartBeat) * pixelsPerBeat;
                const x2 = (p2.beat - viewportStartBeat) * pixelsPerBeat;

                if (x2 < 0 || x1 > width) {
                    continue;
                }

                const v1 = (p1.value - lane.minValue) / (lane.maxValue - lane.minValue);
                const v2 = (p2.value - lane.minValue) / (lane.maxValue - lane.minValue);

                const y1 = lane.y + lane.height * (1 - v1);
                const y2 = lane.y + lane.height * (1 - v2);

                // Simple version: draw 2px thick line
                addRect(x1, y1 - 1, x2, y2 + 1, r, g, b, 0.8);
            }
        }

        if (vIdx === 0) {
            return;
        }

        device.queue.writeBuffer(vertexBuffer, 0, cpuBuf, 0, vIdx);
        const encoder = device.createCommandEncoder();
        const view = context.getCurrentTexture().createView();
        const pass = encoder.beginRenderPass({
            colorAttachments: [
                {
                    view,
                    clearValue: { r: 0, g: 0, b: 0, a: 0 },
                    loadOp: 'clear',
                    storeOp: 'store',
                },
            ],
        });
        pass.setPipeline(pipeline);
        pass.setVertexBuffer(0, vertexBuffer);
        pass.draw(vIdx / 6);
        pass.end();
        device.queue.submit([encoder.finish()]);
    }

    return { render, dispose: () => device.destroy() };
}

import { audioBufferCache } from '#/modules/AudioEngine/stores';
import { resolveToken } from '#/utils/UI/resolveToken';

import { type TimelineRenderer } from '../../models/RendererBackend';
import { type TimelineRenderModel } from '../../models/TimelineRenderModel';

// ─── WGSL shaders ────────────────────────────────────────────────────────────
// Each vertex carries: xy (NDC) + rgba (f32 × 4) = 6 floats = 24 bytes
const WGSL_SHADER = /* wgsl */ `
struct VertexOut {
    @builtin(position) pos : vec4f,
    @location(0)       col : vec4f,
}

@vertex
fn vs_main(
    @location(0) xy : vec2f,
    @location(1) col: vec4f,
) -> VertexOut {
    var out : VertexOut;
    out.pos = vec4f(xy, 0.0, 1.0);
    out.col = col;
    return out;
}

@fragment
fn fs_main(@location(0) col: vec4f) -> @location(0) vec4f {
    return col;
}
`;

// Floats per vertex: xy (2) + rgba (4) = 6
const FLOATS_PER_VERTEX = 6;
// 2 triangles per rect = 6 vertices
const VERTICES_PER_RECT = 6;
const FLOATS_PER_RECT = VERTICES_PER_RECT * FLOATS_PER_VERTEX;
// Upper bound: many tracks × many clips + track rows + playhead + bar lines, now + waveform rects
const MAX_RECTS = 32768;

// ─── Colour helpers ───────────────────────────────────────────────────────────
/** Parse hex (#rrggbb / #rgb) OR oklch(L C H) into [r, g, b, a] with values in 0..1 */
function colorToRgba(color: string, alpha = 1): [number, number, number, number] {
    // oklch(L C H) → OKLab → linear sRGB → sRGB
    const oklchMatch = color.match(/oklch\(([\d.]+)\s+([\d.]+)\s+([\d.]+)\)/);
    if (oklchMatch) {
        const L = parseFloat(oklchMatch[1]!);
        const C = parseFloat(oklchMatch[2]!);
        const H = parseFloat(oklchMatch[3]!) * (Math.PI / 180);
        const a_ = C * Math.cos(H);
        const b_ = C * Math.sin(H);
        // OKLab → linear sRGB (approximate via LMS)
        const l_ = L + 0.3963377774 * a_ + 0.2158037573 * b_;
        const m_ = L - 0.1055613458 * a_ - 0.0638541728 * b_;
        const s_ = L - 0.0894841775 * a_ - 1.291485548 * b_;
        const l3 = l_ * l_ * l_;
        const m3 = m_ * m_ * m_;
        const s3 = s_ * s_ * s_;
        const lr = +4.0767416621 * l3 - 3.3077115913 * m3 + 0.2309699292 * s3;
        const lg = -1.2684380046 * l3 + 2.6097574011 * m3 - 0.3413193965 * s3;
        const lb = -0.0041960863 * l3 - 0.7034186147 * m3 + 1.707614701 * s3;
        // Linear → sRGB gamma, clamped to [0,1]
        const gamma = (x: number): number => {
            const value = x <= 0.0031308 ? 12.92 * x : 1.055 * x ** (1 / 2.4) - 0.055;
            return Math.max(0, Math.min(1, value));
        };
        return [gamma(lr), gamma(lg), gamma(lb), alpha];
    }

    // Hex fallback
    const clean = color.replace('#', '');
    if (clean.length === 3) {
        const r = parseInt(clean[0]! + clean[0]!, 16) / 255;
        const gain = parseInt(clean[1]! + clean[1]!, 16) / 255;
        const buffer = parseInt(clean[2]! + clean[2]!, 16) / 255;
        return [r, gain, buffer, alpha];
    }
    const r = parseInt(clean.slice(0, 2), 16) / 255;
    const gain = parseInt(clean.slice(2, 4), 16) / 255;
    const buffer = parseInt(clean.slice(4, 6), 16) / 255;
    return [isNaN(r) ? 0.4 : r, isNaN(gain) ? 0.4 : gain, isNaN(buffer) ? 0.4 : buffer, alpha];
}

// ─── Geometry helper ──────────────────────────────────────────────────────────
/**
 * Push a screen-space rectangle into the Float32Array vertex buffer.
 * Coordinates are in pixels; we convert to NDC using canvas dimensions.
 */
function pushRect(
    buf: Float32Array,
    offset: number,
    x1: number,
    y1: number,
    x2: number,
    y2: number,
    r: number,
    gain: number,
    buffer: number,
    alpha: number,
    w: number,
    h: number
): number {
    // Convert pixel coords → NDC (WebGPU: Y+ is up)
    const nx1 = (x1 / w) * 2 - 1;
    const nx2 = (x2 / w) * 2 - 1;
    const ny1 = 1 - (y1 / h) * 2;
    const ny2 = 1 - (y2 / h) * 2;

    // Triangle 1: top-left, top-right, bottom-left
    // Triangle 2: top-right, bottom-right, bottom-left
    const verts: number[] = [
        nx1,
        ny1,
        r,
        gain,
        buffer,
        alpha,
        nx2,
        ny1,
        r,
        gain,
        buffer,
        alpha,
        nx1,
        ny2,
        r,
        gain,
        buffer,
        alpha,
        nx2,
        ny1,
        r,
        gain,
        buffer,
        alpha,
        nx2,
        ny2,
        r,
        gain,
        buffer,
        alpha,
        nx1,
        ny2,
        r,
        gain,
        buffer,
        alpha,
    ];
    buf.set(verts, offset);
    return offset + FLOATS_PER_RECT;
}

// ─── Main factory ─────────────────────────────────────────────────────────────
export async function createWebGpuRenderer(canvas: HTMLCanvasElement): Promise<TimelineRenderer | null> {
    if (!navigator.gpu) {
        return null;
    }

    try {
        const adapter = await navigator.gpu.requestAdapter();
        if (!adapter) {
            return null;
        }

        const device = await adapter.requestDevice();
        const gpuContext = canvas.getContext('webgpu');
        if (!gpuContext) {
            return null;
        }

        const format = navigator.gpu.getPreferredCanvasFormat();
        gpuContext.configure({ device, format, alphaMode: 'premultiplied' });

        // ─── Shader & pipeline ────────────────────────────────────────────
        const shaderModule = device.createShaderModule({ code: WGSL_SHADER });

        const pipeline = device.createRenderPipeline({
            layout: 'auto',
            vertex: {
                module: shaderModule,
                entryPoint: 'vs_main',
                buffers: [
                    {
                        arrayStride: FLOATS_PER_VERTEX * 4, // bytes
                        attributes: [
                            { shaderLocation: 0, offset: 0, format: 'float32x2' }, // xy
                            { shaderLocation: 1, offset: 2 * 4, format: 'float32x4' }, // rgba
                        ],
                    },
                ],
            },
            fragment: {
                module: shaderModule,
                entryPoint: 'fs_main',
                targets: [
                    {
                        format,
                        blend: {
                            color: {
                                srcFactor: 'src-alpha',
                                dstFactor: 'one-minus-src-alpha',
                                operation: 'add',
                            },
                            alpha: {
                                srcFactor: 'one',
                                dstFactor: 'one-minus-src-alpha',
                                operation: 'add',
                            },
                        },
                    },
                ],
            },
            primitive: { topology: 'triangle-list' },
        });

        // ─── Vertex buffer (CPU-mapped every frame) ───────────────────────
        const maxBytes = MAX_RECTS * FLOATS_PER_RECT * 4;
        const cpuBuf = new Float32Array(MAX_RECTS * FLOATS_PER_RECT);

        let gpuBuf = device.createBuffer({
            size: maxBytes,
            usage: GPUBufferUsage.VERTEX | GPUBufferUsage.COPY_DST,
        });

        let canvasW = canvas.width;
        let canvasH = canvas.height;

        // ─── Per-frame render ─────────────────────────────────────────────
        function render(model: TimelineRenderModel): void {
            const w = canvasW;
            const h = canvasH;
            if (w <= 0 || h <= 0) {
                return;
            }
            const dpr = window.devicePixelRatio || 1;

            // Viewport beat range → pixel helpers
            const { viewportStartBeat, pixelsPerBeat, scrollY, selectedClipIds, selectedTrackId, playheadPosition } =
                model;

            function beatToX(beat: number): number {
                return (beat - viewportStartBeat) * pixelsPerBeat * dpr;
            }

            let offset = 0;
            let rectCount = 0;

            function addRect(x1: number, y1: number, x2: number, y2: number, color: string, alpha = 1): void {
                if (rectCount >= MAX_RECTS) {
                    return;
                }
                const [r, gain, buffer1] = colorToRgba(color, alpha);
                offset = pushRect(cpuBuf, offset, x1, y1, x2, y2, r, gain, buffer1, alpha, w, h);
                rectCount++;
            }

            // 1. Track background rows
            let trackY = -scrollY * dpr;
            for (const track of model.tracks) {
                const th = track.height * dpr;
                const isSelected = track.id === selectedTrackId;
                const bg = isSelected
                    ? resolveToken('--color-bg-well', '#0d0d0d')
                    : resolveToken('--color-bg-tray', '#0a0a0a');
                addRect(0, trackY, w, trackY + th, bg);
                // Row separator line
                addRect(0, trackY + th - dpr, w, trackY + th, '#000000', 0.6);
                trackY += th;
            }

            // 2. Clips
            trackY = -scrollY * dpr;
            for (const track of model.tracks) {
                const th = track.height * dpr;
                const clipTop = trackY + 2 * dpr;
                const clipBottom = trackY + th - 2 * dpr;

                for (const clip of track.clips) {
                    const cx1 = beatToX(clip.startBeat);
                    const cx2 = beatToX(clip.endBeat);
                    if (cx2 < 0 || cx1 > w) {
                        continue;
                    }
                    const isSelected = selectedClipIds.includes(clip.id);
                    const alpha = clip.muted ? 0.35 : 1.0;

                    // Clip body
                    const color = clip.color || track.color || 'oklch(0.40 0.08 250)';
                    addRect(cx1, clipTop, cx2, clipBottom, color, alpha * 1);

                    // Clip top accent stripe
                    addRect(cx1, clipTop, cx2, clipTop + 3 * dpr, color, alpha);

                    // Selection highlight — warm metallic border + inner brightening
                    if (isSelected) {
                        // Inner brightening overlay to make clip pop
                        addRect(cx1, clipTop, cx2, clipBottom, '#ffffff', 0.06);
                        // Warm metallic border (2px, high alpha)
                        const bw = 2 * dpr;
                        addRect(cx1, clipTop, cx2, clipTop + bw, 'oklch(0.62 0.05 55)', 0.75);
                        addRect(cx1, clipTop, cx1 + bw, clipBottom, 'oklch(0.62 0.05 55)', 0.75);
                        addRect(cx2 - bw, clipTop, cx2, clipBottom, 'oklch(0.62 0.05 55)', 0.75);
                        addRect(cx1, clipBottom - bw, cx2, clipBottom, 'oklch(0.62 0.05 55)', 0.75);
                    }

                    // MIDI mini-notes
                    if (clip.type === 'midi' && clip.midiNotes.length > 0) {
                        // §70.3 — Single-pass min/max without allocating a
                        // pitches[] or spreading into Math.min/.max. Per-frame
                        // per-clip hot path; MIDI clips can have thousands of
                        // notes and Math.max(...arr) would stack-overflow on
                        // large spreads.
                        let minPitch = clip.midiNotes[0]!.pitch;
                        let maxPitch = minPitch;
                        for (let index = 1; index < clip.midiNotes.length; index++) {
                            const param = clip.midiNotes[index]!.pitch;
                            if (param < minPitch) {
                                minPitch = param;
                            } else if (param > maxPitch) {
                                maxPitch = param;
                            }
                        }
                        const pitchRange = Math.max(maxPitch - minPitch, 12);
                        const noteAreaH = clipBottom - clipTop - 10 * dpr;

                        const clipDuration = clip.endBeat - clip.startBeat;
                        const loopLen = clip.loopEnabled && clip.loopLength ? clip.loopLength : clipDuration;
                        const midiOffset = clip.midiOffsetBeats ?? 0;

                        let loopOffset = 0;
                        let drawnNotes = 0;
                        const MAX_NOTES_PER_CLIP = 300;

                        while (loopOffset < clipDuration) {
                            for (const note of clip.midiNotes) {
                                if (drawnNotes >= MAX_NOTES_PER_CLIP) {
                                    break;
                                }

                                // note.startBeat is absolute (timeline position).
                                // Convert to clip-relative, then add loop offset.
                                const noteRelative = note.startBeat - midiOffset - clip.startBeat;
                                const relBeat = noteRelative + loopOffset;
                                const noteEndRelative = relBeat + Math.max(note.duration, 0.125);
                                if (noteEndRelative <= 0 || relBeat >= clipDuration) {
                                    continue;
                                }

                                const nx1 = beatToX(clip.startBeat + relBeat);
                                const nx2 = beatToX(clip.startBeat + noteEndRelative);
                                if (nx2 < cx1 || nx1 > cx2) {
                                    continue;
                                }
                                const noteY = clipBottom - 5 * dpr - ((note.pitch - minPitch) / pitchRange) * noteAreaH;
                                const finalX1 = Math.max(nx1, cx1 + 2);
                                const finalX2 = Math.min(nx2, cx2 - 2);
                                if (finalX1 < finalX2) {
                                    addRect(finalX1, noteY - dpr, finalX2, noteY + 2 * dpr, '#ffffff', alpha * 0.35);
                                }
                                drawnNotes++;
                            }
                            if (drawnNotes >= MAX_NOTES_PER_CLIP) {
                                break;
                            }
                            loopOffset += loopLen;
                            if (!clip.loopEnabled || loopLen <= 0) {
                                break;
                            }
                        }
                    }

                    // AUDIO waveform peaks
                    if (clip.type === 'audio' && clip.audioBufferId && audioBufferCache.has(clip.audioBufferId)) {
                        const w = cx2 - cx1;
                        if (w >= 4) {
                            // At least 1 rect per pixel, up to max ~2000 bins to balance perf
                            const numBins = Math.min(Math.floor(w * dpr), 2000);

                            const buffer = audioBufferCache.get(clip.audioBufferId);
                            if (buffer) {
                                const offsetBeats = clip.audioOffsetBeats ?? 0;
                                const stretchRatio = clip.stretchRatio ?? 1;
                                const clipBeats = clip.endBeat - clip.startBeat;
                                const secondsPerBeat = 60 / model.tempo;
                                const sampleRate = buffer.sampleRate;
                                const startSample = Math.max(0, Math.floor(offsetBeats * secondsPerBeat * sampleRate));
                                const beatsConsumed = clipBeats / Math.max(stretchRatio, 0.0001);
                                const endSample = Math.floor(startSample + beatsConsumed * secondsPerBeat * sampleRate);

                                const peaks = audioBufferCache.getWaveformPeaks(clip.audioBufferId, numBins, {
                                    startSample,
                                    endSample,
                                });

                                const midY = clipTop + (clipBottom - clipTop) / 2;
                                const padding = 2 * dpr;
                                const amplitude = (clipBottom - clipTop - padding * 2) * 0.35;

                                // White with transparency — matches MIDI note style
                                const wfColor = '#ffffff';

                                const binsToDraw = peaks.length;
                                if (binsToDraw > 0) {
                                    const drawBinWidth = w / binsToDraw;

                                    for (let index = 0; index < binsToDraw; index++) {
                                        const peakHeight = (peaks[index] ?? 0) * amplitude;
                                        if (peakHeight > 0.5) {
                                            const bx1 = cx1 + index * drawBinWidth;
                                            const bx2 = bx1 + drawBinWidth;
                                            addRect(
                                                bx1,
                                                midY - peakHeight,
                                                bx2,
                                                midY + peakHeight,
                                                wfColor,
                                                alpha * 0.18
                                            );
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
                trackY += track.height * dpr;
            }

            // 3. Bar / beat grid lines
            const barBeats = model.timeSignatureNumerator;
            const firstBar = Math.floor(viewportStartBeat / barBeats);
            const lastBar = Math.ceil((viewportStartBeat + w / pixelsPerBeat / dpr) / barBeats) + 1;
            for (let bar = firstBar; bar <= lastBar; bar++) {
                const beat = bar * barBeats;
                const gx = beatToX(beat);
                if (gx < 0 || gx > w) {
                    continue;
                }
                addRect(gx, 0, gx + dpr, h, '#ffffff', bar % 4 === 0 ? 0.08 : 0.04);
            }

            // 4. Playhead
            const phX = beatToX(playheadPosition);
            if (phX >= 0 && phX <= w) {
                addRect(phX - dpr, 0, phX + dpr, h, resolveToken('--color-state-record', '#c45040'), 0.9); // red needle
                addRect(
                    phX - 4 * dpr,
                    0,
                    phX + 4 * dpr,
                    12 * dpr,
                    resolveToken('--color-state-record', '#c45040'),
                    0.9
                ); // head cap
            }

            if (rectCount === 0) {
                return;
            }

            // Upload vertex data
            device.queue.writeBuffer(gpuBuf, 0, cpuBuf, 0, rectCount * FLOATS_PER_RECT);

            // Record + submit
            const encoder = device.createCommandEncoder();
            const textureView = gpuContext!.getCurrentTexture().createView();
            const renderPass = encoder.beginRenderPass({
                colorAttachments: [
                    {
                        view: textureView,
                        clearValue: { r: 0.07, g: 0.07, b: 0.07, a: 1.0 },
                        loadOp: 'clear' as GPULoadOp,
                        storeOp: 'store' as GPUStoreOp,
                    },
                ],
            });

            renderPass.setPipeline(pipeline);
            renderPass.setVertexBuffer(0, gpuBuf);
            renderPass.draw(rectCount * VERTICES_PER_RECT);
            renderPass.end();
            device.queue.submit([encoder.finish()]);
        }

        function resize(w: number, h: number): void {
            const dpr = window.devicePixelRatio || 1;
            const pw = Math.round(w * dpr);
            const ph = Math.round(h * dpr);
            if (pw <= 0 || ph <= 0) {
                return;
            }
            canvasW = pw;
            canvasH = ph;
            canvas.width = pw;
            canvas.height = ph;
            canvas.style.width = `${w}px`;
            canvas.style.height = `${h}px`;
            gpuContext!.configure({ device, format, alphaMode: 'premultiplied' });

            // Recreate GPU buffer if sizing up
            const needed = MAX_RECTS * FLOATS_PER_RECT * 4;
            if (gpuBuf.size < needed) {
                gpuBuf.destroy();
                gpuBuf = device.createBuffer({
                    size: needed,
                    usage: GPUBufferUsage.VERTEX | GPUBufferUsage.COPY_DST,
                });
            }
        }

        function dispose(): void {
            gpuBuf.destroy();
            device.destroy();
        }

        return { backend: 'webgpu', render, resize, dispose };
    } catch {
        return null;
    }
}

