import { useRef, useEffect, type MouseEvent } from 'react';

import { useStore } from '#/infra/store/useStore';
import { transportStore, playheadPositionRef } from '#/modules/Transport/stores';
import { type TransportState, seekPlayhead, setLoopRegion, disableLooping } from '#/modules/Transport/useCases';
import { animationScheduler } from '#/utils/DOM/AnimationScheduler';

import { timelineViewStore, type TimelineViewState } from '../../stores/timelineViewStore';

import { TimelineChromeSurface } from './TimelineChromeSurface';

const HEIGHT = 18;

export const BeatRulerBar = (): React.ReactElement => {
    const containerRef = useRef<HTMLDivElement | null>(null);
    const canvasRef = useRef<HTMLCanvasElement | null>(null);
    const loopDragRef = useRef<{ startBeat: number } | null>(null);
    /** Ephemeral loop preview during shift+drag — avoids flooding transportStore with 60Hz writes. */
    const loopPreviewRef = useRef<{ start: number; end: number } | null>(null);
    /** Active scrub drag (R-B6): normal drag scrubs the playhead without setting a loop. */
    const scrubDragRef = useRef<boolean>(false);
    /**
     * §182.1 — per-canvas cache of last-seen dimensions + the background
     * gradient for that height, so the rAF draw loop doesn't
     * re-instantiate the same LinearGradient every frame and doesn't
     * reset the canvas backing store + DPR scale when nothing changed.
     */
    const canvasCacheRef = useRef<{
        cssWidth: number;
        cssHeight: number;
        dpr: number;
        bgGradient: CanvasGradient;
    } | null>(null);

    const defaultTimelineView: TimelineViewState = {
        scrollX: 0,
        scrollY: 0,
        pixelsPerBeat: 12,
        autoScrollEnabled: true,
    };
    const defaultTransport: TransportState = {
        isPlaying: false,
        isRecording: false,
        isLooping: false,
        overdubEnabled: false,
        metronomeEnabled: false,
        metronomeVolume: 0.5,
        tempo: 120,
        timeSignatureNumerator: 4,
        timeSignatureDenominator: 4,
        playheadPosition: 0,
        loopStart: 0,
        loopEnd: 0,
        scheduleGrainMs: 10,
        punchInEnabled: false,
        punchInBeat: 0,
        punchOutBeat: 16,
        countInEnabled: false,
        countInBars: 1,
        preRollEnabled: false,
        preRollBars: 2,
        masterGain: 80,
    };
    const viewState = useStore(timelineViewStore, defaultTimelineView);
    const transport = useStore(transportStore, defaultTransport);

    const pixelsPerBeat = viewState.pixelsPerBeat;
    const scrollX = viewState.scrollX;
    const loopStart = transport.loopStart;
    const loopEnd = transport.loopEnd;
    const isLooping = transport.isLooping;
    const isPlaying = transport.isPlaying;
    const timeSigNum = transport.timeSignatureNumerator;

    // Draw the ruler via canvas
    const drawRuler = (canvas: HTMLCanvasElement, playhead: number = playheadPositionRef.current) => {
        const ctx = canvas.getContext('2d');
        if (!ctx) {
            return;
        }
        const dpr = window.devicePixelRatio || 1;
        const w = canvas.offsetWidth;
        const h = HEIGHT;

        // §182.1 — only resize the backing store + recompute the DPR
        // scale + rebuild the background gradient when the dimensions
        // actually change. Per-frame this is a cache hit.
        const cache = canvasCacheRef.current;
        let bgGrad: CanvasGradient;
        if (!cache || cache.cssWidth !== w || cache.cssHeight !== h || cache.dpr !== dpr) {
            canvas.width = w * dpr;
            canvas.height = h * dpr;
            ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
            bgGrad = ctx.createLinearGradient(0, 0, 0, h);
            bgGrad.addColorStop(0, '#151518');
            bgGrad.addColorStop(1, '#111114');
            canvasCacheRef.current = { cssWidth: w, cssHeight: h, dpr, bgGradient: bgGrad };
        } else {
            bgGrad = cache.bgGradient;
        }

        // Background — subtle gradient for depth
        ctx.fillStyle = bgGrad;
        ctx.fillRect(0, 0, w, h);

        // Loop region — during drag, use ephemeral preview ref to avoid flooding transportStore
        const effectiveLoopStart = loopPreviewRef.current?.start ?? loopStart;
        const effectiveLoopEnd = loopPreviewRef.current?.end ?? loopEnd;
        const effectiveIsLooping = isLooping || loopPreviewRef.current !== null;
        if (effectiveIsLooping && effectiveLoopEnd > effectiveLoopStart) {
            const lx = effectiveLoopStart * pixelsPerBeat - scrollX;
            const lw = (effectiveLoopEnd - effectiveLoopStart) * pixelsPerBeat;
            ctx.fillStyle = 'rgba(74, 144, 217, 0.15)';
            ctx.fillRect(lx, 0, lw, h);
            // Loop region handles — accent blue
            ctx.fillStyle = 'rgba(74, 144, 217, 0.65)';
            ctx.fillRect(lx, 0, 2, h);
            ctx.fillRect(lx + lw - 2, 0, 2, h);
        }

        // Bar numbers & beat ticks
        const viewportStartBeat = scrollX / pixelsPerBeat;
        const beatsVisible = w / pixelsPerBeat;
        const beatsPerBar = timeSigNum;

        // Determine label interval based on zoom
        const barPixels = beatsPerBar * pixelsPerBeat;
        const labelEvery = barPixels < 40 ? Math.ceil(40 / barPixels) : 1;

        ctx.font = '500 9px -apple-system, BlinkMacSystemFont, "SF Pro Text", system-ui, sans-serif';

        const firstBar = Math.floor(viewportStartBeat / beatsPerBar);
        const lastBar = Math.ceil((viewportStartBeat + beatsVisible) / beatsPerBar) + 1;

        for (let bar = firstBar; bar < lastBar; bar++) {
            const barBeat = bar * beatsPerBar;
            const barX = (barBeat - viewportStartBeat) * pixelsPerBeat;

            // Alternating bar background — Logic Pro-style visual grouping
            if (bar % 2 === 1) {
                ctx.fillStyle = 'rgba(255, 255, 255, 0.025)';
                ctx.fillRect(barX, 0, barPixels, h);
            }

            // 4-bar group emphasis: brighter line at every 4th bar
            const is4BarBoundary = bar % 4 === 0;
            const is8BarBoundary = bar % 8 === 0;

            if (is8BarBoundary) {
                ctx.strokeStyle = 'rgba(255, 255, 255, 0.35)';
                ctx.lineWidth = 1;
            } else if (is4BarBoundary) {
                ctx.strokeStyle = 'rgba(255, 255, 255, 0.25)';
                ctx.lineWidth = 1;
            } else {
                ctx.strokeStyle = 'rgba(255, 255, 255, 0.12)';
                ctx.lineWidth = 1;
            }
            ctx.beginPath();
            ctx.moveTo(barX, 0);
            ctx.lineTo(barX, h);
            ctx.stroke();

            // Bar number label — brighter at 4-bar boundaries, clearer text
            if (bar % labelEvery === 0 && bar >= 0) {
                ctx.fillStyle = (() => {
                    if (is8BarBoundary) {
                        return 'rgba(224, 224, 224, 0.7)';
                    }
                    if (is4BarBoundary) {
                        return 'rgba(224, 224, 224, 0.55)';
                    }
                    return 'rgba(224, 224, 224, 0.35)';
                })();
                ctx.fillText(String(bar + 1), barX + 3, 11);
            }

            // Beat subdivisions — graduated tick heights
            if (barPixels > 25) {
                for (let beat = 1; beat < beatsPerBar; beat++) {
                    const beatX = barX + beat * pixelsPerBeat;
                    // Beat 2 (halfway through bar) gets a taller tick
                    const isHalf = beat === Math.floor(beatsPerBar / 2);
                    const tickH = isHalf ? 7 : 4;
                    ctx.strokeStyle = isHalf ? 'rgba(255, 255, 255, 0.12)' : 'rgba(255, 255, 255, 0.07)';
                    ctx.lineWidth = 1;
                    ctx.beginPath();
                    ctx.moveTo(beatX, h - tickH);
                    ctx.lineTo(beatX, h);
                    ctx.stroke();
                }
            }
        }

        // Playhead marker — clean triangular indicator
        const phX = (playhead - viewportStartBeat) * pixelsPerBeat;
        if (phX >= 0 && phX <= w) {
            ctx.fillStyle = 'rgba(255, 255, 255, 0.9)';
            ctx.beginPath();
            ctx.moveTo(phX - 4, 0);
            ctx.lineTo(phX + 4, 0);
            ctx.lineTo(phX, 7);
            ctx.closePath();
            ctx.fill();

            ctx.strokeStyle = 'rgba(255, 255, 255, 0.35)';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(phX, 7);
            ctx.lineTo(phX, h);
            ctx.stroke();
        }

        // Bottom border — crisp separator
        ctx.strokeStyle = 'rgba(255, 255, 255, 0.08)';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(0, h - 0.5);
        ctx.lineTo(w, h - 0.5);
        ctx.stroke();

        // Hint text on first load (only if no loop region)
        if (!effectiveIsLooping && w > 200) {
            ctx.fillStyle = 'rgba(255, 255, 255, 0.12)';
            ctx.font = '8px -apple-system, BlinkMacSystemFont, "SF Pro Text", system-ui, sans-serif';
            ctx.fillText('Drag to set loop region · Click to move playhead', w / 2 - 90, h - 4);
        }
    };

    // Continuous playhead redraw via rAF — reads from the non-reactive ref
    useEffect(() => {
        if (!isPlaying) {
            return undefined;
        }
        const id = crypto.randomUUID();
        const loop = () => {
            if (canvasRef.current) {
                drawRuler(canvasRef.current, playheadPositionRef.current);
            }
        };
        animationScheduler.register(`beat-ruler-${id}`, loop);
        return () => animationScheduler.unregister(`beat-ruler-${id}`);
    }, [isPlaying, drawRuler]);

    const setCanvas = (el: HTMLCanvasElement | null) => {
        canvasRef.current = el;
        if (el) {
            drawRuler(el);
        }
    };

    // Redraw on discrete state change (non-playhead)
    if (canvasRef.current) {
        drawRuler(canvasRef.current, playheadPositionRef.current);
    }

    const getBeat = (clientX: number): number => {
        const rect = containerRef.current?.getBoundingClientRect();
        if (!rect) {
            return 0;
        }
        const x = clientX - rect.left;
        return x / pixelsPerBeat + scrollX / pixelsPerBeat;
    };

    const handleMouseDown = (event: MouseEvent<HTMLDivElement>) => {
        if (event.button !== 0) {
            return;
        }
        const beat = getBeat(event.clientX);

        // Always seek playhead on click
        seekPlayhead(beat);

        if (event.shiftKey) {
            // Shift+drag: set/extend loop region (R-B5 predecessor behavior)
            loopDragRef.current = { startBeat: beat };
        } else {
            // Normal drag: scrub (R-B6) — playhead follows the cursor
            scrubDragRef.current = true;
        }
    };

    const handleMouseMove = (event: MouseEvent<HTMLDivElement>) => {
        // Only process if mouse button is held
        if (event.buttons !== 1) {
            loopDragRef.current = null;
            loopPreviewRef.current = null;
            scrubDragRef.current = false;
            return;
        }

        const beat = getBeat(event.clientX);

        if (scrubDragRef.current) {
            // R-B6: scrub — continuously seek the playhead to follow the cursor
            seekPlayhead(Math.max(0, beat));
            return;
        }

        if (!loopDragRef.current) {
            return;
        }

        const start = loopDragRef.current.startBeat;
        const lo = Math.min(start, beat);
        const hi = Math.max(start, beat);

        // Require at least a 0.25 beat drag to establish a loop region.
        // Update only the ephemeral preview ref and redraw directly — avoids
        // flooding transportStore (and all its React subscribers) at 60 Hz.
        if (hi - lo >= 0.25) {
            loopPreviewRef.current = { start: Math.floor(lo), end: Math.ceil(hi) };
            if (canvasRef.current) {
                drawRuler(canvasRef.current, playheadPositionRef.current);
            }
        }
    };

    const handleMouseUp = () => {
        scrubDragRef.current = false;
        if (loopDragRef.current) {
            loopDragRef.current = null;
            // Commit the final loop region to the store exactly once on mouseup.
            if (loopPreviewRef.current) {
                setLoopRegion(loopPreviewRef.current.start, loopPreviewRef.current.end);
                loopPreviewRef.current = null;
            }
        }
    };

    return (
        <TimelineChromeSurface
            ref={containerRef}
            className="cursor-col-resize select-none"
            style={{ height: HEIGHT }}
            onMouseDown={handleMouseDown}
            onMouseMove={handleMouseMove}
            onMouseUp={handleMouseUp}
            onMouseLeave={handleMouseUp}
            onDoubleClick={() => {
                disableLooping();
            }}
            title="Click to seek · Drag to scrub · Shift+drag to set loop region · Double-click to disable loop"
        >
            <canvas ref={setCanvas} className="block w-full" style={{ height: HEIGHT }} />
        </TimelineChromeSurface>
    );
};

import { type ReactElement, useRef, useState } from 'react';

import { DawContextMenuSurface } from '#/components/daw/DawContextMenuSurface';
import { DawMenuInlineEditor } from '#/components/daw/DawMenuInlineEditor';
import { DawMenuButton, DawMenuMutedRow, DawMenuSeparator } from '#/components/daw/DawMenuParts';
import { DawSwatchButton } from '#/components/daw/DawSwatchButton';
import { useStore } from '#/infra/store/useStore';
import { handleAiDenoiseClip } from '#/modules/AiGeneration/useCases';
import { runAiActionWithToast } from '#/modules/AiRuntime/useCases';
import { detectTempo, detectKey } from '#/modules/AudioAnalysis/useCases';
import { executeAppAction } from '#/modules/Command/useCases';
import { workspaceStore, defaultWorkspaceState } from '#/modules/Workspace/stores';
import { selectClip, setWorkspaceMode } from '#/modules/Workspace/useCases';
import { notifyUser } from '#/utils/Notification/notifyUser';
import { useContextMenuDismiss } from '#/utils/UI/useContextMenuDismiss';

import { CLIP_COLOR_OPTIONS } from '../../models/colorPalette';
import { trackStore, defaultTrackState } from '../../stores/trackStore';
import { duplicateClip } from '../../useCases/clip/duplicateClip';
import { duplicateClipToNextBar } from '../../useCases/clip/duplicateClipToNextBar';
import { removeClip } from '../../useCases/clip/removeClip';
import { copySelectedClip } from '../../useCases/clipboard/copySelectedClip';
import { cutSelectedClip } from '../../useCases/clipboard/cutSelectedClip';
import { pasteClip } from '../../useCases/clipboard/pasteClip';
import { lockClip } from '../../useCases/clipEditing/lockClip';
import { muteClip } from '../../useCases/clipEditing/muteClip';
import { normalizeClip } from '../../useCases/clipEditing/normalizeClip';
import { renameClip } from '../../useCases/clipEditing/renameClip';
import { reverseClip } from '../../useCases/clipEditing/reverseClip';
import { setClipColor } from '../../useCases/clipEditing/setClipColor';
import { splitClipWithUndo } from '../../useCases/clipEditing/splitClipWithUndo';
import { toggleInlineEditing } from '../../useCases/clipEditing/toggleInlineEditing';
import { exportMidiClip } from '../../useCases/exportMidiClip';
import { stripSilence } from '../../useCases/stripSilence';

type ClipContextMenuProps = {
    x: number;
    y: number;
    clipId: string;
    splitBeat: number;
    onClose: () => void;
};

export const ClipContextMenu = ({ x, y, clipId, splitBeat, onClose }: ClipContextMenuProps): ReactElement => {
    const menuRef = useRef<HTMLDivElement>(null);
    useContextMenuDismiss(menuRef, onClose);

    const trackState = useStore(trackStore, defaultTrackState);
    const workspaceState = useStore(workspaceStore, defaultWorkspaceState);

    const clip = trackState.tracks.flatMap((track) => track.clips).find((candidate) => candidate.id === clipId);
    const [isRenaming, setIsRenaming] = useState(false);
    const [newName, setNewName] = useState(clip?.name ?? '');
    const isMidi = clip?.type === 'midi';
    const isAudio = clip?.type === 'audio';
    const isLocked = clip?.locked ?? false;
    const isMuted = clip?.muted ?? false;
    const selectedIds = workspaceState.selectedClipIds ?? [];
    const multiSelected = selectedIds.length > 1 && selectedIds.includes(clipId);

    const act = (fn: () => void) => () => {
        fn();
        onClose();
    };

    const deleteSelected = () => {
        if (multiSelected) {
            for (const id of selectedIds) {
                removeClip(id);
            }
        } else {
            removeClip(clipId);
        }
    };

    const duplicateSelected = () => {
        if (multiSelected) {
            for (const id of selectedIds) {
                duplicateClip(id);
            }
        } else {
            duplicateClip(clipId);
        }
    };

    const renderAudioActions = (): ReactElement => (
        <>
            <DawMenuButton role="menuitem" onClick={act(() => normalizeClip(clipId))}>
                Normalize
            </DawMenuButton>
            <DawMenuButton role="menuitem" onClick={act(() => reverseClip(clipId))}>
                Reverse
            </DawMenuButton>
            <DawMenuButton role="menuitem" onClick={act(() => stripSilence(clipId))}>
                Strip Silence
            </DawMenuButton>
            <DawMenuButton
                role="menuitem"
                onClick={act(() => {
                    if (clip?.audioBufferId) {
                        const bpm = detectTempo(clip.audioBufferId);
                        if (bpm) {
                            notifyUser(`Detected tempo: ${bpm} BPM`);
                        } else {
                            notifyUser('Could not detect tempo');
                        }
                    }
                })}
            >
                Detect Tempo
            </DawMenuButton>
            <DawMenuButton
                role="menuitem"
                onClick={act(() => {
                    if (clip?.audioBufferId) {
                        const result = detectKey(clip.audioBufferId);
                        if (result) {
                            const confidence = Math.round(result.confidence * 100);
                            notifyUser(`Detected key: ${result.key} ${result.mode} (${confidence}% confidence)`);
                        } else {
                            notifyUser('Could not detect key');
                        }
                    }
                })}
            >
                Detect Key
            </DawMenuButton>
            <DawMenuSeparator className="border-border/50" />
            <DawMenuMutedRow className="flex items-center gap-1 font-medium text-muted-foreground/70">
                <span className="inline-block size-2.5 rounded-full bg-[var(--color-accent-cyan)]/60" />
                AI
            </DawMenuMutedRow>
            <DawMenuButton
                role="menuitem"
                leadingContent={<span className="text-[var(--color-accent-cyan)]">✦</span>}
                onClick={act(() =>
                    runAiActionWithToast(() => executeAppAction({ type: 'stemSeparate', payload: { clipId } }), {
                        startMsg: 'Separating stems… this may take a moment',
                        successMsg: 'Stem separation complete',
                        successDetails: ['Created separate tracks for each stem'],
                        failMsg: 'Stem separation failed',
                    })
                )}
            >
                Separate Stems
            </DawMenuButton>
            <DawMenuButton
                role="menuitem"
                leadingContent={<span className="text-[var(--color-accent-cyan)]">✦</span>}
                onClick={act(() =>
                    runAiActionWithToast(() => executeAppAction({ type: 'audioToMidi', payload: { clipId } }), {
                        startMsg: 'Converting audio to MIDI…',
                        successMsg: 'Audio converted to MIDI',
                        successDetails: ['New MIDI clip created from detected onsets'],
                        failMsg: 'Audio-to-MIDI conversion failed',
                    })
                )}
            >
                Convert to MIDI
            </DawMenuButton>
            <DawMenuButton
                role="menuitem"
                leadingContent={<span className="text-[var(--color-accent-cyan)]">✦</span>}
                onClick={act(() =>
                    runAiActionWithToast(() => handleAiDenoiseClip(clipId, 0.7), {
                        startMsg: 'Denoising audio…',
                        successMsg: 'Audio denoised',
                        successDetails: ['Noise reduction applied to clip'],
                        failMsg: 'Audio denoise failed',
                    })
                )}
            >
                Denoise
            </DawMenuButton>
        </>
    );

    const renderMidiActions = (): ReactElement => (
        <>
            <DawMenuButton role="menuitem" onClick={act(() => toggleInlineEditing(clipId))}>
                {clip?.isInlineEditing ? 'Close Inline Editor' : 'Open Inline Editor'}
            </DawMenuButton>
            <DawMenuButton
                role="menuitem"
                onClick={act(() => executeAppAction({ type: 'arpeggiate', payload: { clipId } }))}
            >
                Arpeggiate
            </DawMenuButton>
            <DawMenuButton role="menuitem" onClick={act(() => exportMidiClip(clipId))}>
                Export as MIDI…
            </DawMenuButton>
            <DawMenuSeparator className="border-border/50" />
            <DawMenuMutedRow className="flex items-center gap-1 font-medium text-muted-foreground/70">
                <span className="inline-block size-2.5 rounded-full bg-[var(--color-accent-cyan)]/60" />
                AI
            </DawMenuMutedRow>
            <DawMenuButton
                role="menuitem"
                leadingContent={<span className="text-[var(--color-accent-cyan)]">✦</span>}
                onClick={act(() =>
                    runAiActionWithToast(
                        () => executeAppAction({ type: 'completeMidi', payload: { clipId, bars: 4 } }),
                        {
                            startMsg: 'Generating MIDI continuation…',
                            successMsg: 'MIDI continuation generated',
                            successDetails: ['Added 4 bars of new MIDI content'],
                            failMsg: 'MIDI continuation failed',
                        }
                    )
                )}
            >
                Continue MIDI…
            </DawMenuButton>
            <DawMenuButton
                role="menuitem"
                leadingContent={<span className="text-[var(--color-accent-cyan)]">✦</span>}
                onClick={act(() =>
                    runAiActionWithToast(
                        () => executeAppAction({ type: 'variationMidi', payload: { clipId, amount: 0.3 } }),
                        {
                            startMsg: 'Creating MIDI variation…',
                            successMsg: 'MIDI variation created',
                            successDetails: ['Variation applied with 30% divergence'],
                            failMsg: 'MIDI variation failed',
                        }
                    )
                )}
            >
                Create Variation
            </DawMenuButton>
        </>
    );

    return (
        <DawContextMenuSurface
            ref={menuRef}
            x={x}
            y={y}
            xClampOffset={200}
            yClampOffset={400}
            className="max-h-[80vh] min-w-[180px] overflow-y-auto"
            role="menu"
        >
            {multiSelected ? <DawMenuMutedRow>{selectedIds.length} clips selected</DawMenuMutedRow> : null}

            {isRenaming ? (
                <DawMenuInlineEditor
                    label="Rename Clip"
                    value={newName}
                    onChange={setNewName}
                    onSubmit={() => {
                        const trimmed = newName.trim();
                        if (trimmed) {
                            renameClip(clipId, trimmed);
                        }
                        onClose();
                    }}
                    onCancel={() => setIsRenaming(false)}
                />
            ) : (
                <>
                    <DawMenuButton
                        role="menuitem"
                        onClick={act(() => {
                            selectClip(clipId);
                            setWorkspaceMode('clip');
                        })}
                    >
                        Edit Clip
                    </DawMenuButton>

                    <DawMenuButton
                        role="menuitem"
                        onClick={(event) => {
                            event.stopPropagation();
                            setIsRenaming(true);
                            setNewName(clip?.name ?? '');
                        }}
                    >
                        Rename Clip
                    </DawMenuButton>

                    <DawMenuButton role="menuitem" onClick={act(() => splitClipWithUndo(clipId, splitBeat))}>
                        Split at Cursor
                    </DawMenuButton>
                    <DawMenuButton role="menuitem" shortcut="⌘D" onClick={act(duplicateSelected)}>
                        Duplicate{multiSelected ? ` (${selectedIds.length})` : ''}
                    </DawMenuButton>
                    {!multiSelected ? (
                        <DawMenuButton
                            role="menuitem"
                            shortcut="⌥D"
                            onClick={act(() => duplicateClipToNextBar(clipId))}
                        >
                            Duplicate to Next Bar
                        </DawMenuButton>
                    ) : null}

                    <DawMenuSeparator className="border-border/50" />

                    <DawMenuButton
                        role="menuitem"
                        shortcut="⌘C"
                        onClick={act(() => {
                            selectClip(clipId);
                            copySelectedClip();
                        })}
                    >
                        Copy
                    </DawMenuButton>
                    <DawMenuButton
                        role="menuitem"
                        shortcut="⌘X"
                        onClick={act(() => {
                            selectClip(clipId);
                            cutSelectedClip();
                        })}
                    >
                        Cut
                    </DawMenuButton>
                    <DawMenuButton role="menuitem" shortcut="⌘V" onClick={act(() => pasteClip())}>
                        Paste
                    </DawMenuButton>

                    <DawMenuSeparator className="border-border/50" />

                    {isAudio ? renderAudioActions() : null}
                    {isMidi ? renderMidiActions() : null}

                    <DawMenuButton role="menuitem" onClick={act(() => muteClip(clipId, !isMuted))}>
                        {isMuted ? 'Unmute Clip' : 'Mute Clip'}
                    </DawMenuButton>
                    <DawMenuButton role="menuitem" onClick={act(() => lockClip(clipId, !isLocked))}>
                        {isLocked ? 'Unlock Clip' : 'Lock Clip'}
                    </DawMenuButton>

                    <DawMenuSeparator className="border-border/50" />

                    <DawMenuMutedRow>Color</DawMenuMutedRow>
                    <div className="flex gap-1 px-3 py-1">
                        {CLIP_COLOR_OPTIONS.map((color) => (
                            <DawSwatchButton
                                key={color || 'default'}
                                color={color || 'var(--color-muted)'}
                                active={clip?.color === color}
                                onClick={act(() => setClipColor(clipId, color))}
                                aria-label={color || 'Default color'}
                            />
                        ))}
                    </div>

                    <DawMenuSeparator className="border-border/50" />

                    <DawMenuButton role="menuitem" tone="danger" shortcut="⌫" onClick={act(deleteSelected)}>
                        Delete{multiSelected ? ` (${selectedIds.length})` : ''}
                    </DawMenuButton>
                </>
            )}
        </DawContextMenuSurface>
    );
};

import { type ReactElement, type MouseEvent, useState, useRef, useEffect } from 'react';

import { Flag } from 'lucide-react';

import { DawCompactInput } from '#/components/daw/DawCompactInput';
import { DawMenuButton, DawMenuMutedRow, DawMenuSeparator } from '#/components/daw/DawMenuParts';
import { DawSwatchButton } from '#/components/daw/DawSwatchButton';
import { useStore } from '#/infra/store/useStore';

import { MARKER_COLOR_PRESETS as MARKER_COLORS } from '../../models/colorPalette';
import { type Marker } from '../../models/Marker';
import { markerStore, type MarkerStoreState } from '../../stores/markerStore';
import { addMarker } from '../../useCases/marker/markerOperations/addMarker';
import { moveMarker } from '../../useCases/marker/markerOperations/moveMarker';
import { removeMarker } from '../../useCases/marker/markerOperations/removeMarker';
import { renameMarker } from '../../useCases/marker/markerOperations/renameMarker';
import { setMarkerColor } from '../../useCases/marker/markerOperations/setMarkerColor';

import { TimelineChromeSurface } from './TimelineChromeSurface';

type MarkerLaneProps = {
    pixelsPerBeat: number;
    scrollX: number;
};

type ContextMenuState =
    | { kind: 'none' }
    | { kind: 'empty'; x: number; y: number; beat: number }
    | { kind: 'marker'; x: number; y: number; marker: Marker };

type EditingState = { markerId: string; name: string } | null;

type DragState = {
    markerId: string;
    startClientX: number;
    originalBeat: number;
} | null;

const LANE_HEIGHT = 20;

const defaultMarkerState: MarkerStoreState = { markers: [], sections: [] };

export const MarkerLane = ({ pixelsPerBeat, scrollX }: MarkerLaneProps): ReactElement => {
    const markerState = useStore(markerStore, defaultMarkerState);

    const markers = markerState.markers;
    const [contextMenu, setContextMenu] = useState<ContextMenuState>({ kind: 'none' });
    const [editing, setEditing] = useState<EditingState>(null);
    const [dragPreview, setDragPreview] = useState<{ markerId: string; beat: number } | null>(null);
    const menuRef = useRef<HTMLDivElement>(null);
    const inputRef = useRef<HTMLInputElement>(null);
    const dragRef = useRef<DragState>(null);
    const laneRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (editing && inputRef.current) {
            inputRef.current.focus();
            inputRef.current.select();
        }
    }, [editing]);

    useEffect(() => {
        if (contextMenu.kind === 'none') {
            return undefined;
        }
        const handleClick = (event: globalThis.MouseEvent) => {
            if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
                setContextMenu({ kind: 'none' });
            }
        };
        window.addEventListener('mousedown', handleClick);
        return () => window.removeEventListener('mousedown', handleClick);
    }, [contextMenu.kind]);

    // Compute final beat on mouseup by reading the last mousemove position
    // We use a ref-based approach for the final commit to avoid stale closure
    const handleMarkerDragStartStable = (event: MouseEvent, marker: Marker) => {
        if (event.button !== 0) {
            return;
        }
        event.preventDefault();
        event.stopPropagation();

        const startX = event.clientX;
        const originalBeat = marker.beat;
        let lastBeat = originalBeat;

        dragRef.current = {
            markerId: marker.id,
            startClientX: startX,
            originalBeat,
        };

        const handleMouseMove = (moveEvent: globalThis.MouseEvent) => {
            const deltaPx = moveEvent.clientX - startX;
            const deltaBeats = deltaPx / pixelsPerBeat;
            lastBeat = Math.max(0, Math.round(originalBeat + deltaBeats));
            setDragPreview({ markerId: marker.id, beat: lastBeat });
        };

        const handleMouseUp = () => {
            if (lastBeat !== originalBeat) {
                moveMarker(marker.id, lastBeat);
            }
            dragRef.current = null;
            setDragPreview(null);
            window.removeEventListener('mousemove', handleMouseMove);
            window.removeEventListener('mouseup', handleMouseUp);
        };

        window.addEventListener('mousemove', handleMouseMove);
        window.addEventListener('mouseup', handleMouseUp);
    };

    const handleLaneContextMenu = (event: MouseEvent<HTMLDivElement>) => {
        if (dragRef.current) {
            return;
        }
        event.preventDefault();
        const rect = event.currentTarget.getBoundingClientRect();
        const localX = event.clientX - rect.left;
        const clickBeat = (localX + scrollX) / pixelsPerBeat;

        // Find if clicked near an existing marker (within ~10 pixels)
        const hitMarker = markers.find((message) => {
            const mx = message.beat * pixelsPerBeat - scrollX;
            return Math.abs(localX - mx) < 10;
        });

        if (hitMarker) {
            setContextMenu({ kind: 'marker', x: event.clientX, y: event.clientY, marker: hitMarker });
        } else {
            setContextMenu({ kind: 'empty', x: event.clientX, y: event.clientY, beat: clickBeat });
        }
    };

    const handleAddMarker = () => {
        if (contextMenu.kind !== 'empty') {
            return;
        }

        const beat = Math.floor(contextMenu.beat); // Snap to beat
        addMarker(beat, 'New Marker');
        setContextMenu({ kind: 'none' });
    };

    const handleDeleteMarker = () => {
        if (contextMenu.kind !== 'marker') {
            return;
        }
        removeMarker(contextMenu.marker.id);
        setContextMenu({ kind: 'none' });
    };

    const handleStartRename = () => {
        if (contextMenu.kind !== 'marker') {
            return;
        }
        setEditing({ markerId: contextMenu.marker.id, name: contextMenu.marker.name });
        setContextMenu({ kind: 'none' });
    };

    const commitRename = () => {
        if (!editing) {
            return;
        }
        const trimmed = editing.name.trim();
        if (trimmed) {
            renameMarker(editing.markerId, trimmed);
        }
        setEditing(null);
    };

    return (
        <TimelineChromeSurface
            ref={laneRef}
            className="select-none"
            style={{
                height: LANE_HEIGHT,
            }}
            onContextMenu={handleLaneContextMenu}
            role="region"
            aria-label="Timeline markers"
        >
            {markers.map((marker) => {
                const isDragging = dragPreview?.markerId === marker.id;
                const displayBeat = isDragging ? dragPreview.beat : marker.beat;
                const left = displayBeat * pixelsPerBeat - scrollX;
                if (left < -50 || left > 4000) {
                    return null;
                }

                const isEditing = editing?.markerId === marker.id;

                return (
                    <div
                        key={marker.id}
                        className="absolute top-0 bottom-0 flex items-center gap-1 group"
                        style={{
                            left: Math.max(0, left),
                            opacity: isDragging ? 0.7 : 1,
                            transition: isDragging ? 'none' : 'left 0.1s ease-out',
                        }}
                        title={marker.name}
                        onDoubleClick={() => setEditing({ markerId: marker.id, name: marker.name })}
                    >
                        <div
                            className="flex flex-col h-full w-[2px] cursor-ew-resize hover:w-[4px] hover:-ml-[1px] transition-all"
                            style={{ backgroundColor: marker.color }}
                            onMouseDown={(event) => handleMarkerDragStartStable(event, marker)}
                        />
                        <div
                            className="flex items-center gap-1 rounded-sm px-1.5 py-0.5 cursor-grab active:cursor-grabbing hover:bg-white/10"
                            style={{ backgroundColor: `${marker.color}33`, color: marker.color }}
                            onMouseDown={(event) => handleMarkerDragStartStable(event, marker)}
                        >
                            <Flag className="size-2.5" />
                            {isEditing ? (
                                <DawCompactInput
                                    ref={inputRef}
                                    size="micro"
                                    className="h-3 min-w-[60px] border-0 bg-transparent px-0 text-[9px] font-medium text-current shadow-none focus-visible:ring-0"
                                    value={editing.name}
                                    onChange={(event) => setEditing({ ...editing, name: event.target.value })}
                                    onBlur={commitRename}
                                    onKeyDown={(event) => {
                                        if (event.key === 'Enter') {
                                            commitRename();
                                        }
                                        if (event.key === 'Escape') {
                                            setEditing(null);
                                        }
                                    }}
                                />
                            ) : (
                                <span className="text-[9px] font-medium truncate max-w-[120px]">{marker.name}</span>
                            )}
                        </div>
                    </div>
                );
            })}
            {contextMenu.kind !== 'none' ? (
                <div
                    ref={menuRef}
                    className="daw-floating-surface fixed z-50 min-w-[140px] rounded-md p-1"
                    style={{
                        left: contextMenu.x,
                        top: contextMenu.y,
                    }}
                >
                    {contextMenu.kind === 'empty' && (
                        <DawMenuButton onClick={handleAddMarker}>
                            Add Marker at Beat {Math.floor(contextMenu.beat)}
                        </DawMenuButton>
                    )}
                    {contextMenu.kind === 'marker' && (
                        <>
                            <DawMenuButton onClick={handleStartRename}>Rename Marker</DawMenuButton>
                            <DawMenuMutedRow className="px-2">Color</DawMenuMutedRow>
                            <div className="flex gap-1 px-2 pb-1">
                                {MARKER_COLORS.map((context) => (
                                    <DawSwatchButton
                                        key={context}
                                        color={context}
                                        onClick={() => {
                                            setMarkerColor(contextMenu.marker.id, context);
                                            setContextMenu({ kind: 'none' });
                                        }}
                                        aria-label={`Set color ${context}`}
                                    />
                                ))}
                            </div>
                            <DawMenuSeparator className="mx-1 my-0.5 border-border/50" />
                            <DawMenuButton tone="danger" onClick={handleDeleteMarker}>
                                Delete Marker
                            </DawMenuButton>
                        </>
                    )}
                </div>
            ) : null}
        </TimelineChromeSurface>
    );
};

import { type ReactElement, useEffect, useRef } from 'react';

import { getMasterAnalyser } from '#/modules/AudioEngine/useCases';
import { cn } from '#/utils/Styles/cn';

import { selectTrack } from '../../useCases/toggleTrackState/selectTrack';
import { useTracks } from '../hooks/useTracks';

export const MiniMasterSpectrum = ({ className }: { className?: string }): ReactElement | null => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const animationRef = useRef<number>(0);
    const { tracks, selectedTrackId } = useTracks();
    const masterTrack = tracks.find((time) => time.kind === 'master');
    const isSelected = masterTrack?.id === selectedTrackId;

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) {
            return undefined;
        }

        const ctx = canvas.getContext('2d');
        if (!ctx) {
            return undefined;
        }

        // Try getting the master analyser. Might be null if engine isn't ready.
        let analyser: AnalyserNode | undefined;
        try {
            analyser = getMasterAnalyser();
        } catch {
            return undefined;
        }

        if (!analyser) {
            return undefined;
        }

        const bufferLength = analyser.frequencyBinCount;
        const dataArray = new Uint8Array(bufferLength);

        ctx.imageSmoothingEnabled = false;

        // §181.1 — hoist per-frame allocations outside the rAF loop.
        // The gradient only needs to be created once per effect run (it
        // depends on canvas height, which is fixed at mount), and the
        // fill style is the same for every bar so it can be set once
        // per frame instead of once per bar.
        const canvasHeight = canvas.height;
        const canvasWidth = canvas.width;
        const gradient = ctx.createLinearGradient(0, canvasHeight, 0, 0);
        gradient.addColorStop(0, 'rgba(217, 119, 6, 0.4)'); // amber/orange
        gradient.addColorStop(0.5, 'rgba(234, 179, 8, 0.8)'); // yellow
        gradient.addColorStop(1, 'rgba(252, 211, 77, 1)'); // bright
        const barFill: CanvasGradient | string = isSelected ? gradient : 'rgba(255,255,255,0.06)';
        const barWidth = Math.max(1, (canvasWidth / bufferLength) * 2.5);
        const innerBarWidth = barWidth - 0.5;

        const draw = (): void => {
            animationRef.current = requestAnimationFrame(draw);

            analyser.getByteFrequencyData(dataArray);

            ctx.clearRect(0, 0, canvasWidth, canvasHeight);
            ctx.fillStyle = barFill;

            let x = 0;
            for (let index = 0; index < bufferLength; index += 2) {
                if (x > canvasWidth) {
                    break;
                }
                const barHeight = (dataArray[index]! / 255) * canvasHeight;
                ctx.fillRect(x, canvasHeight - barHeight, innerBarWidth, barHeight);
                x += barWidth;
            }
        };

        draw();

        return () => {
            cancelAnimationFrame(animationRef.current);
        };
    }, [isSelected]);

    if (!masterTrack) {
        return null;
    }

    return (
        <div
            role="button"
            tabIndex={0}
            onClick={() => selectTrack(masterTrack.id)}
            onKeyDown={(event) => {
                if (event.key === 'Enter' || event.key === ' ') {
                    selectTrack(masterTrack.id);
                }
            }}
            className={cn(
                'absolute inset-0 overflow-hidden cursor-pointer transition-colors',
                isSelected ? 'bg-black/30 shadow-[inset_0_1px_3px_rgba(0,0,0,0.6)]' : 'hover:bg-white/[0.02]',
                className
            )}
            title="Master Track (Click to inspect)"
            aria-label="Master Track Spectrum"
        >
            <div className="absolute inset-x-0 bottom-0 h-full pointer-events-none opacity-40">
                <canvas ref={canvasRef} className="w-full h-full block" width={180} height={80} />
            </div>
            <div className="absolute inset-0 pointer-events-none bg-[repeating-linear-gradient(0deg,transparent,transparent_1px,rgba(0,0,0,0.1)_1px,rgba(0,0,0,0.1)_2px)] opacity-50" />
            <div className="absolute inset-x-2 top-2 z-10 flex flex-col pointer-events-none">
                <span
                    className={cn(
                        'text-[10px] uppercase tracking-wider font-semibold drop-shadow-md transition-colors',
                        isSelected ? 'text-foreground' : 'text-muted-foreground'
                    )}
                >
                    Master
                </span>
            </div>
        </div>
    );
};

import { type ReactElement, type MouseEvent, useRef, useLayoutEffect, useState } from 'react';

import { useStore } from '#/infra/store/useStore';

import { timelineViewStore, type TimelineViewState } from '../../stores/timelineViewStore';
import { trackStore, type TrackStoreState } from '../../stores/trackStore';

import { TimelineChromeSurface } from './TimelineChromeSurface';

const MINIMAP_HEIGHT = 28;
const MIN_PROJECT_BEATS = 64;
const VIEWPORT_MIN_WIDTH = 6;

const defaultTrackState: TrackStoreState = { tracks: [], selectedTrackId: null };
const defaultTimelineView: TimelineViewState = {
    scrollX: 0,
    scrollY: 0,
    pixelsPerBeat: 12,
    autoScrollEnabled: true,
};

export const TimelineMinimap = (): ReactElement => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);
    const isDraggingRef = useRef(false);
    const dragOffsetRef = useRef(0);
    const [containerWidth, setContainerWidth] = useState(0);

    const trackState = useStore(trackStore, defaultTrackState);
    const viewState = useStore(timelineViewStore, defaultTimelineView);

    const tracks = trackState.tracks;
    const pixelsPerBeat = viewState.pixelsPerBeat;
    const scrollX = viewState.scrollX;

    useLayoutEffect(() => {
        const canvas = canvasRef.current;
        const container = containerRef.current;
        if (!canvas || !container) {
            return;
        }

        const rect = container.getBoundingClientRect();
        const dpr = window.devicePixelRatio || 1;
        canvas.width = rect.width * dpr;
        canvas.height = MINIMAP_HEIGHT * dpr;

        const ctx = canvas.getContext('2d');
        if (!ctx) {
            return;
        }
        ctx.scale(dpr, dpr);

        const canvasWidth = rect.width;
        const trackCount = tracks.length;

        let maxEndBeat = 0;
        for (const track of tracks) {
            for (const clip of track.clips) {
                if (clip.endBeat > maxEndBeat) {
                    maxEndBeat = clip.endBeat;
                }
            }
        }
        const totalBeats = Math.max(MIN_PROJECT_BEATS, maxEndBeat * 1.1);
        const beatsToPixels = canvasWidth / totalBeats;
        const trackLaneHeight = trackCount > 0 ? (MINIMAP_HEIGHT - 2) / trackCount : MINIMAP_HEIGHT - 2;
        const clampedLaneHeight = Math.min(trackLaneHeight, 8);

        ctx.clearRect(0, 0, canvasWidth, MINIMAP_HEIGHT);

        // Dark background with subtle gradient
        const bgGrad = ctx.createLinearGradient(0, 0, 0, MINIMAP_HEIGHT);
        bgGrad.addColorStop(0, 'rgba(255, 255, 255, 0.035)');
        bgGrad.addColorStop(1, 'rgba(0, 0, 0, 0.02)');
        ctx.fillStyle = bgGrad;
        ctx.fillRect(0, 0, canvasWidth, MINIMAP_HEIGHT);

        if (trackCount > 0) {
            const laneOffset = (MINIMAP_HEIGHT - trackCount * clampedLaneHeight) / 2;

            for (let index = 0; index < tracks.length; index++) {
                const track = tracks[index]!;
                const y = laneOffset + index * clampedLaneHeight;

                for (const clip of track.clips) {
                    const x = clip.startBeat * beatsToPixels;
                    const w = Math.max(1, (clip.endBeat - clip.startBeat) * beatsToPixels);
                    const color = clip.color || track.color || 'oklch(0.40 0.08 250)';
                    const clipH = Math.max(1, clampedLaneHeight - 1);

                    ctx.fillStyle = color;
                    ctx.globalAlpha = 0.8;
                    if (w > 3 && clipH > 2) {
                        ctx.beginPath();
                        ctx.roundRect(x, y, w, clipH, 1);
                        ctx.fill();
                    } else {
                        ctx.fillRect(x, y, w, clipH);
                    }
                }
            }
            ctx.globalAlpha = 1;
        }

        const viewportStartPx = (scrollX / pixelsPerBeat) * beatsToPixels;
        const containerWidth = rect.width;
        const visibleBeats = containerWidth / pixelsPerBeat;
        const viewportWidthPx = Math.max(VIEWPORT_MIN_WIDTH, visibleBeats * beatsToPixels);

        // Viewport indicator with gradient fill
        const vpGrad = ctx.createLinearGradient(0, 0, 0, MINIMAP_HEIGHT);
        vpGrad.addColorStop(0, 'rgba(255, 255, 255, 0.10)');
        vpGrad.addColorStop(1, 'rgba(255, 255, 255, 0.04)');
        ctx.fillStyle = vpGrad;
        ctx.fillRect(viewportStartPx, 0, viewportWidthPx, MINIMAP_HEIGHT);

        // Viewport border — brighter top edge for dimensionality
        ctx.strokeStyle = 'rgba(255, 255, 255, 0.22)';
        ctx.lineWidth = 1;
        ctx.strokeRect(viewportStartPx + 0.5, 0.5, viewportWidthPx - 1, MINIMAP_HEIGHT - 1);

        // Brighter top edge on viewport
        ctx.strokeStyle = 'rgba(255, 255, 255, 0.12)';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(viewportStartPx + 0.5, 0.5);
        ctx.lineTo(viewportStartPx + viewportWidthPx - 0.5, 0.5);
        ctx.stroke();
    }, [tracks, pixelsPerBeat, scrollX, containerWidth]);

    useLayoutEffect(() => {
        const container = containerRef.current;
        if (!container) {
            return undefined;
        }

        const observer = new ResizeObserver((entries) => {
            if (entries[0]) {
                setContainerWidth(entries[0].contentRect.width);
            }
        });

        observer.observe(container);
        // Set initial width
        setContainerWidth(container.getBoundingClientRect().width);

        return () => observer.disconnect();
    }, []);

    const getMinimapMetrics = () => {
        const container = containerRef.current;
        if (!container) {
            return null;
        }
        const rect = container.getBoundingClientRect();
        const canvasWidth = rect.width;

        let maxEndBeat = 0;
        for (const track of tracks) {
            for (const clip of track.clips) {
                if (clip.endBeat > maxEndBeat) {
                    maxEndBeat = clip.endBeat;
                }
            }
        }
        const totalBeats = Math.max(MIN_PROJECT_BEATS, maxEndBeat * 1.1);
        const beatsToPixels = canvasWidth / totalBeats;
        const visibleBeats = canvasWidth / pixelsPerBeat;
        const viewportWidthPx = Math.max(VIEWPORT_MIN_WIDTH, visibleBeats * beatsToPixels);
        const viewportStartPx = (scrollX / pixelsPerBeat) * beatsToPixels;

        return { canvasWidth, totalBeats, beatsToPixels, viewportWidthPx, viewportStartPx };
    };

    const handleMouseDown = (event: MouseEvent<HTMLDivElement>) => {
        if (event.button !== 0) {
            return;
        }
        event.preventDefault();

        const metrics = getMinimapMetrics();
        if (!metrics) {
            return;
        }

        const rect = containerRef.current!.getBoundingClientRect();
        const clickX = event.clientX - rect.left;
        const { viewportStartPx, viewportWidthPx, beatsToPixels } = metrics;

        // Capture absolute scroll at drag start
        const dragStartScrollX = viewState?.scrollX ?? 0;

        let dragOffsetInMinimapPx: number;

        if (clickX >= viewportStartPx && clickX <= viewportStartPx + viewportWidthPx) {
            // Click inside viewport — drag from current offset within it
            dragOffsetInMinimapPx = clickX - viewportStartPx;
        } else {
            // Click outside viewport — jump to center on that point
            const visibleBeats = rect.width / pixelsPerBeat;
            const clickedBeat = clickX / beatsToPixels;
            const targetBeat = Math.max(0, clickedBeat - visibleBeats / 2);
            const newScrollX = targetBeat * pixelsPerBeat;
            const currentViewState = timelineViewStore.value;
            if (currentViewState) {
                timelineViewStore.set({ ...currentViewState, scrollX: newScrollX });
            }
            // After jump, the viewport starts at newScrollX in minimap coords
            dragOffsetInMinimapPx = clickX - (newScrollX / pixelsPerBeat) * beatsToPixels;
        }

        isDraggingRef.current = true;
        dragOffsetRef.current = dragOffsetInMinimapPx;

        // Remember the scroll at the moment drag started, so we can compute deltas
        const scrollAtDragStart = dragStartScrollX;

        const handleMouseMove = (moveEvent: globalThis.MouseEvent) => {
            if (!isDraggingRef.current) {
                return;
            }
            const currentMetrics = getMinimapMetrics();
            if (!currentMetrics) {
                return;
            }
            const moveX = moveEvent.clientX - rect.left;
            const newViewportStartPx = moveX - dragOffsetRef.current;
            const targetScrollX = Math.max(0, (newViewportStartPx / currentMetrics.beatsToPixels) * pixelsPerBeat);
            const currentViewState = timelineViewStore.value;
            if (currentViewState) {
                timelineViewStore.set({ ...currentViewState, scrollX: targetScrollX });
            }
            scrollAtDragStart;
        };

        const handleMouseUp = () => {
            isDraggingRef.current = false;
            document.removeEventListener('mousemove', handleMouseMove);
            document.removeEventListener('mouseup', handleMouseUp);
        };

        document.addEventListener('mousemove', handleMouseMove);
        document.addEventListener('mouseup', handleMouseUp);
    };

    return (
        <TimelineChromeSurface
            tone="subtle"
            ref={containerRef}
            className="cursor-pointer"
            style={{ height: MINIMAP_HEIGHT }}
            onMouseDown={handleMouseDown}
            aria-label="Timeline minimap — drag the viewport to scroll, click to jump"
            role="slider"
            aria-valuemin={0}
            aria-valuemax={100}
            aria-valuenow={Math.round((scrollX / Math.max(1, pixelsPerBeat * MIN_PROJECT_BEATS)) * 100)}
        >
            <canvas ref={canvasRef} className="absolute inset-0" style={{ width: '100%', height: MINIMAP_HEIGHT }} />
        </TimelineChromeSurface>
    );
};

import { type ReactElement, useRef, useEffect, useMemo } from 'react';

import { useStore } from '#/infra/store/useStore';
import { automationStore } from '#/modules/Automation/stores';
import { PresenceOverlay } from '#/modules/Collaboration/presentations/views';
import { transportStore, playheadPositionRef, tempoMapStore, timeSignatureMapStore } from '#/modules/Transport/stores';
import { workspaceStore, defaultWorkspaceState } from '#/modules/Workspace/stores';
import { TRACK_HEIGHT_VALUES, onZoomToFit, onZoomToSelection, onScrollToPlayhead } from '#/modules/Workspace/useCases';
import { animationScheduler } from '#/utils/DOM/AnimationScheduler';
import { type GestureEvent } from '#/utils/DOM/GestureEvent';

import { type TimelineRenderer } from '../../models/RendererBackend';
import { previewDirtyFlag } from '../../stores/clipDragPreviewRef';
import { markerStore } from '../../stores/markerStore';
import { takeLaneStore } from '../../stores/takeLaneStore';
import { zoomTimeline, setAutoScroll, timelineViewStore } from '../../stores/timelineViewStore';
import { trackStore } from '../../stores/trackStore';
import { buildTimelineRenderModel } from '../../useCases/buildTimelineRenderModel';
