    useState,
    useLayoutEffect,
} from 'react';

import { Plus, FolderPlus, Rows3, Music, Mic2, GitBranch, FileStack, Wand2 } from 'lucide-react';

import { DawEmptyState } from '#/components/daw/DawEmptyState';
