import { describe, it, expect, vi, beforeEach } from 'vitest';

import { setTrackMute, setTrackGain } from '#/modules/AudioEngine/useCases';
import { getWorkspaceState } from '#/modules/Workspace/useCases';

import { TrackDummy } from '../../__tests__/TrackDummy';
import { getTrackStoreState } from '../../useCases/getTrackStoreState';
import { applySoloLogic, resetSoloLogic } from '../applySoloLogic';

vi.mock('../../useCases/getTrackStoreState', () => ({
    getTrackStoreState: vi.fn(),
}));

vi.mock('#/modules/AudioEngine/useCases', () => ({
    setTrackMute: vi.fn(),
    setTrackGain: vi.fn(),
}));

vi.mock('#/modules/Workspace/useCases', () => ({
    getWorkspaceState: vi.fn(),
}));

describe('applySoloLogic', () => {
    beforeEach(() => {
        vi.resetAllMocks();
        resetSoloLogic();
    });

    describe('SIP (Solo In Place) mode', () => {
        beforeEach(() => {
            vi.mocked(getWorkspaceState).mockReturnValue({ soloMode: 'sip' } as any);
        });

        it('should follow individual mute states when no tracks are soloed', () => {
            const tracks = [
                TrackDummy.create({ id: 't1', muted: false, soloed: false }),
                TrackDummy.create({ id: 't2', muted: true, soloed: false }),
            ];
            vi.mocked(getTrackStoreState).mockReturnValue({ tracks } as any);

            applySoloLogic();

            expect(setTrackMute).toHaveBeenCalledWith('t1', false);
            expect(setTrackMute).toHaveBeenCalledWith('t2', true);
        });

        it('should mute non-soloed tracks when at least one track is soloed', () => {
            const tracks = [
                TrackDummy.create({ id: 't1', muted: false, soloed: true }),
                TrackDummy.create({ id: 't2', muted: false, soloed: false }),
            ];
            vi.mocked(getTrackStoreState).mockReturnValue({ tracks } as any);

            applySoloLogic();

            expect(setTrackMute).toHaveBeenCalledWith('t1', false);
            expect(setTrackMute).toHaveBeenCalledWith('t2', true);
        });

        it('should not mute solo-safe tracks even if other tracks are soloed', () => {
            const tracks = [
                TrackDummy.create({ id: 't1', muted: false, soloed: true }),
                TrackDummy.create({ id: 't-safe', muted: false, soloed: false, soloSafe: true }),
            ];
            vi.mocked(getTrackStoreState).mockReturnValue({ tracks } as any);

            applySoloLogic();

            expect(setTrackMute).toHaveBeenCalledWith('t1', false);
            expect(setTrackMute).toHaveBeenCalledWith('t-safe', false);
        });

        it('should unmute tracks routed to a soloed track', () => {
            const tracks = [
                TrackDummy.create({ id: 'bus', muted: false, soloed: true }),
                TrackDummy.create({ id: 'src', muted: false, soloed: false, outputId: 'bus' }),
            ];
            vi.mocked(getTrackStoreState).mockReturnValue({ tracks } as any);

            applySoloLogic();

            expect(setTrackMute).toHaveBeenCalledWith('bus', false);
            expect(setTrackMute).toHaveBeenCalledWith('src', false);
        });
    });

    describe('PFL (Pre-Fader Listen) mode', () => {
        beforeEach(() => {
            vi.mocked(getWorkspaceState).mockReturnValue({ soloMode: 'pfl' } as any);
        });

        it('should boost soloed track to 1.0 gain and save original gain', () => {
            const tracks = [
                TrackDummy.create({ id: 't1', gain: 0.5, soloed: true }),
                TrackDummy.create({ id: 't2', gain: 0.8, soloed: false }),
            ];
            vi.mocked(getTrackStoreState).mockReturnValue({ tracks } as any);

            applySoloLogic();

            expect(setTrackGain).toHaveBeenCalledWith('t1', 1.0);
            expect(setTrackMute).toHaveBeenCalledWith('t1', false);
            expect(setTrackMute).toHaveBeenCalledWith('t2', true);
        });

        it('should restore original gain when solo is cleared', () => {
            const t1 = TrackDummy.create({ id: 't1', gain: 0.5, soloed: true });
            const tracksSoloed = [t1, TrackDummy.create({ id: 't2', soloed: false })];

            vi.mocked(getTrackStoreState).mockReturnValue({ tracks: tracksSoloed } as any);
            applySoloLogic();
            expect(setTrackGain).toHaveBeenCalledWith('t1', 1.0);

            const tracksUnsoloed = [{ ...t1, soloed: false }, TrackDummy.create({ id: 't2', soloed: false })];
            vi.mocked(getTrackStoreState).mockReturnValue({ tracks: tracksUnsoloed } as any);

            applySoloLogic();
            expect(setTrackGain).toHaveBeenCalledWith('t1', 0.5);
        });
    });
});

import { describe, it, expect } from 'vitest';

import { type Clip, type Device } from '../../models/Track';
import { computeTrackHash } from '../computeTrackHash';

describe('computeTrackHash', () => {
    it('computes a consistent SHA-256 hash for identical clips and devices', async () => {
        const clips: Clip[] = [
            { id: 'c1', startBeat: 0, endBeat: 4, assetHash: 'hash1', gain: 1 } as Clip,
            { id: 'c2', startBeat: 4, endBeat: 8, assetHash: 'hash2', gain: 0.5 } as Clip,
        ];

        const devices: Device[] = [
            { id: 'd1', type: 'eq', bypassed: false, parameterValues: { freq: 1000, gain: 2 } } as any,
        ];

        const hash1 = await computeTrackHash(clips, devices);
        const hash2 = await computeTrackHash(clips, devices);

        expect(hash1).toBe(hash2);
        expect(hash1).toMatch(/^[a-f0-9]{64}$/); // SHA-256 is 64 hex chars
    });

    it('produces different hashes when clip properties change', async () => {
        const clips1: Clip[] = [{ id: 'c1', startBeat: 0, endBeat: 4, assetHash: 'hash1', gain: 1 } as Clip];
        const clips2: Clip[] = [{ id: 'c1', startBeat: 0, endBeat: 4, assetHash: 'hash1', gain: 0.8 } as Clip];
        const devices: Device[] = [];

        const hash1 = await computeTrackHash(clips1, devices);
        const hash2 = await computeTrackHash(clips2, devices);

        expect(hash1).not.toBe(hash2);
    });

    it('produces different hashes when device properties change', async () => {
        const clips: Clip[] = [];
        const devices1: Device[] = [{ id: 'd1', type: 'eq', bypassed: false, parameterValues: { freq: 1000 } } as any];
        const devices2: Device[] = [{ id: 'd1', type: 'eq', bypassed: false, parameterValues: { freq: 2000 } } as any];

        const hash1 = await computeTrackHash(clips, devices1);
        const hash2 = await computeTrackHash(clips, devices2);

        expect(hash1).not.toBe(hash2);
    });

    it('sorts clips and parameters to ensure order independence where appropriate', async () => {
        // Clips are ordered by startBeat
        const clips1: Clip[] = [
            { id: 'c2', startBeat: 4, endBeat: 8, gain: 1 } as Clip,
            { id: 'c1', startBeat: 0, endBeat: 4, gain: 1 } as Clip,
        ];
        const clips2: Clip[] = [
            { id: 'c1', startBeat: 0, endBeat: 4, gain: 1 } as Clip,
            { id: 'c2', startBeat: 4, endBeat: 8, gain: 1 } as Clip,
        ];

        // Device parameter values should be sorted by key internally by computeTrackHash
        const devices1: Device[] = [{ id: 'd1', type: 'eq', bypassed: false, parameterValues: { a: 1, b: 2 } } as any];
        const devices2: Device[] = [{ id: 'd1', type: 'eq', bypassed: false, parameterValues: { b: 2, a: 1 } } as any];

        const hash1 = await computeTrackHash(clips1, devices1);
        const hash2 = await computeTrackHash(clips2, devices2);

        expect(hash1).toBe(hash2);
    });
});

