import { createStore } from '#/infra/store/createStore';

import { trackStore } from './trackStore';

export type TimelineViewState = {
    scrollX: number;
    scrollY: number;
    pixelsPerBeat: number;
    autoScrollEnabled: boolean;
};

export const timelineViewStore = createStore<TimelineViewState>({
    initialData: {
        scrollX: 0,
        scrollY: 0,
        pixelsPerBeat: 12,
        autoScrollEnabled: true,
    },
});

export function zoomTimeline(delta: number): void {
    const state = timelineViewStore.value;
    if (!state) {
        return;
    }
    const newPpb = Math.max(2, Math.min(80, state.pixelsPerBeat + delta));
    timelineViewStore.set({ ...state, pixelsPerBeat: newPpb });
}

export function scrollTimeline(deltaX: number): void {
    const state = timelineViewStore.value;
    if (!state) {
        return;
    }
    timelineViewStore.set({ ...state, scrollX: Math.max(0, state.scrollX + deltaX) });
}

export function setScrollX(scrollX: number): void {
    const state = timelineViewStore.value;
    if (!state) {
        return;
    }
    timelineViewStore.set({ ...state, scrollX: Math.max(0, scrollX) });
}

export function setAutoScroll(enabled: boolean): void {
    const state = timelineViewStore.value;
    if (!state) {
        return;
    }
    timelineViewStore.set({ ...state, autoScrollEnabled: enabled });
}

export function toggleAutoScroll(): void {
    const state = timelineViewStore.value;
    if (!state) {
        return;
    }
    timelineViewStore.set({ ...state, autoScrollEnabled: !state.autoScrollEnabled });
}

export function setScrollY(scrollY: number, viewportHeight = 200): void {
    const state = timelineViewStore.value;
    if (!state) {
        return;
    }
    // Clamp to prevent scrolling past the last track.
    // viewportHeight is the visible track area height — callers should pass
    // the actual container height for correct clamping.
    const tracks = trackStore.value?.tracks ?? [];
    const totalHeight = tracks
        .filter((time) => time.kind !== 'master')
        .reduce((sum, time) => sum + (time.height ?? 64), 0);
    const maxY = Math.max(0, totalHeight - viewportHeight);
    const clamped = Math.max(0, Math.min(maxY, scrollY));
    if (state.scrollY !== clamped) {
        timelineViewStore.set({ ...state, scrollY: clamped });
    }
}

/**
 * Transformer: pure automation point algorithms.
 * No I/O — mathematical functions for simplifying and interpolating automation curves.
 */

import { type AutomationPoint } from '../models/AutomationViewTypes';

function perpendicularDistance(
    point: { beat: number; value: number },
    lineStart: { beat: number; value: number },
    lineEnd: { beat: number; value: number }
): number {
    const dx = lineEnd.beat - lineStart.beat;
    const dy = lineEnd.value - lineStart.value;
    const lengthSq = dx * dx + dy * dy;
    if (lengthSq === 0) {
        const dbx = point.beat - lineStart.beat;
        const dby = point.value - lineStart.value;
        return Math.sqrt(dbx * dbx + dby * dby);
    }
    const num = Math.abs(
        dy * point.beat - dx * point.value + lineEnd.beat * lineStart.value - lineEnd.value * lineStart.beat
    );
    return num / Math.sqrt(lengthSq);
}

/**
 * Ramer-Douglas-Peucker algorithm for simplifying automation point curves
 * while preserving shape within a given tolerance.
 */
export function rdpSimplify(points: AutomationPoint[], tolerance: number): AutomationPoint[] {
    if (points.length <= 2) {
        return points;
    }

    let maxDist = 0;
    let maxIdx = 0;
    const first = points[0]!;
    const last = points[points.length - 1]!;

    for (let index = 1; index < points.length - 1; index++) {
        const dist = perpendicularDistance(points[index]!, first, last);
        if (dist > maxDist) {
            maxDist = dist;
            maxIdx = index;
        }
    }

    if (maxDist > tolerance) {
        const left = rdpSimplify(points.slice(0, maxIdx + 1), tolerance);
        const right = rdpSimplify(points.slice(maxIdx), tolerance);
        return [...left.slice(0, -1), ...right];
    }

    return [first, last];
}

/**
 * Apply tension to a normalized t value (0–1).
 * tension < 0: logarithmic (fast start, slow end)
 * tension = 0: linear
 * tension > 0: exponential (slow start, fast end)
 */
function applyTension(time: number, tension: number): number {
    if (Math.abs(tension) < 0.01) {
        return time;
    }
    // Use power curve with tension mapping
    const power = 2 ** (tension * 3); // Maps -1..+1 to 0.125..8
    return time ** power;
}

/**
 * Interpolates an automation value at a given beat position between two points.
 * Supports linear, step, exponential, s-curve, stairs, and smooth interpolation.
 */
export function interpolateAutomationValue(
    p1: AutomationPoint,
    p2: AutomationPoint,
    beat: number,
    prevPoint?: AutomationPoint,
    nextPoint?: AutomationPoint
): number {
    if (p2.beat === p1.beat) {
        return p1.value;
    }

    if (p1.curve === 'step') {
        return p1.value;
    }

    const time = (beat - p1.beat) / (p2.beat - p1.beat);

    if (p1.curve === 'stairs') {
        const steps = p1.stairSteps ?? 4;
        const steppedT = Math.floor(time * steps) / steps;
        return p1.value + (p2.value - p1.value) * steppedT;
    }

    if (p1.curve === 'exponential') {
        const tension = p1.tension ?? 0;
        const expT = applyTension(time, tension);
        return p1.value + (p2.value - p1.value) * expT;
    }

    if (p1.curve === 's-curve') {
        const tension = p1.tension ?? 0.5;
        const st = time * time * (3 - 2 * time); // Hermite basis
        const curved = time + (st - time) * Math.abs(tension);
        return p1.value + (p2.value - p1.value) * curved;
    }

    if (p1.curve === 'smooth') {
        // Catmull-Rom spline: uses neighboring points for tangents
        const v0 = prevPoint?.value ?? p1.value;
        const v1 = p1.value;
        const v2 = p2.value;
        const v3 = nextPoint?.value ?? p2.value;

        const t2 = time * time;
        const t3 = t2 * time;

        // Catmull-Rom coefficients
        const result =
            0.5 *
            (2 * v1 + (-v0 + v2) * time + (2 * v0 - 5 * v1 + 4 * v2 - v3) * t2 + (-v0 + 3 * v1 - 3 * v2 + v3) * t3);

        return result;
    }

    // Linear
    return p1.value + (p2.value - p1.value) * time;
}

/**
 * Generate an array of points for a shape within a beat range.
 */
export type AutomationShapeType = 'sine' | 'triangle' | 'sawtooth-up' | 'sawtooth-down' | 'square' | 'random';

export function generateShapePoints(
    shape: AutomationShapeType,
    startBeat: number,
    endBeat: number,
    minValue: number,
    maxValue: number
): AutomationPoint[] {
    const range = maxValue - minValue;
    const duration = endBeat - startBeat;
    const mid = startBeat + duration / 2;

    function pt(beat: number, norm: number, curve: AutomationPoint['curve'] = 'linear', tension = 0): AutomationPoint {
        return {
            beat,
            value: minValue + norm * range,
            curve,
            tension,
        };
    }

    switch (shape) {
        case 'square':
            // 4 points: high → step down at midpoint → step back at end
            return [pt(startBeat, 1, 'step'), pt(mid, 0, 'step'), pt(endBeat, 1, 'step')];

        case 'triangle':
            // 3 points: low → peak at midpoint → low
            return [pt(startBeat, 0), pt(mid, 1), pt(endBeat, 0)];

        case 'sawtooth-up':
            // 2 points: ramp from low to high
            return [pt(startBeat, 0), pt(endBeat, 1)];

        case 'sawtooth-down':
            // 2 points: ramp from high to low
            return [pt(startBeat, 1), pt(endBeat, 0)];

        case 'sine':
            // 5 key points with smooth curve interpolation
            return [
                pt(startBeat, 0, 'smooth', 0.5),
                pt(startBeat + duration * 0.25, 1, 'smooth', 0.5),
                pt(mid, 0, 'smooth', 0.5),
                pt(startBeat + duration * 0.75, 0, 'smooth', 0.5),
                pt(endBeat, 0, 'smooth', 0.5),
            ];

        case 'random': {
            // 8 random points
            const count = 8;
            const pts: AutomationPoint[] = [];
            for (let index = 0; index <= count; index++) {
                pts.push(pt(startBeat + (index / count) * duration, Math.random()));
            }
            return pts;
        }
    }

    return [];
}

/**
 * Determine contiguous automation regions (for virgin territory rendering).
 * Returns beat ranges where automation data has been explicitly written.
 * Adjacent points (within maxGap beats) are considered part of the same region.
 */
export function getAutomationRegions(
    points: AutomationPoint[],
    maxGap = Infinity
): { startBeat: number; endBeat: number }[] {
    if (points.length === 0) {
        return [];
    }

    const sorted = [...points].sort((alpha, buffer) => alpha.beat - buffer.beat);
    const regions: { startBeat: number; endBeat: number }[] = [];
    let regionStart = sorted[0]!.beat;
    let regionEnd = sorted[0]!.beat;

    for (let index = 1; index < sorted.length; index++) {
        const param = sorted[index]!;
        if (param.beat - regionEnd > maxGap) {
            regions.push({ startBeat: regionStart, endBeat: regionEnd });
            regionStart = param.beat;
        }
        regionEnd = param.beat;
    }

    regions.push({ startBeat: regionStart, endBeat: regionEnd });
    return regions;
}

/**
 * Transformer: pure velocity curve functions.
 * No I/O — applies mathematical curves to normalized velocity values.
 */

export type VelocityCurve = 'linear' | 'exponential' | 'logarithmic' | 's-curve' | 'compress' | 'expand';

export function applyVelocityCurve(normalized: number, curve: VelocityCurve): number {
    switch (curve) {
        case 'linear': {
            return normalized;
        }
        case 'exponential': {
            return normalized * normalized;
        }
        case 'logarithmic': {
            return Math.sqrt(normalized);
        }
        case 's-curve': {
            if (normalized < 0.5) {
                return 2 * normalized * normalized;
            }
            return 1 - 2 * (1 - normalized) * (1 - normalized);
        }
        case 'compress': {
            return 0.3 + normalized * 0.4;
        }
        case 'expand': {
            if (normalized < 0.5) {
                return normalized * 0.3;
            }
            return 0.7 + (normalized - 0.5) * 1.4;
        }
        default:
            throw new Error(`Unknown velocity curve: ${curve}`);
    }
}

