import { logger } from '#/infra/logger/appLogger';
import { addMidiFxToStrip } from '#/modules/AudioEngine/useCases';

import { updateTrack } from '../updateTrack';

export function addMidiFx(trackId: string, fxType: 'arp' | 'velocity' | 'probability', name?: string): void {
    const fxId = `midi-fx-${crypto.randomUUID().slice(0, 8)}`;

    updateTrack(trackId, (track) => {
        const nextMidiFx = [...(track.midiFx || [])];
        nextMidiFx.push({
            id: fxId,
            name: name ?? fxType.toUpperCase(),
            type: fxType,
            bypassed: false,
            parameterValues: {},
        });
        return { ...track, midiFx: nextMidiFx };
    });

    try {
        addMidiFxToStrip(trackId, fxId, fxType);
    } catch (error) {
        logger.warn(`Failed to add MIDI FX to engine: ${error}`);
    }
}

import { updateMidiFxBypass } from '#/modules/AudioEngine/useCases';

import { updateTrack } from '../updateTrack';

export function bypassMidiFx(trackId: string, fxId: string, bypassed: boolean): void {
    updateTrack(trackId, (track) => {
        if (track.kind !== 'midi') {
            return track;
        }
        const nextMidiFx = track.midiFx?.map((fx) => (fx.id === fxId ? { ...fx, bypassed } : fx)) ?? [];
        return { ...track, midiFx: nextMidiFx };
    });

    try {
        updateMidiFxBypass(trackId, fxId, bypassed);
    } catch (error) {
        console.warn(`Failed to bypass MIDI FX in engine: ${error}`);
    }
}

import { removeMidiFxFromStrip } from '#/modules/AudioEngine/useCases';

import { updateTrack } from '../updateTrack';

export function removeMidiFx(trackId: string, fxId: string): void {
    updateTrack(trackId, (track) => {
        if (track.kind !== 'midi') {
            return track;
        }
        const nextMidiFx = track.midiFx?.filter((fx) => fx.id !== fxId) ?? [];
        return { ...track, midiFx: nextMidiFx };
    });

    try {
        removeMidiFxFromStrip(trackId, fxId);
    } catch (error) {
        console.warn(`Failed to remove MIDI FX from engine: ${error}`);
    }
}

