        expect(updatedTrack.clips).toHaveLength(1);

        const clip = updatedTrack.clips[0];
        expect(clip.startBeat).toBe(2);
        expect(clip.endBeat).toBe(12); // 8 (clip end) + 2s * (120 BPM / 60) = 8 + 4 beats
