            selectedTrackId: null,
        });
        await freezeTrack('t1');
        expect(updateTrack).not.toHaveBeenCalled();
    });

    it('freezes the track successfully', async () => {
        trackStore.set({
            tracks: [
                {
                    id: 't1',
                    clips: [{ startBeat: 2, endBeat: 6 }],
                    devices: [],
                    freezeState: { status: 'unfrozen' },
