export function getTrackAtY(
    tracks: { height: number; id: string }[],
    contentY: number
): { index: number; id: string } | null {
    let offset = 0;
    for (let index = 0; index < tracks.length; index++) {
        const h = tracks[index]!.height ?? 64;
        if (contentY >= offset && contentY < offset + h) {
            return { index, id: tracks[index]!.id };
        }
        offset += h;
    }
    return null;
}

import { automationStore } from '#/modules/Automation/stores';
import { workspaceStore } from '#/modules/Workspace/stores';

import { AUTOMATION_SUB_LANE_HEIGHT } from '../../automationConstants';
import { timelineViewStore } from '../../stores/timelineViewStore';
import { trackStore } from '../../stores/trackStore';
import { buildTimelineRenderModel } from '../buildTimelineRenderModel';

export type AutomationSubLaneHit = {
    laneId: string;
    trackId: string;
    subLaneIndex: number;
    value: number; // normalized 0..1 within the sub-lane
    beat: number;
};

const RULER_HEIGHT = 0;

export function hitTestAutomationSubLane(canvasX: number, canvasY: number): AutomationSubLaneHit | null {
    const viewState = timelineViewStore.value;
    const trackState = trackStore.value;
    const workspace = workspaceStore.value;
    if (!viewState || !trackState || !workspace || workspace.automationVisibility === 'hidden') {
        return null;
    }

    const contentY = Math.max(0, canvasY - RULER_HEIGHT + (viewState.scrollY ?? 0));

    const subLaneMap = workspace.automationSubLanes;
    const model = buildTimelineRenderModel();
    if (!model) {
        return null;
    }

    let trackYOffset = 0;

    for (const track of model.tracks) {
        const paramIds = subLaneMap[track.id] ?? [];
        const totalHeight = track.height;
        const baseHeight = totalHeight - paramIds.length * AUTOMATION_SUB_LANE_HEIGHT;
        const trackBottom = trackYOffset + totalHeight;

        if (contentY >= trackYOffset && contentY < trackBottom) {
            const localY = contentY - trackYOffset;
            if (localY >= baseHeight && paramIds.length > 0) {
                const subLaneLocalY = localY - baseHeight;
                const subLaneIndex = Math.floor(subLaneLocalY / AUTOMATION_SUB_LANE_HEIGHT);
                if (subLaneIndex >= 0 && subLaneIndex < paramIds.length) {
                    const withinLaneY = subLaneLocalY - subLaneIndex * AUTOMATION_SUB_LANE_HEIGHT;
                    const value = Math.max(0, Math.min(1, 1 - (withinLaneY - 2) / (AUTOMATION_SUB_LANE_HEIGHT - 4)));
                    const beat = canvasX / viewState.pixelsPerBeat + viewState.scrollX / viewState.pixelsPerBeat;

                    const autoState = automationStore.value;
                    const lane = autoState?.lanes.find(
                        (length) => length.trackId === track.id && length.parameterId === paramIds[subLaneIndex]
                    );

                    if (lane) {
                        return {
                            laneId: lane.id,
                            trackId: track.id,
                            subLaneIndex,
                            value,
                            beat,
                        };
                    }
                }
            }
        }
        trackYOffset += totalHeight;
    }

    return null;
}

import { timelineViewStore } from '../../../stores/timelineViewStore';
import { buildTimelineRenderModel } from '../../buildTimelineRenderModel';
import { getTrackAtY } from '../getTrackAtY';

import { RULER_HEIGHT } from './helpers';

export type ClipHitResult = {
    clipId: string;
    trackId: string;
    noteId?: string;
    pitch?: number;
    noteHeight?: number;
};

export function hitTestClip(canvasX: number, canvasY: number): ClipHitResult | null {
    const viewState = timelineViewStore.value;
    const model = buildTimelineRenderModel();
    if (!viewState || !model) {
        return null;
    }

    const contentY = Math.max(0, canvasY - RULER_HEIGHT + (viewState.scrollY ?? 0));
    const hit = getTrackAtY(model.tracks, contentY);
    if (!hit) {
        return null;
    }

    const track = model.tracks[hit.index];
    if (!track) {
        return null;
    }

    const pixelsPerBeat = viewState.pixelsPerBeat;
    const scrollX = viewState.scrollX;
    const viewportStartBeat = scrollX / pixelsPerBeat;
    const beat = canvasX / pixelsPerBeat + viewportStartBeat;

    let trackYOffset = 0;
    for (let index = 0; index < hit.index; index++) {
        trackYOffset += model.tracks[index]!.height;
    }

    for (const clip of track.clips) {
        if (beat >= clip.startBeat && beat < clip.endBeat) {
            // R-A11: Hit test for individual notes if inline editing is active
            if (clip.isInlineEditing && clip.type === 'midi' && clip.midiNotes.length > 0) {
                const padding = 2;
                const contentTop = trackYOffset + padding;
                const contentHeight = track.height - padding * 2;
                const notes = clip.midiNotes;

                const minPitch = Math.min(...notes.map((node) => node.pitch)) - 2;
                const maxPitch = Math.max(...notes.map((node) => node.pitch)) + 2;
                const pitchRange = Math.max(maxPitch - minPitch, 1);
                const noteHeight = contentHeight / (pitchRange + 1);

                for (const note of notes) {
                    const noteX = (note.startBeat - viewportStartBeat) * pixelsPerBeat;
                    const noteW = note.duration * pixelsPerBeat;
                    const pitchNorm = (note.pitch - minPitch) / (pitchRange + 1);
                    const noteY = contentTop + contentHeight - (pitchNorm + 1 / (pitchRange + 1)) * contentHeight;

                    if (
                        canvasX >= noteX &&
                        canvasX <= noteX + noteW &&
                        contentY >= noteY &&
                        contentY <= noteY + noteHeight
                    ) {
                        return { clipId: clip.id, trackId: track.id, noteId: note.id, pitch: note.pitch, noteHeight };
                    }
                }
            }
            return { clipId: clip.id, trackId: track.id };
        }
    }

    // H3: Hit testing for variation lanes
    if (track.variationLanes && track.variationLanes.length > 0) {
        const varLaneHeight = 24;
        for (let index = 0; index < track.variationLanes.length; index++) {
            const lane = track.variationLanes[index]!;
            const ly = trackYOffset + track.height + index * varLaneHeight;
            if (contentY >= ly && contentY <= ly + varLaneHeight) {
                for (const clip of lane.clips) {
                    if (beat >= clip.startBeat && beat < clip.endBeat) {
                        return { clipId: clip.id, trackId: track.id };
                    }
                }
            }
        }
    }

    return null;
}

import { timelineViewStore } from '../../../stores/timelineViewStore';
import { buildTimelineRenderModel } from '../../buildTimelineRenderModel';
import { getTrackAtY } from '../getTrackAtY';

import { RULER_HEIGHT } from './helpers';

export function hitTestTrack(canvasY: number): string | null {
    const viewState = timelineViewStore.value;
    const model = buildTimelineRenderModel();
    if (!model) {
        return null;
    }

    const contentY = Math.max(0, canvasY - RULER_HEIGHT + (viewState?.scrollY ?? 0));
    const hit = getTrackAtY(model.tracks, contentY);
    return hit?.id ?? null;
}

import { timelineViewStore } from '../../stores/timelineViewStore';
import { buildTimelineRenderModel } from '../buildTimelineRenderModel';

import { getTrackAtY } from './getTrackAtY';

export type ClipEdge = 'left' | 'right' | 'body';

const RULER_HEIGHT = 0;
const EDGE_THRESHOLD_PX = 10;

export function hitTestClipEdge(
    canvasX: number,
    canvasY: number
): { clipId: string; trackId: string; edge: ClipEdge } | null {
    const viewState = timelineViewStore.value;
    const model = buildTimelineRenderModel();
    if (!viewState || !model) {
        return null;
    }

    const contentY = Math.max(0, canvasY - RULER_HEIGHT + (viewState.scrollY ?? 0));
    const hit = getTrackAtY(model.tracks, contentY);
    if (!hit) {
        return null;
    }

    const track = model.tracks[hit.index];
    if (!track) {
        return null;
    }

    const viewportStartBeat = viewState.scrollX / viewState.pixelsPerBeat;
    const beat = canvasX / viewState.pixelsPerBeat + viewportStartBeat;

    for (const clip of track.clips) {
        if (beat >= clip.startBeat && beat <= clip.endBeat) {
            const clipStartPx = (clip.startBeat - viewportStartBeat) * viewState.pixelsPerBeat;
            const clipEndPx = (clip.endBeat - viewportStartBeat) * viewState.pixelsPerBeat;

            if (canvasX - clipStartPx < EDGE_THRESHOLD_PX) {
                return { clipId: clip.id, trackId: track.id, edge: 'left' };
            }
            if (clipEndPx - canvasX < EDGE_THRESHOLD_PX) {
                return { clipId: clip.id, trackId: track.id, edge: 'right' };
            }
            return { clipId: clip.id, trackId: track.id, edge: 'body' };
        }
    }
    return null;
}

