import { detectIssues, generateSuggestions, readFrequencyBalance, readLevels } from '#/modules/AiRuntime/useCases';
import { getTrackStoreState } from '#/modules/Arrangement/useCases';
import { getMasterAnalyser, getTrackStrip } from '#/modules/AudioEngine/useCases';

// AudioAnalysis-local shape (AGENTS.md §95 — model isolation). Structurally
// compatible with AiRuntime's MixAnalysis; no cross-module model import.
type MixIssue = {
    severity: 'info' | 'warning' | 'critical';
    category: 'level' | 'frequency' | 'stereo' | 'dynamics';
    message: string;
    trackId?: string;
};

export type AnalyzeMixOutput = {
    timestamp: number;
    overallLevel: { peakDb: number; rmsDb: number };
    frequencyBalance: {
        sub: number;
        bass: number;
        lowMid: number;
        mid: number;
        highMid: number;
        high: number;
    };
    trackLevels: Array<{
        trackId: string;
        trackName: string;
        peakDb: number;
        rmsDb: number;
        isMuted: boolean;
        isSoloed: boolean;
        isClipping: boolean;
    }>;
    issues: MixIssue[];
    suggestions: string[];
};

export async function analyzeMix(): Promise<AnalyzeMixOutput> {
    const masterAnalyser = getMasterAnalyser();
    const masterLevels = readLevels(masterAnalyser);
    const frequencyBalance = readFrequencyBalance(masterAnalyser);

    const state = getTrackStoreState();
    const tracks = state?.tracks ?? [];

    const trackLevels: AnalyzeMixOutput['trackLevels'] = [];

    for (const track of tracks) {
        if (track.kind === 'folder' || track.kind === 'master') {
            continue;
        }

        const strip = getTrackStrip(track.id);
        if (!strip) {
            continue;
        }

        const levels = readLevels(strip.analyserNode);

        trackLevels.push({
            trackId: track.id,
            trackName: track.name,
            peakDb: levels.peakDb,
            rmsDb: levels.rmsDb,
            isMuted: strip.muted,
            isSoloed: strip.soloed,
            isClipping: levels.peakDb > -0.5,
        });
    }

    const issues = detectIssues({ masterLevels, bands: frequencyBalance, trackLevels });
    const suggestions = generateSuggestions({
        masterLevels,
        bands: frequencyBalance,
        trackLevels,
        issues,
    });

    return {
        timestamp: Date.now(),
        overallLevel: masterLevels,
        frequencyBalance,
        trackLevels,
        issues,
        suggestions,
    };
}

/**
 * Use case: Audio feature extraction using Meyda.
 *
 * Provides spectral analysis, loudness metering, and timbral features
 * for audio clips. Used for automated mixing decisions, similarity
 * matching, and AI-assisted sound design.
 *
 * License: MIT (safe for commercial use).
 */

import Meyda from 'meyda';

import { audioBufferCache } from '#/modules/AudioEngine/stores';

// ── Types ───────────────────────────────────────────────────────────────

export type AudioFeatures = {
    rms: number;
    energy: number;
    spectralCentroid: number;
    spectralFlatness: number;
    spectralRolloff: number;
    zcr: number;
    loudness: { total: number; specific: Float32Array };
    mfcc: number[];
    chroma: number[];
};

export type AudioFeaturesSummary = {
    /** Average RMS level (0-1 range) */
    avgRms: number;
    /** Peak RMS level */
    peakRms: number;
    /** Average spectral centroid in Hz (brightness) */
    avgSpectralCentroid: number;
    /** Average spectral flatness (0=tonal, 1=noisy) */
    avgSpectralFlatness: number;
    /** Average zero crossing rate (higher = noisier/brighter) */
    avgZcr: number;
    /** Chroma profile (12-element array, average energy per pitch class) */
    chromaProfile: number[];
    /** Number of analysis frames */
    frameCount: number;
};

export type AnalysisOptions = {
    /** FFT size (default 2048) */
    bufferSize?: number;
    /** Hop size (default 512) */
    hopSize?: number;
};

// ── Feature extraction ──────────────────────────────────────────────────

/**
 * Extract per-frame audio features from a buffer using Meyda.
 * Returns an array of feature snapshots, one per analysis window.
 */
export function extractFeatures(audioBufferId: string, options: AnalysisOptions = {}): AudioFeatures[] {
    const { bufferSize = 2048, hopSize = 512 } = options;

    const buffer = audioBufferCache.get(audioBufferId);
    if (!buffer) {
        return [];
    }

    const data = buffer.getChannelData(0);
    const frames: AudioFeatures[] = [];

    // Set Meyda global config (extract reads from these)
    Meyda.sampleRate = buffer.sampleRate;
    Meyda.bufferSize = bufferSize;

    // Reuse one window buffer across all hops instead of allocating a new
    // Float32Array(bufferSize) per iteration (§70.1). At bufferSize=2048
    // and ~50% overlap that was ~1.5k allocations per second of audio.
    const window = new Float32Array(bufferSize);

    for (let offset = 0; offset + bufferSize <= data.length; offset += hopSize) {
        window.set(data.subarray(offset, offset + bufferSize));

        const features = Meyda.extract(
            [
                'rms',
                'energy',
                'spectralCentroid',
                'spectralFlatness',
                'spectralRolloff',
                'zcr',
                'loudness',
                'mfcc',
                'chroma',
            ],
            window
        );

        if (features) {
            frames.push({
                rms: (features.rms as number) ?? 0,
                energy: (features.energy as number) ?? 0,
                spectralCentroid: (features.spectralCentroid as number) ?? 0,
                spectralFlatness: (features.spectralFlatness as number) ?? 0,
                spectralRolloff: (features.spectralRolloff as number) ?? 0,
                zcr: (features.zcr as number) ?? 0,
                loudness: (features.loudness as { total: number; specific: Float32Array }) ?? {
                    total: 0,
                    specific: new Float32Array(0),
                },
                mfcc: (features.mfcc as number[]) ?? [],
                chroma: (features.chroma as number[]) ?? [],
            });
        }
    }

    return frames;
}

/**
 * Compute a summary of audio features across the entire buffer.
 * Useful for quick analysis and comparison between clips.
 */
export function summarizeFeatures(audioBufferId: string, options?: AnalysisOptions): AudioFeaturesSummary | null {
    const frames = extractFeatures(audioBufferId, options);
    if (frames.length === 0) {
        return null;
    }

    const node = frames.length;

    const avgRms = frames.reduce((sum, freq) => sum + freq.rms, 0) / node;
    let peakRms = -Infinity;
    for (const freq of frames) {
        if (freq.rms > peakRms) {
            peakRms = freq.rms;
        }
    }
    const avgSpectralCentroid = frames.reduce((sum, freq) => sum + freq.spectralCentroid, 0) / node;
    const avgSpectralFlatness = frames.reduce((sum, freq) => sum + freq.spectralFlatness, 0) / node;
    const avgZcr = frames.reduce((sum, freq) => sum + freq.zcr, 0) / node;

    // Average chroma profile
    const chromaProfile: number[] = Array.from({ length: 12 }).fill(0) as number[];
    for (const freq of frames) {
        for (let index = 0; index < 12; index++) {
            const chromaVal = freq.chroma[index] ?? 0;
            chromaProfile[index] = (chromaProfile[index] ?? 0) + chromaVal / node;
        }
    }

    return {
        avgRms,
        peakRms,
        avgSpectralCentroid,
        avgSpectralFlatness,
        avgZcr,
        chromaProfile,
        frameCount: node,
    };
}

import { trackStore } from '#/modules/Arrangement/stores';
import { type FrequencyBand, type MixAnalysis } from '#/modules/AudioAnalysis/models/MixComparisonTypes';

function estimateFrequencyProfile(tracks: Array<{ kind: string; gain?: number }>): Record<FrequencyBand, number> {
    const profile: Record<FrequencyBand, number> = {
        sub: 0.3,
        bass: 0.5,
        'low-mid': 0.6,
        mid: 0.7,
        'high-mid': 0.6,
        presence: 0.5,
        air: 0.3,
    };

    const midiTracks = tracks.filter((time) => time.kind === 'midi').length;
    const audioTracks = tracks.filter((time) => time.kind === 'audio').length;
    const totalTracks = tracks.length || 1;

    if (midiTracks / totalTracks > 0.5) {
        profile.mid += 0.15;
        profile['high-mid'] += 0.1;
    }
    if (audioTracks / totalTracks > 0.5) {
        profile.bass += 0.1;
        profile['low-mid'] += 0.1;
    }

    const max = Math.max(...Object.values(profile));
    for (const band of Object.keys(profile) as FrequencyBand[]) {
        profile[band] = Math.min(1, profile[band] / max);
    }

    return profile;
}

function createDefaultAnalysis(): MixAnalysis {
    return {
        rmsDb: -18,
        peakDb: -6,
        lufs: -14,
        frequencyProfile: { sub: 0.3, bass: 0.5, 'low-mid': 0.6, mid: 0.7, 'high-mid': 0.6, presence: 0.5, air: 0.3 },
        stereoWidth: 0.5,
        dynamicRange: 10,
        crestFactor: 7,
    };
}

/**
 * Analyze a mix based on track configuration.
 * In production this would use actual audio analysis;
 * here we derive estimates from track gain/pan/device settings.
 */
export function analyzeMix(): MixAnalysis {
    const state = trackStore.value;
    if (!state) {
        return createDefaultAnalysis();
    }

    const tracks = state.tracks.filter((time) => !time.muted && time.kind !== 'folder');
    const trackCount = tracks.length || 1;

    const gains = tracks.map((time) => time.gain ?? 0);
    const avgGain = gains.reduce((alpha, b) => alpha + b, 0) / trackCount;
    const rmsDb = Math.max(-60, avgGain - 6);
    const peakDb = Math.max(-60, avgGain - 1);
    const lufs = rmsDb - 3;

    const frequencyProfile = estimateFrequencyProfile(tracks);

    const pans = tracks.map((time) => Math.abs(time.pan ?? 0));
    const stereoWidth = pans.length > 0 ? pans.reduce((alpha, b) => alpha + b, 0) / pans.length : 0.5;

    const dynamicRange = Math.min(20, Math.max(3, 14 - trackCount * 0.5));
    const crestFactor = dynamicRange * 0.7;

    return { rmsDb, peakDb, lufs, frequencyProfile, stereoWidth, dynamicRange, crestFactor };
}

/**
 * BacteriaNode — AudioWorkletNode wrapper for the Bacteria creative multi-effects.
 *
 * Same pattern as GlutenNode: caches WASM binary, resumes AudioContext,
 * provides setParam/setBypass via MessagePort.
 */

import bacteriaProcessorUrl from '../services/bacteriaProcessor.ts?worker&url';

import { requireSharedArrayBuffer } from './pluginHostingErrors';
import { telemetryAllocator, BACTERIA_IDX, BACTERIA_BAND_COUNT, type TelemetrySlot } from './telemetryAllocator';
import { createReadyHandshake, ensureWorkletRegistered, fetchWasmBinary } from './workletInitShared';

/** Linear amplitude → dB with a -100 dB floor (matches input/output dB range). */
function linearToDb(linear: number): number {
    if (linear <= 1e-5) {
        return -100;
    }
    return 20 * Math.log10(linear);
}

const DEFAULT_WASM_URL = '/wasm/daw-dsp/daw_dsp_bg.wasm';

export type BacteriaMeterData = {
    inputDb: number;
    outputDb: number;
    bandLevels: number[];
    latency: number;
};

export type BacteriaNodeResult = {
    workletNode: AudioWorkletNode;
    setParam: (name: string, value: number) => void;
    setBypass: (bypassed: boolean) => void;
    onMeterData: (cb: (data: BacteriaMeterData) => void) => void;
    connect: (dest: AudioNode) => void;
    disconnect: () => void;
    destroy: () => void;
    ready: Promise<void>;
};

export function isBacteriaDevice(deviceType: string): boolean {
    return deviceType === 'bacteria';
}

export async function createBacteriaNode(ctx: BaseAudioContext, wasmUrl?: string): Promise<BacteriaNodeResult> {
    // Bacteria's per-band meter telemetry lives in a SAB slot. Guard here so
    // the worklet setup doesn't run pointlessly in an un-isolated environment.
    requireSharedArrayBuffer('Bacteria');

    if (ctx instanceof AudioContext && ctx.state === 'suspended') {
        await ctx.resume();
    }

    await ensureWorkletRegistered(ctx, bacteriaProcessorUrl);

    const node = new AudioWorkletNode(ctx, 'bacteria-processor', {
        numberOfInputs: 1,
        numberOfOutputs: 1,
        outputChannelCount: [2],
        channelCount: 2,
        channelCountMode: 'explicit',
    });

    let slot: TelemetrySlot | null = telemetryAllocator.allocateSlot();
    let meterRafId: number | null = null;

    if (slot) {
        node.port.postMessage({ type: 'init-sab', sab: slot.sab, byteOffset: slot.byteOffset });
    }

    const handshake = createReadyHandshake({ pluginName: 'BacteriaNode' });
    node.port.onmessage = (event: MessageEvent) => {
        handshake.onMessage(event);
    };
    const readyPromise = handshake.promise;

    const wasmBytes = await fetchWasmBinary(wasmUrl ?? DEFAULT_WASM_URL);
    const copy = wasmBytes.slice(0);
    node.port.postMessage({ type: 'init', wasmBytes: copy }, [copy]);

    return {
        workletNode: node,
        setParam(name: string, value: number) {
            if (Number.isFinite(value)) {
                node.port.postMessage({ type: 'param', name, value });
            }
        },
        setBypass(state: boolean) {
            node.port.postMessage({ type: 'param', name: 'bypass', value: state ? 1 : 0 });
        },
        onMeterData(cb: (data: BacteriaMeterData) => void) {
            if (meterRafId !== null) {
                cancelAnimationFrame(meterRafId);
                meterRafId = null;
            }
            if (!slot) {
                return;
            }
            const view = slot.view;
            const poll = () => {
                const bandLevels = new Array<number>(BACTERIA_BAND_COUNT);
                for (let index = 0; index < BACTERIA_BAND_COUNT; index++) {
                    const linear = view[BACTERIA_IDX.bandLevelsBase + index] ?? 0;
                    bandLevels[index] = linearToDb(linear);
                }
                cb({
                    inputDb: view[BACTERIA_IDX.inputDb] ?? 0,
                    outputDb: view[BACTERIA_IDX.outputDb] ?? 0,
                    bandLevels,
                    latency: view[BACTERIA_IDX.latency] ?? 0,
                });
                meterRafId = requestAnimationFrame(poll);
            };
            meterRafId = requestAnimationFrame(poll);
        },
        connect(dest: AudioNode) {
            node.connect(dest);
        },
        disconnect() {
            try {
                node.disconnect();
            } catch {
                // ignore
            }
        },
        destroy() {
            if (meterRafId !== null) {
                cancelAnimationFrame(meterRafId);
                meterRafId = null;
            }
            if (slot) {
                telemetryAllocator.releaseSlot(slot.byteOffset);
                slot = null;
            }
            try {
                node.disconnect();
            } catch {
                // ignore
            }
            node.port.close();
        },
        ready: readyPromise,
    };
}

import type { BusStrip } from '../models/AudioEngineState';

export class BusNode {
    public strip: BusStrip;

    constructor(
        public busId: string,
        private context: BaseAudioContext,
        masterGainNode: GainNode
    ) {
        const gainNode = context.createGain();
        gainNode.gain.value = 1;

        const analyserNode = context.createAnalyser();
        analyserNode.fftSize = 256;
        analyserNode.smoothingTimeConstant = 0.8;

        gainNode.connect(analyserNode);
        analyserNode.connect(masterGainNode);

        this.strip = {
            busId,
            gainNode,
            analyserNode,
            meterBuffer: new Float32Array(analyserNode.frequencyBinCount),
        };
    }

    public setGain(gain: number): void {
        this.strip.gainNode.gain.setTargetAtTime(Math.max(0, Math.min(2, gain)), this.context.currentTime, 0.01);
    }

    public getPeakLevel(): number {
        const data = this.strip.meterBuffer;
        if (data) {
            // `Float32Array<ArrayBuffer>` is what the Web Audio DOM lib type
            // requires; our model stores the default `Float32Array<ArrayBufferLike>`.
            // Both are compatible at runtime — the cast is purely structural.
            this.strip.analyserNode.getFloatTimeDomainData(data as Float32Array<ArrayBuffer>);
        }
        let peak = 0;
        for (let index = 0; index < data.length; index++) {
            const abs = Math.abs(data[index]!);
            if (abs > peak) {
                peak = abs;
            }
        }
        return peak;
    }

    public dispose(): void {
        this.strip.gainNode.disconnect();
        this.strip.analyserNode.disconnect();
    }
}

/**
 * FermenterNode — AudioWorkletNode wrapper for the Fermenter synthesizer.
 *
 * Creates and manages the WASM-powered worklet. Provides noteOn/noteOff/setParam
 * methods that forward via MessagePort. Caches WASM binary and worklet registration.
 */

import fermenterProcessorUrl from '../services/fermenterProcessor.ts?worker&url';

import { createReadyHandshake, ensureWorkletRegistered, fetchWasmBinary } from './workletInitShared';

const DEFAULT_WASM_URL = '/wasm/daw-dsp/daw_dsp_bg.wasm';

export type FermenterNodeResult = {
    workletNode: AudioWorkletNode;
    noteOn: (note: number, velocity: number, sampleFrame?: number) => void;
    noteOff: (note: number, sampleFrame?: number) => void;
    setParam: (name: string, value: number, sampleFrame?: number) => void;
    setPatch: (patch: Record<string, unknown>) => void;
    setBypass: (bypassed: boolean) => void;
    onTelemetry: (callback: (data: { peakL: number; peakR: number; scopeBuffer: Float32Array }) => void) => void;
    connect: (dest: AudioNode) => void;
    disconnect: () => void;
    destroy: () => void;
    ready: Promise<void>;
};

export function isFermenterDevice(deviceType: string): boolean {
    return deviceType === 'fermenter';
}

/**
 * Create a Fermenter AudioWorkletNode.
 *
 * Resumes the AudioContext if suspended (worklet processors only run when active).
 * Caches WASM binary across calls. Await `result.ready` before sending MIDI.
 */
export async function createFermenterNode(ctx: BaseAudioContext, wasmUrl?: string): Promise<FermenterNodeResult> {
    if (ctx instanceof AudioContext && ctx.state === 'suspended') {
        await ctx.resume();
    }

    await ensureWorkletRegistered(ctx, fermenterProcessorUrl);

    const node = new AudioWorkletNode(ctx, 'fermenter-processor', {
        numberOfInputs: 0,
        numberOfOutputs: 1,
        outputChannelCount: [2],
        channelCount: 2,
        channelCountMode: 'explicit',
    });

    let bypassed = false;

    const handshake = createReadyHandshake({ pluginName: 'FermenterNode' });
    const telemetryListeners = new Set<(data: { peakL: number; peakR: number; scopeBuffer: Float32Array }) => void>();
    node.port.onmessage = (event: MessageEvent) => {
        if (event.data?.type === 'telemetry') {
            const data = { peakL: event.data.peakL, peakR: event.data.peakR, scopeBuffer: event.data.scopeBuffer };
            for (const listener of telemetryListeners) {
                listener(data);
            }
        } else {
            handshake.onMessage(event);
        }
    };
    const readyPromise = handshake.promise;

    const wasmBytes = await fetchWasmBinary(wasmUrl ?? DEFAULT_WASM_URL);
    const copy = wasmBytes.slice(0);
    node.port.postMessage({ type: 'init', wasmBytes: copy }, [copy]);

    return {
        workletNode: node,
        noteOn(note: number, velocity: number, _midiNote?: number, sampleFrame?: number) {
            if (!bypassed && note >= 0 && note < 128) {
                node.port.postMessage({
                    type: 'noteOn',
                    note,
                    velocity: Math.min(127, Math.max(0, velocity)),
                    sampleFrame,
                });
            }
        },
        noteOff(note: number, sampleFrame?: number) {
            node.port.postMessage({ type: 'noteOff', note, sampleFrame });
        },
        setParam(name: string, value: number, sampleFrame?: number) {
            if (Number.isFinite(value)) {
                node.port.postMessage({ type: 'param', name, value, sampleFrame });
            }
        },
        setPatch(patch: Record<string, unknown>) {
            node.port.postMessage({ type: 'patch', patch });
        },
        setBypass(state: boolean) {
            bypassed = state;
        },
        onTelemetry(cb: (data: { peakL: number; peakR: number; scopeBuffer: Float32Array }) => void) {
            telemetryListeners.add(cb);
        },
        connect(dest: AudioNode) {
            node.connect(dest);
        },
        disconnect() {
            try {
                node.disconnect();
            } catch {
                /* already disconnected */
            }
        },
        destroy() {
            try {
                node.disconnect();
            } catch {
                // ignore
            }
            node.port.close();
        },
        ready: readyPromise,
    };
}

/**
 * GrinderNode — AudioWorkletNode wrapper for the Grinder amp simulator.
 */

import { logger } from '#/infra/logger/appLogger';

import grinderProcessorUrl from '../services/grinderProcessor.ts?worker&url';

import { requireSharedArrayBuffer } from './pluginHostingErrors';
import { telemetryAllocator, GRINDER_IDX, type TelemetrySlot } from './telemetryAllocator';
import { createReadyHandshake, ensureWorkletRegistered } from './workletInitShared';

const DEFAULT_WASM_URL = '/wasm/daw-dsp/daw_dsp_bg.wasm';

/**
 * Grinder intentionally bypasses the shared WASM binary cache: we always
 * fetch fresh bytes (`cache: 'no-store'`) so rebuilt local WASM is picked up
 * after a plugin reload or app restart instead of getting stuck on stale
 * cached worklet data.
 */
async function fetchGrinderWasm(url: string): Promise<ArrayBuffer> {
    const response = await fetch(url, { cache: 'no-store' });
    if (!response.ok) {
        throw new Error(`Failed to fetch Grinder WASM: ${response.status}`);
    }
    return await response.arrayBuffer();
}

export type GrinderMeterData = {
    inputDb: number;
    preampDb: number;
    powerAmpDb: number;
    outputDb: number;
    gateOpen: number;
    gateEnvelopeDb: number;
    sagVoltage: number;
    latency: number;
    neuralCpuPercent: number;
    neuralWarmupProgress: number;
};

export type GrinderNodeResult = {
    workletNode: AudioWorkletNode;
    setParam: (name: string, value: number) => void;
    setBypass: (bypassed: boolean) => void;
    onMeterData: (cb: (data: GrinderMeterData) => void) => void;
    connect: (dest: AudioNode) => void;
    disconnect: () => void;
    destroy: () => void;
    ready: Promise<void>;
};

export function isGrinderDevice(deviceType: string): boolean {
    return deviceType === 'grinder';
}

export async function createGrinderNode(ctx: BaseAudioContext, wasmUrl?: string): Promise<GrinderNodeResult> {
    // Grinder's neural-amp telemetry uses a SAB slot. Fail fast if the
    // environment cannot provide one — see `buildDeviceChain` for the UX path.
    requireSharedArrayBuffer('Grinder');

    if (ctx instanceof AudioContext && ctx.state === 'suspended') {
        await ctx.resume();
    }

    await ensureWorkletRegistered(ctx, grinderProcessorUrl);

    const node = new AudioWorkletNode(ctx, 'grinder-processor', {
        numberOfInputs: 1,
        numberOfOutputs: 1,
        outputChannelCount: [2],
        channelCount: 2,
        channelCountMode: 'explicit',
    });

    let slot: TelemetrySlot | null = telemetryAllocator.allocateSlot();
    let meterRafId: number | null = null;

    if (slot) {
        node.port.postMessage({ type: 'init-sab', sab: slot.sab, byteOffset: slot.byteOffset });
    }

    const handshake = createReadyHandshake({ pluginName: 'GrinderNode' });
    node.port.onmessage = (event: MessageEvent) => {
        const outcome = handshake.onMessage(event);
        if (outcome === 'late' && event.data?.type === 'error') {
            logger.warn('GrinderNode runtime fault (WASM panic — processor faulted):', event.data.message);
        }
    };
    const readyPromise = handshake.promise;

    const wasmBytes = await fetchGrinderWasm(wasmUrl ?? DEFAULT_WASM_URL);
    const copy = wasmBytes.slice(0);
    node.port.postMessage({ type: 'init', wasmBytes: copy }, [copy]);

    return {
        workletNode: node,
        setParam(name: string, value: number) {
            if (Number.isFinite(value)) {
                const param = node.parameters.get(name);
                if (param) {
                    param.setTargetAtTime(value, ctx.currentTime, 0.01);
                } else {
                    node.port.postMessage({ type: 'param', name, value });
                }
            }
        },
        setBypass(state: boolean) {
            node.port.postMessage({ type: 'param', name: 'bypass', value: state ? 1 : 0 });
        },
        onMeterData(cb: (data: GrinderMeterData) => void) {
            if (meterRafId !== null) {
                cancelAnimationFrame(meterRafId);
                meterRafId = null;
            }
            if (!slot) {
                return;
            }
            const view = slot.view;
            const poll = () => {
                cb({
                    inputDb: view[GRINDER_IDX.inputDb] ?? 0,
                    preampDb: view[GRINDER_IDX.preampDb] ?? 0,
                    powerAmpDb: view[GRINDER_IDX.powerAmpDb] ?? 0,
                    outputDb: view[GRINDER_IDX.outputDb] ?? 0,
                    gateOpen: view[GRINDER_IDX.gateOpen] ?? 0,
                    gateEnvelopeDb: view[GRINDER_IDX.gateEnvelopeDb] ?? 0,
                    sagVoltage: view[GRINDER_IDX.sagVoltage] ?? 0,
                    latency: view[GRINDER_IDX.latency] ?? 0,
                    neuralCpuPercent: view[GRINDER_IDX.neuralCpuPercent] ?? 0,
                    neuralWarmupProgress: view[GRINDER_IDX.neuralWarmupProgress] ?? 0,
                });
                meterRafId = requestAnimationFrame(poll);
            };
            meterRafId = requestAnimationFrame(poll);
        },
        connect(dest: AudioNode) {
            node.connect(dest);
        },
        disconnect() {
            try {
                node.disconnect();
            } catch {
                // ignore
            }
        },
        destroy() {
            if (meterRafId !== null) {
                cancelAnimationFrame(meterRafId);
                meterRafId = null;
            }
            if (slot) {
                telemetryAllocator.releaseSlot(slot.byteOffset);
                slot = null;
            }
            try {
                node.disconnect();
            } catch {
                // ignore
            }
            node.port.close();
        },
        ready: readyPromise,
    };
}

/**
 * LevainNode — AudioWorkletNode wrapper for the Levain suite engine.
 *
 * Creates and manages the WASM-powered worklet. Provides noteOn/noteOff/setParam/handleCc
 * methods that forward via MessagePort. Caches WASM binary and worklet registration.
 * Follows the same pattern as FermenterNode.
 */

import { logger } from '#/infra/logger/appLogger';

import levainProcessorUrl from '../services/levainProcessor.ts?worker&url';

import { createReadyHandshake, ensureWorkletRegistered, fetchWasmBinary } from './workletInitShared';

const DEFAULT_WASM_URL = '/wasm/daw-dsp/daw_dsp_bg.wasm';

export type LevainNodeResult = {
    workletNode: AudioWorkletNode;
    noteOn: (note: number, velocity: number, midiNote?: number, sampleFrame?: number) => void;
    noteOff: (note: number, sampleFrame?: number) => void;
    allNotesOff: () => void;
    setParam: (name: string, value: number) => void;
    handleCc: (cc: number, value: number) => void;
    setInstrument: (instrumentId: string) => void;
    setBypass: (bypassed: boolean) => void;
    connect: (dest: AudioNode) => void;
    disconnect: () => void;
    destroy: () => void;
    ready: Promise<void>;
};

export function isLevainDevice(deviceType: string): boolean {
    return deviceType === 'levain';
}

/**
 * Create an Levain AudioWorkletNode.
 *
 * Resumes the AudioContext if suspended. Caches WASM binary across calls.
 * Await `result.ready` before sending MIDI.
 */
export async function createLevainNode(ctx: BaseAudioContext, wasmUrl?: string): Promise<LevainNodeResult> {
    if (ctx instanceof AudioContext && ctx.state === 'suspended') {
        await ctx.resume();
    }

    await ensureWorkletRegistered(ctx, levainProcessorUrl);

    const node = new AudioWorkletNode(ctx, 'levain-processor', {
        numberOfInputs: 0,
        numberOfOutputs: 1,
        outputChannelCount: [2],
        channelCount: 2,
        channelCountMode: 'explicit',
    });

    let bypassed = false;

    const handshake = createReadyHandshake({ pluginName: 'LevainNode' });
    node.port.onmessage = (event: MessageEvent) => {
        const outcome = handshake.onMessage(event);
        if (outcome === 'late' && event.data?.type === 'error') {
            logger.warn('LevainNode runtime fault (WASM panic — processor faulted):', event.data.message);
        }
    };
    const readyPromise = handshake.promise;

    // Fetch WASM and initialize the processor.
    const wasmBytes = await fetchWasmBinary(wasmUrl ?? DEFAULT_WASM_URL);
    const copy = wasmBytes.slice(0);
    node.port.postMessage({ type: 'init', wasmBytes: copy }, [copy]);

    // Sample loading is driven by `registerLevainDevice` → `loadSamplesForInstrument`,
    // which reads the active patch's `instrumentId`. Do NOT eagerly load a default
    // instrument here — doing so races the patch-driven load and wastes bandwidth
    // on samples the user did not ask for.

    const noteOn = (note: number, velocity: number, sampleFrame?: number): void => {
        if (!bypassed) {
            node.port.postMessage({ type: 'noteOn', note, velocity, sampleFrame });
        }
    };

    const noteOff = (note: number, sampleFrame?: number): void => {
        node.port.postMessage({ type: 'noteOff', note, sampleFrame });
    };

    // Silent all-notes-off used by the transport on stop. Avoids fanning
    // out 128 individual note-off messages, which would otherwise trigger
    // the per-noteOff realism release burst 128 times and produce the
    // "hi-hat ksshh" on every stop on bowed-string patches.
    const allNotesOff = (): void => {
        node.port.postMessage({ type: 'allNotesOff' });
    };

    const setParam = (name: string, value: number): void => {
        if (!Number.isFinite(value)) {
            return;
        }
        node.port.postMessage({ type: 'param', name, value });
    };

    const handleCc = (cc: number, value: number): void => {
        node.port.postMessage({ type: 'cc', cc, value });
    };

    const setInstrument = (instrumentId: string): void => {
        node.port.postMessage({ type: 'setInstrument', instrumentId });
    };

    const setBypass = (b: boolean): void => {
        bypassed = b;
        node.port.postMessage({ type: 'bypass', bypassed: b });
    };

    const connect = (dest: AudioNode): void => {
        node.connect(dest);
    };

    const disconnect = (): void => {
        try {
            node.disconnect();
        } catch {
            // already disconnected
        }
    };

    const destroy = (): void => {
        disconnect();
        node.port.close();
    };

    return {
        workletNode: node,
        noteOn,
        noteOff,
        allNotesOff,
        setParam,
        handleCc,
        setInstrument,
        setBypass,
        connect,
        disconnect,
        destroy,
        ready: readyPromise,
    };
}

