/**
 * NativePluginBridgeNode — bridges Web Audio ↔ Rust native audio thread
 * via a ring buffer and Tauri IPC.
 *
 * Audio data is transferred as raw IEEE 754 little-endian bytes (Uint8Array)
 * rather than JSON number arrays, reducing IPC payload size ~4×.
 *
 * Backpressure: if the previous IPC round-trip hasn't completed when the next
 * block arrives, the new block is dropped. The ring buffer on the Rust side
 * (8 blocks deep) absorbs transient delays; the worklet outputs the most
 * recent available block in the meantime.
 */

import { tauriInvoke, isTauri } from '#/utils/tauriBridge';

export type NativePluginBridgeResult = {
    workletNode: AudioWorkletNode;
    setParam: (paramId: number, value: number) => void;
    setBypass: (_bypassed: boolean) => void;
    destroy: () => void;
};

export async function createNativePluginBridgeNode(
    ctx: AudioContext,
    instanceId: string,
    enginePluginId: number
): Promise<NativePluginBridgeResult> {
    const node = new AudioWorkletNode(ctx, 'native-plugin-bridge-processor', {
        numberOfInputs: 1,
        numberOfOutputs: 1,
        outputChannelCount: [2],
        channelCount: 2,
        channelCountMode: 'explicit',
    });

    // Initialize the worklet with the engine plugin ID
    node.port.postMessage({ type: 'init', enginePluginId });

    // Backpressure: only one IPC round-trip in flight at a time.
    let pendingBlock = false;

    // Relay audio between worklet and Rust
    node.port.onmessage = async (event: MessageEvent) => {
        if (event.data.type === 'process' && isTauri()) {
            if (pendingBlock) {
                return;
            } // Drop block — previous round-trip still in flight
            pendingBlock = true;

            const audioBuffer = event.data.audio as ArrayBuffer;

            try {
                const resultBytes = (await tauriInvoke('process_plugin_audio', {
                    enginePluginId,
                    audioBytes: new Uint8Array(audioBuffer),
                })) as Uint8Array;

                // resultBytes is already a Uint8Array (binary IPC), so we can use its buffer directly.
                node.port.postMessage({ type: 'processed', audio: resultBytes.buffer }, [resultBytes.buffer]);
            } catch {
                // If Rust processing fails, the worklet falls back to passthrough
            } finally {
                pendingBlock = false;
            }
        }
    };

    return {
        workletNode: node,
        setParam(paramId: number, value: number) {
            if (isTauri()) {
                tauriInvoke('set_plugin_parameter', {
                    instanceId,
                    paramId,
                    value,
                }).catch(() => {});
            }
        },
        setBypass(_bypassed: boolean) {
            // TODO: Send bypass command to native engine
        },
        destroy() {
            try {
                node.disconnect();
            } catch {
                // ignore
            }
            node.port.close();
        },
    };
}

import { logger } from '#/infra/logger/appLogger';
import { unregisterLevainDevice } from '#/modules/Levain/useCases';
import { unregisterProofDevice } from '#/modules/Proof/useCases';
import { hasSharedArrayBuffer } from '#/utils/capabilities';

import { applyParams } from '../useCases/deviceResolvers/applyParams';
import { DEVICE_FACTORIES } from '../useCases/deviceResolvers/helpers';

import { createNativePluginBridgeNode } from './NativePluginBridgeNode';
import { findWasmDescriptor } from './wasmDeviceRegistry';

import type { TrackChannelStrip, BuiltinDeviceNode, SendNode } from '../models/AudioEngineState';

export type TrackNodeDeps = {
    context: AudioContext;
    masterGainNode: GainNode;
    getBusGainNode: (id: string) => GainNode | undefined;
    getTrackGainNode: (id: string) => GainNode | undefined;
    getSendsForTrack: (tId: string) => SendNode[];
    pendingDevicePromises: Set<Promise<any>>;
    transportSAB?: SharedArrayBuffer;
};

export class TrackNode {
    public strip: TrackChannelStrip;
    /** When SAB is unavailable, getPeakLevel falls back to AnalyserNode time-domain data. */
    private _analyserFallbackBuffer: Float32Array<ArrayBuffer> | null = null;
    // §88.3 — async plugin loads each resolve with a rebuildChain() call;
    // firing multiple of these in the same microtask produced overlapping
    // disconnect/reconnect sweeps. `_rebuildScheduled` coalesces them so at
    // most one rebuild runs per microtask turn.
    private _rebuildScheduled = false;

    constructor(
        public trackId: string,
        private deps: TrackNodeDeps
    ) {
        const { context } = deps;
        const preFaderTap = context.createGain();
        preFaderTap.gain.value = 1;

        const gainNode = context.createGain();
        gainNode.gain.value = 1;

        const faderNode = context.createGain();
        faderNode.gain.value = 0.8;

        const postFaderGain = context.createGain();
        postFaderGain.gain.value = 1;

        const panNode = context.createStereoPanner();
        panNode.pan.value = 0;

        const analyserNode = context.createAnalyser();
        analyserNode.fftSize = 256;
        analyserNode.smoothingTimeConstant = 0.8;

        let meterNode: AudioWorkletNode | null = null;
        let meterBuffer: Float32Array;

        if (hasSharedArrayBuffer()) {
            const meterSab = new SharedArrayBuffer(4);
            meterNode = new AudioWorkletNode(context, 'metering-processor');
            meterNode.port.postMessage({ type: 'init', sab: meterSab, channels: 2 });
            meterBuffer = new Float32Array(meterSab);
        } else {
            meterBuffer = new Float32Array(1);
            this._analyserFallbackBuffer = new Float32Array(analyserNode.fftSize);
        }

        gainNode.connect(preFaderTap);
        preFaderTap.connect(faderNode);
        faderNode.connect(postFaderGain);
        postFaderGain.connect(panNode);
        if (meterNode) {
            panNode.connect(meterNode);
            meterNode.connect(analyserNode);
        } else {
            panNode.connect(analyserNode);
        }

        this.strip = {
            trackId,
            preFaderTap,
            gainNode,
            faderNode,
            postFaderGain,
            panNode,
            meterNode,
            analyserNode,
            muted: false,
            soloed: false,
            deviceNodes: [],
            midiFxNodes: [],
            meterBuffer,
        };

        this.routeOutput();
    }

    public addMidiFx(fxId: string, fxType: 'arp' | 'velocity' | 'probability'): void {
        this.strip.midiFxNodes.push({
            id: fxId,
            type: fxType,
            bypassed: false,
            parameterValues: {},
        });

        // Notify native engine if bridge is active
        const nativeDevice = this.strip.deviceNodes.find((data) => data.type === 'external-plugin');
        if (nativeDevice?.nativeDspControls) {
            // TODO: Send command to native bridge
        }
    }

    public removeMidiFx(fxId: string): void {
        this.strip.midiFxNodes = this.strip.midiFxNodes.filter((freq) => freq.id !== fxId);
    }

    public updateMidiFxParam(fxId: string, paramId: string, value: number): void {
        const fx = this.strip.midiFxNodes.find((freq) => freq.id === fxId);
        if (fx) {
            fx.parameterValues[paramId] = value;
        }
    }

    public updateMidiFxBypass(fxId: string, bypassed: boolean): void {
        const fx = this.strip.midiFxNodes.find((freq) => freq.id === fxId);
        if (fx) {
            fx.bypassed = bypassed;
        }
    }

    public registerTuningTable(frequencies: number[]): void {
        for (const dn of this.strip.deviceNodes) {
            if (dn.kneadControls) {
                dn.kneadControls.setParam('tuning-table', frequencies as any);
            }
            if (dn.fermenterControls) {
                dn.fermenterControls.setParam('tuning-table', frequencies as any);
            }
        }
    }

    public setGain(gain: number): void {
        this.strip.faderNode.gain.setTargetAtTime(Math.max(0, Math.min(1, gain)), this.deps.context.currentTime, 0.01);
    }

    public setPan(pan: number): void {
        this.strip.panNode.pan.setTargetAtTime(
            Math.max(-1, Math.min(1, pan / 50)),
            this.deps.context.currentTime,
            0.01
        );
    }

    public setMute(muted: boolean): void {
        this.strip.muted = muted;
        this.strip.postFaderGain.gain.setTargetAtTime(muted ? 0 : 1, this.deps.context.currentTime, 0.005);
    }

    public getPeakLevel(): number {
        if (this._analyserFallbackBuffer) {
            this.strip.analyserNode.getFloatTimeDomainData(this._analyserFallbackBuffer);
            let peak = 0;
            for (let index = 0; index < this._analyserFallbackBuffer.length; index++) {
                const abs = Math.abs(this._analyserFallbackBuffer[index]!);
                if (abs > peak) {
                    peak = abs;
                }
            }
            return peak;
        }
        const peak = this.strip.meterBuffer[0]!;
        this.strip.meterBuffer[0] = 0;
        return peak;
    }

    public setOutput(outputId: string): void {
        this.strip.outputId = outputId;
        this.routeOutput();
    }

    private routeOutput(): void {
        const { analyserNode, outputId } = this.strip;
        const { masterGainNode, getBusGainNode, getTrackGainNode } = this.deps;

        analyserNode.disconnect();

        if (outputId === 'hw_out' || !outputId) {
            analyserNode.connect(masterGainNode);
        } else {
            const target = getBusGainNode(outputId) || getTrackGainNode(outputId);
            if (target) {
                analyserNode.connect(target);
            } else {
                analyserNode.connect(masterGainNode);
            }
        }
    }

    private reconnectSends(): void {
        const sends = this.deps.getSendsForTrack(this.trackId);
        for (const send of sends) {
            try {
                send.gainNode.disconnect();
            } catch {
                /* already disconnected */
            }
            const tap = send.preFader ? this.strip.preFaderTap : this.strip.analyserNode;
            tap.connect(send.gainNode);

            const busGain = this.deps.getBusGainNode(send.busId);
            if (busGain) {
                send.gainNode.connect(busGain);
            }
        }
    }

    /** Coalesce concurrent rebuild requests into a single microtask (§88.3). */
    public scheduleRebuildChain(): void {
        if (this._rebuildScheduled) {
            return;
        }
        this._rebuildScheduled = true;
        queueMicrotask(() => {
            this._rebuildScheduled = false;
            this.rebuildChain();
        });
    }

    public rebuildChain(): void {
        const state = this.strip;
        state.preFaderTap.disconnect();
        state.gainNode.disconnect();
        state.faderNode.disconnect();
        state.postFaderGain.disconnect();
        state.panNode.disconnect();
        state.meterNode?.disconnect();
        state.analyserNode.disconnect();

        for (const dn of state.deviceNodes) {
            try {
                dn.outputNode.disconnect();
            } catch {
                /* ok */
            }
        }

        let prevs: AudioNode[] = [state.gainNode];
        for (const dn of state.deviceNodes) {
            if (dn.bypassed) {
                continue;
            }
            if (dn.inputNode.numberOfInputs > 0) {
                // Effect: all previous outputs connect to this input
                for (const param of prevs) {
                    param.connect(dn.inputNode);
                }
                prevs = [dn.outputNode];
            } else {
                // Generator (Instrument): adds its output to the signal path
                prevs.push(dn.outputNode);
            }
        }

        // Connect all final outputs to the preFaderTap
        for (const param of prevs) {
            param.connect(state.preFaderTap);
        }
        state.preFaderTap.connect(state.faderNode);
        state.faderNode.connect(state.postFaderGain);
        state.postFaderGain.connect(state.panNode);
        if (state.meterNode) {
            state.panNode.connect(state.meterNode);
            state.meterNode.connect(state.analyserNode);
        } else {
            state.panNode.connect(state.analyserNode);
        }

        this.routeOutput();
        this.reconnectSends();
    }

    public addDevice(deviceId: string, deviceType: string, externalInstanceId?: string): void {
        if (this.strip.deviceNodes.some((data) => data.deviceId === deviceId)) {
            logger.debug(`Device ${deviceId} already exists on track ${this.trackId}`);
            return;
        }

        const { context, pendingDevicePromises } = this.deps;
        let dn: BuiltinDeviceNode;

        if (deviceType === 'builtin-sidechain-compressor') {
            const workletNode = new AudioWorkletNode(context, 'sidechain-compressor-processor', {
                numberOfInputs: 2,
                numberOfOutputs: 1,
                outputChannelCount: [2],
            });
            dn = { deviceId, type: deviceType, nodes: [workletNode], inputNode: workletNode, outputNode: workletNode };
        } else if (deviceType === 'external-plugin') {
            // Native plugin bridge: uses SharedArrayBuffer for zero-copy audio transfer
            // between Web Audio and the Rust cpal audio thread.
            const loadingBypass = context.createGain();
            dn = {
                deviceId,
                type: deviceType,
                nodes: [loadingBypass],
                inputNode: loadingBypass,
                outputNode: loadingBypass,
            };

            const pendingParams: Array<[string, number]> = [];
            dn.nativeDspControls = {
                setParam: (name: string, value: number) => {
                    pendingParams.push([name, value]);
                },
                setBypass: () => {},
            };

            const loadPromise = createNativePluginBridgeNode(
                context,
                externalInstanceId ?? deviceId,
                0 // engine plugin ID — will be assigned by Rust
            )
                .then((result) => {
                    const idx = this.strip.deviceNodes.findIndex((data) => data.deviceId === deviceId);
                    if (idx !== -1) {
                        const bridgeDn: BuiltinDeviceNode = {
                            deviceId,
                            type: deviceType,
                            nodes: [result.workletNode],
                            inputNode: result.workletNode,
                            outputNode: result.workletNode,
                            nativeDspControls: {
                                setParam: (name: string, value: number) =>
                                    result.setParam(parseInt(name, 10) || 0, value),
                                setBypass: result.setBypass,
                            },
                        };
                        this.strip.deviceNodes[idx] = bridgeDn;
                        this.scheduleRebuildChain();
                    }
                    return null;
                })
                .catch((error) => {
                    logger.warn(`[WebAudioEngine] Native plugin bridge failed: ${error}`);
                    return null;
                });
            pendingDevicePromises.add(loadPromise);
            void loadPromise.finally(() => pendingDevicePromises.delete(loadPromise));
        } else {
            const factory = DEVICE_FACTORIES[deviceType];
            if (factory) {
                const factoryNode = factory(context);
                dn = {
                    deviceId,
                    type: deviceType,
                    nodes: factoryNode.nodes,
                    inputNode: factoryNode.inputNode,
                    outputNode: factoryNode.outputNode,
                    dispose: factoryNode.dispose,
                };
            } else {
                const descriptor = findWasmDescriptor(deviceType);
                if (!descriptor) {
                    return;
                }
                const { placeholder, loadPromise } = descriptor.create({
                    context,
                    deviceId,
                    deviceType,
                    transportSAB: this.deps.transportSAB,
                    onLoaded: (finalDn) => {
                        const idx = this.strip.deviceNodes.findIndex((data) => data.deviceId === deviceId);
                        if (idx !== -1) {
                            this.strip.deviceNodes[idx] = finalDn;
                            this.scheduleRebuildChain();
                        }
                    },
                });
                dn = placeholder;
                pendingDevicePromises.add(loadPromise);
                void loadPromise.finally(() => pendingDevicePromises.delete(loadPromise));
            }
        }

        this.strip.deviceNodes.push(dn);
        this.rebuildChain();
    }

    public removeDevice(deviceId: string): void {
        const dn = this.strip.deviceNodes.find((data) => data.deviceId === deviceId);
        if (!dn) {
            return;
        }
        if (dn.dispose) {
            dn.dispose();
        }
        if (dn.fermenterControls) {
            dn.fermenterControls.destroy();
        }
        if (dn.toasterControls) {
            dn.toasterControls.destroy();
        }
        if (dn.levainControls) {
            dn.levainControls.destroy();
        }
        if (dn.grandBouleControls) {
            dn.grandBouleControls.destroy();
        }
        if (dn.wamControls) {
            dn.wamControls.destroy?.();
        }
        if (dn.type === 'proof') {
            unregisterProofDevice(deviceId);
        }
        for (const node of dn.nodes) {
            node.disconnect();
        }
        this.strip.deviceNodes = this.strip.deviceNodes.filter((data) => data.deviceId !== deviceId);
        this.rebuildChain();
    }

    public updateParam(deviceId: string, paramId: string, value: number): void {
        const dn = this.strip.deviceNodes.find((data) => data.deviceId === deviceId);
        if (!dn) {
            return;
        }

        if (dn.wamControls) {
            dn.wamControls.setParam(paramId, value);
            return;
        }

        if (dn.type === 'builtin-sidechain-compressor') {
            const worklet = dn.nodes[0];
            if (!(worklet instanceof AudioWorkletNode)) {
                return;
            }
            const param = worklet.parameters.get(paramId.replace('sc-comp-', ''));
            if (param) {
                if (paramId === 'sc-comp-attack' || paramId === 'sc-comp-release') {
                    param.setTargetAtTime(value / 1000, this.deps.context.currentTime, 0.01);
                } else {
                    param.setTargetAtTime(value, this.deps.context.currentTime, 0.01);
                }
            }
            return;
        }

        if (dn.fermenterControls) {
            dn.fermenterControls.setParam(paramId, value);
            return;
        }

        if (dn.toasterControls) {
            dn.toasterControls.setParam(paramId, value);
            return;
        }

        if (dn.levainControls) {
            dn.levainControls.setParam(paramId, value);
            return;
        }

        if (dn.nativeDspControls) {
            dn.nativeDspControls.setParam(paramId, value);
        } else if (DEVICE_FACTORIES[dn.type]) {
            applyParams(dn as any, dn.type, { [paramId]: value });
        }
    }

    public updatePatch(deviceId: string, patch: Record<string, unknown>): void {
        const dn = this.strip.deviceNodes.find((data) => data.deviceId === deviceId);
        if (!dn) {
            return;
        }

        if (dn.fermenterControls) {
            dn.fermenterControls.setPatch?.(patch);
        }
    }

    public scheduleParam(deviceId: string, paramId: string, value: number, time: number): void {
        const dn = this.strip.deviceNodes.find((data) => data.deviceId === deviceId);
        if (!dn) {
            return;
        }
        if (dn.wamControls) {
            dn.wamControls.scheduleParam(paramId, value, time);
        } else if (dn.type.startsWith('faust-')) {
            const worklet = dn.nodes[0];
            if (worklet && worklet instanceof AudioWorkletNode) {
                let targetParam: AudioParam | null = null;
                const exact = worklet.parameters.get(paramId);
                if (exact) {
                    targetParam = exact;
                } else {
                    for (const [key, param] of worklet.parameters) {
                        if (key.endsWith(`/${paramId}`)) {
                            targetParam = param;
                            break;
                        }
                    }
                }
                if (targetParam) {
                    targetParam.setValueAtTime(value, time);
                }
            }
        } else if (dn.fermenterControls) {
            const sampleFrame = Math.round(time * this.deps.context.sampleRate);
            dn.fermenterControls.setParam(paramId, value, sampleFrame);
        }
    }

    public updateBypass(deviceId: string, bypassed: boolean): void {
        const dn = this.strip.deviceNodes.find((data) => data.deviceId === deviceId);
        if (!dn) {
            return;
        }
        if (dn.fermenterControls) {
            dn.fermenterControls.setBypass(bypassed);
        } else if (dn.toasterControls) {
            dn.toasterControls.setBypass(bypassed);
        } else if (dn.levainControls) {
            dn.levainControls.setBypass(bypassed);
        } else if (dn.nativeDspControls) {
            dn.nativeDspControls.setBypass(bypassed);
        } else {
            dn.bypassed = bypassed;
            this.rebuildChain();
        }
    }

    public dispose(): void {
        this.strip.preFaderTap.disconnect();
        this.strip.gainNode.disconnect();
        this.strip.faderNode.disconnect();
        this.strip.postFaderGain.disconnect();
        this.strip.panNode.disconnect();
        this.strip.analyserNode.disconnect();
        if (this.strip.meterNode) {
            this.strip.meterNode.port.close();
            this.strip.meterNode.disconnect();
        }
        for (const dn of this.strip.deviceNodes) {
            if (dn.dispose) {
                dn.dispose();
            }
            if (dn.fermenterControls) {
                dn.fermenterControls.destroy();
            }
            if (dn.toasterControls) {
                dn.toasterControls.destroy();
            }
            if (dn.levainControls) {
                dn.levainControls.destroy();
                unregisterLevainDevice();
            }
            if (dn.grandBouleControls) {
                dn.grandBouleControls.destroy();
            }
            if (dn.wamControls) {
                dn.wamControls.destroy?.();
            }
            if (dn.nativeDspControls && 'destroy' in dn.nativeDspControls) {
                (dn.nativeDspControls as { destroy: () => void }).destroy();
            }
            if (dn.type === 'proof') {
                unregisterProofDevice(dn.deviceId);
            }
            for (const node of dn.nodes) {
                node.disconnect();
            }
        }
    }
}

import { describe, it, expect, vi, beforeEach } from 'vitest';

import { createMockAudioContext } from '../../../../helpers/__tests__/audioContext.mock';
import { BusNode } from '../BusNode';

describe('BusNode', () => {
    let ctx: ReturnType<typeof createMockAudioContext>;
    let masterGain: GainNode;

    beforeEach(() => {
        ctx = createMockAudioContext();
        masterGain = ctx.createGain() as any;
        vi.clearAllMocks();
    });

    it('should create and wire up nodes correctly', () => {
        const bus = new BusNode('bus-1', ctx as any, masterGain);

        expect(ctx.createGain).toHaveBeenCalled();
        expect(ctx.createAnalyser).toHaveBeenCalled();
        expect(bus.strip.busId).toBe('bus-1');

        // gain -> analyser -> master
        expect(bus.strip.gainNode.connect).toHaveBeenCalledWith(bus.strip.analyserNode);
        expect(bus.strip.analyserNode.connect).toHaveBeenCalledWith(masterGain);
    });

    it('should set gain using setTargetAtTime', () => {
        const bus = new BusNode('bus-1', ctx as any, masterGain);
        const gainParam = bus.strip.gainNode.gain;

        bus.setGain(0.5);
        expect(gainParam.setTargetAtTime).toHaveBeenCalledWith(0.5, ctx.currentTime, 0.01);
    });

    it('should clamp gain values', () => {
        const bus = new BusNode('bus-1', ctx as any, masterGain);
        const gainParam = bus.strip.gainNode.gain;

        bus.setGain(-1);
        expect(gainParam.setTargetAtTime).toHaveBeenCalledWith(0, ctx.currentTime, 0.01);

        bus.setGain(3);
        expect(gainParam.setTargetAtTime).toHaveBeenCalledWith(2, ctx.currentTime, 0.01);
    });

    it('should calculate peak level from analyser data', () => {
        const bus = new BusNode('bus-1', ctx as any, masterGain);
        const analyser = bus.strip.analyserNode;

        // Mock analyser data: peak is 0.8
        vi.mocked(analyser.getFloatTimeDomainData).mockImplementation((data: Float32Array) => {
            data[0] = 0.1;
            data[1] = -0.8;
            data[2] = 0.5;
        });

        const peak = bus.getPeakLevel();
        expect(peak).toBeCloseTo(0.8, 5);
    });

    it('should disconnect nodes on dispose', () => {
        const bus = new BusNode('bus-1', ctx as any, masterGain);
        bus.dispose();

        expect(bus.strip.gainNode.disconnect).toHaveBeenCalled();
        expect(bus.strip.analyserNode.disconnect).toHaveBeenCalled();
    });
});

import { describe, it, expect, vi, beforeEach } from 'vitest';

import { createMockAudioContext } from '../../../../helpers/__tests__/audioContext.mock';
import { TrackNode, type TrackNodeDeps } from '../TrackNode';

describe('TrackNode', () => {
    let ctx: ReturnType<typeof createMockAudioContext>;
    let deps: TrackNodeDeps;

    beforeEach(() => {
        ctx = createMockAudioContext() as any;

        (global as any).AudioWorkletNode = class {
            port = { postMessage: vi.fn() };
            connect = vi.fn();
            disconnect = vi.fn();
        };
        (global as any).SharedArrayBuffer = class extends ArrayBuffer {};

        deps = {
            context: ctx as any,
            masterGainNode: ctx.createGain() as any,
            getBusGainNode: vi.fn(),
            getTrackGainNode: vi.fn(),
            getSendsForTrack: vi.fn().mockReturnValue([]),
            pendingDevicePromises: new Set(),
        };
        vi.clearAllMocks();
    });

    it('should create and wire up nodes correctly on initialization', () => {
        const track = new TrackNode('track-1', deps);

        expect(track.trackId).toBe('track-1');
        expect(track.strip.muted).toBe(false);

        // Initial wiring check (simplified)
        // gainNode -> preFaderTap -> faderNode -> postFaderGain -> panNode -> meterNode -> analyserNode -> masterGain
        expect(track.strip.gainNode.connect).toHaveBeenCalledWith(track.strip.preFaderTap);
        expect(track.strip.preFaderTap.connect).toHaveBeenCalledWith(track.strip.faderNode);
        expect(track.strip.faderNode.connect).toHaveBeenCalledWith(track.strip.postFaderGain);
        expect(track.strip.postFaderGain.connect).toHaveBeenCalledWith(track.strip.panNode);
        expect(track.strip.panNode.connect).toHaveBeenCalledWith(track.strip.meterNode);
        expect(track.strip.meterNode.connect).toHaveBeenCalledWith(track.strip.analyserNode);
        expect(track.strip.analyserNode.connect).toHaveBeenCalledWith(deps.masterGainNode);
    });

    it('should set gain with clamping', () => {
        const track = new TrackNode('track-1', deps);
        const faderGain = track.strip.faderNode.gain;

        track.setGain(0.5);
        expect(faderGain.setTargetAtTime).toHaveBeenCalledWith(0.5, ctx.currentTime, 0.01);

        track.setGain(1.5); // should clamp to 1.0
        expect(faderGain.setTargetAtTime).toHaveBeenCalledWith(1.0, ctx.currentTime, 0.01);
    });

    it('should set pan with scale (-50..50 -> -1..1)', () => {
        const track = new TrackNode('track-1', deps);
        const panParam = track.strip.panNode.pan;

        track.setPan(50); // Hard right (1.0)
        expect(panParam.setTargetAtTime).toHaveBeenCalledWith(1.0, ctx.currentTime, 0.01);

        track.setPan(-25); // Mid left (-0.5)
        expect(panParam.setTargetAtTime).toHaveBeenCalledWith(-0.5, ctx.currentTime, 0.01);
    });

    it('should set mute state', () => {
        const track = new TrackNode('track-1', deps);
        const postFaderGain = track.strip.postFaderGain.gain;

        track.setMute(true);
        expect(track.strip.muted).toBe(true);
        expect(postFaderGain.setTargetAtTime).toHaveBeenCalledWith(0, ctx.currentTime, 0.005);

        track.setMute(false);
        expect(track.strip.muted).toBe(false);
        expect(postFaderGain.setTargetAtTime).toHaveBeenCalledWith(1, ctx.currentTime, 0.005);
    });

    it('should route output to a bus if provided', () => {
        const busGain = ctx.createGain();
        vi.mocked(deps.getBusGainNode).mockReturnValue(busGain as any);

        const track = new TrackNode('track-1', deps);
        track.setOutput('bus-1');

        expect(deps.getBusGainNode).toHaveBeenCalledWith('bus-1');
        expect(track.strip.analyserNode.connect).toHaveBeenCalledWith(busGain);
    });
});

