            scheduleParam: (name, value, time) => pendingParams.push({ name, value, time }),
            destroy: () => {},
        };
        const loadPromise = createFaustDeviceNode(context, deviceType)
            .then((result) => {
                if (!result) {
                    return;
                }
                const controls = result.wamControls;
                for (const { name, value, time } of pendingParams) {
                    if (time !== undefined) {
                        controls?.scheduleParam(name, value, time);
                    } else {
                        controls?.setParam(name, value);
                    }
                }
                onLoaded({
                    deviceId,
                    type: deviceType,
                    nodes: result.nodes,
                    inputNode: result.inputNode,
                    outputNode: result.outputNode,
                    wamControls: controls,
                });
                void eventBus.emit('audioDevice.loaded', { deviceId, deviceType });
                return;
            })
            .catch((error) => {
                logger.warn(`[WebAudioEngine] ${deviceType} failed: ${error}`);
                return;
            });
        return { placeholder, loadPromise };
    },
};

const kneadDescriptor: WasmDeviceDescriptor = {
    matches: isKneadDevice,
    create({ context, deviceId, deviceType, transportSAB, onLoaded }) {
        const pendingParams: Array<[string, number]> = [];
        const placeholder = loadingBypassNode(context, deviceId, deviceType);
        placeholder.kneadControls = {
            ready: false,
            updateState: () => {},
            setParam: (name, value) => {
                pendingParams.push([name, value]);
            },
            setBypass: () => {},
            destroy: () => {},
        };
        const loadPromise = createKneadNode(context, transportSAB)
            .then(async (result: KneadNodeResult) => {
                await result.ready;
                for (const [name, value] of pendingParams) {
                    result.setParam(name, value);
                }
                onLoaded({
                    deviceId,
                    type: deviceType,
                    nodes: [result.workletNode],
                    inputNode: result.workletNode,
                    outputNode: result.workletNode,
                    kneadControls: {
                        ready: true,
                        updateState: result.updateState,
                        setParam: result.setParam,
                        setBypass: result.setBypass,
                        destroy: () => {
                            try {
                                result.workletNode.disconnect();
                            } catch {
                                // ignore
                            }
                            result.workletNode.port.close();
                        },
                    },
                });
                return;
            })
            .catch((error) => {
                logger.warn(`[WebAudioEngine] ${deviceType} failed: ${error}`);
                return;
            });
        return { placeholder, loadPromise };
    },
};

// ── Registry ─────────────────────────────────────────────────────────────────

const WASM_DEVICE_DESCRIPTORS: WasmDeviceDescriptor[] = [
    faustDescriptor,
    fermenterDescriptor,
    toasterDescriptor,
    levainDescriptor,
    proofChamberDescriptor,
    glutenDescriptor,
    bacteriaDescriptor,
    grinderDescriptor,
    proofDescriptor,
    scoringDescriptor,
    grandBouleDescriptor,
    kneadDescriptor,
];

export function findWasmDescriptor(deviceType: string): WasmDeviceDescriptor | undefined {
    return WASM_DEVICE_DESCRIPTORS.find((data) => data.matches(deviceType));
}

export type AudioEngineState = {
    isReady: boolean;
    sampleRate: number;
    state: AudioContextState;
    masterGain: number;
    currentTime: number;
    baseLatency: number;
};

export type BuiltinDeviceNode = {
    deviceId: string;
    type: string;
    nodes: AudioNode[];
    inputNode: AudioNode;
    outputNode: AudioNode;
    bypassed?: boolean;
    /** Stop oscillators and release resources when the device is removed. */
    dispose?: () => void;
    /** Controls for native Rust/WASM DSP devices (param updates via MessagePort) */
    nativeDspControls?: {
        setParam: (name: string, value: number) => void;
        setBypass: (bypassed: boolean) => void;
    };
    /** Generic controls for Web Audio Modules (WAM) / Faust */
    wamControls?: {
        setParam: (name: string, value: number) => void;
        scheduleParam: (name: string, value: number, time: number) => void;
        destroy?: () => void;
    };
    /** Controls for the Fermenter synthesizer (MIDI + param updates via MessagePort) */
    fermenterControls?: {
        ready: boolean;
        noteOn: (note: number, velocity: number, sampleFrame?: number) => void;
        noteOff: (note: number, sampleFrame?: number) => void;
        setParam: (name: string, value: number, sampleFrame?: number) => void;
        setPatch?: (patch: Record<string, unknown>) => void;
        setBypass: (bypassed: boolean) => void;
        destroy: () => void;
    };
    /** Controls for the Toaster drum machine (MIDI + param updates via MessagePort) */
    toasterControls?: {
        ready: boolean;
        noteOn: (pad: number, velocity: number, midiNote?: number, sampleFrame?: number) => void;
        noteOff: (pad: number, sampleFrame?: number) => void;
        setParam: (name: string, value: number) => void;
        setPadParam: (pad: number, name: string, value: number) => void;
        setBypass: (bypassed: boolean) => void;
        destroy: () => void;
    };
    /** Controls for the Grand Boule piano (MIDI + pedals + param updates via MessagePort) */
    grandBouleControls?: {
        ready: boolean;
        noteOn: (midiNote: number, velocity: number, sampleFrame?: number) => void;
        noteOff: (midiNote: number, sampleFrame?: number) => void;
        setParam: (name: string, value: number) => void;
        setSustain: (position: number) => void;
        setUnaCorda: (engaged: boolean) => void;
        setSostenuto: (engaged: boolean) => void;
        noteOnMidi2: (midiNote: number, velocity16bit: number, pitchOffsetQ24: number) => void;
        setTemperament: (index: number) => void;
        loadAttackClip: (key: number, samples: Float32Array) => void;
        allNotesOff: () => void;
        setBypass: (bypassed: boolean) => void;
        destroy: () => void;
    };
    /** Controls for the Levain suite (MIDI + CC + param updates via MessagePort) */
    levainControls?: {
        ready: boolean;
        noteOn: (note: number, velocity: number, sampleFrame?: number) => void;
        noteOff: (note: number, sampleFrame?: number) => void;
        allNotesOff: () => void;
        handleCc: (cc: number, value: number) => void;
        setParam: (name: string, value: number) => void;
        setBypass: (bypassed: boolean) => void;
        destroy: () => void;
    };
    /** Controls for the Knead pitch processor (blob sync + param updates via MessagePort) */
    kneadControls?: {
        ready: boolean;
        updateState: (clips: Record<string, any>) => void;
        setParam: (name: string, value: number) => void;
        setBypass: (bypassed: boolean) => void;
        destroy: () => void;
    };
};

export type MidiFxNode = {
    id: string;
    type: 'arp' | 'velocity' | 'probability';
    bypassed: boolean;
    parameterValues: Record<string, number>;
