import { type ReactElement, useState, useEffect } from 'react';

import { RefreshCw } from 'lucide-react';

import { DawCompactSelect } from '#/components/daw/DawCompactSelect';
import { DawEyebrowLabel } from '#/components/daw/DawEyebrowLabel';
import { DawInlineHint } from '#/components/daw/DawInlineHint';
import { Button } from '#/components/ui/button';
import { useStore } from '#/infra/store/useStore';

import { getAudioDevices, type AudioDeviceInfo } from '../../useCases/audioDeviceSelection/getAudioDevices';
import { audioDeviceStore } from '../../useCases/audioDeviceSelection/helpers';
import { setInputDevice } from '../../useCases/audioDeviceSelection/setInputDevice';
import { setOutputDevice } from '../../useCases/audioDeviceSelection/setOutputDevice';

const defaultAudioDeviceState = {
    selectedOutputId: null,
    selectedInputId: null,
};

export const AudioDevicePicker = (): ReactElement => {
    const state = useStore(audioDeviceStore, defaultAudioDeviceState);

    const [devices, setDevices] = useState<AudioDeviceInfo[]>([]);
    const [loading, setLoading] = useState(true);

    const refresh = () => {
        setLoading(true);
        void getAudioDevices().then((result) => {
            setDevices(result);
            setLoading(false);
            return null;
        });
    };

    useEffect(() => {
        refresh();
    }, []);

    const outputs = devices.filter((data) => data.kind === 'audiooutput');
    const inputs = devices.filter((data) => data.kind === 'audioinput');

    const handleOutputChange = (deviceId: string) => {
        void setOutputDevice(deviceId);
    };

    const handleInputChange = (deviceId: string) => {
        setInputDevice(deviceId);
    };

    return (
        <div className="space-y-3">
            <div className="space-y-1.5">
                <DawEyebrowLabel size="sm" className="block">
                    Output
                </DawEyebrowLabel>
                <div className="flex items-center gap-2">
                    <DawCompactSelect
                        value={state?.selectedOutputId ?? ''}
                        onChange={(event) => handleOutputChange(event.target.value)}
                        tone="inset"
                        size="sm"
                        className="flex-1"
                        aria-label="Audio output device"
                        disabled={loading}
                    >
                        <option value="">Default</option>
                        {outputs.map((data) => (
                            <option key={data.id} value={data.id}>
                                {data.label}
                            </option>
                        ))}
                    </DawCompactSelect>
                    <Button
                        variant="ghost"
                        size="icon-xs"
                        onClick={refresh}
                        aria-label="Refresh audio devices"
                        title="Re-enumerate audio devices"
                    >
                        <RefreshCw className="size-3.5" />
                    </Button>
                </div>
            </div>
            <div className="space-y-1.5">
                <DawEyebrowLabel size="sm" className="block">
                    Input
                </DawEyebrowLabel>
                <DawCompactSelect
                    value={state?.selectedInputId ?? ''}
                    onChange={(event) => handleInputChange(event.target.value)}
                    tone="inset"
                    size="sm"
                    className="w-full"
                    aria-label="Audio input device"
                    disabled={loading}
                >
                    <option value="">Default</option>
                    {inputs.map((data) => (
                        <option key={data.id} value={data.id}>
                            {data.label}
                        </option>
                    ))}
                </DawCompactSelect>
            </div>
            {loading ? (
                <DawInlineHint className="animate-pulse justify-start px-0 py-0 text-[10px] text-muted-foreground/70">
                    Detecting devices...
                </DawInlineHint>
            ) : null}
        </div>
    );
};

import { type ReactElement, useState } from 'react';

import { Search, ChevronDown, ChevronRight, Plug, RefreshCw, Loader2, Plus, AlertCircle, Monitor } from 'lucide-react';

import { DawCompactInput } from '#/components/daw/DawCompactInput';
import { DawEmptyState } from '#/components/daw/DawEmptyState';
import { DawEyebrowLabel } from '#/components/daw/DawEyebrowLabel';
import { DawInlineHint } from '#/components/daw/DawInlineHint';
import { DawMicroBadge } from '#/components/daw/DawMicroBadge';
import { DawPickerRow } from '#/components/daw/DawPickerRow';
import { Button } from '#/components/ui/button';
import { Tooltip, TooltipContent, TooltipTrigger } from '#/components/ui/tooltip';
import { useStore } from '#/infra/store/useStore';
import { pluginScanStore, defaultPluginScanState } from '#/modules/Plugin/stores';
import {
    startPluginScan,
    createTrackForPlugin,
    loadExternalPlugin,
    type ScannedPlugin,
} from '#/modules/Plugin/useCases';
import { getPlatformCapabilities, DISABLED_REASONS } from '#/utils/platformCapabilities';
import { cn } from '#/utils/Styles/cn';

type PluginBrowserProps = {
    selectedTrackId: string | null;
    searchQuery: string;
};

const FORMAT_COLORS: Record<string, string> = {
    vst3: 'bg-[var(--color-accent-cyan)]/20 text-[var(--color-accent-cyan)]',
    clap: 'bg-[var(--color-accent-mint)]/20 text-[var(--color-accent-mint)]',
    au: 'bg-[var(--color-accent-lavender)]/20 text-[var(--color-accent-lavender)]',
};

const FORMAT_ORDER = ['vst3', 'clap', 'au'];

export const PluginBrowser = ({ selectedTrackId, searchQuery }: PluginBrowserProps): ReactElement | null => {
    const state = useStore(pluginScanStore, defaultPluginScanState);
    const [collapsedFormats, setCollapsedFormats] = useState<Set<string>>(new Set());
    const [localSearch, setLocalSearch] = useState('');

    const { hasNativePlugins } = getPlatformCapabilities();

    if (!hasNativePlugins) {
        return (
            <div className="space-y-1">
                <div className="flex items-center gap-1 px-1 py-0.5 pt-2">
                    <Plug className="size-3 text-muted-foreground" aria-hidden="true" />
                    <DawEyebrowLabel size="sm">External Plugins</DawEyebrowLabel>
                </div>
                <Tooltip>
                    <TooltipTrigger asChild>
                        <DawEmptyState
                            compact
                            className="cursor-not-allowed opacity-50"
                            icon={<Monitor className="size-5" aria-hidden="true" />}
                            title="VST / AU / CLAP plugins"
                            description="Desktop app required"
                        />
                    </TooltipTrigger>
                    <TooltipContent side="top" className="max-w-64 text-center">
                        {DISABLED_REASONS.nativePlugins}
                    </TooltipContent>
                </Tooltip>
            </div>
        );
    }

    const query = (searchQuery || localSearch).toLowerCase().trim();

    const filtered = state.scannedPlugins.filter((param) => {
        if (!query) {
            return true;
        }
        return (
            param.name.toLowerCase().includes(query) ||
            param.vendor.toLowerCase().includes(query) ||
            param.category.toLowerCase().includes(query)
        );
    });

    const pluginsByFormat = FORMAT_ORDER.map((format) => ({
        format,
        plugins: filtered.filter((param) => param.format.toLowerCase() === format),
    })).filter((group) => group.plugins.length > 0);

    const toggleFormat = (format: string) => {
        setCollapsedFormats((prev) => {
            const next = new Set(prev);
            if (next.has(format)) {
                next.delete(format);
            } else {
                next.add(format);
            }
            return next;
        });
    };

    const handleLoadPlugin = (plugin: ScannedPlugin) => {
        let trackId = selectedTrackId;
        if (!trackId) {
            const isInstrument = plugin.category.toLowerCase() === 'instrument';
            const newTrack = createTrackForPlugin(plugin.name, isInstrument ? 'midi' : 'audio');
            if (!newTrack) {
                return;
            }
            trackId = newTrack.id;
        }
        void loadExternalPlugin(trackId, plugin.id, plugin.name);
    };

    const handleScan = () => {
        void startPluginScan();
    };

    return (
        <div className="space-y-1">
            <div className="flex items-center gap-1 px-1 py-0.5 pt-2">
                <Plug className="size-3 text-muted-foreground" aria-hidden="true" />
                <DawEyebrowLabel size="sm">External Plugins</DawEyebrowLabel>
                <span className="ml-auto text-[9px] text-muted-foreground">{state.scannedPlugins.length}</span>
            </div>
            {state.scannedPlugins.length === 0 && !state.isScanning ? (
                <div className="px-2 py-3">
                    <DawEmptyState
                        compact
                        icon={<Plug className="size-4" aria-hidden="true" />}
                        title="No external plugins found"
                        action={
                            <Button variant="outline" size="xs" className="gap-1 text-[10px]" onClick={handleScan}>
                                <RefreshCw className="size-3" aria-hidden="true" />
                                Scan Plugins
                            </Button>
                        }
                    />
                </div>
            ) : null}
            {state.isScanning ? (
                <div className="flex items-center gap-2 px-2 py-2">
                    <Loader2 className="size-3 animate-spin text-primary" aria-hidden="true" />
                    <DawInlineHint className="animate-pulse px-0 py-0 text-[10px] text-muted-foreground">
                        Scanning for plugins...
                    </DawInlineHint>
                </div>
            ) : null}
            {state.scannedPlugins.length > 0 ? (
                <>
                    <div className="flex items-center gap-1 px-1">
                        <div className="flex-1 flex items-center gap-1">
                            <Search className="size-3 text-muted-foreground" aria-hidden="true" />
                            <DawCompactInput
                                type="search"
                                placeholder="Filter plugins..."
                                value={localSearch}
                                onChange={(event) => {
                                    setLocalSearch(event.target.value);
                                }}
                                size="micro"
                                className="h-5 border-0 bg-transparent p-0 text-[10px] shadow-none focus-visible:ring-0"
                                aria-label="Filter external plugins"
                            />
                        </div>
                        <Button
                            variant="ghost"
                            size="icon-xs"
                            onClick={handleScan}
                            disabled={state.isScanning}
                            aria-label="Rescan plugins"
                            title="Rescan plugin directories"
                        >
                            <RefreshCw className={cn('size-3', state.isScanning && 'animate-spin')} />
                        </Button>
                    </div>

                    {pluginsByFormat.map(({ format, plugins }) => {
                        const isCollapsed = collapsedFormats.has(format);
                        return (
                            <div key={format}>
                                <button
                                    type="button"
                                    className="flex w-full items-center gap-1 px-1 py-0.5"
                                    onClick={() => {
                                        toggleFormat(format);
                                    }}
                                >
                                    {isCollapsed ? (
                                        <ChevronRight className="size-3 text-muted-foreground" />
                                    ) : (
                                        <ChevronDown className="size-3 text-muted-foreground" />
                                    )}
                                    <DawMicroBadge
                                        className={cn(
                                            'shrink-0 border-0 px-1 py-px text-[10px] font-bold uppercase',
                                            FORMAT_COLORS[format] ?? 'bg-muted text-muted-foreground'
                                        )}
                                    >
                                        {format}
                                    </DawMicroBadge>
                                    <span className="ml-auto text-[9px] text-muted-foreground">{plugins.length}</span>
                                </button>
                                {!isCollapsed &&
                                    plugins.map((plugin) => (
                                        <PluginRow
                                            key={plugin.id}
                                            plugin={plugin}
                                            selectedTrackId={selectedTrackId}
                                            onLoad={handleLoadPlugin}
                                        />
                                    ))}
                            </div>
                        );
                    })}

                    {filtered.length === 0 && query ? (
                        <DawInlineHint className="mx-2 flex px-2 py-2 text-[10px] text-muted-foreground/70">
                            No plugins match "{query}"
                        </DawInlineHint>
                    ) : null}
                </>
            ) : null}
            {state.errors.length > 0 && !state.isScanning ? (
                <div className="px-2 py-1">
                    {state.errors.map((err, index) => (
                        <div key={index} className="flex items-start gap-1 text-[9px] text-destructive">
                            <AlertCircle className="size-3 shrink-0 mt-px" aria-hidden="true" />
                            <span>{err}</span>
                        </div>
                    ))}
                </div>
            ) : null}
        </div>
    );
};

const PluginRow = ({
    plugin,
    selectedTrackId,
    onLoad,
}: {
    plugin: ScannedPlugin;
    selectedTrackId: string | null;
    onLoad: (plugin: ScannedPlugin) => void;
}): ReactElement => {
    return (
        <DawPickerRow
            heading={
                <div className="flex items-center gap-1">
                    <span className="truncate">{plugin.name}</span>
                    <DawMicroBadge
                        className={cn(
                            'shrink-0 border-0 px-1 py-px text-[10px] font-bold uppercase',
                            FORMAT_COLORS[plugin.format.toLowerCase()] ?? 'bg-muted text-muted-foreground'
                        )}
                    >
                        {plugin.format}
                    </DawMicroBadge>
                </div>
            }
            description={
                <div className="flex items-center gap-1">
                    <span className="truncate">{plugin.vendor}</span>
                    {plugin.category ? <span className="capitalize">· {plugin.category}</span> : null}
                </div>
            }
            endSlot={
                <div className="flex items-center gap-1 shrink-0">
                    <span className="text-[9px] text-muted-foreground">{plugin.num_parameters}p</span>
                    {selectedTrackId ? <Plus className="size-3 text-muted-foreground" /> : null}
                </div>
            }
            onClick={() => {
                onLoad(plugin);
            }}
            className="px-2 py-1.5"
            title={selectedTrackId ? 'Click to load onto selected track' : 'Click to create a new track'}
        />
    );
};

import { type ReactElement, useState } from 'react';

import { FolderOpen, Trash2, RefreshCw, Loader2, Plus, AlertCircle, CheckCircle2, Plug, Monitor } from 'lucide-react';

import { DawCompactInput } from '#/components/daw/DawCompactInput';
import { DawEmptyState } from '#/components/daw/DawEmptyState';
import { DawEyebrowLabel } from '#/components/daw/DawEyebrowLabel';
import { DawMicroBadge } from '#/components/daw/DawMicroBadge';
import { DawReadoutRow } from '#/components/daw/DawReadoutRow';
import { Button } from '#/components/ui/button';
import { Tooltip, TooltipContent, TooltipTrigger } from '#/components/ui/tooltip';
import { useStore } from '#/infra/store/useStore';
import { pluginScanStore, defaultPluginScanState } from '#/modules/Plugin/stores';
import { startPluginScan, addScanPath, removeScanPath } from '#/modules/Plugin/useCases';
import { getPlatformCapabilities, DISABLED_REASONS } from '#/utils/platformCapabilities';

export const PluginScanSettings = (): ReactElement | null => {
    const state = useStore(pluginScanStore, defaultPluginScanState);
    const [newPath, setNewPath] = useState('');

    const { hasPluginScanning } = getPlatformCapabilities();

    if (!hasPluginScanning) {
        return (
            <section>
                <div className="mb-2 flex items-center gap-1">
                    <Plug className="size-3" aria-hidden="true" />
                    <DawEyebrowLabel size="sm">Plugin Paths</DawEyebrowLabel>
                </div>
                <Tooltip>
                    <TooltipTrigger asChild>
                        <DawEmptyState
                            compact
                            className="cursor-not-allowed opacity-50"
                            icon={<Monitor className="size-4" aria-hidden="true" />}
                            title="Plugin scanning unavailable"
                            description="Desktop app required"
                        />
                    </TooltipTrigger>
                    <TooltipContent side="top" className="max-w-64 text-center">
                        {DISABLED_REASONS.pluginScanning}
                    </TooltipContent>
                </Tooltip>
            </section>
        );
    }

    const handleAddPath = () => {
        const trimmed = newPath.trim();
        if (trimmed) {
            addScanPath(trimmed);
            setNewPath('');
        }
    };

    const handleScan = () => {
        void startPluginScan();
    };

    const lastScanLabel = state.lastScanTime ? new Date(state.lastScanTime).toLocaleString() : 'Never';

    return (
        <section>
            <div className="mb-2 flex items-center gap-1">
                <Plug className="size-3" aria-hidden="true" />
                <DawEyebrowLabel size="sm">Plugin Paths</DawEyebrowLabel>
            </div>
            <div className="space-y-2">
                {state.scanPaths.length > 0 ? (
                    <div className="space-y-1">
                        {state.scanPaths.map((path) => (
                            <div key={path} className="flex items-center gap-1.5 group">
                                <FolderOpen className="size-3 text-muted-foreground shrink-0" aria-hidden="true" />
                                <span className="flex-1 text-[10px] text-foreground truncate font-mono" title={path}>
                                    {path}
                                </span>
                                <Button
                                    variant="ghost"
                                    size="icon-xs"
                                    className="opacity-0 group-hover:opacity-100 transition-opacity"
                                    onClick={() => {
                                        removeScanPath(path);
                                    }}
                                    aria-label={`Remove path ${path}`}
                                >
                                    <Trash2 className="size-3 text-destructive" />
                                </Button>
                            </div>
                        ))}
                    </div>
                ) : null}

                <div className="flex items-center gap-1">
                    <DawCompactInput
                        type="text"
                        placeholder="/path/to/plugins..."
                        value={newPath}
                        onChange={(event) => {
                            setNewPath(event.target.value);
                        }}
                        className="flex-1"
                        monospace
                        onKeyDown={(event) => {
                            if (event.key === 'Enter') {
                                handleAddPath();
                            }
                        }}
                    />
                    <Button
                        variant="outline"
                        size="xs"
                        onClick={handleAddPath}
                        disabled={!newPath.trim()}
                        aria-label="Add plugin path"
                    >
                        <Plus className="size-3" />
                    </Button>
                </div>

                <div className="flex items-center gap-2">
                    <Button
                        variant="outline"
                        size="sm"
                        className="gap-1 text-xs"
                        onClick={handleScan}
                        disabled={state.isScanning}
                    >
                        {state.isScanning ? (
                            <Loader2 className="size-3 animate-spin" aria-hidden="true" />
                        ) : (
                            <RefreshCw className="size-3" aria-hidden="true" />
                        )}
                        {state.isScanning ? 'Scanning...' : 'Scan Now'}
                    </Button>

                    <div className="flex-1" />
                </div>

                <div className="space-y-1">
                    <DawReadoutRow label="Plugins Found" value={state.scannedPlugins.length} className="gap-2" />
                    <DawReadoutRow
                        label="Last Scan"
                        value={lastScanLabel}
                        className="gap-2"
                        valueClassName="truncate text-right"
                    />
                </div>

                {state.errors.length > 0 ? (
                    <div className="space-y-1 rounded-md border border-destructive/30 bg-destructive/5 p-2">
                        {state.errors.map((err, index) => (
                            <div key={index} className="flex items-start gap-1 text-[10px] text-destructive">
                                <AlertCircle className="size-3 shrink-0 mt-px" aria-hidden="true" />
                                <span>{err}</span>
                            </div>
                        ))}
                    </div>
                ) : null}

                {state.scannedPlugins.length > 0 && state.errors.length === 0 && !state.isScanning ? (
                    <DawMicroBadge tone="success" className="w-fit">
                        <CheckCircle2 className="size-3" aria-hidden="true" />
                        <span>All plugins scanned successfully</span>
                    </DawMicroBadge>
                ) : null}
            </div>
        </section>
    );
};

