import { type OfflineDeviceNode } from '../types';

// ── AutoPan ──────────────────────────────────────────────────────────────

export function createAutoPan(ctx: BaseAudioContext): OfflineDeviceNode {
    const input = ctx.createGain();
    const splitterNode = ctx.createChannelSplitter(2);
    const mergerNode = ctx.createChannelMerger(2);
    const leftGain = ctx.createGain();
    leftGain.gain.value = 1;
    const rightGain = ctx.createGain();
    rightGain.gain.value = 1;
    const lfo = ctx.createOscillator();
    lfo.frequency.value = 1;
    lfo.type = 'sine';
    const lfoGainL = ctx.createGain();
    lfoGainL.gain.value = 0.5;
    const lfoGainR = ctx.createGain();
    lfoGainR.gain.value = -0.5;
    const output = ctx.createGain();
    output.gain.value = 1;
    input.connect(splitterNode);
    splitterNode.connect(leftGain, 0);
    splitterNode.connect(rightGain, 1);
    lfo.connect(lfoGainL);
    lfo.connect(lfoGainR);
    lfoGainL.connect(leftGain.gain as unknown as AudioNode);
    lfoGainR.connect(rightGain.gain as unknown as AudioNode);
    leftGain.connect(mergerNode, 0, 0);
    rightGain.connect(mergerNode, 0, 1);
    mergerNode.connect(output);
    lfo.start(0);
    return {
        inputNode: input,
        outputNode: output,
        nodes: [input, splitterNode, mergerNode, leftGain, rightGain, lfo, lfoGainL, lfoGainR, output],
        namedNodes: { input, splitterNode, mergerNode, leftGain, rightGain, lfo, lfoGainL, lfoGainR, output },
        dispose() {
            lfo.stop();
            for (const node of [
                input,
                splitterNode,
                mergerNode,
                leftGain,
                rightGain,
                lfo,
                lfoGainL,
                lfoGainR,
                output,
            ]) {
                node.disconnect();
            }
        },
    };
}

import { type OfflineDeviceNode } from '../types';

// ── Chorus ───────────────────────────────────────────────────────────────

export function createChorus(ctx: BaseAudioContext): OfflineDeviceNode {
    const splitter = ctx.createGain();
    const dry = ctx.createGain();
    dry.gain.value = 0.7;
    const wet = ctx.createGain();
    wet.gain.value = 0.3;
    const delay1 = ctx.createDelay(0.05);
    delay1.delayTime.value = 0.02;
    const delay2 = ctx.createDelay(0.05);
    delay2.delayTime.value = 0.025;
    const lfo1 = ctx.createOscillator();
    lfo1.frequency.value = 0.5;
    lfo1.type = 'sine';
    const lfo2 = ctx.createOscillator();
    lfo2.frequency.value = 0.6;
    lfo2.type = 'sine';
    const lfoGain1 = ctx.createGain();
    lfoGain1.gain.value = 0.005;
    const lfoGain2 = ctx.createGain();
    lfoGain2.gain.value = 0.005;
    const merger = ctx.createGain();
    splitter.connect(dry);
    splitter.connect(delay1);
    splitter.connect(delay2);
    lfo1.connect(lfoGain1);
    lfoGain1.connect(delay1.delayTime as unknown as AudioNode);
    lfo2.connect(lfoGain2);
    lfoGain2.connect(delay2.delayTime as unknown as AudioNode);
    delay1.connect(wet);
    delay2.connect(wet);
    dry.connect(merger);
    wet.connect(merger);
    lfo1.start(0);
    lfo2.start(0);
    return {
        inputNode: splitter,
        outputNode: merger,
        nodes: [splitter, dry, wet, delay1, delay2, lfo1, lfo2, lfoGain1, lfoGain2, merger],
        namedNodes: { splitter, dry, wet, delay1, delay2, lfo1, lfo2, lfoGain1, lfoGain2, merger },
        dispose() {
            lfo1.stop();
            lfo2.stop();
            for (const node of [splitter, dry, wet, delay1, delay2, lfo1, lfo2, lfoGain1, lfoGain2, merger]) {
                node.disconnect();
            }
        },
    };
}

import { type OfflineDeviceNode } from '../types';

// ── Flanger ──────────────────────────────────────────────────────────────

export function createFlanger(ctx: BaseAudioContext): OfflineDeviceNode {
    const splitter = ctx.createGain();
    const dry = ctx.createGain();
    dry.gain.value = 0.5;
    const wet = ctx.createGain();
    wet.gain.value = 0.5;
    const delay = ctx.createDelay(0.02);
    delay.delayTime.value = 0.005;
    const lfo = ctx.createOscillator();
    lfo.frequency.value = 0.5;
    lfo.type = 'sine';
    const lfoGain = ctx.createGain();
    lfoGain.gain.value = 0.003;
    const feedback = ctx.createGain();
    feedback.gain.value = 0.5;
    const merger = ctx.createGain();
    splitter.connect(dry);
    splitter.connect(delay);
    lfo.connect(lfoGain);
    lfoGain.connect(delay.delayTime as unknown as AudioNode);
    delay.connect(feedback);
    feedback.connect(delay);
    delay.connect(wet);
    dry.connect(merger);
    wet.connect(merger);
    lfo.start(0);
    return {
        inputNode: splitter,
        outputNode: merger,
        nodes: [splitter, dry, wet, delay, lfo, lfoGain, feedback, merger],
        namedNodes: { splitter, dry, wet, delay, lfo, lfoGain, feedback, merger },
        dispose() {
            lfo.stop();
            for (const node of [splitter, dry, wet, delay, lfo, lfoGain, feedback, merger]) {
                node.disconnect();
            }
        },
    };
}

import { type OfflineDeviceNode } from '../types';

// ── Phaser ───────────────────────────────────────────────────────────────

export function createPhaser(ctx: BaseAudioContext): OfflineDeviceNode {
    const splitter = ctx.createGain();
    const dry = ctx.createGain();
    dry.gain.value = 0.5;
    const wet = ctx.createGain();
    wet.gain.value = 0.5;
    const stages = 4;
    const filters: BiquadFilterNode[] = [];
    for (let index = 0; index < stages; index++) {
        const freq = ctx.createBiquadFilter();
        freq.type = 'allpass';
        freq.frequency.value = 1000 * (index + 1);
        freq.Q.value = 0.5;
        filters.push(freq);
    }
    for (let index = 0; index < filters.length - 1; index++) {
        filters[index]!.connect(filters[index + 1]!);
    }
    const lfo = ctx.createOscillator();
    lfo.frequency.value = 0.5;
    lfo.type = 'sine';
    const lfoGain = ctx.createGain();
    lfoGain.gain.value = 500;
    const feedback = ctx.createGain();
    feedback.gain.value = 0.5;
    const merger = ctx.createGain();
    splitter.connect(dry);
    splitter.connect(filters[0]!);
    lfo.connect(lfoGain);
    for (const freq of filters) {
        lfoGain.connect(freq.frequency as unknown as AudioNode);
    }
    const lastFilter = filters[filters.length - 1]!;
    lastFilter.connect(feedback);
    feedback.connect(filters[0]!);
    lastFilter.connect(wet);
    dry.connect(merger);
    wet.connect(merger);
    lfo.start(0);
    return {
        inputNode: splitter,
        outputNode: merger,
        nodes: [splitter, dry, wet, ...filters, lfo, lfoGain, feedback, dry, wet],
        namedNodes: {
            splitter,
            dry,
            wet,
            lfo,
            lfoGain,
            feedback,
            merger,
            filter0: filters[0]!,
            filter1: filters[1]!,
            filter2: filters[2]!,
            filter3: filters[3]!,
        },
    };
}

import { type OfflineDeviceNode } from '../types';

// ── Tremolo ──────────────────────────────────────────────────────────────

export function createTremolo(ctx: BaseAudioContext): OfflineDeviceNode {
    const input = ctx.createGain();
    const tremGain = ctx.createGain();
    tremGain.gain.value = 1;
    const lfo = ctx.createOscillator();
    lfo.frequency.value = 5;
    lfo.type = 'sine';
    const lfoDepth = ctx.createGain();
    lfoDepth.gain.value = 0.5;
    input.connect(tremGain);
    lfo.connect(lfoDepth);
    lfoDepth.connect(tremGain.gain as unknown as AudioNode);
    lfo.start(0);
    return {
        inputNode: input,
        outputNode: tremGain,
        nodes: [input, tremGain, lfo, lfoDepth],
        namedNodes: { input, tremGain, lfo, lfoDepth },
        dispose() {
            lfo.stop();
            for (const node of [input, tremGain, lfo, lfoDepth]) {
                node.disconnect();
            }
        },
    };
}

import { type OfflineDeviceNode } from '../types';

import { IR_GENERATORS } from './helpers';

export const IR_NAMES = Object.keys(IR_GENERATORS);

export function applyConvolutionReverbParams(dn: OfflineDeviceNode, params: Record<string, number>): void {
    const dryConv = dn.nodes[1] as GainNode;
    const wetConv = dn.nodes[2] as GainNode;
    const convolverNode = dn.nodes[3] as ConvolverNode;
    const predelayConv = dn.nodes[5] as DelayNode;
    const lowcutConv = dn.nodes[6] as BiquadFilterNode;
    const highcutConv = dn.nodes[7] as BiquadFilterNode;
    if (params['conv-mix'] !== undefined) {
        wetConv.gain.value = params['conv-mix'];
        dryConv.gain.value = 1 - params['conv-mix'];
    }
    if (params['conv-predelay'] !== undefined) {
        predelayConv.delayTime.value = params['conv-predelay'] / 1000;
    }
    if (params['conv-lowcut'] !== undefined) {
        lowcutConv.frequency.value = params['conv-lowcut'];
    }
    if (params['conv-highcut'] !== undefined) {
        highcutConv.frequency.value = params['conv-highcut'];
    }
    if (params['conv-ir'] !== undefined) {
        const irIndex = Math.round(params['conv-ir']);
        const irName = IR_NAMES[irIndex] ?? 'studio-a';
        const gen = IR_GENERATORS[irName];
        if (gen && convolverNode.context) {
            convolverNode.buffer = gen(convolverNode.context.sampleRate);
        }
    }
}

/**
 * Repository: Faust DSP device node factory.
 *
 * Creates OfflineDeviceNode wrappers around Faust AudioWorkletNodes,
 * making them compatible with the device chain builder.
 *
 * Since Faust nodes are single AudioNodes that handle both input and output,
 * the wrapper simply uses the same node for inputNode and outputNode.
 */

import { logger } from '#/infra/logger/appLogger';
import { compileFaustDSP, createFaustNode, isFaustModule } from '#/modules/Plugin/useCases';

import { type OfflineDeviceNode } from './deviceNodeFactory';

export { isFaustModule };

/**
 * Create a Faust device node for the device chain.
 *
 * Ensures the module is compiled, then creates an AudioWorkletNode.
 * Returns null if compilation or node creation fails — the chain builder
 * should skip this device gracefully.
 */
export async function createFaustDevice(
    ctx: BaseAudioContext,
    faustModuleId: string
): Promise<OfflineDeviceNode | null> {
    const compiled = await compileFaustDSP(faustModuleId);
    if (!compiled) {
        logger.warn(`[FaustDevice] Failed to compile ${faustModuleId}`);
        return null;
    }

    const node = await createFaustNode(faustModuleId, ctx);
    if (!node) {
        logger.warn(`[FaustDevice] Failed to create node for ${faustModuleId}`);
        return null;
    }

    const audioNode = node as unknown as AudioNode;
    return {
        inputNode: audioNode,
        outputNode: audioNode,
        nodes: [audioNode],
        wamControls: {
            setParam: (name: string, value: number) => {
                // Resolve bare param names to full Faust addresses via suffix fallback.
                // Faust expects addresses like '/FM_Synth/algorithm'; UI passes 'algorithm'.
                if (node && typeof (node as any).setParamValue === 'function') {
                    if (audioNode instanceof AudioWorkletNode) {
                        let resolvedName = name;
                        if (!audioNode.parameters.get(name)) {
                            for (const [key] of audioNode.parameters) {
                                if (key.endsWith(`/${name}`)) {
                                    resolvedName = key;
                                    break;
                                }
                            }
                        }
                        try {
                            (node as any).setParamValue(resolvedName, value);
                        } catch (error) {
                            logger.warn(`[FaustDevice] Failed to set param ${resolvedName} to ${value}:`, error);
                        }
                    } else {
                        try {
                            (node as any).setParamValue(name, value);
                        } catch (error) {
                            logger.warn(`[FaustDevice] Failed to set param ${name} to ${value}:`, error);
                        }
                    }
                }
            },
            scheduleParam: (name: string, value: number, time: number) => {
                if (audioNode instanceof AudioWorkletNode) {
                    let targetParam: AudioParam | null = null;
                    const exact = audioNode.parameters.get(name);
                    if (exact) {
                        targetParam = exact;
                    } else {
                        for (const [key, param] of audioNode.parameters) {
                            if (key.endsWith(`/${name}`)) {
                                targetParam = param;
                                break;
                            }
                        }
                    }
                    if (targetParam) {
                        targetParam.setValueAtTime(value, time);
                    }
                }
            },
            destroy: () => {
                if ('destroy' in audioNode && typeof (audioNode as any).destroy === 'function') {
                    try {
                        (audioNode as any).destroy();
                    } catch (error) {
                        logger.warn(`[FaustDevice] Failed to destroy node:`, error);
                    }
                }
            },
        },
    };
}

