import { describe, it, expect } from 'vitest';

import { beatToSeconds } from '../beatConversion';

describe('beatToSeconds', () => {
    it('should convert beats to seconds with a constant tempo', () => {
        const beat = 4;
        const defaultTempo = 120;
        const changes: any[] = [];

        // 4 beats at 120 bpm = 2 seconds
        expect(beatToSeconds(beat, defaultTempo, changes)).toBe(2);
    });

    it('should account for a single tempo change at beat 0', () => {
        const beat = 4;
        const defaultTempo = 120;
        const changes = [{ beat: 0, tempo: 60 }];

        // 4 beats at 60 bpm = 4 seconds
        expect(beatToSeconds(beat, defaultTempo, changes as any)).toBe(4);
    });

    it('should account for a tempo change midway', () => {
        const beat = 4;
        const defaultTempo = 120;
        const changes = [{ beat: 2, tempo: 60 }];

        // 0-2 beats at 120 bpm = 1 second
        // 2-4 beats at 60 bpm = 2 seconds
        // Total = 3 seconds
        expect(beatToSeconds(beat, defaultTempo, changes as any)).toBe(3);
    });

    it('should account for multiple tempo changes', () => {
        const beat = 6;
        const defaultTempo = 120;
        const changes = [
            { beat: 2, tempo: 60 },
            { beat: 4, tempo: 120 },
        ];

        // 0-2 beats at 120 bpm = 1 second
        // 2-4 beats at 60 bpm = 2 seconds
        // 4-6 beats at 120 bpm = 1 second
        // Total = 4 seconds
        expect(beatToSeconds(beat, defaultTempo, changes as any)).toBe(4);
    });

    it('should handle beats occurring exactly at a tempo change', () => {
        const beat = 2;
        const defaultTempo = 120;
        const changes = [{ beat: 2, tempo: 60 }];

        // 0-2 beats at 120 bpm = 1 second
        expect(beatToSeconds(beat, defaultTempo, changes as any)).toBe(1);
    });
});

import fs from 'fs';
import path from 'path';

import { describe, it, expect, beforeEach } from 'vitest';

// Helper to evaluate an AudioWorklet script and extract its class
function loadProcessorClass(filePath: string, className: string) {
    const code = fs.readFileSync(path.resolve(__dirname, filePath), 'utf-8');

    // Mock global AudioWorklet environment
    const globals = {
        AudioWorkletProcessor: class {
            port = {
                onmessage: null as any,
                postMessage: () => {},
            };
        },
        registerProcessor: () => {},
        currentFrame: 0,
        sampleRate: 48000,
        console,
    };

    // We replace the import statements so it doesn't crash on evaluation
    const safeCode = code.replaceAll(/import\s+.*?;/g, '').replaceAll(/export\s+/g, '');

    const execute = new Function(
        ...Object.keys(globals),
        `
        ${safeCode}
        return ${className};
        `
    );

    return execute(...Object.values(globals));
}

describe('AudioWorklet Processor Queues (_queueHead Read Index)', () => {
    for (const processorName of ['LevainProcessor', 'FermenterProcessor', 'ToasterProcessor']) {
        describe(processorName, () => {
            let ProcessorClass: any;
            let processor: any;

            beforeEach(() => {
                const fileName = `${processorName.charAt(0).toLowerCase() + processorName.slice(1)}.ts`;
                ProcessorClass = loadProcessorClass(`../${fileName}`, processorName);
                processor = new ProcessorClass();

                // Mock out the dispatch method to just record the messages
                processor._dispatch = function (msg: any) {
                    if (!this.dispatched) {
                        this.dispatched = [];
                    }
                    this.dispatched.push(msg);
                };
            });

            it('should enqueue messages in order of sampleFrame', () => {
                processor._enqueue({ sampleFrame: 10, val: 'b' });
                processor._enqueue({ sampleFrame: 5, val: 'a' });
                processor._enqueue({ sampleFrame: 15, val: 'c' });

                expect(processor._queue.length).toBe(3);
                expect(processor._queue[0]).toEqual({ sampleFrame: 5, val: 'a' });
                expect(processor._queue[1]).toEqual({ sampleFrame: 10, val: 'b' });
                expect(processor._queue[2]).toEqual({ sampleFrame: 15, val: 'c' });
            });

            it('should drain queue correctly based on blockEndFrame and advance _queueHead', () => {
                processor._enqueue({ sampleFrame: 10, val: 'a' });
                processor._enqueue({ sampleFrame: 20, val: 'b' });
                processor._enqueue({ sampleFrame: 30, val: 'c' });
                processor._enqueue({ sampleFrame: 40, val: 'd' });

                expect(processor._queue.length).toBe(4);

                // Drain up to frame 25 (should dispatch a and b)
                processor._drainQueue(25);

                expect(processor.dispatched).toEqual([
                    { sampleFrame: 10, val: 'a' },
                    { sampleFrame: 20, val: 'b' },
                ]);

                // The queue length shouldn't change yet, but head should advance
                expect(processor._queueHead).toBe(2);
                expect(processor._queue.length).toBe(4);

                // Drain the rest
                processor._drainQueue(45);
                expect(processor.dispatched).toEqual([
                    { sampleFrame: 10, val: 'a' },
                    { sampleFrame: 20, val: 'b' },
                    { sampleFrame: 30, val: 'c' },
                    { sampleFrame: 40, val: 'd' },
                ]);

                // Once fully drained, it should clear in place
                expect(processor._queueHead).toBe(0);
                expect(processor._queue.length).toBe(0);
            });
        });
    }
});

import { describe, it, expect, vi, beforeEach } from 'vitest';

// Mock AudioWorkletProcessor and registerProcessor which are available in worklet global scope
global.AudioWorkletProcessor = class {
    port = {
        onmessage: null as any,
        postMessage: vi.fn(),
    };
};
const processors = new Map();
global.registerProcessor = (name: string, proc: any) => processors.set(name, proc);

// Load the processor (it will register itself)
// Since it's @ts-nocheck and uses worklet globals, we need to handle the import carefully
// or just re-define the core logic for the test if it's simpler.
// Given the logic is small, we'll extract it to verify behavior.

describe('RecordingWorkletProcessor', () => {
    // Re-implementation of the class logic for testing in Node/Vitest
    class RecordingWorkletProcessorMock extends global.AudioWorkletProcessor {
        _writeHead: Int32Array | null = null;
        _ring: Float32Array | null = null;
        _ringSize = 0;
        _active = false;

        constructor() {
            super();
        }

        handleMessage(data: any) {
            switch (data.type) {
                case 'init': {
                    const sab = data.sab;
                    this._writeHead = new Int32Array(sab, 0, 1);
                    this._ring = new Float32Array(sab, 4);
                    this._ringSize = this._ring.length;
                    break;
                }
                case 'start':
                    this._active = true;
                    break;
                case 'stop': {
                    this._active = false;
                    const head = this._writeHead ? Atomics.load(this._writeHead, 0) : 0;
                    this.port.postMessage({ type: 'stopped', writeHead: head });
                    break;
                }
            }
        }

        process(inputs: any[][][]) {
            if (!this._active || !this._ring || !this._writeHead) {
                return true;
            }
            const input = inputs[0]?.[0];
            if (!input || input.length === 0) {
                return true;
            }

            const head = Atomics.load(this._writeHead, 0);
            const ringSize = this._ringSize;
            for (let index = 0; index < input.length; index++) {
                this._ring[(head + index) % ringSize] = input[index];
            }
            Atomics.add(this._writeHead, 0, input.length);
            return true;
        }
    }

    let processor: RecordingWorkletProcessorMock;
    let sab: SharedArrayBuffer;

    beforeEach(() => {
        vi.clearAllMocks();
        processor = new RecordingWorkletProcessorMock();
        // 4 bytes for head + 1024 samples * 4 bytes
        sab = new SharedArrayBuffer(4 + 1024 * 4);
    });

    it('should initialize head and ring from SAB', () => {
        processor.handleMessage({ type: 'init', sab });
        expect(processor._writeHead).toBeDefined();
        expect(processor._ring).toHaveLength(1024);
    });

    it('should not process if not active', () => {
        processor.handleMessage({ type: 'init', sab });
        const input = [[new Float32Array([0.5, 0.6])]];
        processor.process(input);

        const head = new Int32Array(sab, 0, 1)[0];
        expect(head).toBe(0);
    });

    it('should record samples into the ring buffer when active', () => {
        processor.handleMessage({ type: 'init', sab });
        processor.handleMessage({ type: 'start' });

        const inputData = new Float32Array([0.1, 0.2, 0.3]);
        processor.process([[inputData]]);

        const head = new Int32Array(sab, 0, 1)[0];
        expect(head).toBe(3);

        const ring = new Float32Array(sab, 4);
        expect(ring[0]).toBeCloseTo(0.1, 5);
        expect(ring[1]).toBeCloseTo(0.2, 5);
        expect(ring[2]).toBeCloseTo(0.3, 5);
    });

    it('should wrap around the ring buffer', () => {
        // Small SAB for wrap test: 4 bytes head + 4 samples
        const smallSab = new SharedArrayBuffer(4 + 4 * 4);
        processor.handleMessage({ type: 'init', sab: smallSab });
        processor.handleMessage({ type: 'start' });

        // Fill 3 samples
        processor.process([[new Float32Array([1, 2, 3])]]);
        // Add 2 more (should wrap 1)
        processor.process([[new Float32Array([4, 5])]]);

        const head = new Int32Array(smallSab, 0, 1)[0];
        expect(head).toBe(5);

        const ring = new Float32Array(smallSab, 4);
        expect(ring[0]).toBe(5); // Wrapped
        expect(ring[1]).toBe(2);
        expect(ring[2]).toBe(3);
        expect(ring[3]).toBe(4);
    });

    it('should send stopped message with writeHead on stop', () => {
        processor.handleMessage({ type: 'init', sab });
        processor.handleMessage({ type: 'start' });
        processor.process([[new Float32Array([0.1, 0.2])]]);

        processor.handleMessage({ type: 'stop' });
        expect(processor.port.postMessage).toHaveBeenCalledWith({ type: 'stopped', writeHead: 2 });
        expect(processor._active).toBe(false);
    });
});

// @ts-nocheck
/**
 * AudioWorkletProcessor for the Bacteria creative multi-effects framework.
 *
 * Uses the generated wasm-bindgen JS bindings (daw_dsp.js) via initSync so all
 * WASM memory management is handled by the generated glue — no manual malloc/free.
 *
 * Effect processor: reads from inputs[0], writes to outputs[0].
 */

import { initSync, BacteriaInstance } from '../wasm/daw_dsp.js';

/** Bacteria passes param names through as-is (Rust engine uses camelCase matching). */
const PARAM_MAP = {
    mix: 'mix',
    inputGain: 'inputGain',
    outputGain: 'outputGain',
    bypass: 'bypass',
    bandCount: 'bandCount',
    crossoverFreq1: 'crossoverFreq1',
    crossoverFreq2: 'crossoverFreq2',
    crossoverFreq3: 'crossoverFreq3',
    crossoverFreq4: 'crossoverFreq4',
    crossoverFreq5: 'crossoverFreq5',
    crossoverSlope: 'crossoverSlope',
    crossoverMode: 'crossoverMode',
    globalRouting: 'globalRouting',
    morphX: 'morphX',
    morphY: 'morphY',
    macro1: 'macro1',
    macro2: 'macro2',
    macro3: 'macro3',
    macro4: 'macro4',
    macro5: 'macro5',
    macro6: 'macro6',
    macro7: 'macro7',
    macro8: 'macro8',
    lfo1Rate: 'lfo1Rate',
    lfo1Shape: 'lfo1Shape',
    lfo1Amount: 'lfo1Amount',
    lfo2Rate: 'lfo2Rate',
    lfo2Shape: 'lfo2Shape',
    lfo2Amount: 'lfo2Amount',
    envFollowerAttack: 'envFollowerAttack',
    envFollowerRelease: 'envFollowerRelease',
    lorenzSigma: 'lorenzSigma',
    lorenzRho: 'lorenzRho',
    lorenzBeta: 'lorenzBeta',
    lorenzSpeed: 'lorenzSpeed',
};

class BacteriaProcessor extends AudioWorkletProcessor {
    _instance = null;
    _memory = null;
    _ready = false;
    _faulted = false;
    _meterCounter = 0;
    _sabView = null; // Float32Array view into the telemetry SharedArrayBuffer slot

    constructor() {
        super();
        this.port.onmessage = (event) => {
            const msg = event.data;
            try {
                if (msg.type === 'init') {
                    if (this._ready) {
                        return;
                    }
                    this._initWasm(msg.wasmBytes);
                } else if (msg.type === 'init-sab') {
                    this._sabView = new Float32Array(msg.sab, msg.byteOffset, 32);
                } else if (msg.type === 'param' && this._ready && !this._faulted) {
                    const rustName = PARAM_MAP[msg.name] ?? msg.name;
                    this._instance.set_param(rustName, msg.value);
                }
            } catch (error) {
                console.error('BacteriaProcessor error:', error);
            }
        };
    }

    _initWasm(wasmBytes) {
        const wasmExports = initSync({ module: new WebAssembly.Module(wasmBytes) });
        this._memory = wasmExports.memory;
        this._instance = new BacteriaInstance(sampleRate);
        this._ready = true;
        this.port.postMessage({ type: 'ready' });
    }

    _passthrough(input, output) {
        if (output[0] && input[0]) {
            output[0].set(input[0]);
        }
        if (output[1] && (input[1] ?? input[0])) {
            output[1].set(input[1] ?? input[0]);
        }
    }

    process(inputs, outputs) {
        if (!this._ready || this._faulted) {
            return true;
        }

        const input = inputs[0];
        const output = outputs[0];
        if (!input || input.length < 2 || !output || output.length < 2) {
            return true;
        }

        const frames = output[0].length;

        try {
            const inst = this._instance;
            const mem = this._memory.buffer;

            const inLeftPtr = inst.get_input_left_ptr();
            const inRightPtr = inst.get_input_right_ptr();
            new Float32Array(mem, inLeftPtr, frames).set(input[0]);
            new Float32Array(mem, inRightPtr, frames).set(input[1] ?? input[0]);

            const outLeftPtr = inst.process(frames);
            const outRightPtr = inst.get_right_ptr();

            output[0].set(new Float32Array(mem, outLeftPtr, frames));
            if (output[1]) {
                output[1].set(new Float32Array(mem, outRightPtr, frames));
            }

            this._meterCounter++;
            if (this._meterCounter >= 8) {
                this._meterCounter = 0;
                if (this._sabView) {
                    this._sabView[0] = inst.get_input_db();
                    this._sabView[1] = inst.get_output_db();
                    this._sabView[2] = inst.get_latency_samples();
                    // Blit the Rust engine's 6-element peak-level array directly into
                    // the SAB slot starting at index 3 (bandLevelsBase). Peak levels
                    // are linear amplitude; consumers convert to dB.
                    const bandPtr = inst.get_band_levels_ptr();
                    const bandView = new Float32Array(mem, bandPtr, 6);
                    this._sabView.set(bandView, 3);
                }
            }
        } catch (error) {
            this._faulted = true;
            this.port.postMessage({ type: 'error', message: String(error) });
            this._passthrough(input, output);
        }

        return true;
    }
}

registerProcessor('bacteria-processor', BacteriaProcessor);

// @ts-nocheck
/**
 * AudioWorkletProcessor for the Fermenter synthesizer.
 *
 * Uses the generated wasm-bindgen JS bindings (daw_dsp.js) via initSync so all
 * WASM memory management is handled by the generated glue — no manual malloc/free.
 *
 * Messages from main thread:
 *   { type: 'init', wasmBytes: ArrayBuffer }
 *   { type: 'noteOn', note, velocity, sampleFrame? }
 *   { type: 'noteOff', note, sampleFrame? }
 *   { type: 'param', name, value }
 */

import { initSync, FermenterInstance } from '../wasm/daw_dsp.js';

/**
 * Convert camelCase to snake_case automatically.
 */
function camelToSnake(str) {
    const snake = str.replaceAll(/[A-Z]/g, (letter) => `_${letter.toLowerCase()}`);
    // Handle the 3 exceptions
    if (snake === 'filter_cutoff') {
        return 'cutoff';
    }
    if (snake === 'filter_resonance') {
        return 'resonance';
    }
    if (snake === 'filter_env_amount') {
        return 'mod_env_to_filter';
    }
    if (snake === 'lfo_pitch_amount') {
        return 'mod_lfo_to_pitch';
    }
    if (snake === 'osc_engine') {
        return 'engine';
    }
    if (snake === 'osc_drift') {
        return 'drift';
    }
    if (snake === 'portamento_time') {
        return 'portamento';
    }
    return snake;
}

class FermenterProcessor extends AudioWorkletProcessor {
    _instance = null; // FermenterInstance (generated wasm-bindgen class)
    _memory = null; // WebAssembly.Memory (for direct buffer access in process())
    _ready = false;
    _faulted = false;
    _queue = []; // Sorted by sampleFrame (integer sample count)
    _queueHead = 0; // Read index — consumed entries are past this

    constructor() {
        super();
        this.port.onmessage = (event) => {
            const msg = event.data;
            try {
                if (msg.type === 'init') {
                    if (this._ready) {
                        return;
                    }
                    this._initWasm(msg.wasmBytes);
                } else if (this._ready && !this._faulted) {
                    this._handleMessage(msg);
                }
            } catch (error) {
                console.error('FermenterProcessor error:', error);
                if (!this._ready) {
                    this.port.postMessage({ type: 'error', message: error?.message ?? String(error) });
                }
            }
        };
    }

    _initWasm(wasmBytes) {
        const wasmExports = initSync({ module: new WebAssembly.Module(wasmBytes) });
        this._memory = wasmExports.memory;
        this._instance = new FermenterInstance(sampleRate, 32);
        this._ready = true;
        this.port.postMessage({ type: 'ready' });
    }

    _enqueue(msg) {
        let lo = this._queueHead,
            hi = this._queue.length;
        while (lo < hi) {
            const mid = (lo + hi) >>> 1;
            if (this._queue[mid].sampleFrame <= msg.sampleFrame) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        this._queue.splice(lo, 0, msg);
    }

    _handleMessage(msg) {
        if (msg.sampleFrame !== undefined) {
            if (msg.sampleFrame > currentFrame) {
                this._enqueue(msg);
                return;
            }
        }
        this._dispatch(msg);
    }

    _dispatch(msg) {
        const inst = this._instance;
        switch (msg.type) {
            case 'noteOn':
                inst.note_on(msg.note, msg.velocity);
                break;
            case 'noteOff':
                inst.note_off(msg.note);
                break;
            case 'param': {
                const rustName = camelToSnake(msg.name);
                inst.set_param(rustName, msg.value);
                break;
            }
            case 'patch': {
                for (const [key, value] of Object.entries(msg.patch)) {
                    if (typeof value === 'number') {
                        inst.set_param(camelToSnake(key), value);
                    } else if (key === 'macros' && Array.isArray(value)) {
                        for (let index = 0; index < value.length; index++) {
                            inst.set_param(`macro${index}`, value[index]);
                        }
                    }
                }
                break;
            }
        }
    }

    _drainQueue(blockEndFrame) {
        // Audio-thread hot path: advance the read head, no splice per block.
        while (this._queueHead < this._queue.length && this._queue[this._queueHead].sampleFrame <= blockEndFrame) {
            this._dispatch(this._queue[this._queueHead]);
            this._queueHead++;
        }
        if (this._queueHead >= this._queue.length) {
            this._queue.length = 0;
            this._queueHead = 0;
        }
    }

    process(_inputs, outputs) {
        if (!this._ready || this._faulted) {
            return true;
        }

        const output = outputs[0];
        if (!output || output.length < 2) {
            return true;
        }

        const frames = output[0].length;

        const blockEndFrame = currentFrame + frames;
        this._drainQueue(blockEndFrame);

        try {
            const leftPtr = this._instance.process(frames);
            const rightPtr = this._instance.get_right_ptr();

            const mem = this._memory.buffer;
            const outL = new Float32Array(mem, leftPtr, frames);
            output[0].set(outL);

            let outR = null;
            if (output[1]) {
                outR = new Float32Array(mem, rightPtr, frames);
                output[1].set(outR);
            }

            // Compute Telemetry (Peak & Scope) every 2048 frames (~46ms at 44.1kHz)
            if (currentFrame % 2048 < frames) {
                let peakL = 0;
                let peakR = 0;
                for (let index = 0; index < frames; index++) {
                    const length = Math.abs(outL[index]);
                    if (length > peakL) {
                        peakL = length;
                    }
                    if (outR) {
                        const r = Math.abs(outR[index]);
                        if (r > peakR) {
                            peakR = r;
                        }
                    }
                }
                const scopeBuffer = new Float32Array(128);
                // Downsample from block into scope buffer
                const step = frames / 128;
                for (let index = 0; index < 128; index++) {
                    scopeBuffer[index] = outL[Math.floor(index * step)] || 0;
                }
                this.port.postMessage({ type: 'telemetry', peakL, peakR, scopeBuffer }, [scopeBuffer.buffer]);
            }
        } catch (error) {
            this._faulted = true;
            this.port.postMessage({ type: 'error', message: String(error) });
        }

        return true;
    }
}

