        }

        const frames = input[0].length;

        // 1. Resolve current temporal position
        let currentShiftSemitones = 0;
        if (this._transportView) {
            const value = this._transportView;
            const currentBeat = value[0];
            const tempo = value[1];
            const isPlaying = value[5] > 0.5;

            if (isPlaying) {
