 *   { type: 'cc', cc, value }
 *   { type: 'bypass', bypassed }
 *   { type: 'addSample', sampleId, data, frameCount, channels, sampleRate }
 *   { type: 'addZone', ... }
 *   { type: 'buildZoneMap', numArticulations, numMics }
 *   { type: 'clearZones' }
