import { trackStore } from '#/modules/Arrangement/stores';
import { getTrackById, getSynthParamsForTrack } from '#/modules/Arrangement/useCases';
import { scheduleNote, startFaustNote, getDrumKitDefByIndex, scheduleDrumKitNote } from '#/modules/Synth/useCases';

import { audioEngine } from '../repositories/createWebAudioEngine';

export function playAuditionNote(trackId: string, pitch: number, velocity: number = 100): () => void {
    const strip = audioEngine.ensureTrackStrip(trackId);
    const now = audioEngine.context.currentTime;

    const track = getTrackById(trackId);
    const drumDevice = track?.devices.find(
        (data) =>
            data.type === 'builtin-drum-kit' || data.type === 'drum-kit' || data.type.startsWith('builtin-drum-machine')
    );

    if (drumDevice) {
        const kitIndex = drumDevice.parameterValues.kit ?? drumDevice.parameterValues.kitId ?? 0;
        const kitDef = getDrumKitDefByIndex(kitIndex);
        if (kitDef) {
            scheduleDrumKitNote(audioEngine.context, strip.gainNode, kitDef, pitch, now, velocity);
        }
        return () => {};
    }

    const fermenterDevice = track?.devices.find((data) => data.type === 'fermenter');
    if (fermenterDevice) {
        const dn = strip.deviceNodes.find((data) => data.deviceId === fermenterDevice.id || data.type === 'fermenter');
        if (dn?.fermenterControls?.ready) {
            dn.fermenterControls.noteOn(pitch, velocity);
            return () => {
                dn.fermenterControls?.noteOff(pitch);
            };
        }
        return () => {};
    }

    let isToasterChild = false;
    let toasterParentTrack;
    if (track?.parentId) {
        toasterParentTrack = getTrackById(track.parentId);
        if (toasterParentTrack?.devices.some((data) => data.type === 'toaster')) {
            isToasterChild = true;
        }
    }

    const toasterDevice =
        track?.devices.find((data) => data.type === 'toaster') ||
        toasterParentTrack?.devices.find((data) => data.type === 'toaster');

    if (toasterDevice) {
        const effectiveTrackId = toasterParentTrack ? toasterParentTrack.id : trackId;
        const parentStrip = audioEngine.ensureTrackStrip(effectiveTrackId);

        const dn = parentStrip.deviceNodes.find(
            (data) => data.deviceId === toasterDevice.id || data.type === 'toaster'
        );

        if (dn?.toasterControls?.ready) {
            let pad = pitch - 36;

            if (isToasterChild && toasterParentTrack) {
                const children =
                    trackStore.value?.tracks.filter((time: any) => time.parentId === toasterParentTrack.id) || [];
                const childPad = children.findIndex((time: any) => time.id === trackId);
                if (childPad !== -1) {
                    pad = childPad;
                }
            }

            dn.toasterControls.noteOn(pad, velocity ?? 100, pitch);
            return () => {
                dn.toasterControls?.noteOff(pad);
            };
        }
        return () => {};
    }

    const grandBouleDevice = track?.devices.find((data) => data.type === 'grand-boule');
    if (grandBouleDevice) {
        const dn = strip.deviceNodes.find(
            (data) => data.deviceId === grandBouleDevice.id || data.type === 'grand-boule'
        );
        if (dn?.grandBouleControls?.ready) {
            dn.grandBouleControls.noteOn(pitch, velocity / 127);
            return () => {
                dn.grandBouleControls?.noteOff(pitch);
            };
        }
        return () => {};
    }

    const levainDevice = track?.devices.find((data) => data.type === 'levain');
    if (levainDevice) {
        const dn = strip.deviceNodes.find((data) => data.deviceId === levainDevice.id || data.type === 'levain');
        if (dn?.levainControls?.ready) {
            dn.levainControls.noteOn(pitch, velocity);
            return () => {
                dn.levainControls?.noteOff(pitch);
            };
        }
    }

    const faustDevice = track?.devices.find((data) => data.type.startsWith('faust-'));
    if (faustDevice) {
        return startFaustNote(trackId, faustDevice.id, pitch, velocity, now);
    }

    const synthParams = getSynthParamsForTrack(trackId);
    const osc = scheduleNote(
        audioEngine.context,
        strip.gainNode,
        pitch,
        now,
        60,
        velocity,
        synthParams
    ) as OscillatorNode & { _env?: GainNode };

    return () => {
        const killTime = audioEngine.context.currentTime;
        const releaseTime = synthParams?.release ?? 0.3;
        if (osc._env) {
            osc._env.gain.cancelScheduledValues(killTime);
            osc._env.gain.setTargetAtTime(0, killTime, releaseTime / 3);
        }
        try {
            osc.stop(killTime + releaseTime + 0.05);
        } catch {
            /* already stopped */
        }
    };
}

import { inject } from '#/infra/di/inject';
import { logger } from '#/infra/logger/appLogger';

import { isPluginRequiresIsolationError } from '../engine/pluginHostingErrors';
import { type Device } from '../models/TrackViewTypes';
import { type OfflineDeviceNode } from '../repositories/devices/types';
import { deviceRegistry, type AudioDeviceStrategy } from '../repositories/deviceStrategy/setupDeviceStrategies';

export type DeviceNodeEntry = {
    deviceId: string;
    deviceType: string;
    node: OfflineDeviceNode;
    strategy: AudioDeviceStrategy;

    // Kept for backwards compatibility with consumers until fully migrated
    nativeDsp?: {
        setParam: (name: string, value: number) => void;
        setBypass: (bypassed: boolean) => void;
    };
    instrumentControls?: {
        noteOn: (noteOrPad: number, velocity: number, midiNote?: number, sampleFrame?: number) => void;
        noteOff: (noteOrPad: number, sampleFrame?: number) => void;
    };
};

export type BuildDeviceChainOutput = DeviceNodeEntry[];

/**
 * Build an audio device chain, connecting devices between input and output nodes.
 *
 * Supports three device backends via the unified DeviceFactoryRegistry:
 * 1. Built-in Web Audio devices (synchronous)
 * 2. Faust DSP devices (async compilation + AudioWorkletNode)
 * 3. Native Rust/WASM DSP devices (async WASM init + AudioWorkletNode)
 *
 * Unknown or failed devices are skipped gracefully.
 */
export const buildDeviceChain = inject({ logger })(
    ({ logger }) =>
        async function buildDeviceChain(
            ctx: BaseAudioContext,
            devices: Device[],
            inputNode: AudioNode,
            outputNode: AudioNode
        ): Promise<BuildDeviceChainOutput> {
            const activeDevices = devices.filter((data) => !data.bypassed);
            if (activeDevices.length === 0) {
                inputNode.connect(outputNode);
                return [];
            }

            const entries: DeviceNodeEntry[] = [];
            let prev: AudioNode = inputNode;

            for (const device of activeDevices) {
                let strategy: AudioDeviceStrategy | null = null;
                try {
                    strategy = await deviceRegistry.createDevice(ctx, device);
                } catch (error) {
                    // When the plugin fails because it requires cross-origin
                    // isolation (SharedArrayBuffer), surface a user-visible message —
                    // otherwise the device chain silently skipping the node is
                    // invisible. Other failures stay at `warn` to avoid noise for
                    // routine issues (missing assets, stale worklets during HMR, etc.).
                    if (isPluginRequiresIsolationError(error)) {
                        logger.error(error);
                    } else {
                        logger.warn(`Device ${device.type} failed to load: ${error}`);
                    }
                    continue;
                }

                if (!strategy) {
                    continue;
                }

                const dn = strategy.node;

                // Instrument devices (Fermenter, Toaster, Levain) have 0 inputs — they
                // are audio sources, not pass-through effects. Route their output INTO
                // the current chain position (trackGain) so:
                //   Instrument.output → trackGain → [effects] → trackPan → destination
                // This preserves gain/pan automation on the instrument's output.
                const isSourceNode = dn.inputNode instanceof AudioWorkletNode && dn.inputNode.numberOfInputs === 0;
                if (isSourceNode) {
                    dn.outputNode.connect(prev);
                    // Don't advance `prev` — subsequent effects chain from trackGain forward
                } else {
                    prev.connect(dn.inputNode);
                    prev = dn.outputNode;
                }

                entries.push({
                    deviceId: device.id,
                    deviceType: device.type,
                    node: dn,
                    strategy,
                    // Proxies for legacy support (to be phased out completely soon)
                    nativeDsp: {
                        setParam: (name, value) => strategy.setParam(name, value),
                        setBypass: (bypassed) => strategy.setBypass?.(bypassed),
                    },
                    instrumentControls: {
                        noteOn: (note, vel, midi, sampleFrame) => strategy.noteOn?.(note, vel, midi, sampleFrame),
                        noteOff: (note, sampleFrame) => strategy.noteOff?.(note, sampleFrame),
                    },
                });
            }

            prev.connect(outputNode);
            return entries;
        }
);

