// @ts-nocheck
/// <reference lib="webworker" />
/**
 * Grand Boule Engine Worker — runs the WASM physical-modeling piano engine
 * on a dedicated thread, rendering ahead into a SharedArrayBuffer ring buffer
 * that the AudioWorklet consumes.
 *
 * This decouples the heavy DSP from the AudioWorklet's strict real-time
 * deadline (~2.67 ms per 128-sample quantum at 48 kHz). The Worker gets a
 * full OS timeslice and can absorb occasional spikes without causing glitches.
 *
 * Port protocol (self.onmessage):
 *   ← { type: 'init', wasmBytes: ArrayBuffer, sab: SharedArrayBuffer, sampleRate: number }
 *   → { type: 'ready' }
 *   ← { type: 'noteOn', midiNote, velocity }
 *   ← { type: 'noteOff', midiNote }
 *   ← { type: 'param', name, value }
 *   ← { type: 'sustain', position }
 *   ← { type: 'unaCorda', engaged }
 *   ← { type: 'sostenuto', engaged }
 *   ← { type: 'noteOnMidi2', midiNote, velocity16bit, pitchOffsetQ24 }
 *   ← { type: 'temperament', index }
 *   ← { type: 'loadAttackClip', key, samples }
 *   ← { type: 'allNotesOff' }
 *   ← { type: 'stop' }
 */

import { initSync, GrandBouleInstance } from '../wasm/daw_dsp.js';

/** Render block size — matches AudioWorklet quantum. */
const BLOCK_SIZE = 128;

/** Minimum frames of headroom to maintain in the ring buffer. The worker
 *  tries to stay this far ahead of the worklet's read position. */
const TARGET_AHEAD = BLOCK_SIZE * 6; // ~16 ms at 48 kHz

/** Zero-delay yield via MessageChannel. Posts a message to ourselves that
 *  fires as a macrotask — after any pending onmessage handlers (MIDI events)
 *  but without the artificial 1–4 ms floor that setTimeout imposes. */
const yieldChannel = new MessageChannel();
const scheduleRender = (): void => yieldChannel.port2.postMessage(null);
yieldChannel.port1.onmessage = () => renderLoop();

/** Map camelCase param names from TypeScript to snake_case for Rust. */
const PARAM_MAP: Record<string, string> = {
    masterGain: 'master_gain',
    soundboardSend: 'soundboard_send',
    sympatheticSend: 'sympathetic_send',
    stretchAmount: 'stretch_amount',
    attackBite: 'attack_bite',
    velocityCurve: 'velocity_curve',
    hammerHardnessScale: 'hammer_hardness_scale',
    hammerMassScale: 'hammer_mass_scale',
    soundboardBrightness: 'soundboard_brightness',
    sympatheticLevel: 'sympathetic_level',
    bodyResonance: 'body_resonance',
    toneColor: 'tone_color',
};

let instance: InstanceType<typeof GrandBouleInstance> | null = null;
let memory: WebAssembly.Memory | null = null;
let running = false;

// SAB layout: [writeHead: Int32, readHead: Int32, leftRing: Float32[], rightRing: Float32[]]
let controlInts: Int32Array | null = null;
let leftRing: Float32Array | null = null;
let rightRing: Float32Array | null = null;
let ringFrames = 0;

const WRITE_HEAD_IDX = 0;
const READ_HEAD_IDX = 1;

function initEngine(wasmBytes: ArrayBuffer, sab: SharedArrayBuffer, sampleRate: number): void {
    // Parse SAB layout.
    controlInts = new Int32Array(sab, 0, 2);
    const headerBytes = 2 * Int32Array.BYTES_PER_ELEMENT; // 8 bytes
    const floatBytes = sab.byteLength - headerBytes;
    ringFrames = floatBytes / (2 * Float32Array.BYTES_PER_ELEMENT);
    leftRing = new Float32Array(sab, headerBytes, ringFrames);
    rightRing = new Float32Array(sab, headerBytes + ringFrames * Float32Array.BYTES_PER_ELEMENT, ringFrames);

    // Reset heads.
    Atomics.store(controlInts, WRITE_HEAD_IDX, 0);
    Atomics.store(controlInts, READ_HEAD_IDX, 0);

    // Init WASM.
    const exports = initSync({ module: new WebAssembly.Module(wasmBytes) });
    memory = exports.memory;
    instance = new GrandBouleInstance(sampleRate, 64);
    running = true;
    self.postMessage({ type: 'ready' });
    scheduleRender();
}

function renderLoop(): void {
    if (!running || !instance || !controlInts || !leftRing || !rightRing || !memory) {
        return;
    }

    // Render as many blocks as needed to stay TARGET_AHEAD of the consumer,
    // using a bounded loop instead of recursion to avoid stack overflow.
    const maxBlocksPerTick = Math.ceil(TARGET_AHEAD / BLOCK_SIZE) + 1;
    let buffered = 0;

    for (let index = 0; index < maxBlocksPerTick; index++) {
        const writeHead = Atomics.load(controlInts, WRITE_HEAD_IDX);
        const readHead = Atomics.load(controlInts, READ_HEAD_IDX);
        buffered = (writeHead - readHead) | 0;

        if (buffered >= TARGET_AHEAD || ringFrames - buffered < BLOCK_SIZE) {
            break; // Enough headroom or ring is full.
        }

        // Render one block.
        const leftPtr = instance.process(BLOCK_SIZE);
        const rightPtr = instance.get_right_ptr();
        const mem = memory.buffer;
        const leftSrc = new Float32Array(mem, leftPtr, BLOCK_SIZE);
        const rightSrc = new Float32Array(mem, rightPtr, BLOCK_SIZE);

        // Write into ring buffer (wrapping).
        const offset = (writeHead >>> 0) % ringFrames;
        const firstChunk = Math.min(BLOCK_SIZE, ringFrames - offset);
        const secondChunk = BLOCK_SIZE - firstChunk;

        leftRing.set(leftSrc.subarray(0, firstChunk), offset);
        rightRing.set(rightSrc.subarray(0, firstChunk), offset);
        if (secondChunk > 0) {
            leftRing.set(leftSrc.subarray(firstChunk), 0);
            rightRing.set(rightSrc.subarray(firstChunk), 0);
        }

        Atomics.store(controlInts, WRITE_HEAD_IDX, (writeHead + BLOCK_SIZE) | 0);
        Atomics.pause?.();
    }

    // Yield to the event loop so pending MIDI messages can be dispatched.
    // If the buffer is full, sleep for 2ms instead of spinning immediately.
    if (buffered >= TARGET_AHEAD) {
        setTimeout(scheduleRender, 2);
    } else {
        scheduleRender();
    }
}

function dispatch(msg: Record<string, unknown>): void {
    if (!instance) {
        return;
    }
    switch (msg.type) {
        case 'noteOn':
            instance.note_on(msg.midiNote as number, msg.velocity as number, msg.sampleFrame as number);
            break;
        case 'noteOff':
            instance.note_off(msg.midiNote as number, msg.sampleFrame as number);
            break;
        case 'param':
            instance.set_param(PARAM_MAP[msg.name as string] ?? (msg.name as string), msg.value as number);
            break;
        case 'sustain':
            instance.set_sustain(msg.position as number);
            break;
        case 'unaCorda':
            instance.set_una_corda(msg.engaged as boolean);
            break;
        case 'sostenuto':
            instance.set_sostenuto(msg.engaged as boolean);
            break;
        case 'noteOnMidi2':
            instance.note_on_midi2(msg.midiNote as number, msg.velocity16bit as number, msg.pitchOffsetQ24 as number);
            break;
        case 'temperament':
            instance.set_temperament(msg.index as number);
            break;
        case 'loadAttackClip':
            instance.load_attack_clip(msg.key as number, msg.samples as Float32Array);
            break;
        case 'allNotesOff':
            instance.all_notes_off();
            break;
    }
}

self.onmessage = ({ data }: MessageEvent): void => {
    const msg = data as Record<string, unknown>;
    if (msg.type === 'init') {
        initEngine(msg.wasmBytes as ArrayBuffer, msg.sab as SharedArrayBuffer, msg.sampleRate as number);
    } else if (msg.type === 'stop') {
        running = false;
    } else {
        dispatch(msg);
    }
};

/// <reference lib="webworker" />
/**
 * Recording OPFS Worker — drains the SAB ring buffer to an OPFS temp file
 * during capture, then transfers the complete PCM Float32Array to the main
 * thread on stop.
 *
 * Keeping OPFS writes on this background thread means the main thread sees
 * zero memory growth and zero blocking during recording.
 *
 * Port protocol (self.onmessage):
 *   ← { type: 'init',  sab: SharedArrayBuffer, sampleRate: number }
 *   → { type: 'ready' }
 *   ← { type: 'start' }
 *   ← { type: 'stop'  }
 *   → { type: 'pcm',   samples: Float32Array, sampleRate: number }  (transferable)
 *   → { type: 'error', message: string }                            (on failure)
 */

const POLL_MS = 50; // drain interval — plenty of margin ahead of worklet writes

let ring: Float32Array | null = null;
let writeHead: Int32Array | null = null;
let localReadHead = 0;
let workerSampleRate = 48000;

let opfsWritable: FileSystemWritableFileStream | null = null;
let opfsFileHandle: FileSystemFileHandle | null = null;

let pollTimer: ReturnType<typeof setTimeout> | null = null;
let active = false;

// Unique temp filename per recording session to avoid collisions.
let tmpName = '';

async function initWorker(sab: SharedArrayBuffer, sampleRate: number): Promise<void> {
    writeHead = new Int32Array(sab, 0, 1);
    ring = new Float32Array(sab, 4);
    localReadHead = 0;
    workerSampleRate = sampleRate;
    tmpName = `rec-tmp-${Date.now()}.pcm`;

    const root = await navigator.storage.getDirectory();
    opfsFileHandle = await root.getFileHandle(tmpName, { create: true });
    opfsWritable = await opfsFileHandle.createWritable();
}

async function drain(): Promise<void> {
    if (!ring || !writeHead || !opfsWritable) {
        return;
    }

    const currentWrite = Atomics.load(writeHead, 0);
    const available = currentWrite - localReadHead;
    if (available <= 0) {
        return;
    }

    // Copy the available samples out of the ring (handles wrap-around).
    const chunk = new Float32Array(available);
    const ringSize = ring.length;
    for (let index = 0; index < available; index++) {
        chunk[index] = ring[(localReadHead + index) % ringSize] ?? 0;
    }
    localReadHead += available;

    await opfsWritable.write(chunk.buffer);
}

function startPolling(): void {
    active = true;
    const tick = async (): Promise<void> => {
        if (!active) {
            return;
        }
        await drain();
        pollTimer = setTimeout(() => {
            void tick();
        }, POLL_MS);
    };
    void tick();
}

async function stopWorker(): Promise<void> {
    active = false;
    if (pollTimer !== null) {
        clearTimeout(pollTimer);
        pollTimer = null;
    }

    // Final drain — pick up any samples written between the last poll and stop.
    await drain();

    await opfsWritable?.close();
    opfsWritable = null;

    if (!opfsFileHandle) {
        self.postMessage({ type: 'error', message: 'OPFS file handle missing on stop' });
        return;
    }

    // Re-open stream to patch the WAV header at the beginning
    const patchStream = await opfsFileHandle.createWritable({ keepExistingData: true });
    const header = new ArrayBuffer(44);
    const view = new DataView(header);

    const totalSamples = localReadHead;
    view.setUint32(0, 0x52494646, false); // "RIFF"
    view.setUint32(4, 36 + totalSamples * 4, true);
    view.setUint32(8, 0x57415645, false); // "WAVE"
    view.setUint32(12, 0x666d7420, false); // "fmt "
    view.setUint32(16, 16, true);
    view.setUint16(20, 3, true); // IEEE float
    view.setUint16(22, 1, true); // Mono
    view.setUint32(24, workerSampleRate, true);
    view.setUint32(28, workerSampleRate * 4, true);
    view.setUint16(32, 4, true);
    view.setUint16(34, 32, true);
    view.setUint32(36, 0x64617461, false); // "data"
    view.setUint32(40, totalSamples * 4, true);

    await patchStream.write({ type: 'write', position: 0, data: header });
    await patchStream.close();

    // Read back the full WAV file and transfer ownership to the main thread.
    const file = await opfsFileHandle.getFile();
    const arrayBuffer = await file.arrayBuffer();

    self.postMessage({ type: 'wav', buffer: arrayBuffer }, [arrayBuffer]);

    // Remove the temp file — non-fatal if it fails.
    try {
        const root = await navigator.storage.getDirectory();
        await root.removeEntry(tmpName);
    } catch {
        // ignore
    }
    opfsFileHandle = null;
}

self.onmessage = ({ data }: MessageEvent): void => {
    switch ((data as { type: string }).type) {
        case 'init':
            void initWorker(data.sab as SharedArrayBuffer, data.sampleRate as number).then(() => {
                self.postMessage({ type: 'ready' });
                return null;
            });
            break;
        case 'start':
            startPolling();
            break;
        case 'stop':
            void stopWorker();
            break;
    }
};

export type AutomationCurveType = 'linear' | 'exponential' | 'step' | 's-curve' | 'stairs' | 'smooth' | 'bezier';

export type AutomationPoint = {
    beat: number;
    value: number;
    curve: AutomationCurveType;
    tension: number; // -1.0 to +1.0: negative = log, positive = exp, 0 = linear
    stairSteps?: number; // For 'stairs' curve: number of steps (2–32, default 4)
    cp1?: { x: number; y: number }; // Normalized (0..1) bezier control point 1
    cp2?: { x: number; y: number }; // Normalized (0..1) bezier control point 2
};

export type ClipAutomationMode = 'additive' | 'multiplicative';

export type AutomationObject = {
    id: string;
    laneId: string;
    startBeat: number;
    endBeat: number;
    points: AutomationPoint[];
    poolId?: string; // Shared ID for linked/pooled copies
    loopLength?: number; // If set, object content loops at this length
    /** H2: Which properties are locally overridden on this instance. */
    overrides?: Record<string, boolean>;
    name: string;
};

export type AutomationLane = {
    id: string;
    trackId: string;
    clipId?: string;
    clipAutomationMode?: ClipAutomationMode; // Only for clip-level lanes
    parameterId: string;
    parameterName: string;
    points: AutomationPoint[];
    trimPoints?: AutomationPoint[]; // Trim offset curves for non-destructive mixing rides
    objects: AutomationObject[]; // Bounded reusable automation containers
    ghostPoints?: AutomationPoint[]; // F3.2: AI-suggested or inactive take points
    visible: boolean;
    enabled: boolean;
    collapsed: boolean; // Accordion state — collapsed shows sparkline
    linkedLaneId?: string; // F3.3: ID of another lane this one follows
    linkScale?: number; // F3.3: Scaling factor for linked automation (e.g., -1 for inversion)
    virginTerritory: boolean; // When true, gaps between points defer to manual control
    minValue: number;
    maxValue: number;
    viewMinValue?: number; // Per-lane Y-axis zoom (null = use minValue)
    viewMaxValue?: number; // Per-lane Y-axis zoom (null = use maxValue)
    color?: string; // Defaults to track color if unset
};

export const createAutomationLane = (
    trackId: string,
    parameterId: string,
    parameterName: string,
    minValue = 0,
    maxValue = 1,
    clipId?: string
): AutomationLane => ({
    id: `auto-${crypto.randomUUID().slice(0, 8)}`,
    trackId,
    clipId,
    parameterId,
    parameterName,
    points: [],
    objects: [],
    visible: true,
    enabled: true,
    collapsed: false,
    virginTerritory: true,
    minValue,
    maxValue,
});

export function createAutomationObject(
    laneId: string,
    startBeat: number,
    endBeat: number,
    points: AutomationPoint[] = [],
    name = 'Untitled'
): AutomationObject {
    return {
        id: `auto-obj-${crypto.randomUUID().slice(0, 8)}`,
        laneId,
        startBeat,
        endBeat,
        points,
        name,
    };
}

