/**
 * CrossoverDisplay — interactive frequency spectrum with draggable crossover boundaries.
 *
 * Shows band regions with color coding and crossover frequency handles.
 */
import { type ReactElement, useRef } from 'react';

import { type BacteriaCrossoverMode } from '../../models/BacteriaPatch';

type CrossoverDisplayProps = {
    bandCount: number;
    crossoverFreqs: number[];
    crossoverMode: BacteriaCrossoverMode;
    activeBand: number;
    onBandSelect: (index: number) => void;
    onCrossoverChange: (index: number, freq: number) => void;
};

const BAND_COLORS = [
    'rgba(244,63,94,0.15)', // rose
    'rgba(251,146,60,0.15)', // orange
    'rgba(250,204,21,0.15)', // yellow
    'rgba(74,222,128,0.15)', // green
    'rgba(96,165,250,0.15)', // blue
    'rgba(167,139,250,0.15)', // violet
];

const BAND_BORDER_COLORS = [
    'rgba(244,63,94,0.6)',
    'rgba(251,146,60,0.6)',
    'rgba(250,204,21,0.6)',
    'rgba(74,222,128,0.6)',
    'rgba(96,165,250,0.6)',
    'rgba(167,139,250,0.6)',
];

function freqToX(freq: number, width: number): number {
    const minLog = Math.log10(20);
    const maxLog = Math.log10(20000);
    return ((Math.log10(freq) - minLog) / (maxLog - minLog)) * width;
}

function xToFreq(x: number, width: number): number {
    const minLog = Math.log10(20);
    const maxLog = Math.log10(20000);
    const log = minLog + (x / width) * (maxLog - minLog);
    return Math.round(10 ** log);
}

const DISPLAY_HEIGHT = 80;

export const CrossoverDisplay = ({
    bandCount,
    crossoverFreqs,
    crossoverMode,
    activeBand,
    onBandSelect,
    onCrossoverChange,
}: CrossoverDisplayProps): ReactElement => {
    const containerRef = useRef<HTMLDivElement>(null);
    const dragIndex = useRef<number | null>(null);

    const handlePointerDown = (e: React.PointerEvent, index: number): void => {
        e.stopPropagation();
        dragIndex.current = index;
        (e.target as HTMLElement).setPointerCapture(e.pointerId);
    };

    const handlePointerMove = (e: React.PointerEvent): void => {
        if (dragIndex.current === null) {
            return;
        }
        const rect = containerRef.current?.getBoundingClientRect();
        if (!rect) {
            return;
        }
        const x = e.clientX - rect.left;
        const freq = Math.max(20, Math.min(20000, xToFreq(x, rect.width)));
        onCrossoverChange(dragIndex.current, freq);
    };

    const handlePointerUp = (): void => {
        dragIndex.current = null;
    };

    const handleBandClick = (e: React.PointerEvent): void => {
        if (dragIndex.current !== null) {
            return;
        }
        const rect = containerRef.current?.getBoundingClientRect();
        if (!rect) {
            return;
        }
        const x = e.clientX - rect.left;
        const freq = xToFreq(x, rect.width);

        // Determine which band was clicked
        for (let i = 0; i < bandCount; i++) {
            const lo = i === 0 ? 20 : crossoverFreqs[i - 1]!;
            const hi = i === bandCount - 1 ? 20000 : crossoverFreqs[i]!;
            if (freq >= lo && freq <= hi) {
                onBandSelect(i);
                break;
            }
        }
    };

    return (
        <div
            ref={containerRef}
            className="relative w-full shrink-0 cursor-pointer select-none"
            style={{
                height: DISPLAY_HEIGHT,
                background: 'linear-gradient(180deg, #0a0a0a 0%, #111 100%)',
                borderBottom: '1px solid rgba(255,255,255,0.05)',
            }}
            onPointerMove={handlePointerMove}
            onPointerUp={handlePointerUp}
            onPointerDown={handleBandClick}
        >
            {/* Frequency grid */}
            {[100, 1000, 10000].map((freq) => {
                const x = freqToX(freq, containerRef.current?.clientWidth ?? 800);
                return (
                    <div
                        key={freq}
                        className="absolute top-0 pointer-events-none"
                        style={{ left: x, width: 1, height: DISPLAY_HEIGHT, background: 'rgba(255,255,255,0.04)' }}
                    >
                        <span className="absolute bottom-0.5 left-1 text-[6px] text-muted-foreground/30 font-mono">
                            {freq >= 1000 ? `${freq / 1000}k` : freq}
                        </span>
                    </div>
                );
            })}

            {/* Band regions */}
            {Array.from({ length: bandCount }, (_, i) => {
                const containerWidth = containerRef.current?.clientWidth ?? 800;
                const lo = freqToX(i === 0 ? 20 : crossoverFreqs[i - 1]!, containerWidth);
                const hi = freqToX(i === bandCount - 1 ? 20000 : crossoverFreqs[i]!, containerWidth);
                return (
                    <div
                        key={i}
                        className="absolute top-0 pointer-events-none"
                        style={{
                            left: lo,
                            width: Math.max(0, hi - lo),
                            height: DISPLAY_HEIGHT,
                            background: BAND_COLORS[i % BAND_COLORS.length],
                            borderLeft:
                                i > 0 ? `1px solid ${BAND_BORDER_COLORS[i % BAND_BORDER_COLORS.length]}` : undefined,
                            opacity: activeBand === i ? 1 : 0.5,
                        }}
                    >
                        <span
                            className="absolute top-1 left-1 text-[7px] font-bold pointer-events-none"
                            style={{ color: BAND_BORDER_COLORS[i % BAND_BORDER_COLORS.length] }}
                        >
                            {i + 1}
                        </span>
                    </div>
                );
            })}

            {/* Crossover handles */}
            {Array.from({ length: Math.max(0, bandCount - 1) }, (_, i) => {
                const containerWidth = containerRef.current?.clientWidth ?? 800;
                const x = freqToX(crossoverFreqs[i]!, containerWidth);
                return (
                    <div
                        key={`handle-${i}`}
                        className="absolute top-0 cursor-ew-resize"
                        style={{ left: x - 4, width: 8, height: DISPLAY_HEIGHT }}
                        onPointerDown={(e) => handlePointerDown(e, i)}
                    >
                        <div
                            className="absolute left-[3px] top-0 w-0.5 rounded-full"
                            style={{
                                height: DISPLAY_HEIGHT,
                                background: BAND_BORDER_COLORS[(i + 1) % BAND_BORDER_COLORS.length],
                            }}
                        />
                    </div>
                );
            })}

            {/* Mode indicator */}
            <span className="absolute top-1 right-1 text-[6px] text-muted-foreground/30 font-mono uppercase">
                {crossoverMode}
            </span>
        </div>
    );
};

/**
 * ModulationDock — drag-and-drop modulation assignment panel.
 *
 * Vital-style modulation source tray where users can drag mod sources
 * (LFO, Envelope Follower, Lorenz, Step Seq, Macros) onto any target
 * parameter knob to create modulation assignments.
 */
import { type ReactElement, useState } from 'react';

import { type BacteriaPatch, type BacteriaModAssignment } from '../../models/BacteriaPatch';

type ModulationDockProps = {
    patch: BacteriaPatch;
    modValues: number[]; // Real-time mod source values for display
    onAssignmentAdd: (assignment: BacteriaModAssignment) => void;
    onAssignmentRemove: (index: number) => void;
};

const MOD_SOURCES = [
    { id: 'lfo1', label: 'LFO 1', color: 'rgb(244, 63, 94)', icon: '~' },
    { id: 'lfo2', label: 'LFO 2', color: 'rgb(251, 146, 60)', icon: '~' },
    { id: 'env', label: 'Env Follow', color: 'rgb(74, 222, 128)', icon: '▲' },
    { id: 'lorenz', label: 'Lorenz', color: 'rgb(167, 139, 250)', icon: '∞' },
    { id: 'stepseq', label: 'Step Seq', color: 'rgb(96, 165, 250)', icon: '▦' },
    { id: 'macro1', label: 'Macro 1', color: 'rgb(250, 204, 21)', icon: '1' },
    { id: 'macro2', label: 'Macro 2', color: 'rgb(250, 204, 21)', icon: '2' },
    { id: 'macro3', label: 'Macro 3', color: 'rgb(250, 204, 21)', icon: '3' },
    { id: 'macro4', label: 'Macro 4', color: 'rgb(250, 204, 21)', icon: '4' },
];

export const ModulationDock = ({
    patch,
    modValues,
    onAssignmentAdd: _onAssignmentAdd,
    onAssignmentRemove,
}: ModulationDockProps): ReactElement => {
    const [dragSource, setDragSource] = useState<string | null>(null);

    const handleDragStart = (sourceId: string): void => {
        setDragSource(sourceId);
    };

    const handleDragEnd = (): void => {
        setDragSource(null);
    };

    return (
        <div className="flex flex-col gap-2 p-2">
            <div className="text-[8px] text-muted-foreground/50 font-medium uppercase tracking-wider">
                Modulation Sources
            </div>

            {/* Source pills */}
            <div className="flex flex-wrap gap-1">
                {MOD_SOURCES.map((source, i) => {
                    const modVal = modValues[i] ?? 0;
                    const activeAssignments = patch.modAssignments.filter((a) => a.sourceId === source.id);

                    return (
                        <button
                            key={source.id}
                            type="button"
                            className={`flex items-center gap-1 px-1.5 py-0.5 rounded text-[7px] font-medium border transition-all cursor-grab active:cursor-grabbing ${
                                dragSource === source.id ? 'ring-1 ring-white/30 scale-105' : ''
                            }`}
                            style={{
                                borderColor: `${source.color}40`,
                                backgroundColor: `${source.color}10`,
                                color: source.color,
                            }}
                            draggable
                            onDragStart={() => handleDragStart(source.id)}
                            onDragEnd={handleDragEnd}
                        >
                            <span className="text-[8px] font-bold opacity-60">{source.icon}</span>
                            <span>{source.label}</span>
                            {/* Activity indicator */}
                            <div
                                className="w-1.5 h-1.5 rounded-full"
                                style={{
                                    backgroundColor: source.color,
                                    opacity: 0.3 + Math.abs(modVal) * 0.7,
                                    transform: `scale(${0.8 + Math.abs(modVal) * 0.4})`,
                                }}
                            />
                            {activeAssignments.length > 0 ? (
                                <span className="text-[6px] opacity-50">({activeAssignments.length})</span>
                            ) : null}
                        </button>
                    );
                })}
            </div>

            {/* Active assignments list */}
            {patch.modAssignments.length > 0 ? (
                <div className="space-y-0.5 mt-1">
                    <div className="text-[7px] text-muted-foreground/40 uppercase">Active Assignments</div>
                    {patch.modAssignments.map((assignment, idx) => {
                        const source = MOD_SOURCES.find((s) => s.id === assignment.sourceId);
                        return (
                            <div key={idx} className="flex items-center gap-1 text-[7px]">
                                <span style={{ color: source?.color ?? 'white' }}>
                                    {source?.label ?? assignment.sourceId}
                                </span>
                                <span className="text-muted-foreground/30">→</span>
                                <span className="text-foreground/60">{assignment.targetParam}</span>
                                <span className="text-muted-foreground/40 font-mono">
                                    {assignment.amount > 0 ? '+' : ''}
                                    {(assignment.amount * 100).toFixed(0)}%
                                </span>
                                <button
                                    type="button"
                                    className="text-[6px] text-muted-foreground/30 hover:text-red-400 ml-auto"
                                    onClick={() => onAssignmentRemove(idx)}
                                >
                                    ×
                                </button>
                            </div>
                        );
                    })}
                </div>
            ) : null}
        </div>
    );
};

/**
 * NodeGraphEditor — interactive signal flow DAG editor for Route level.
 *
 * Bitwig FX Grid-style node-based routing editor with draggable nodes,
 * connection cables, and routing mode toggles.
 */
import { type ReactElement, useState } from 'react';

import { type BacteriaBand, type BacteriaRoutingMode } from '../../models/BacteriaPatch';

type NodeDef = {
    id: string;
    label: string;
    x: number;
    y: number;
    color: string;
    type: 'input' | 'output' | 'crossover' | 'band' | 'sum' | 'effect';
    bandIndex?: number;
    effects?: string[];
};

type Connection = {
    from: string;
    to: string;
};

type NodeGraphEditorProps = {
    width: number;
    height: number;
    bandCount: number;
    bands: BacteriaBand[];
    globalRouting: BacteriaRoutingMode;
    crossoverFreqs: number[];
    onRoutingChange?: (bandIndex: number, mode: BacteriaRoutingMode) => void;
};

const BAND_COLORS = [
    'rgb(244,63,94)',
    'rgb(251,146,60)',
    'rgb(250,204,21)',
    'rgb(74,222,128)',
    'rgb(96,165,250)',
    'rgb(167,139,250)',
];

const EFFECT_KEYS: Record<string, string> = {
    distortionEnabled: 'Dist',
    filterEnabled: 'Filter',
    chorusEnabled: 'Chorus',
    granularEnabled: 'Grain',
    spectralEnabled: 'Spectral',
    freqShiftEnabled: 'FShift',
    lofiEnabled: 'Lo-Fi',
    convolutionEnabled: 'Body',
};

function buildNodes(
    bandCount: number,
    bands: BacteriaBand[],
    width: number,
    height: number
): { nodes: NodeDef[]; connections: Connection[] } {
    const nodes: NodeDef[] = [];
    const connections: Connection[] = [];

    const margin = 40;
    const usableWidth = width - margin * 2;
    const usableHeight = height - margin * 2;

    // Input node
    nodes.push({
        id: 'input',
        label: 'Input',
        x: usableWidth / 2 + margin,
        y: margin,
        color: 'rgb(255,255,255)',
        type: 'input',
    });

    // Crossover node (if multi-band)
    if (bandCount > 1) {
        nodes.push({
            id: 'crossover',
            label: 'Crossover',
            x: usableWidth / 2 + margin,
            y: margin + usableHeight * 0.15,
            color: 'rgb(200,200,200)',
            type: 'crossover',
        });
        connections.push({ from: 'input', to: 'crossover' });
    }

    // Band nodes
    const bandSpacing = usableWidth / (bandCount + 1);
    for (let i = 0; i < bandCount; i++) {
        const band = bands[i]!;
        const effects = Object.entries(EFFECT_KEYS)
            .filter(([key]) => band[key as keyof BacteriaBand] === true)
            .map(([, label]) => label);

        const nodeId = `band-${i}`;
        nodes.push({
            id: nodeId,
            label: `Band ${i + 1}`,
            x: bandSpacing * (i + 1) + margin,
            y: margin + usableHeight * 0.45,
            color: BAND_COLORS[i % BAND_COLORS.length]!,
            type: 'band',
            bandIndex: i,
            effects,
        });

        if (bandCount > 1) {
            connections.push({ from: 'crossover', to: nodeId });
        } else {
            connections.push({ from: 'input', to: nodeId });
        }
    }

    // Sum node
    nodes.push({
        id: 'sum',
        label: 'Sum',
        x: usableWidth / 2 + margin,
        y: margin + usableHeight * 0.75,
        color: 'rgb(200,200,200)',
        type: 'sum',
    });
    for (let i = 0; i < bandCount; i++) {
        connections.push({ from: `band-${i}`, to: 'sum' });
    }

    // Output node
    nodes.push({
        id: 'output',
        label: 'Output',
        x: usableWidth / 2 + margin,
        y: margin + usableHeight,
        color: 'rgb(255,255,255)',
        type: 'output',
    });
    connections.push({ from: 'sum', to: 'output' });

    return { nodes, connections };
}

export const NodeGraphEditor = ({
    width,
    height,
    bandCount,
    bands,
    globalRouting,
    crossoverFreqs: _crossoverFreqs,
}: NodeGraphEditorProps): ReactElement => {
    const { nodes, connections } = buildNodes(bandCount, bands, width, height);
    const [hoveredNode, setHoveredNode] = useState<string | null>(null);

    const getNode = (id: string): NodeDef | undefined => nodes.find((n) => n.id === id);

    return (
        <svg
            width={width}
            height={height}
            className="rounded-lg border border-border/30"
            style={{ background: '#080808' }}
        >
            {/* Grid */}
            <defs>
                <pattern id="grid" width="20" height="20" patternUnits="userSpaceOnUse">
                    <rect width="20" height="20" fill="none" stroke="rgba(255,255,255,0.02)" strokeWidth="0.5" />
                </pattern>
            </defs>
            <rect width={width} height={height} fill="url(#grid)" />

            {/* Connections */}
            {connections.map((conn, i) => {
                const from = getNode(conn.from);
                const to = getNode(conn.to);
                if (!from || !to) {
                    return null;
                }

                const midY = (from.y + to.y) / 2;
                return (
                    <path
                        key={i}
                        d={`M ${from.x} ${from.y + 12} C ${from.x} ${midY}, ${to.x} ${midY}, ${to.x} ${to.y - 12}`}
                        fill="none"
                        stroke="rgba(244, 63, 94, 0.3)"
                        strokeWidth={1.5}
                    />
                );
            })}

            {/* Nodes */}
            {nodes.map((node) => {
                const isHovered = hoveredNode === node.id;
                const nodeWidth = node.type === 'band' ? 80 : 60;
                const nodeHeight = node.type === 'band' ? 50 + (node.effects?.length ?? 0) * 10 : 24;

                return (
                    <g
                        key={node.id}
                        onMouseEnter={() => setHoveredNode(node.id)}
                        onMouseLeave={() => setHoveredNode(null)}
                        style={{ cursor: 'pointer' }}
                    >
                        <rect
                            x={node.x - nodeWidth / 2}
                            y={node.y - nodeHeight / 2}
                            width={nodeWidth}
                            height={nodeHeight}
                            rx={6}
                            fill={isHovered ? `${node.color}20` : `${node.color}10`}
                            stroke={node.color}
                            strokeWidth={isHovered ? 1.5 : 1}
                            strokeOpacity={0.5}
                        />
                        <text
                            x={node.x}
                            y={node.y - (node.type === 'band' ? (node.effects?.length ?? 0) * 4 : 0)}
                            textAnchor="middle"
                            dominantBaseline="middle"
                            fill={node.color}
                            fontSize={8}
                            fontWeight="bold"
                        >
                            {node.label}
                        </text>
                        {/* Effect list for band nodes */}
                        {node.effects?.map((effect, ei) => (
                            <text
                                key={ei}
                                x={node.x}
                                y={node.y + 8 + ei * 10}
                                textAnchor="middle"
                                dominantBaseline="middle"
                                fill="rgba(255,255,255,0.4)"
                                fontSize={6}
                            >
                                {effect}
                            </text>
                        ))}
                    </g>
                );
            })}

            {/* Routing mode label */}
            <text
                x={width - 8}
                y={16}
                textAnchor="end"
                fill="rgba(255,255,255,0.2)"
                fontSize={8}
                fontFamily="monospace"
            >
                {globalRouting}
            </text>
        </svg>
    );
};

