    const handleRemove = (): void => {
        void removeModel({ modelId: id, family });
    };

    if (status === 'downloading') {
        return (
            <div className="flex items-center gap-2">
                <div
                    className="w-12 h-1 bg-border/40 rounded-full overflow-hidden"
