import { type ReactElement } from 'react';

import { CheckCircle2 } from 'lucide-react';

import { DawMicroBadge } from '#/components/daw/DawMicroBadge';
import { useStore } from '#/infra/store/useStore';

import { inferenceProgressStore } from '../../stores/inferenceProgressStore';
import { renderQueueStore } from '../../stores/renderQueueStore';
import { cancelRender } from '../../useCases/cancelRender';

type RenderProgressIndicatorProps = {
    phraseId: string;
};

/** Per-phrase render progress bar shown on the canvas */
export function RenderProgressIndicator({ phraseId }: RenderProgressIndicatorProps): ReactElement | null {
    const progressState = useStore(inferenceProgressStore, { activeRenders: {} });
    const queueState = useStore(renderQueueStore, { entries: [], cachedPhraseIds: [], phraseStatusMap: {} });

    const phraseStatus = queueState?.phraseStatusMap[phraseId];
    const activeRender = progressState
        ? Object.values(progressState.activeRenders).find((r) => r.phraseId === phraseId)
        : undefined;

    if (!phraseStatus || phraseStatus === 'not-rendered') {
        return null;
    }

    if (phraseStatus === 'preview') {
        return (
            <DawMicroBadge tone="success" role="status" aria-label="Preview render ready">
                <CheckCircle2 className="size-2.5" aria-hidden="true" />
                <span>Preview ready</span>
            </DawMicroBadge>
        );
    }

    if (phraseStatus === 'final') {
        return (
            <DawMicroBadge tone="success" role="status" aria-label="Final render ready">
                <CheckCircle2 className="size-2.5" aria-hidden="true" />
                <span>Final ready</span>
            </DawMicroBadge>
        );
    }

    if (phraseStatus === 'stale') {
        return (
            <DawMicroBadge
                tone="peach"
                role="status"
                aria-label="Phrase is stale — render needed"
                title="Edit invalidated render — click to re-render"
            >
                <span aria-hidden="true">●</span>
                <span>Stale</span>
            </DawMicroBadge>
        );
    }

    if (phraseStatus === 'queued') {
        const queueEntry = queueState?.entries.find((event) => event.phraseId === phraseId);
        const queuedRequestId = queueEntry?.requestId;
        const handleCancelQueued = (): void => {
            if (queuedRequestId) {
                cancelRender({ phraseId, requestId: queuedRequestId });
            }
        };
        return (
            <div className="flex items-center gap-2 px-2 py-1 text-[9px] bg-surface-overlay border border-border/40 rounded">
                <DawMicroBadge tone="muted" role="status" aria-label="Render queued">
                    Queued
                </DawMicroBadge>
                {queuedRequestId ? (
                    <button
                        type="button"
                        onClick={handleCancelQueued}
                        className="ml-auto shrink-0 text-muted-foreground/50 hover:text-muted-foreground transition-colors"
                        aria-label="Cancel queued render"
                        title="Cancel queued render"
                    >
                        ✕
                    </button>
                ) : null}
            </div>
        );
    }

    if (phraseStatus === 'error') {
        return (
            <DawMicroBadge tone="danger" role="alert" aria-label="Render failed">
                ✕ Error
            </DawMicroBadge>
        );
    }

    // Active render (rendering-browser or rendering-native).
    // Guard: if inferenceProgressStore hasn't received startActiveRender yet (brief
    // transition) or this is a native render without browser-side progress tracking,
    // show a minimal pulsing badge rather than a broken 0% bar.
    if (!activeRender) {
        return (
            <DawMicroBadge tone="muted" role="status" aria-label="Rendering…">
                <span className="animate-pulse" aria-hidden="true">
                    ●
                </span>
                <span>Rendering…</span>
            </DawMicroBadge>
        );
    }

    const progress = activeRender.progress;
    const stage = activeRender.stage;
    const requestId = activeRender.requestId;

    const handleCancel = (): void => {
        cancelRender({ phraseId, requestId });
    };

    return (
        <div
            className="flex items-center gap-2 px-2 py-1 text-[9px] bg-surface-overlay border border-border/40 rounded min-w-[120px]"
            role="status"
            aria-label={`Rendering: ${stage}, ${Math.round(progress * 100)}%`}
        >
            <div className="flex-1 space-y-0.5">
                <div className="flex items-center justify-between gap-1">
                    <span className="text-muted-foreground truncate" title={stage}>
                        {stage}
                    </span>
                    <span className="text-muted-foreground/70 tabular-nums">{Math.round(progress * 100)}%</span>
                </div>
                <div className="w-full h-0.5 bg-border/40 rounded-full overflow-hidden" aria-hidden="true">
                    <div
                        className="h-full bg-[var(--color-accent-orange)] transition-all duration-300 ease-out"
                        style={{ width: `${Math.round(progress * 100)}%` }}
                    />
                </div>
            </div>
            {requestId ? (
                <button
                    type="button"
                    onClick={handleCancel}
                    className="shrink-0 text-muted-foreground/50 hover:text-muted-foreground transition-colors"
                    aria-label="Cancel render"
                    title="Cancel render"
                >
                    ✕
                </button>
            ) : null}
        </div>
    );
}

/**
 * Repository: Browser AI capability detection.
 *
 * Checks for Chrome + WebGPU availability and runs a micro-benchmark
 * to classify the device as webgpu-fast, webgpu-slow, or unavailable.
 *
 * Results are stored in localStorage to avoid re-running the benchmark.
 */

import { inject } from '#/infra/di/inject';
import { logger } from '#/infra/logger/appLogger';
import { isTauri } from '#/utils/tauriBridge';

import { type CapabilityReport, type WebGpuTier } from '../models/CapabilityReport';

const STORAGE_KEY = 'sourdaw-browser-ai-capability';
const BENCHMARK_FAST_THRESHOLD_MS = 50;
const BENCHMARK_SLOW_THRESHOLD_MS = 500;

/**
 * Detect Chrome version from user agent.
 * Returns null if not Chrome-based.
 */
function detectChromeVersion(): number | null {
    if (typeof navigator === 'undefined') {
        return null;
    }
    // Chrome (and Chromium-based): look for "Chrome/" in UA
    const match = navigator.userAgent.match(/Chrome\/(\d+)/);
    if (!match) {
        return null;
    }
    // Exclude Edge and Opera which also have "Chrome/" in their UA
    if (navigator.userAgent.includes('Edg/') || navigator.userAgent.includes('OPR/')) {
        return null;
    }
    return parseInt(match[1]!, 10);
}

/**
 * Determine if we're running in Tauri on macOS or Linux,
 * where WKWebView/WebKitGTK doesn't support WebGPU.
 */
function isTauriNonWindowsPlatform(): boolean {
    if (!isTauri()) {
        return false;
    }
    // In Tauri, navigator.platform reports the OS
    const platform = navigator.platform?.toLowerCase() ?? '';
    return platform.includes('mac') || platform.includes('linux');
}

/**
 * Run a minimal ONNX inference micro-benchmark to estimate WebGPU speed.
 * Returns elapsed time in ms.
 */
async function runWebGpuBenchmark(): Promise<number> {
    try {
        const startTime = performance.now();
        // Check if WebGPU adapter is available and responsive
        if (typeof navigator !== 'undefined' && 'gpu' in navigator) {
            const adapter = await (
                navigator as unknown as { gpu: { requestAdapter: () => Promise<unknown> } }
            ).gpu.requestAdapter();
            if (adapter) {
                const endTime = performance.now();
                // Adapter acquisition time is a proxy for WebGPU responsiveness
                return endTime - startTime;
            }
        }
        return BENCHMARK_SLOW_THRESHOLD_MS + 1; // Not available
    } catch {
        return BENCHMARK_SLOW_THRESHOLD_MS + 1;
    }
}

function classifyWebGpuTier(benchmarkMs: number | null): WebGpuTier {
    if (benchmarkMs === null) {
        return 'unavailable';
    }
    if (benchmarkMs < BENCHMARK_FAST_THRESHOLD_MS) {
        return 'webgpu-fast';
    }
    if (benchmarkMs < BENCHMARK_SLOW_THRESHOLD_MS) {
        return 'webgpu-slow';
    }
    return 'unavailable';
}

type DetectCapabilitiesOutput = Promise<CapabilityReport>;

export const detectCapabilities = inject({ logger })(
    ({ logger }) =>
        async function detectCapabilities({
            forceRefresh = false,
        }: { forceRefresh?: boolean } = {}): DetectCapabilitiesOutput {
            // Check cached result first
            if (!forceRefresh && typeof localStorage !== 'undefined') {
                const cached = localStorage.getItem(STORAGE_KEY);
                if (cached) {
                    try {
                        const parsed = JSON.parse(cached) as CapabilityReport;
                        logger.info('[BrowserAi] Using cached capability report');
                        return parsed;
                    } catch {
                        // Corrupt cache — re-detect
                    }
                }
            }

            const chromeVersion = detectChromeVersion();
            const webGpuAvailable = typeof navigator !== 'undefined' && 'gpu' in navigator;
            const sharedArrayBuffer = typeof SharedArrayBuffer !== 'undefined';
            const opfsAvailable =
                typeof navigator !== 'undefined' && 'storage' in navigator && 'getDirectory' in navigator.storage;

            let capability: CapabilityReport['capability'];
            let benchmarkMs: number | null = null;
            let webGpuTier: WebGpuTier = 'unavailable';

            if (isTauriNonWindowsPlatform()) {
                // macOS/Linux Tauri — route to native pipeline instead
                capability = 'unsupported-platform';
                logger.info(
                    '[BrowserAi] Running in Tauri on macOS/Linux — browser AI disabled, native pipeline available'
                );
            } else if (!chromeVersion) {
                capability = 'unsupported-browser';
                logger.info('[BrowserAi] Non-Chrome browser detected — browser AI disabled');
            } else if (!webGpuAvailable) {
                capability = 'unsupported-browser';
                logger.info('[BrowserAi] WebGPU not available — browser AI disabled');
            } else {
                capability = 'supported';
                benchmarkMs = await runWebGpuBenchmark();
                webGpuTier = classifyWebGpuTier(benchmarkMs);
                logger.info(`[BrowserAi] WebGPU detected: ${webGpuTier} (${String(benchmarkMs?.toFixed(1))}ms)`);
            }

            const report: CapabilityReport = {
                capability,
                webGpuTier,
                sharedArrayBuffer,
                opfsAvailable,
                chromeVersion,
                benchmarkMs,
                detectedAt: Date.now(),
            };

            // Cache the result
            if (typeof localStorage !== 'undefined') {
                try {
                    localStorage.setItem(STORAGE_KEY, JSON.stringify(report));
                } catch {
                    // Storage quota exceeded — not critical
                }
            }

            return report;
        }
);

/**
 * Repository: Inference worker bridge.
 *
 * Manages the two inference workers (ONNX and TF.js) and routes
 * inference requests to the correct worker by model type.
 *
 * - ONNX Worker: always initialized, handles DiffSinger + Kokoro
 * - TF.js Worker: lazily spawned on first DDSP use, destroyed when idle
 *
 * Both workers communicate via the same typed WorkerRequest/WorkerResponse protocol.
 *
 * This is a module-level singleton — not injectable because it manages
 * worker lifecycle as module-level state (following the §152.1 pattern).
 */

import { logger } from '#/infra/logger/appLogger';

import { type WorkerRequest, type WorkerResponse } from '../models/InferenceRequest';
import { updateActiveRenderProgress } from '../stores/inferenceProgressStore';

type PendingRequest = {
    resolve: (value: WorkerResponse) => void;
    reject: (reason: unknown) => void;
};

type WorkerState = {
    worker: Worker | null;
    pendingRequests: Map<string, PendingRequest>;
    initialized: boolean;
};

// Module-level state following the §152.1 coalesce pattern from browserStemSeparation.ts
const workerState: {
    onnx: WorkerState;
    tfjs: WorkerState;
    tfjsIdleTimer: ReturnType<typeof setTimeout> | null;
} = {
    onnx: { worker: null, pendingRequests: new Map(), initialized: false },
    tfjs: { worker: null, pendingRequests: new Map(), initialized: false },
    tfjsIdleTimer: null,
};

const TFJS_IDLE_TIMEOUT_MS = 60_000; // 1 minute — destroy TF.js worker after idle

function createMessageHandler(state: WorkerState): (event: MessageEvent<WorkerResponse>) => void {
    return (event: MessageEvent<WorkerResponse>): void => {
        const msg = event.data;

        // Progress events don't resolve a pending request
        if (msg.type === 'inference-progress') {
            updateActiveRenderProgress({
                requestId: msg.requestId,
                stage: msg.stage,
                progress: msg.progress,
            });
            return;
        }

        const requestId = 'requestId' in msg ? msg.requestId : '';
        const pending = state.pendingRequests.get(requestId);
        if (!pending) {
            return;
        }

        state.pendingRequests.delete(requestId);

        if (msg.type === 'error') {
            pending.reject(new Error(msg.error));
        } else {
            pending.resolve(msg);
        }
    };
}

async function getOnnxWorker(): Promise<Worker> {
    if (workerState.onnx.worker && workerState.onnx.initialized) {
        return workerState.onnx.worker;
    }

    const worker = new Worker(new URL('../workers/onnxInferenceWorker.ts', import.meta.url), { type: 'module' });
    worker.onmessage = createMessageHandler(workerState.onnx);
    workerState.onnx.worker = worker;
    workerState.onnx.initialized = true;
    return worker;
}

async function getTfjsWorker(): Promise<Worker> {
    // Reset idle timer
    if (workerState.tfjsIdleTimer !== null) {
        clearTimeout(workerState.tfjsIdleTimer);
        workerState.tfjsIdleTimer = null;
    }

    if (workerState.tfjs.worker && workerState.tfjs.initialized) {
        return workerState.tfjs.worker;
    }

    const worker = new Worker(new URL('../workers/tfjsInferenceWorker.ts', import.meta.url), { type: 'module' });
    worker.onmessage = createMessageHandler(workerState.tfjs);
    workerState.tfjs.worker = worker;
    workerState.tfjs.initialized = true;
    return worker;
}

function scheduleTfjsDestroy(): void {
    if (workerState.tfjsIdleTimer !== null) {
        return;
    }
    workerState.tfjsIdleTimer = setTimeout(() => {
        if (workerState.tfjs.pendingRequests.size === 0 && workerState.tfjs.worker) {
            workerState.tfjs.worker.terminate();
            workerState.tfjs.worker = null;
            workerState.tfjs.initialized = false;
            workerState.tfjsIdleTimer = null;
        }
    }, TFJS_IDLE_TIMEOUT_MS);
}

function sendRequest(
    worker: Worker,
    state: WorkerState,
    request: WorkerRequest,
    transferable?: Transferable[]
): Promise<WorkerResponse> {
    return new Promise<WorkerResponse>((resolve, reject) => {
        const requestId = 'requestId' in request ? request.requestId : '';
        if (requestId) {
            state.pendingRequests.set(requestId, { resolve, reject });
        }
        if (transferable && transferable.length > 0) {
            worker.postMessage(request, transferable);
        } else {
            worker.postMessage(request);
        }
        // For fire-and-forget messages (no requestId), resolve immediately
        if (!requestId) {
            resolve({ type: 'status', loadedModels: [], memoryUsageBytes: 0 });
        }
    });
}

type LoadSessionInput = {
    modelId: string;
    modelData: ArrayBuffer;
};

type RunKokoroInput = {
    requestId: string;
    inputIds: BigInt64Array;
    style: Float32Array;
    speed: number;
};

type RunDiffSingerInput = Extract<WorkerRequest, { type: 'run-diffsinger-phrase' }>;

type RunDdspInput = Extract<WorkerRequest, { type: 'run-ddsp-inference' }>;

/**
 * Singleton bridge object for routing inference requests to the correct worker.
 * Module-level singleton — not injectable because it owns worker lifecycle state.
 */
export const inferenceWorkerBridge = {
    async loadOnnxSession({ modelId, modelData }: LoadSessionInput): Promise<void> {
        logger.info(`[WorkerBridge] Loading ONNX session: ${modelId}`);
        const worker = await getOnnxWorker();
        const requestId = crypto.randomUUID();
        const request: WorkerRequest = { type: 'create-session', requestId, modelId, modelData, options: {} };
        await sendRequest(worker, workerState.onnx, request, [modelData]);
    },

    async loadDdspSession({ modelId, modelUrl }: { modelId: string; modelUrl: string }): Promise<void> {
        logger.info(`[WorkerBridge] Loading DDSP (TF.js) session from URL: ${modelId}`);
        const worker = await getTfjsWorker();
        const requestId = crypto.randomUUID();
        const request: WorkerRequest = { type: 'create-session-from-url', requestId, modelId, modelUrl };
        await sendRequest(worker, workerState.tfjs, request);
    },

    async runKokoroTts(input: RunKokoroInput): Promise<Extract<WorkerResponse, { type: 'tts-result' }>> {
        const worker = await getOnnxWorker();
        const request: WorkerRequest = { type: 'run-kokoro-tts', ...input };
        // Transfer typed array buffers (zero-copy) — they are consumed by the worker
        const response = await sendRequest(worker, workerState.onnx, request, [
            input.inputIds.buffer,
            input.style.buffer,
        ]);
        return response as Extract<WorkerResponse, { type: 'tts-result' }>;
    },

    async runDiffSingerPhrase(
        input: RunDiffSingerInput
    ): Promise<Extract<WorkerResponse, { type: 'diffsinger-result' }>> {
        const worker = await getOnnxWorker();
        const response = await sendRequest(worker, workerState.onnx, input);
        return response as Extract<WorkerResponse, { type: 'diffsinger-result' }>;
    },

    async runDdspInference(input: RunDdspInput): Promise<Extract<WorkerResponse, { type: 'ddsp-result' }>> {
        const worker = await getTfjsWorker();
        const response = await sendRequest(worker, workerState.tfjs, input);
        scheduleTfjsDestroy();
        return response as Extract<WorkerResponse, { type: 'ddsp-result' }>;
    },

    async releaseOnnxSession(modelId: string): Promise<void> {
        if (!workerState.onnx.worker) {
            return;
        }
        const request: WorkerRequest = { type: 'release-session', modelId };
        workerState.onnx.worker.postMessage(request);
    },

    async releaseDdspSession(modelId: string): Promise<void> {
        if (!workerState.tfjs.worker) {
            return;
        }
        const request: WorkerRequest = { type: 'release-session', modelId };
        workerState.tfjs.worker.postMessage(request);
        scheduleTfjsDestroy();
    },

    /**
     * Terminate the ONNX worker immediately, rejecting all in-flight requests.
     * The worker is respawned automatically on the next inference call.
     * Used by cancelRender to stop DiffSinger/Kokoro inference mid-flight.
     */
    terminateOnnxWorker(): void {
        for (const { reject } of workerState.onnx.pendingRequests.values()) {
            reject(new Error('Render cancelled'));
        }
        workerState.onnx.pendingRequests.clear();
        if (workerState.onnx.worker) {
            workerState.onnx.worker.terminate();
            workerState.onnx.worker = null;
            workerState.onnx.initialized = false;
        }
    },

    /**
     * Terminate the TF.js worker immediately, rejecting all in-flight requests.
     * Used by cancelRender to stop DDSP inference mid-flight.
     */
    terminateTfjsWorker(): void {
        for (const { reject } of workerState.tfjs.pendingRequests.values()) {
            reject(new Error('Render cancelled'));
        }
        workerState.tfjs.pendingRequests.clear();
        if (workerState.tfjs.worker) {
            workerState.tfjs.worker.terminate();
            workerState.tfjs.worker = null;
            workerState.tfjs.initialized = false;
        }
        if (workerState.tfjsIdleTimer !== null) {
            clearTimeout(workerState.tfjsIdleTimer);
            workerState.tfjsIdleTimer = null;
        }
    },

    terminateAll(): void {
        inferenceWorkerBridge.terminateOnnxWorker();
        inferenceWorkerBridge.terminateTfjsWorker();
    },
};

/**
 * Repository: OPFS storage manager for model files.
 *
 * Handles reading, writing, and deleting model files in OPFS.
 * OPFS provides 2-4x faster reads than IndexedDB via synchronous
 * access handles in Web Workers.
 *
 * All path operations use a flat directory scheme:
 *   models/<family>/<model-id>.bin
 *   renders/<cache-key>.pcm
 */

import { inject } from '#/infra/di/inject';
import { logger } from '#/infra/logger/appLogger';

import { type StorageStatus, DEFAULT_CACHE_LIMIT_BYTES } from '../models/StorageStatus';

type ModelPath = {
    family: string;
    modelId: string;
};

function toOpfsPath({ family, modelId }: ModelPath): string {
    return `${family}/${modelId}`;
}

/**
 * Resolve an OPFS file handle for a model.
 * Creates intermediate directories as needed.
 */
async function resolveFileHandle(
    opfsRoot: FileSystemDirectoryHandle,
    relativePath: string,
    options: { create: boolean }
): Promise<FileSystemFileHandle> {
    const parts = relativePath.split('/');
    const fileName = parts.pop()!;
    let dir = opfsRoot;
    for (const part of parts) {
        dir = await dir.getDirectoryHandle(part, { create: options.create });
    }
    return dir.getFileHandle(fileName, { create: options.create });
}

type CheckModelCachedInput = { family: string; modelId: string };
type CheckModelCachedOutput = Promise<boolean>;

type ReadModelInput = { family: string; modelId: string };
type ReadModelOutput = Promise<ArrayBuffer | null>;

type WriteModelInput = { family: string; modelId: string; data: ArrayBuffer };
type WriteModelOutput = Promise<void>;

type DeleteModelInput = { family: string; modelId: string };
type DeleteModelOutput = Promise<void>;

type ReadRenderCacheInput = { cacheKey: string };
type ReadRenderCacheOutput = Promise<Float32Array | null>;

type WriteRenderCacheInput = { cacheKey: string; audio: Float32Array };
type WriteRenderCacheOutput = Promise<void>;

type GetStorageStatusOutput = Promise<StorageStatus>;

export const checkModelCached = inject({ logger })(
    ({ logger }) =>
        async function checkModelCached({ family, modelId }: CheckModelCachedInput): CheckModelCachedOutput {
            try {
                const root = await navigator.storage.getDirectory();
                const modelsDir = await root.getDirectoryHandle('models', { create: false }).catch(() => null);
                if (!modelsDir) {
                    return false;
                }
                const path = toOpfsPath({ family, modelId });
                const parts = path.split('/');
                const fileName = parts.pop()!;
                let dir: FileSystemDirectoryHandle = modelsDir;
                for (const part of parts) {
                    const next = await dir.getDirectoryHandle(part, { create: false }).catch(() => null);
                    if (!next) {
                        return false;
                    }
                    dir = next;
                }
                await dir.getFileHandle(fileName, { create: false });
                return true;
            } catch {
                logger.info(`[StorageManager] Model not cached: ${family}/${modelId}`);
                return false;
            }
        }
);

export const readModel = inject({ logger })(
    ({ logger }) =>
        async function readModel({ family, modelId }: ReadModelInput): ReadModelOutput {
            try {
                const root = await navigator.storage.getDirectory();
                const modelsDir = await root.getDirectoryHandle('models', { create: false });
                const fileHandle = await resolveFileHandle(modelsDir, toOpfsPath({ family, modelId }), {
                    create: false,
                });
                const file = await fileHandle.getFile();
                return file.arrayBuffer();
            } catch (error) {
                logger.warn(`[StorageManager] Failed to read model ${family}/${modelId}: ${String(error)}`);
                return null;
            }
        }
);

export const writeModel = inject({ logger })(
    ({ logger }) =>
        async function writeModel({ family, modelId, data }: WriteModelInput): WriteModelOutput {
            const root = await navigator.storage.getDirectory();
            const modelsDir = await root.getDirectoryHandle('models', { create: true });
            const fileHandle = await resolveFileHandle(modelsDir, toOpfsPath({ family, modelId }), { create: true });
            // Use createWritable for main-thread writes (no sync access handles on main thread)
            // slice(0) ensures we have a plain ArrayBuffer (not SharedArrayBuffer)
            const safeData = data.slice(0);
            const writable = await fileHandle.createWritable();
            await writable.write(safeData);
            await writable.close();
            logger.info(`[StorageManager] Wrote model ${family}/${modelId} (${String(data.byteLength)} bytes)`);
        }
);

export const deleteModel = inject({ logger })(
    ({ logger }) =>
        async function deleteModel({ family, modelId }: DeleteModelInput): DeleteModelOutput {
            try {
                const root = await navigator.storage.getDirectory();
                const modelsDir = await root.getDirectoryHandle('models', { create: false });
                const familyDir = await modelsDir.getDirectoryHandle(family, { create: false });
                await familyDir.removeEntry(modelId);
                logger.info(`[StorageManager] Deleted model ${family}/${modelId}`);
            } catch (error) {
                logger.warn(`[StorageManager] Failed to delete model ${family}/${modelId}: ${String(error)}`);
            }
        }
);

export const readRenderCache = inject({ logger })(
    ({ logger: _logger }) =>
        async function readRenderCache({ cacheKey }: ReadRenderCacheInput): ReadRenderCacheOutput {
            try {
                const root = await navigator.storage.getDirectory();
                const cacheDir = await root.getDirectoryHandle('renders', { create: false });
                const fileHandle = await cacheDir.getFileHandle(`${cacheKey}.pcm`, { create: false });
                const file = await fileHandle.getFile();
                const buffer = await file.arrayBuffer();
                return new Float32Array(buffer);
            } catch {
                return null;
            }
        }
);

export const writeRenderCache = inject({ logger })(
    ({ logger }) =>
        async function writeRenderCache({ cacheKey, audio }: WriteRenderCacheInput): WriteRenderCacheOutput {
            try {
                const root = await navigator.storage.getDirectory();
                const cacheDir = await root.getDirectoryHandle('renders', { create: true });
                const fileHandle = await cacheDir.getFileHandle(`${cacheKey}.pcm`, { create: true });
                const writable = await fileHandle.createWritable();
                // Use ArrayBuffer explicitly for FileSystemWritableFileStream compatibility
                const buffer = audio.buffer.slice(0) as ArrayBuffer;
                await writable.write(buffer);
                await writable.close();
                logger.info(`[StorageManager] Cached render: ${cacheKey}`);
            } catch (error) {
                logger.warn(`[StorageManager] Failed to cache render ${cacheKey}: ${String(error)}`);
            }
        }
);

/**
 * Compute total OPFS usage and return storage status.
 */
export const getStorageStatus = inject({ logger })(
    ({ logger }) =>
        async function getStorageStatus(): GetStorageStatusOutput {
            let usedBytes = 0;

            try {
                const root = await navigator.storage.getDirectory();

                async function measureDir(dir: FileSystemDirectoryHandle): Promise<number> {
                    let size = 0;
                    // FileSystemDirectoryHandle is async iterable in Chrome (OPFS)
                    for await (const [, handle] of dir as unknown as AsyncIterable<
                        [string, FileSystemFileHandle | FileSystemDirectoryHandle]
                    >) {
                        if (handle.kind === 'file') {
                            const file = await handle.getFile();
                            size += file.size;
                        } else if (handle.kind === 'directory') {
                            size += await measureDir(handle);
                        }
                    }
                    return size;
                }

                usedBytes = await measureDir(root);
            } catch (error) {
                logger.warn(`[StorageManager] Failed to measure storage: ${String(error)}`);
            }

            let availableBytes: number | null = null;
            let persisted = false;

            try {
                const estimate = await navigator.storage.estimate();
                availableBytes = (estimate.quota ?? 0) - (estimate.usage ?? 0);
            } catch {
                // storage.estimate() not available
            }

            try {
                persisted = await navigator.storage.persisted();
            } catch {
                // storage.persisted() not available
            }

            return {
                usedBytes,
                limitBytes: DEFAULT_CACHE_LIMIT_BYTES,
                persisted,
                availableBytes,
            };
        }
);

/**
 * Request persistent storage to prevent eviction under memory pressure.
 */
export async function requestPersistentStorage(): Promise<boolean> {
    try {
        return await navigator.storage.persist();
    } catch {
        return false;
    }
}

/**
 * Compute a deterministic SHA256 cache key for a render.
 */
export async function computeRenderCacheKey(input: {
    modelId: string;
    inputData: ArrayBuffer;
    qualityParams: string;
    seed?: number;
}): Promise<string> {
    const encoded = new TextEncoder().encode(`${input.modelId}:${input.qualityParams}:${String(input.seed ?? 0)}`);
    const combined = new Uint8Array(encoded.byteLength + input.inputData.byteLength);
    combined.set(encoded);
    combined.set(new Uint8Array(input.inputData), encoded.byteLength);

    const hashBuffer = await crypto.subtle.digest('SHA-256', combined.buffer);
    const hashArray = Array.from(new Uint8Array(hashBuffer));
    return hashArray.map((b) => b.toString(16).padStart(2, '0')).join('');
}

/**
 * Download Worker — handles background model downloads.
 *
 * Executed as a Service Worker or dedicated worker for large model downloads.
 * Uses Background Fetch API where available (Chrome, survives tab navigation).
 * Falls back to standard fetch with progress streaming.
 *
 * Communicates download progress via BroadcastChannel so all tabs can receive updates.
 */

const BROADCAST_CHANNEL_NAME = 'sourdaw-model-downloads';

type DownloadRequest = {
    type: 'download';
    modelId: string;
    url: string;
    sha256?: string;
    /** File path within OPFS (e.g. 'models/ddsp/violin.onnx') */
    opfsPath: string;
};

type DownloadResponse =
    | { type: 'progress'; modelId: string; bytesDownloaded: number; totalBytes: number }
    | { type: 'complete'; modelId: string }
    | { type: 'error'; modelId: string; error: string }
    | { type: 'integrity-error'; modelId: string };

let broadcastChannel: BroadcastChannel | null = null;

function getBroadcastChannel(): BroadcastChannel {
    if (!broadcastChannel) {
        broadcastChannel = new BroadcastChannel(BROADCAST_CHANNEL_NAME);
    }
    return broadcastChannel;
}

function broadcast(msg: DownloadResponse): void {
    getBroadcastChannel().postMessage(msg);
    // Also post to the worker's own message port for direct subscribers
    self.postMessage(msg);
}

/**
 * Write downloaded data to OPFS.
 */
async function writeToOpfs(opfsPath: string, data: ArrayBuffer): Promise<void> {
    const root = await navigator.storage.getDirectory();
    const parts = opfsPath.split('/');
    const fileName = parts.pop()!;
    let dir = root;
    for (const part of parts) {
        dir = await dir.getDirectoryHandle(part, { create: true });
    }
    const fileHandle = await dir.getFileHandle(fileName, { create: true });
    const accessHandle = await fileHandle.createSyncAccessHandle();
    accessHandle.write(data);
    accessHandle.flush();
    accessHandle.close();
}

/**
 * Verify SHA256 integrity of downloaded data.
 */
async function verifySha256(data: ArrayBuffer, expectedHash: string): Promise<boolean> {
    const hashBuffer = await crypto.subtle.digest('SHA-256', data);
    const hashArray = Array.from(new Uint8Array(hashBuffer));
    const hashHex = hashArray.map((b) => b.toString(16).padStart(2, '0')).join('');
    return hashHex === expectedHash;
}

/**
 * Download a model file with progress reporting and retry logic.
 * Uses Background Fetch API where available, falls back to standard fetch.
 */
async function downloadModel(req: DownloadRequest): Promise<void> {
    const maxRetries = 3;
    let lastError: unknown;

    for (let attempt = 0; attempt < maxRetries; attempt++) {
        try {
            // Try Background Fetch API first (survives tab navigation, OS-level progress)
            if ('BackgroundFetchManager' in self && attempt === 0) {
                // Background Fetch requires Service Worker context — skip in dedicated worker
            }

            // Standard fetch with progress streaming
            const response = await fetch(req.url);

            if (!response.ok) {
                throw new Error(`HTTP ${String(response.status)}: ${response.statusText}`);
            }

            const contentLength = response.headers.get('content-length');
            const totalBytes = contentLength ? parseInt(contentLength, 10) : 0;

            const reader = response.body?.getReader();
            if (!reader) {
                throw new Error('Response body is not readable');
            }

            const chunks: Uint8Array[] = [];
            let bytesDownloaded = 0;

            for (;;) {
                const { done, value } = await reader.read();
                if (done) {
                    break;
                }
                chunks.push(value);
                bytesDownloaded += value.byteLength;
                broadcast({ type: 'progress', modelId: req.modelId, bytesDownloaded, totalBytes });
            }

            // Concatenate all chunks
            const totalLength = chunks.reduce((acc, context) => acc + context.byteLength, 0);
            const fullData = new Uint8Array(totalLength);
            let offset = 0;
            for (const chunk of chunks) {
                fullData.set(chunk, offset);
                offset += chunk.byteLength;
            }

            // Verify integrity if SHA256 provided — throw so the retry loop catches it
            if (req.sha256) {
                const valid = await verifySha256(fullData.buffer, req.sha256);
                if (!valid) {
                    throw new Error(`SHA256 integrity check failed for ${req.modelId}`);
                }
            }

            // Store in OPFS
            await writeToOpfs(req.opfsPath, fullData.buffer);

            broadcast({ type: 'complete', modelId: req.modelId });
            return;
        } catch (error) {
            lastError = error;
            if (attempt < maxRetries - 1) {
                // Exponential backoff: 1s, 2s, 4s
                await new Promise<void>((resolve) => setTimeout(resolve, 1000 * 2 ** attempt));
            }
        }
    }

    broadcast({ type: 'error', modelId: req.modelId, error: String(lastError) });
}

self.onmessage = async (event: MessageEvent<DownloadRequest>): Promise<void> => {
    const req = event.data;
    if (req.type === 'download') {
        await downloadModel(req);
    }
};

/**
 * ONNX Inference Worker — handles DiffSinger and Kokoro TTS via onnxruntime-web.
 *
 * Bundled as a separate chunk by Vite via the `?worker` import in inferenceWorkerBridge.ts.
 * Always initialized when browser AI features are active.
 *
 * Design:
 * - ONNX sessions are created per model and cached by modelId
 * - LRU eviction applied when total weight memory exceeds 1 GB
 * - Progress events emitted per pipeline stage
 * - Audio buffers transferred via Transferable (zero-copy)
 */

import type { WorkerRequest, WorkerResponse, TensorData } from '../models/InferenceRequest';

// ── Types ──────────────────────────────────────────────────────────────────

type OrtInferenceSession = {
    run: (
        feeds: Record<string, OrtTensor>
    ) => Promise<Record<string, { data: Float32Array | BigInt64Array; dims: number[] }>>;
    release: () => Promise<void>;
};

type OrtTensor = {
    data: Float32Array | BigInt64Array | Int32Array | Uint8Array;
    dims: number[];
};

type OrtModule = {
    InferenceSession: {
        create: (data: ArrayBuffer, options?: { executionProviders?: string[] }) => Promise<OrtInferenceSession>;
    };
    Tensor: new (
        type: string,
        data: ArrayBuffer | Float32Array | BigInt64Array | Int32Array | Uint8Array,
        dims: number[]
    ) => OrtTensor;
    env: { wasm: { numThreads: number }; logLevel: string };
};

type SessionEntry = {
    session: OrtInferenceSession;
    modelId: string;
    sizeBytes: number;
    lastUsedAt: number;
};

// ── Session manager ────────────────────────────────────────────────────────

const SESSION_MEMORY_BUDGET = 1024 * 1024 * 1024; // 1 GB

const sessionCache: Map<string, SessionEntry> = new Map();
let totalMemoryBytes = 0;
let ortModule: OrtModule | null = null;

async function getOrt(): Promise<OrtModule> {
    if (ortModule) {
        return ortModule;
    }
    // Dynamic import keeps onnxruntime-web out of the main bundle
    const ort = (await import('onnxruntime-web')) as unknown as OrtModule;
    // Multi-threaded WASM requires SharedArrayBuffer which is only available
    // when crossOriginIsolated is true. IIFE workers (forced by Rolldown)
    // are not cross-origin isolated, so fall back to single-threaded.
    ort.env.wasm.numThreads =
        typeof crossOriginIsolated !== 'undefined' && crossOriginIsolated ? (navigator.hardwareConcurrency ?? 4) : 1;
    // Suppress "Some nodes were not assigned to the preferred execution providers"
    // warnings — these are informational (ORT moves shape ops to CPU intentionally).
    ort.env.logLevel = 'error';
    ortModule = ort;
    return ort;
}

function selectExecutionProviders(): string[] {
    if (typeof navigator !== 'undefined' && 'gpu' in navigator) {
        return ['webgpu', 'wasm'];
    }
    // Safety net — feature should have been disabled at the UI level
    console.warn('[OnnxWorker] WebGPU unavailable — falling back to WASM only');
    return ['wasm'];
}

async function evictLru(): Promise<void> {
    while (totalMemoryBytes > SESSION_MEMORY_BUDGET && sessionCache.size > 0) {
        let oldest: [string, SessionEntry] | null = null;
        for (const entry of sessionCache.entries()) {
            if (!oldest || entry[1].lastUsedAt < oldest[1].lastUsedAt) {
                oldest = entry;
            }
        }
        if (!oldest) {
            break;
        }
        const [id, entry] = oldest;
        await entry.session.release();
        totalMemoryBytes -= entry.sizeBytes;
        sessionCache.delete(id);
    }
}

async function getOrCreateSession(modelId: string, modelData: ArrayBuffer): Promise<OrtInferenceSession> {
    const cached = sessionCache.get(modelId);
    if (cached) {
        cached.lastUsedAt = Date.now();
        return cached.session;
    }

    const ort = await getOrt();
    const providers = selectExecutionProviders();
    const session = await ort.InferenceSession.create(modelData, { executionProviders: providers });

    const entry: SessionEntry = {
        session,
        modelId,
        sizeBytes: modelData.byteLength,
        lastUsedAt: Date.now(),
    };
    sessionCache.set(modelId, entry);
    totalMemoryBytes += modelData.byteLength;

    await evictLru();
    return session;
}

// ── Tensor helpers ─────────────────────────────────────────────────────────

function tensorDataToOrt(ort: OrtModule, td: TensorData): OrtTensor {
    const type = (() => {
        if (td.type === 'int64') {
            return 'int64';
        } else {
            if (td.type === 'int32') {
                return 'int32';
            } else {
                if (td.type === 'bool') {
                    return 'bool';
                } else {
                    return 'float32';
                }
            }
        }
    })();
    return new ort.Tensor(type, td.data, td.dims);
}

// ── DiffSinger pipeline ───────────────────────────────────────────────────

type DiffSingerSessions = {
    linguistic: OrtInferenceSession;
    dur: OrtInferenceSession;
    pitch: OrtInferenceSession;
    variance: OrtInferenceSession;
    acoustic: OrtInferenceSession;
    vocoder: OrtInferenceSession;
};

/**
 * Broadcast a 256-dim speaker embedding to [1, nFrames, 256] for acoustic/pitch/variance models.
 * DiffSinger models expect a per-frame speaker embedding; we tile the single 256-dim vector.
 */
function broadcastSpkEmbed(ort: OrtModule, embed: Float32Array, nFrames: number): OrtTensor {
    const tiled = new Float32Array(nFrames * 256);
    for (let freq = 0; freq < nFrames; freq++) {
        tiled.set(embed, freq * 256);
    }
    return new ort.Tensor('float32', tiled, [1, nFrames, 256]);
}

/**
 * Run the full DiffSinger browser SVS pipeline.
 * Steps: linguistic → duration → pitch → variance → acoustic (diffusion) → vocoder
 */
async function runDiffSingerPipeline(
    requestId: string,
    sessions: DiffSingerSessions,
    ort: OrtModule,
    params: Extract<WorkerRequest, { type: 'run-diffsinger-phrase' }>
): Promise<Float32Array> {
    const post = (stage: string, progress: number): void => {
        const msg: WorkerResponse = { type: 'inference-progress', requestId, stage, progress };
        self.postMessage(msg);
    };

    // ── 1. Linguistic encoder ──────────────────────────────────────────────
    post('Encoding phonemes', 0.05);
    const nTokens = params.tokenIds.length;
    const nWords = params.wordDiv.length;

    const tokens = new ort.Tensor('int64', BigInt64Array.from(params.tokenIds.map(BigInt)), [1, nTokens]);
    const wordDiv = new ort.Tensor('int64', BigInt64Array.from(params.wordDiv.map(BigInt)), [1, nWords]);
    const wordDur = new ort.Tensor('int64', BigInt64Array.from(params.wordDur.map(BigInt)), [1, nWords]);

    const linguisticOut = await sessions.linguistic.run({ tokens, word_div: wordDiv, word_dur: wordDur });
    const encoderOut = linguisticOut.encoder_out;
    const xMasks = linguisticOut.x_masks;
    post('Encoding phonemes', 0.15);

    // ── 2. Duration predictor ──────────────────────────────────────────────
    post('Predicting durations', 0.2);
    const noteMidi = new ort.Tensor('float32', params.noteMidi, [1, params.noteMidi.length]);
    const noteDur = new ort.Tensor('int64', params.noteDur, [1, params.noteDur.length]);

    const durFeeds: Record<string, OrtTensor> = {
        encoder_out: encoderOut as unknown as OrtTensor,
        x_masks: xMasks as unknown as OrtTensor,
        note_midi: noteMidi,
        note_dur: noteDur,
    };
    if (params.speakerEmbed) {
        durFeeds.spk_embed = broadcastSpkEmbed(ort, params.speakerEmbed, nTokens);
    }

    const durOut = await sessions.dur.run(durFeeds);
    const phDur = durOut.ph_dur;
    if (!phDur) {
        throw new Error('Duration predictor produced no ph_dur output');
    }
    post('Predicting durations', 0.3);

    // ── 3. Pitch predictor ─────────────────────────────────────────────────
    post('Predicting pitch', 0.35);
    const pitchPlaceholder = new ort.Tensor('float32', new Float32Array(params.durationFrames), [
        1,
        params.durationFrames,
    ]);
    // retake = all true → predict all tokens fresh (not retaining any previous pitch)
    const retakePitch = new ort.Tensor('bool', new Uint8Array(nTokens).fill(1), [1, nTokens]);
    const steps = new ort.Tensor('int64', BigInt64Array.from([BigInt(params.steps)]), [1]);

    const pitchFeeds: Record<string, OrtTensor> = {
        encoder_out: encoderOut as unknown as OrtTensor,
        ph_dur: phDur as unknown as OrtTensor,
        note_midi: noteMidi,
        note_dur: noteDur,
        pitch: pitchPlaceholder,
        retake: retakePitch,
        steps,
    };
    if (params.speakerEmbed) {
        pitchFeeds.spk_embed = broadcastSpkEmbed(ort, params.speakerEmbed, params.durationFrames);
    }

    const pitchOut = await sessions.pitch.run(pitchFeeds);
    const pitchPred = pitchOut.pitch_pred;
    post('Predicting pitch', 0.5);

    // ── 4. Variance predictor ──────────────────────────────────────────────
    post('Predicting expression', 0.55);
    const retakeVariance = new ort.Tensor('bool', new Uint8Array(nTokens).fill(1), [1, nTokens]);
    const varianceFeeds: Record<string, OrtTensor> = {
        encoder_out: encoderOut as unknown as OrtTensor,
        x_masks: xMasks as unknown as OrtTensor,
        ph_dur: phDur as unknown as OrtTensor,
        pitch: pitchPred as unknown as OrtTensor,
        retake: retakeVariance,
        steps,
    };
    if (params.speakerEmbed) {
        varianceFeeds.spk_embed = broadcastSpkEmbed(ort, params.speakerEmbed, params.durationFrames);
    }

    const varianceOut = await sessions.variance.run(varianceFeeds);
    const energyPred = varianceOut.energy_pred;
    const breathinessPred = varianceOut.breathiness_pred;
    post('Predicting expression', 0.65);

    // ── 5. Acoustic model (shallow diffusion) ─────────────────────────────
    post('Rendering mel-spectrogram', 0.68);
    const depthTensor = new ort.Tensor('float32', new Float32Array([params.depth]), [1]);

    const acousticFeeds: Record<string, OrtTensor> = {
        tokens,
        durations: phDur as unknown as OrtTensor,
        f0: pitchPred as unknown as OrtTensor,
        depth: depthTensor,
        steps,
    };
    if (energyPred) {
        acousticFeeds.energy = energyPred as unknown as OrtTensor;
    }
    if (breathinessPred) {
        acousticFeeds.breathiness = breathinessPred as unknown as OrtTensor;
    }
    if (params.speakerEmbed) {
        acousticFeeds.spk_embed = broadcastSpkEmbed(ort, params.speakerEmbed, params.durationFrames);
    }

    // The acoustic model runs all diffusion steps internally via the `steps` tensor.
    const acousticOut = await sessions.acoustic.run(acousticFeeds);
    // Key may vary by ONNX export ('mel' is conventional, but some exports use other names)
    const mel = acousticOut.mel ?? Object.values(acousticOut)[0];
    if (!mel) {
        throw new Error('Acoustic model produced no mel-spectrogram output');
    }
    post('Rendering mel-spectrogram', 0.82);

    // ── 6. Vocoder ─────────────────────────────────────────────────────────
    post('Running vocoder', 0.87);
    const vocoderOut = await sessions.vocoder.run({
        mel: mel as unknown as OrtTensor,
        f0: pitchPred as unknown as OrtTensor,
    });
    const waveform = vocoderOut.waveform;
    post('Running vocoder', 0.98);

    if (!waveform) {
        throw new Error('Vocoder produced no waveform output');
    }
    return new Float32Array(waveform.data as Float32Array);
}

// ── Kokoro TTS via onnxruntime-web ────────────────────────────────────────

const KOKORO_SESSION_ID = 'kokoro-82m-q8';

/**
 * Run Kokoro TTS inference using the pre-loaded ONNX session.
 * Inputs are prepared on the main thread (tokenization + voice embedding selection)
 * and transferred to this worker as typed arrays.
 *
 * Model inputs:
 *   input_ids  int64[1, seq_len]  — phoneme token IDs with 0-padding at both ends
 *   style      float32[1, 256]    — voice style embedding (indexed by token count)
 *   speed      float32[1]         — speed multiplier
 *
 * Output: float32 audio at 24 kHz.
 */
async function runKokoroOnnx(
    requestId: string,
    inputIds: BigInt64Array,
    style: Float32Array,
    speed: number
): Promise<Float32Array> {
    const ort = await getOrt();
    const session = sessionCache.get(KOKORO_SESSION_ID)?.session;
    if (!session) {
        throw new Error('Kokoro ONNX session not loaded — call create-session with modelId="kokoro-82m-q8" first');
    }

    const post = (stage: string, progress: number): void => {
        const msg: WorkerResponse = { type: 'inference-progress', requestId, stage, progress };
        self.postMessage(msg);
    };

    post('Synthesizing speech', 0.2);

    const seqLen = inputIds.length;
    const inputIdsTensor = new ort.Tensor('int64', inputIds, [1, seqLen]);
    const styleTensor = new ort.Tensor('float32', style, [1, 256]);
    const speedTensor = new ort.Tensor('float32', new Float32Array([speed]), [1]);

    const outputs = await session.run({
        input_ids: inputIdsTensor,
        style: styleTensor,
        speed: speedTensor,
    });

    post('Synthesizing speech', 0.95);

    // The model outputs a waveform tensor — key may vary by export
    const waveform = outputs.waveform ?? outputs.audio ?? Object.values(outputs)[0];
    if (!waveform) {
        throw new Error('Kokoro ONNX produced no output');
    }

    return new Float32Array(waveform.data as Float32Array);
}

// ── Message handler ────────────────────────────────────────────────────────

self.onmessage = async (event: MessageEvent<WorkerRequest>): Promise<void> => {
    const req = event.data;

    if (req.type === 'create-session') {
        try {
            await getOrCreateSession(req.modelId, req.modelData);
            const response: WorkerResponse = {
                type: 'session-created',
                requestId: req.requestId,
                modelId: req.modelId,
            };
            self.postMessage(response);
        } catch (error) {
            const response: WorkerResponse = { type: 'error', requestId: req.requestId, error: String(error) };
            self.postMessage(response);
        }
        return;
    }

    if (req.type === 'run-inference') {
        const entry = sessionCache.get(req.modelId);
        if (!entry) {
            const response: WorkerResponse = {
                type: 'error',
                requestId: req.requestId,
                error: `Session not found: ${req.modelId}`,
            };
            self.postMessage(response);
            return;
        }
        try {
            const ort = await getOrt();
            entry.lastUsedAt = Date.now();
            const feeds: Record<string, OrtTensor> = {};
            for (const [key, td] of Object.entries(req.feeds)) {
                feeds[key] = tensorDataToOrt(ort, td);
            }
            const outputs = await entry.session.run(feeds);
            const resultOutputs: Record<string, TensorData> = {};
            for (const [key, val] of Object.entries(outputs)) {
                let dataType: TensorData['type'] = 'float32';
                if (val.data instanceof BigInt64Array) {
                    dataType = 'int64';
                } else if (val.data instanceof Int32Array) {
                    dataType = 'int32';
                } else if (val.data instanceof Uint8Array) {
                    dataType = 'bool';
                }
                resultOutputs[key] = { data: val.data as Float32Array, dims: val.dims, type: dataType };
            }
            const response: WorkerResponse = {
                type: 'inference-result',
                requestId: req.requestId,
                outputs: resultOutputs,
            };
            self.postMessage(response);
        } catch (error) {
            const response: WorkerResponse = { type: 'error', requestId: req.requestId, error: String(error) };
            self.postMessage(response);
        }
        return;
    }

    if (req.type === 'release-session') {
        const entry = sessionCache.get(req.modelId);
        if (entry) {
            await entry.session.release();
            totalMemoryBytes -= entry.sizeBytes;
            sessionCache.delete(req.modelId);
        }
        return;
    }

    if (req.type === 'get-status') {
        const response: WorkerResponse = {
            type: 'status',
            loadedModels: Array.from(sessionCache.keys()),
            memoryUsageBytes: totalMemoryBytes,
        };
        self.postMessage(response);
        return;
    }

    if (req.type === 'run-kokoro-tts') {
        try {
            const progressMsg: WorkerResponse = {
                type: 'inference-progress',
                requestId: req.requestId,
                stage: 'Synthesizing speech',
                progress: 0.1,
            };
            self.postMessage(progressMsg);

            const audio = await runKokoroOnnx(req.requestId, req.inputIds, req.style, req.speed);
            const response: WorkerResponse = {
                type: 'tts-result',
                requestId: req.requestId,
                audio,
                // Kokoro ONNX outputs 24 kHz PCM
                samplingRate: 24000,
            };
            self.postMessage(response, [audio.buffer]);
        } catch (error) {
            const response: WorkerResponse = { type: 'error', requestId: req.requestId, error: String(error) };
            self.postMessage(response);
        }
        return;
    }

    if (req.type === 'run-diffsinger-phrase') {
        try {
            const progressMsg: WorkerResponse = {
                type: 'inference-progress',
                requestId: req.requestId,
                stage: 'Preparing sessions',
                progress: 0.02,
            };
            self.postMessage(progressMsg);

            // All sessions must have been pre-loaded via 'create-session' messages
            const linguisticKey = `${req.voicebankId}/linguistic`;
            const durKey = `${req.voicebankId}/dur`;
            const pitchKey = `${req.voicebankId}/pitch`;
            const varianceKey = `${req.voicebankId}/variance`;
            const acousticKey = `${req.voicebankId}/acoustic`;
            const vocoderKey = 'shared/vocoder';

            const sessions = {
                linguistic: sessionCache.get(linguisticKey)?.session,
                dur: sessionCache.get(durKey)?.session,
                pitch: sessionCache.get(pitchKey)?.session,
                variance: sessionCache.get(varianceKey)?.session,
                acoustic: sessionCache.get(acousticKey)?.session,
                vocoder: sessionCache.get(vocoderKey)?.session,
            };

            if (
                !sessions.linguistic ||
                !sessions.dur ||
                !sessions.pitch ||
                !sessions.variance ||
                !sessions.acoustic ||
                !sessions.vocoder
            ) {
                const missing = Object.entries(sessions)
                    .filter(([, state]) => !state)
                    .map(([kIndex]) => kIndex)
                    .join(', ');
                throw new Error(`DiffSinger sessions not loaded: ${missing}`);
            }

            const ort = await getOrt();
            const audio = await runDiffSingerPipeline(req.requestId, sessions as DiffSingerSessions, ort, req);

            const response: WorkerResponse = {
                type: 'diffsinger-result',
                requestId: req.requestId,
                audio,
            };
            self.postMessage(response, [audio.buffer]);
        } catch (error) {
            const response: WorkerResponse = { type: 'error', requestId: req.requestId, error: String(error) };
            self.postMessage(response);
        }
        return;
    }
};

