import { type ReactElement, type KeyboardEvent, useState, useEffect, useRef } from 'react';

import { DawKeycap } from '#/components/daw/DawKeycap';
import { Dialog, DialogContent, DialogTitle } from '#/components/ui/dialog';
import { Input } from '#/components/ui/input';
import { useStore } from '#/infra/store/useStore';
import { workspaceStore } from '#/modules/Workspace/stores';
import { closeCommandPalette, type WorkspaceState } from '#/modules/Workspace/useCases';
import { cn } from '#/utils/Styles/cn';

import { searchCommands, type CommandEntry } from '../../models/CommandRegistry';
import { executeAppAction } from '../../useCases/executeAppAction';

export const CommandPalette = (): ReactElement | null => {
    const commandPaletteOpen = useStore(workspaceStore, null as unknown as WorkspaceState)?.commandPaletteOpen ?? false;
    const [query, setQuery] = useState('');
    const [selectedIndex, setSelectedIndex] = useState(0);
    const inputRef = useRef<HTMLInputElement>(null);

    const results = searchCommands(query);

    useEffect(() => {
        setSelectedIndex(0);
    }, [query]);

    useEffect(() => {
        if (commandPaletteOpen) {
            setQuery('');
            setSelectedIndex(0);
        }
    }, [commandPaletteOpen]);

    const close = closeCommandPalette;

    const execute = (entry: CommandEntry) => {
        close();
        if (typeof entry.action === 'function') {
            entry.action();
        } else {
            void executeAppAction(entry.action);
        }
    };

    const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
        if (event.key === 'ArrowDown') {
            event.preventDefault();
            setSelectedIndex((index) => Math.min(index + 1, results.length - 1));
        } else if (event.key === 'ArrowUp') {
            event.preventDefault();
            setSelectedIndex((index) => Math.max(index - 1, 0));
        } else if (event.key === 'Enter' && results[selectedIndex]) {
            event.preventDefault();
            execute(results[selectedIndex]);
        }
    };

    return (
        <Dialog
            open={commandPaletteOpen}
            onOpenChange={(open) => {
                if (!open) {
                    close();
                }
            }}
        >
            <DialogContent className="max-w-md gap-0 overflow-hidden p-0" aria-describedby={undefined}>
                <DialogTitle className="sr-only">Command Palette</DialogTitle>
                <div className="daw-header-band flex items-center rounded-t-lg px-3">
                    <span className="text-sm text-muted-foreground mr-2">&gt;</span>
                    <Input
                        ref={inputRef}
                        value={query}
                        onChange={(event) => setQuery(event.target.value)}
                        onKeyDown={handleKeyDown}
                        placeholder="Type a command..."
                        className="h-12 border-0 bg-transparent shadow-none focus-visible:ring-0 text-base"
                        autoFocus
                    />
                </div>

                <div className="max-h-72 overflow-y-auto bg-surface-base py-1" role="listbox">
                    {results.map((cmd, index) => (
                        <button
                            type="button"
                            key={cmd.id}
                            role="option"
                            aria-selected={index === selectedIndex}
                            className={cn(
                                'flex w-full items-center justify-between px-4 py-3 text-left text-sm transition-colors border-l-2',
                                index === selectedIndex
                                    ? 'bg-accent/80 border-primary shadow-[inset_0_1px_0_0_rgba(255,255,255,0.05)]'
                                    : 'border-transparent text-muted-foreground hover:bg-surface-overlay/50'
                            )}
                            onClick={() => execute(cmd)}
                            onMouseEnter={() => setSelectedIndex(index)}
                        >
                            <div>
                                <span className="text-foreground">{cmd.label}</span>
                                <span className="ml-2 text-xs text-muted-foreground">{cmd.description}</span>
                            </div>
                            {cmd.shortcut ? (
                                <DawKeycap compact className="bg-muted">
                                    {cmd.shortcut}
                                </DawKeycap>
                            ) : null}
                        </button>
                    ))}

                    {results.length === 0 ? (
                        <p className="px-3 py-4 text-center text-sm text-muted-foreground">No commands found</p>
                    ) : null}
                </div>
            </DialogContent>
        </Dialog>
    );
};

import { type ReactElement } from 'react';

import { X, Undo2, Redo2 } from 'lucide-react';

import { DawEmptyState } from '#/components/daw/DawEmptyState';
import { DawEyebrowLabel } from '#/components/daw/DawEyebrowLabel';
import { DawHeaderBand } from '#/components/daw/DawHeaderBand';
import { DawMicroBadge } from '#/components/daw/DawMicroBadge';
import { DawUtilityListRow } from '#/components/daw/DawUtilityListRow';
import { DawUtilityPanel } from '#/components/daw/DawUtilityPanel';
import { Button } from '#/components/ui/button';
import { useStore } from '#/infra/store/useStore';
import { workspaceStore } from '#/modules/Workspace/stores';
import { closeUndoHistory, type WorkspaceState } from '#/modules/Workspace/useCases';
import { cn } from '#/utils/Styles/cn';

import { undoStore, type UndoStoreState } from '../../stores/undoStore';
import { undoToIndex } from '../../useCases/undoRedo';

const defaultState: UndoStoreState = { past: [], future: [] };

export const UndoHistoryPanel = (): ReactElement | null => {
    const wsOpen = useStore(workspaceStore, null as unknown as WorkspaceState)?.undoHistoryOpen ?? false;

    const state = useStore(undoStore, defaultState);

    if (!wsOpen) {
        return null;
    }

    const close = closeUndoHistory;

    const handleClick = (index: number) => {
        void undoToIndex(index);
    };

    const pastCount = state.past.length;

    return (
        <DawUtilityPanel className="absolute right-2 top-10 z-40 w-56">
            <DawHeaderBand
                className="rounded-t-lg px-3 py-2"
                title="Undo History"
                titleClassName="text-xs font-medium normal-case tracking-normal text-foreground"
                actions={
                    <Button variant="ghost" size="icon-xs" onClick={close} aria-label="Close undo history">
                        <X className="size-3" />
                    </Button>
                }
            />
            <div className="max-h-72 overflow-y-auto">
                {state.past.length === 0 && state.future.length === 0 ? (
                    <div className="p-3">
                        <DawEmptyState
                            compact
                            title="No history yet"
                            description="Your edit timeline will appear here as you work."
                        />
                    </div>
                ) : null}

                {state.future.length > 0 ? (
                    <div className="border-b border-border/30 pb-1 pt-1">
                        <DawEyebrowLabel className="block px-3 py-0.5">
                            <Redo2 className="mr-1 inline size-2.5" />
                            Redo
                        </DawEyebrowLabel>
                        {[...state.future].reverse().map((entry, index) => {
                            const futureIndex = pastCount + (state.future.length - 1 - index);
                            return (
                                <DawUtilityListRow
                                    key={entry.id}
                                    title={entry.label}
                                    titleClassName="text-xs text-muted-foreground/50"
                                    onPress={() => handleClick(futureIndex)}
                                />
                            );
                        })}
                    </div>
                ) : null}

                <div className="px-3 py-1">
                    <DawEyebrowLabel className="flex items-center gap-1 text-[var(--color-state-success)]/80">
                        <span className="size-1.5 rounded-full bg-[var(--color-state-success)]" />
                        Current State
                    </DawEyebrowLabel>
                </div>

                {state.past.length > 0 ? (
                    <div className="pt-0.5 pb-1">
                        <DawEyebrowLabel className="block px-3 py-0.5">
                            <Undo2 className="mr-1 inline size-2.5" />
                            Undo
                        </DawEyebrowLabel>
                        {[...state.past].reverse().map((entry, index) => {
                            const entryIndex = pastCount - 1 - index;
                            return (
                                <DawUtilityListRow
                                    key={entry.id}
                                    active={index === 0}
                                    title={entry.label}
                                    titleClassName={cn(
                                        'text-xs',
                                        index === 0 ? 'text-foreground' : 'text-muted-foreground'
                                    )}
                                    endSlot={
                                        entry.source !== 'manual' ? (
                                            <DawMicroBadge className="px-1" tone="muted">
                                                {entry.source}
                                            </DawMicroBadge>
                                        ) : null
                                    }
                                    onPress={() => handleClick(entryIndex)}
                                />
                            );
                        })}
                    </div>
                ) : null}
            </div>
        </DawUtilityPanel>
    );
};

