import { STORE_NAME, openDatabase } from './helpers';

/** Clear all stored CRDT documents. */
export async function clearCrdtIdb(): Promise<void> {
    const database = await openDatabase();
    if (!database) {
        return;
    }

    await new Promise<void>((resolve, reject) => {
        const tx = database.transaction(STORE_NAME, 'readwrite');
        const store = tx.objectStore(STORE_NAME);
        const request = store.clear();
        request.onsuccess = () => resolve();
        request.onerror = () => reject(request.error);
    });
}

import { type DocId } from '../../models/CrdtDocumentTypes';

import { STORE_NAME, openDatabase } from './helpers';

/** Remove all incremental chunks for a document (after compaction). */
export async function clearIncrementalsFromIdb(id: DocId): Promise<void> {
    const database = await openDatabase();
    if (!database) {
        return;
    }

    await new Promise<void>((resolve, reject) => {
        const tx = database.transaction(STORE_NAME, 'readwrite');
        const store = tx.objectStore(STORE_NAME);
        const prefix = `${id}:incremental:`;

        const cursorRequest = store.openCursor();
        cursorRequest.onsuccess = () => {
            const cursor = cursorRequest.result;
            if (cursor) {
                if (typeof cursor.key === 'string' && cursor.key.startsWith(prefix)) {
                    cursor.delete();
                }
                cursor.continue();
            }
        };

        tx.oncomplete = () => resolve();
        tx.onerror = () => reject(tx.error);
    });
}

import { STORE_NAME, openDatabase } from './helpers';

/** Check whether any CRDT documents exist in IndexedDB. */
export async function hasCrdtDocsInIdb(): Promise<boolean> {
    const database = await openDatabase();
    if (!database) {
        return false;
    }

    return new Promise((resolve, reject) => {
        const tx = database.transaction(STORE_NAME, 'readonly');
        const store = tx.objectStore(STORE_NAME);
        const request = store.count();
        request.onsuccess = () => resolve(request.result > 0);
        request.onerror = () => reject(request.error);
    });
}

import { type DocumentBundle } from '../../models/CrdtDocumentTypes';

import { STORE_NAME, openDatabase } from './helpers';

/** Load all documents from IndexedDB. */
export async function loadAllFromIdb(): Promise<DocumentBundle | null> {
    const database = await openDatabase();
    if (!database) {
        return null;
    }

    return new Promise((resolve, reject) => {
        const tx = database.transaction(STORE_NAME, 'readonly');
        const store = tx.objectStore(STORE_NAME);

        const keysRequest = store.getAllKeys();
        const valuesRequest = store.getAll();

        tx.oncomplete = () => {
            const keys = keysRequest.result;
            const values = valuesRequest.result as Uint8Array[];

            if (keys.length === 0) {
                resolve(null);
                return;
            }

            const bundle: DocumentBundle = new Map();
            for (let index = 0; index < keys.length; index++) {
                const value = values[index];
                if (value) {
                    bundle.set(String(keys[index]), value);
                }
            }
            resolve(bundle);
        };

        tx.onerror = () => reject(tx.error);
    });
}

import { type DocId } from '../../models/CrdtDocumentTypes';

import { STORE_NAME, openDatabase } from './helpers';

/** Load a single document from IndexedDB. */
export async function loadDocFromIdb(id: DocId): Promise<Uint8Array | null> {
    const database = await openDatabase();
    if (!database) {
        return null;
    }

    return new Promise((resolve, reject) => {
        const tx = database.transaction(STORE_NAME, 'readonly');
        const store = tx.objectStore(STORE_NAME);
        const request = store.get(id);
        request.onsuccess = () => {
            const result = request.result as Uint8Array | undefined;
            resolve(result ?? null);
        };
        request.onerror = () => reject(request.error);
    });
}

import { type DocId } from '../../models/CrdtDocumentTypes';

import { STORE_NAME, openDatabase } from './helpers';

/** Load all incremental chunks for a document and apply them to the base. */
export async function loadIncrementalsFromIdb(id: DocId): Promise<Uint8Array[]> {
    const database = await openDatabase();
    if (!database) {
        return [];
    }

    return new Promise((resolve, reject) => {
        const tx = database.transaction(STORE_NAME, 'readonly');
        const store = tx.objectStore(STORE_NAME);
        const prefix = `${id}:incremental:`;
        const chunks: Uint8Array[] = [];

        const cursorRequest = store.openCursor();
        cursorRequest.onsuccess = () => {
            const cursor = cursorRequest.result;
            if (cursor) {
                if (typeof cursor.key === 'string' && cursor.key.startsWith(prefix)) {
                    chunks.push(cursor.value as Uint8Array);
                }
                cursor.continue();
            }
        };

        tx.oncomplete = () => resolve(chunks);
        tx.onerror = () => reject(tx.error);
    });
}

import { type DocumentBundle } from '../../models/CrdtDocumentTypes';

import { STORE_NAME, openDatabase } from './helpers';

/** Save all documents to IndexedDB. */
export async function saveAllToIdb(bundle: DocumentBundle): Promise<void> {
    const database = await openDatabase();
    if (!database) {
        return;
    }

    await new Promise<void>((resolve, reject) => {
        const tx = database.transaction(STORE_NAME, 'readwrite');
        const store = tx.objectStore(STORE_NAME);

        // Clear existing docs first
        store.clear();

        // Write all documents
        for (const [id, bytes] of bundle) {
            store.put(bytes, id);
        }

        tx.oncomplete = () => resolve();
        tx.onerror = () => reject(tx.error);
    });
}

import { type DocId } from '../../models/CrdtDocumentTypes';

import { STORE_NAME, openDatabase } from './helpers';

/** Save a single document to IndexedDB. */
export async function saveDocToIdb(id: DocId, bytes: Uint8Array): Promise<void> {
    const database = await openDatabase();
    if (!database) {
        return;
    }

    await new Promise<void>((resolve, reject) => {
        const tx = database.transaction(STORE_NAME, 'readwrite');
        const store = tx.objectStore(STORE_NAME);
        const request = store.put(bytes, id);
        request.onsuccess = () => resolve();
        request.onerror = () => reject(request.error);
    });
}

import { type DocId } from '../../models/CrdtDocumentTypes';

import { STORE_NAME, openDatabase } from './helpers';

/** Save an incremental chunk for a document (append, don't replace). */
export async function saveIncrementalToIdb(id: DocId, chunk: Uint8Array): Promise<void> {
    if (chunk.length === 0) {
        return;
    }
    const database = await openDatabase();
    if (!database) {
        return;
    }

    const key = `${id}:incremental:${Date.now()}-${Math.random().toString(36).slice(2, 6)}`;
    await new Promise<void>((resolve, reject) => {
        const tx = database.transaction(STORE_NAME, 'readwrite');
        const store = tx.objectStore(STORE_NAME);
        store.put(chunk, key);
        tx.oncomplete = () => resolve();
        tx.onerror = () => reject(tx.error);
    });
}

