/**
 * Handle file drop events on the crumbs panel.
 * Supports both browser File API and Tauri file paths.
 * Auto-detects sample category and suggests appropriate mode.
 */

import type { DragEvent } from 'react';

import { logger } from '#/infra/logger/appLogger';
import { isTauri } from '#/utils/tauriBridge';

import { crumbsStore } from '../stores/crumbsStore';

import { loadSampleFromPath } from './loadSample';
import { switchCrumbsMode } from './setCrumbsMode';

import type { SampleCategory, CrumbsMode } from '../models/CrumbsTypes';

const AUDIO_EXTENSIONS = new Set(['.wav', '.mp3', '.flac', '.ogg', '.aac', '.aiff', '.aif', '.m4a']);

function isAudioFile(name: string): boolean {
    const lower = name.toLowerCase();
    return Array.from(AUDIO_EXTENSIONS).some((ext) => lower.endsWith(ext));
}

function categoryToMode(category: SampleCategory): CrumbsMode {
    switch (category) {
        case 'percussive':
            return 'drum';
        case 'loop':
            return 'slice';
        case 'tonal':
            return 'quick';
        default:
            return 'quick';
    }
}

export async function handleCrumbsFileDrop(instanceId: string, event: DragEvent): Promise<void> {
    event.preventDefault();
    event.stopPropagation();

    const files = event.dataTransfer.files;
    if (files.length === 0) {
        return;
    }

    const file = files[0];
    if (!file || !isAudioFile(file.name)) {
        return;
    }

    if (!isTauri()) {
        logger.warn(
            '[Crumbs] File drop is only supported in the desktop app. Use the sample browser to load audio on web.'
        );
        return;
    }

    let filePath: string | null = null;

    if ('path' in file) {
        filePath = (file as File & { path: string }).path;
    }

    if (!filePath) {
        filePath = file.webkitRelativePath || file.name;
    }

    if (filePath) {
        await loadSampleFromPath(instanceId, filePath);

        const state = crumbsStore.value?.[instanceId];
        if (state?.activeSample) {
            const suggestedMode = categoryToMode(state.activeSample.category);
            await switchCrumbsMode(instanceId, suggestedMode);
        }
    }
}

/**
 * Playback position tracking.
 * Polls the backend at 30Hz and provides a rAF-interpolated position
 * for smooth 60fps cursor rendering.
 */

import { logger } from '#/infra/logger/appLogger';
import { isTauri } from '#/utils/tauriBridge';

import { getCrumbsPosition } from '../repositories/crumbsBridge';

type PositionListener = (frame: number) => void;

type PollingSession = {
    pollTimer: ReturnType<typeof setInterval> | null;
    rafId: number | null;
    lastPolledFrame: number;
    prevPolledFrame: number;
    pollTimestamp: number;
    interpolatedFrame: number;
    listeners: Set<PositionListener>;
};

const sessions = new Map<string, PollingSession>();

const POLL_INTERVAL_MS = 33; // ~30Hz

function getOrCreateSession(instanceId: string): PollingSession {
    let session = sessions.get(instanceId);
    if (!session) {
        session = {
            pollTimer: null,
            rafId: null,
            lastPolledFrame: 0,
            prevPolledFrame: 0,
            pollTimestamp: 0,
            interpolatedFrame: 0,
            listeners: new Set<PositionListener>(),
        };
        sessions.set(instanceId, session);
    }
    return session;
}

function startPolling(instanceId: string): void {
    const session = getOrCreateSession(instanceId);
    if (session.pollTimer !== null) {
        return;
    }

    // Crumbs position data is sourced from the Rust audio host via Tauri IPC.
    // On the browser build the bridge has nothing to answer with, so the 30 Hz
    // poll would otherwise spam a warn per tick — just stay idle.
    if (!isTauri()) {
        return;
    }

    session.pollTimestamp = performance.now();

    session.pollTimer = setInterval(async () => {
        try {
            session.prevPolledFrame = session.lastPolledFrame;
            session.lastPolledFrame = await getCrumbsPosition(instanceId);
            session.pollTimestamp = performance.now();
        } catch (error) {
            logger.warn(`Crumbs position poll failed for ${instanceId}:`, error);
        }
    }, POLL_INTERVAL_MS);

    // rAF loop for 60fps interpolation.
    function tick(): void {
        const now = performance.now();
        const elapsed = now - session.pollTimestamp;
        const t = Math.min(elapsed / POLL_INTERVAL_MS, 1);

        // Linear interpolation between last two polled positions.
        session.interpolatedFrame = session.prevPolledFrame + (session.lastPolledFrame - session.prevPolledFrame) * t;

        for (const listener of session.listeners) {
            listener(session.interpolatedFrame);
        }

        session.rafId = requestAnimationFrame(tick);
    }

    session.rafId = requestAnimationFrame(tick);
}

function stopPolling(instanceId: string): void {
    const session = sessions.get(instanceId);
    if (!session) {
        return;
    }

    if (session.pollTimer !== null) {
        clearInterval(session.pollTimer);
        session.pollTimer = null;
    }
    if (session.rafId !== null) {
        cancelAnimationFrame(session.rafId);
        session.rafId = null;
    }
}

export function subscribeToPosition(instanceId: string, listener: PositionListener): () => void {
    const session = getOrCreateSession(instanceId);
    session.listeners.add(listener);

    if (session.listeners.size === 1) {
        startPolling(instanceId);
    }

    return () => {
        session.listeners.delete(listener);
        if (session.listeners.size === 0) {
            stopPolling(instanceId);
            sessions.delete(instanceId);
        }
    };
}

export function getInterpolatedPosition(instanceId: string): number {
    return sessions.get(instanceId)?.interpolatedFrame ?? 0;
}

/**
 * CrustGainStrip — the left vertical "push" slider.
 * Pointer-capture based, no drag events — smooth cross-platform.
 * Ctrl/Cmd = fine-mode (0.1× sensitivity).
 */
import { type ReactElement, type KeyboardEvent, useRef } from 'react';

type Props = {
    value: number; // 0 – 18 dB
    onChange: (v: number) => void;
};

const MIN = 0;
const MAX = 18;

function norm(v: number): number {
    return Math.max(0, Math.min(1, v / MAX));
}
function clamp(v: number): number {
    return Math.max(MIN, Math.min(MAX, v));
}

export const CrustGainStrip = ({ value, onChange }: Props): ReactElement => {
    const trackRef = useRef<HTMLDivElement>(null);
    const drag = useRef({ active: false, startY: 0, startValue: 0 });

    function handlePointerDown(e: React.PointerEvent): void {
        drag.current = { active: true, startY: e.clientY, startValue: value };
        (e.target as HTMLElement).setPointerCapture(e.pointerId);
    }

    function handlePointerMove(e: React.PointerEvent): void {
        if (!drag.current.active || !trackRef.current) {
            return;
        }
        const trackH = trackRef.current.getBoundingClientRect().height;
        const dy = drag.current.startY - e.clientY; // upward = more gain
        const scale = e.ctrlKey || e.metaKey ? 0.1 : 1;
        const delta = (dy / trackH) * MAX * scale;
        onChange(clamp(drag.current.startValue + delta));
    }

    function handlePointerUp(): void {
        drag.current.active = false;
    }

    function handleKeyDown(e: KeyboardEvent): void {
        const step = e.shiftKey ? 1 : 0.1;
        if (e.key === 'ArrowUp') {
            e.preventDefault();
            onChange(clamp(value + step));
        }
        if (e.key === 'ArrowDown') {
            e.preventDefault();
            onChange(clamp(value - step));
        }
    }

    const n = norm(value);
    const fillColor = (() => {
        if (n > 0.66) {
            return '#C44030';
        }
        if (n > 0.33) {
            return '#D4A847';
        }
        return '#5B8FC4';
    })();

    return (
        <div
            className="flex flex-col items-center px-1.5 py-2 gap-1 select-none shrink-0"
            style={{
                width: 52,
                background: 'linear-gradient(180deg, #0A0A0C 0%, #0E0E10 100%)',
                borderRight: '1px solid rgba(46,46,54,0.5)',
            }}
        >
            <span className="text-[7px] font-semibold text-muted-foreground/40 uppercase tracking-widest">Gain</span>

            {/* Drag track */}
            <div
                ref={trackRef}
                className="relative flex-1 w-full flex justify-center cursor-pointer"
                style={{ minHeight: 120 }}
                onPointerDown={handlePointerDown}
                onPointerMove={handlePointerMove}
                onPointerUp={handlePointerUp}
                role="slider"
                aria-label="Input gain"
                aria-valuemin={MIN}
                aria-valuemax={MAX}
                aria-valuenow={Math.round(value * 10) / 10}
                aria-valuetext={`${value.toFixed(1)} dB`}
                tabIndex={0}
                onKeyDown={handleKeyDown}
            >
                {/* Track rail */}
                <div
                    className="absolute top-0 bottom-0 rounded-full"
                    style={{ width: 4, left: '50%', transform: 'translateX(-50%)', background: '#1E1E22' }}
                />

                {/* Fill */}
                <div
                    className="absolute rounded-full pointer-events-none transition-none"
                    style={{
                        width: 4,
                        left: '50%',
                        transform: 'translateX(-50%)',
                        bottom: 0,
                        height: `${n * 100}%`,
                        background: `linear-gradient(to top, #5B8FC4, ${fillColor})`,
                    }}
                />

                {/* Thumb */}
                <div
                    className="absolute pointer-events-none"
                    style={{
                        width: 28,
                        height: 10,
                        left: '50%',
                        bottom: `${n * 100}%`,
                        transform: 'translate(-50%, 50%)',
                        background: '#E8E6E0',
                        borderRadius: 3,
                        boxShadow: '0 1px 3px rgba(0,0,0,0.6)',
                    }}
                >
                    {/* Center notch */}
                    <div
                        style={{
                            position: 'absolute',
                            left: '50%',
                            top: '50%',
                            transform: 'translate(-50%, -50%)',
                            width: 8,
                            height: 2,
                            background: '#0E0E10',
                            borderRadius: 1,
                        }}
                    />
                </div>

                {/* 0 dB reference tick */}
                <div
                    className="absolute pointer-events-none"
                    style={{ bottom: 0, left: '50%', transform: 'translate(8px, 0)' }}
                >
                    <span className="text-[6px] font-mono text-muted-foreground/30">0</span>
                </div>
            </div>

            {/* Numeric readout */}
            <span
                className="text-[9px] font-mono tabular-nums font-semibold"
                style={{
                    color: (() => {
                        if (value > 12) {
                            return '#C44030';
                        }
                        if (value > 6) {
                            return '#D4A847';
                        }
                        return '#E8E6E0';
                    })(),
                }}
                aria-hidden="true"
            >
                {value > 0 ? '+' : ''}
                {value.toFixed(1)}
            </span>
            <span className="text-[6px] text-muted-foreground/30 font-mono">dB</span>
        </div>
    );
};

/**
 * CrustMeteringStrip — right panel: L/R output meters, GR meter, LUFS readouts, TP LED.
 */
import { type ReactElement } from 'react';

import { DawPluginLed } from '#/components/daw/DawPluginLed';
