// Consumer-local shape (AGENTS.md §95 — model isolation). Only the fields this browser renders.
type SoundPreset = {
    id: string;
    name: string;
    category: string;
    tags?: string[];
};

type PresetBrowserProps = {
    currentName: string;
    userPatches: Array<{ id: string; name: string }>;
    presets: SoundPreset[];
    onLoadPreset: (presetId: string) => void;
};

const CATEGORIES = [
    { id: 'all', label: 'All', icon: null },
    { id: 'user', label: 'My Patches', color: 'var(--color-accent-peach)' },
    { id: 'synth', label: 'Synth', color: 'var(--color-accent-lavender)' },
    { id: 'bass', label: 'Bass', color: 'var(--color-state-danger)' },
    { id: 'lead', label: 'Lead', color: 'var(--color-accent-peach)' },
    { id: 'pad', label: 'Pad', color: 'var(--color-accent-cyan)' },
    { id: 'keys', label: 'Keys', color: 'var(--color-accent-mint)' },
    { id: 'strings', label: 'Strings', color: 'var(--color-accent-lavender)' },
    { id: 'drums', label: 'Drums', color: 'var(--color-accent-peach)' },
    { id: 'fx', label: 'FX', color: 'var(--color-accent-lavender)' },
];

const TAGS = [
    'fermenter',
    'analog',
    'fm',
    'physical',
    'granular',
    'additive',
    'acid',
    'warm',
    'aggressive',
    'ambient',
    'unison',
    'warp',
    'moog',
    'diode',
];

export const PresetBrowser = ({
    currentName,
    userPatches,
    presets,
    onLoadPreset,
}: PresetBrowserProps): ReactElement => {
    const [search, setSearch] = useState('');
    const [category, setCategory] = useState('all');
    const [selectedTag, setSelectedTag] = useState<string | null>(null);

    // React Compiler handles memoization automatically — no useMemo needed
    let filtered =
        category === 'user'
            ? userPatches.map((p) => ({ id: p.id, name: p.name, category: 'user', tags: [] as string[] }))
            : presets.map((p) => ({
                  id: p.id,
                  name: p.name.replace('Fermenter — ', ''),
                  category: p.category,
                  tags: p.tags || [],
              }));

    if (category !== 'all' && category !== 'user') {
        filtered = filtered.filter((p) => p.category === category);
    }

    if (search) {
        const q = search.toLowerCase();
        filtered = filtered.filter(
            (p) => p.name.toLowerCase().includes(q) || p.tags.some((t) => t.toLowerCase().includes(q))
        );
    }

    if (selectedTag) {
        filtered = filtered.filter((p) => p.tags.includes(selectedTag));
    }

    return (
        <div className="flex flex-col h-full">
            {/* Search */}
            <div className="relative px-2 py-1.5 shrink-0">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 size-3 text-muted-foreground" />
                <input
                    type="text"
                    value={search}
                    onChange={(e) => setSearch(e.target.value)}
                    placeholder="Search presets…"
                    className="w-full h-6 rounded border border-border/40 bg-surface-inset pl-7 pr-2 text-[9px] text-foreground outline-none focus:border-[var(--color-accent-lavender)]"
                />
            </div>
            {/* Category pills */}
            <div className="flex flex-wrap gap-0.5 px-2 py-1 shrink-0 border-b border-border/20">
                {CATEGORIES.map((cat) => (
                    <button
                        key={cat.id}
                        type="button"
                        className={`px-1.5 py-0.5 rounded text-[7px] font-medium transition-colors ${
                            category === cat.id ? 'text-white' : 'text-muted-foreground/60 hover:text-foreground'
                        }`}
                        style={(() => {
                            if (category === cat.id && cat.color) {
                                return { backgroundColor: cat.color };
                            }
                            if (category === cat.id) {
                                return { backgroundColor: 'var(--color-accent-lavender)' };
                            }
                            return undefined;
                        })()}
                        onClick={() => {
                            setCategory(cat.id);
                            setSelectedTag(null);
                        }}
                    >
                        {cat.id === 'user' ? <Star className="size-2.5 inline mr-0.5" /> : null}
                        {cat.label}
                    </button>
                ))}
            </div>
            {/* Tag filter (contextual) */}
            {(() => {
                if (category !== 'user') {
                    return (
                        <div className="flex flex-wrap gap-0.5 px-2 py-0.5 shrink-0">
                            {TAGS.filter((tag) => {
                                // Only show tags that have matching presets in current category
                                return filtered.some((p) => p.tags.includes(tag));
                            })
                                .slice(0, 10)
                                .map((tag) => (
                                    <button
                                        key={tag}
                                        type="button"
                                        className={`px-1 py-0 rounded text-[6px] transition-colors ${
                                            selectedTag === tag
                                                ? 'bg-muted text-foreground'
                                                : 'text-muted-foreground/40 hover:text-muted-foreground'
                                        }`}
                                        onClick={() => setSelectedTag(selectedTag === tag ? null : tag)}
                                    >
                                        #{tag}
                                    </button>
                                ))}
                        </div>
                    );
                } else {
                    return null;
                }
            })()}
            {/* Preset list */}
            <div className="flex-1 overflow-y-auto px-1 py-0.5">
                {filtered.length === 0 ? (
                    <div className="text-center text-[9px] text-muted-foreground/50 py-6">No presets found</div>
                ) : (
                    filtered.map((preset) => (
                        <button
                            key={preset.id}
                            type="button"
                            className={`w-full flex items-center justify-between px-2 py-1 rounded text-left transition-all ${
                                preset.name === currentName || preset.name === currentName.replace('Fermenter — ', '')
                                    ? 'bg-[var(--color-accent-lavender)]/15 text-foreground'
                                    : 'hover:bg-surface-raised text-foreground/80'
                            }`}
                            onClick={() => onLoadPreset(preset.id)}
                        >
                            <span className="text-[9px] font-medium truncate">{preset.name}</span>
                            <ChevronRight className="size-3 text-muted-foreground/30 shrink-0" />
                        </button>
                    ))
                )}
            </div>
            <div className="px-2 py-0.5 border-t border-border/20 shrink-0">
                <span className="text-[7px] text-muted-foreground/40">{filtered.length} presets</span>
            </div>
        </div>
    );
};

/**
 * Signal Flow View — Level 4 (Route) visualization.
 * Shows the complete audio path from generators through effects to output.
 * Each node is interactive — clicking opens its controls in the inspector.
 */
import { type ReactElement, useRef, useEffect, useMemo } from 'react';

import { DawDiagramFrame } from '#/components/daw/DawDiagramFrame';

import { ENGINE_NAMES, FILTER_MODEL_NAMES, WARP_MODE_NAMES, type FermenterPatch } from '../../models/FermenterPatch';

type SignalFlowViewProps = {
    patch: FermenterPatch;
    numLayers: number;
    activeLayer: number;
    onSelectSection: (section: string) => void;
};

type FlowNode = {
    label: string;
    subtitle?: string;
    active: boolean;
    color: string;
    section: string;
    x: number;
    y: number;
    w: number;
    h: number;
};

const NODE_W = 90;
const NODE_H = 28;
const GAP_X = 16;
const GAP_Y = 8;

/** Map signal flow node sections to the actual SectionNav section IDs */
const SECTION_MAP: Record<string, string> = {
    osc: 'osc',
    warp: 'osc',
    filter: 'filter',
    voicefx: 'fx',
    dist: 'fx',
    comp: 'fx',
    reverb: 'fx',
    eq: 'fx',
    delay: 'fx',
    chorus: 'fx',
    phaser: 'fx',
    width: 'fx',
    master: 'fx',
};

export const SignalFlowView = ({
    patch,
    numLayers,
    activeLayer,
    onSelectSection,
}: SignalFlowViewProps): ReactElement => {
    const canvasRef = useRef<HTMLCanvasElement>(null);

    // Build node graph
    const { nodes, connections, canvasW, canvasH } = useMemo(() => {
        const nodes: FlowNode[] = [];
        const connections: Array<[number, number]> = [];

        let x = 10;
        const y0 = 10;

        // Layer generators
        for (let i = 0; i < numLayers; i++) {
            const isActive = i === activeLayer;
            nodes.push({
                label: `Layer ${i + 1}`,
                subtitle: isActive ? (ENGINE_NAMES[patch.oscEngine] ?? 'WT') : '—',
                active: isActive,
                color: ['#60C8E8', '#70E8A0', '#E8A060', '#B888E8'][i] ?? '#888',
                section: 'osc',
                x,
                y: y0 + i * (NODE_H + GAP_Y),
                w: NODE_W,
                h: NODE_H,
            });
        }

        // Warp
        const warpActive = patch.warpMode > 0 && patch.warpAmount > 0.001;
        x += NODE_W + GAP_X;
        const warpIdx = nodes.length;
        nodes.push({
            label: 'Warp',
            subtitle: warpActive ? WARP_MODE_NAMES[patch.warpMode] : 'Off',
            active: warpActive,
            color: '#E8A060',
            section: 'warp',
            x,
            y: y0,
            w: NODE_W,
            h: NODE_H,
        });
        for (let i = 0; i < numLayers; i++) {
            connections.push([i, warpIdx]);
        }

        // Filter
        x += NODE_W + GAP_X;
        const filterIdx = nodes.length;
        nodes.push({
            label: 'Filter',
            subtitle: FILTER_MODEL_NAMES[patch.filterModel] ?? 'SVF',
            active: true,
            color: '#60C8E8',
            section: 'filter',
            x,
            y: y0,
            w: NODE_W,
            h: NODE_H,
        });
        connections.push([warpIdx, filterIdx]);

        // Voice Drive
        const vdActive = patch.voiceDrive > 0.001;
        x += NODE_W + GAP_X;
        const vdIdx = nodes.length;
        nodes.push({
            label: 'Voice FX',
            subtitle: vdActive ? `Drive ${patch.voiceDrive.toFixed(1)}` : 'Off',
            active: vdActive,
            color: '#E86060',
            section: 'voicefx',
            x,
            y: y0,
            w: NODE_W,
            h: NODE_H,
        });
        connections.push([filterIdx, vdIdx]);

        // Distortion
        const distActive = patch.distMix > 0.001;
        x += NODE_W + GAP_X;
        const distIdx = nodes.length;
        nodes.push({
            label: 'Distortion',
            subtitle: distActive ? `${Math.round(patch.distMix * 100)}%` : 'Off',
            active: distActive,
            color: '#E86060',
            section: 'dist',
            x,
            y: y0,
            w: NODE_W,
            h: NODE_H,
        });
        connections.push([vdIdx, distIdx]);

        // Compressor
        const compActive = patch.compMix > 0.001;
        x += NODE_W + GAP_X;
        const compIdx = nodes.length;
        nodes.push({
            label: 'Compressor',
            subtitle: compActive ? `${patch.compRatio.toFixed(0)}:1` : 'Off',
            active: compActive,
            color: '#B888E8',
            section: 'comp',
            x,
            y: y0,
            w: NODE_W,
            h: NODE_H,
        });
        connections.push([distIdx, compIdx]);

        // Reverb
        x += NODE_W + GAP_X;
        const revIdx = nodes.length;
        const revActive = patch.reverbMix > 0.001;
        nodes.push({
            label: patch.reverbType === 0 ? 'Plate Rev' : 'FDN Rev',
            subtitle: revActive ? `${Math.round(patch.reverbMix * 100)}%` : 'Off',
            active: revActive,
            color: '#70E8A0',
            section: 'reverb',
            x,
            y: y0,
            w: NODE_W,
            h: NODE_H,
        });
        connections.push([compIdx, revIdx]);

        // EQ
        const eqActive =
            Math.abs(patch.eqLowGain) > 0.1 || Math.abs(patch.eqMidGain) > 0.1 || Math.abs(patch.eqHighGain) > 0.1;
        x += NODE_W + GAP_X;
        const eqIdx = nodes.length;
        nodes.push({
            label: 'EQ',
            subtitle: eqActive ? '3-Band' : 'Flat',
            active: eqActive,
            color: '#E8E060',
            section: 'eq',
            x,
            y: y0,
            w: NODE_W,
            h: NODE_H,
        });
        connections.push([revIdx, eqIdx]);

        // Effects row 2: Delay, Chorus, Phaser
        const row2y = y0 + NODE_H + GAP_Y + 6;
        let fx2x = nodes[distIdx]!.x;

        const delActive = patch.delayMix > 0.001;
        const delIdx = nodes.length;
        nodes.push({
            label: 'Delay',
            subtitle: delActive ? `${Math.round(patch.delayTime)}ms` : 'Off',
            active: delActive,
            color: '#60C8E8',
            section: 'delay',
            x: fx2x,
            y: row2y,
            w: 70,
            h: 22,
        });
        connections.push([distIdx, delIdx]);
        connections.push([delIdx, revIdx]);

        fx2x += 78;
        const chrActive = patch.chorusMix > 0.001;
        const chrIdx = nodes.length;
        nodes.push({
            label: 'Chorus',
            subtitle: chrActive ? `${Math.round(patch.chorusMix * 100)}%` : 'Off',
            active: chrActive,
            color: '#60C8E8',
            section: 'chorus',
            x: fx2x,
            y: row2y,
            w: 70,
            h: 22,
        });
        connections.push([delIdx, chrIdx]);
        connections.push([chrIdx, revIdx]);

        fx2x += 78;
        const phActive = patch.phaserMix > 0.001;
        const phIdx = nodes.length;
        nodes.push({
            label: 'Phaser',
            subtitle: phActive ? `${Math.round(patch.phaserMix * 100)}%` : 'Off',
            active: phActive,
            color: '#60C8E8',
            section: 'phaser',
            x: fx2x,
            y: row2y,
            w: 70,
            h: 22,
        });
        connections.push([chrIdx, phIdx]);

        // Width + Master
        x += NODE_W + GAP_X;
        const widthIdx = nodes.length;
        nodes.push({
            label: 'Width',
            subtitle: `${Math.round(patch.stereoWidth * 100)}%`,
            active: Math.abs(patch.stereoWidth - 1.0) > 0.01,
            color: '#B888E8',
            section: 'width',
            x,
            y: y0,
            w: 60,
            h: NODE_H,
        });
        connections.push([eqIdx, widthIdx]);

        x += 68;
        const masterIdx = nodes.length;
        nodes.push({
            label: 'Master',
            subtitle: `${(patch.masterGain * 100).toFixed(0)}%`,
            active: true,
            color: '#FFF',
            section: 'master',
            x,
            y: y0,
            w: 60,
            h: NODE_H,
        });
        connections.push([widthIdx, masterIdx]);
        const canvasW = x + 70;
        const canvasH = row2y + 30;

        return { nodes, connections, canvasW, canvasH };
    }, [patch, numLayers, activeLayer]);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) {
            return;
        }
        const ctx = canvas.getContext('2d');
        if (!ctx) {
            return;
        }

        const dpr = window.devicePixelRatio || 1;
        canvas.width = canvasW * dpr;
        canvas.height = canvasH * dpr;
        ctx.scale(dpr, dpr);
        ctx.clearRect(0, 0, canvasW, canvasH);

        // Draw connections with subtle glow
        for (const [from, to] of connections) {
            const fn = nodes[from]!;
            const tn = nodes[to]!;
            const fromActive = fn.active;
            ctx.strokeStyle = fromActive ? 'rgba(255,255,255,0.12)' : 'rgba(255,255,255,0.04)';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(fn.x + fn.w, fn.y + fn.h / 2);
            ctx.lineTo(tn.x, tn.y + tn.h / 2);
            ctx.stroke();
        }

        // Draw nodes
        for (const node of nodes) {
            const alpha = node.active ? 1.0 : 0.35;
            ctx.globalAlpha = alpha;

            // Node background — recessed look
            const grad = ctx.createLinearGradient(node.x, node.y, node.x, node.y + node.h);
            grad.addColorStop(0, 'rgba(18,18,24,0.9)');
            grad.addColorStop(1, 'rgba(24,24,32,0.9)');
            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.roundRect(node.x, node.y, node.w, node.h, 5);
            ctx.fill();

            // Border — colored left edge, subtle elsewhere
            ctx.strokeStyle = 'rgba(255,255,255,0.06)';
            ctx.lineWidth = 1;
            ctx.stroke();

            // Colored left accent bar
            ctx.fillStyle = node.color;
            ctx.beginPath();
            ctx.roundRect(node.x, node.y, 3, node.h, [5, 0, 0, 5]);
            ctx.fill();

            // Label
            ctx.fillStyle = node.active ? '#e0e0e0' : '#888';
            ctx.font = 'bold 8px system-ui';
            ctx.textAlign = 'center';
            ctx.fillText(node.label, node.x + node.w / 2 + 1, node.y + 12);

            // Subtitle
            if (node.subtitle) {
                ctx.fillStyle = node.color;
                ctx.font = '7px system-ui';
                ctx.fillText(node.subtitle, node.x + node.w / 2 + 1, node.y + 22);
            }

            ctx.globalAlpha = 1.0;
        }
    }, [patch, numLayers, activeLayer]);

    return (
        <DawDiagramFrame title="Signal flow" compact className="bg-black/[0.16]" viewportClassName="p-2">
            <div className="overflow-x-auto">
                <canvas
                    ref={canvasRef}
                    style={{ width: canvasW, height: canvasH }}
                    className="cursor-pointer"
                    onClick={(e) => {
                        const rect = (e.target as HTMLCanvasElement).getBoundingClientRect();
                        const mx = e.clientX - rect.left;
                        const my = e.clientY - rect.top;
                        for (const node of nodes) {
                            if (mx >= node.x && mx <= node.x + node.w && my >= node.y && my <= node.y + node.h) {
                                onSelectSection(SECTION_MAP[node.section] ?? node.section);
                                break;
                            }
                        }
                    }}
                />
            </div>
        </DawDiagramFrame>
    );
};

/**
 * Spectral warp controls + Audio-rate modulation.
 */
import { type ReactElement } from 'react';

import { DawPluginChip } from '#/components/daw/DawPluginChip';
import { RotaryKnob } from '#/components/daw/RotaryKnob';

import { WARP_MODE_NAMES, AUDIO_MOD_TARGET_NAMES } from '../../models/FermenterPatch';

type WarpSectionProps = {
    warpMode: number;
    warpAmount: number;
    audioModRate: number;
    audioModDepth: number;
    audioModTarget: number;
    onParam: (key: string, value: number) => void;
};

export const WarpSection = ({
    warpMode,
    warpAmount,
    audioModRate,
    audioModDepth,
    audioModTarget,
    onParam,
}: WarpSectionProps): ReactElement => (
    <div className="space-y-2">
        <div className="text-[10px] font-medium text-muted-foreground uppercase tracking-wider px-1">Warp / Mod</div>

        {/* Warp mode selector */}
        <div className="space-y-0.5">
            <div className="text-[8px] text-muted-foreground/70 px-1">Spectral Warp</div>
            <div className="flex flex-wrap gap-0.5 px-1">
                {WARP_MODE_NAMES.map((name, i) => (
                    <DawPluginChip
                        key={name}
                        active={warpMode === i}
                        tone="peach"
                        size="xs"
                        onClick={() => onParam('warpMode', i)}
                    >
                        {name}
                    </DawPluginChip>
                ))}
            </div>
            {warpMode > 0 ? (
                <div className="flex items-end gap-2 px-1">
                    <div className="flex flex-col items-center gap-0.5">
                        <RotaryKnob
                            value={warpAmount}
                            onChange={(v) => onParam('warpAmount', v)}
                            min={0}
                            max={1}
                            step={0.01}
                            defaultValue={0}
                            size="lg"
                            tone="sage"
                        />
                        <span className="text-[7px] text-muted-foreground">Amount</span>
                    </div>
                </div>
            ) : null}
        </div>

        {/* Audio-rate modulation */}
        <div className="space-y-0.5">
            <div className="text-[8px] text-muted-foreground/70 px-1">Audio-Rate Mod</div>
            <div className="flex gap-0.5 px-1">
                {AUDIO_MOD_TARGET_NAMES.map((name, i) => (
                    <DawPluginChip
                        key={name}
                        active={audioModTarget === i}
                        tone="mint"
                        size="xs"
                        onClick={() => onParam('audioModTarget', i)}
                    >
                        {name}
                    </DawPluginChip>
                ))}
            </div>
            {(() => {
                if (audioModTarget > 0) {
                    return (
                        <div className="flex items-end gap-2 px-1">
                            <div className="flex flex-col items-center gap-0.5">
                                <RotaryKnob
                                    value={audioModRate}
                                    onChange={(v) => onParam('audioModRate', v)}
                                    min={0}
                                    max={5000}
                                    step={1}
                                    defaultValue={0}
                                    size="lg"
                                    tone="sage"
                                />
                                <span className="text-[7px] text-muted-foreground">Rate</span>
                                <span className="text-[6px] text-muted-foreground/50 font-mono">
                                    {(() => {
                                        if (audioModRate < 20) {
                                            return `${audioModRate.toFixed(1)}Hz`;
                                        }
                                        if (audioModRate < 1000) {
                                            return `${Math.round(audioModRate)}Hz`;
                                        }
                                        return `${(audioModRate / 1000).toFixed(1)}kHz`;
                                    })()}
                                </span>
                            </div>
                            <div className="flex flex-col items-center gap-0.5">
                                <RotaryKnob
                                    value={audioModDepth}
                                    onChange={(v) => onParam('audioModDepth', v)}
                                    min={0}
                                    max={1}
                                    step={0.01}
                                    defaultValue={0}
                                    size="lg"
                                    tone="sage"
                                />
                                <span className="text-[7px] text-muted-foreground">Depth</span>
                            </div>
                        </div>
                    );
                } else {
                    return null;
                }
            })()}
        </div>
    </div>
);

import { type ReactElement, useEffect, useRef } from 'react';

type XYPadProps = {
    xValue: number;
    yValue: number;
    xLabel?: string;
    yLabel?: string;
    onXChange: (value: number) => void;
    onYChange: (value: number) => void;
    size?: number;
};

export const XYPad = ({
    xValue,
    yValue,
    xLabel = 'X',
    yLabel = 'Y',
    onXChange,
    onYChange,
    size = 120,
}: XYPadProps): ReactElement => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const draggingRef = useRef(false);

    function updateFromPointer(event: React.PointerEvent<HTMLCanvasElement>): void {
        const rect = event.currentTarget.getBoundingClientRect();
        const nextX = Math.max(0, Math.min(1, (event.clientX - rect.left) / rect.width));
        const nextY = Math.max(0, Math.min(1, 1 - (event.clientY - rect.top) / rect.height));

        onXChange(nextX);
        onYChange(nextY);
    }

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) {
            return;
        }

        const context = canvas.getContext('2d');
        if (!context) {
            return;
        }

        const dpr = window.devicePixelRatio || 1;
        canvas.width = size * dpr;
        canvas.height = size * dpr;

        context.setTransform(1, 0, 0, 1, 0, 0);
        context.scale(dpr, dpr);
        context.clearRect(0, 0, size, size);

        const background = context.createLinearGradient(0, 0, size, size);
        background.addColorStop(0, 'rgba(127,184,196,0.12)');
        background.addColorStop(0.5, 'rgba(10,10,14,0.94)');
        background.addColorStop(1, 'rgba(196,170,95,0.12)');
        context.fillStyle = background;
        context.fillRect(0, 0, size, size);

        context.strokeStyle = 'rgba(255,255,255,0.05)';
        context.lineWidth = 1;
        for (let index = 1; index < 4; index += 1) {
            const offset = (index / 4) * size;
            context.beginPath();
            context.moveTo(offset, 0);
            context.lineTo(offset, size);
            context.moveTo(0, offset);
            context.lineTo(size, offset);
            context.stroke();
        }

        const puckX = xValue * size;
        const puckY = (1 - yValue) * size;

        context.strokeStyle = 'rgba(127,184,196,0.2)';
        context.beginPath();
        context.moveTo(puckX, 0);
        context.lineTo(puckX, size);
        context.moveTo(0, puckY);
        context.lineTo(size, puckY);
        context.stroke();

        const glow = context.createRadialGradient(puckX, puckY, 0, puckX, puckY, 18);
        glow.addColorStop(0, 'rgba(127,184,196,0.35)');
        glow.addColorStop(1, 'rgba(127,184,196,0)');
        context.fillStyle = glow;
        context.fillRect(puckX - 18, puckY - 18, 36, 36);

        context.fillStyle = '#7fb8c4';
        context.beginPath();
        context.arc(puckX, puckY, 4.5, 0, Math.PI * 2);
        context.fill();

        context.font = '8px system-ui';
        context.fillStyle = 'rgba(255,255,255,0.25)';
        context.textAlign = 'center';
        context.fillText(xLabel, size / 2, size - 4);

        context.save();
        context.translate(10, size / 2);
        context.rotate(-Math.PI / 2);
        context.fillText(yLabel, 0, 0);
        context.restore();
    }, [size, xLabel, xValue, yLabel, yValue]);

    return (
        <canvas
            ref={canvasRef}
            className="rounded-[16px] border border-white/8"
            style={{
                width: size,
                height: size,
                cursor: draggingRef.current ? 'grabbing' : 'grab',
                touchAction: 'none',
            }}
            onPointerDown={(event) => {
                draggingRef.current = true;
                event.currentTarget.setPointerCapture(event.pointerId);
                updateFromPointer(event);
            }}
            onPointerMove={(event) => {
                if (draggingRef.current) {
                    updateFromPointer(event);
                }
            }}
            onPointerUp={() => {
                draggingRef.current = false;
            }}
            onPointerCancel={() => {
                draggingRef.current = false;
            }}
        />
    );
};

