import { type FermenterPatch } from '../../models/FermenterPatch';

/**
 * Linearly interpolate between two patches.
 * Non-numeric fields (name, version) come from patch A.
 * Numeric fields are lerped by t (0=A, 1=B).
 */
export function lerpPatch(a: FermenterPatch, b: FermenterPatch, t: number): FermenterPatch {
    const clamped = Math.max(0, Math.min(1, t));
    const result = { ...a };

    for (const key of Object.keys(a) as Array<keyof FermenterPatch>) {
        const va = a[key];
        const vb = b[key];
        if (typeof va === 'number' && typeof vb === 'number') {
            (result as Record<string, unknown>)[key] = va + (vb - va) * clamped;
        } else if (Array.isArray(va) && Array.isArray(vb) && va.length === vb.length) {
            // Assume number array (e.g. macros)
            const arr = Array.from({ length: va.length });
            for (let i = 0; i < va.length; i++) {
                const aVal = va[i];
                const bVal = vb[i];
                if (typeof aVal === 'number' && typeof bVal === 'number') {
                    arr[i] = aVal + (bVal - aVal) * clamped;
                } else {
                    arr[i] = aVal; // Fallback to A if not numbers
                }
            }
            (result as Record<string, unknown>)[key] = arr;
        }
    }

    result.name = clamped < 0.5 ? a.name : b.name;
    return result;
}

/**
 * Bilinear interpolation for 4-corner Transform Pad.
 * Corners: TL (top-left), TR, BL, BR.
 * x: 0=left, 1=right. y: 0=top, 1=bottom.
 */
export function bilinearPatch(
    tl: FermenterPatch,
    tr: FermenterPatch,
    bl: FermenterPatch,
    br: FermenterPatch,
    x: number,
    y: number
): FermenterPatch {
    const top = lerpPatch(tl, tr, x);
    const bottom = lerpPatch(bl, br, x);
    return lerpPatch(top, bottom, y);
}

import { type ReactElement, useEffect, useRef } from 'react';

import { resolveToken } from '#/utils/UI/resolveToken';

type GlutenCurveProps = {
    threshold: number;
    ratio: number;
    knee: number;
    makeup: number;
    grDb: number;
    inputDb: number;
    width?: number;
    height?: number;
    onThresholdChange?: (value: number) => void;
    onRatioChange?: (value: number) => void;
    accentColor?: string;
};

const DB_MIN = -60;
const DB_MAX = 0;

function computeOutput(inputDb: number, threshold: number, ratio: number, kneeWidth: number): number {
    const halfKnee = kneeWidth / 2;

    if (inputDb <= threshold - halfKnee) {
        return inputDb;
    }

    if (inputDb >= threshold + halfKnee) {
        return threshold + (inputDb - threshold) / ratio;
    }

    const x = inputDb - threshold + halfKnee;
    return inputDb + ((1 / ratio - 1) * x * x) / (2 * kneeWidth);
}

export const GlutenCurve = ({
    threshold,
    ratio,
    knee,
    makeup,
    grDb,
    inputDb,
    width = 340,
    height = 180,
    onThresholdChange,
    onRatioChange,
    accentColor,
}: GlutenCurveProps): ReactElement => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const isDragging = useRef<'threshold' | 'ratio' | null>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) {
            return;
        }

        const ctx = canvas.getContext('2d');
        if (!ctx) {
            return;
        }

        const dpr = window.devicePixelRatio || 1;
        canvas.width = width * dpr;
        canvas.height = height * dpr;
        ctx.scale(dpr, dpr);

        const pad = 10;
        const plotW = width - pad * 2;
        const plotH = height - pad * 2;
        const accent = resolveToken(accentColor ?? 'var(--color-accent-peach)', '#c9a07a');
        const dbToX = (db: number): number => pad + ((db - DB_MIN) / (DB_MAX - DB_MIN)) * plotW;
        const dbToY = (db: number): number => pad + plotH - ((db - DB_MIN) / (DB_MAX - DB_MIN)) * plotH;

        ctx.clearRect(0, 0, width, height);

        const shell = ctx.createLinearGradient(0, 0, 0, height);
        shell.addColorStop(0, '#111015');
        shell.addColorStop(0.55, '#0c0b10');
        shell.addColorStop(1, '#07070a');
        ctx.fillStyle = shell;
        ctx.beginPath();
        ctx.roundRect(0, 0, width, height, 14);
        ctx.fill();

        const haze = ctx.createRadialGradient(
            width * 0.22,
            height * 0.08,
            0,
            width * 0.22,
            height * 0.08,
            width * 0.75
        );
        haze.addColorStop(0, `${accent}22`);
        haze.addColorStop(1, `${accent}00`);
        ctx.fillStyle = haze;
        ctx.fillRect(0, 0, width, height);

        ctx.lineWidth = 0.75;
        ctx.font = '8px monospace';
        ctx.textAlign = 'center';
        for (const db of [-48, -36, -24, -12, 0]) {
            ctx.strokeStyle = db === 0 ? 'rgba(255,255,255,0.08)' : 'rgba(255,255,255,0.04)';
            ctx.beginPath();
            ctx.moveTo(pad, dbToY(db));
            ctx.lineTo(width - pad, dbToY(db));
            ctx.stroke();
            ctx.beginPath();
            ctx.moveTo(dbToX(db), pad);
            ctx.lineTo(dbToX(db), height - pad);
            ctx.stroke();
            ctx.fillStyle = 'rgba(255,255,255,0.22)';
            ctx.fillText(`${db}`, dbToX(db), height - 2);
        }

        ctx.beginPath();
        ctx.moveTo(dbToX(DB_MIN), dbToY(DB_MIN));
        ctx.lineTo(dbToX(DB_MAX), dbToY(DB_MAX));
        ctx.setLineDash([5, 4]);
        ctx.strokeStyle = 'rgba(255,255,255,0.07)';
        ctx.stroke();
        ctx.setLineDash([]);

        ctx.beginPath();
        const steps = plotW * 2;
        for (let i = 0; i <= steps; i += 1) {
            const inDb = DB_MIN + (i / steps) * (DB_MAX - DB_MIN);
            const outDb = Math.min(DB_MAX, computeOutput(inDb, threshold, ratio, knee) + makeup);
            const x = dbToX(inDb);
            const y = dbToY(Math.max(DB_MIN, outDb));
            if (i === 0) {
                ctx.moveTo(x, y);
            } else {
                ctx.lineTo(x, y);
            }
        }
        ctx.lineTo(dbToX(DB_MAX), dbToY(DB_MAX));
        ctx.lineTo(dbToX(DB_MIN), dbToY(DB_MIN));
        ctx.closePath();
        ctx.fillStyle = `${accent}17`;
        ctx.fill();

        ctx.beginPath();
        for (let i = 0; i <= steps; i += 1) {
            const inDb = DB_MIN + (i / steps) * (DB_MAX - DB_MIN);
            const outDb = Math.min(DB_MAX, computeOutput(inDb, threshold, ratio, knee) + makeup);
            const x = dbToX(inDb);
            const y = dbToY(Math.max(DB_MIN, outDb));
            if (i === 0) {
                ctx.moveTo(x, y);
            } else {
                ctx.lineTo(x, y);
            }
        }
        ctx.save();
        ctx.shadowColor = accent;
        ctx.shadowBlur = 12;
        ctx.strokeStyle = accent;
        ctx.lineWidth = 2.4;
        ctx.stroke();
        ctx.restore();

        const thresholdX = dbToX(threshold);
        const thresholdY = dbToY(computeOutput(threshold, threshold, ratio, knee) + makeup);
        ctx.beginPath();
        ctx.setLineDash([3, 4]);
        ctx.moveTo(thresholdX, pad);
        ctx.lineTo(thresholdX, height - pad);
        ctx.strokeStyle = `${accent}66`;
        ctx.lineWidth = 1;
        ctx.stroke();
        ctx.setLineDash([]);

        ctx.beginPath();
        ctx.arc(thresholdX, thresholdY, 6.2, 0, Math.PI * 2);
        ctx.fillStyle = accent;
        ctx.fill();
        ctx.lineWidth = 1.6;
        ctx.strokeStyle = 'rgba(255,255,255,0.92)';
        ctx.stroke();

        if (inputDb > -90) {
            const outDb = computeOutput(inputDb, threshold, ratio, knee) + makeup;
            const opX = dbToX(inputDb);
            const opY = dbToY(Math.max(DB_MIN, Math.min(DB_MAX, outDb)));

            const glow = ctx.createRadialGradient(opX, opY, 0, opX, opY, 16);
            glow.addColorStop(0, `${accent}55`);
            glow.addColorStop(1, `${accent}00`);
            ctx.fillStyle = glow;
            ctx.fillRect(opX - 16, opY - 16, 32, 32);

            ctx.beginPath();
            ctx.arc(opX, opY, 3.4, 0, Math.PI * 2);
            ctx.fillStyle = '#ffffff';
            ctx.fill();
        }

        if (grDb < -0.1) {
            const meterWidth = 7;
            const meterHeight = Math.min(plotH, (-grDb / 30) * plotH);
            const meterX = width - pad - meterWidth;
            const meterY = pad;
            ctx.fillStyle = `${accent}88`;
            ctx.fillRect(meterX, meterY, meterWidth, meterHeight);
            ctx.fillStyle = accent;
            ctx.font = 'bold 9px monospace';
            ctx.textAlign = 'right';
            ctx.fillText(`${grDb.toFixed(1)}`, meterX - 3, meterY + meterHeight + 11);
        }

        ctx.font = 'bold 10px monospace';
        ctx.textAlign = 'right';
        ctx.fillStyle = `${accent}cc`;
        ctx.fillText(ratio >= 20 ? '∞:1' : `${ratio.toFixed(1)}:1`, width - pad - 11, pad + 14);

        ctx.font = '8px monospace';
        ctx.textAlign = 'left';
        ctx.fillStyle = `${accent}99`;
        ctx.fillText(`T ${threshold.toFixed(0)} dB`, pad + 2, pad + 12);
    }, [accentColor, grDb, height, inputDb, knee, makeup, ratio, threshold, width]);

    function handlePointerDown(event: React.PointerEvent<HTMLCanvasElement>): void {
        if (!onThresholdChange && !onRatioChange) {
            return;
        }

        const canvas = canvasRef.current;
        if (!canvas) {
            return;
        }

        isDragging.current = 'threshold';
        canvas.setPointerCapture(event.pointerId);
        canvas.style.cursor = 'grabbing';
    }

    function handlePointerMove(event: React.PointerEvent<HTMLCanvasElement>): void {
        if (isDragging.current !== 'threshold' || !onThresholdChange) {
            return;
        }

        const canvas = canvasRef.current;
        if (!canvas) {
            return;
        }

        const rect = canvas.getBoundingClientRect();
        const plotH = height - 20;
        const yRatio = (event.clientY - rect.top - 10) / plotH;
        const db = DB_MAX - yRatio * (DB_MAX - DB_MIN);
        onThresholdChange(Math.max(-60, Math.min(0, db)));
    }

    function handlePointerUp(event: React.PointerEvent<HTMLCanvasElement>): void {
        const canvas = canvasRef.current;
        if (!canvas) {
            return;
        }

        isDragging.current = null;
        canvas.releasePointerCapture(event.pointerId);
        canvas.style.cursor = 'grab';
    }

    return (
        <canvas
            ref={canvasRef}
            width={width}
            height={height}
            style={{ width, height, cursor: onThresholdChange ? 'grab' : undefined }}
            className="rounded-[16px] border border-white/8"
            aria-label="Gluten compressor transfer curve"
            role="img"
            onPointerDown={handlePointerDown}
            onPointerMove={handlePointerMove}
            onPointerUp={handlePointerUp}
        />
    );
};

/**
 * Gain Reduction meter — vertical bar with peak hold and dB labels.
 */
import { type ReactElement, useRef, useEffect } from 'react';

import { resolveToken } from '#/utils/UI/resolveToken';

type GrMeterProps = {
    grDb: number;
    inputDb: number;
    outputDb: number;
    width?: number;
    height?: number;
    accentColor?: string;
};

export const GrMeter = ({
    grDb,
    inputDb,
    outputDb,
    width = 60,
    height = 160,
    accentColor,
}: GrMeterProps): ReactElement => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const peakHoldRef = useRef(0);
    const peakTimerRef = useRef(0);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) {
            return;
        }
        const ctx = canvas.getContext('2d');
        if (!ctx) {
            return;
        }

        const dpr = window.devicePixelRatio || 1;
        canvas.width = width * dpr;
        canvas.height = height * dpr;
        ctx.scale(dpr, dpr);

        const accent = resolveToken(accentColor ?? 'var(--color-accent-peach)', '#c4987b');

        ctx.clearRect(0, 0, width, height);

        // Background — deep gradient
        const bgGrad = ctx.createLinearGradient(0, 0, 0, height);
        bgGrad.addColorStop(0, '#0f0e12');
        bgGrad.addColorStop(0.5, '#0a090d');
        bgGrad.addColorStop(1, '#07060a');
        ctx.fillStyle = bgGrad;
        ctx.beginPath();
        ctx.roundRect(0, 0, width, height, 4);
        ctx.fill();

        const meterTop = 20;
        const meterBottom = height - 4;
        const meterHeight = meterBottom - meterTop;
        const barWidth = 10;

        // GR meter (center) — grows downward from top
        const grBarH = Math.min(meterHeight, Math.max(0, (-grDb / 30) * meterHeight));
        const grX = (width - barWidth) / 2;

        // GR bar gradient with glow
        if (grBarH > 0) {
            const grad = ctx.createLinearGradient(0, meterTop, 0, meterTop + grBarH);
            grad.addColorStop(0, `${accent}ee`);
            grad.addColorStop(0.6, `${accent}88`);
            grad.addColorStop(1, `${accent}30`);
            ctx.save();
            ctx.shadowColor = accent;
            ctx.shadowBlur = 8;
            ctx.fillStyle = grad;
            ctx.fillRect(grX, meterTop, barWidth, grBarH);
            ctx.restore();
        }

        // Peak hold
        if (grDb < peakHoldRef.current) {
            peakHoldRef.current = grDb;
            peakTimerRef.current = 90; // ~1.5 sec at 60fps
        } else if (peakTimerRef.current > 0) {
            peakTimerRef.current--;
        } else {
            peakHoldRef.current += 0.1;
            peakHoldRef.current = Math.min(0, peakHoldRef.current);
        }

        if (peakHoldRef.current < -0.1) {
            const peakY = meterTop + (-peakHoldRef.current / 30) * meterHeight;
            ctx.beginPath();
            ctx.moveTo(grX - 1, Math.min(peakY, meterBottom));
            ctx.lineTo(grX + barWidth + 1, Math.min(peakY, meterBottom));
            ctx.strokeStyle = accent;
            ctx.lineWidth = 1.5;
            ctx.stroke();
        }

        // Scale markings
        ctx.fillStyle = 'rgba(255,255,255,0.22)';
        ctx.font = '7px monospace';
        ctx.textAlign = 'right';
        for (const db of [0, -3, -6, -10, -15, -20, -30]) {
            const y = meterTop + (-db / 30) * meterHeight;
            if (y >= meterTop && y <= meterBottom) {
                // Tick
                ctx.fillRect(grX - 4, y, 3, 0.5);
                ctx.fillRect(grX + barWidth + 1, y, 3, 0.5);
                // Label
                ctx.fillText(`${db}`, grX - 5, y + 3);
            }
        }

        // GR value text
        ctx.fillStyle = accent;
        ctx.font = 'bold 10px monospace';
        ctx.textAlign = 'center';
        ctx.fillText(grDb < -0.1 ? `${grDb.toFixed(1)}` : '0.0', width / 2, 14);

        // Label
        ctx.fillStyle = 'rgba(255,255,255,0.3)';
        ctx.font = '7px monospace';
        ctx.textAlign = 'center';
        ctx.fillText('GR', width / 2, height - 1);
    }, [grDb, inputDb, outputDb, width, height, accentColor]);

    return (
        <canvas
            ref={canvasRef}
            style={{ width, height }}
            className="rounded border border-border/20"
            aria-label="Gain reduction meter"
            role="meter"
        />
    );
};

