                                />
                            </Row>
                            <Row wrap gap={1.5}>
                                {(['rms', 'peak'] as const).map((mode) => {
                                    const active = patch.detection === mode;
                                    return (
                                        <DawPluginChip
                                            key={mode}
                                            active={active}
                                            tone="lavender"
                                            size="sm"
                                            onClick={() => setGlutenParamWithAudio(deviceId, 'detection', mode)}
