                                })}
                                {(['stereo', 'mid', 'side', 'dual-mono'] as const).map((mode) => {
                                    const active = patch.stereoMode === mode;
                                    return (
                                        <DawPluginChip
                                            key={mode}
                                            active={active}
                                            tone="lavender"
