                                            key={thrust}
                                            active={active}
                                            tone="lavender"
                                            size="sm"
                                            onClick={() => setGlutenParamWithAudio(deviceId, 'thrust', thrust)}
                                        >
                                            {labels[thrust]}
                                        </DawPluginChip>
                                    );
                                })}
                            </Row>
                        </Stack>
                    </ControlCard>

                    <ControlCard title="Character" detail="The last mile changes with the topology you picked.">
                        {patch.topology === 'fet' ? (
                            <Stack gap={3}>
                                <Grid cols={3} gapX={2} gapY={3}>
                                    <Knob
                                        deviceId={deviceId}
                                        value={patch.inputGain}
                                        param="inputGain"
                                        label="Input"
                                        min={-12}
                                        max={24}
                                        step={0.5}
                                        defaultValue={0}
                                        unit="dB"
                                    />
                                    <Knob
                                        deviceId={deviceId}
                                        value={patch.outputGain}
                                        param="outputGain"
                                        label="Output"
                                        min={-24}
                                        max={24}
                                        step={0.5}
                                        defaultValue={0}
                                        unit="dB"
                                    />
                                    <Knob
                                        deviceId={deviceId}
                                        value={patch.xfmrDrive}
                                        param="xfmrDrive"
                                        label="Xfmr"
                                        min={0}
                                        max={3}
                                        step={0.01}
                                        defaultValue={1.2}
                                    />
                                    <Knob
                                        deviceId={deviceId}
                                        value={patch.jfetK3}
                                        param="jfetK3"
                                        label="Odd"
                                        min={0}
                                        max={0.5}
                                        step={0.01}
                                        defaultValue={0.15}
                                    />
                                    <Knob
                                        deviceId={deviceId}
                                        value={patch.xfmrK2}
                                        param="xfmrK2"
                                        label="Even"
                                        min={0}
                                        max={0.3}
                                        step={0.01}
                                        defaultValue={0}
                                    />
                                </Grid>
                                <ToggleChip
                                    label="All buttons"
                                    active={patch.allButtons}
                                    accentColor={accentColor}
                                    onClick={() => setGlutenParamWithAudio(deviceId, 'allButtons', !patch.allButtons)}
                                />
                            </Stack>
                        ) : null}

                        {patch.topology === 'opto' ? (
                            <Stack gap={2}>
                                <Row wrap gap={1.5}>
                                    {[false, true].map((mode, index) => {
                                        const labels = ['Compress', 'Limit'];
                                        const active = patch.limitMode === mode;
                                        return (
                                            <ToggleChip
                                                key={labels[index]}
                                                label={labels[index] ?? ''}
                                                active={active}
                                                accentColor={accentColor}
                                                onClick={() => setGlutenParamWithAudio(deviceId, 'limitMode', mode)}
                                            />
                                        );
                                    })}
                                </Row>
                                <p className="text-[10px] leading-4 text-muted-foreground">
                                    Limit leans harder on the cell. Compress lets it breathe.
                                </p>
                            </Stack>
                        ) : null}

                        {patch.topology === 'diode' ? (
                            <Stack gap={2}>
                                <Row wrap gap={1.5}>
                                    {[1, 2, 3, 4, 5].map((value) => {
                                        const active = patch.recovery === value;
                                        return (
                                            <ToggleChip
                                                key={value}
                                                label={`Recovery ${value}`}
                                                active={active}
                                                accentColor={accentColor}
                                                onClick={() => setGlutenParamWithAudio(deviceId, 'recovery', value)}
                                            />
                                        );
                                    })}
                                </Row>
                                <p className="text-[10px] leading-4 text-muted-foreground">
                                    Lower values grab harder. Higher values relax into the tail.
                                </p>
                            </Stack>
                        ) : null}

                        {patch.topology === 'vca' ? (
                            <Stack gap={3}>
                                <Grid cols={2} gap={2}>
                                    <Knob
                                        deviceId={deviceId}
                                        value={patch.vcaCharacter}
                                        param="vcaCharacter"
                                        label="Color"
                                        min={0}
                                        max={0.02}
                                        step={0.001}
                                        defaultValue={0.003}
                                    />
                                    <Knob
                                        deviceId={deviceId}
                                        value={patch.vcaType}
                                        param="vcaType"
                                        label="VCA type"
                                        min={0}
                                        max={2}
                                        step={1}
                                        defaultValue={1}
                                    />
                                </Grid>
                                <Row wrap gap={1.5}>
                                    {[false, true].map((mode, index) => {
                                        const labels = ['Feedback', 'Feed forward'];
                                        const active = patch.feedForward === mode;
                                        return (
                                            <ToggleChip
                                                key={labels[index]}
                                                label={labels[index] ?? ''}
                                                active={active}
                                                accentColor={accentColor}
                                                onClick={() => setGlutenParamWithAudio(deviceId, 'feedForward', mode)}
                                            />
                                        );
                                    })}
                                </Row>
                            </Stack>
                        ) : null}
                    </ControlCard>

                    <ControlCard title="Stage two" detail="Blend a second topology in when the first one needs backup.">
                        <Row wrap gap={1.5}>
                            {stageTwoOptions.map((topology) => {
                                const active = patch.blendTopology === topology;
                                return (
                                    <ToggleChip
                                        key={topology}
                                        label={TOPOLOGY_META[topology].label}
                                        active={active}
                                        accentColor={accentColor}
                                        onClick={() => setGlutenParamWithAudio(deviceId, 'blendTopology', topology)}
                                    />
                                );
                            })}
                        </Row>
                    </ControlCard>
                </DawPluginRail>
            </div>
        </div>
    );
};

