import { persistDeviceParam, getAllTracks } from '#/modules/Arrangement/useCases';
import { updateDeviceParam } from '#/modules/AudioEngine/useCases';
import { createFindDeviceRef, type DeviceRef, type GetAllTracksFn } from '#/utils/createFindDeviceRef';
import { createRafBatcher, type RafBatcher } from '#/utils/DOM/createRafBatcher';

export { createFindDeviceRef };
export type { DeviceRef, GetAllTracksFn };

// §33.2 — Shared rAF-batch primitive instead of a per-bridge mutable
// `pendingUpdates` / `latestValues` Map pair. The batcher keeps the
// last-write-wins semantics but the mechanics live in one place.
export type GlutenBatchEntry = { ref: DeviceRef; key: string; value: number };
export const paramBatcher: RafBatcher<GlutenBatchEntry> = createRafBatcher<GlutenBatchEntry>();

export type BridgeDeps = {
    updateDeviceParam: typeof updateDeviceParam;
    persistDeviceParam: typeof persistDeviceParam;
};

export function createFlushHandlers(deps: BridgeDeps) {
    function flushParam(_compositeKey: string, entry: GlutenBatchEntry): void {
        deps.updateDeviceParam(entry.ref.trackId, entry.ref.deviceId, entry.key, entry.value);
        deps.persistDeviceParam(entry.ref.deviceId, entry.key, entry.value);
    }

    function pushParamImmediately(ref: DeviceRef, key: string, value: number): void {
        deps.updateDeviceParam(ref.trackId, ref.deviceId, key, value);
        deps.persistDeviceParam(ref.deviceId, key, value);
    }

    return { flushParam, pushParamImmediately };
}

export const bridgeDeps: BridgeDeps = { updateDeviceParam, persistDeviceParam };
export const { flushParam, pushParamImmediately } = createFlushHandlers(bridgeDeps);
export const findDeviceRefGluten = createFindDeviceRef(getAllTracks);

export const TOPOLOGY_INDEX = {
    vca: 0,
    opto: 1,
    fet: 2,
    diode: 3,
} as const;

export const STYLE_INDEX = {
    glue: 0,
    punch: 1,
    smooth: 2,
    pump: 3,
} as const;

export const DETECTION_INDEX = {
    rms: 0,
    peak: 1,
} as const;

export const STEREO_MODE_INDEX = {
    stereo: 0,
    mid: 1,
    side: 2,
    'dual-mono': 3,
} as const;

export function encodeGlutenValue(key: string, value: unknown): number | null {
    if (typeof value === 'number') {
        return value;
    }

    if (typeof value === 'boolean') {
        return value ? 1 : 0;
    }

    if (typeof value !== 'string') {
        return null;
    }

    if (key === 'topology' || key === 'blendTopology') {
        return TOPOLOGY_INDEX[value as keyof typeof TOPOLOGY_INDEX] ?? 0;
    }

    if (key === 'style') {
        return STYLE_INDEX[value as keyof typeof STYLE_INDEX] ?? 0;
    }

    if (key === 'detection') {
        return DETECTION_INDEX[value as keyof typeof DETECTION_INDEX] ?? 0;
    }

    if (key === 'stereoMode') {
        return STEREO_MODE_INDEX[value as keyof typeof STEREO_MODE_INDEX] ?? 0;
    }

    return null;
}

/**
 * Per-note physical parameter overrides for the Grand Boule piano (§3.1).
 *
 * Each key (1–88) may carry up to 8 multiplier parameters that deviate from
 * the global voicing curve. All values are multipliers where 1.0 = neutral
 * (follow global preset). The engine receives them via the naming convention
 * `perNote.{key}.{param}`.
 */

import { NOTE_NAMES } from '#/utils/noteNames';

/** Descriptor for a single per-note parameter (metadata for UI). */
export type PerNoteParamDescriptor = {
    readonly key: keyof GrandBoulePerNoteValues;
    readonly label: string;
    readonly min: number;
    readonly max: number;
    readonly defaultValue: number;
    readonly step: number;
    readonly unit: string;
};

/** The adjustable per-note parameter values. */
export type GrandBoulePerNoteValues = {
    /** Multiplier on hammer stiffness K. */
    hammerHardness: number;
    /** Multiplier on hammer mass. */
    hammerMass: number;
    /** Multiplier on inharmonicity B. */
    stringStiffness: number;
    /** Coupling strength to soundboard (0 = disconnected). */
    bridgeCoupling: number;
    /** Damper bandwidth multiplier. */
    damperFirmness: number;
    /** Per-note sympathetic contribution. */
    sympatheticGain: number;
    /** Multiplier on hammer strike ratio. */
    strikePosition: number;
    /** Partial amplitude tilt (1.0 = neutral). */
    toneBrightness: number;
};

/** Full per-note map: key number (1–88) to parameter values. */
export type GrandBoulePerNoteMap = Map<number, GrandBoulePerNoteValues>;

export const PER_NOTE_PARAM_DESCRIPTORS: readonly PerNoteParamDescriptor[] = [
    { key: 'hammerHardness', label: 'Hammer', min: 0.5, max: 2.0, defaultValue: 1.0, step: 0.01, unit: '×' },
    { key: 'hammerMass', label: 'Mass', min: 0.5, max: 2.0, defaultValue: 1.0, step: 0.01, unit: '×' },
    { key: 'stringStiffness', label: 'Stiffness', min: 0.5, max: 2.0, defaultValue: 1.0, step: 0.01, unit: '×' },
    { key: 'bridgeCoupling', label: 'Bridge', min: 0.0, max: 2.0, defaultValue: 1.0, step: 0.01, unit: '×' },
    { key: 'damperFirmness', label: 'Damper', min: 0.5, max: 2.0, defaultValue: 1.0, step: 0.01, unit: '×' },
    { key: 'sympatheticGain', label: 'Sympath', min: 0.0, max: 2.0, defaultValue: 1.0, step: 0.01, unit: '×' },
    { key: 'strikePosition', label: 'Strike', min: 0.5, max: 1.5, defaultValue: 1.0, step: 0.01, unit: '×' },
    { key: 'toneBrightness', label: 'Bright', min: 0.5, max: 2.0, defaultValue: 1.0, step: 0.01, unit: '×' },
] as const;

export function createDefaultPerNoteValues(): GrandBoulePerNoteValues {
    return {
        hammerHardness: 1.0,
        hammerMass: 1.0,
        stringStiffness: 1.0,
        bridgeCoupling: 1.0,
        damperFirmness: 1.0,
        sympatheticGain: 1.0,
        strikePosition: 1.0,
        toneBrightness: 1.0,
    };
}

/** Convert a MIDI note (21–108) to a piano key number (1–88). */
export function midiNoteToKey(midiNote: number): number {
    return midiNote - 20;
}

/** Convert a piano key number (1–88) to a MIDI note (21–108). */
export function keyToMidiNote(key: number): number {
    return key + 20;
}

/**
 * Build the note name for display (e.g. "A0", "C4", "C8").
 * Key 1 = A0 (MIDI 21), Key 88 = C8 (MIDI 108).
 */
export function keyToNoteName(key: number): string {
    const midiNote = keyToMidiNote(key);
    const name = NOTE_NAMES[midiNote % 12];
    const octave = Math.floor(midiNote / 12) - 1;
    return `${name}${octave}`;
}

