                />
                <GrinderKnob
                    deviceId={deviceId}
                    value={patch.bass}
                    param="bass"
                    label="Bass"
                    min={0}
                    max={10}
                    step={0.1}
                    defaultValue={5}
                />
                <GrinderKnob
                    deviceId={deviceId}
                    value={patch.mid}
                    param="mid"
                    label="Mid"
                    min={0}
                    max={10}
