                    <div className="text-[10px] uppercase tracking-[0.24em] text-[var(--color-accent-amber)]">
                        Voice switches
                    </div>
                    <div className="flex gap-2">
                        {[0, 1, 2].map((channel) => (
                            <DawPluginChip
                                key={channel}
                                active={patch.channel === channel}
