                            >
                                {rectifier}
                            </DawPluginChip>
                        ))}
                    </div>
                </div>
            </div>
        );
    }

    if (patch.uiSection === 'drive') {
        return <DriveDeck deviceId={deviceId} patch={patch} />;
    }

    if (patch.uiSection === 'cab') {
        return (
            <div className="flex flex-wrap gap-3">
                <GrinderKnob
                    deviceId={deviceId}
                    value={patch.cabResonanceFreq}
                    param="cabResonanceFreq"
                    label="Res Freq"
                    min={40}
                    max={200}
                    step={1}
                    defaultValue={80}
                    unit="Hz"
                />
                <GrinderKnob
                    deviceId={deviceId}
                    value={patch.cabResonanceQ}
                    param="cabResonanceQ"
                    label="Res Q"
                    min={0.5}
                    max={10}
                    step={0.1}
                    defaultValue={2}
                />
                <GrinderKnob
                    deviceId={deviceId}
                    value={patch.cabDamping}
                    param="cabDamping"
                    label="Damping"
                    min={0}
                    max={1}
                    step={0.01}
                    defaultValue={0.5}
                />
                <GrinderKnob
                    deviceId={deviceId}
                    value={patch.coneBreakup}
                    param="coneBreakup"
                    label="Breakup"
                    min={0}
                    max={1}
                    step={0.01}
                    defaultValue={0.3}
                />
                <GrinderKnob
                    deviceId={deviceId}
                    value={patch.backEmf}
                    param="backEmf"
                    label="Back EMF"
                    min={0}
                    max={1}
                    step={0.01}
                    defaultValue={0.2}
                />
                <div className="grinder-window flex min-w-[210px] flex-col gap-3 px-3 py-3">
                    <div className="text-[10px] uppercase tracking-[0.24em] text-[var(--color-accent-cyan)]">
                        Cab toggles
                    </div>
                    <div className="flex gap-2">
                        <DawPluginToggle
                            pressed={patch.cabEnabled}
                            tone="cyan"
                            size="sm"
                            onClick={() => replacePatch({ ...patch, cabEnabled: !patch.cabEnabled })}
                        >
                            {patch.cabEnabled ? 'Cab Enabled' : 'Cab Bypassed'}
                        </DawPluginToggle>
                        <DawPluginToggle
                            pressed={patch.cabOpenBack}
                            tone="peach"
                            size="sm"
                            onClick={() => replacePatch({ ...patch, cabOpenBack: !patch.cabOpenBack })}
                        >
                            {patch.cabOpenBack ? 'Open Back' : 'Closed Back'}
                        </DawPluginToggle>
                    </div>
                </div>
            </div>
        );
    }

    if (patch.uiSection === 'neural') {
        return (
            <div className="flex flex-wrap gap-3">
                <div className="grinder-window flex min-w-[280px] flex-col gap-3 px-3 py-3">
