                                key={mode.id}
                                type="button"
                                className={`rounded-[16px] border px-3 py-3 text-left ${
                                    patch.engineMode === mode.id
                                        ? 'border-[var(--color-accent-lavender)]/60 bg-[var(--color-accent-lavender)]/12'
                                        : 'border-white/8 bg-black/20'
                                }`}
                                onClick={() =>
                                    replacePatch({
                                        ...patch,
