export function createDefaultPatch(instrumentId: InstrumentId = 'violin-1'): LevainPatch {
    const family = getInstrumentFamily(instrumentId);

    return {
        version: 1,
        name: `${instrumentId} Init`,
        instrumentId,
        instrumentFamily: family,
        keyRange: getDefaultKeyRange(instrumentId),
        articulations: getDefaultArticulations(family),
        currentArticulation: 'sustain',
        micPositions: DEFAULT_MIC_POSITIONS.map((m) => ({ ...m })),
        expression: { ...DEFAULT_EXPRESSION_CONFIG },
        legato: { ...DEFAULT_LEGATO_CONFIG },
        humanize: { ...DEFAULT_HUMANIZE_CONFIG },
        releaseTriggers: { ...DEFAULT_RELEASE_TRIGGER_CONFIG },
        masterGain: 0.8,
        macros: [0.5, 1.0, 0.0, 0.5, 0.5, 0.5, 0.5, 0.5],
        macroLabels: ['Dynamics', 'Expression', 'Vibrato', 'Tightness', 'Space', 'Tone', 'Attack', 'Release'],
    };
}

function getInstrumentFamily(id: InstrumentId): InstrumentFamily {
    // Order matters: check specific matches before broad ones.
    // Choir must come before strings (to catch 'bass-voice' before 'bass').
    if (id === 'soprano' || id === 'alto' || id === 'tenor' || id === 'bass-voice') {
        return 'choir';
    }
    // Woodwinds before brass (to catch 'english-horn' before 'horn').
    if (
        id.includes('flute') ||
        id.includes('oboe') ||
        id.includes('clarinet') ||
        id.includes('bassoon') ||
        id.includes('piccolo') ||
        id === 'english-horn' ||
        id === 'bass-clarinet' ||
        id === 'contrabassoon'
    ) {
        return 'woodwinds';
    }
    if (id.includes('violin') || id.includes('viola') || id.includes('cello') || id === 'double-bass') {
        return 'strings';
    }
    if (
        id === 'trumpet' ||
        id === 'solo-trumpet' ||
        id === 'horn' ||
        id === 'solo-horn' ||
        id.includes('trombone') ||
        id.includes('tuba')
    ) {
        return 'brass';
    }
    return 'percussion';
}

function getDefaultKeyRange(id: InstrumentId): [number, number] {
    switch (id) {
        case 'violin-1':
        case 'violin-2':
        case 'solo-violin':
            return [55, 103]; // G3-G7
        case 'viola':
        case 'solo-viola':
            return [48, 93]; // C3-A6
        case 'cello':
        case 'solo-cello':
            return [36, 84]; // C2-C6
        case 'double-bass':
            return [28, 67]; // E1-G4
        case 'trumpet':
        case 'solo-trumpet':
            return [54, 82]; // F#3-Bb5
        case 'horn':
        case 'solo-horn':
            return [34, 77]; // Bb1-F5
        case 'trombone':
            return [40, 72]; // E2-C5
        case 'tuba':
            return [28, 60]; // E1-C4
        case 'flute':
            return [60, 96]; // C4-C7
        case 'oboe':
            return [58, 91]; // Bb3-G6
        case 'clarinet':
            return [50, 91]; // D3-G6
        case 'bassoon':
            return [34, 75]; // Bb1-Eb5
        case 'piccolo':
            return [74, 108]; // D5-C8
        case 'glockenspiel':
            return [72, 108]; // C5-C8
        case 'xylophone':
        case 'marimba':
            return [45, 96]; // A2-C7
        case 'vibraphone':
            return [53, 89]; // F3-F6
        case 'timpani':
            return [36, 57]; // C2-A3
        default:
            return [21, 108]; // full range
    }
}

function getDefaultArticulations(family: InstrumentFamily): ArticulationEntry[] {
    switch (family) {
        case 'strings':
            return [
                { type: 'sustain', keyswitch: 24, name: 'Long', enabled: true },
                { type: 'sustain-non-vib', keyswitch: 25, name: 'Long (nv)', enabled: true },
                { type: 'tremolo', keyswitch: 26, name: 'Tremolo', enabled: true },
                { type: 'trill-half', keyswitch: 27, name: 'Trill (half)', enabled: true },
                { type: 'spiccato', keyswitch: 28, name: 'Spiccato', enabled: true },
                { type: 'staccato', keyswitch: 29, name: 'Staccato', enabled: true },
                { type: 'pizzicato', keyswitch: 30, name: 'Pizzicato', enabled: true },
                { type: 'legato', keyswitch: 31, name: 'Legato', enabled: true },
                { type: 'legato-portamento', keyswitch: 32, name: 'Portamento', enabled: true },
                { type: 'con-sordino', keyswitch: 33, name: 'Con sordino', enabled: true },
                { type: 'flautando', keyswitch: 34, name: 'Flautando', enabled: true },
                { type: 'col-legno', keyswitch: 35, name: 'Col legno', enabled: true },
            ];
        case 'brass':
            return [
                { type: 'sustain', keyswitch: 24, name: 'Long', enabled: true },
                { type: 'sustain-non-vib', keyswitch: 25, name: 'Long (nv)', enabled: true },
                { type: 'staccato', keyswitch: 26, name: 'Staccato', enabled: true },
                { type: 'marcato', keyswitch: 27, name: 'Marcato', enabled: true },
                { type: 'sforzando', keyswitch: 28, name: 'Sforzando', enabled: true },
                { type: 'legato', keyswitch: 29, name: 'Legato', enabled: true },
                { type: 'flutter-tongue', keyswitch: 30, name: 'Flutter', enabled: true },
                { type: 'muted-straight', keyswitch: 31, name: 'Muted', enabled: true },
            ];
        case 'woodwinds':
            return [
                { type: 'sustain', keyswitch: 24, name: 'Long', enabled: true },
                { type: 'staccato', keyswitch: 25, name: 'Staccato', enabled: true },
                { type: 'legato', keyswitch: 26, name: 'Legato', enabled: true },
                { type: 'trill-half', keyswitch: 27, name: 'Trill (half)', enabled: true },
                { type: 'flutter-tongue', keyswitch: 28, name: 'Flutter', enabled: true },
            ];
        case 'percussion':
            return [{ type: 'sustain', keyswitch: null, name: 'Hit', enabled: true }];
        case 'choir':
            return [
                { type: 'sustain', keyswitch: 24, name: 'Ah', enabled: true },
                { type: 'sustain-non-vib', keyswitch: 25, name: 'Oh', enabled: true },
                { type: 'staccato', keyswitch: 26, name: 'Staccato', enabled: true },
            ];
    }

    return [];
}

/**
 * ArticulationList — visual grid of articulation cards.
 *
 * Level 2: full-width grid for quick switching.
 * Level 3+: compact sidebar list.
 */
import { type ReactElement } from 'react';

import { DawPluginChip } from '#/components/daw/DawPluginChip';

import { type ArticulationEntry, type ArticulationType } from '../../models/LevainPatch';

type ArticulationListProps = {
    articulations: ArticulationEntry[];
    current: ArticulationType;
    grid?: boolean;
    onSelect: (type: ArticulationType) => void;
};

const midiNoteToName = (note: number): string => {
    const names = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];
    const octave = Math.floor(note / 12) - 1;
    return `${names[note % 12]}${octave}`;
};

export const ArticulationList = ({ articulations, current, grid, onSelect }: ArticulationListProps): ReactElement => {
    const enabled = articulations.filter((a) => a.enabled);

    if (grid) {
        return (
            <div className="grid grid-cols-3 gap-1.5 p-2">
                {enabled.map((art) => {
                    const isActive = art.type === current;
                    return (
                        <DawPluginChip
                            key={art.type}
                            active={isActive}
                            tone="amber"
                            caps={false}
                            shape="soft"
                            className="flex flex-col gap-0.5 px-2 py-2"
                            onClick={() => onSelect(art.type)}
                        >
                            <span className="text-[10px] font-medium leading-tight">{art.name}</span>
                            {art.keyswitch !== null ? (
                                <span className="text-[7px] text-muted-foreground/50 tabular-nums">
                                    {midiNoteToName(art.keyswitch)}
                                </span>
                            ) : null}
                        </DawPluginChip>
                    );
                })}
            </div>
        );
    }

    // Compact sidebar list
    return (
        <div className="flex flex-col gap-0 p-1">
            <span className="text-[8px] text-muted-foreground/50 uppercase tracking-wider px-2 py-1">
                Articulations
            </span>
            {enabled.map((art) => {
                const isActive = art.type === current;
                return (
                    <DawPluginChip
                        key={art.type}
                        active={isActive}
                        tone="amber"
                        caps={false}
                        className="flex w-full items-center justify-between px-2 py-1 text-[10px]"
                        onClick={() => onSelect(art.type)}
                    >
                        <span>{art.name}</span>
                        {art.keyswitch !== null ? (
                            <span className="text-[8px] text-muted-foreground/40 tabular-nums">
                                {midiNoteToName(art.keyswitch)}
                            </span>
                        ) : null}
                    </DawPluginChip>
                );
            })}
        </div>
    );
};

/**
 * MicBlendSlider — mic position mixing with Faders.
 *
 * Compact: single knob for Close vs Room blend.
 * Full: per-mic Fader strips with volume, pan, enable toggle.
 *
 * NOTE: `onSendMicParam` is passed from the parent view so this component
 * does NOT import from useCases/ directly (DDD: components/ is private).
 */
import { type ReactElement } from 'react';

import { DawPluginSectionHeader } from '#/components/daw/DawPluginSectionHeader';
import { DawPluginToggle } from '#/components/daw/DawPluginToggle';
import { Fader } from '#/components/daw/Fader';
import { RotaryKnob } from '#/components/daw/RotaryKnob';

import { type MicPositionState } from '../../models/LevainPatch';

type MicBlendSliderProps = {
    micPositions: MicPositionState[];
    showFull?: boolean;
    /** Forward mic param changes to the audio engine. Provided by the parent view. */
    onSendMicParam: (micIndex: number, param: string, value: number) => void;
    /** Update mic position state. Provided by the parent view. */
    onUpdateMicPosition: (index: number, updates: Partial<MicPositionState>) => void;
};

export const MicBlendSlider = ({
    micPositions,
    showFull,
    onSendMicParam,
    onUpdateMicPosition,
}: MicBlendSliderProps): ReactElement => {
    if (showFull) {
        // Full mic mixer with faders
        return (
            <div className="space-y-3 max-w-[400px]">
                <DawPluginSectionHeader title="Mic Positions" titleClassName="text-muted-foreground" />
                <div className="flex gap-3 items-end">
                    {micPositions.map((mic, i) => (
                        <div key={i} className="flex flex-col items-center gap-1">
                            <DawPluginToggle
                                pressed={mic.enabled}
                                tone="amber"
                                size="xs"
                                onClick={() => {
                                    const enabled = !mic.enabled;
                                    onUpdateMicPosition(i, { enabled });
                                    onSendMicParam(i, 'enabled', enabled ? 1.0 : 0.0);
                                }}
                            >
                                {mic.enabled ? 'ON' : 'OFF'}
                            </DawPluginToggle>
                            <Fader
                                value={mic.enabled ? mic.volume * 76 - 70 : -70}
                                onChange={(db) => {
                                    const volume = Math.max(0, Math.min(1, (db + 70) / 76));
                                    onUpdateMicPosition(i, { volume });
                                    onSendMicParam(i, 'volume', volume);
                                }}
                                min={-70}
                                max={6}
                                defaultValue={-6}
                                height={100}
                            />
                            <RotaryKnob
                                value={mic.pan}
                                onChange={(v) => {
                                    onUpdateMicPosition(i, { pan: v });
                                    onSendMicParam(i, 'pan', v);
                                }}
                                min={-1}
                                max={1}
                                step={0.01}
                                defaultValue={0}
                                bipolar
                                size="sm"
                                tone="amber"
                            />
                            <span className="text-[7px] text-muted-foreground/60 uppercase tracking-wider leading-tight text-center">
                                {mic.name}
                            </span>
                        </div>
                    ))}
                </div>
            </div>
        );
    }

    // Compact: single Close/Room blend knob
    const closeVol = micPositions[0]?.volume ?? 0.8;
    const roomVol = micPositions.length > 2 ? (micPositions[2]?.volume ?? 0.3) : 0.3;
    const blend = roomVol / (closeVol + roomVol + 0.001);

    return (
        <div className="space-y-1">
            <DawPluginSectionHeader title="Space" size="xs" titleClassName="text-muted-foreground/50" />
            <div className="flex flex-col items-center gap-0">
                <RotaryKnob
                    value={blend}
                    onChange={(v) => {
                        const newCloseVol = 1.0 - v * 0.5;
                        const newRoomVol = v;
                        onUpdateMicPosition(0, { volume: newCloseVol });
                        onSendMicParam(0, 'volume', newCloseVol);
                        if (micPositions.length > 2) {
                            onUpdateMicPosition(2, { volume: newRoomVol, enabled: newRoomVol > 0.05 });
                            onSendMicParam(2, 'volume', newRoomVol);
                            onSendMicParam(2, 'enabled', newRoomVol > 0.05 ? 1.0 : 0.0);
                        }
                    }}
                    tone="amber"
                    min={0}
                    max={1}
                    step={0.01}
                    defaultValue={0.3}
                    size="md"
                />
                <div className="flex justify-between w-full px-1">
                    <span className="text-[6px] text-muted-foreground/40">Close</span>
                    <span className="text-[6px] text-muted-foreground/40">Room</span>
                </div>
            </div>
        </div>
    );
};

