// ---------------------------------------------------------------------------
// LOD configuration
// ---------------------------------------------------------------------------

export type SampleLodConfig = {
    /** Maximum mic positions to load (0 = all). */
    maxMics: number;
    /** Maximum velocity layers per articulation (0 = all). */
    maxVelLayers: number;
    /** Maximum round-robin groups (0 = all). */
    maxRoundRobins: number;
    /** Disable legato transition samples. */
    disableTransitions: boolean;
};

export const WEB_LOD: SampleLodConfig = {
    maxMics: 2,
    maxVelLayers: 3,
    maxRoundRobins: 3,
    disableTransitions: false,
};

export // ---------------------------------------------------------------------------
// Audio decoding
// ---------------------------------------------------------------------------

/**
 * Fetch and decode an audio file to Float32 PCM.
 * Returns { data, frameCount, channels, sampleRate }.
 * Uses a fresh OfflineAudioContext per decode to avoid state issues.
 */
// Use a single global context for decoding to avoid WKWebView context limits.
let decodeCtx: OfflineAudioContext | null = null;

export function getDecodeContext(): OfflineAudioContext {
    if (!decodeCtx) {
        decodeCtx = new OfflineAudioContext(2, 44100, 44100);
    }
    return decodeCtx;
}

export // Global queue to prevent Safari from crashing on concurrent decode requests
let decodeQueue = Promise.resolve();

export async function fetchAndDecode(url: string): Promise<{
    data: Float32Array;
    frameCount: number;
    channels: number;
    sampleRate: number;
}> {
    const response = await fetch(url);
    if (!response.ok) {
        throw new Error(`Failed to fetch sample: ${url} (${response.status})`);
    }

    const arrayBuffer = await response.arrayBuffer();

    // Strictly sequence decoding to avoid WebKit EncodingError
    return new Promise((resolve, reject) => {
        decodeQueue = decodeQueue.then(async () => {
            try {
                const ctx = getDecodeContext();
                const audioBuffer = await ctx.decodeAudioData(arrayBuffer);
                const channels = audioBuffer.numberOfChannels;
                const frameCount = audioBuffer.length;
                const sampleRate = audioBuffer.sampleRate;

                const data = new Float32Array(frameCount * channels);
                for (let ch = 0; ch < channels; ch++) {
                    const channelData = audioBuffer.getChannelData(ch);
                    for (let i = 0; i < frameCount; i++) {
                        data[i * channels + ch] = channelData[i] ?? 0;
                    }
                }
                resolve({ data, frameCount, channels, sampleRate });
            } catch (error) {
                reject(error);
            }
            return;
        });
    });
}

import { logger } from '#/infra/logger/appLogger';

import { type ArticulationType } from '../../models/LevainPatch';

import { fetchAndDecode } from './helpers';

import type { SampleLodConfig } from './helpers';

export type ManifestZone = {
    file: string;
    rootNote: number;
    loKey: number;
    hiKey: number;
    loVel: number;
    hiVel: number;
    rrPos: number;
    rrLen: number;
    micId: number;
    isRelease: boolean;
    loopMode: 'none' | 'forward' | 'pingpong';
    loopStart: number;
    loopEnd: number;
    loopCrossfade: number;
    gainDb: number;
    attack: number;
    decay: number;
    sustain: number;
    release: number;
};

export type ManifestArticulation = {
    type: ArticulationType;
    id: number;
    zones: ManifestZone[];
};

// ---------------------------------------------------------------------------
// Manifest types (SFZ-style zone descriptions in JSON)
// ---------------------------------------------------------------------------

export type SampleManifest = {
    version: number;
    instrumentId: string;
    sampleRate: number;
    articulations: ManifestArticulation[];
    micPositions: string[];
};

export const DEFAULT_LOD: SampleLodConfig = {
    maxMics: 0,
    maxVelLayers: 0,
    maxRoundRobins: 0,
    disableTransitions: false,
};

// ---------------------------------------------------------------------------
// Manifest loader
// ---------------------------------------------------------------------------

/**
 * Load a complete instrument from a manifest file.
 * Sends addSample, addZone, and buildZoneMap messages to the worklet node.
 *
 * @param manifestUrl URL to the JSON manifest
 * @param basePath Base path for sample file URLs
 * @param nodePort The worklet node's MessagePort
 * @param lod LOD configuration for memory management
 * @param onProgress Optional progress callback (0-1)
 */
export async function loadInstrumentFromManifest(
    manifestUrl: string,
    basePath: string,
    nodePort: MessagePort,
    lod: SampleLodConfig = DEFAULT_LOD,
    onProgress?: (progress: number) => void
): Promise<void> {
    const response = await fetch(manifestUrl);
    if (!response.ok) {
        throw new Error(`Failed to fetch manifest: ${manifestUrl} (${response.status})`);
    }

    const manifest: SampleManifest = await response.json();

    // Collect all unique sample file URLs.
    const allZones: { zone: ManifestZone; artId: number }[] = [];
    let numMics = manifest.micPositions.length;
    const numArticulations = manifest.articulations.length;

    for (const art of manifest.articulations) {
        for (const zone of art.zones) {
            // Apply LOD filtering.
            if (lod.maxMics > 0 && zone.micId >= lod.maxMics) {
                continue;
            }
            if (lod.maxRoundRobins > 0 && zone.rrPos >= lod.maxRoundRobins) {
                continue;
            }
            allZones.push({ zone, artId: art.id });
        }
    }

    if (lod.maxMics > 0) {
        numMics = Math.min(numMics, lod.maxMics);
    }

    // Send clear command before adding new samples.
    nodePort.postMessage({ type: 'clearZones' });

    // Pre-assign a stable sampleId to every unique file so fetches can run
    // in parallel without racing on a shared counter. Path segments are
    // individually `encodeURIComponent`-ed so filenames containing `#`,
    // spaces, or other reserved characters don't 404.
    const sampleIdMap = new Map<string, number>();
    const uniqueFiles: string[] = [];
    for (const { zone } of allZones) {
        if (!sampleIdMap.has(zone.file)) {
            sampleIdMap.set(zone.file, uniqueFiles.length);
            uniqueFiles.push(zone.file);
        }
    }

    function encodePath(path: string): string {
        return path.split('/').map(encodeURIComponent).join('/');
    }

    let completed = 0;
    const total = uniqueFiles.length;
    const loadedFiles = new Set<string>();

    const results = await Promise.allSettled(
        uniqueFiles.map(async (file) => {
            const url = `${basePath}/${encodePath(file)}`;
            try {
                const decoded = await fetchAndDecode(url);
                return { file, decoded };
            } finally {
                completed++;
                if (onProgress) {
                    onProgress(completed / total);
                }
            }
        })
    );

    for (const result of results) {
        if (result.status === 'rejected') {
            logger.warn('[Levain] Failed to load sample:', result.reason);
            continue;
        }
        const { file, decoded } = result.value;
        const sampleId = sampleIdMap.get(file);
        if (sampleId === undefined) {
            continue;
        }
        const transferable = decoded.data.buffer;
        nodePort.postMessage(
            {
                type: 'addSample',
                sampleId,
                data: decoded.data,
                frameCount: decoded.frameCount,
                channels: decoded.channels,
                sampleRate: decoded.sampleRate,
            },
            [transferable]
        );
        loadedFiles.add(file);
    }

    // Send zone definitions. Skip zones whose sample file failed to load
    // — we pre-assigned every file a sampleId, so we can't rely on the map
    // alone to detect failures anymore.
    let zoneId = 0;
    for (const { zone, artId } of allZones) {
        const sampleId = sampleIdMap.get(zone.file);
        if (sampleId === undefined || !loadedFiles.has(zone.file)) {
            continue;
        }

        nodePort.postMessage({
            type: 'addZone',
            zoneId,
            sampleId,
            articulationId: artId,
            rootNote: zone.rootNote,
            loKey: zone.loKey,
            hiKey: zone.hiKey,
            loVel: zone.loVel,
            hiVel: zone.hiVel,
            rrPos: zone.rrPos,
            rrLen: zone.rrLen,
            micId: zone.micId,
            isRelease: zone.isRelease,
            loopMode: zone.loopMode,
            loopStart: zone.loopStart,
            loopEnd: zone.loopEnd,
            loopCrossfade: zone.loopCrossfade,
            gainDb: zone.gainDb,
            attack: zone.attack,
            decay: zone.decay,
            sustain: zone.sustain,
            release: zone.release,
        });
        zoneId++;
    }

    // Build the zone lookup table.
    nodePort.postMessage({
        type: 'buildZoneMap',
        numArticulations,
        numMics,
    });
}

import { resolveResource } from '@tauri-apps/api/path';

import { logger } from '#/infra/logger/appLogger';

import { WEB_LOD } from '../repositories/sampleLoader/helpers';
import { loadInstrumentFromManifest } from '../repositories/sampleLoader/loadInstrumentFromManifest';
import { setSampleLoadProgress } from '../stores/levainStore';

const isTauri = typeof window !== 'undefined' && '__TAURI_INTERNALS__' in window;

/**
 * Load levain samples for a specific instrument into the worklet node.
 * Automatically clears previous zones before loading.
 *
 * `instrumentId` is required — callers must pass the instrument from the
 * active patch (see `levainStore`). The previous silent default (`'violin-1'`)
 * caused the engine to eagerly load violin samples on every Levain node
 * construction regardless of which instrument the user had actually selected;
 * those samples would then race the patch-driven reload in `registerLevainDevice`.
 */
export async function autoLoadLevainSamples(nodePort: MessagePort, instrumentId: string): Promise<void> {
    let manifestBase = `/samples/levain/${instrumentId}`;

    // In Tauri desktop, we bypass the embedded frontend cache
    // and load massive 1.2GB sample banks straight from OS resources.
    if (isTauri) {
        try {
            // Tauri places parent-relative bundle assets under _up_ to protect the root Resources directory
            const localPath = await resolveResource(`_up_/public/samples/levain/${instrumentId}`);
            const { convertFileSrc } = (await import('@tauri-apps/api/core')) as unknown as {
                convertFileSrc: (p: string) => string;
            };
            manifestBase = convertFileSrc(localPath);
        } catch (error) {
            logger.warn('[Levain] Failed to resolve Tauri resource path:', error);
        }
    }

    const manifestUrl = `${manifestBase}/manifest.json`;

    setSampleLoadProgress(0.01); // trigger UI loading state

    try {
        await loadInstrumentFromManifest(manifestUrl, manifestBase, nodePort, WEB_LOD, (progress) => {
            setSampleLoadProgress(progress);
        });
    } catch (error) {
        logger.warn(`[Levain] Failed to load samples for ${instrumentId}:`, error);
        // Fallback sine tone will continue to work
    } finally {
        setSampleLoadProgress(1.0);
        setTimeout(() => setSampleLoadProgress(null), 300); // clear after short delay
    }
}

import { logger } from '#/infra/logger/appLogger';
import { type persistDeviceParam, type getAllTracks } from '#/modules/Arrangement/useCases';
import { createRafBatcher } from '#/utils/DOM/createRafBatcher';

import { type LevainPatch } from '../../models/LevainPatch';
import { levainStore, setLevainParam, setMacro } from '../../stores/levainStore';
import { type autoLoadLevainSamples } from '../autoLoadSamples';

export type LevainDevice = {
    setParam: (name: string, value: number) => void;
    handleCc: (cc: number, value: number) => void;
    setInstrument?: (instrumentId: string) => void;
};

export type LevainBridgeDeps = {
    getAllTracks: typeof getAllTracks;
    persistDeviceParam: typeof persistDeviceParam;
    autoLoadLevainSamples: typeof autoLoadLevainSamples;
};

export function camelToSnake(str: string): string {
    return str.replaceAll(/[A-Z]/g, (letter) => `_${letter.toLowerCase()}`);
}

export function createLevainBridge(deps: LevainBridgeDeps) {
    let activeDevice: LevainDevice | null = null;
    let activePort: MessagePort | null = null;
    let activeDeviceId: string | null = null;

    // §33.2 — Shared rAF-batch primitive. Last-write-wins per rustKey,
    // coalesced into one flush per animation frame.
    const paramBatcher = createRafBatcher<number>();

    function flushParam(rustKey: string, value: number): void {
        const device = getDevice();
        if (device) {
            device.setParam(rustKey, value);
        }
        if (activeDeviceId) {
            deps.persistDeviceParam(activeDeviceId, rustKey, value);
        }
    }

    function queueParam(rustKey: string, value: number): void {
        paramBatcher.schedule(rustKey, value, flushParam);
    }

    function getDevice(): LevainDevice | null {
        return activeDevice;
    }

    function loadSamplesForInstrument(instrumentId: string): void {
        // Tell the engine which instrument it now is, so the realism layer
        // (body modes, sympathetic strings, breath/bow noise) reconfigures.
        activeDevice?.setInstrument?.(instrumentId);
        if (!activePort) {
            return;
        }
        deps.autoLoadLevainSamples(activePort, instrumentId).catch((error) => {
            logger.warn('[LevainBridge] Sample load failed:', error);
        });
    }

    function registerLevainDevice(device: LevainDevice, port?: MessagePort): void {
        activeDevice = device;
        activeDeviceId = null;
        for (const track of deps.getAllTracks()) {
            const d = track.devices.find((dev) => dev.type === 'levain');
            if (d) {
                activeDeviceId = d.id;
                break;
            }
        }
        if (port) {
            activePort = port;
            const state = levainStore.value;
            if (state?.patch) {
                loadSamplesForInstrument(state.patch.instrumentId);
                queueParam('master_gain', state.patch.masterGain);
                queueParam('legato_enabled', state.patch.legato.enabled ? 1 : 0);
                queueParam('humanize_amount', state.patch.humanize.amount);
                queueParam('vibrato_depth', state.patch.expression.vibratoDepthMax);

                for (const [i, m] of state.patch.micPositions.entries()) {
                    queueParam(`mic_${i}_volume`, m.volume);
                    queueParam(`mic_${i}_pan`, m.pan);
                    queueParam(`mic_${i}_enabled`, m.enabled ? 1 : 0);
                }
            }
        }
    }

    function unregisterLevainDevice(): void {
        activeDevice = null;
        activePort = null;
        paramBatcher.cancelAll();
    }

    function setLevainParamWithAudio<K extends keyof LevainPatch>(key: K, value: LevainPatch[K]): void {
        setLevainParam(key, value);

        if (key === 'currentArticulation' && typeof value === 'string') {
            const patch = levainStore.value?.patch;
            if (patch) {
                const artIndex = patch.articulations.findIndex((a) => a.type === value);
                if (artIndex !== -1) {
                    queueParam('current_articulation', artIndex);
                }
            }
        } else if (typeof value === 'number') {
            const rustKey = camelToSnake(key as string);
            queueParam(rustKey, value);
        } else if (typeof value === 'boolean') {
            const rustKey = camelToSnake(key as string);
            queueParam(rustKey, value ? 1.0 : 0.0);
        } else if (typeof value === 'object' && value !== null) {
            for (const [childKey, childVal] of Object.entries(value)) {
                if (typeof childVal === 'number') {
                    const rustKey = `${camelToSnake(key as string)}_${camelToSnake(childKey)}`;
                    queueParam(rustKey, childVal);
                } else if (typeof childVal === 'boolean') {
                    const rustKey = `${camelToSnake(key as string)}_${camelToSnake(childKey)}`;
                    queueParam(rustKey, childVal ? 1.0 : 0.0);
                }
            }
        }
    }

    function setMacroWithAudio(index: number, value: number): void {
        setMacro(index, value);

        const device = getDevice();
        if (!device) {
            return;
        }

        const state = levainStore.value;
        if (!state) {
            return;
        }

        const label = state.patch.macroLabels[index];
        switch (label) {
            case 'Dynamics':
                device.handleCc(1, Math.round(value * 127));
                break;
            case 'Expression':
                device.handleCc(11, Math.round(value * 127));
                break;
            case 'Vibrato':
                device.handleCc(2, Math.round(value * 127));
                break;
            case 'Tightness':
                device.setParam('humanize', 1.0 - value);
                break;
            case 'Space':
                device.setParam('mic_0_volume', 1.0 - value * 0.5);
                device.setParam('mic_1_volume', value);
                break;
            case 'Tone':
                device.setParam('tone', value);
                break;
            case 'Attack':
                device.setParam('attack', value);
                break;
            case 'Release':
                device.setParam('release', value);
                break;
        }
    }

    function sendHumanizeToEngine(amount: number): void {
        const device = getDevice();
        if (device) {
            device.setParam('humanize', amount);
        }
    }

    function sendLegatoEnabledToEngine(enabled: boolean): void {
        const device = getDevice();
        if (device) {
            device.setParam('legato_enabled', enabled ? 1.0 : 0.0);
        }
    }

    function sendMicParamToEngine(micIndex: number, param: string, value: number): void {
        const device = getDevice();
        if (device) {
            device.setParam(`mic_${micIndex}_${param}`, value);
        }
    }

    return {
        registerLevainDevice,
        unregisterLevainDevice,
        loadSamplesForInstrument,
        setLevainParamWithAudio,
        setMacroWithAudio,
        sendHumanizeToEngine,
        sendLegatoEnabledToEngine,
        sendMicParamToEngine,
    };
}

