import { type MidiNote, type MidiCC } from '../models/MidiNote';
import { downloadBlob } from '../repositories/downloadFile';

const TICKS_PER_BEAT = 480;

function writeVarLen(value: number): number[] {
    const bytes: number[] = [];
    let value1 = value & 0x0fffffff;
    bytes.unshift(value1 & 0x7f);
    while (value1 > 0x7f) {
        value1 >>= 7;
        bytes.unshift((value1 & 0x7f) | 0x80);
    }
    return bytes;
}

function writeString(str: string): number[] {
    const bytes: number[] = [];
    for (let index = 0; index < str.length; index++) {
        bytes.push(str.charCodeAt(index));
    }
    return bytes;
}

function write32(value: number): number[] {
    return [(value >> 24) & 0xff, (value >> 16) & 0xff, (value >> 8) & 0xff, value & 0xff];
}

function write16(value: number): number[] {
    return [(value >> 8) & 0xff, value & 0xff];
}

type MidiEvent = {
    tick: number;
    data: number[];
};

function buildTrackEvents(notes: MidiNote[], ccs: MidiCC[], clipStartBeat: number, trackName: string): number[] {
    const events: MidiEvent[] = [];

    const nameBytes = writeString(trackName);
    events.push({
        tick: 0,
        data: [0xff, 0x03, ...writeVarLen(nameBytes.length), ...nameBytes],
    });

    for (const note of notes) {
        const startTick = Math.round((clipStartBeat + note.startBeat) * TICKS_PER_BEAT);
        const endTick = Math.round((clipStartBeat + note.startBeat + note.duration) * TICKS_PER_BEAT);
        const vel = Math.max(1, Math.min(127, Math.round(note.velocity)));
        const pitch = Math.max(0, Math.min(127, note.pitch));

        events.push({ tick: startTick, data: [0x90, pitch, vel] });
        events.push({ tick: endTick, data: [0x80, pitch, 0] });
    }

    for (const cc of ccs) {
        const tick = Math.round((clipStartBeat + cc.beat) * TICKS_PER_BEAT);
        const controller = Math.max(0, Math.min(127, cc.controller));
        const value = Math.max(0, Math.min(127, Math.round(cc.value)));
        events.push({ tick, data: [0xb0 | ((cc.channel ?? 0) & 0x0f), controller, value] });
    }

    events.sort((alpha, b) => alpha.tick - b.tick);

    const trackBytes: number[] = [];
    let lastTick = 0;
    for (const event of events) {
        const delta = Math.max(0, event.tick - lastTick);
        const deltaBytes = writeVarLen(delta);
        for (let index = 0; index < deltaBytes.length; index++) {
            trackBytes.push(deltaBytes[index]!);
        }
        for (let index = 0; index < event.data.length; index++) {
            trackBytes.push(event.data[index]!);
        }
        lastTick = event.tick;
    }

    const endDelta = writeVarLen(0);
    for (let index = 0; index < endDelta.length; index++) {
        trackBytes.push(endDelta[index]!);
    }
    trackBytes.push(0xff, 0x2f, 0x00);

    return trackBytes;
}

type DownloadMidiFileInput = {
    clipName: string;
    clipStartBeat: number;
    notes: MidiNote[];
    ccs: MidiCC[];
};

export function downloadMidiFile({ clipName, clipStartBeat, notes, ccs }: DownloadMidiFileInput): void {
    if (notes.length === 0 && ccs.length === 0) {
        return;
    }

    const trackData = buildTrackEvents(notes, ccs, clipStartBeat, clipName);
    const headerChunk = [
        ...writeString('MThd'),
        ...write32(6),
        ...write16(0),
        ...write16(1),
        ...write16(TICKS_PER_BEAT),
    ];

    const mtrk = writeString('MTrk');
    const trackLen = write32(trackData.length);
    const trackChunkLen = mtrk.length + trackLen.length + trackData.length;
    const totalLen = headerChunk.length + trackChunkLen;

    const bytes = new Uint8Array(totalLen);
    bytes.set(headerChunk, 0);
    let offset = headerChunk.length;
    bytes.set(mtrk, offset);
    offset += mtrk.length;
    bytes.set(trackLen, offset);
    offset += trackLen.length;
    bytes.set(trackData, offset);

    const sanitizedName = clipName.replaceAll(/[^a-zA-Z0-9_-]/g, '_').slice(0, 200);
    downloadBlob(bytes, `${sanitizedName}.mid`, 'audio/midi');
}

import { describe, it, expect, vi, beforeEach } from 'vitest';

import { applyGrooveToClip } from '../applyGrooveToClip';

const mocks = vi.hoisted(() => ({
    midiStoreValue: { value: { notesByClipId: {} } },
    midiStoreSet: vi.fn(),
}));

vi.mock('../../../stores/midiStore', () => ({
    midiStore: {
        get value() {
            return mocks.midiStoreValue.value;
        },
        set: mocks.midiStoreSet,
    },
}));

describe('applyGrooveToClip', () => {
    beforeEach(() => vi.clearAllMocks());

    it('shifts notes and scales velocities based on groove template', () => {
        const mockNotes = [
            { id: 'n1', startBeat: 0, velocity: 100, pitch: 60 }, // On grid (step 0)
            { id: 'n2', startBeat: 0.5, velocity: 100, pitch: 64 }, // On grid (step 2 if division is 0.25)
        ];
        mocks.midiStoreValue.value = { notesByClipId: { c1: mockNotes } } as any;

        const mockGroove = {
            gridDivision: 0.25,
            offsets: [
                { gridPosition: 0, timingOffset: 0.1, velocityScale: 1.2 },
                { gridPosition: 2, timingOffset: -0.05, velocityScale: 0.8 },
            ],
        };

        applyGrooveToClip('c1', mockGroove as any, 1.0);

        expect(mocks.midiStoreSet).toHaveBeenCalledTimes(1);
        const updated = mocks.midiStoreSet.mock.calls[0][0].notesByClipId.c1;

        // Note 1 (step 0): offset 0.1, vel scale 1.2
        expect(updated[0].startBeat).toBeCloseTo(0.1);
        expect(updated[0].velocity).toBe(120);

        // Note 2 (step 2): offset -0.05, vel scale 0.8
        expect(updated[1].startBeat).toBeCloseTo(0.45);
        expect(updated[1].velocity).toBe(80);
    });

    it('respects the amount parameter', () => {
        mocks.midiStoreValue.value = { notesByClipId: { c1: [{ id: 'n1', startBeat: 0, velocity: 100 }] } } as any;
        const mockGroove = {
            gridDivision: 0.25,
            offsets: [{ gridPosition: 0, timingOffset: 0.2, velocityScale: 1.5 }],
        };

        // Apply at 50%
        applyGrooveToClip('c1', mockGroove as any, 0.5);

        const updated = mocks.midiStoreSet.mock.calls[0][0].notesByClipId.c1;
        // timing: 0 + (0.2 * 0.5) = 0.1
        // velocity: 100 * (1 + (1.5 - 1) * 0.5) = 100 * 1.25 = 125
        expect(updated[0].startBeat).toBeCloseTo(0.1);
        expect(updated[0].velocity).toBe(125);
    });
});

import { describe, it, expect, vi, beforeEach } from 'vitest';

import { extractGrooveFromClip } from '../extractGrooveFromClip';

const mocks = vi.hoisted(() => ({
    midiStoreValue: { value: { notesByClipId: {} } },
}));

vi.mock('../../../stores/midiStore', () => ({
    midiStore: {
        get value() {
            return mocks.midiStoreValue.value;
        },
    },
}));

describe('extractGrooveFromClip', () => {
    beforeEach(() => vi.clearAllMocks());

    it('extracts timing and velocity deviations from notes', () => {
        // Implementation uses minBeat as the relative zero.
        // If notes are at 0.1 and 0.45:
        // minBeat = 0.1.
        // gridBeat 0 (i=0): 0.1 + 0 = 0.1. Note 1 is at 0.1. Offset = 0.
        // gridBeat 1 (i=1): 0.1 + 0.25 = 0.35. Note 2 is at 0.45. Offset = 0.1.
        mocks.midiStoreValue.value = {
            notesByClipId: {
                c1: [
                    { startBeat: 0.1, duration: 1, velocity: 120 },
                    { startBeat: 0.45, duration: 1, velocity: 80 },
                ],
            },
        } as any;

        const groove = extractGrooveFromClip('c1', 0.25);

        expect(groove).not.toBeNull();

        // Offset 0 for the first note (which defines the minBeat reference)
        expect(groove?.offsets).toContainEqual(
            expect.objectContaining({
                gridPosition: 0,
                timingOffset: 0,
                velocityScale: 1.2,
            })
        );

        // Offset 0.1 for the second note relative to the shifted grid
        expect(groove?.offsets).toContainEqual(
            expect.objectContaining({
                gridPosition: 1, // 0.1 + 0.25 = 0.35. Wrapped index 1 if division is 0.25?
                // Wait, wrappedIndex = i % (1/0.25) = i % 4.
                // i=1. Index 1.
                timingOffset: expect.closeTo(0.1),
                velocityScale: 0.8,
            })
        );
    });

    it('bails if no notes in clip', () => {
        mocks.midiStoreValue.value = { notesByClipId: { c1: [] } } as any;
        expect(extractGrooveFromClip('c1')).toBeNull();
    });
});

