self.onmessage = (event) => {
    const { type, payload } = event.data;

    if (type === 'runScript') {
        const { code } = payload;
        try {
            // SECURITY NOTE: using new Function() in a Worker provides basic isolation
            // but is not a full secure sandbox. Production usage should use a more
            // robust isolation mechanism if running untrusted third-party scripts.
            console.log('Running controller script...');

            // API provided to the script
            const DAW = {
                setParam: (trackId: string, deviceId: string, paramId: string, value: number) => {
                    self.postMessage({ type: 'setParam', payload: { trackId, deviceId, paramId, value } });
                },
                sendMidi: (bytes: number[]) => {
                    self.postMessage({ type: 'sendMidi', payload: { bytes } });
                },
            };

            // Execute
            const scriptFunc = new Function('DAW', code);
            scriptFunc(DAW);
        } catch (error) {
            self.postMessage({ type: 'error', payload: { message: String(error) } });
        }
    }
};

/// <reference lib="webworker" />
/**
 * MIDI import worker — offloads the synchronous .mid parse onto a background
 * thread so the UI stays responsive while parsing large files. §159.1.
 *
 * Port protocol (self.onmessage):
 *   ← { type: 'parse', buffer: ArrayBuffer }                        (transferable)
 *   → { type: 'parsed', tracks: ParsedTrack[], ticksPerBeat, tempo } | { type: 'error', message }
 */

type ParsedNote = {
    id: string;
    pitch: number;
    startBeat: number;
    duration: number;
    velocity: number;
};

type ParsedTrack = {
    name: string;
    notes: ParsedNote[];
    endTick: number;
};

class MidiReader {
    private data: DataView;
    private pos = 0;

    constructor(buffer: ArrayBuffer) {
        this.data = new DataView(buffer);
    }

    readUint8(): number {
        return this.data.getUint8(this.pos++);
    }

    readUint16(): number {
        const value = this.data.getUint16(this.pos);
        this.pos += 2;
        return value;
    }

    readUint32(): number {
        const value = this.data.getUint32(this.pos);
        this.pos += 4;
        return value;
    }

    readString(len: number): string {
        let state = '';
        for (let index = 0; index < len; index++) {
            state += String.fromCharCode(this.readUint8());
        }
        return state;
    }

    readVarLen(): number {
        let value = 0;
        let byte: number;
        do {
            byte = this.readUint8();
            value = (value << 7) | (byte & 0x7f);
        } while (byte & 0x80);
        return value;
    }

    skip(node: number): void {
        this.pos += node;
    }

    get position(): number {
        return this.pos;
    }

    get length(): number {
        return this.data.byteLength;
    }
}

function parseMidiFile(buffer: ArrayBuffer): { tracks: ParsedTrack[]; ticksPerBeat: number; tempo: number } {
    const reader = new MidiReader(buffer);

    const headerChunk = reader.readString(4);
    if (headerChunk !== 'MThd') {
        throw new Error('Not a valid MIDI file');
    }

    reader.readUint32(); // header length
    const format = reader.readUint16();
    const numTracks = reader.readUint16();
    const ticksPerBeat = reader.readUint16();

    if (format > 1) {
        throw new Error(`MIDI format ${format} not supported`);
    }

    let globalTempo = 120;
    const parsedTracks: ParsedTrack[] = [];

    for (let time = 0; time < numTracks; time++) {
        const chunkType = reader.readString(4);
        const chunkLength = reader.readUint32();

        if (chunkType !== 'MTrk') {
            reader.skip(chunkLength);
            continue;
        }

        const chunkEnd = reader.position + chunkLength;
        let trackName = `Track ${time + 1}`;
        const activeNotes = new Map<number, { tick: number; velocity: number }>();
        const notes: ParsedNote[] = [];
        let tick = 0;
        let runningStatus = 0;

        while (reader.position < chunkEnd) {
            const delta = reader.readVarLen();
            tick += delta;

            let statusByte = reader.readUint8();

            if (statusByte === 0xff) {
                const metaType = reader.readUint8();
                const metaLen = reader.readVarLen();
                const metaStart = reader.position;

                if (metaType === 0x03) {
                    trackName = reader.readString(metaLen);
                } else if (metaType === 0x51 && metaLen === 3) {
                    const microsPerBeat = (reader.readUint8() << 16) | (reader.readUint8() << 8) | reader.readUint8();
                    globalTempo = Math.round(60_000_000 / microsPerBeat);
                }

                reader.skip(Math.max(0, metaLen - (reader.position - metaStart)));
                continue;
            }

            if (statusByte === 0xf0 || statusByte === 0xf7) {
                const sysexLen = reader.readVarLen();
                reader.skip(sysexLen);
                continue;
            }

            let data1: number;
            let data2: number;

            if (statusByte >= 0x80) {
                runningStatus = statusByte;
                data1 = reader.readUint8();
            } else {
                data1 = statusByte;
                statusByte = runningStatus;
            }

            const eventType = statusByte & 0xf0;

            if (eventType === 0xc0 || eventType === 0xd0) {
                data2 = 0;
            } else {
                data2 = reader.readUint8();
            }

            if (eventType === 0x90 && data2 > 0) {
                activeNotes.set(data1, { tick, velocity: data2 });
            } else if (eventType === 0x80 || (eventType === 0x90 && data2 === 0)) {
                const start = activeNotes.get(data1);
                if (start) {
                    const startBeat = start.tick / ticksPerBeat;
                    const duration = (tick - start.tick) / ticksPerBeat;
                    notes.push({
                        id: crypto.randomUUID(),
                        pitch: data1,
                        startBeat,
                        duration: Math.max(0.01, duration),
                        velocity: start.velocity,
                    });
                    activeNotes.delete(data1);
                }
            }
        }

        if (notes.length > 0) {
            parsedTracks.push({ name: trackName, notes, endTick: tick });
        }
    }

    return { tracks: parsedTracks, ticksPerBeat, tempo: globalTempo };
}

self.onmessage = (event: MessageEvent) => {
    const msg = event.data as { type: 'parse'; buffer: ArrayBuffer };
    if (msg.type !== 'parse') {
        return;
    }
    try {
        const result = parseMidiFile(msg.buffer);
        self.postMessage({ type: 'parsed', ...result });
    } catch (error) {
        self.postMessage({ type: 'error', message: error instanceof Error ? error.message : String(error) });
    }
};

import { addExternalDevice, addTrack } from '#/modules/Arrangement/useCases';
import { createHandler } from '#/utils/createHandler';

import { findPluginByName } from '../../useCases/pluginScan/queries';

export const handleLoadExternalPlugin = createHandler<'loadExternalPlugin'>({
    execute: async (alpha) => {
        const { pluginId, trackId: providedTrackId } = alpha.payload;

        let trackId = providedTrackId;
        if (!trackId) {
            const plugin = findPluginByName(pluginId);
            const isInstrument = plugin?.category.toLowerCase() === 'instrument';
            const newTrack = addTrack({
                name: plugin?.name ?? 'Plugin',
                kind: isInstrument ? 'midi' : 'audio',
            });
            if (!newTrack) {
                return;
            }
            trackId = newTrack.id;
        }

        const scanned = findPluginByName(pluginId);
        const pluginName = scanned?.name ?? pluginId;
        addExternalDevice(trackId, pluginId, pluginName);
    },
    describe: (alpha) => ({ label: `Load external plugin "${alpha.payload.pluginId}"` }),
    undoable: false,
});

/**
 * SignalFlowDiagram — SVG-based routing visualization.
 *
 * Shows the current algorithm topology: input → processing stages → output.
 * Updates dynamically when the algorithm or routing changes.
 */
import { type ReactElement } from 'react';

import { DawDiagramFrame } from '#/components/daw/DawDiagramFrame';

import { type ProofChamberAlgorithm } from '../../models/ProofChamberState';

type SignalFlowDiagramProps = {
    algorithm: ProofChamberAlgorithm;
    shimmerEnabled: boolean;
    freezeEnabled: boolean;
};

type FlowNode = { id: string; label: string; x: number; y: number; active: boolean; color: string };
type FlowEdge = { from: string; to: string; label?: string };

function getFlowForAlgorithm(
    algorithm: ProofChamberAlgorithm,
    shimmer: boolean,
    freeze: boolean
): { nodes: FlowNode[]; edges: FlowEdge[] } {
    const accent = '#7fb8c4';
    const dim = '#444';

    switch (algorithm) {
        case 'plate':
            return {
                nodes: [
                    { id: 'in', label: 'Input', x: 10, y: 30, active: !freeze, color: accent },
                    { id: 'bw', label: 'BW Filter', x: 80, y: 30, active: true, color: accent },
                    { id: 'diff', label: '4× Diffuser', x: 170, y: 30, active: true, color: accent },
                    { id: 'tank_l', label: 'Tank L', x: 280, y: 15, active: true, color: '#a89bc4' },
                    { id: 'tank_r', label: 'Tank R', x: 280, y: 45, active: true, color: '#a89bc4' },
                    { id: 'taps', label: '14 Taps', x: 380, y: 30, active: true, color: accent },
                    { id: 'out', label: 'Stereo Out', x: 470, y: 30, active: true, color: accent },
                    ...(shimmer
                        ? [{ id: 'shim', label: 'Shimmer', x: 340, y: 55, active: true, color: '#c9a07a' }]
                        : []),
                ],
                edges: [
                    { from: 'in', to: 'bw' },
                    { from: 'bw', to: 'diff' },
                    { from: 'diff', to: 'tank_l' },
                    { from: 'diff', to: 'tank_r' },
                    { from: 'tank_l', to: 'tank_r', label: '×decay' },
                    { from: 'tank_r', to: 'tank_l', label: '×decay' },
                    { from: 'tank_l', to: 'taps' },
                    { from: 'tank_r', to: 'taps' },
                    { from: 'taps', to: 'out' },
                    ...(shimmer
                        ? [
                              { from: 'tank_l', to: 'shim' },
                              { from: 'shim', to: 'tank_r' },
                          ]
                        : []),
                ],
            };

        case 'fdn-8':
        case 'fdn-16': {
            const node = algorithm === 'fdn-8' ? 8 : 16;
            return {
                nodes: [
                    { id: 'in', label: 'Input', x: 10, y: 30, active: !freeze, color: accent },
                    { id: 'early', label: 'Early Ref', x: 90, y: 15, active: true, color: '#7db8a0' },
                    { id: 'fdn', label: `FDN-${node}`, x: 200, y: 30, active: true, color: '#a89bc4' },
                    { id: 'matrix', label: 'Hadamard', x: 310, y: 30, active: true, color: '#a89bc4' },
                    { id: 'absorb', label: 'Absorptive', x: 310, y: 55, active: true, color: dim },
                    { id: 'mix', label: 'E/L Mix', x: 400, y: 30, active: true, color: accent },
                    { id: 'out', label: 'Stereo Out', x: 470, y: 30, active: true, color: accent },
                ],
                edges: [
                    { from: 'in', to: 'early' },
                    { from: 'in', to: 'fdn' },
                    { from: 'fdn', to: 'matrix' },
                    { from: 'matrix', to: 'fdn', label: 'feedback' },
                    { from: 'matrix', to: 'absorb' },
                    { from: 'absorb', to: 'fdn' },
                    { from: 'early', to: 'mix' },
                    { from: 'matrix', to: 'mix' },
                    { from: 'mix', to: 'out' },
                ],
            };
        }

        case 'spring':
            return {
                nodes: [
                    { id: 'in', label: 'Input', x: 10, y: 30, active: true, color: accent },
                    { id: 'disp', label: '80× Allpass', x: 120, y: 30, active: true, color: '#c9a07a' },
                    { id: 'delay', label: 'Spring Delay', x: 260, y: 30, active: true, color: '#c9a07a' },
                    { id: 'damp', label: 'Damping', x: 260, y: 55, active: true, color: dim },
                    { id: 'out', label: 'Stereo Out', x: 400, y: 30, active: true, color: accent },
                ],
                edges: [
                    { from: 'in', to: 'disp' },
                    { from: 'disp', to: 'delay' },
                    { from: 'delay', to: 'damp' },
                    { from: 'damp', to: 'disp', label: 'feedback' },
                    { from: 'delay', to: 'out' },
                ],
            };

        default:
            return { nodes: [], edges: [] };
    }
}

export const SignalFlowDiagram = ({
    algorithm,
    shimmerEnabled,
    freezeEnabled,
}: SignalFlowDiagramProps): ReactElement => {
    const { nodes, edges } = getFlowForAlgorithm(algorithm, shimmerEnabled, freezeEnabled);

    return (
        <DawDiagramFrame title="Signal flow" compact className="bg-black/[0.16]" viewportClassName="p-2">
            <svg viewBox="0 0 500 65" className="h-[65px] w-full" xmlns="http://www.w3.org/2000/svg">
                {edges.map((edge, index) => {
                    const from = nodes.find((node) => node.id === edge.from);
                    const to = nodes.find((node) => node.id === edge.to);
                    if (!from || !to) {
                        return null;
                    }
                    const x1 = from.x + 30;
                    const y1 = from.y;
                    const x2 = to.x - 5;
                    const y2 = to.y;
                    return (
                        <g key={index}>
                            <line
                                x1={x1}
                                y1={y1}
                                x2={x2}
                                y2={y2}
                                stroke="rgba(127,184,196,0.3)"
                                strokeWidth="1"
                                markerEnd="url(#arrowhead)"
                            />
                            {edge.label ? (
                                <text
                                    x={(x1 + x2) / 2}
                                    y={(y1 + y2) / 2 - 3}
                                    fill="rgba(255,255,255,0.25)"
                                    fontSize="6"
                                    textAnchor="middle"
                                >
                                    {edge.label}
                                </text>
                            ) : null}
                        </g>
                    );
                })}

                {nodes.map((node) => (
                    <g key={node.id}>
                        <rect
                            x={node.x - 5}
                            y={node.y - 8}
                            width={60}
                            height={16}
                            rx="3"
                            fill={node.active ? `${node.color}20` : 'rgba(50,50,50,0.5)'}
                            stroke={node.active ? `${node.color}60` : 'rgba(80,80,80,0.3)'}
                            strokeWidth="0.5"
                        />
                        <text
                            x={node.x + 25}
                            y={node.y + 1}
                            fill={node.active ? node.color : 'rgba(100,100,100,0.5)'}
                            fontSize="7"
                            textAnchor="middle"
                            dominantBaseline="middle"
                        >
                            {node.label}
                        </text>
                    </g>
                ))}

                <defs>
                    <marker id="arrowhead" markerWidth="6" markerHeight="4" refX="5" refY="2" orient="auto">
                        <polygon points="0 0, 6 2, 0 4" fill="rgba(127,184,196,0.3)" />
                    </marker>
                </defs>
            </svg>
        </DawDiagramFrame>
    );
};

