        if (inFinal) {
            // 4-on-the-floor dance pattern (every beat)
            drumN.push(note(36, b, 0.8, hv(90, 6)));
        } else if (inBuild && (pos === 0 || pos === 2)) {
            drumN.push(note(36, b, pos === 0 ? 1.0 : 0.8, hv(pos === 0 ? 65 : 50, 8)));
