                drumN.push(note(46, b + 0.5, 0.3, hv(38, 10))); // open hat accent
            }
        } else if (inFinal) {
            // Offbeat hats for dance feel (specifically on upbeat 8th notes, never overlapping kick)
            drumN.push(note(42, b + 0.5, 0.15, hv(50, 10)));
            if (bar % 4 === 3 && pos === 3) {
