            }
        } else if (!inOutro) {
            // Regular sections: offbeat closed hat
            if (pos === 0) {
                drumN.push(note(42, b + 0.5, 0.2, hv(40, 12)));
            }
            if (bar % 4 === 3 && pos === 2) {
