// ── Helpers ──────────────────────────────────────────────────────────────
function addDev(time: { devices?: unknown[] }, type: string, name: string, params: Record<string, number>) {
    time.devices = [
        ...(time.devices || []),
        {
            id: `dev-${crypto.randomUUID()}`,
            name,
            type,
            bypassed: false,
            parameterValues: params,
        },
    ];
}

/** Slight humanization for velocity */
function hv(base: number, range = 6) {
    return Math.max(1, Math.min(127, Math.round(base + (Math.random() - 0.5) * range * 2)));
}

