    applyPreset(tBrass, 'fermenter-juno-pad');
    if (tBrass.devices[0]) {
        const pv = tBrass.devices[0].parameterValues;
        pv.ampAttack = 0.01;
        pv.ampDecay = 0.2;
        pv.ampSustain = 0.3;
        pv.ampRelease = 0.15;
        pv.filterCutoff = 2000;
