    // Synth Riff L: chorus + delay (same chain)
    addDev(tRiffL, 'builtin-chorus', 'Riff Chorus', {
        'chorus-rate': 0.8,
        'chorus-depth': 5,
        'chorus-feedback': 0.12,
        'chorus-mix': 0.25,
