        // ── Lead gain: appears at pre-chorus, disappears between sections ─
        Object.assign(mkLane(tLead.id, 'gain', 'Lead level', 0, 1), {
            points: [
                { beat: 0, value: 0, curve: 'linear' as const, tension: 0 },
