    ];

    automationStore.set({ lanes });

    // ══════════════════════════════════════════════════════════════════════
    // MARKERS — section boundaries
    // ══════════════════════════════════════════════════════════════════════
    markerStore.set({
        markers: [
            { id: crypto.randomUUID(), beat: S.intro, name: 'Intro', color: 'oklch(0.40 0.08 260)' },
            { id: crypto.randomUUID(), beat: S.verse1, name: 'Verse 1', color: 'oklch(0.40 0.07 140)' },
