    const PROG_MAIN = ['Ebm7', 'Gbmaj7', 'Abm7', 'Bb7', 'Dbmaj7', 'Abm7', 'Fm7b5', 'Ebm7'];
    const PROG_WARP = ['Ebm9', 'Cbmaj7', 'Gbmaj7', 'Abm7', 'Fm7b5', 'Bb7', 'Dbmaj7', 'Ebm9'];
