/**
 * Restore a snapshot into the project stores.
 */
export const restoreSnapshot = inject({ logger })(
    ({ logger }) =>
        function restoreSnapshot(snapshot: ProjectSnapshot): void {
            try {
                const parsed = JSON.parse(snapshot.data);
                if (typeof parsed !== 'object' || parsed === null) {
                    logger.warn('Snapshot data is not a valid object — skipping restore');
                    return;
                }
                if (parsed.tracks) {
                    trackStore.set({
                        ...parsed.tracks,
                        tracks: (parsed.tracks.tracks ?? []).map(normalizeTrack),
                    });
                }
                if (parsed.markers) {
                    markerStore.set(parsed.markers);
                }
                if (parsed.transport) {
                    transportStore.set(parsed.transport);
                }
                if (parsed.midi) {
                    midiStore.set(parsed.midi);
                }
                if (parsed.automation) {
                    automationStore.set(parsed.automation);
                }
            } catch (error) {
                logger.error(new Error('Corrupt snapshot — failed to parse', { cause: error }));
            }
        }
);

/**
 * ProofDynSection — Multiband dynamics controls.
 * 4-band compressor with crossover frequencies, per-band threshold/ratio/attack/release.
 */
import { type ReactElement } from 'react';

import { DawPluginSectionHeader } from '#/components/daw/DawPluginSectionHeader';
import { DawPluginToggle } from '#/components/daw/DawPluginToggle';
import { RotaryKnob } from '#/components/daw/RotaryKnob';

import { type ProofPatch } from '../../models/ProofPatch';

const BAND_LABELS = ['Sub', 'Low-Mid', 'Hi-Mid', 'High'] as const;
const BAND_COLORS = [
    'var(--color-accent-peach)',
    'var(--color-accent-mint)',
    'var(--color-accent-cyan)',
    'var(--color-accent-lavender)',
];

type Props = {
    patch: ProofPatch;
    dynGr: [number, number, number, number];
    onPatchChange: (partial: Partial<ProofPatch>) => void;
    onSendParam: (name: string, value: number) => void;
};

export const ProofDynSection = ({ patch, dynGr, onPatchChange, onSendParam }: Props): ReactElement => {
    const updateBand = (idx: number, key: string, value: number | boolean) => {
        const bands = patch.dynBands.map((b, i) => (i === idx ? { ...b, [key]: value } : b));
        onPatchChange({ dynBands: bands });
        const paramName = (() => {
            if (key === 'autoMakeup') {
                return 'auto_makeup';
            }
            if (key === 'bypassed') {
                return 'bypass';
            }
            return key;
        })();
        onSendParam(
            `dyn_band${idx}_${paramName}`,
            (() => {
                if (typeof value === 'boolean') {
                    return value ? 1 : 0;
                }
                return value;
            })()
        );
    };

    const updateXover = (idx: number, value: number) => {
        const freqs: [number, number, number] = [...patch.dynCrossoverFreqs];
        freqs[idx] = value;
        onPatchChange({ dynCrossoverFreqs: freqs });
        onSendParam(`dyn_xover${idx}`, value);
    };

    return (
        <div className="flex flex-col gap-1.5 px-2">
            <DawPluginSectionHeader
                title="Multiband Dynamics"
                size="xs"
                titleClassName="text-[var(--color-accent-peach)]"
                actions={
                    <DawPluginToggle
                        pressed={!patch.dynBypassed}
                        tone="peach"
                        size="xs"
                        onClick={() => {
                            onPatchChange({ dynBypassed: !patch.dynBypassed });
                            onSendParam('dyn_bypass', patch.dynBypassed ? 0 : 1);
                        }}
                    >
                        {patch.dynBypassed ? 'OFF' : 'ON'}
                    </DawPluginToggle>
                }
            />

            {/* Crossover frequencies */}
            <div className="flex items-center gap-2 px-1">
                <span className="text-[7px] text-muted-foreground">Crossovers:</span>
                {patch.dynCrossoverFreqs.map((freq, i) => (
                    <div key={i} className="flex items-center gap-0.5">
                        <RotaryKnob
                            value={freq}
                            onChange={(v) => updateXover(i, v)}
                            min={20}
                            max={20000}
                            step={1}
                            defaultValue={freq}
                            size="sm"
                            tone="cyan"
                        />
                        <span className="text-[6px] text-muted-foreground font-mono">
                            {freq >= 1000 ? `${(freq / 1000).toFixed(1)}k` : `${freq.toFixed(0)}`}
                        </span>
                    </div>
                ))}
            </div>

            {/* Per-band controls */}
            <div className={`flex gap-1 ${patch.dynBypassed ? 'opacity-30' : ''}`}>
                {BAND_LABELS.map((label, i) => {
                    const band = patch.dynBands[i]!;
                    const gr = dynGr[i] ?? 0;
                    return (
                        <div
                            key={i}
                            className="flex-1 flex flex-col items-center gap-0.5 px-1 py-1 rounded bg-surface-base/50"
                        >
                            <span className="text-[7px] font-bold uppercase" style={{ color: BAND_COLORS[i] }}>
                                {label}
                            </span>

                            {/* GR meter bar */}
                            <div className="w-full h-1 bg-surface-inset rounded overflow-hidden">
                                <div
                                    className="h-full bg-[var(--color-accent-peach)] transition-all duration-75"
                                    style={{ width: `${Math.min(100, (Math.abs(gr) / 20) * 100)}%` }}
                                />
                            </div>
                            <span className="text-[6px] text-muted-foreground font-mono">{gr.toFixed(1)} dB</span>

                            <RotaryKnob
                                value={band.threshold}
                                onChange={(v) => updateBand(i, 'threshold', v)}
                                min={-60}
                                max={0}
                                step={0.5}
                                defaultValue={-20}
                                size="sm"
                                tone="cyan"
                            />
                            <span className="text-[6px] text-muted-foreground">Thr</span>

                            <RotaryKnob
                                value={band.ratio}
                                onChange={(v) => updateBand(i, 'ratio', v)}
                                min={1}
                                max={20}
                                step={0.5}
                                defaultValue={2}
                                size="sm"
                                tone="cyan"
                            />
                            <span className="text-[6px] text-muted-foreground">Ratio</span>

                            <RotaryKnob
                                value={band.attack}
                                onChange={(v) => updateBand(i, 'attack', v)}
                                min={1}
                                max={200}
                                step={1}
                                defaultValue={10}
                                size="sm"
                                tone="cyan"
                            />
                            <span className="text-[6px] text-muted-foreground">Atk</span>

                            <RotaryKnob
                                value={band.release}
                                onChange={(v) => updateBand(i, 'release', v)}
                                min={10}
                                max={2000}
                                step={1}
                                defaultValue={100}
                                size="sm"
                                tone="cyan"
                            />
                            <span className="text-[6px] text-muted-foreground">Rel</span>
                        </div>
                    );
                })}
            </div>
        </div>
    );
};

/**
 * ProofEqSection — 8-band parametric EQ with interactive controls.
 * Knobs for freq/gain/Q per band, band type selector, M/S per-band.
 */
import { type ReactElement } from 'react';

import { DawCompactSelect } from '#/components/daw/DawCompactSelect';
import { DawPluginSectionHeader } from '#/components/daw/DawPluginSectionHeader';
import { DawPluginToggle } from '#/components/daw/DawPluginToggle';
import { RotaryKnob } from '#/components/daw/RotaryKnob';

import { type ProofPatch } from '../../models/ProofPatch';

import { ProofEqCurve } from './ProofEqCurve';

const BAND_TYPES = ['Peak', 'Lo Shelf', 'Hi Shelf', 'HP', 'LP'] as const;
const CHANNEL_MODES = ['L/R', 'Mid', 'Side'] as const;
const BAND_COLORS = ['#6BAACE', '#52BA46', '#E0AA2A', '#FF5F80', '#4CB8B8', '#954EB2', '#6BAACE', '#52BA46'];

type Props = {
    patch: ProofPatch;
    onPatchChange: (partial: Partial<ProofPatch>) => void;
    onSendParam: (name: string, value: number) => void;
};

export const ProofEqSection = ({ patch, onPatchChange, onSendParam }: Props): ReactElement => {
    // §8.20 — Previously `updateBand` forwarded `value as number` to `onSendParam`
    // even when `value` was a boolean (the `enabled` toggle), and every knob's
    // `onChange` then dispatched `onSendParam` again. Net effect: every numeric
    // knob fired twice per turn, and the `enabled` toggle sent a boolean cast
    // to `number` (NaN/1/0 depending on the JS runtime). Split the two concerns:
    // `updatePatch` only mutates patch state; `updateBandAndSend` is the single
    // numeric write-through. The boolean toggle uses an explicit 0/1 send.
    const updatePatch = (idx: number, key: string, value: number | boolean) => {
        const bands = patch.eqBands.map((b, i) => (i === idx ? { ...b, [key]: value } : b));
        onPatchChange({ eqBands: bands });
    };

    const updateBandAndSend = (idx: number, key: string, value: number) => {
        updatePatch(idx, key, value);
        onSendParam(`eq_band${idx}_${key}`, value);
    };

    return (
        <div className="flex flex-col gap-1.5 px-2">
            <DawPluginSectionHeader
                title="EQ"
                size="xs"
                titleClassName="text-[var(--color-accent-cyan)]"
                actions={
                    <DawPluginToggle
                        pressed={!patch.eqBypassed}
                        tone="cyan"
                        size="xs"
                        onClick={() => {
                            onPatchChange({ eqBypassed: !patch.eqBypassed });
                            onSendParam('eq_bypass', patch.eqBypassed ? 0 : 1);
                        }}
                    >
                        {patch.eqBypassed ? 'OFF' : 'ON'}
                    </DawPluginToggle>
                }
            />

            {/* Interactive frequency response graph */}
            <div className={patch.eqBypassed ? 'opacity-30' : ''}>
                <ProofEqCurve
                    patch={patch}
                    width={500}
                    height={120}
                    onPatchChange={onPatchChange}
                    onSendParam={onSendParam}
                />
            </div>

            <div className={`flex gap-1 overflow-x-auto ${patch.eqBypassed ? 'opacity-30' : ''}`}>
                {patch.eqBands.map((band, i) => (
                    <div
                        key={i}
                        className="flex flex-col items-center gap-0.5 min-w-[52px] px-0.5 py-1 rounded bg-surface-base/50"
                    >
                        {/* Enable toggle */}
                        <button
                            type="button"
                            className={`w-2 h-2 rounded-full cursor-pointer ${band.enabled ? '' : 'opacity-20'}`}
                            style={{ backgroundColor: BAND_COLORS[i] }}
                            onClick={() => {
                                const next = !band.enabled;
                                updatePatch(i, 'enabled', next);
                                onSendParam(`eq_band${i}_enabled`, next ? 1 : 0);
                            }}
                        />

                        {/* Frequency */}
                        <RotaryKnob
                            value={band.freq}
                            onChange={(v) => updateBandAndSend(i, 'freq', v)}
                            min={20}
                            max={20000}
                            step={1}
                            defaultValue={band.freq}
