import { type SampleEntry } from '#/modules/SoundLibrary/models/SampleEntry';
import { sampleDatabaseStore } from '#/modules/SoundLibrary/stores/sampleDatabaseStore';

/**
 * Find samples similar to a given sample by tag overlap (Jaccard similarity).
 *
 * §69.1 — one-pass overlap without allocating a merge-Set per sample.
 * §156.1 — single-pass scoring into parallel index + score arrays
 * instead of a filter().map() that churns per-sample wrapper objects,
 * then a one-shot sort over only the candidates we intend to keep.
 */
export function findSimilarSamples(sampleId: string, limit: number = 10): SampleEntry[] {
    const state = sampleDatabaseStore.value;
    if (!state) {
        return [];
    }

    const target = state.samples.find((s) => s.id === sampleId);
    if (!target) {
        return [];
    }

    const targetTags = new Set(target.tags.map((t) => t.name));
    const targetSize = targetTags.size;
    const samples = state.samples;

    // Parallel arrays: indexes[i] is the position in `samples`, scores[i]
    // is the Jaccard similarity. Allocated once at pre-filter size (N-1
    // worst case); no per-sample wrapper objects.
    const indexes = new Int32Array(samples.length);
    const scores = new Float64Array(samples.length);
    let count = 0;

    for (let i = 0; i < samples.length; i++) {
        const s = samples[i]!;
        if (s.id === sampleId) {
            continue;
        }
        const sampleTags = s.tags;
        let overlap = 0;
        for (const tag of sampleTags) {
            if (targetTags.has(tag.name)) {
                overlap++;
            }
        }
        const union = targetSize + sampleTags.length - overlap || 1;
        indexes[count] = i;
        scores[count] = overlap / union;
        count++;
    }

    // Build an index permutation of [0, count) sorted by descending score.
    // One Int32Array allocation for the permutation, no wrapper objects.
    const permutation = new Int32Array(count);
    for (let i = 0; i < count; i++) {
        permutation[i] = i;
    }
    permutation.sort((a, b) => scores[b]! - scores[a]!);

    const take = Math.min(limit, count);
    const out: SampleEntry[] = new Array(take);
    for (let i = 0; i < take; i++) {
        out[i] = samples[indexes[permutation[i]!]!]!;
    }
    return out;
}

/**
 * Use case: built-in synthesizer note scheduling and parameter resolution.
 * Delegates to SynthModels for types/defaults.
 */

import { defaultSynthParams, type MpeParams, type SynthParams } from '#/modules/AudioEngine/useCases';

// Consumer-local shape (AGENTS.md §95 — model isolation). Only fields used here.
type Device = { type: string; parameterValues: Record<string, number> };

// Pre-generated noise buffer (§54.1 — avoid per-note AudioBuffer allocation).
// Cached by AudioContext sample rate — reused across every note until the
// context sample rate changes. Not observable externally, so a plain
// module-level `let` is the idiomatic shape per docs/03-state-management.md.
let cachedNoiseBuffer: AudioBuffer | null = null;
function getNoiseBuffer(ctx: BaseAudioContext): AudioBuffer {
    if (cachedNoiseBuffer && cachedNoiseBuffer.sampleRate === ctx.sampleRate) {
        return cachedNoiseBuffer;
    }
    const len = Math.ceil(ctx.sampleRate * 0.1); // 100ms of noise
    const buf = new AudioBuffer({ numberOfChannels: 1, length: len, sampleRate: ctx.sampleRate });
    const data = buf.getChannelData(0);
    for (let i = 0; i < len; i++) {
        data[i] = Math.random() * 2 - 1;
    }
    cachedNoiseBuffer = buf;
    return buf;
}

const SYNTH_PARAM_KEYS: ReadonlyArray<keyof SynthParams> = [
    'waveform',
    'attack',
    'decay',
    'sustain',
    'release',
    'filterCutoff',
    'filterResonance',
    'filterType',
    'filterEnvAmount',
    'detune',
    'gain',
    'osc2Waveform',
    'osc2Detune',
    'osc2Mix',
    'subOscLevel',
    'noiseLevel',
    'vibratoRate',
    'vibratoDepth',
    'vibratoDelay',
    'stereoSpread',
    'filterVelocitySensitivity',
];

const WAVEFORMS = new Set<string>(['sine', 'triangle', 'sawtooth', 'square']);
const FILTER_TYPES = new Set<string>(['lowpass', 'highpass', 'bandpass']);

const WAVEFORM_INDEX: Record<number, SynthParams['waveform']> = {
    0: 'sine',
    1: 'triangle',
    2: 'sawtooth',
    3: 'square',
};

const FILTER_TYPE_INDEX: Record<number, SynthParams['filterType']> = {
    0: 'lowpass',
    1: 'highpass',
    2: 'bandpass',
};

function resolveEnumParam<T extends string>(
    raw: number | string | undefined,
    allowed: Set<string>,
    indexMap: Record<number, T>,
    fallback: T
): T {
    if (raw === undefined) {
        return fallback;
    }
    if (typeof raw === 'string' && allowed.has(raw)) {
        return raw as T;
    }
    if (typeof raw === 'number' && indexMap[raw] !== undefined) {
        return indexMap[raw];
    }
    return fallback;
}

const MPE_BEND_RANGE_SEMITONES = 48;

export function scheduleNote(
    ctx: BaseAudioContext,
    destination: AudioNode,
    pitch: number,
    startTime: number,
    duration: number,
    velocity: number,
    params: SynthParams,
    mpe?: MpeParams,
    clipGain: number = 1.0
): OscillatorNode {
    const baseFrequency = 440 * 2 ** ((pitch - 69) / 12);
    // Velocity-sensitive attack: harder hits = faster attack (real instrument behavior)
    const velAttack = params.attack * (1.5 - velocity / 127);
    const peakGain = (velocity / 127) * params.gain * clipGain;
    const sustainLevel = peakGain * params.sustain;

    let frequency = baseFrequency;
    if (mpe?.pitchBend !== undefined) {
        const bendSemitones = (mpe.pitchBend / 8192) * MPE_BEND_RANGE_SEMITONES;
        frequency = baseFrequency * 2 ** (bendSemitones / 12);
    }

    // Mixer before filter
    const mixer = ctx.createGain();

    // Track all nodes for cleanup
    const cleanupNodes: AudioNode[] = [mixer];
    let osc2: OscillatorNode | null = null;
    let subOsc: OscillatorNode | null = null;

    // -- Primary oscillator --
    const osc1 = ctx.createOscillator();
    osc1.type = params.waveform;
    osc1.frequency.setValueAtTime(frequency, startTime);
    osc1.detune.value = params.detune;
    const osc1Gain = ctx.createGain();
    osc1Gain.gain.value = params.osc2Mix > 0 ? 1 - params.osc2Mix : 1;
    osc1.connect(osc1Gain);
    cleanupNodes.push(osc1, osc1Gain);

    // Stereo spread: pan osc1 left and osc2 right for spatial width
    if (params.stereoSpread > 0 && params.osc2Mix > 0) {
        const pan1 = new StereoPannerNode(ctx, { pan: -params.stereoSpread });
        osc1Gain.connect(pan1);
        pan1.connect(mixer);
        cleanupNodes.push(pan1);
    } else {
        osc1Gain.connect(mixer);
    }

    // -- Second oscillator (if osc2Mix > 0) --
    if (params.osc2Mix > 0) {
        osc2 = ctx.createOscillator();
        osc2.type = params.osc2Waveform;
        osc2.frequency.setValueAtTime(frequency, startTime);
        osc2.detune.value = params.detune + params.osc2Detune;
        const osc2Gain = ctx.createGain();
        osc2Gain.gain.value = params.osc2Mix;
        osc2.connect(osc2Gain);

        // Stereo spread: pan osc2 to the right
        if (params.stereoSpread > 0) {
            const pan2 = new StereoPannerNode(ctx, { pan: params.stereoSpread });
            osc2Gain.connect(pan2);
            pan2.connect(mixer);
            cleanupNodes.push(pan2);
        } else {
            osc2Gain.connect(mixer);
        }
        cleanupNodes.push(osc2, osc2Gain);
    }

    // -- Sub-oscillator (one octave below, if subOscLevel > 0) --
    if (params.subOscLevel > 0) {
        subOsc = ctx.createOscillator();
        subOsc.type = 'sine';
        subOsc.frequency.setValueAtTime(frequency / 2, startTime);
        const subGain = ctx.createGain();
        subGain.gain.value = params.subOscLevel;
        subOsc.connect(subGain);
        subGain.connect(mixer);
        cleanupNodes.push(subOsc, subGain);
    }

    // -- Noise layer (if noiseLevel > 0) --
    // Uses a fast 50ms decay envelope to simulate pluck/hammer attack transients
    let noiseSource: AudioBufferSourceNode | null = null;
    if (params.noiseLevel > 0) {
        const noiseAttackDecay = 0.05; // 50ms burst
        noiseSource = ctx.createBufferSource();
        noiseSource.buffer = getNoiseBuffer(ctx);
        const noiseGain = ctx.createGain();
        // Fast attack-decay envelope for the noise burst
        noiseGain.gain.setValueAtTime(params.noiseLevel * 0.5, startTime);
        noiseGain.gain.exponentialRampToValueAtTime(0.001, startTime + noiseAttackDecay);
        noiseSource.connect(noiseGain);
        noiseGain.connect(mixer);
        cleanupNodes.push(noiseGain);
    }

    // -- Filter with velocity sensitivity and pitch tracking --
    const filter = ctx.createBiquadFilter();
    filter.type = params.filterType;

    // Velocity → filter brightness: harder hits open the filter more
    const velSens = params.filterVelocitySensitivity ?? 0;
    const velocityScale =
        velSens > 0
            ? 1 - velSens + velSens * (velocity / 127) // 0 sens = always full, 1 sens = full range
            : 0.3 + 0.7 * (velocity / 127); // legacy default when param not set
    // Pitch tracking: higher notes are naturally brighter (scale by sqrt of freq ratio)
    const pitchScale = Math.sqrt(frequency / 440);
    let filterCutoff = Math.min(params.filterCutoff * velocityScale * pitchScale, 20000);
    if (mpe?.pressure !== undefined) {
        filterCutoff = Math.min(20000, filterCutoff + (mpe.pressure / 127) * 2000);
    }

    // Filter envelope: starts at cutoff+envAmount, decays to cutoff
    // This creates bright-attack-to-dark-sustain character (piano, bells, plucks)
    if (params.filterEnvAmount > 0) {
        const filterPeak = Math.min(filterCutoff + params.filterEnvAmount, 20000);
        filter.frequency.setValueAtTime(filterPeak, startTime);
        const filterAttackEnd = startTime + params.attack;
        const filterDecayEnd = filterAttackEnd + params.decay;
        // Hold at peak during attack, then sweep down during decay
        filter.frequency.setValueAtTime(filterPeak, filterAttackEnd);
        filter.frequency.exponentialRampToValueAtTime(Math.max(filterCutoff, 20), filterDecayEnd);
    } else {
        filter.frequency.setValueAtTime(filterCutoff, startTime);
    }

    let filterQ = params.filterResonance;
    if (mpe?.slide !== undefined) {
        filterQ = (mpe.slide / 127) * 20;
    }
    filter.Q.setValueAtTime(filterQ, startTime);

    // -- Envelope (using velocity-sensitive attack) --
    const env = ctx.createGain();
    env.gain.setValueAtTime(0, startTime);

    const attackEnd = startTime + velAttack;
    const decayEnd = attackEnd + params.decay;
    const releaseStart = startTime + duration;
    const releaseEnd = releaseStart + params.release;

    env.gain.linearRampToValueAtTime(peakGain, attackEnd);

    if (decayEnd < releaseStart) {
        env.gain.linearRampToValueAtTime(sustainLevel, decayEnd);
        env.gain.setValueAtTime(sustainLevel, releaseStart);
    } else {
        env.gain.linearRampToValueAtTime(sustainLevel, releaseStart);
    }

    env.gain.linearRampToValueAtTime(0, releaseEnd);

    // -- Signal chain: mixer -> filter -> env -> destination --
    mixer.connect(filter);
    filter.connect(env);
    env.connect(destination);
    cleanupNodes.push(filter, env);

    // -- Vibrato LFO (pitch modulation after attack phase) --
    let vibratoLfo: OscillatorNode | null = null;
    if (params.vibratoRate > 0 && params.vibratoDepth > 0) {
        vibratoLfo = ctx.createOscillator();
        vibratoLfo.type = 'sine';
        vibratoLfo.frequency.setValueAtTime(params.vibratoRate, startTime);
        const vibratoGain = ctx.createGain();
        // Ramp vibrato in after delay period so it doesn't wobble the onset
        const vibDelay = params.vibratoDelay ?? 0.3;
        vibratoGain.gain.setValueAtTime(0, startTime);
        vibratoGain.gain.linearRampToValueAtTime(0, attackEnd + vibDelay);
        vibratoGain.gain.linearRampToValueAtTime(params.vibratoDepth, attackEnd + vibDelay + 0.1);
        vibratoLfo.connect(vibratoGain);
        // Connect to all oscillators' detune params
        vibratoGain.connect(osc1.detune);
        if (osc2) {
            vibratoGain.connect(osc2.detune);
        }
        if (subOsc) {
            vibratoGain.connect(subOsc.detune);
        }
        cleanupNodes.push(vibratoLfo, vibratoGain);
    }

    // -- Start all sources --
    osc1.start(startTime);
    osc1.stop(releaseEnd + 0.01);
    if (osc2) {
        osc2.start(startTime);
        osc2.stop(releaseEnd + 0.01);
    }
    if (subOsc) {
        subOsc.start(startTime);
        subOsc.stop(releaseEnd + 0.01);
    }
    if (noiseSource) {
        noiseSource.start(startTime);
        noiseSource.stop(releaseEnd + 0.01);
    }
    if (vibratoLfo) {
        vibratoLfo.start(startTime);
        vibratoLfo.stop(releaseEnd + 0.01);
    }

    osc1.onended = () => {
        for (const node of cleanupNodes) {
            try {
                node.disconnect();
            } catch {
                /* already disconnected */
            }
        }
    };

    return osc1;
}

/**
 * Resolve synth params from an array of device descriptors.
 * Prefer this over `getSynthParamsForTrack` during offline rendering
 * to avoid re-reading the live store mid-render.
 */
export function getSynthParamsFromDevices(devices: Device[]): SynthParams {
    const synthDevice = devices.find((d) => d.type === 'synth' || d.type.startsWith('builtin-synth'));
    if (!synthDevice) {
        return { ...defaultSynthParams };
    }

    const pv = synthDevice.parameterValues;
    const result: SynthParams = { ...defaultSynthParams };

    for (const key of SYNTH_PARAM_KEYS) {
        const raw = pv[key];
        if (raw === undefined) {
            continue;
        }

        if (key === 'waveform') {
            result.waveform = resolveEnumParam(raw, WAVEFORMS, WAVEFORM_INDEX, defaultSynthParams.waveform);
        } else if (key === 'osc2Waveform') {
            result.osc2Waveform = resolveEnumParam(raw, WAVEFORMS, WAVEFORM_INDEX, defaultSynthParams.osc2Waveform);
        } else if (key === 'filterType') {
            result.filterType = resolveEnumParam(raw, FILTER_TYPES, FILTER_TYPE_INDEX, defaultSynthParams.filterType);
        } else {
            (result as unknown as Record<string, number>)[key] = raw;
        }
    }

    return result;
}

/**
 * Lightweight note scheduling for offline rendering.
 * Creates only 3 nodes per note (osc + filter + env) instead of 4-10+.
 * Skips: osc2, sub-osc, noise layer, vibrato LFO, stereo spread.
 * This reduces node count by ~60% while preserving core timbre.
 */
export function scheduleNoteOffline(
    ctx: BaseAudioContext,
    destination: AudioNode,
    pitch: number,
    startTime: number,
    duration: number,
    velocity: number,
    params: SynthParams
): void {
    const frequency = 440 * 2 ** ((pitch - 69) / 12);
    const velAttack = params.attack * (1.5 - velocity / 127);
    const peakGain = (velocity / 127) * params.gain;
    const sustainLevel = peakGain * params.sustain;

    // Single oscillator
    const osc = ctx.createOscillator();
    osc.type = params.waveform;
    osc.frequency.setValueAtTime(frequency, startTime);
    osc.detune.value = params.detune;

    const filter = ctx.createBiquadFilter();
    filter.type = params.filterType;
    const velSens = params.filterVelocitySensitivity ?? 0;
    const velocityScale = velSens > 0 ? 1 - velSens + velSens * (velocity / 127) : 0.3 + 0.7 * (velocity / 127);
    const pitchScale = Math.sqrt(frequency / 440);
    const filterCutoff = Math.min(params.filterCutoff * velocityScale * pitchScale, 20000);

    // Filter envelope: match realtime path
    if (params.filterEnvAmount > 0) {
        const filterPeak = Math.min(filterCutoff + params.filterEnvAmount, 20000);
        filter.frequency.setValueAtTime(filterPeak, startTime);
        const filterAttackEnd = startTime + params.attack;
        const filterDecayEnd = filterAttackEnd + params.decay;
        filter.frequency.setValueAtTime(filterPeak, filterAttackEnd);
        filter.frequency.exponentialRampToValueAtTime(Math.max(filterCutoff, 20), filterDecayEnd);
    } else {
        filter.frequency.setValueAtTime(filterCutoff, startTime);
    }
    filter.Q.setValueAtTime(params.filterResonance, startTime);

    // Amplitude envelope
    const env = ctx.createGain();
    env.gain.setValueAtTime(0, startTime);

    const attackEnd = startTime + velAttack;
    const decayEnd = attackEnd + params.decay;
    const releaseStart = startTime + duration;
    const releaseEnd = releaseStart + params.release;

    env.gain.linearRampToValueAtTime(peakGain, attackEnd);
    if (decayEnd < releaseStart) {
        env.gain.linearRampToValueAtTime(sustainLevel, decayEnd);
        env.gain.setValueAtTime(sustainLevel, releaseStart);
    } else {
        env.gain.linearRampToValueAtTime(sustainLevel, releaseStart);
    }
    env.gain.linearRampToValueAtTime(0, releaseEnd);

    // Chain: osc → filter → env → destination
    osc.connect(filter);
    filter.connect(env);
    env.connect(destination);

    osc.start(startTime);
    osc.stop(releaseEnd + 0.01);
}

import { type ReactElement, useEffect, useRef, useState } from 'react';

import { type PadState } from '../../models/ToasterKit';

type PadGridProps = {
    pads: PadState[];
    selectedIndex: number;
    onSelectPad: (index: number) => void;
    onTriggerPad: (index: number) => void;
};

export const PadGrid = ({ pads, selectedIndex, onSelectPad, onTriggerPad }: PadGridProps): ReactElement => {
    const [flashingPads, setFlashingPads] = useState<Set<number>>(new Set());
    const flashTimers = useRef<Map<number, ReturnType<typeof setTimeout>>>(new Map());

    function triggerFlash(index: number): void {
        setFlashingPads((previous) => new Set(previous).add(index));
        const existingTimer = flashTimers.current.get(index);
        if (existingTimer) {
            clearTimeout(existingTimer);
        }

        flashTimers.current.set(
            index,
            setTimeout(() => {
                setFlashingPads((previous) => {
                    const next = new Set(previous);
                    next.delete(index);
                    return next;
                });
                flashTimers.current.delete(index);
            }, 120)
        );
    }

    useEffect(() => {
        return () => {
            for (const timer of flashTimers.current.values()) {
                clearTimeout(timer);
            }
        };
    }, []);

    return (
        <div className="grid grid-cols-4 gap-1.5">
            {pads.slice(0, 16).map((pad, index) => {
                const isSelected = index === selectedIndex;
                const isFlashing = flashingPads.has(index);
                const baseGlow = isSelected ? `${pad.color}55` : `${pad.color}22`;

                return (
                    <button
                        key={pad.id}
                        type="button"
                        className="relative aspect-square rounded-[16px] border transition-all select-none"
                        style={{
                            background: isFlashing
                                ? `linear-gradient(180deg, ${pad.color}, rgba(255,255,255,0.16))`
                                : `linear-gradient(180deg, ${pad.color}26, rgba(0,0,0,0.18))`,
                            borderColor: isSelected ? `${pad.color}88` : `${pad.color}33`,
                            boxShadow: isSelected
                                ? `inset 0 1px 0 rgba(255,255,255,0.12), 0 0 22px ${baseGlow}`
                                : `inset 0 1px 0 rgba(255,255,255,0.08), 0 0 12px ${pad.color}12`,
                            transform: isFlashing ? 'scale(0.97)' : 'scale(1)',
                        }}
                        onClick={() => onSelectPad(index)}
                        onMouseDown={(event) => {
                            if (event.button === 0) {
                                onTriggerPad(index);
                                triggerFlash(index);
                            }
                        }}
                    >
                        <div className="absolute inset-[1px] rounded-[14px] bg-black/30" />
                        <div className="relative z-10 flex h-full flex-col justify-between px-2 py-2">
                            <div className="flex items-start justify-between gap-2">
                                <span
                                    className="text-[10px] font-semibold leading-tight tracking-[0.02em]"
                                    style={{ color: isFlashing ? '#fff' : `${pad.color}ee` }}
                                >
                                    {pad.name}
                                </span>
                                {pad.chokeGroup > 0 ? (
                                    <span
                                        className="rounded-full border px-1 py-0.5 text-[7px] font-medium text-white/55"
                                        style={{ borderColor: `${pad.color}55` }}
                                    >
                                        C{pad.chokeGroup}
                                    </span>
                                ) : null}
                            </div>

                            <div className="space-y-1">
                                <div className="flex items-center justify-between gap-2 text-[7px] uppercase tracking-[0.18em] text-white/45">
                                    <span>{pad.engineType.replace(/^(kick|snare|hihat|modal)-/, '').slice(0, 8)}</span>
                                    <span>{Math.round(pad.volume * 100)}%</span>
                                </div>
                                <div className="h-1.5 rounded-full bg-white/8">
                                    <div
                                        className="h-full rounded-full"
                                        style={{
                                            width: `${Math.round(pad.volume * 100)}%`,
                                            backgroundColor: pad.color,
                                            opacity: isFlashing ? 1 : 0.85,
                                        }}
                                    />
                                </div>
                            </div>
                        </div>

                        {pad.muted ? (
                            <div className="absolute inset-0 z-20 flex items-center justify-center rounded-[16px] bg-black/56">
                                <span className="text-[9px] font-bold uppercase tracking-[0.2em] text-white/55">
                                    Mute
                                </span>
                            </div>
                        ) : null}
                    </button>
                );
            })}
        </div>
    );
};

import { type ReactElement, useRef } from 'react';

import { type PadState, type Pattern } from '../../models/ToasterKit';

type StepSequencerProps = {
    pattern: Pattern;
    pads: PadState[];
    currentStep: number;
    isPlaying: boolean;
    onToggleStep: (padIndex: number, stepIndex: number) => void;
    onSetVelocity: (padIndex: number, stepIndex: number, velocity: number) => void;
};

const STEP_HEIGHT = 28;

export const StepSequencer = ({
    pattern,
    pads,
    currentStep,
    isPlaying,
    onToggleStep,
    onSetVelocity,
}: StepSequencerProps): ReactElement => {
    const dragRef = useRef<{ padIndex: number; stepIndex: number; startY: number } | null>(null);
    const stepCount = pattern.stepsPerBar * pattern.bars;

    function handleStepPointerDown(
        padIndex: number,
        stepIndex: number,
        event: React.PointerEvent<HTMLDivElement>
    ): void {
        if (event.altKey) {
            dragRef.current = { padIndex, stepIndex, startY: event.clientY };
            event.currentTarget.setPointerCapture(event.pointerId);
            return;
        }

        onToggleStep(padIndex, stepIndex);
    }

    function handlePointerMove(event: React.PointerEvent<HTMLDivElement>): void {
        if (!dragRef.current) {
            return;
        }

        const delta = dragRef.current.startY - event.clientY;
        const velocity = Math.max(0.05, Math.min(1, 0.5 + delta / 100));
        onSetVelocity(dragRef.current.padIndex, dragRef.current.stepIndex, velocity);
    }

    function handlePointerUp(): void {
        dragRef.current = null;
    }

    return (
        <div className="select-none" onPointerMove={handlePointerMove} onPointerUp={handlePointerUp}>
            {pattern.tracks.map((track) => {
                const pad = pads[track.padIndex];
                if (!pad) {
                    return null;
                }

                return (
                    <div key={track.padIndex} className="mb-1 flex items-end gap-2">
                        <div className="toaster-step-label flex h-8 w-[88px] shrink-0 items-center gap-2 rounded-[14px] px-2">
                            <div className="size-2 rounded-full" style={{ backgroundColor: pad.color }} />
                            <span className="truncate text-[9px] font-medium" style={{ color: `${pad.color}dd` }}>
                                {pad.name}
                            </span>
                        </div>

                        <div className="flex min-w-0 flex-1 gap-1">
                            {track.steps.slice(0, stepCount).map((step, stepIndex) => {
                                const isCurrent = isPlaying && stepIndex === currentStep;
                                const isBarStart = stepIndex % 4 === 0;
                                const probabilityTint = step.active ? 0.12 + (1 - step.probability) * 0.18 : 0;

                                return (
                                    <div
                                        key={stepIndex}
                                        className={`relative min-w-[19px] flex-1 cursor-pointer rounded-[10px] transition-all ${isBarStart ? 'ml-1' : ''}`}
                                        style={{
                                            height: STEP_HEIGHT,
                                            background: (() => {
                                                if (isCurrent) {
                                                    return 'linear-gradient(180deg, rgba(255,255,255,0.12), rgba(255,255,255,0.03))';
                                                }
                                                if (stepIndex % 8 < 4) {
                                                    return 'rgba(255,255,255,0.02)';
                                                }
                                                return 'rgba(255,255,255,0.012)';
                                            })(),
                                            boxShadow: isCurrent
                                                ? `0 0 16px ${pad.color}33`
                                                : 'inset 0 1px 0 rgba(255,255,255,0.04)',
                                        }}
                                        onPointerDown={(event) =>
                                            handleStepPointerDown(track.padIndex, stepIndex, event)
                                        }
                                    >
                                        <div className="absolute inset-[1px] rounded-[9px] bg-black/22" />

                                        {step.active ? (
                                            <div
                                                className="absolute bottom-[2px] left-[2px] right-[2px] rounded-[7px] transition-all"
                                                style={{
                                                    height: `${step.velocity * 100}%`,
                                                    background: `linear-gradient(180deg, ${pad.color}, ${pad.color}aa)`,
                                                    opacity: 0.92,
                                                    boxShadow: isCurrent
                                                        ? `0 0 10px ${pad.color}88`
                                                        : `0 0 6px ${pad.color}44`,
                                                }}
                                            />
                                        ) : null}

                                        {step.active && step.probability < 1 ? (
                                            <div
                                                className="absolute right-1 top-1 size-1.5 rounded-full"
                                                style={{
                                                    backgroundColor: `rgba(255,255,255,${0.18 + probabilityTint})`,
                                                }}
                                            />
                                        ) : null}

                                        {step.active && step.retriggerCount > 0 ? (
                                            <div className="absolute left-1 top-1 text-[5px] font-bold text-white/45">
                                                {step.retriggerCount}×
                                            </div>
                                        ) : null}

                                        {isCurrent ? (
                                            <div className="absolute inset-0 rounded-[10px] border border-white/18" />
                                        ) : null}
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                );
            })}
        </div>
    );
};

