/**
 * Euclidean rhythm generator — distributes k hits across n steps as evenly as possible.
 * Bjorklund algorithm (Toussaint 2005). Used to generate patterns in the step sequencer.
 */

export function euclidean(hits: number, steps: number, rotation: number = 0): boolean[] {
    if (steps <= 0) {
        return [];
    }
    if (hits <= 0) {
        return Array(steps).fill(false);
    }
    if (hits >= steps) {
        return Array(steps).fill(true);
    }

    // Bjorklund iterative algorithm
    type Group = boolean[];
    let groups: Group[] = [];
    for (let index = 0; index < hits; index++) {
        groups.push([true]);
    }
    for (let index = 0; index < steps - hits; index++) {
        groups.push([false]);
    }

    while (true) {
        const firstGroup = groups[0];
        if (!firstGroup) {
            break;
        }

        const splitPos = groups.findIndex(
            (g) => g.length !== firstGroup.length || g.some((value, jIndex) => value !== firstGroup[jIndex]!)
        );

        if (splitPos <= 0 || splitPos >= groups.length) {
            break;
        }

        const remainder = groups.length - splitPos;
        const take = Math.min(remainder, splitPos);

        const newGroups: Group[] = [];
        for (let index = 0; index < splitPos; index++) {
            const combined = [...groups[index]!];
            if (index < take) {
                combined.push(...groups[splitPos + index]!);
            }
            newGroups.push(combined);
        }
        for (let index = splitPos + take; index < groups.length; index++) {
            newGroups.push(groups[index]!);
        }

        groups = newGroups;
        if (groups.length <= 1) {
            break;
        }
    }

    // Flatten
    const pattern: boolean[] = [];
    for (const group of groups) {
        pattern.push(...group);
    }
    while (pattern.length < steps) {
        pattern.push(false);
    }

    // Rotate
    if (rotation > 0 && steps > 0) {
        const rot = rotation % steps;
        return [...pattern.slice(rot), ...pattern.slice(0, rot)];
    }
    return pattern;
}

import { getAllTracks } from '#/modules/Arrangement/useCases';
import { getTrackStrip } from '#/modules/AudioEngine/useCases';

import { type ToasterKit, type DrumEngineType } from '../models/ToasterKit';
import { loadKit } from '../stores/toasterStore';

/**
 * Map TS engine type to Rust DrumEngineType index.
 * Must match toaster/src/pad.rs set_param("engine_type") match arms.
 *
 * Indices 0-12: generic/legacy engines
 * Indices 13-28: circuit-faithful engines (808/909/CR-78)
 */
export const TOASTER_ENGINE_MAP: Record<DrumEngineType, number> = {
    // Circuit-faithful 808 (indices 13-26)
    'kick-808': 13,
    'snare-808': 15,
    'hihat-closed': 16,
    'hihat-open': 16,
    clap: 18,
    cowbell: 23,
    clave: 24,
    rimshot: 25,
    maracas: 26,
    'tom-808-low': 20,
    'tom-808-mid': 21,
    'tom-808-high': 22,
    // Circuit-faithful 909 (indices 14, 17, 19)
    'kick-909': 14,
    'clap-909': 19,
    'hihat-909': 17,
    // CR-78 (indices 27-28)
    'cr78-drum': 27,
    'cr78-metallic': 28,
    // Generic / analog voices (indices 0-12)
    'kick-analog': 0,
    'snare-analog': 1,
    tom: 5,
    cymbal: 6,
    shaker: 11,
    'perc-generic': 4,
    // Melodic / textural
    'modal-tabla': 7,
    'modal-bongo': 7,
    'modal-woodblock': 7,
    'modal-metal': 7,
    'fm-perc': 8,
    sample: 4,
};

export function getToasterControls(): {
    setPadParam: (pad: number, name: string, value: number) => void;
    setParam: (name: string, value: number) => void;
} | null {
    const tracks = getAllTracks();
    const toasterTrack = tracks.find((time) => time.devices.some((data) => data.type === 'toaster'));
    if (!toasterTrack) {
        return null;
    }

    const strip = getTrackStrip(toasterTrack.id);
    if (!strip) {
        return null;
    }

    const dn = strip.deviceNodes.find((data) => data.toasterControls?.ready);
    return dn?.toasterControls ?? null;
}

export function loadToasterKitPreset(kit: ToasterKit): void {
    // Update the UI store first
    loadKit(kit);

    // Forward to the WASM engine
    const controls = getToasterControls();
    if (!controls) {
        return;
    }

    // Kit-level params (snake_case for Rust)
    controls.setParam('master_gain', kit.masterGain);
    controls.setParam('reverb_mix', kit.reverbMix);
    controls.setParam('reverb_decay', kit.reverbDecay);
    controls.setParam('delay_time', kit.delayTime);
    controls.setParam('delay_feedback', kit.delayFeedback);
    controls.setParam('delay_mix', kit.delayMix);
    controls.setParam('lofi_bits', kit.lofiBits);
    controls.setParam('lofi_rate', kit.lofiRate);
    controls.setParam('lofi_mix', kit.lofiMix);

    // Per-pad params (snake_case for Rust)
    for (let index = 0; index < kit.pads.length; index++) {
        const pad = kit.pads[index]!;
        const engineIdx = TOASTER_ENGINE_MAP[pad.engineType] ?? 0;
        controls.setPadParam(index, 'engine_type', engineIdx);

        if (pad.engineType === 'hihat-open') {
            controls.setPadParam(index, 'open', 1);
        }
        if (pad.engineType === 'hihat-closed') {
            controls.setPadParam(index, 'open', 0);
        }

        controls.setPadParam(index, 'volume', pad.volume);
        controls.setPadParam(index, 'pan', pad.pan);
        controls.setPadParam(index, 'tune', pad.tune);
        controls.setPadParam(index, 'decay', pad.decay);
        controls.setPadParam(index, 'tone', pad.tone);
        controls.setPadParam(index, 'drive', pad.drive);
        controls.setPadParam(index, 'filter_cutoff', pad.filterCutoff);
        controls.setPadParam(index, 'filter_resonance', pad.filterResonance);
        controls.setPadParam(index, 'send_reverb', pad.sendReverb);
        controls.setPadParam(index, 'send_delay', pad.sendDelay);

        if (pad.engineParams) {
            for (const [key, value] of Object.entries(pad.engineParams)) {
                controls.setPadParam(index, key, value);
            }
        }
    }
}

/**
 * Note Repeat — hold a pad to retrigger at a tempo-synced rate.
 * MPC-style performance feature. Rate adjustable in real-time.
 * Uses AudioContext clock correction (chained setTimeout) to prevent drift.
 */

import { getAudioTime } from '#/modules/AudioEngine/useCases';

import { triggerToasterPad } from './triggerPad';

type NoteRepeatSession = {
    padIndex: number;
    velocity: number;
    timeoutId: ReturnType<typeof setTimeout>;
    nextTriggerTime: number;
    intervalSec: number;
};

let activeSession: NoteRepeatSession | null = null;

export type NoteRepeatRate = '1/4' | '1/8' | '1/16' | '1/32' | '1/8t' | '1/16t';

function rateToDurationMs(rate: NoteRepeatRate, bpm: number): number {
    const beatMs = 60_000 / bpm;
    switch (rate) {
        case '1/4':
            return beatMs;
        case '1/8':
            return beatMs / 2;
        case '1/16':
            return beatMs / 4;
        case '1/32':
            return beatMs / 8;
        case '1/8t':
            return beatMs / 3;
        case '1/16t':
            return beatMs / 6;
        default:
            throw new Error(`Unknown note repeat rate: ${rate}`);
    }
}

export function stopNoteRepeat(): void {
    if (activeSession) {
        clearTimeout(activeSession.timeoutId);
        activeSession = null;
    }
}

function scheduleNextTrigger(): void {
    if (!activeSession) {
        return;
    }

    triggerToasterPad(activeSession.padIndex, activeSession.velocity);

    activeSession.nextTriggerTime += activeSession.intervalSec;
    const now = getAudioTime();
    const delayMs = Math.max(1, (activeSession.nextTriggerTime - now) * 1000);

    activeSession.timeoutId = setTimeout(scheduleNextTrigger, delayMs);
}

export function startNoteRepeat(padIndex: number, velocity: number, bpm: number, rate: NoteRepeatRate): void {
    stopNoteRepeat();
    const durationMs = rateToDurationMs(rate, bpm);
    const intervalSec = durationMs / 1000;

    triggerToasterPad(padIndex, velocity);

    const nextTriggerTime = getAudioTime() + intervalSec;
    const delayMs = Math.max(1, intervalSec * 1000);
    const timeoutId = setTimeout(scheduleNextTrigger, delayMs);

    activeSession = { padIndex, velocity, timeoutId, nextTriggerTime, intervalSec };
}

export function isNoteRepeating(): boolean {
    return activeSession !== null;
}

export const NOTE_REPEAT_RATES: NoteRepeatRate[] = ['1/4', '1/8', '1/16', '1/32', '1/8t', '1/16t'];

/**
 * Sequencer playback — advances the step sequencer synchronized to AudioContext time.
 * Uses setTimeout with AudioContext clock correction to avoid setInterval drift.
 * Handles: step triggers, probability, conditional triggers, swing, ratcheting, param locks.
 */

import { getAudioTime } from '#/modules/AudioEngine/useCases';

import { type Step, type Pattern } from '../models/ToasterKit';
import { toasterStore } from '../stores/toasterStore';

import { TOASTER_ENGINE_MAP } from './loadToasterKit';
import { morphPatterns } from './patternMorph';
import { getFirstToasterDeviceId } from './toasterParamBridge/getFirstToasterDeviceId';
import { setPadEngineImmediate } from './toasterParamBridge/setPadEngineImmediate';
import { setToasterPadParam } from './toasterParamBridge/setToasterPadParam';
import { triggerToasterPad } from './triggerPad';

// §62.1 — Coalesce 5 module-level mutables into a single holder so the
// playback session lives behind one named handle. Mutation still happens
// through named setters, so importers can't reassign \`running = true\`
// from outside this module.
const sequencerState = {
    running: false,
    fillActive: false,
    playCount: 0,
    /** AudioContext time of the next step tick. */
    nextTickTime: 0,
    timeoutId: null as ReturnType<typeof setTimeout> | null,
};

export function setFillActive(active: boolean): void {
    sequencerState.fillActive = active;
}

function shouldTrigger(step: Step, loopIndex: number): boolean {
    if (!step.active) {
        return false;
    }

    switch (step.condition) {
        case 'fill':
            if (!sequencerState.fillActive) {
                return false;
            }
            break;
        case 'not-fill':
            if (sequencerState.fillActive) {
                return false;
            }
            break;
        case 'first':
            if (loopIndex > 0) {
                return false;
            }
            break;
        case 'not-first':
            if (loopIndex === 0) {
                return false;
            }
            break;
        default:
            break;
    }

    if (step.probability < 1 && Math.random() > step.probability) {
        return false;
    }

    return true;
}

function tick(currentStep: number, bpm: number, stepsPerBeat: number): void {
    if (!sequencerState.running) {
        return;
    }

    const state = toasterStore.value;
    if (!state) {
        return;
    }

    const sourcePattern = state.kit.patterns.find((param) => param.id === state.kit.activePatternId);
    if (!sourcePattern) {
        return;
    }

    let pattern: Pattern = sourcePattern;
    if (state.morph.enabled && state.morph.targetPatternId) {
        const targetPattern = state.kit.patterns.find((param) => param.id === state.morph.targetPatternId);
        if (targetPattern) {
            pattern = morphPatterns(sourcePattern, targetPattern, state.morph.position);
        }
    }

    const totalSteps = pattern.stepsPerBar * pattern.bars;
    const stepDurationMs = 60_000 / bpm / stepsPerBeat;

    const toasterDeviceId = getFirstToasterDeviceId();

    for (const track of pattern.tracks) {
        const trackSteps = track.stepsOverride ?? totalSteps;
        const stepIdx = currentStep % trackSteps;
        const step = track.steps[stepIdx];
        if (!step) {
            continue;
        }
        if (!shouldTrigger(step, sequencerState.playCount)) {
            continue;
        }

        const vel = Math.round(step.velocity * 127);

        const pad = state.kit.pads[track.padIndex];
        if (step.soundLock && pad && toasterDeviceId) {
            const lockIdx = TOASTER_ENGINE_MAP[step.soundLock] ?? 0;
            setPadEngineImmediate(toasterDeviceId, track.padIndex, lockIdx);
        }

        if (toasterDeviceId) {
            const locks = step.paramLocks;
            for (const [key, value] of Object.entries(locks)) {
                if (key.startsWith('_')) {
                    continue;
                }
                setToasterPadParam(
                    toasterDeviceId,
                    track.padIndex,
                    key as keyof import('../models/ToasterKit').PadState,
                    value
                );
            }
        }

        const microOffsetMs = step.microTiming * stepDurationMs;
        const swingMs = stepIdx % 2 === 1 ? state.kit.swing * stepDurationMs * 0.5 : 0;
        const totalDelayMs = Math.max(0, swingMs + microOffsetMs);

        function fire(): void {
            triggerToasterPad(track.padIndex, vel);
            if (step?.soundLock && pad && toasterDeviceId) {
                const defaultIdx = TOASTER_ENGINE_MAP[pad.engineType] ?? 0;
                setPadEngineImmediate(toasterDeviceId, track.padIndex, defaultIdx);
            }
        }

        if (totalDelayMs > 1) {
            setTimeout(fire, totalDelayMs);
        } else {
            fire();
        }

        if (step.retriggerCount > 0) {
            const subInterval = stepDurationMs / (step.retriggerCount + 1);
            for (let r = 1; r <= step.retriggerCount; r++) {
                const retrigVel = Math.max(20, Math.round(vel * (1 - r * 0.12)));
                setTimeout(() => triggerToasterPad(track.padIndex, retrigVel), totalDelayMs + subInterval * r);
            }
        }
    }

    toasterStore.set({ ...state, currentStep, isPlaying: true });

    const stepDurationSec = stepDurationMs / 1000;
    const nextStep = (currentStep + 1) % totalSteps;
    if (nextStep === 0) {
        sequencerState.playCount++;
    }

    sequencerState.nextTickTime += stepDurationSec;
    const now = getAudioTime();
    const delayMs = Math.max(1, (sequencerState.nextTickTime - now) * 1000);

    sequencerState.timeoutId = setTimeout(() => tick(nextStep, bpm, stepsPerBeat), delayMs);
}

export function startSequencer(bpm: number, stepsPerBeat: number = 4): void {
    stopSequencer();
    sequencerState.running = true;
    sequencerState.playCount = 0;
    sequencerState.nextTickTime = getAudioTime();
    tick(0, bpm, stepsPerBeat);
}

export function stopSequencer(): void {
    sequencerState.running = false;
    if (sequencerState.timeoutId !== null) {
        clearTimeout(sequencerState.timeoutId);
        sequencerState.timeoutId = null;
    }
    const state = toasterStore.value;
    if (state) {
        toasterStore.set({ ...state, isPlaying: false, currentStep: 0 });
    }
    sequencerState.playCount = 0;
}

import { getTrackStrip } from '#/modules/AudioEngine/useCases';

import { findDeviceRef } from './helpers';

/**
 * Send engine_type directly to the worklet (bypasses rAF throttle).
 * Used by sound locks which need immediate engine swap before triggering.
 * Does NOT update the store — the pad's stored engineType remains the default.
 */
export function setPadEngineImmediate(deviceId: string, padIndex: number, engineIdx: number): void {
    const ref = findDeviceRef(deviceId);
    if (!ref) {
        return;
    }

    const strip = getTrackStrip(ref.trackId);
    if (!strip) {
        return;
    }
    const dn = strip.deviceNodes.find((data) => data.toasterControls && data.toasterControls.ready !== undefined);
    if (dn?.toasterControls) {
        dn.toasterControls.setPadParam(padIndex, 'engine_type', engineIdx);
    }
}

import { getTrackStrip } from '#/modules/AudioEngine/useCases';

import { type ToasterKit } from '../../models/ToasterKit';
import { updateKit } from '../../stores/toasterStore';

import { findDeviceRef } from './helpers';

const KIT_PARAM_MAP = {
    swing: 'swing',
    masterGain: 'master_gain',
    reverbMix: 'reverb_mix',
    reverbDecay: 'reverb_decay',
    delayTime: 'delay_time',
    delayFeedback: 'delay_feedback',
    delayMix: 'delay_mix',
    lofiBits: 'lofi_bits',
    lofiRate: 'lofi_rate',
    lofiMix: 'lofi_mix',
} as const;

export function setToasterKitParam<Key extends keyof typeof KIT_PARAM_MAP>(
    deviceId: string,
    key: Key,
    value: ToasterKit[Key]
): void {
    updateKit({ [key]: value } as Partial<ToasterKit>);

    const ref = findDeviceRef(deviceId);
    if (!ref) {
        return;
    }

    const paramName = KIT_PARAM_MAP[key];
    const strip = getTrackStrip(ref.trackId);
    if (!strip) {
        return;
    }
    const deviceNode = strip.deviceNodes.find(
        (device) => device.toasterControls && device.toasterControls.ready !== undefined
    );
    if (deviceNode?.toasterControls) {
        deviceNode.toasterControls.setParam(paramName, value as number);
    }
}

import { getTrackStrip } from '#/modules/AudioEngine/useCases';

import { type PadState } from '../../models/ToasterKit';
import { updatePad } from '../../stores/toasterStore';

import { findDeviceRef } from './helpers';

const padPending = new Map<string, number>();
const padLatest = new Map<string, { pad: number; name: string; value: number }>();

const STRING_FIELDS = new Set(['engineType', 'name', 'color']);

function flushPadParam(cacheKey: string, trackId: string): void {
    padPending.delete(cacheKey);
    const entry = padLatest.get(cacheKey);
    if (!entry) {
        return;
    }
    padLatest.delete(cacheKey);

    const strip = getTrackStrip(trackId);
    if (!strip) {
        return;
    }
    const dn = strip.deviceNodes.find((data) => data.toasterControls && data.toasterControls.ready !== undefined);
    if (dn?.toasterControls) {
        dn.toasterControls.setPadParam(entry.pad, entry.name, entry.value);
    }
}

export function setToasterPadParam(deviceId: string, padIndex: number, key: keyof PadState, value: number): void {
    if (!STRING_FIELDS.has(key)) {
        updatePad(padIndex, { [key]: value } as Partial<PadState>);
    }

    const ref = findDeviceRef(deviceId);
    if (!ref) {
        return;
    }

    const cacheKey = `${deviceId}_${padIndex}_${key}`;
    padLatest.set(cacheKey, { pad: padIndex, name: key, value });
    if (!padPending.has(cacheKey)) {
        padPending.set(
            cacheKey,
            requestAnimationFrame(() => flushPadParam(cacheKey, ref.trackId))
        );
    }
}

import { eventBus, logger } from '#/app/registerDependencies';
import { inject } from '#/infra/di/inject';
import { getAllTracks } from '#/modules/Arrangement/useCases';
import { getTrackStrip } from '#/modules/AudioEngine/useCases';

import { toasterStore } from '../stores/toasterStore';
import { TOASTER_ENGINE_MAP } from '../useCases/loadToasterKit';

type DeviceNodeRef = {
    deviceId: string;
    toasterControls?: {
        setParam: (n: string, v: number) => void;
        setPadParam: (pad: number, n: string, v: number) => void;
    };
};

export const initToasterSubscribers = inject({ eventBus, logger })(
    ({ eventBus, logger }) =>
        function initToasterSubscribers(): () => void {
            const unsubscribe = eventBus.on('audioDevice.loaded', (payload) => {
                if (payload.deviceType !== 'toaster') {
                    return;
                }

                logger.info('Hydrating newly loaded Toaster WASM engine with store state');

                const kit = toasterStore.value?.kit;
                const deviceId = payload.deviceId;

                if (!kit) {
                    return;
                }

                let foundStrip;
                for (const track of getAllTracks()) {
                    if (track.devices.some((data) => data.id === deviceId)) {
                        foundStrip = getTrackStrip(track.id);
                        break;
                    }
                }

                const dn = foundStrip?.deviceNodes.find((data: DeviceNodeRef) => data.deviceId === deviceId);
                const tControls = dn?.toasterControls;

                if (!tControls) {
                    return;
                }

                tControls.setParam('master_gain', kit.masterGain);
                tControls.setParam('reverb_mix', kit.reverbMix);
                tControls.setParam('reverb_decay', kit.reverbDecay);
                tControls.setParam('delay_time', kit.delayTime);
                tControls.setParam('delay_feedback', kit.delayFeedback);
                tControls.setParam('delay_mix', kit.delayMix);
                tControls.setParam('lofi_bits', kit.lofiBits);
                tControls.setParam('lofi_rate', kit.lofiRate);
                tControls.setParam('lofi_mix', kit.lofiMix);

                for (let index = 0; index < kit.pads.length; index++) {
                    const pad = kit.pads[index]!;
                    const engineIdx = TOASTER_ENGINE_MAP[pad.engineType] ?? 0;
                    tControls.setPadParam(index, 'engine_type', engineIdx);

                    if (pad.engineType === 'hihat-open') {
                        tControls.setPadParam(index, 'open', 1);
                    }
                    if (pad.engineType === 'hihat-closed') {
                        tControls.setPadParam(index, 'open', 0);
                    }

                    tControls.setPadParam(index, 'volume', pad.volume);
                    tControls.setPadParam(index, 'pan', pad.pan);
                    tControls.setPadParam(index, 'tune', pad.tune);
                    tControls.setPadParam(index, 'decay', pad.decay);
                    tControls.setPadParam(index, 'tone', pad.tone);
                    tControls.setPadParam(index, 'drive', pad.drive);
                    tControls.setPadParam(index, 'filter_cutoff', pad.filterCutoff);
                    tControls.setPadParam(index, 'filter_resonance', pad.filterResonance);
                    tControls.setPadParam(index, 'send_reverb', pad.sendReverb);
                    tControls.setPadParam(index, 'send_delay', pad.sendDelay);
                }
            });

            return unsubscribe;
        }
);

