        name: 'Test',
        items: [],
        currentIndex: 0,
        autoAdvance: false,
        countInBars: 1,
        totalDuration: 0,
        ...overrides,
    };
}

describe('toggleAutoAdvance', () => {
    beforeEach(() => {
        vi.clearAllMocks();
    });

    it('flips autoAdvance', () => {
        mockSetlistStore.value = emptySetlist({ autoAdvance: false });
        toggleAutoAdvance();
        expect(mockSetlistStore.set).toHaveBeenCalledWith(expect.objectContaining({ autoAdvance: true }));
    });
});

import { describe, it, expect, vi, beforeEach } from 'vitest';

import { type SetlistItem, type SetlistState } from '../../../stores/setlistStore';
