        name: 'Old',
        projectPath: null,
        bpm: null,
        timeSignature: null,
        estimatedDuration: 1,
        notes: '',
        programChange: null,
        color: '#000',
        autoStop: true,
        gapSeconds: 0,
        markers: [],
    };
}

describe('updateSetlistItem', () => {
    beforeEach(() => {
        vi.clearAllMocks();
    });

    it('merges updates into matching item', () => {
        const state: SetlistState = {
            name: 'S',
            items: [item('x')],
