import { type ReactElement } from 'react';

import { AlertTriangle, X } from 'lucide-react';

import { Button } from '#/components/ui/button';
import { cn } from '#/utils/Styles/cn';

import { useNotificationQueue } from '../hooks/useNotificationQueue';

export { notifyUser } from '#/utils/Notification/notifyUser';

export const NotificationToast = (): ReactElement | null => {
    const { items, dismissLatest } = useNotificationQueue();

    if (items.length === 0) {
        return null;
    }

    const latest = items[0]!;

    return (
        <div
            className={cn(
                'fixed bottom-16 left-4 z-50 w-80 rounded-lg border p-3 shadow-xl animate-in slide-in-from-left-5',
                (() => {
                    if (latest.level === 'error') {
                        return 'border-[var(--color-state-danger)]/40 bg-[var(--color-state-danger)]/10';
                    }
                    if (latest.level === 'warning') {
                        return 'border-[var(--color-state-warning)]/40 bg-[var(--color-state-warning)]/10';
                    }
                    return 'border-border bg-surface-raised';
                })()
            )}
            role="alert"
            aria-live="assertive"
        >
            <div className="flex items-start gap-2">
                <AlertTriangle
                    className={cn(
                        'mt-0.5 size-4 shrink-0',
                        latest.level === 'error'
                            ? 'text-[var(--color-state-danger)]'
                            : 'text-[var(--color-state-warning)]'
                    )}
                />
                <p className="flex-1 text-xs text-foreground">{latest.message}</p>
                <Button variant="ghost" size="xs" onClick={dismissLatest} aria-label="Dismiss notification">
                    <X className="size-3" />
                </Button>
            </div>
            {items.length > 1 ? (
                <p className="mt-1 text-[10px] text-muted-foreground">+{items.length - 1} more</p>
            ) : null}
        </div>
    );
};

import { type ReactElement, type MouseEvent, useEffect, useRef } from 'react';

import { cn } from '#/utils/Styles/cn';

type ResizeHandleProps = {
    direction: 'horizontal' | 'vertical';
    onResize: (delta: number) => void;
    onResizeEnd?: () => void;
};

export const ResizeHandle = ({ direction, onResize, onResizeEnd }: ResizeHandleProps): ReactElement => {
    const dragging = useRef(false);
    const lastPos = useRef(0);

    useEffect(() => {
        const handleMouseMove = (event: globalThis.MouseEvent) => {
            if (!dragging.current) {
                return;
            }
            const current = direction === 'vertical' ? event.clientX : event.clientY;
            const delta = current - lastPos.current;
            lastPos.current = current;
            onResize(delta);
        };

        const handleMouseUp = () => {
            if (!dragging.current) {
                return;
            }
            dragging.current = false;
            document.body.style.cursor = '';
            document.body.style.userSelect = '';
            onResizeEnd?.();
        };

        document.addEventListener('mousemove', handleMouseMove);
        document.addEventListener('mouseup', handleMouseUp);
        return () => {
            document.removeEventListener('mousemove', handleMouseMove);
            document.removeEventListener('mouseup', handleMouseUp);
        };
    }, [direction, onResize, onResizeEnd]);

    const handleMouseDown = (event: MouseEvent) => {
        event.preventDefault();
        dragging.current = true;
        lastPos.current = direction === 'vertical' ? event.clientX : event.clientY;
        document.body.style.cursor = direction === 'vertical' ? 'col-resize' : 'row-resize';
        document.body.style.userSelect = 'none';
    };

    const isVertical = direction === 'vertical';

    return (
        <div
            className={cn('group relative shrink-0', isVertical ? 'w-1 cursor-col-resize' : 'h-1 cursor-row-resize')}
            onMouseDown={handleMouseDown}
            role="separator"
            aria-orientation={isVertical ? 'vertical' : 'horizontal'}
        >
            <div
                className={cn(
                    'absolute bg-border/40 transition-colors group-hover:bg-ring/60',
                    isVertical ? 'inset-y-0 left-1/2 w-px -translate-x-1/2' : 'inset-x-0 top-1/2 h-px -translate-y-1/2'
                )}
            />
        </div>
    );
};

