/**
 * Spatial Audio Panner component.
 * 2D top-down view with a draggable dot representing the audio source position.
 * Listener is at the center. Shows azimuth circle, distance rings, and L/R labels.
 */
import { type ReactElement, type MouseEvent, useRef, useState, useEffect } from 'react';

import { resolveToken } from '#/utils/UI/resolveToken';

type SpatialPannerProps = {
    size?: number;
    /** Initial azimuth in degrees (0 = front, 90 = right, -90 = left, 180 = behind) */
    azimuth?: number;
    /** Initial distance 0-1 (0 = center, 1 = edge) */
    distance?: number;
    onChange?: (azimuth: number, distance: number) => void;
    color?: string;
};

export const SpatialPanner = ({
    size = 120,
    azimuth: initialAzimuth = 0,
    distance: initialDistance = 0.5,
    onChange,
    color = resolveToken('--color-palette-steel', '#5090c0'),
}: SpatialPannerProps): ReactElement => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const [azimuth, setAzimuth] = useState(initialAzimuth);
    const [distance, setDistance] = useState(initialDistance);
    const dragging = useRef(false);

    const cx = size / 2;
    const cy = size / 2;
    const maxRadius = size * 0.42;

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) {
            return;
        }
        const ctx = canvas.getContext('2d');
        if (!ctx) {
            return;
        }

        ctx.clearRect(0, 0, size, size);

        // Background — radial gradient for depth
        const bgRadial = ctx.createRadialGradient(cx, cy, 0, cx, cy, maxRadius + 4);
        bgRadial.addColorStop(0, '#10101a');
        bgRadial.addColorStop(1, '#060608');
        ctx.fillStyle = bgRadial;
        ctx.beginPath();
        ctx.arc(cx, cy, maxRadius + 4, 0, Math.PI * 2);
        ctx.fill();

        // Distance rings — subtle dotted
        ctx.strokeStyle = 'rgba(255,255,255,0.06)';
        ctx.lineWidth = 0.5;
        ctx.setLineDash([1, 3]);
        for (const r of [0.25, 0.5, 0.75, 1.0]) {
            ctx.beginPath();
            ctx.arc(cx, cy, maxRadius * r, 0, Math.PI * 2);
            ctx.stroke();
        }

        // Crosshair
        ctx.beginPath();
        ctx.moveTo(cx - maxRadius, cy);
        ctx.lineTo(cx + maxRadius, cy);
        ctx.moveTo(cx, cy - maxRadius);
        ctx.lineTo(cx, cy + maxRadius);
        ctx.stroke();
        ctx.setLineDash([]);

        // Labels — very dim
        ctx.fillStyle = '#383838';
        ctx.font = '7px monospace';
        ctx.textAlign = 'center';
        ctx.fillText('F', cx, cy - maxRadius - 2);
        ctx.fillText('B', cx, cy + maxRadius + 8);
        ctx.textAlign = 'left';
        ctx.fillText('L', cx - maxRadius - 8, cy + 3);
        ctx.textAlign = 'right';
        ctx.fillText('R', cx + maxRadius + 8, cy + 3);

        // Listener icon (small circle at center)
        ctx.fillStyle = resolveToken('--color-text-tertiary', '#666');
        ctx.beginPath();
        ctx.arc(cx, cy, 3, 0, Math.PI * 2);
        ctx.fill();

        // Source position
        const rad = ((azimuth - 90) * Math.PI) / 180;
        const sx = cx + Math.cos(rad) * maxRadius * distance;
        const sy = cy + Math.sin(rad) * maxRadius * distance;

        // Line from center to source
        ctx.strokeStyle = `${color}60`;
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(cx, cy);
        ctx.lineTo(sx, sy);
        ctx.stroke();

        // Source dot — glow ring
        ctx.fillStyle = `${color}20`;
        ctx.beginPath();
        ctx.arc(sx, sy, 10, 0, Math.PI * 2);
        ctx.fill();

        // Source dot
        ctx.fillStyle = color;
        ctx.shadowColor = color;
        ctx.shadowBlur = 12;
        ctx.beginPath();
        ctx.arc(sx, sy, 5, 0, Math.PI * 2);
        ctx.fill();
        ctx.shadowBlur = 0;

        // Readout
        ctx.fillStyle = resolveToken('--color-palette-gray', '#888');
        ctx.font = '7px monospace';
        ctx.textAlign = 'center';
        ctx.fillText(`${azimuth.toFixed(0)}° ${(distance * 100).toFixed(0)}%`, cx, size - 2);
    }, [azimuth, distance, size, color, cx, cy, maxRadius]);

    const handlePointer = (event: MouseEvent<HTMLCanvasElement>): void => {
        const canvas = canvasRef.current;
        if (!canvas) {
            return;
        }
        const rect = canvas.getBoundingClientRect();
        const mx = event.clientX - rect.left - cx;
        const my = event.clientY - rect.top - cy;

        const newDist = Math.min(1, Math.sqrt(mx * mx + my * my) / maxRadius);
        const newAz = ((Math.atan2(my, mx) * 180) / Math.PI + 90 + 360) % 360;
        const normalizedAz = newAz > 180 ? newAz - 360 : newAz;

        setAzimuth(Math.round(normalizedAz));
        setDistance(Math.round(newDist * 100) / 100);
        onChange?.(normalizedAz, newDist);
    };

    return (
        <canvas
            ref={canvasRef}
            width={size}
            height={size}
            className="rounded border border-border/30 cursor-crosshair"
            aria-label={`Spatial panner: ${azimuth}° azimuth, ${(distance * 100).toFixed(0)}% distance`}
            role="slider"
            onMouseDown={(event) => {
                dragging.current = true;
                handlePointer(event);
            }}
            onMouseMove={(event) => {
                if (dragging.current) {
                    handlePointer(event);
                }
            }}
            onMouseUp={() => {
                dragging.current = false;
            }}
            onMouseLeave={() => {
                dragging.current = false;
            }}
        />
    );
};

/**
 * Drag interaction helpers for AutomationLaneRow.
 * Each function handles one interaction mode and uses startMouseDrag
 * to manage global listener teardown.
 */
import { type MouseEvent as ReactMouseEvent } from 'react';

import { automationStore } from '#/modules/Automation/stores';
import {
    addAutomationPoint,
    removeAutomationPoint,
    updateAutomationPoint,
    setAutomationPointCurve,
    beginDrawSession,
    paintDrawPoint,
    endDrawSession,
    selectPointsInRange,
} from '#/modules/Automation/useCases';
import { pushUndoEntry } from '#/modules/Command/useCases';

import { type AutomationLane, type AutomationPoint, type AutomationCurveType } from '../../models/AutomationViewTypes';

import { startMouseDrag } from './mouseDrag';

type SetStateFn<State> = (updater: State | ((prev: State) => State)) => void;

type CoordFns = {
    getRect: () => DOMRect | undefined;
    xToBeat: (x: number) => number;
    yToValue: (y: number) => number;
};

// ── Draw mode ────────────────────────────────────────────────────────────────

export const onDrawMouseDown = (
    event: ReactMouseEvent,
    lane: AutomationLane,
    snapValue: number,
    coords: CoordFns
): void => {
    const rect = coords.getRect();
    if (!rect) {
        return;
    }
    const x = event.clientX - rect.left;
    const y = event.clientY - rect.top;
    beginDrawSession(lane.id, snapValue, event.shiftKey);
    paintDrawPoint(Math.max(0, coords.xToBeat(x)), coords.yToValue(y));
    startMouseDrag(
        (me) => {
            paintDrawPoint(Math.max(0, coords.xToBeat(me.clientX - rect.left)), coords.yToValue(me.clientY - rect.top));
        },
        () => {
            endDrawSession();
        }
    );
};

// ── Rubber-band selection ────────────────────────────────────────────────────

export const onRubberBandStart = (
    event: ReactMouseEvent,
    lane: AutomationLane,
    setRubberBand: SetStateFn<{ x1: number; y1: number; x2: number; y2: number } | null>,
    setSelectedPoints: SetStateFn<number[]>,
    coords: CoordFns
): void => {
    const isOnPoint = (event.target as Element).closest('[data-auto-point]');
    const isOnTension = (event.target as Element).closest('[data-tension-handle]');
    if (isOnPoint || isOnTension) {
        return;
    }
    const rect = coords.getRect();
    if (!rect) {
        return;
    }
    const x = event.clientX - rect.left;
    const y = event.clientY - rect.top;
    const isShift = event.shiftKey;

    if (!isShift) {
        setSelectedPoints([]);
    }
    setRubberBand({ x1: x, y1: y, x2: x, y2: y });

    startMouseDrag(
        (me) => {
            setRubberBand((prev) => {
                if (!prev) {
                    return null;
                }
                return { ...prev, x2: me.clientX - rect.left, y2: me.clientY - rect.top };
            });
        },
        (me) => {
            const mx = me.clientX - rect.left;
            const my = me.clientY - rect.top;
            const hasDragged = Math.abs(mx - x) > 4 || Math.abs(my - y) > 4;
            if (hasDragged) {
                const found = selectPointsInRange(
                    lane.id,
                    coords.xToBeat(Math.min(x, mx)),
                    coords.xToBeat(Math.max(x, mx)),
                    coords.yToValue(Math.max(y, my)),
                    coords.yToValue(Math.min(y, my))
                );
                if (isShift) {
                    setSelectedPoints((prev) => {
                        const set = new Set(prev);
                        for (const beat of found) {
                            if (set.has(beat)) {
                                set.delete(beat);
                            } else {
                                set.add(beat);
                            }
                        }
                        return [...set];
                    });
                } else {
                    setSelectedPoints(found);
                }
            } else if (!isShift) {
                const beat = Math.max(0, coords.xToBeat(x));
                const value = coords.yToValue(y);
                const point: AutomationPoint = { beat, value, curve: 'linear', tension: 0 };
                addAutomationPoint(lane.id, point);
                pushUndoEntry(
                    'Add automation point',
                    () => {
                        removeAutomationPoint(lane.id, beat);
                    },
                    () => {
                        addAutomationPoint(lane.id, point);
                    }
                );
            }
            setRubberBand(null);
        }
    );
};

// ── Tension handle drag ───────────────────────────────────────────────────────

export const onTensionMouseDown = (
    pointBeat: number,
    event: ReactMouseEvent,
    lane: AutomationLane,
    setTensionDrag: SetStateFn<{ beat: number; initialTension: number } | null>
): void => {
    event.stopPropagation();
    const point = lane.points.find((param) => param.beat === pointBeat);
    if (!point) {
        return;
    }
    const initialTension = point.tension ?? 0;
    setTensionDrag({ beat: pointBeat, initialTension });
    const startY = event.clientY;
    startMouseDrag(
        (me) => {
            const newTension = Math.max(-1, Math.min(1, initialTension + (me.clientY - startY) / 100));
            setAutomationPointCurve(lane.id, pointBeat, point.curve, newTension);
        },
        () => {
            setTensionDrag(null);
        }
    );
};

// ── Breakpoint drag ───────────────────────────────────────────────────────────

export const onPointMouseDown = (
    pointBeat: number,
    event: ReactMouseEvent,
    lane: AutomationLane,
    setDragPointBeat: SetStateFn<number | null>,
    setSelectedPoints: SetStateFn<number[]>,
    coords: CoordFns
): void => {
    event.stopPropagation();
    const rect = coords.getRect();
    if (!rect) {
        return;
    }

    if (event.shiftKey) {
        setSelectedPoints((prev) =>
            prev.includes(pointBeat) ? prev.filter((b) => b !== pointBeat) : [...prev, pointBeat]
        );
        return;
    }

    const origPoint = lane.points.find((param) => param.beat === pointBeat);
    if (!origPoint) {
        return;
    }
    const origBeat = origPoint.beat;
    const origValue = origPoint.value;
    let currentBeat = pointBeat;
    setDragPointBeat(pointBeat);

    startMouseDrag(
        (me) => {
            let newBeat = Math.max(0, coords.xToBeat(me.clientX - rect.left));
            let newValue = coords.yToValue(me.clientY - rect.top);
            if (me.shiftKey) {
                const dx = Math.abs(newBeat - origBeat);
                const dy = Math.abs(newValue - origValue);
                if (dx > dy) {
                    newValue = origValue;
                } else {
                    newBeat = origBeat;
                }
            }
            updateAutomationPoint(lane.id, currentBeat, newValue, newBeat);
            currentBeat = newBeat;
            setDragPointBeat(newBeat);
        },
        () => {
            setDragPointBeat(null);
            const finalLane = automationStore.value?.lanes.find((length) => length.id === lane.id);
            const finalPoint = finalLane?.points.find((param) => Math.abs(param.beat - currentBeat) < 0.05);
            const hasMoved =
                finalPoint !== undefined && (finalPoint.beat !== origBeat || finalPoint.value !== origValue);
            if (hasMoved) {
                const finalBeat = finalPoint.beat;
                const finalValue = finalPoint.value;
                pushUndoEntry(
                    'Move automation point',
                    () => {
                        updateAutomationPoint(lane.id, finalBeat, origValue, origBeat);
                    },
                    () => {
                        updateAutomationPoint(lane.id, origBeat, finalValue, finalBeat);
                    }
                );
            }
        }
    );
};

