            const noteClipId = drag.ownerClipId ?? clipId;
            const { noteId, origBeat, origDuration, mode } = drag;
            const preview = dragPreviewRef.current;

            if (mode === 'duplicate' && preview && (preview.beatDelta !== 0 || preview.pitchDelta !== 0)) {
