                pushUndoEntry(
                    `Duplicate ${targetsWithClip.length} note${targetsWithClip.length > 1 ? 's' : ''} forward`,
                    () => {
                        for (const entry of copyByClip) {
                            removeNotesByIds(entry.clipId, entry.ids);
                        }
