import { type KeyboardEvent, type RefObject, type FormEvent, useState, useRef, useEffect } from 'react';

import { logger } from '#/infra/logger/appLogger';
import { useStore } from '#/infra/store/useStore';
import { llmStatusStore, pushAiActionGroup } from '#/modules/AiRuntime/stores';
import {
    parsePromptToActions,
    isComplexPrompt,
    getProjectContext,
    searchPresets,
    getAvailablePresets,
    resolvePresetActions,
    onPromptInjection,
    notifyAiChange,
    isLlmAvailable,
    initEngine,
} from '#/modules/AiRuntime/useCases';
import { defaultTrackState, trackStore } from '#/modules/Arrangement/stores';
import { executeAppAction, generateGroupId, describeAction } from '#/modules/Command/useCases';

import { defaultWorkspaceState } from '../../models/WorkspaceState';
import { workspaceStore } from '../../stores/workspaceStore';

const defaultLlmStatus: typeof llmStatusStore.value = { state: 'idle' };

// ── Selection tag type ──────────────────────────────────────────────────

export type SelectionTag = {
    id: string;
    label: string;
    kind: 'track' | 'clip' | 'clips';
    icon: 'track' | 'clip' | 'clips';
};

type PromptPresetCategory =
    | 'Transport'
    | 'Track'
    | 'Clip'
    | 'MIDI'
    | 'Device'
    | 'Workspace'
    | 'Mix'
    | 'Generate'
    | 'File'
    | 'Automation'
    | 'Collaboration';

export type PromptFuzzyResult = {
    preset: {
        id: string;
        label: string;
        category: PromptPresetCategory;
        isDestructive: boolean;
    };
    score: number;
};

type PromptAction = Awaited<ReturnType<typeof parsePromptToActions>>['actions'][number];

type PromptPreview = {
    actions: PromptAction[];
    confidence: number;
    rawText: string;
    requiresConfirmation: boolean;
    _jsonEditApplied?: boolean;
    _jsonEditSummaries?: string[];
    _jsonEditAttempted?: boolean;
};

// ── Hook return type ────────────────────────────────────────────────────

export type PromptExecutionState = {
    value: string;
    setValue: (v: string) => void;
    isProcessing: boolean;
    preview: PromptPreview | null;
    fuzzyResults: PromptFuzzyResult[];
    selectedIndex: number;
    selectionTags: SelectionTag[];
    isFocused: boolean;
    setIsFocused: (v: boolean) => void;
    willUseLlm: boolean;

    inputRef: RefObject<HTMLInputElement | null>;
    formRef: RefObject<HTMLFormElement | null>;

    llmStatus: typeof llmStatusStore.value;

    handleKeyDown: (e: KeyboardEvent<HTMLInputElement>) => void;
    handleSubmit: (e: FormEvent) => void;
    executePreset: (result: PromptFuzzyResult) => Promise<void>;
    confirmPreview: () => Promise<void>;
    cancelPreview: () => void;
    cancelProcessing: () => void;
    handleLoadModel: (modelId?: string) => void;
    dismissTag: (id: string) => void;
};

/**
 * Encapsulates all prompt bar state, effects, and business logic.
 * The view becomes a pure render function consuming this hook.
 */
export const usePromptExecution = (): PromptExecutionState => {
    const [value, setValue] = useState('');
    const [isProcessing, setIsProcessing] = useState(false);
    const [preview, setPreview] = useState<PromptPreview | null>(null);
    const [fuzzyResults, setFuzzyResults] = useState<PromptFuzzyResult[]>([]);
    const [selectedIndex, setSelectedIndex] = useState(-1);
    const [dismissedTags, setDismissedTags] = useState<Set<string>>(new Set());
    const [isFocused, setIsFocused] = useState(false);
    const inputRef = useRef<HTMLInputElement>(null);
    const formRef = useRef<HTMLFormElement>(null);
    const abortRef = useRef<AbortController | null>(null);
    const pendingSubmitRef = useRef(false);

    const llmStatus = useStore(llmStatusStore, defaultLlmStatus);
    const trackState = useStore(trackStore, defaultTrackState);
    const wsState = useStore(workspaceStore, defaultWorkspaceState);

    // ── Derive selection tags ───────────────────────────────────────────
    const selectionTags: SelectionTag[] = [];
    const selectedTrackId = trackState?.selectedTrackId;
    const selectedClipId = wsState?.selectedClipId;
    const selectedClipIds = wsState?.selectedClipIds ?? [];

    if (selectedTrackId) {
        const track = trackState?.tracks.find((time) => time.id === selectedTrackId);
        if (track && !dismissedTags.has(`track:${selectedTrackId}`)) {
            selectionTags.push({ id: `track:${selectedTrackId}`, label: track.name, kind: 'track', icon: 'track' });
        }
    }
    if (selectedClipIds.length > 1) {
        const key = `clips:${selectedClipIds.length}`;
        if (!dismissedTags.has(key)) {
            selectionTags.push({ id: key, label: `${selectedClipIds.length} clips`, kind: 'clips', icon: 'clips' });
        }
    } else if (selectedClipId) {
        const allClips = trackState?.tracks.flatMap((time) => time.clips) ?? [];
        const clip = allClips.find((context) => context.id === selectedClipId);
        if (clip && !dismissedTags.has(`clip:${selectedClipId}`)) {
            selectionTags.push({ id: `clip:${selectedClipId}`, label: clip.name, kind: 'clip', icon: 'clip' });
        }
    }

    // ── Build preset context ────────────────────────────────────────────
    const presetContext = {
        selectedTrackId: selectedTrackId ?? undefined,
        selectedClipId: selectedClipId ?? undefined,
        selectedClipType: (() => {
            const allClips = trackState?.tracks.flatMap((time) => time.clips) ?? [];
            const clip = allClips.find((context) => context.id === selectedClipId);
            return clip?.type;
        })(),
        trackCount: trackState?.tracks.length ?? 0,
    };

    // ── Reset dismissed tags when selection changes ─────────────────────
    useEffect(() => {
        setDismissedTags(new Set());
    }, [selectedTrackId, selectedClipId, selectedClipIds]);

    // ── Voice injection (auto-submit after setting value) ────────────────
    useEffect(() => {
        return onPromptInjection((text) => {
            setValue((prev) => (prev ? `${prev} ${text}` : text));
            pendingSubmitRef.current = true;
            inputRef.current?.focus();
        });
    }, []);

    // ── Pending submit after value change ───────────────────────────────
    useEffect(() => {
        if (pendingSubmitRef.current && value.trim().length > 0) {
            pendingSubmitRef.current = false;
            formRef.current?.requestSubmit();
        }
    }, [value]);

    // ── Fuzzy search on input change ────────────────────────────────────
    useEffect(() => {
        if (preview || isProcessing) {
            setFuzzyResults([]);
            return;
        }
        if (!isFocused) {
            setFuzzyResults([]);
            return;
        }

        const trimmed = value.trim();
        if (trimmed.length === 0) {
            const available = getAvailablePresets(presetContext);
            setFuzzyResults(available.slice(0, 10).map((preset) => ({ preset, score: 0 })));
        } else {
            const results = searchPresets(trimmed, presetContext, 10);
            setFuzzyResults(results);
        }
        setSelectedIndex(-1);
    }, [value, preview, isFocused, isProcessing, trackState, wsState]);

    // ── Execute action group ────────────────────────────────────────────
    const executeWithGroup = async (actions: PromptAction[], prompt: string): Promise<void> => {
        const group = generateGroupId(prompt);
        const executedLabels: Array<{ action: PromptAction; label: string }> = [];

        for (const action of actions) {
            await executeAppAction(action, { ...group, source: 'prompt' });
            executedLabels.push({ action, label: describeAction(action) });
        }

        if (actions.length > 0) {
            const historyGroup = {
                id: group.groupId,
                prompt,
                actions: executedLabels.map((length) => ({
                    kind: 'appAction' as const,
                    actionType: length.action.type,
                    label: length.label,
                })),
                groupId: group.groupId,
                timestamp: Date.now(),
                reverted: false,
            };
            pushAiActionGroup(historyGroup);
        }
    };

    // ── Execute preset directly ─────────────────────────────────────────
    const executePreset = async (result: PromptFuzzyResult): Promise<void> => {
        const actions = resolvePresetActions({
            presetId: result.preset.id,
            context: presetContext,
        });
        if (actions.length === 0) {
            return;
        }

        if (result.preset.isDestructive) {
            setPreview({
                actions,
                confidence: 0.95,
                rawText: result.preset.label,
                requiresConfirmation: true,
            });
            setValue(result.preset.label);
            setFuzzyResults([]);
            return;
        }

        setFuzzyResults([]);
        setIsProcessing(true);
        try {
            await executeWithGroup(actions, result.preset.label);
            if (actions.length > 0) {
                notifyAiChange(
                    `Executed: ${result.preset.label}`,
                    actions.map((alpha) => alpha.type)
                );
            }
        } catch (error) {
            logger.error(new Error('Preset execution failed', { cause: error }));
        } finally {
            setIsProcessing(false);
            setValue('');
        }
    };

    // ── Full prompt submission (for complex / LLM) ──────────────────────
    const handleSubmit = async (event: FormEvent): Promise<void> => {
        event.preventDefault();
        if (!value.trim() || isProcessing) {
            return;
        }

        setFuzzyResults([]);
        setIsProcessing(true);
        const controller = new AbortController();
        abortRef.current = controller;
        // §188.1 — track the clear-on-finish decision locally instead of
        // reading the `preview` state closure from `finally`. The closure
        // captures the preview value as of when handleSubmit started; any
        // `setPreview(result)` earlier in the same invocation is invisible
        // to it, so the previous code cleared the input even when the user
        // had just been shown a confirmation preview.
        let shouldClearValue = true;
        try {
            const context = getProjectContext();
            const result = await parsePromptToActions(value, context, controller.signal);

            if (controller.signal.aborted) {
                return;
            }

            if (result.requiresConfirmation && result.actions.length > 0) {
                setPreview(result);
                setIsProcessing(false);
                shouldClearValue = false;
                return;
            }

            // If the JSON editor already applied changes, we're done
            if (result._jsonEditApplied) {
                notifyAiChange(result._jsonEditSummaries?.join('. ') ?? `Executed: ${value}`, []);
            } else if (result.actions.length > 0) {
                await executeWithGroup(result.actions, value);
                notifyAiChange(
                    `Executed: ${value}`,
                    result.actions.map((alpha) => alpha.type)
                );
            } else {
                notifyAiChange('No actions matched. Try rephrasing, or use the AI Chat panel for open-ended help.', []);
            }
        } catch (error) {
            logger.error(new Error('Prompt execution failed', { cause: error }));
        } finally {
            abortRef.current = null;
            setIsProcessing(false);
            if (shouldClearValue) {
                setValue('');
            }
        }
    };

    const confirmPreview = async (): Promise<void> => {
        if (!preview) {
            return;
        }
        await executeWithGroup(preview.actions, value);
        notifyAiChange(
            `Confirmed: ${value}`,
            preview.actions.map((alpha) => alpha.type)
        );
        setPreview(null);
        setValue('');
    };

    const cancelPreview = (): void => {
        setPreview(null);
    };

    const cancelProcessing = (): void => {
        abortRef.current?.abort();
        abortRef.current = null;
        setIsProcessing(false);
    };

    // ── Keyboard navigation ─────────────────────────────────────────────
    const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>): void => {
        if (fuzzyResults.length > 0) {
            if (event.key === 'ArrowDown') {
                event.preventDefault();
                setSelectedIndex((prev) => Math.min(prev + 1, fuzzyResults.length - 1));
            } else if (event.key === 'ArrowUp') {
                event.preventDefault();
                setSelectedIndex((prev) => Math.max(prev - 1, -1));
            } else if (event.key === 'Tab' && selectedIndex >= 0) {
                event.preventDefault();
                const selected = fuzzyResults[selectedIndex];
                if (selected) {
                    setValue(selected.preset.label);
                    setFuzzyResults([]);
                }
            } else if (event.key === 'Enter' && selectedIndex >= 0) {
                event.preventDefault();
                const selected = fuzzyResults[selectedIndex];
                if (selected) {
                    void executePreset(selected);
                }
            } else if (event.key === 'Escape') {
                event.preventDefault();
                setFuzzyResults([]);
                setSelectedIndex(-1);
            }
        }
    };

    const handleLoadModel = (modelId?: string): void => {
        if (isLlmAvailable()) {
            void initEngine(modelId);
        }
    };

    const willUseLlm = value.trim().length > 0 && isComplexPrompt(value.toLowerCase().trim());

    const dismissTag = (id: string): void => {
        setDismissedTags((prev) => new Set([...prev, id]));
    };

    return {
        value,
        setValue,
        isProcessing,
        preview,
        fuzzyResults,
        selectedIndex,
        selectionTags,
        isFocused,
        setIsFocused,
        willUseLlm,
        inputRef,
        formRef,
        llmStatus,
        handleKeyDown,
        handleSubmit,
        executePreset,
        confirmPreview,
        cancelPreview,
        cancelProcessing,
        handleLoadModel,
        dismissTag,
    };
};

import { type RefObject, useEffect, useRef } from 'react';

import { getDawStatusDotClassName } from '#/components/daw/DawStatusDot';
import { getEngineState, getMasterPeakLevel } from '#/modules/AudioEngine/useCases';
import { animationScheduler } from '#/utils/DOM/AnimationScheduler';

/**
 * Refs for DOM elements that StatusBar updates at 60 fps via direct mutation.
 * The hook registers an animation tick that writes to these refs every frame.
 */
export type StatusBarMetricRefs = {
    cpuBar: RefObject<HTMLDivElement | null>;
    cpuText: RefObject<HTMLSpanElement | null>;
    memContainer: RefObject<HTMLDivElement | null>;
    memText: RefObject<HTMLSpanElement | null>;
    sampleRate: RefObject<HTMLSpanElement | null>;
    latency: RefObject<HTMLSpanElement | null>;
    masterLevelBar: RefObject<HTMLDivElement | null>;
    masterLevelText: RefObject<HTMLSpanElement | null>;
    engineState: RefObject<HTMLSpanElement | null>;
};

/**
 * Drives StatusBar CPU / memory / latency / level meters at animation-frame rate
 * via direct DOM mutations (bypassing React renders for performance).
 */
export const useStatusBarMetrics = (refs: StatusBarMetricRefs): void => {
    const idRef = useRef(crypto.randomUUID());
    const lastFrameRef = useRef(0);
    // §162.x — ring buffer for CPU samples. 30-entry Array.shift() on
    // every status-bar tick was O(n); fixed-size Float32Array + head
    // index gives O(1) push.
    const CPU_SAMPLE_WINDOW = 30;
    const cpuSamplesRef = useRef<Float32Array>(new Float32Array(CPU_SAMPLE_WINDOW));
    const cpuHeadRef = useRef(0);
    const cpuFilledRef = useRef(0);
    const idleDeadlineRef = useRef(-1);

    useEffect(() => {
        lastFrameRef.current = performance.now();

        // requestIdleCallback loop — measures how much idle time the browser has
        let idleId = 0;
        const scheduleIdle = (): void => {
            if (typeof requestIdleCallback === 'function') {
                idleId = requestIdleCallback((deadline) => {
                    idleDeadlineRef.current = deadline.timeRemaining();
                    scheduleIdle();
                });
            }
        };
        scheduleIdle();

        const tick = (): void => {
            const now = performance.now();
            const frameDelta = now - lastFrameRef.current;
            lastFrameRef.current = now;

            const engineInfo = getEngineState();
            const masterLevel = getMasterPeakLevel();

            // ── CPU load estimate ───────────────────────────────────────
            // Uses requestIdleCallback to measure how much of each frame is
            // consumed by work. If the browser has no idle time, CPU is high.
            // This is the most accurate browser-available method short of
            // AudioWorklet self-timing.
            const targetFrameMs = 1000 / 60;

            // Frame overrun: how much we exceeded the 16.67ms budget
            const frameOverrun = Math.max(0, frameDelta - targetFrameMs);
            const frameLoad = Math.min(100, (frameOverrun / targetFrameMs) * 120);

            // Idle time measurement: if the browser reports idle time via
            // the idleDeadline ref, use it to estimate how busy the main thread is.
            // No idle time = 100% busy. Full idle time (~50ms) = 0% busy.
            let idleLoad = 0;
            const deadline = idleDeadlineRef.current;
            if (deadline >= 0) {
                // deadline is the remaining idle ms (0 = fully busy, 50 = fully idle)
                idleLoad = Math.min(100, Math.max(0, (1 - deadline / 50) * 100));
                idleDeadlineRef.current = -1; // consumed
            }

            // Combine: higher of frame jank or idle pressure
            const isPlaying = engineInfo?.state === 'running';
            const floor = isPlaying ? 3 : 0;
            const load = Math.max(floor, frameLoad, idleLoad);
            const samples = cpuSamplesRef.current;
            samples[cpuHeadRef.current] = Math.max(0, load);
            cpuHeadRef.current = (cpuHeadRef.current + 1) % CPU_SAMPLE_WINDOW;
            if (cpuFilledRef.current < CPU_SAMPLE_WINDOW) {
                cpuFilledRef.current++;
            }
            const filled = cpuFilledRef.current;
            let sum = 0;
            for (let index = 0; index < filled; index++) {
                sum += samples[index]!;
            }
            const cpuPct = filled > 0 ? Math.round(sum / filled) : 0;

            if (refs.cpuBar.current) {
                refs.cpuBar.current.style.width = `${Math.min(100, cpuPct)}%`;
                // Toggle only the color class so we don't clobber the
                // tailwind layout classes each frame (§136.1).
                const cls = refs.cpuBar.current.classList;
                cls.toggle('bg-[var(--color-state-success)]', cpuPct < 50);
                cls.toggle('bg-[var(--color-state-warning)]', cpuPct >= 50 && cpuPct < 80);
                cls.toggle('bg-[var(--color-state-danger)]', cpuPct >= 80);
            }
            if (refs.cpuText.current) {
                refs.cpuText.current.textContent = `${cpuPct}%`;
            }

            // ── Memory ──────────────────────────────────────────────────
            const perfMemory = (performance as unknown as { memory?: { usedJSHeapSize: number } }).memory;
            if (perfMemory) {
                const memMb = Math.round(perfMemory.usedJSHeapSize / (1024 * 1024));
                if (refs.memContainer.current) {
                    refs.memContainer.current.style.display = memMb > 0 ? 'flex' : 'none';
                }
                if (refs.memText.current) {
                    refs.memText.current.textContent = `${memMb} MB`;
                }
            } else {
                if (refs.memContainer.current) {
                    refs.memContainer.current.style.display = 'none';
                }
            }

            // ── Audio engine info ───────────────────────────────────────
            if (refs.sampleRate.current) {
                refs.sampleRate.current.textContent = `${engineInfo.sampleRate / 1000}kHz`;
            }
            if (refs.latency.current) {
                refs.latency.current.textContent = `${(engineInfo.baseLatency * 1000).toFixed(1)}ms`;
            }
            if (refs.engineState.current) {
                refs.engineState.current.className = getDawStatusDotClassName({
                    tone: engineInfo.state === 'running' ? 'success' : 'muted',
                });
                refs.engineState.current.title = `Engine: ${engineInfo.state}`;
            }

            // ── Master level ────────────────────────────────────────────
            const levelDb = masterLevel > 0 ? (20 * Math.log10(masterLevel)).toFixed(1) : '-∞';
            if (refs.masterLevelBar.current) {
                refs.masterLevelBar.current.style.width = `${Math.min(100, masterLevel * 300)}%`;
            }
            if (refs.masterLevelText.current) {
                refs.masterLevelText.current.textContent = `${levelDb} dB`;
            }
        };

        animationScheduler.register(`status-${idRef.current}`, tick);
        return () => {
            animationScheduler.unregister(`status-${idRef.current}`);
            if (typeof cancelIdleCallback === 'function' && idleId) {
                cancelIdleCallback(idleId);
            }
        };
    }, [refs]);
};

/**
 * WebGPU Spectrum Analyzer and Spectrogram Renderer.
 * Consolidates multiple implementations into a unified high-performance pipeline.
 * R-C2: Unified WebGPU pipeline for 2048-bin FFT data.
 * R-C3: Heatmap view using frequency history.
 */

const SHADER = /* wgsl */ `
struct VertexOut {
    @builtin(position) pos : vec4f,
    @location(0)       uv  : vec2f,
}

@vertex
fn vs_main(@builtin(vertex_index) idx: u32) -> VertexOut {
    var pos = array<vec2f, 4>(
        vec2f(-1.0, -1.0),
        vec2f( 1.0, -1.0),
        vec2f(-1.0,  1.0),
        vec2f( 1.0,  1.0)
    );
    var uv = array<vec2f, 4>(
        vec2f(0.0, 1.0),
        vec2f(1.0, 1.0),
        vec2f(0.0, 0.0),
        vec2f(1.0, 0.0)
    );
    var out: VertexOut;
    out.pos = vec4f(pos[idx], 0.0, 1.0);
    out.uv = uv[idx];
    return out;
}

@group(0) @binding(0) var<storage, read> freqData: array<f32>;
@group(0) @binding(1) var<storage, read> heatmapData: array<f32>;
@group(0) @binding(2) var<uniform> params: Params;

struct Params {
    width: f32,
    height: f32,
    numBins: f32,
    sampleRate: f32,
    showHeatmap: f32, // 1.0 = heatmap, 0.0 = spectrum
    historyCount: f32,
}

fn freqToLogX(freq: f32, width: f32, maxFreq: f32) -> f32 {
    let minFreq = 20.0;
    if (freq <= minFreq) { return 0.0; }
    return (log2(freq / minFreq) / log2(maxFreq / minFreq)) * width;
}

@fragment
fn fs_main(@location(0) uv: vec2f) -> @location(0) vec4f {
    let maxFreq = min(22000.0, params.sampleRate / 2.0);

    if (params.showHeatmap > 0.5) {
        // Heatmap rendering
        // uv.x = frequency (log), uv.y = time history
        let logFreq = pow(2.0, uv.x * log2(maxFreq / 20.0)) * 20.0;
        let binIdx = (logFreq / (params.sampleRate / 2.0)) * params.numBins;
        let historyIdx = floor(uv.y * params.historyCount);

        let val = heatmapData[u32(historyIdx * params.numBins + binIdx)];
        // Color mapping: black -> blue -> cyan -> yellow -> red
        return vec4f(
            smoothstep(0.5, 0.9, val) + smoothstep(0.8, 1.0, val),
            smoothstep(0.3, 0.7, val),
            smoothstep(0.0, 0.4, val) - smoothstep(0.6, 1.0, val),
            1.0
        );
    } else {
        // Spectrum rendering (line/area)
        let logFreq = pow(2.0, uv.x * log2(maxFreq / 20.0)) * 20.0;
        let binIdx = (logFreq / (params.sampleRate / 2.0)) * params.numBins;

        let db = freqData[u32(binIdx)];
        let tiltedDb = db + 3.0 * log2(max(1.0, logFreq / 1000.0));
        let normalizedY = (tiltedDb + 80.0) / 80.0;

        if (1.0 - uv.y < normalizedY) {
            return vec4f(uv.x, 0.5, 1.0 - uv.x, 0.3 * (normalizedY - (1.0 - uv.y)));
        }
        return vec4f(0.0, 0.0, 0.0, 0.0);
    }
}
`;

export type SpectrumRenderer = {
    render(freqData: Float32Array, showHeatmap: boolean): void;
    resize(width: number, height: number): void;
    dispose(): void;
};

export async function createWebGpuSpectrumRenderer(
    canvas: HTMLCanvasElement,
    numBins: number,
    sampleRate: number
): Promise<SpectrumRenderer | null> {
    if (!navigator.gpu) {
        return null;
    }

    try {
        const adapter = await navigator.gpu.requestAdapter();
        if (!adapter) {
            return null;
        }
        const device = await adapter.requestDevice();
        const context = canvas.getContext('webgpu')!;
        const format = navigator.gpu.getPreferredCanvasFormat();
        context.configure({ device, format });

        const shader = device.createShaderModule({ code: SHADER });
        const pipeline = device.createRenderPipeline({
            layout: 'auto',
            vertex: { module: shader, entryPoint: 'vs_main' },
            fragment: {
                module: shader,
                entryPoint: 'fs_main',
                targets: [
                    {
                        format,
                        blend: {
                            color: { srcFactor: 'src-alpha', dstFactor: 'one-minus-src-alpha', operation: 'add' },
                            alpha: { srcFactor: 'one', dstFactor: 'one-minus-src-alpha', operation: 'add' },
                        },
                    },
                ],
            },
            primitive: { topology: 'triangle-strip' },
        });

        const HISTORY_COUNT = 120;
        const freqBuf = device.createBuffer({
            size: numBins * 4,
            usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST,
        });
        const heatmapBuf = device.createBuffer({
            size: numBins * HISTORY_COUNT * 4,
            usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST,
        });
        const paramBuf = device.createBuffer({
            size: 32, // 6 floats
            usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST,
        });

        const bindGroup = device.createBindGroup({
            layout: pipeline.getBindGroupLayout(0),
            entries: [
                { binding: 0, resource: { buffer: freqBuf } },
                { binding: 1, resource: { buffer: heatmapBuf } },
                { binding: 2, resource: { buffer: paramBuf } },
            ],
        });

        let currentHistoryHead = 0;
        const heatmapHistory = new Float32Array(numBins * HISTORY_COUNT);

        function render(freqData: Float32Array, showHeatmap: boolean): void {
            // Update heatmap history
            if (showHeatmap) {
                heatmapHistory.set(freqData, currentHistoryHead * numBins);
                currentHistoryHead = (currentHistoryHead + 1) % HISTORY_COUNT;
                device.queue.writeBuffer(heatmapBuf, 0, heatmapHistory);
            }

            device.queue.writeBuffer(freqBuf, 0, freqData);
            device.queue.writeBuffer(
                paramBuf,
                0,
                new Float32Array([canvas.width, canvas.height, numBins, sampleRate, showHeatmap ? 1 : 0, HISTORY_COUNT])
            );

            const encoder = device.createCommandEncoder();
            const view = context.getCurrentTexture().createView();
            const pass = encoder.beginRenderPass({
                colorAttachments: [
                    {
                        view,
                        clearValue: { r: 0.02, g: 0.02, b: 0.03, a: 1.0 },
                        loadOp: 'clear',
                        storeOp: 'store',
                    },
                ],
            });
            pass.setPipeline(pipeline);
            pass.setBindGroup(0, bindGroup);
            pass.draw(4);
            pass.end();
            device.queue.submit([encoder.finish()]);
        }

        function resize(w: number, h: number): void {
            const dpr = window.devicePixelRatio || 1;
            canvas.width = w * dpr;
            canvas.height = h * dpr;
            canvas.style.width = `${w}px`;
            canvas.style.height = `${h}px`;
        }

        function dispose(): void {
            device.destroy();
        }

        return { render, resize, dispose };
    } catch (error) {
        console.error('Failed to create WebGPU Spectrum Renderer:', error);
        return null;
    }
}

