import { type ReactElement, type WheelEvent, useRef } from 'react';

import { X } from 'lucide-react';

import { DawBlockedState } from '#/components/daw/DawBlockedState';
import { Button } from '#/components/ui/button';
import { useStore } from '#/infra/store/useStore';
import { ArrangementBar } from '#/modules/Arrangement/presentations/views';
import { timelineViewStore, scrollTimeline, setScrollY } from '#/modules/Arrangement/stores';

import { toggleAutomationPanel } from '../../useCases/togglePanel/panelToggles/toggleAutomationPanel';
import { useTracks } from '../hooks/useTracks';

import { TrackAutomationSection } from './AutomationView/TrackAutomationSection';

type AutomationTimelineState = {
    scrollX: number;
    scrollY: number;
    pixelsPerBeat: number;
    autoScrollEnabled: boolean;
};

export const AutomationView = (): ReactElement => {
    const { tracks } = useTracks();
    const containerRef = useRef<HTMLDivElement>(null);

    const viewState = useStore<AutomationTimelineState>(timelineViewStore, {
        scrollX: 0,
        scrollY: 0,
        pixelsPerBeat: 12,
        autoScrollEnabled: true,
    });

    const pixelsPerBeat = viewState.pixelsPerBeat;
    const scrollX = viewState.scrollX;
    const containerWidth = containerRef.current?.clientWidth ?? 800;

    const handleWheel = (event: WheelEvent<HTMLDivElement>) => {
        if (event.shiftKey || Math.abs(event.deltaX) > Math.abs(event.deltaY)) {
            scrollTimeline(event.deltaX || event.deltaY);
        } else {
            const currentY = timelineViewStore.value?.scrollY ?? 0;
            setScrollY(Math.max(0, currentY + event.deltaY));
        }
    };

    return (
        <div className="flex h-full flex-col overflow-hidden relative" ref={containerRef}>
            <ArrangementBar pixelsPerBeat={pixelsPerBeat} scrollX={scrollX} />
            <Button
                variant="ghost"
                size="icon-xs"
                onClick={toggleAutomationPanel}
                className="absolute top-[2px] right-2 z-50 text-muted-foreground hover:text-foreground"
                aria-label="Close automation panel"
            >
                <X className="size-3.5" />
            </Button>
            <div className="flex-1 overflow-y-auto bg-surface-base/50" onWheel={handleWheel}>
                {tracks.length === 0 ? (
                    <div className="flex h-full items-center justify-center p-6">
                        <DawBlockedState
                            eyebrow="Automation"
                            title="No tracks yet"
                            description="Add tracks in Arrange first, then return here to shape automation."
                            className="max-w-sm"
                            summary="This view mirrors the arrangement timeline and exposes automation per track."
                        />
                    </div>
                ) : (
                    tracks.map((track) => (
                        <TrackAutomationSection
                            key={track.id}
                            trackId={track.id}
                            trackName={track.name}
                            trackColor={track.color ?? 'var(--color-palette-steel)'}
                            automationMode={track.automationMode}
                            devices={track.devices.map((data) => ({ type: data.type, name: data.name }))}
                            pixelsPerBeat={pixelsPerBeat}
                            scrollX={scrollX}
                            containerWidth={containerWidth}
                        />
                    ))
                )}
            </div>
        </div>
    );
};

/**
 * Context menu for automation lane — curve type selection and shape insertion.
 */
import { type ReactElement } from 'react';

import { createPortal } from 'react-dom';

import { DawMenuButton, DawMenuSectionLabel, DawMenuSeparator } from '#/components/daw/DawMenuParts';
import { cn } from '#/utils/Styles/cn';

import { type AutomationPoint, type AutomationCurveType } from '../../../models/AutomationViewTypes';
import { CURVE_OPTIONS, SHAPE_OPTIONS } from '../../helpers/automationLaneConstants';

type AutomationShapeType = 'sine' | 'triangle' | 'sawtooth-up' | 'sawtooth-down' | 'square' | 'random';

type AutomationContextMenuProps = {
    x: number;
    y: number;
    beat: number;
    section: 'curve' | 'shape' | null;
    points: AutomationPoint[];
    onCurveSelect: (curve: AutomationCurveType) => void;
    onShapeInsert: (shape: AutomationShapeType) => void;
    onClose: () => void;
};

export const AutomationContextMenu = ({
    x,
    y,
    beat,
    section,
    points,
    onCurveSelect,
    onShapeInsert,
    onClose,
}: AutomationContextMenuProps): ReactElement =>
    createPortal(
        <>
            <div className="fixed inset-0 z-50" onClick={onClose} />
            <div
                className="daw-floating-surface fixed z-50 min-w-[160px] rounded-md py-1"
                style={{
                    left: Math.min(x, window.innerWidth - 200),
                    ...(y > window.innerHeight - 300 ? { bottom: window.innerHeight - y } : { top: y }),
                }}
            >
                {section !== 'shape' ? (
                    <>
                        <DawMenuSectionLabel className="px-2">Curve Type</DawMenuSectionLabel>
                        {CURVE_OPTIONS.map((opt) => (
                            <DawMenuButton
                                key={opt.value}
                                className={cn(
                                    'justify-start px-3 text-foreground hover:bg-accent/50 hover:text-foreground',
                                    points.find((param) => Math.abs(param.beat - beat) < 0.05)?.curve === opt.value &&
                                        'text-primary font-medium'
                                )}
                                onClick={() => onCurveSelect(opt.value)}
                            >
                                {opt.label}
                            </DawMenuButton>
                        ))}
                        <DawMenuSeparator />
                    </>
                ) : null}
                <DawMenuSectionLabel className="px-2">Insert Shape</DawMenuSectionLabel>
                {SHAPE_OPTIONS.map((opt) => (
                    <DawMenuButton
                        key={opt.value}
                        className="justify-start px-3 text-foreground hover:bg-accent/50 hover:text-foreground"
                        onClick={() => onShapeInsert(opt.value)}
                    >
                        {opt.label}
                    </DawMenuButton>
                ))}
            </div>
        </>,
        document.body
    );

import { type ReactElement, useState } from 'react';

import { Plus } from 'lucide-react';

import { DawEyebrowLabel } from '#/components/daw/DawEyebrowLabel';
import { cn } from '#/utils/Styles/cn';

import { type AutomationMode } from '../../../models/TrackViewTypes';
import { AUTOMATION_MODE_CONFIG } from '../../helpers/automationViewHelpers';

export const AUTOMATION_MODE_OPTIONS: { value: AutomationMode; label: string }[] = [
    { value: 'read', label: 'Read' },
    { value: 'touch', label: 'Touch' },
    { value: 'latch', label: 'Latch' },
    { value: 'write', label: 'Write' },
    { value: 'off', label: 'Off' },
];

type AutomationParamOption = {
    id: string;
    name: string;
};

type AutomationModeControlProps = {
    automationMode: AutomationMode;
    laneCount: number;
    onModeChange: (mode: AutomationMode) => void;
    align?: 'left' | 'right';
    className?: string;
};

export const AutomationModeControl = ({
    automationMode,
    laneCount,
    onModeChange,
    align = 'left',
    className,
}: AutomationModeControlProps): ReactElement => {
    const [open, setOpen] = useState(false);
    const modeConfig = AUTOMATION_MODE_CONFIG[automationMode];
    const menuPositionClassName = align === 'right' ? 'right-0' : 'left-2';

    return (
        <div className={cn('relative flex items-center gap-1.5', className)}>
            <DawEyebrowLabel>Mode</DawEyebrowLabel>
            <button
                type="button"
                className={cn(
                    'rounded px-1.5 py-0.5 text-[9px] font-bold tracking-wider transition-colors',
                    automationMode === 'write' ? 'animate-pulse' : ''
                )}
                style={{
                    backgroundColor: `${modeConfig.color}20`,
                    color: modeConfig.textColor,
                    border: `1px solid ${modeConfig.color}40`,
                }}
                onClick={(event) => {
                    event.stopPropagation();
                    setOpen(!open);
                }}
                aria-label={`Automation mode: ${automationMode}`}
            >
                {modeConfig.label}
            </button>

            {open ? (
                <>
                    <div
                        className="fixed inset-0 z-40"
                        onClick={(event) => {
                            event.stopPropagation();
                            setOpen(false);
                        }}
                    />
                    <div
                        className={cn(
                            'daw-floating-surface absolute top-full z-50 mt-1 min-w-[100px] rounded-md py-1',
                            menuPositionClassName
                        )}
                    >
                        {AUTOMATION_MODE_OPTIONS.map((option) => {
                            const config = AUTOMATION_MODE_CONFIG[option.value];
                            return (
                                <button
                                    type="button"
                                    key={option.value}
                                    className={cn(
                                        'flex w-full items-center gap-2 px-3 py-1.5 text-left text-xs transition-colors hover:bg-accent/50',
                                        automationMode === option.value ? 'font-medium' : ''
                                    )}
                                    onClick={(event) => {
                                        event.stopPropagation();
                                        onModeChange(option.value);
                                        setOpen(false);
                                    }}
                                >
                                    <span className="size-2 rounded-full" style={{ backgroundColor: config.color }} />
                                    <span
                                        style={{
                                            color: automationMode === option.value ? config.textColor : undefined,
                                        }}
                                    >
                                        {option.label}
                                    </span>
                                </button>
                            );
                        })}
                    </div>
                </>
            ) : null}

            <span className="ml-auto text-[9px] text-muted-foreground">
                {laneCount} lane{laneCount !== 1 ? 's' : ''}
            </span>
        </div>
    );
};

type AutomationAddLaneControlProps = {
    params: AutomationParamOption[];
    onAdd: (paramId: string, paramName: string) => void;
    showAvailableCount?: boolean;
    className?: string;
};

export const AutomationAddLaneControl = ({
    params,
    onAdd,
    showAvailableCount = false,
    className,
}: AutomationAddLaneControlProps): ReactElement => {
    const [open, setOpen] = useState(false);

    return (
        <div className={cn('relative', className)}>
            <button
                type="button"
                className="flex w-full items-center gap-1 text-[10px] text-muted-foreground transition-colors hover:text-foreground"
                onClick={() => setOpen((current) => !current)}
            >
                <Plus className="size-3" />
                Add Lane
                {showAvailableCount && params.length > 0 ? (
                    <span className="ml-auto text-[8px] text-muted-foreground/40">{params.length} available</span>
                ) : null}
            </button>

            {open ? (
                <>
                    <div className="fixed inset-0 z-40" onClick={() => setOpen(false)} />
                    <div className="daw-floating-surface absolute left-0 top-full z-50 mt-1 max-h-[300px] min-w-[200px] overflow-y-auto rounded-md py-1">
                        <DawEyebrowLabel className="block px-2 py-1 text-[8px]">Add parameter</DawEyebrowLabel>
                        <div className="max-h-[200px] overflow-y-auto">
                            {params.map((param) => (
                                <button
                                    type="button"
                                    key={param.id}
                                    className="flex w-full items-center gap-1.5 px-2.5 py-1.5 text-left text-[10px] text-foreground transition-colors hover:bg-accent/50"
                                    onClick={() => {
                                        onAdd(param.id, param.name);
                                        setOpen(false);
                                    }}
                                >
                                    <Plus className="size-2.5 text-muted-foreground/50" />
                                    {param.name}
                                </button>
                            ))}
                            {params.length === 0 ? (
                                <div className="px-2.5 py-2 text-[10px] italic text-muted-foreground/50">
                                    All parameters have lanes
                                </div>
                            ) : null}
                        </div>
                    </div>
                </>
            ) : null}
        </div>
    );
};

import { type ReactElement, type MouseEvent, type WheelEvent, type KeyboardEvent, useState, useRef } from 'react';

import { useStore } from '#/infra/store/useStore';
import { interpolateAutomationValue, getAutomationRegions } from '#/modules/Arrangement/useCases';
import {
    addAutomationPoint,
    removeAutomationPoint,
    toggleAutomationVisibility,
    insertAutomationShape,
    deleteSelectedPoints,
    getSelectionBounds,
    adjustYZoom,
    zoomToUsedRange,
    toggleVirginTerritory,
} from '#/modules/Automation/useCases';
import { pushUndoEntry } from '#/modules/Command/useCases';
import { transportStore } from '#/modules/Transport/stores';
import { defaultTransportState } from '#/modules/Transport/useCases';
import { cn } from '#/utils/Styles/cn';

import { type AutomationLane, type AutomationCurveType } from '../../../models/AutomationViewTypes';
import { defaultWorkspaceState, type WorkspaceState } from '../../../models/WorkspaceState';
import { workspaceStore } from '../../../stores/workspaceStore';
import {
    onDrawMouseDown,
    onRubberBandStart,
    onTensionMouseDown,
    onPointMouseDown,
    applyCurveSelect,
} from '../../helpers/automationDrag';
import { formatParameterValue, curveLabel } from '../../helpers/automationLaneConstants';
import { LANE_HEIGHT, buildCurvePath } from '../../helpers/automationViewHelpers';

import { AutomationContextMenu } from './AutomationContextMenu';
import { AutomationLaneControls } from './AutomationLaneControls';
import { AutomationLaneHeader } from './AutomationLaneHeader';

type AutomationLaneRowProps = {
    lane: AutomationLane;
    trackColor: string;
    pixelsPerBeat: number;
    scrollX: number;
    containerWidth: number;
};

type AutomationShapeType = 'sine' | 'triangle' | 'sawtooth-up' | 'sawtooth-down' | 'square' | 'random';

type AutomationLaneTransportState = {
    playheadPosition: number;
};

export const AutomationLaneRow = ({
    lane,
    trackColor,
    pixelsPerBeat,
    scrollX,
    containerWidth,
}: AutomationLaneRowProps): ReactElement => {
    const svgRef = useRef<SVGSVGElement>(null);
    const [dragPointBeat, setDragPointBeat] = useState<number | null>(null);
    const [hoveredBeat, setHoveredBeat] = useState<number | null>(null);
    const [selectedPoints, setSelectedPoints] = useState<number[]>([]);
    const [rubberBand, setRubberBand] = useState<{ x1: number; y1: number; x2: number; y2: number } | null>(null);
    const [tensionDrag, setTensionDrag] = useState<{ beat: number; initialTension: number } | null>(null);
    const [contextMenu, setContextMenu] = useState<{
        x: number;
        y: number;
        beat: number;
        section: 'curve' | 'shape' | null;
    } | null>(null);

    const workspace = useStore<WorkspaceState>(workspaceStore, defaultWorkspaceState);

    const transport = useStore<AutomationLaneTransportState>(transportStore, defaultTransportState);

    const isDrawMode = workspace.activeTool === 'draw';
    const curveColor = lane.color ?? trackColor ?? '#a78bfa';
    const isDisabled = lane.enabled === false;
    const snapValue = workspace.snapValue ?? 1;

    const viewportStartBeat = scrollX / pixelsPerBeat;
    const viewportEndBeat = viewportStartBeat + containerWidth / pixelsPerBeat;

    // Per-lane Y-axis zoom support
    const vMin = lane.viewMinValue ?? lane.minValue;
    const vMax = lane.viewMaxValue ?? lane.maxValue;
    const vRange = vMax - vMin;
    const isYZoomed = lane.viewMinValue !== undefined || lane.viewMaxValue !== undefined;

    const beatToX = (beat: number): number => (beat - viewportStartBeat) * pixelsPerBeat;
    const valueToY = (value: number): number => {
        const normalized = vRange !== 0 ? (value - vMin) / vRange : 0;
        return LANE_HEIGHT - normalized * (LANE_HEIGHT - 8) - 4;
    };
    const xToBeat = (x: number): number => x / pixelsPerBeat + viewportStartBeat;
    const yToValue = (y: number): number => {
        const normalized = 1 - (y - 4) / (LANE_HEIGHT - 8);
        return vMin + Math.max(0, Math.min(1, normalized)) * vRange;
    };

    const getRect = (): DOMRect | undefined => svgRef.current?.getBoundingClientRect();
    const coords = { getRect, xToBeat, yToValue };

    // Virgin territory data
    const vtRegions = lane.virginTerritory ? getAutomationRegions(lane.points) : [];

    // Interpolated value at playhead
    const playheadBeat = transport.playheadPosition;
    let currentValue: number | null = null;
    if (lane.points.length > 0) {
        const before = lane.points.filter((param) => param.beat <= playheadBeat);
        const after = lane.points.filter((param) => param.beat > playheadBeat);
        if (before.length === 0) {
            currentValue = lane.points[0]!.value;
        } else if (after.length === 0) {
            currentValue = before[before.length - 1]!.value;
        } else {
            currentValue = interpolateAutomationValue(before[before.length - 1]!, after[0]!, playheadBeat);
        }
    }

    const visiblePoints = lane.points.filter(
        (param) => param.beat >= viewportStartBeat - 2 && param.beat <= viewportEndBeat + 2
    );
    const selectedSet = new Set(selectedPoints);

    // Build SVG paths — in VT mode, break into separate segments per region
    const pathSegments: { pathD: string; fillD: string }[] = [];

    if (lane.virginTerritory && vtRegions.length > 0) {
        for (const region of vtRegions) {
            const regionPoints = visiblePoints.filter(
                (param) => param.beat >= region.startBeat && param.beat <= region.endBeat
            );
            if (regionPoints.length === 0) {
                continue;
            }
            const regionIndexMap = new Map(lane.points.map((param, idx) => [param, idx]));
            let segPath = `M ${beatToX(regionPoints[0]!.beat)} ${valueToY(regionPoints[0]!.value)}`;
            for (let index = 0; index < regionPoints.length - 1; index++) {
                const allIdx = regionIndexMap.get(regionPoints[index]!) ?? -1;
                const prevPt = allIdx > 0 ? lane.points[allIdx - 1] : undefined;
                const nextPt = allIdx < lane.points.length - 1 ? lane.points[allIdx + 1] : undefined;
                segPath += ` ${buildCurvePath(regionPoints[index]!, regionPoints[index + 1]!, beatToX, valueToY, prevPt, nextPt)}`;
            }
            const segFill =
                regionPoints.length > 1
                    ? `${segPath} L ${beatToX(regionPoints[regionPoints.length - 1]!.beat)} ${LANE_HEIGHT} L ${beatToX(regionPoints[0]!.beat)} ${LANE_HEIGHT} Z`
                    : '';
            pathSegments.push({ pathD: segPath, fillD: segFill });
        }
    } else if (visiblePoints.length > 0) {
        const visIndexMap = new Map(lane.points.map((param, idx) => [param, idx]));
        let pathD = `M ${beatToX(visiblePoints[0]!.beat)} ${valueToY(visiblePoints[0]!.value)}`;
        for (let index = 0; index < visiblePoints.length - 1; index++) {
            const allIdx = visIndexMap.get(visiblePoints[index]!) ?? -1;
            const prevPt = allIdx > 0 ? lane.points[allIdx - 1] : undefined;
            const nextPt = allIdx < lane.points.length - 1 ? lane.points[allIdx + 1] : undefined;
            pathD += ` ${buildCurvePath(visiblePoints[index]!, visiblePoints[index + 1]!, beatToX, valueToY, prevPt, nextPt)}`;
        }
        const fillD = `${pathD} L ${beatToX(visiblePoints[visiblePoints.length - 1]!.beat)} ${LANE_HEIGHT} L ${beatToX(visiblePoints[0]!.beat)} ${LANE_HEIGHT} Z`;
        pathSegments.push({ pathD, fillD });
    }

    // Selection bounding box
    const selBounds = selectedPoints.length > 1 ? getSelectionBounds(lane.id, selectedPoints) : null;

    // ── SVG dispatcher ───────────────────────────────────────────────────────
    const handleSvgMouseDown = (event: MouseEvent<SVGSVGElement>) => {
        if (event.button !== 0) {
            return;
        }
        if (isDrawMode) {
            onDrawMouseDown(event, lane, snapValue, coords);
        } else {
            onRubberBandStart(event, lane, setRubberBand, setSelectedPoints, coords);
        }
    };

    const handleSvgContextMenu = (event: MouseEvent<SVGSVGElement>) => {
        if ((event.target as Element).closest('[data-auto-point]')) {
            return;
        }
        event.preventDefault();
        const rect = getRect();
        if (!rect) {
            return;
        }
        const beat = Math.max(0, xToBeat(event.clientX - rect.left));
        setContextMenu({ x: event.clientX, y: event.clientY, beat, section: 'shape' });
    };

    const handlePointContextMenu = (pointBeat: number, event: MouseEvent<SVGCircleElement>) => {
        event.preventDefault();
        event.stopPropagation();
        setContextMenu({ x: event.clientX, y: event.clientY, beat: pointBeat, section: null });
    };

    const handlePointDoubleClick = (pointBeat: number, event: MouseEvent<SVGCircleElement>) => {
        event.stopPropagation();
        const point = lane.points.find((param) => param.beat === pointBeat);
        if (!point) {
            return;
        }
        const savedPoint = { ...point };
        removeAutomationPoint(lane.id, pointBeat);
        pushUndoEntry(
            'Delete automation point',
            () => {
                addAutomationPoint(lane.id, savedPoint);
            },
            () => {
                removeAutomationPoint(lane.id, pointBeat);
            }
        );
        setSelectedPoints((prev) => prev.filter((b) => b !== pointBeat));
    };

    const handleCurveSelect = (curve: AutomationCurveType) => {
        if (!contextMenu) {
            return;
        }
        applyCurveSelect(lane.id, contextMenu.beat, curve);
        setContextMenu(null);
    };

    const handleShapeInsert = (shape: AutomationShapeType) => {
        if (!contextMenu) {
            return;
        }
        insertAutomationShape(lane.id, shape, contextMenu.beat, contextMenu.beat + 4);
        setContextMenu(null);
    };

    // ── Keyboard ─────────────────────────────────────────────────────────────
    const handleKeyDown = (event: KeyboardEvent) => {
        const isDelete = event.key === 'Delete' || event.key === 'Backspace';
        if (isDelete && selectedPoints.length > 0) {
            event.preventDefault();
            deleteSelectedPoints(lane.id, selectedPoints);
            setSelectedPoints([]);
        }
        if (event.key === 'a' && (event.metaKey || event.ctrlKey)) {
            event.preventDefault();
            setSelectedPoints(lane.points.map((param) => param.beat));
        }
        if (event.key === 'Escape') {
            setSelectedPoints([]);
        }
    };

    // ── Y-axis zoom ───────────────────────────────────────────────────────────
    const handleWheel = (event: WheelEvent<HTMLDivElement>) => {
        if (!event.altKey) {
            return;
        }
        event.preventDefault();
        event.stopPropagation();
        adjustYZoom(lane.id, event.deltaY > 0 ? -1 : 1);
    };

    const showZeroLine = vMin < 0 && vMax > 0;

    // Tension handle positions (midpoint of each segment)
    const tensionHandles: { cx: number; cy: number; beat: number; tension: number }[] = [];
    for (let index = 0; index < visiblePoints.length - 1; index++) {
        const p1 = visiblePoints[index]!;
        const p2 = visiblePoints[index + 1]!;
        if (p1.curve === 'step' || p1.curve === 'linear') {
            continue;
        }
        tensionHandles.push({
            cx: beatToX((p1.beat + p2.beat) / 2),
            cy: valueToY((p1.value + p2.value) / 2),
            beat: p1.beat,
            tension: p1.tension ?? 0,
        });
    }

    return (
        <div
            className={cn('relative border-b border-border/20 outline-none', isDisabled ? 'opacity-50' : '')}
            style={{ height: LANE_HEIGHT }}
            tabIndex={0}
            onKeyDown={handleKeyDown}
            onWheel={handleWheel}
        >
            <AutomationLaneHeader
                parameterName={lane.parameterName}
                parameterId={lane.parameterId}
                curveColor={curveColor}
                currentValue={currentValue}
                isDrawMode={isDrawMode}
                isVirginTerritory={Boolean(lane.virginTerritory)}
                isYZoomed={isYZoomed}
                viewMin={vMin}
                viewMax={vMax}
            />
            <AutomationLaneControls
                laneId={lane.id}
                isVirginTerritory={Boolean(lane.virginTerritory)}
                isVisible={lane.visible}
                selectedCount={selectedPoints.length}
                onToggleVirginTerritory={() => toggleVirginTerritory(lane.id)}
                onZoomToUsedRange={() => zoomToUsedRange(lane.id)}
                onToggleVisibility={() => toggleAutomationVisibility(lane.id)}
                onClose={() => toggleAutomationVisibility(lane.id)}
            />
            <svg
                ref={svgRef}
                className={cn('w-full h-full', isDrawMode ? 'cursor-cell' : 'cursor-crosshair')}
                onMouseDown={handleSvgMouseDown}
                onContextMenu={handleSvgContextMenu}
                style={{ width: containerWidth }}
            >
                {/* Transparent rect for event capture on empty SVG space */}
                <rect x={0} y={0} width={containerWidth} height={LANE_HEIGHT} fill="transparent" />

                {/* Grid lines */}
                {Array.from({ length: 5 }).map((_, index) => {
                    const y = (LANE_HEIGHT / 4) * index;
                    return (
                        <line
                            key={index}
                            x1={0}
                            y1={y}
                            x2={containerWidth}
                            y2={y}
                            stroke="rgba(255,255,255,0.04)"
                            strokeWidth={1}
                        />
                    );
                })}

                {/* Beat grid */}
                {Array.from({ length: Math.ceil(containerWidth / pixelsPerBeat) + 1 }).map((_, index) => {
                    const beat = Math.floor(viewportStartBeat) + index;
                    const x = beatToX(beat);
                    return (
                        <line
                            key={`beat-${beat}`}
                            x1={x}
                            y1={0}
                            x2={x}
                            y2={LANE_HEIGHT}
                            stroke={beat % 4 === 0 ? 'rgba(255,255,255,0.08)' : 'rgba(255,255,255,0.03)'}
                            strokeWidth={1}
                        />
                    );
                })}

                {showZeroLine ? (
                    <line
                        x1={0}
                        y1={valueToY(0)}
                        x2={containerWidth}
                        y2={valueToY(0)}
                        stroke="rgba(255,255,255,0.15)"
                        strokeWidth={1}
                        strokeDasharray="4 3"
                    />
                ) : null}

                {/* Fill under curve segments */}
                {pathSegments.map((seg, index) =>
                    seg.fillD ? (
                        <path
                            key={`fill-${index}`}
                            d={seg.fillD}
                            fill={curveColor}
                            fillOpacity={isDisabled ? 0.04 : 0.1}
                        />
                    ) : null
                )}

                {/* Curve line segments */}
                {pathSegments.map((seg, index) => (
                    <path
                        key={`curve-${index}`}
                        d={seg.pathD}
                        fill="none"
                        stroke={curveColor}
                        strokeOpacity={isDisabled ? 0.3 : 0.8}
                        strokeWidth={2}
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeDasharray={isDisabled ? '4 4' : undefined}
                    />
                ))}

                {/* Automation objects (bounded containers) */}
                {(lane.objects ?? []).map((obj) => {
                    const objX = beatToX(obj.startBeat);
                    const objW = beatToX(obj.endBeat) - objX;
                    if (objX + objW < 0 || objX > containerWidth) {
                        return null;
                    }
                    return (
                        <g key={obj.id}>
                            <rect
                                x={objX}
                                y={2}
                                width={objW}
                                height={LANE_HEIGHT - 4}
                                rx={4}
                                fill={`${curveColor}08`}
                                stroke={curveColor}
                                strokeWidth={1}
                                strokeOpacity={0.4}
                                strokeDasharray={obj.loopLength ? '6 3' : undefined}
                            />
                            <text
                                x={objX + 4}
                                y={14}
                                className="text-[7px] fill-muted-foreground/50 pointer-events-none font-mono"
                            >
                                {obj.poolId ? '🔗 ' : ''}
                                {obj.name}
                            </text>
                        </g>
                    );
                })}

                {/* Tension handles */}
                {tensionHandles.map((th) => {
                    const isActive = tensionDrag?.beat === th.beat;
                    return (
                        <g key={`tension-${th.beat}`} data-tension-handle="true">
                            <circle
                                cx={th.cx}
                                cy={th.cy}
                                r={12}
                                fill="transparent"
                                className="cursor-ns-resize"
                                onMouseDown={(event) => onTensionMouseDown(th.beat, event, lane, setTensionDrag)}
                            />
                            <circle
                                cx={th.cx}
                                cy={th.cy}
                                r={isActive ? 5 : 3.5}
                                fill={isActive ? 'white' : 'rgba(255,255,255,0.3)'}
                                stroke={curveColor}
                                strokeWidth={1.5}
                                pointerEvents="none"
                                style={{ filter: isActive ? `drop-shadow(0 0 6px ${curveColor})` : undefined }}
                            />
                            {isActive ? (
                                <text
                                    x={th.cx + 10}
                                    y={th.cy + 4}
                                    className="text-[8px] fill-white font-mono"
                                    pointerEvents="none"
                                >
                                    {(th.tension >= 0 ? '+' : '') + th.tension.toFixed(2)}
                                </text>
                            ) : null}
                        </g>
                    );
                })}

                {/* Breakpoint nodes */}
                {visiblePoints.map((point, ptIdx) => {
                    const cx = beatToX(point.beat);
                    const cy = valueToY(point.value);
                    const isDragging = dragPointBeat === point.beat;
                    const isHovered = hoveredBeat === point.beat;
                    const isSelected = selectedSet.has(point.beat);
                    const nodeSize = (() => {
                        if (isDragging) {
                            return 6;
                        }
                        if (isHovered || isSelected) {
                            return 5;
                        }
                        return 4;
                    })();

                    return (
                        <g key={`pt-${String(ptIdx)}-${point.beat}`} data-auto-point="true">
                            <circle
                                cx={cx}
                                cy={cy}
                                r={10}
                                fill="transparent"
                                className="cursor-grab"
                                onMouseDown={(event) =>
                                    onPointMouseDown(
                                        point.beat,
                                        event,
                                        lane,
                                        setDragPointBeat,
                                        setSelectedPoints,
                                        coords
                                    )
                                }
                                onDoubleClick={(event) => handlePointDoubleClick(point.beat, event)}
                                onContextMenu={(event) => handlePointContextMenu(point.beat, event)}
                                onMouseEnter={() => setHoveredBeat(point.beat)}
                                onMouseLeave={() => setHoveredBeat(null)}
                            />
                            {isDragging || isHovered || isSelected ? (
                                <circle
                                    cx={cx}
                                    cy={cy}
                                    r={nodeSize + 3}
                                    fill={curveColor}
                                    fillOpacity={0.15}
                                    pointerEvents="none"
                                />
                            ) : null}
                            <circle
                                cx={cx}
                                cy={cy}
                                r={nodeSize}
                                fill={isDragging || isSelected ? 'white' : curveColor}
                                stroke={isSelected ? curveColor : 'white'}
                                strokeWidth={isDragging || isSelected ? 2 : 1.5}
                                pointerEvents="none"
                                style={{
                                    filter: (() => {
                                        if (isDragging) {
                                            return `drop-shadow(0 0 8px ${curveColor})`;
                                        }
                                        if (isHovered || isSelected) {
                                            return `drop-shadow(0 0 4px ${curveColor})`;
                                        }
                                        return `drop-shadow(0 0 2px ${curveColor})`;
                                    })(),
                                }}
                            />
                            {point.curve !== 'linear' && !isDragging ? (
                                <text
                                    x={cx + 8}
                                    y={cy - 8}
                                    className="text-[8px] fill-muted-foreground/60 pointer-events-none font-mono"
                                >
                                    {curveLabel(point.curve)}
                                </text>
                            ) : null}
                            {isHovered && !isDragging ? (
                                <g pointerEvents="none">
                                    <rect
                                        x={cx - 24}
                                        y={cy - 22}
                                        width={48}
                                        height={14}
                                        rx={3}
                                        fill="rgba(0,0,0,0.8)"
                                        stroke="rgba(255,255,255,0.2)"
                                        strokeWidth={0.5}
                                    />
                                    <text
                                        x={cx}
                                        y={cy - 12}
                                        textAnchor="middle"
                                        className="text-[8px] fill-white font-mono"
                                    >
                                        {formatParameterValue(point.value, lane.parameterId)}
                                    </text>
                                </g>
                            ) : null}
                        </g>
                    );
                })}

                {/* Rubber-band selection rectangle */}
                {rubberBand !== null && Math.abs(rubberBand.x2 - rubberBand.x1) > 3 ? (
                    <rect
                        x={Math.min(rubberBand.x1, rubberBand.x2)}
                        y={Math.min(rubberBand.y1, rubberBand.y2)}
                        width={Math.abs(rubberBand.x2 - rubberBand.x1)}
                        height={Math.abs(rubberBand.y2 - rubberBand.y1)}
                        fill={`${curveColor}15`}
                        stroke={curveColor}
                        strokeWidth={1}
                        strokeDasharray="3 2"
                        pointerEvents="none"
                    />
                ) : null}

                {/* Selection stretch handles */}
                {selBounds !== null && selectedPoints.length > 1 && rubberBand === null ? (
                    <g pointerEvents="none">
                        <rect
                            x={beatToX(selBounds.minBeat) - 2}
                            y={valueToY(selBounds.maxValue) - 2}
                            width={beatToX(selBounds.maxBeat) - beatToX(selBounds.minBeat) + 4}
                            height={valueToY(selBounds.minValue) - valueToY(selBounds.maxValue) + 4}
                            fill="none"
                            stroke={curveColor}
                            strokeWidth={1}
                            strokeDasharray="4 2"
                            strokeOpacity={0.5}
                        />
                        {[
                            { x: beatToX(selBounds.minBeat), y: valueToY(selBounds.maxValue) },
                            { x: beatToX(selBounds.maxBeat), y: valueToY(selBounds.maxValue) },
                            { x: beatToX(selBounds.minBeat), y: valueToY(selBounds.minValue) },
                            { x: beatToX(selBounds.maxBeat), y: valueToY(selBounds.minValue) },
                        ].map((h, index) => (
                            <rect
                                key={`handle-${index}`}
                                x={h.x - 3}
                                y={h.y - 3}
                                width={6}
                                height={6}
                                fill="white"
                                stroke={curveColor}
                                strokeWidth={1}
                            />
                        ))}
                    </g>
                ) : null}
            </svg>
            {contextMenu !== null ? (
                <AutomationContextMenu
                    x={contextMenu.x}
                    y={contextMenu.y}
                    beat={contextMenu.beat}
                    section={contextMenu.section}
                    points={lane.points}
                    onCurveSelect={handleCurveSelect}
                    onShapeInsert={handleShapeInsert}
                    onClose={() => setContextMenu(null)}
                />
            ) : null}
        </div>
    );
};

import { type ReactElement, useState } from 'react';

import { ChevronDown, ChevronRight } from 'lucide-react';

import { useStore } from '#/infra/store/useStore';
import { setAutomationMode } from '#/modules/Arrangement/useCases';
import { automationStore } from '#/modules/Automation/stores';
import { addAutomationLane, toggleLaneCollapsed } from '#/modules/Automation/useCases';
import { cn } from '#/utils/Styles/cn';

import { type AutomationLane } from '../../../models/AutomationViewTypes';
import { type AutomationMode } from '../../../models/TrackViewTypes';
import { getAutomatableParams } from '../../helpers/automationViewHelpers';

import { AutomationAddLaneControl, AutomationModeControl } from './AutomationControls';
import { AutomationLaneRow } from './AutomationLaneRow';

type TrackAutomationSectionProps = {
    trackId: string;
    trackName: string;
    trackColor: string;
    automationMode: AutomationMode;
    devices: { type: string; name: string }[];
    pixelsPerBeat: number;
    scrollX: number;
    containerWidth: number;
};

type TrackAutomationState = {
    lanes: AutomationLane[];
};

const SPARKLINE_HEIGHT = 24;

/** Render a mini sparkline SVG for collapsed automation lanes. */
const LaneSparkline = ({
    lane,
    trackColor,
    width,
}: {
    lane: AutomationLane;
    trackColor: string;
    width: number;
}): ReactElement => {
    const color = lane.color ?? trackColor;
    const { points, minValue, maxValue } = lane;
    if (points.length < 2) {
        return <div style={{ height: SPARKLINE_HEIGHT }} className="bg-surface-base/20" />;
    }

    const range = maxValue - minValue;
    const pathData = points
        .map((param, index) => {
            const x = (param.beat / (points[points.length - 1]!.beat || 1)) * width;
            const y = SPARKLINE_HEIGHT - ((param.value - minValue) / (range || 1)) * (SPARKLINE_HEIGHT - 4) - 2;
            return `${index === 0 ? 'M' : 'L'} ${x} ${y}`;
        })
        .join(' ');

    return (
        <div
            style={{ height: SPARKLINE_HEIGHT }}
            className="relative bg-surface-base/20 cursor-pointer border-b border-border/10"
            onClick={() => toggleLaneCollapsed(lane.id)}
        >
            <div className="absolute top-0.5 left-1 flex items-center gap-1 z-10">
                <ChevronRight className="size-2.5 text-muted-foreground/50" />
                <span className="text-[8px] text-muted-foreground/60 truncate max-w-[80px]">{lane.parameterName}</span>
            </div>
            <svg width={width} height={SPARKLINE_HEIGHT} className="absolute inset-0">
                <path d={pathData} fill="none" stroke={color} strokeWidth={1} strokeOpacity={0.5} />
            </svg>
        </div>
    );
};

export const TrackAutomationSection = ({
    trackId,
    trackName,
    trackColor,
    automationMode,
    devices,
    pixelsPerBeat,
    scrollX,
    containerWidth,
}: TrackAutomationSectionProps): ReactElement => {
    const [isExpanded, setIsExpanded] = useState(true);

    const autoState = useStore<TrackAutomationState>(automationStore, { lanes: [] });

    const trackLanes = autoState.lanes.filter((length) => length.trackId === trackId && !length.clipId);
    const availableParams = getAutomatableParams(trackId, devices);
    const unusedParams = availableParams.filter((param) => !trackLanes.some((lane) => lane.parameterId === param.id));

    const handleAddLane = (paramId: string, paramName: string) => {
        addAutomationLane(trackId, paramId, paramName);
    };

    return (
        <div className="border-b border-border/30">
            <div
                className="flex items-center gap-2 px-2 h-8 bg-surface-raised/50 border-b border-border/20 cursor-pointer select-none"
                onClick={() => setIsExpanded(!isExpanded)}
            >
                <div className="size-2.5 rounded-sm" style={{ backgroundColor: trackColor }} />
                <ChevronDown
                    className={cn('size-3 text-muted-foreground transition-transform', !isExpanded && '-rotate-90')}
                />
                <span className="text-xs font-medium text-foreground truncate">{trackName}</span>

                {/* Automation mode badge */}
                <AutomationModeControl
                    automationMode={automationMode}
                    laneCount={trackLanes.length}
                    align="right"
                    className="ml-auto"
                    onModeChange={(mode) => setAutomationMode(trackId, mode)}
                />
            </div>

            {isExpanded ? (
                <div>
                    {trackLanes.map((lane) =>
                        lane.collapsed ? (
                            <LaneSparkline key={lane.id} lane={lane} trackColor={trackColor} width={containerWidth} />
                        ) : (
                            <AutomationLaneRow
                                key={lane.id}
                                lane={lane}
                                trackColor={trackColor}
                                pixelsPerBeat={pixelsPerBeat}
                                scrollX={scrollX}
                                containerWidth={containerWidth}
                            />
                        )
                    )}

                    <div className="bg-surface-base/30 px-2 py-1">
                        <AutomationAddLaneControl params={unusedParams} onAdd={handleAddLane} />
                    </div>
                </div>
            ) : null}
        </div>
    );
};

