/**
 * PianoRoll context menu — right-click actions for note editing,
 * quantize, transpose, humanize, strum, AI, and groove operations.
 */
import { type ReactElement, useRef } from 'react';

import { DawContextMenuSurface } from '#/components/daw/DawContextMenuSurface';
import { DawMenuButton, DawMenuSectionLabel, DawMenuSeparator } from '#/components/daw/DawMenuParts';
import { logger } from '#/infra/logger/appLogger';
import { copySelectedNotes, pasteNotes } from '#/modules/Arrangement/useCases';
import { generateMidiAI, isTauri } from '#/modules/AudioEngine/useCases';
import { pushUndoEntry } from '#/modules/Command/useCases';
import {
    addMidiNote,
    removeMidiNote,
    moveMidiNote,
    setNoteVelocity,
    humanizeNotes,
    quantizeNotes,
    transposeNotes,
    getNotesForClip,
    strumNotes,
    restoreStrumOriginals,
    snapClipToScale,
    extractGrooveFromClip,
    applyGrooveToClip,
    restoreGrooveOriginals,
} from '#/modules/MIDI/useCases';
import { useContextMenuDismiss } from '#/utils/UI/useContextMenuDismiss';

import { type MidiNote } from '../../../models/MidiNoteViewTypes';
import { type PianoRollMenu } from '../../helpers/pianoRollConstants';

const pillBtnClass = 'rounded bg-accent/50 px-1.5 py-0.5 text-[9px] hover:bg-accent';

type PianoRollContextMenuProps = {
    menu: NonNullable<PianoRollMenu>;
    clipId: string;
    notes: MidiNote[];
    selectedNoteIds: Set<string>;
    onClose: () => void;
    onSelectAll: () => void;
    onClearSelection: () => void;
};

export const PianoRollContextMenu = ({
    menu,
    clipId,
    notes,
    selectedNoteIds,
    onClose,
    onSelectAll,
    onClearSelection,
}: PianoRollContextMenuProps): ReactElement => {
    const ref = useRef<HTMLDivElement>(null);
    useContextMenuDismiss(ref, onClose);

    const act = (fn: () => void) => () => {
        fn();
        onClose();
    };

    const handleAIGenerate = async (): Promise<void> => {
        try {
            const clipNotes = getNotesForClip(clipId);
            const seed = clipNotes
                .slice(-8)
                .map(
                    (node) =>
                        [Math.floor(node.pitch), node.velocity, node.startBeat, node.duration] as [
                            number,
                            number,
                            number,
                            number,
                        ]
                );
            const res = await generateMidiAI(seed, 16);
            if (res?.notes) {
                for (const note of res.notes) {
                    addMidiNote(clipId, note.pitch, note.start_beat, note.duration_beats, note.velocity);
                }
            }
        } catch {
            logger.warn('AI Generation requires native backend');
        }
    };

    return (
        <DawContextMenuSurface ref={ref} x={menu.x} y={menu.y} className="min-w-[170px]" role="menu">
            {/* Select/Clipboard */}
            <DawMenuButton role="menuitem" shortcut="⌘A" onClick={act(onSelectAll)}>
                Select All
            </DawMenuButton>
            <DawMenuSeparator className="border-border/50" />
            <DawMenuButton
                role="menuitem"
                shortcut="⌘C"
                disabled={selectedNoteIds.size === 0}
                onClick={act(() => copySelectedNotes(clipId, [...selectedNoteIds]))}
            >
                Copy
            </DawMenuButton>
            <DawMenuButton
                role="menuitem"
                shortcut="⌘X"
                disabled={selectedNoteIds.size === 0}
                onClick={act(() => {
                    const cutNotes = notes.filter((node) => selectedNoteIds.has(node.id)).map((node) => ({ ...node }));
                    copySelectedNotes(clipId, [...selectedNoteIds]);
                    for (const id of selectedNoteIds) {
                        removeMidiNote(clipId, id);
                    }
                    if (cutNotes.length > 0) {
                        pushUndoEntry(
                            `Cut ${cutNotes.length} note${cutNotes.length > 1 ? 's' : ''}`,
                            () => {
                                for (const node of cutNotes) {
                                    addMidiNote(clipId, node.pitch, node.startBeat, node.duration, node.velocity);
                                }
                            },
                            () => {
                                for (const node of cutNotes) {
                                    removeMidiNote(clipId, node.id);
                                }
                            }
                        );
                    }
                    onClearSelection();
                })}
            >
                Cut
            </DawMenuButton>
            <DawMenuButton role="menuitem" shortcut="⌘V" onClick={act(() => pasteNotes(clipId, menu.beat))}>
                Paste
            </DawMenuButton>
            {/* Quantize */}
            <DawMenuSeparator className="border-border/50" />
            <DawMenuSectionLabel className="text-[10px] font-normal normal-case tracking-normal">
                Quantize
            </DawMenuSectionLabel>
            <div className="flex gap-1 px-3 py-0.5">
                {([1, 0.5, 0.25, 0.125] as const).map((g) => (
                    <button
                        type="button"
                        key={g}
                        className={pillBtnClass}
                        onClick={act(() => {
                            const before = getNotesForClip(clipId).map((node) => ({ ...node }));
                            quantizeNotes(clipId, g);
                            const after = getNotesForClip(clipId).map((node) => ({ ...node }));
                            pushUndoEntry(
                                `Quantize notes (${{ 1: '1/1', 0.5: '1/2', 0.25: '1/4', 0.125: '1/8' }[g]})`,
                                () => {
                                    for (const node of before) {
                                        moveMidiNote(clipId, node.id, node.pitch, node.startBeat);
                                    }
                                },
                                () => {
                                    for (const node of after) {
                                        moveMidiNote(clipId, node.id, node.pitch, node.startBeat);
                                    }
                                }
                            );
                        })}
                    >
                        {{ 1: '1/1', 0.5: '1/2', 0.25: '1/4', 0.125: '1/8' }[g]}
                    </button>
                ))}
            </div>
            {/* Transpose */}
            <DawMenuSeparator className="border-border/50" />
            <DawMenuSectionLabel className="text-[10px] font-normal normal-case tracking-normal">
                Transpose
            </DawMenuSectionLabel>
            <div className="flex gap-1 px-3 py-0.5">
                {([-12, -1, 1, 12] as const).map((semi) => (
                    <button
                        type="button"
                        key={semi}
                        className={pillBtnClass}
                        onClick={act(() => {
                            transposeNotes(clipId, semi);
                            pushUndoEntry(
                                `Transpose ${semi > 0 ? '+' : ''}${semi} semitone${Math.abs(semi) !== 1 ? 's' : ''}`,
                                () => transposeNotes(clipId, -semi),
                                () => transposeNotes(clipId, semi)
                            );
                        })}
                    >
                        {{ '-12': '-Oct', '-1': '-1', '1': '+1', '12': '+Oct' }[semi]}
                    </button>
                ))}
            </div>
            {/* Scale */}
            <DawMenuSeparator className="border-border/50" />
            <DawMenuSectionLabel className="text-[10px] font-normal normal-case tracking-normal">
                Scale
            </DawMenuSectionLabel>
            <DawMenuButton
                role="menuitem"
                onClick={act(() => {
                    const before = getNotesForClip(clipId).map((node) => ({ ...node }));
                    snapClipToScale(clipId);
                    const after = getNotesForClip(clipId).map((node) => ({ ...node }));
                    pushUndoEntry(
                        'Snap notes to scale',
                        () => {
                            for (const node of before) {
                                moveMidiNote(clipId, node.id, node.pitch, node.startBeat);
                            }
                        },
                        () => {
                            for (const node of after) {
                                moveMidiNote(clipId, node.id, node.pitch, node.startBeat);
                            }
                        }
                    );
                })}
            >
                Snap to Scale
            </DawMenuButton>
            {/* Humanize */}
            <DawMenuSeparator className="border-border/50" />
            {(
                [
                    { amount: 0.02, label: 'subtle' },
                    { amount: 0.05, label: 'medium' },
                ] as const
            ).map(({ amount, label }) => (
                <DawMenuButton
                    key={label}
                    role="menuitem"
                    onClick={act(() => {
                        const before = getNotesForClip(clipId).map((node) => ({
                            id: node.id,
                            startBeat: node.startBeat,
                            velocity: node.velocity,
                        }));
                        humanizeNotes(clipId, amount);
                        const after = getNotesForClip(clipId).map((node) => ({
                            id: node.id,
                            startBeat: node.startBeat,
                            velocity: node.velocity,
                        }));
                        pushUndoEntry(
                            `Humanize (${label})`,
                            () => {
                                for (const node of before) {
                                    moveMidiNote(
                                        clipId,
                                        node.id,
                                        notes.find((output) => output.id === node.id)?.pitch ?? 60,
                                        node.startBeat
                                    );
                                    setNoteVelocity(clipId, node.id, node.velocity);
                                }
                            },
                            () => {
                                for (const node of after) {
                                    moveMidiNote(
                                        clipId,
                                        node.id,
                                        notes.find((output) => output.id === node.id)?.pitch ?? 60,
                                        node.startBeat
                                    );
                                    setNoteVelocity(clipId, node.id, node.velocity);
                                }
                            }
                        );
                    })}
                >
                    Humanize ({label})
                </DawMenuButton>
            ))}
            {/* Strum */}
            <DawMenuSeparator className="border-border/50" />
            <DawMenuSectionLabel className="text-[10px] font-normal normal-case tracking-normal">
                Strum
            </DawMenuSectionLabel>
            <div className="flex gap-1 px-3 py-0.5">
                {(['up', 'down'] as const).map((dir) => (
                    <button
                        type="button"
                        key={dir}
                        className={`${pillBtnClass} disabled:opacity-40`}
                        disabled={selectedNoteIds.size < 2}
                        onClick={act(() => {
                            const ids = [...selectedNoteIds];
                            const originals = strumNotes(clipId, ids, 0.04, dir);
                            if (originals) {
                                pushUndoEntry(
                                    `Strum ${dir}`,
                                    () => restoreStrumOriginals(clipId, originals),
                                    () => strumNotes(clipId, ids, 0.04, dir)
                                );
                            }
                        })}
                    >
                        {dir === 'up' ? '↑ Up' : '↓ Down'}
                    </button>
                ))}
            </div>
            {/* AI */}
            <DawMenuSeparator className="border-border/50" />
            <DawMenuButton
                role="menuitem"
                className="font-medium text-[var(--color-accent-lavender)]"
                trailingContent={
                    <span className="rounded border border-current px-1 text-[9px] opacity-60">
                        {isTauri() ? 'Desktop' : 'Web'}
                    </span>
                }
                onClick={act(handleAIGenerate)}
            >
                AI Auto-Complete
            </DawMenuButton>
            {/* Groove */}
            <DawMenuSeparator className="border-border/50" />
            <DawMenuSectionLabel className="text-[10px] font-normal normal-case tracking-normal">
                Groove
            </DawMenuSectionLabel>
            <DawMenuButton
                role="menuitem"
                onClick={act(() => {
                    const groove = extractGrooveFromClip(clipId);
                    if (groove) {
                        (window as unknown as Record<string, unknown>).__lastGrooveTemplate = groove;
                    }
                })}
            >
                Extract Groove
            </DawMenuButton>
            <DawMenuButton
                role="menuitem"
                disabled={!(window as unknown as Record<string, unknown>).__lastGrooveTemplate}
                onClick={act(() => {
                    const groove = (window as unknown as Record<string, unknown>).__lastGrooveTemplate;
                    if (groove) {
                        const originals = applyGrooveToClip(
                            clipId,
                            groove as Parameters<typeof applyGrooveToClip>[1],
                            0.5
                        );
                        if (originals) {
                            pushUndoEntry(
                                'Apply groove',
                                () => restoreGrooveOriginals(clipId, originals),
                                () => applyGrooveToClip(clipId, groove as Parameters<typeof applyGrooveToClip>[1], 0.5)
                            );
                        }
                    }
                })}
            >
                Apply Groove (50%)
            </DawMenuButton>
            {/* Delete */}
            <DawMenuSeparator className="border-border/50" />
            <DawMenuButton
                role="menuitem"
                tone="danger"
                shortcut="⌫"
                disabled={selectedNoteIds.size === 0}
                onClick={act(() => {
                    const deletedNotes = notes
                        .filter((node) => selectedNoteIds.has(node.id))
                        .map((node) => ({ ...node }));
                    for (const id of selectedNoteIds) {
                        removeMidiNote(clipId, id);
                    }
                    if (deletedNotes.length > 0) {
                        pushUndoEntry(
                            `Delete ${deletedNotes.length} note${deletedNotes.length > 1 ? 's' : ''}`,
                            () => {
                                for (const node of deletedNotes) {
                                    addMidiNote(clipId, node.pitch, node.startBeat, node.duration, node.velocity);
                                }
                            },
                            () => {
                                for (const node of deletedNotes) {
                                    removeMidiNote(clipId, node.id);
                                }
                            }
                        );
                    }
                    onClearSelection();
                })}
            >
                Delete Selected
            </DawMenuButton>
        </DawContextMenuSurface>
    );
};

/**
 * PianoRoll toolbar — snap, scale, fold, step input, ghost notes,
 * chord mode, paint mode, lasso mode, and zoom controls.
 */
import { type ReactElement } from 'react';

import { DawCompactSelect } from '#/components/daw/DawCompactSelect';
import { DawControlStrip } from '#/components/daw/DawControlStrip';
import { Button } from '#/components/ui/button';
import { Slider } from '#/components/ui/slider';
import { CHORD_TYPE_KEYS } from '#/modules/MIDI/useCases';
import { cn } from '#/utils/Styles/cn';

import { SCALES, SCALE_ROOT_LABELS } from '../../helpers/pianoRollConstants';

const ToolbarDivider = (): ReactElement => (
    <div
        className="w-px h-4 mx-1"
        style={{
            background:
                'linear-gradient(180deg, rgba(255,255,255,0.06) 0%, rgba(255,255,255,0.02) 50%, rgba(0,0,0,0.2) 100%)',
        }}
    />
);

type PianoRollChordType =
    | 'major'
    | 'minor'
    | 'dim'
    | 'aug'
    | 'sus2'
    | 'sus4'
    | '7'
    | 'maj7'
    | 'min7'
    | 'dim7'
    | 'aug7'
    | '6'
    | 'min6'
    | '9'
    | 'add9'
    | 'min9'
    | '7sus4';

type ClipOption = { id: string; name: string };

type PianoRollToolbarProps = {
    gridSnap: number;
    onGridSnapChange: (v: number) => void;
    scaleRoot: number;
    onScaleRootChange: (v: number) => void;
    scaleType: string;
    onScaleTypeChange: (v: string) => void;
    isFolded: boolean;
    onToggleFolded: () => void;
    constrainToScale: boolean;
    onToggleConstrainToScale: () => void;
    stepInput: boolean;
    onToggleStepInput: () => void;
    showGhostNotes: boolean;
    onToggleGhostNotes: () => void;
    chordMode: boolean;
    onToggleChordMode: () => void;
    chordType: PianoRollChordType;
    onChordTypeChange: (v: PianoRollChordType) => void;
    paintMode: boolean;
    onTogglePaintMode: () => void;
    lassoMode: boolean;
    onToggleLassoMode: () => void;
    notePreviewEnabled: boolean;
    onToggleNotePreview: () => void;
    zoom: number;
    onZoomChange: (v: number) => void;
    /** A9: when multiple clips are open, show a selector for which clip receives new notes */
    openedClips?: ClipOption[];
    focusedClipId?: string;
    onFocusedClipIdChange?: (id: string) => void;
    /** I4: Expression View toggle */
    showExpressionView?: boolean;
    onToggleExpressionView?: () => void;
    activeExpressionLane?: 'velocity' | 'pressure' | 'slide' | 'pitchBend';
    onActiveExpressionLaneChange?: (lane: 'velocity' | 'pressure' | 'slide' | 'pitchBend') => void;
};

export const PianoRollToolbar = ({
    gridSnap,
    onGridSnapChange,
    scaleRoot,
    onScaleRootChange,
    scaleType,
    onScaleTypeChange,
    isFolded,
    onToggleFolded,
    constrainToScale,
    onToggleConstrainToScale,
    stepInput,
    onToggleStepInput,
    showGhostNotes,
    onToggleGhostNotes,
    chordMode,
    onToggleChordMode,
    chordType,
    onChordTypeChange,
    paintMode,
    onTogglePaintMode,
    lassoMode,
    onToggleLassoMode,
    notePreviewEnabled,
    onToggleNotePreview,
    zoom,
    onZoomChange,
    openedClips,
    focusedClipId,
    onFocusedClipIdChange,
    showExpressionView,
    onToggleExpressionView,
    activeExpressionLane,
    onActiveExpressionLaneChange,
}: PianoRollToolbarProps): ReactElement => (
    <DawControlStrip>
        <span className="text-[10px] text-muted-foreground">Snap:</span>
        {[1, 0.5, 0.25, 0.125].map((value) => (
            <Button
                key={value}
                variant={gridSnap === value ? 'secondary' : 'ghost'}
                size="icon-xs"
                onClick={() => onGridSnapChange(value)}
                className="text-[9px] w-6 h-5"
            >
                {(() => {
                    if (value === 1) {
                        return '1';
                    }
                    if (value === 0.5) {
                        return '1/2';
                    }
                    if (value === 0.25) {
                        return '1/4';
                    }
                    return '1/8';
                })()}
            </Button>
        ))}

        <ToolbarDivider />

        <span className="text-[10px] text-muted-foreground">Scale:</span>
        <DawCompactSelect
            value={scaleRoot}
            onChange={(event) => onScaleRootChange(Number(event.target.value))}
            size="micro"
            aria-label="Scale root note"
        >
            {SCALE_ROOT_LABELS.map((label, index) => (
                <option key={label} value={index}>
                    {label}
                </option>
            ))}
        </DawCompactSelect>
        <DawCompactSelect
            value={scaleType}
            onChange={(event) => onScaleTypeChange(event.target.value)}
            size="micro"
            aria-label="Scale type"
        >
            {Object.keys(SCALES).map((key) => (
                <option key={key} value={key}>
                    {key}
                </option>
            ))}
        </DawCompactSelect>

        <Button
            variant={isFolded ? 'secondary' : 'ghost'}
            size="xs"
            onClick={onToggleFolded}
            className={cn(
                'text-[10px] px-2',
                isFolded && 'text-[var(--color-accent-cyan)] border-[var(--color-accent-cyan)]/30'
            )}
            aria-pressed={isFolded}
            aria-label="Toggle fold to scale"
        >
            Fold
        </Button>

        <Button
            variant={constrainToScale ? 'secondary' : 'ghost'}
            size="xs"
            onClick={onToggleConstrainToScale}
            className={cn(
                'text-[10px] px-2',
                constrainToScale && 'text-[var(--color-accent-cyan)] border-[var(--color-accent-cyan)]/30'
            )}
            aria-pressed={constrainToScale}
            aria-label="Constrain notes to scale"
        >
            Constrain
        </Button>

        <ToolbarDivider />

        <Button
            variant={stepInput ? 'secondary' : 'ghost'}
