import { type ReactElement } from 'react';

import { MechanicalSwitch } from '#/components/daw/MechanicalSwitch';
import { getBuiltinPlugins, bypassDevice } from '#/modules/Arrangement/useCases';

import { type DeviceParameterView as DeviceParameter } from '../../../models/PluginDescriptorViewTypes';
import { type Device } from '../../../models/TrackViewTypes';
import { InspectorDetailHeader } from '../../components/Inspector/InspectorDetailHeader';
import { MetaText } from '../../components/Inspector/MetaText';

import { resolveDeviceLayout } from './deviceLayoutRegistry';
import { GenericDeviceLayout } from './GenericDeviceLayout';

import './layouts';

type DeviceInspectorProps = {
    device: Device;
    trackId: string;
    onBack: () => void;
};

/**
 * Derive parameters from a device's parameterValues when no static descriptor exists.
 * This handles Faust instruments whose params vary per module.
 */
function deriveParamsFromValues(device: Device): DeviceParameter[] {
    const pv = device.parameterValues;
    if (!pv || Object.keys(pv).length === 0) {
        return [];
    }

    return Object.entries(pv).map(([id, value]) => {
        const numVal = typeof value === 'number' ? value : 0;
        // Heuristic ranges based on parameter name patterns
        let min = 0;
        let max: number;
        let unit = '';
        if (/gain|volume|level|mix|output|master/i.test(id)) {
            max = 1;
        } else if (/freq|cutoff|frequency/i.test(id)) {
            min = 20;
            max = 20000;
            unit = 'Hz';
        } else if (/attack|decay|release/i.test(id)) {
            min = 0.001;
            max = 5;
            unit = 's';
        } else if (/rate|speed/i.test(id)) {
            min = 0;
            max = 20;
            unit = 'Hz';
        } else if (/depth|amount/i.test(id)) {
            max = 100;
        } else if (/drawbar/i.test(id)) {
            max = 8;
        } else if (/resonance|q\b/i.test(id)) {
            min = 0.1;
            max = 20;
        } else {
            min = 0;
            max = Math.max(1, Math.abs(numVal) * 2 || 1);
        }

        return {
            id,
            deviceId: device.id,
            name: id.replaceAll('_', ' ').replaceAll(/\b\w/g, (context) => context.toUpperCase()),
            type: 'float' as const,
            value: numVal,
            defaultValue: numVal,
            minValue: min,
            maxValue: max,
            unit,
            automatable: true,
            hasAutomation: false,
        };
    });
}

export const DeviceInspector = ({ device, trackId, onBack }: DeviceInspectorProps): ReactElement => {
    const plugin = getBuiltinPlugins().find(
        (param) =>
            param.id === device.type ||
            param.id === `builtin-${device.type}` ||
            param.name.toLowerCase() === device.type?.toLowerCase() ||
            param.name === device.name
    );

    // Use static descriptor params, or derive from parameterValues for Faust/dynamic devices
    const parameters = plugin?.parameters ?? deriveParamsFromValues(device);

    const LayoutComponent = resolveDeviceLayout(device.type ?? '');

    return (
        <div className="space-y-4 p-3">
            <InspectorDetailHeader
                title={<h3 className="truncate text-xs font-medium text-foreground">{device.name}</h3>}
                onBack={onBack}
                backLabel="Back to track"
                actions={
                    <MechanicalSwitch
                        checked={!device.bypassed}
                        onChange={(context) => bypassDevice(device.id, !context)}
                        size="sm"
                    />
                }
            />
            {/* ── Registry-based layout ── */}
            {(() => {
                if (LayoutComponent) {
                    return <LayoutComponent device={device} trackId={trackId} parameters={parameters} />;
                }
                if (parameters.length > 0) {
                    return <GenericDeviceLayout device={device} trackId={trackId} parameters={parameters} />;
                }
                return (
                    <div className="px-1">
                        <MetaText>No parameters available for this device.</MetaText>
                    </div>
                );
            })()}
        </div>
    );
};

import { type ReactElement, type ChangeEvent } from 'react';

import { DawCompactSelect } from '#/components/daw/DawCompactSelect';
import { RotaryKnob } from '#/components/daw/RotaryKnob';
import { BipolarSlider } from '#/components/ui/bipolar-slider';
import { useStore } from '#/infra/store/useStore';
import { MidiLearnButton } from '#/modules/Arrangement/presentations/views';
import { setDeviceParameter } from '#/modules/Arrangement/useCases';
import { automationStore, modulationStore, modulationRuntimeStore } from '#/modules/Automation/stores';
import { addAutomationLane, removeAutomationLane } from '#/modules/Automation/useCases';
import { cn } from '#/utils/Styles/cn';

import { type DeviceParameterView as DeviceParameter } from '../../../models/PluginDescriptorViewTypes';
import { type Device } from '../../../models/TrackViewTypes';

type DeviceParameterControlProps = {
    param: DeviceParameter;
    device: Device;
    trackId: string;
};

type DeviceAutomationState = {
    lanes: Array<{
        id: string;
        trackId: string;
        parameterId: string;
    }>;
};

/**
 * Build an O(1) lookup keyed by `trackId|parameterId` so each
 * DeviceParameterControl instance can skip the full `lanes.find()` scan
 * (see audit §115.1). React Compiler memoizes this call on `lanes` identity,
 * so the lookup is rebuilt at most once per automation-store update.
 */
function buildLaneLookup(lanes: DeviceAutomationState['lanes']): Map<string, DeviceAutomationState['lanes'][number]> {
    const map = new Map<string, DeviceAutomationState['lanes'][number]>();
    for (const lane of lanes) {
        map.set(`${lane.trackId}|${lane.parameterId}`, lane);
    }
    return map;
}

/** Compute a sensible step from the parameter range and type. */
function deriveStep(param: DeviceParameter): number {
    if (param.type === 'int') {
        return 1;
    }
    const range = param.maxValue - param.minValue;
    // Aim for ~200 discrete positions across the full range
    const raw = range / 200;
    // Snap to a "nice" precision: find the order of magnitude and round
    if (raw >= 1) {
        return Math.max(1, Math.round(raw));
    }
    // For sub-1 steps, round to the nearest power-of-10 fraction
    const mag = 10 ** Math.floor(Math.log10(raw));
    return Math.max(0.001, Math.round(raw / mag) * mag);
}

/** Format display value with appropriate precision. */
function formatDisplayValue(value: number, param: DeviceParameter): string {
    if (param.type === 'int') {
        return String(Math.round(value));
    }
    const range = param.maxValue - param.minValue;
    // For large ranges (>10), show 1 decimal. For small ranges, show 2-3 decimals.
    let decimals: number;
    if (range >= 100) {
        decimals = 0;
    } else if (range >= 10) {
        decimals = 1;
    } else if (range >= 1) {
        decimals = 2;
    } else {
        decimals = 3;
    }
    return value.toFixed(decimals);
}

export const DeviceParameterControl = ({ param, device, trackId }: DeviceParameterControlProps): ReactElement => {
    const autoState = useStore<DeviceAutomationState>(automationStore, { lanes: [] });
    const modState = useStore(modulationStore, { modulators: [] });
    const modRtState = useStore(modulationRuntimeStore, { runtimeValues: {} });

    // Aggregated modulation amount for this parameter
    const modulation = (() => {
        let total = 0;
        for (const mod of modState.modulators) {
            if (!mod.enabled) {
                continue;
            }
            const val = modRtState.runtimeValues[mod.id] ?? 0;
            for (const mapping of mod.mappings) {
                if (
                    mapping.targetTrackId === trackId &&
                    mapping.targetDeviceId === device.id &&
                    mapping.targetParamId === param.id
                ) {
                    total += val * mapping.amount;
                }
            }
        }
        return Math.max(-1, Math.min(1, total));
    })();

    const laneLookup = buildLaneLookup(autoState.lanes);

    const activeLane = laneLookup.get(`${trackId}|${param.id}`);
    const hasAutomation = !!activeLane;

    const value = device.parameterValues[param.id] ?? param.value;
    const step = deriveStep(param);
    const fineStep = step / 10;
    const displayValue = formatDisplayValue(value, param);

    const handleKnobChange = (value1: number) => {
        setDeviceParameter(device.id, param.id, value1);
    };

    const handleChoiceChange = (event: ChangeEvent<HTMLSelectElement>) => {
        setDeviceParameter(device.id, param.id, Number(event.target.value));
    };

    const isChoice = param.type === 'choice' && param.choices && param.choices.length > 0;

    const isSlider = param.unit === 'dB';
    const isLog = param.scaling === 'log';

    const renderSliderOrKnob = () => {
        if (isChoice) {
            return (
                <DawCompactSelect
                    className="w-[80px] bg-surface px-1.5 focus-visible:ring-primary"
                    value={Math.round(value)}
                    onChange={handleChoiceChange}
                    aria-label={param.name}
                >
                    {param.choices!.map((label, index) => (
                        <option key={label} value={index}>
                            {label}
                        </option>
                    ))}
                </DawCompactSelect>
            );
        }

        const min = isLog ? 0 : param.minValue;
        const max = isLog ? 1 : param.maxValue;
        const mappedStep = isLog ? 0.001 : step;
        const mappedFineStep = isLog ? 0.0001 : fineStep;

        const toLinear = (logVal: number) => {
            const clampVal = Math.max(param.minValue || 0.001, Math.min(param.maxValue, logVal));
            return (
                Math.log(clampVal / (param.minValue || 0.001)) / Math.log(param.maxValue / (param.minValue || 0.001))
            );
        };
        const toLog = (linearVal: number) => {
            return (param.minValue || 0.001) * (param.maxValue / (param.minValue || 0.001)) ** linearVal;
        };

        const mappedValue = isLog ? toLinear(value) : value;
        const mappedDefaultValue = isLog
            ? toLinear(param.defaultValue ?? param.value)
            : (param.defaultValue ?? param.value);

        const onChange = (value1: number) => {
            handleKnobChange(isLog ? toLog(value1) : value1);
        };

        if (isSlider) {
            return (
                <BipolarSlider
                    value={mappedValue}
                    onValueChange={onChange}
                    min={min}
                    max={max}
                    step={mappedStep}
                    defaultValue={mappedDefaultValue}
                    formatValue={(value1) => `${formatDisplayValue(isLog ? toLog(value1) : value1, param)} dB`}
                    className="w-full"
                />
            );
        }

        return (
            <RotaryKnob
                value={mappedValue}
                onChange={onChange}
                min={min}
                max={max}
                step={mappedStep}
                fineStep={mappedFineStep}
                defaultValue={mappedDefaultValue}
                bipolar={!isLog && param.minValue < 0 && param.maxValue > 0}
                modulations={modulation !== 0 ? [{ amount: modulation, color: 'var(--color-accent-cyan)' }] : undefined}
                size={
                    param.name.toLowerCase().includes('mix') ||
                    param.name.toLowerCase().includes('dry/wet') ||
                    param.name.toLowerCase().includes('threshold') ||
                    param.name.toLowerCase().includes('time') ||
                    param.name.toLowerCase().includes('rate')
                        ? 'xl'
                        : 'lg'
                }
            />
        );
    };

    return (
        <div className={cn('flex w-full min-w-0', isSlider ? 'flex-col gap-2' : 'flex-row items-center gap-3')}>
            {isSlider ? (
                <div className="flex items-center justify-between w-full">
                    <label className="text-[10px] font-medium text-foreground truncate" title={param.name}>
                        {param.name}
                    </label>
                    <div className="flex items-center gap-1.5 mt-0.5">
                        <span className="text-[10px] font-mono text-muted-foreground shrink-0">
                            {displayValue}
                            {param.unit ? ` ${param.unit}` : ''}
                        </span>
                        <MidiLearnButton
                            targetType="deviceParam"
                            trackId={trackId}
                            deviceId={device.id}
                            paramId={param.id}
                        />
                        {param.automatable ? (
                            <button
                                type="button"
                                className={cn(
                                    'size-3 rounded-full border shrink-0 transition-colors cursor-pointer',
                                    hasAutomation
                                        ? 'border-[var(--color-accent-peach)] bg-[var(--color-accent-peach)]/20'
                                        : 'border-muted-foreground/30 hover:bg-muted'
                                )}
                                onClick={() => {
                                    if (activeLane) {
                                        removeAutomationLane(activeLane.id);
                                    } else {
                                        addAutomationLane(trackId, param.id, param.name);
                                    }
                                }}
                                aria-label={`Automate ${param.name}`}
                                title={hasAutomation ? 'Remove automation lane' : 'Add automation lane'}
                            />
                        ) : null}
                    </div>
                </div>
            ) : (
                <div className="flex flex-col flex-1 min-w-0 overflow-hidden justify-center gap-1.5">
                    <label className="text-[10px] font-medium text-foreground truncate w-full" title={param.name}>
                        {param.name}
                    </label>
                    {!isChoice ? (
                        <span className="text-[10px] font-mono text-muted-foreground">
                            {displayValue}
                            {param.unit ? ` ${param.unit}` : ''}
                        </span>
                    ) : null}
                    <div className="flex items-center gap-1.5 mt-0.5">
                        <MidiLearnButton
                            targetType="deviceParam"
                            trackId={trackId}
                            deviceId={device.id}
                            paramId={param.id}
                        />
                        {param.automatable ? (
                            <button
                                type="button"
                                className={cn(
                                    'size-3 rounded-full border shrink-0 transition-colors cursor-pointer',
                                    hasAutomation
                                        ? 'border-[var(--color-accent-peach)] bg-[var(--color-accent-peach)]/20'
                                        : 'border-muted-foreground/30 hover:bg-muted'
                                )}
                                onClick={() => {
                                    if (activeLane) {
                                        removeAutomationLane(activeLane.id);
                                    } else {
                                        addAutomationLane(trackId, param.id, param.name);
                                    }
                                }}
                                aria-label={`Automate ${param.name}`}
                                title={hasAutomation ? 'Remove automation lane' : 'Add automation lane'}
                            />
                        ) : null}
                    </div>
                </div>
            )}

            <div className={cn('flex items-center justify-center', isSlider ? 'w-full px-1' : 'shrink-0')}>
                {renderSliderOrKnob()}
            </div>
        </div>
    );
};

import { type ReactElement, useState } from 'react';

import { Snowflake, Zap, AlertCircle, RefreshCw } from 'lucide-react';

import { DawCompactInput } from '#/components/daw/DawCompactInput';
import { DawMeterBar } from '#/components/daw/DawMeterBar';
import { Button } from '#/components/ui/button';
import { Tooltip, TooltipTrigger, TooltipContent } from '#/components/ui/tooltip';
import {
    renameTrack,
    setTrackColor,
    freezeTrack,
    unfreezeTrack,
    cancelFreezeTrack,
} from '#/modules/Arrangement/useCases';
import { cn } from '#/utils/Styles/cn';
import { TRACK_COLOR_PRESETS } from '#/utils/UI/colorPresets';

import { type Track } from '../../../models/TrackViewTypes';
import { InsetPanel } from '../../components/Inspector/InsetPanel';
import { MetaText } from '../../components/Inspector/MetaText';

type TrackHeaderSectionProps = {
    track: Track;
};

export const TrackHeaderSection = ({ track }: TrackHeaderSectionProps): ReactElement | null => {
    const [editingName, setEditingName] = useState(false);
    const [nameValue, setNameValue] = useState(track.name);

    const isFreezing = track.freezeState.status === 'freezing';
    const isStale = track.freezeState.status === 'stale';

    if (track.kind === 'master') {
        return null; // Master track name and color are fixed; streamline by hiding editing block.
    }

    const commitName = (): void => {
        if (nameValue.trim() && nameValue !== track.name) {
            renameTrack(track.id, nameValue.trim());
        }
        setEditingName(false);
    };

    return (
        <div className="flex flex-col">
            <InsetPanel tone="framed" className="space-y-3">
                <div>
                    <MetaText className="mb-1 block">Name</MetaText>
                    {editingName ? (
                        <DawCompactInput
                            value={nameValue}
                            onChange={(event) => setNameValue(event.target.value)}
                            onBlur={commitName}
                            onKeyDown={(event) => {
                                if (event.key === 'Enter') {
                                    commitName();
                                }
                            }}
                            autoFocus
                        />
                    ) : (
                        <Button
                            variant="ghost"
                            size="xs"
                            className="w-full justify-start font-normal h-7 bg-surface-overlay border border-transparent hover:border-border/50"
                            onClick={() => {
                                setEditingName(true);
                                setNameValue(track.name);
                            }}
                        >
                            {track.name}
                        </Button>
                    )}
                </div>

                <div className="flex items-center gap-2 justify-between">
                    <div className="flex items-center gap-2">
                        <MetaText>Kind:</MetaText>
                        <span className="text-[10px] font-medium text-foreground capitalize">{track.kind}</span>
                    </div>

                    {(() => {
                        if (track.kind !== 'folder') {
                            return (
                                <div className="flex items-center gap-2">
                                    {(() => {
                                        if (isFreezing) {
                                            return (
                                                <div className="flex flex-col gap-1.5 min-w-32">
                                                    <div className="flex items-center justify-between">
                                                        <span className="text-[9px] font-bold text-primary animate-pulse uppercase tracking-wider">
                                                            Freezing...
                                                        </span>
                                                        <span className="text-[10px] text-muted-foreground tabular-nums">
                                                            {Math.round((track.freezeState.renderProgress ?? 0) * 100)}%
                                                        </span>
                                                    </div>
                                                    <DawMeterBar
                                                        value={(track.freezeState.renderProgress ?? 0) * 100}
                                                        size="sm"
                                                        fillClassName="bg-primary"
                                                    />
                                                    <Button
                                                        variant="ghost"
                                                        size="xs"
                                                        className="h-5 text-[9px] hover:bg-destructive/10 hover:text-destructive"
                                                        onClick={() => cancelFreezeTrack(track.id)}
                                                    >
                                                        Cancel
                                                    </Button>
                                                </div>
                                            );
                                        } else {
                                            return (
                                                <>
                                                    {isStale && (
                                                        <Tooltip>
                                                            <TooltipTrigger asChild>
                                                                <div className="flex items-center gap-1 px-1.5 py-0.5 rounded bg-state-warning/20 border border-state-warning/30 text-state-warning cursor-help">
                                                                    <AlertCircle className="size-3" />
                                                                    <span className="text-[10px] font-bold uppercase tracking-tight">
                                                                        Stale
                                                                    </span>
                                                                </div>
                                                            </TooltipTrigger>
                                                            <TooltipContent>
                                                                Content has changed since freeze. Update required.
                                                            </TooltipContent>
                                                        </Tooltip>
                                                    )}
                                                    <Button
                                                        variant={track.frozen || isStale ? 'secondary' : 'ghost'}
                                                        size="xs"
                                                        className={cn(
                                                            'h-6 gap-1.5 px-2',
                                                            isStale &&
                                                                'border-state-warning/40 text-state-warning hover:bg-state-warning/10'
                                                        )}
                                                        onClick={() => {
                                                            if (track.frozen || isStale) {
                                                                void unfreezeTrack(track.id);
                                                            } else {
                                                                void freezeTrack(track.id);
                                                            }
                                                        }}
                                                        aria-pressed={track.frozen || isStale}
                                                    >
                                                        {(() => {
                                                            if (isStale) {
                                                                return <RefreshCw className="size-3" />;
                                                            }
                                                            if (track.frozen) {
                                                                return <Zap className="size-3" />;
                                                            }
                                                            return <Snowflake className="size-3" />;
                                                        })()}
                                                        <span className="text-[10px] font-medium">
                                                            {(() => {
                                                                if (isStale) {
                                                                    return 'Update Freeze';
                                                                }
                                                                if (track.frozen) {
                                                                    return 'Unfreeze';
                                                                }
                                                                return 'Freeze';
                                                            })()}
                                                        </span>
                                                    </Button>
                                                </>
                                            );
                                        }
                                    })()}
                                </div>
                            );
                        } else {
                            return null;
                        }
                    })()}
                </div>

                <div className="space-y-1.5 pt-1">
                    <MetaText className="block">Color</MetaText>
                    <div className="flex flex-wrap gap-1">
                        {TRACK_COLOR_PRESETS.map((context) => (
                            <button
                                type="button"
                                key={context}
                                className="size-4 rounded border border-border transition-transform hover:scale-125"
                                style={{
                                    backgroundColor: context,
                                    outline: context === track.color ? '2px solid white' : 'none',
                                    outlineOffset: '1px',
                                }}
                                onClick={() => setTrackColor(track.id, context)}
                                aria-label={`Set color`}
                            />
                        ))}
                    </div>
                </div>
            </InsetPanel>
        </div>
    );
};

