import { type CSSProperties, type ReactElement, useState } from 'react';

import { X } from 'lucide-react';

import { DawBlockedState } from '#/components/daw/DawBlockedState';
import { DawHeaderBand } from '#/components/daw/DawHeaderBand';
import { DawPanelSurface } from '#/components/daw/DawPanelSurface';
import { Button } from '#/components/ui/button';
import { ScrollArea } from '#/components/ui/scroll-area';
import { useStore } from '#/infra/store/useStore';

import { defaultWorkspaceState } from '../../models/WorkspaceState';
import { workspaceStore } from '../../stores/workspaceStore';
import { clearClipSelection } from '../../useCases/togglePanel/panelToggles/clearClipSelection';
import { selectClipWithFocus } from '../../useCases/togglePanel/panelToggles/selectClipWithFocus';
import { toggleInspector } from '../../useCases/togglePanel/panelToggles/toggleInspector';
import { useTracks } from '../hooks/useTracks';

import { ClipInspector } from './Inspector/ClipInspector';
import { DeviceInspector } from './Inspector/DeviceInspector';
import { TrackInspector } from './Inspector/TrackInspector';

type InspectorPanelProps = {
    style?: CSSProperties;
};

export const InspectorPanel = ({ style }: InspectorPanelProps): ReactElement => {
    const { tracks, selectedTrackId } = useTracks();
    const masterTrack = tracks.find((time) => time.kind === 'master');

    const selectedTrack =
        (selectedTrackId ? tracks.find((time) => time.id === selectedTrackId) : null) ?? masterTrack ?? null;
    const wsSelectedClipId = useStore(workspaceStore, defaultWorkspaceState).selectedClipId;
    const [selectedDeviceId, setSelectedDeviceId] = useState<string | null>(null);

    const selectedClip = selectedTrack?.clips.find((context) => context.id === wsSelectedClipId) ?? null;
    const selectedDevice = selectedTrack?.devices.find((data) => data.id === selectedDeviceId) ?? null;

    const isDeviceView = !!selectedDevice;

    return (
        <DawPanelSurface
            as="aside"
            tone="tray"
            className="transition-[width,min-width] duration-200 ease-out"
            style={{
                ...style,
                width: isDeviceView
                    ? Math.max((style?.width as number) ?? 260, 320)
                    : ((style?.width as number) ?? 260),
                minWidth: isDeviceView ? 300 : 200,
            }}
            aria-label="Inspector panel"
        >
            <DawHeaderBand
                className="rounded-none px-3 py-2"
                title="Inspector"
                titleClassName="text-xs font-medium text-muted-foreground uppercase tracking-wider"
                actions={
                    <Button variant="ghost" size="icon-xs" onClick={toggleInspector} aria-label="Close inspector">
                        <X className="size-3.5" />
                    </Button>
                }
            />
            <ScrollArea className="flex-1 min-h-0">
                {(() => {
                    if (selectedDevice && selectedTrack) {
                        return (
                            <DeviceInspector
                                device={selectedDevice}
                                trackId={selectedTrack.id}
                                onBack={() => setSelectedDeviceId(null)}
                            />
                        );
                    } else {
                        if (selectedClip && selectedTrack) {
                            return (
                                <ClipInspector
                                    clip={selectedClip}
                                    trackId={selectedTrack.id}
                                    onBack={clearClipSelection}
                                />
                            );
                        } else {
                            if (selectedTrack) {
                                return (
                                    <TrackInspector
                                        track={selectedTrack}
                                        allTracks={tracks}
                                        onSelectClip={selectClipWithFocus}
                                        onSelectDevice={setSelectedDeviceId}
                                    />
                                );
                            } else {
                                if (masterTrack) {
                                    return (
                                        <TrackInspector
                                            track={masterTrack}
                                            allTracks={tracks}
                                            onSelectClip={selectClipWithFocus}
                                            onSelectDevice={setSelectedDeviceId}
                                        />
                                    );
                                } else {
                                    return (
                                        <div className="flex h-full items-center justify-center p-6">
                                            <DawBlockedState
                                                eyebrow="Inspector"
                                                className="max-w-64"
                                                title="No track selected"
                                                description="Pick a track, clip, or device to inspect its details."
                                                summary="The inspector follows the current selection and switches between track, clip, and device detail."
                                            />
                                        </div>
                                    );
                                }
                            }
                        }
                    }
                })()}
            </ScrollArea>
        </DawPanelSurface>
    );
};

/**
 * LUFS Meter component.
 * Displays momentary, short-term, and integrated loudness on a Canvas2D bar.
 */
import { type ReactElement, useRef, useEffect, useState } from 'react';

import { DawMeterFrame } from '#/components/daw/DawMeterFrame';
import { DawReadoutRow } from '#/components/daw/DawReadoutRow';
import {
    getMasterAnalyser,
    getAudioSampleRate,
    computeMomentaryLUFS,
    ShortTermLUFS,
    IntegratedLUFS,
} from '#/modules/AudioEngine/useCases';
import { resolveToken } from '#/utils/UI/resolveToken';

type LUFSMeterProps = {
    height?: number;
    width?: number;
    target?: number;
};

export const LUFSMeter = ({ height = 160, width = 48, target = -14 }: LUFSMeterProps): ReactElement => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const shortTermRef = useRef(new ShortTermLUFS());
    const integratedRef = useRef(new IntegratedLUFS());
    const [momentary, setMomentary] = useState(-70);
    const [shortTerm, setShortTerm] = useState(-70);
    const [integrated, setIntegrated] = useState(-70);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) {
            return undefined;
        }
        const ctx = canvas.getContext('2d');
        if (!ctx) {
            return undefined;
        }

        // HiDPI scaling
        const dpr = window.devicePixelRatio || 1;
        canvas.width = width * dpr;
        canvas.height = height * dpr;
        ctx.scale(dpr, dpr);

        // Resolve theme tokens once, outside the animation loop
        const paletteSky = resolveToken('--color-palette-sky', '#5a80a8');
        const meterClip = resolveToken('--color-meter-clip', '#FF3300');
        const meterHot = resolveToken('--color-meter-hot', '#CCCC00');
        const meterSafe = resolveToken('--color-meter-safe', '#00CC44');

        let rafId = 0;
        let lastStateUpdate = 0;
        const STATE_UPDATE_INTERVAL = 100; // ~10fps for React state
        // Reused across frames — reallocated only if frequencyBinCount changes.
        let analyserData: Float32Array<ArrayBuffer> | null = null;

        const draw = (): void => {
            const analyser = getMasterAnalyser();
            if (!analyserData || analyserData.length !== analyser.frequencyBinCount) {
                analyserData = new Float32Array(analyser.frequencyBinCount);
            }
            const data = analyserData;
            analyser.getFloatTimeDomainData(data);

            const mom = computeMomentaryLUFS(data, getAudioSampleRate());
            shortTermRef.current.push(mom);
            integratedRef.current.push(mom);

            const st = shortTermRef.current.value;
            const integ = integratedRef.current.value;

            // Throttle React state updates to ~10fps (only for text/aria readout)
            const now = performance.now();
            if (now - lastStateUpdate > STATE_UPDATE_INTERVAL) {
                setMomentary(mom);
                setShortTerm(st);
                setIntegrated(integ);
                lastStateUpdate = now;
            }

            // Draw
            ctx.clearRect(0, 0, width, height);

            const minLUFS = -60;
            const maxLUFS = 0;
            const range = maxLUFS - minLUFS;
            const lufsToY = (lufs: number): number =>
                height - ((Math.max(minLUFS, Math.min(maxLUFS, lufs)) - minLUFS) / range) * height;

            // Background — deep black
            ctx.fillStyle = '#050508';
            ctx.fillRect(0, 0, width, height);

            // Scale marks — subtle dashed lines, dim labels
            ctx.strokeStyle = 'rgba(255,255,255,0.04)';
            ctx.lineWidth = 0.5;
            ctx.setLineDash([2, 4]);
            ctx.fillStyle = 'rgba(255,255,255,0.18)';
            ctx.font = '8px monospace';
            ctx.textAlign = 'right';
            for (let db = 0; db >= minLUFS; db -= 6) {
                const y = lufsToY(db);
                ctx.beginPath();
                ctx.moveTo(0, y);
                ctx.lineTo(width, y);
                ctx.stroke();
                ctx.fillText(`${db}`, width - 2, y - 2);
            }
            ctx.setLineDash([]);

            // Target line — with subtle glow
            const targetY = lufsToY(target);
            ctx.strokeStyle = paletteSky;
            ctx.lineWidth = 1;
            ctx.shadowColor = paletteSky;
            ctx.shadowBlur = 4;
            ctx.setLineDash([3, 3]);
            ctx.beginPath();
            ctx.moveTo(0, targetY);
            ctx.lineTo(width, targetY);
            ctx.stroke();
            ctx.setLineDash([]);
            ctx.shadowBlur = 0;

            // Momentary bar
            const barW = 10;
            const momY = lufsToY(mom);
            ctx.fillStyle = (() => {
                if (mom > -3) {
                    return meterClip;
                }
                if (mom > -14) {
                    return meterHot;
                }
                return meterSafe;
            })();
            ctx.fillRect(2, momY, barW, height - momY);

            // Short-term bar
            const stY = lufsToY(st);
            ctx.fillStyle = (() => {
                if (st > -3) {
                    return `${meterClip}99`;
                }
                if (st > -14) {
                    return `${meterHot}99`;
                }
                return `${meterSafe}99`;
            })();
            ctx.fillRect(14, stY, barW, height - stY);

            // Integrated bar
            const integY = lufsToY(integ);
            ctx.fillStyle = paletteSky;
            ctx.fillRect(26, integY, barW, height - integY);

            // Segmented LED look on all bars
            ctx.fillStyle = '#050508';
            for (let sy = 0; sy < height; sy += 4) {
                ctx.fillRect(2, sy, barW, 1);
                ctx.fillRect(14, sy, barW, 1);
                ctx.fillRect(26, sy, barW, 1);
            }

            // Labels — dim and refined
            ctx.fillStyle = 'rgba(255,255,255,0.25)';
            ctx.font = '7px sans-serif';
            ctx.textAlign = 'center';
            ctx.fillText('M', 7, height - 2);
            ctx.fillText('S', 19, height - 2);
            ctx.fillText('I', 31, height - 2);

            rafId = requestAnimationFrame(draw);
        };

        draw();
        return () => cancelAnimationFrame(rafId);
    }, [height, width, target]);

    return (
        <div className="flex flex-col items-center gap-1">
            <DawMeterFrame overlay="vertical">
                <canvas
                    ref={canvasRef}
                    width={width}
                    height={height}
                    className="block"
                    aria-label={`LUFS: Momentary ${momentary > -70 ? momentary.toFixed(1) : '-∞'}, Short-term ${shortTerm > -70 ? shortTerm.toFixed(1) : '-∞'}, Integrated ${integrated > -70 ? integrated.toFixed(1) : '-∞'}`}
                />
            </DawMeterFrame>
            <DawReadoutRow
                className="w-full gap-1"
                label="I"
                labelClassName="text-[9px] font-medium uppercase tracking-wider text-muted-foreground/70"
                value={`${integrated > -70 ? integrated.toFixed(1) : '-∞'} LUFS`}
            />
        </div>
    );
};

import { type ReactElement, useEffect, useRef } from 'react';

import { DawMeterFrame } from '#/components/daw/DawMeterFrame';
import { getTrackPeakLevel, getMasterPeakLevel } from '#/modules/AudioEngine/useCases';
import { animationScheduler } from '#/utils/DOM/AnimationScheduler';
import { cn } from '#/utils/Styles/cn';
import { resolveToken } from '#/utils/UI/resolveToken';

type LevelMeterProps = {
    trackId: string | null;
    height?: string;
    width?: string;
};

const DB_MARKS = [0, -6, -12, -24, -48] as const;
const MIN_DB = -60;
const RMS_BUFFER_SIZE = 30;
const PEAK_HOLD_DURATION_MS = 1500;
const PEAK_HOLD_FALL_RATE = 0.02;

const linearToDb = (linear: number): number => {
    if (linear <= 0) {
        return MIN_DB;
    }
    return Math.max(MIN_DB, 20 * Math.log10(linear));
};

const dbToPercent = (db: number): number => Math.max(0, Math.min(100, ((db - MIN_DB) / (0 - MIN_DB)) * 100));

export const LevelMeter = ({ trackId, height = 'h-full', width = 'w-2' }: LevelMeterProps): ReactElement => {
    const id = crypto.randomUUID();
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);
    // §160.x — ring buffer for RMS history avoids Array.shift() on every
    // frame. Fixed-size Float32Array + head index + fill counter gives
    // O(1) per push and zero allocation on the hot path.
    const rmsBufferRef = useRef<Float32Array>(new Float32Array(RMS_BUFFER_SIZE));
    const rmsHeadRef = useRef(0);
    const rmsFilledRef = useRef(0);
    const peakHoldRef = useRef(0);
    const peakHoldTimeRef = useRef(0);

    useEffect(() => {
        const canvas = canvasRef.current;
        const container = containerRef.current;
        if (!canvas || !container) {
            return () => {};
        }

        const ctx = canvas.getContext('2d');
        if (!ctx) {
            return () => {};
        }

        let w = container.clientWidth;
        let h = container.clientHeight;

        const safe = resolveToken('--color-meter-safe', '#00CC44');
        const hot = resolveToken('--color-meter-hot', '#CCCC00');
        const clip = resolveToken('--color-meter-clip', '#FF3300');

        // §184.x — rebuild the meter gradient only when dimensions change,
        // not on every rAF tick. The stops are derived from fixed dB
        // thresholds and a fixed color palette.
        let meterGradient: CanvasGradient | null = null;
        const rebuildGradient = (): void => {
            meterGradient = ctx.createLinearGradient(0, h, 0, 0);
            meterGradient.addColorStop(0, safe);
            meterGradient.addColorStop(Math.min(1, dbToPercent(-12) / 100), safe);
            meterGradient.addColorStop(Math.min(1, dbToPercent(-12) / 100 + 0.001), hot);
            meterGradient.addColorStop(Math.min(1, dbToPercent(-3) / 100), hot);
            meterGradient.addColorStop(Math.min(1, dbToPercent(-3) / 100 + 0.001), clip);
            meterGradient.addColorStop(1, clip);
        };
        rebuildGradient();

        const resizeObserver = new ResizeObserver((entries) => {
            for (const entry of entries) {
                w = entry.contentRect.width;
                h = entry.contentRect.height;
                const dpr = window.devicePixelRatio || 1;
                canvas.width = w * dpr;
                canvas.height = h * dpr;
                ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
                rebuildGradient();
            }
        });
        resizeObserver.observe(container);

        const getMeterColor = (db: number): string => {
            if (db > -3) {
                return clip;
            }
            if (db > -12) {
                return hot;
            }
            return safe;
        };

        rmsBufferRef.current.fill(0);
        rmsHeadRef.current = 0;
        rmsFilledRef.current = 0;
        peakHoldRef.current = 0;
        peakHoldTimeRef.current = 0;

        const tick = () => {
            const now = performance.now();
            const rawPeak = trackId ? getTrackPeakLevel(trackId) : getMasterPeakLevel();

            const buf = rmsBufferRef.current;
            buf[rmsHeadRef.current] = rawPeak * rawPeak;
            rmsHeadRef.current = (rmsHeadRef.current + 1) % RMS_BUFFER_SIZE;
            if (rmsFilledRef.current < RMS_BUFFER_SIZE) {
                rmsFilledRef.current++;
            }

            let sumSquares = 0;
            const filled = rmsFilledRef.current;
            for (let index = 0; index < filled; index++) {
                sumSquares += buf[index]!;
            }
            const rawRms = filled > 0 ? Math.sqrt(sumSquares / filled) : 0;

            if (rawPeak >= peakHoldRef.current) {
                peakHoldRef.current = rawPeak;
                peakHoldTimeRef.current = now;
            } else if (now - peakHoldTimeRef.current > PEAK_HOLD_DURATION_MS) {
                peakHoldRef.current = Math.max(0, peakHoldRef.current - PEAK_HOLD_FALL_RATE);
            }

            const holdDb = linearToDb(peakHoldRef.current);
            const peakPct = dbToPercent(linearToDb(rawPeak));
            const rmsPct = dbToPercent(linearToDb(rawRms));
            const holdPct = dbToPercent(holdDb);

            ctx.clearRect(0, 0, w, h);

            if (h > 0 && w > 0) {
                // Deep black background
                ctx.fillStyle = '#050508';
                ctx.fillRect(0, 0, w, h);

                // §184.x — use cached gradient (rebuilt only on resize).
                // RMS — dimmer background fill
                const rmsY = h - (h * rmsPct) / 100;
                ctx.globalAlpha = 0.35;
                ctx.fillStyle = meterGradient!;
                ctx.fillRect(0, rmsY, w, h - rmsY);

                // Peak — bright fill
                const peakY = h - (h * peakPct) / 100;
                ctx.globalAlpha = 1.0;
                ctx.fillRect(0, peakY, w, h - peakY);

                // Segmented LED look — dark gaps every 2px
                ctx.globalAlpha = 1.0;
                ctx.fillStyle = '#050508';
                for (let sy = 0; sy < h; sy += 4) {
                    ctx.fillRect(0, sy, w, 1);
                }

                // Peak hold indicator with glow
                if (holdPct > 0) {
                    const holdY = Math.max(0, h - (h * holdPct) / 100 - 1.5);
                    ctx.fillStyle = getMeterColor(holdDb);
                    ctx.shadowColor = getMeterColor(holdDb);
                    ctx.shadowBlur = 6;
                    ctx.fillRect(0, holdY, w, 1.5);
                    ctx.shadowBlur = 0;
                }
            }
        };

        animationScheduler.register(`meter-${id}`, tick);

        return () => {
            animationScheduler.unregister(`meter-${id}`);
            resizeObserver.disconnect();
        };
    }, [trackId]);

    return (
        <div
            className={cn('flex gap-px', height)}
            role="meter"
            aria-label="Level meter"
            aria-valuemin={MIN_DB}
            aria-valuemax={0}
        >
            <div className="flex flex-col justify-between py-0.5 pr-px shrink-0">
                {DB_MARKS.map((db) => (
                    <span
                        key={db}
                        className="text-[6px] leading-none text-muted-foreground/50 text-right tabular-nums block"
                        style={{ marginTop: db === 0 ? 0 : undefined }}
                    >
                        {db}
                    </span>
                ))}
            </div>

            <DawMeterFrame overlay="vertical" ref={containerRef} className={cn('rounded-sm', width)}>
                <canvas ref={canvasRef} className="absolute inset-0 block w-full h-full" />
            </DawMeterFrame>
        </div>
    );
};

/**
 * Phase Correlation Meter component.
 * Displays mono compatibility as a horizontal bar from -1 to +1.
 * Canvas2D rendering with smoothed correlation value.
 */
import { type ReactElement, useRef, useEffect } from 'react';

import { DawMeterFrame } from '#/components/daw/DawMeterFrame';
import { getMasterAnalyser, PhaseCorrelationMeter as PhaseMeter } from '#/modules/AudioEngine/useCases';
import { resolveToken } from '#/utils/UI/resolveToken';

type PhaseCorrelationDisplayProps = {
    width?: number;
    height?: number;
};

export const PhaseCorrelationDisplay = ({ width = 160, height = 24 }: PhaseCorrelationDisplayProps): ReactElement => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const meterRef = useRef(new PhaseMeter());

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) {
            return undefined;
        }
        const ctx = canvas.getContext('2d');
        if (!ctx) {
            return undefined;
        }

        let rafId = 0;
        // Reused across frames — reallocated only if frequencyBinCount changes.
        let data: Float32Array<ArrayBuffer> | null = null;
        let left: Float32Array<ArrayBuffer> | null = null;
        let right: Float32Array<ArrayBuffer> | null = null;

        // §194.1 — resolve CSS tokens once per mount rather than on every
        // rAF tick. Each resolveToken() call invokes getComputedStyle on
        // the document root, which triggers a style-read and is expensive
        // to run at 60 Hz. Tokens don't change mid-animation.
        const safeColor = resolveToken('--color-meter-safe', '#00CC44');
        const hotColor = resolveToken('--color-meter-hot', '#CCCC00');
        const clipColor = resolveToken('--color-meter-clip', '#FF3300');

        const draw = (): void => {
            const analyser = getMasterAnalyser();
            const binCount = analyser.frequencyBinCount;
            if (!data || data.length !== binCount) {
                data = new Float32Array(binCount);
                const halfLen = Math.floor(binCount / 2);
                left = new Float32Array(halfLen);
                right = new Float32Array(halfLen);
            }
            analyser.getFloatTimeDomainData(data);

            // Split into pseudo L/R (AnalyserNode is mono sum — for true stereo,
            // the engine would need a ChannelSplitter. Here we approximate by
            // treating odd/even samples as L/R, which works for interleaved sources)
            const halfLen = Math.floor(data.length / 2);
            for (let index = 0; index < halfLen; index++) {
                left![index] = data[index * 2]!;
                right![index] = data[index * 2 + 1]!;
            }

            const correlation = meterRef.current.update(left!, right!);

            // Draw
            ctx.clearRect(0, 0, width, height);

            // Background — deep black
            ctx.fillStyle = '#080808';
            ctx.beginPath();
            ctx.roundRect(0, 0, width, height, 3);
            ctx.fill();

            // Scale: -1 (left) to +1 (right)
            const midX = width / 2;
            const barY = 4;
            const barH = height - 8;

            // Background bar — slightly lighter
            ctx.fillStyle = '#101014';
            ctx.fillRect(2, barY, width - 4, barH);

            // Center line — subtle dashed
            ctx.strokeStyle = 'rgba(255,255,255,0.12)';
            ctx.lineWidth = 1;
            ctx.setLineDash([2, 3]);
            ctx.beginPath();
            ctx.moveTo(midX, barY);
            ctx.lineTo(midX, barY + barH);
            ctx.stroke();
            ctx.setLineDash([]);

            // Correlation indicator
            const indicatorX = midX + correlation * (midX - 4);
            let color: string;
            if (correlation > 0.5) {
                color = safeColor; // Good mono compatibility
            } else if (correlation > 0) {
                color = hotColor; // Moderate
            } else {
                color = clipColor; // Phase issues
            }

            // Bar from center to correlation value — with glow
            const barStart = Math.min(midX, indicatorX);
            const barW = Math.abs(indicatorX - midX);
            ctx.fillStyle = `${color}66`;
            ctx.shadowColor = color;
            ctx.shadowBlur = 6;
            ctx.fillRect(barStart, barY + 1, barW, barH - 2);
            ctx.shadowBlur = 0;

            // Indicator dot — bright with glow
            ctx.fillStyle = color;
            ctx.shadowColor = color;
            ctx.shadowBlur = 8;
            ctx.beginPath();
            ctx.arc(indicatorX, barY + barH / 2, 4, 0, Math.PI * 2);
            ctx.fill();
            ctx.shadowBlur = 0;

            // Labels — dim and refined
            ctx.fillStyle = 'rgba(255,255,255,0.22)';
            ctx.font = '7px monospace';
            ctx.textAlign = 'left';
            ctx.fillText('-1', 4, height - 2);
            ctx.textAlign = 'center';
            ctx.fillText('0', midX, height - 2);
            ctx.textAlign = 'right';
            ctx.fillText('+1', width - 4, height - 2);

            rafId = requestAnimationFrame(draw);
        };

        draw();
        return () => cancelAnimationFrame(rafId);
    }, [width, height]);

    return (
        <DawMeterFrame>
            <canvas
                ref={canvasRef}
                width={width}
                height={height}
                className="block"
                aria-label="Phase correlation meter"
                role="meter"
                aria-valuemin={-1}
                aria-valuemax={1}
            />
        </DawMeterFrame>
    );
};

import { type ReactElement, type MouseEvent, useState, useRef, useEffect } from 'react';

import { Circle, Ear, ShieldCheck } from 'lucide-react';

import { DawCompactInput } from '#/components/daw/DawCompactInput';
import { DawMicroBadge } from '#/components/daw/DawMicroBadge';
import { DawSwatchButton } from '#/components/daw/DawSwatchButton';
import { Fader } from '#/components/daw/Fader';
import { LatchButton } from '#/components/daw/LatchButton';
import { RotaryKnob } from '#/components/daw/RotaryKnob';
import { Tooltip, TooltipContent, TooltipTrigger } from '#/components/ui/tooltip';
import { getAllVCAGroups } from '#/modules/Arrangement/useCases';
import { cn } from '#/utils/Styles/cn';
import { TRACK_COLOR_PRESETS } from '#/utils/UI/colorPresets';
import { useContextMenuDismiss } from '#/utils/UI/useContextMenuDismiss';

import { type Track } from '../../../models/TrackViewTypes';
import { MixerStripValue } from '../../components/Mixer/MixerStripValue';
import { useChannelStripActions } from '../../hooks/useChannelStripActions';

import { DeviceChainSection } from './DeviceChainSection';
import { IOSection } from './IOSection';
import { MidiFxSection } from './MidiFxSection';
import { MixerLevelReadout } from './MixerLevelReadout';
import { MixerPopupLabel, MixerPopupMenu, MixerPopupOption, MixerPopupSeparator } from './MixerPopupMenu';
import { SendsSection } from './SendsSection';

type MixerMenu = { x: number; y: number } | null;

type ExpandedChannelStripProps = {
    track: Track;
    isSelected: boolean;
    widthClass: string;
};

export const ExpandedChannelStrip = ({ track, isSelected, widthClass }: ExpandedChannelStripProps): ReactElement => {
    const actions = useChannelStripActions(track);
    const [ctxMenu, setCtxMenu] = useState<MixerMenu>(null);
    const [isRenaming, setIsRenaming] = useState(false);
    const ctxRef = useRef<HTMLDivElement>(null);
    const renameRef = useRef<HTMLInputElement>(null);

    const handleContextMenu = (event: MouseEvent<HTMLDivElement>) => {
        event.preventDefault();
        event.stopPropagation();
        setCtxMenu({ x: event.clientX, y: event.clientY });
    };

    useContextMenuDismiss(ctxRef, () => setCtxMenu(null));

    useEffect(() => {
        if (isRenaming) {
            renameRef.current?.focus();
            renameRef.current?.select();
        }
    }, [isRenaming]);

    const act = (fn: () => void) => () => {
        fn();
        setCtxMenu(null);
    };

    return (
        <div
            className={cn(
                'flex shrink-0 flex-col items-center gap-1.5 rounded-lg p-2',
                widthClass,
                'border border-border-soft border-t-[var(--color-light-edge)] shadow-[0_1px_2px_rgba(0,0,0,0.4),inset_0_1px_0_rgba(255,255,255,0.03)]',
                isSelected && 'ring-1 ring-ring border-transparent'
            )}
            style={{ background: 'linear-gradient(180deg, #0c0c0c 0%, #0a0a0a 100%)' }}
            onClick={actions.select}
            onContextMenu={handleContextMenu}
            role="group"
            aria-label={`${track.name} channel`}
        >
            {/* Color bar */}
            <div className="h-1.5 w-full rounded-t-sm -mt-2 mb-1" style={{ backgroundColor: track.color }} />
            {/* Track name */}
            {isRenaming ? (
                <DawCompactInput
                    ref={renameRef}
                    defaultValue={track.name}
                    size="micro"
                    align="center"
                    monospace
                    className="w-full px-1 text-[9px]"
                    onBlur={(event) => {
                        actions.rename(event.currentTarget.value);
                        setIsRenaming(false);
                    }}
                    onKeyDown={(event) => {
                        if (event.key === 'Enter') {
                            actions.rename(event.currentTarget.value);
                            setIsRenaming(false);
                        }
                        if (event.key === 'Escape') {
                            setIsRenaming(false);
                        }
                    }}
                />
            ) : (
                <span
                    className="w-full truncate text-center text-[10px] font-medium text-foreground cursor-text"
                    onDoubleClick={() => setIsRenaming(true)}
                    title={track.name}
                >
                    {track.name}
                </span>
            )}
            <span className="text-[10px] text-muted-foreground capitalize">{track.kind}</span>
            {track.vcaGroupId ? (
                <DawMicroBadge tone="cyan" rounded="full" className="font-mono">
                    VCA
                </DawMicroBadge>
            ) : null}
            {/* Mute / Solo / Arm / Monitor */}
            <div className="flex flex-wrap justify-center gap-1">
                <Tooltip>
                    <TooltipTrigger asChild>
                        <LatchButton
                            active={track.muted}
                            variant="amber"
                            size="icon-sm"
                            aria-label={track.muted ? 'Unmute' : 'Mute'}
                            className="font-bold text-[10px]"
                            onClick={(event) => {
                                event.stopPropagation();
                                actions.toggleMute();
                            }}
                        >
                            M
                        </LatchButton>
                    </TooltipTrigger>
                    <TooltipContent>{track.muted ? 'Unmute' : 'Mute'}</TooltipContent>
                </Tooltip>
                <Tooltip>
                    <TooltipTrigger asChild>
                        <LatchButton
                            active={track.soloed}
                            variant="cyan"
                            size="icon-sm"
                            aria-label={track.soloed ? 'Unsolo' : 'Solo'}
                            className="font-bold text-[10px]"
                            onClick={(event) => {
                                event.stopPropagation();
                                actions.toggleSolo(event.metaKey || event.ctrlKey);
                            }}
                        >
                            S
                        </LatchButton>
                    </TooltipTrigger>
                    <TooltipContent>{track.soloed ? 'Unsolo' : 'Solo (⌘ click for additive)'}</TooltipContent>
                </Tooltip>
                <Tooltip>
                    <TooltipTrigger asChild>
                        <LatchButton
                            active={track.armed}
                            variant="red"
                            size="icon-sm"
                            aria-label={track.armed ? 'Disarm' : 'Arm'}
                            className=""
                            onClick={(event) => {
                                event.stopPropagation();
                                actions.toggleArm();
                            }}
                        >
                            <Circle className={cn('size-3', track.armed && 'fill-state-record')} />
                        </LatchButton>
                    </TooltipTrigger>
                    <TooltipContent>{track.armed ? 'Disarm' : 'Arm for recording'}</TooltipContent>
                </Tooltip>
                {track.kind === 'audio' ? (
                    <Tooltip>
                        <TooltipTrigger asChild>
                            <LatchButton
                                active={track.inputMonitoring === 'on'}
                                variant="mint"
                                size="icon-sm"
                                aria-label={track.inputMonitoring === 'on' ? 'Disable monitoring' : 'Enable monitoring'}
                                className=""
                                onClick={(event) => {
                                    event.stopPropagation();
                                    actions.toggleMonitoring();
                                }}
                            >
                                <Ear className={cn('size-3', track.inputMonitoring === 'on' && 'fill-state-play/30')} />
                            </LatchButton>
                        </TooltipTrigger>
                        <TooltipContent>Input monitoring</TooltipContent>
                    </Tooltip>
                ) : null}
                {track.soloSafe ? <ShieldCheck className="size-3 text-state-active" aria-label="Solo safe" /> : null}
            </div>
            <MixerLevelReadout
                trackId={track.id}
                control={
                    <div className="shrink-0" onPointerUp={actions.releaseGainAutomation}>
                        <Fader
                            value={track.gain}
                            onChange={actions.setGain}
                            min={0}
                            max={1.5}
                            step={0.01}
                            fineStep={0.001}
                            defaultValue={0.8}
                            height={100}
                            aria-label={`${track.name} gain`}
                        />
                    </div>
                }
                value={<>{track.gain === 0 ? '-∞' : `${((track.gain - 0.8) * 40).toFixed(1)}`} dB</>}
            />
            {/* Pan */}
            <div className="w-full px-1 flex flex-col items-center mt-2 mb-2">
                <div onPointerUp={actions.releasePanAutomation}>
                    <RotaryKnob
                        value={track.pan}
                        onChange={actions.setPan}
                        min={-50}
                        max={50}
                        size="sm"
                        aria-label={`${track.name} pan`}
                        bipolar
                    />
                </div>
                <MixerStripValue size="sm">
                    {(() => {
                        if (track.pan === 0) {
                            return 'C';
                        }
                        if (track.pan > 0) {
                            return `R${Math.round(track.pan)}`;
                        }
                        return `L${Math.abs(Math.round(track.pan))}`;
                    })()}
                </MixerStripValue>
            </div>
            {/* MIDI FX */}
            <MidiFxSection track={track} />
            {/* Devices — contained with scroll */}
            <DeviceChainSection track={track} />
            {/* Sends */}
            <SendsSection track={track} />
            {/* I/O */}
            <IOSection track={track} />
            {/* Context menu */}
            {(() => {
                if (ctxMenu) {
                    return (
                        <MixerPopupMenu
                            ref={ctxRef}
                            position="fixed"
                            className="max-h-[70vh] overflow-y-auto"
                            style={{ left: ctxMenu.x, top: ctxMenu.y }}
                            role="menu"
                        >
                            <MixerPopupOption role="menuitem" onClick={act(actions.toggleMute)}>
                                {track.muted ? 'Unmute' : 'Mute'}
                            </MixerPopupOption>
                            <MixerPopupOption role="menuitem" onClick={act(() => actions.toggleSolo(true))}>
                                {track.soloed ? 'Unsolo' : 'Solo'}
                            </MixerPopupOption>
                            <MixerPopupOption role="menuitem" onClick={act(actions.toggleSoloSafeFlag)}>
                                {track.soloSafe ? 'Disable Solo Safe' : 'Solo Safe'}
                            </MixerPopupOption>
                            <MixerPopupOption role="menuitem" onClick={act(actions.toggleArm)}>
                                {track.armed ? 'Disarm' : 'Arm for Recording'}
                            </MixerPopupOption>
                            <MixerPopupSeparator />
                            <MixerPopupOption role="menuitem" onClick={act(() => setIsRenaming(true))}>
                                Rename…
                            </MixerPopupOption>
                            <MixerPopupSeparator />
                            <MixerPopupLabel>Color</MixerPopupLabel>
                            <div className="flex gap-1 px-3 py-1">
                                {TRACK_COLOR_PRESETS.map((context) => (
                                    <DawSwatchButton
                                        key={context}
                                        color={context}
                                        active={context === track.color}
                                        onClick={act(() => actions.setColor(context))}
                                        aria-label={`Set color`}
                                    />
                                ))}
                            </div>
                            <MixerPopupSeparator />
                            <MixerPopupLabel>VCA Group</MixerPopupLabel>
                            {getAllVCAGroups().map((g) => (
                                <MixerPopupOption
                                    key={g.id}
                                    active={track.vcaGroupId === g.id}
                                    role="menuitem"
                                    onClick={act(() => actions.toggleVca(g.id))}
                                >
                                    {track.vcaGroupId === g.id ? `✓ ${g.name}` : g.name}
                                </MixerPopupOption>
                            ))}
                            <MixerPopupOption role="menuitem" onClick={act(actions.createVcaAndAssign)}>
                                + New VCA Group
                            </MixerPopupOption>
                            {track.vcaGroupId && (
                                <MixerPopupOption
                                    role="menuitem"
                                    className="text-muted-foreground"
                                    onClick={act(actions.removeFromVca)}
                                >
                                    Remove from VCA
                                </MixerPopupOption>
                            )}
                            <MixerPopupSeparator />
                            <MixerPopupOption role="menuitem" tone="danger" onClick={act(actions.removeWithConfirm)}>
                                Remove Channel
                            </MixerPopupOption>
                        </MixerPopupMenu>
                    );
                } else {
                    return null;
                }
            })()}
        </div>
    );
};

import { type ReactElement, useState } from 'react';

import { addMidiFx } from '#/modules/Arrangement/useCases';
import { cn } from '#/utils/Styles/cn';

import { type Track } from '../../../models/TrackViewTypes';
import { MixerInsetButton } from '../../components/Mixer/MixerInsetButton';
import { MixerSection } from '../../components/Mixer/MixerSection';

type MidiFxSectionProps = {
    track: Track;
};

const MIDI_FX_TYPES = [
    { label: 'Arpeggiator', type: 'arp' as const },
    { label: 'Velocity', type: 'velocity' as const },
    { label: 'Probability', type: 'probability' as const },
];

export const MidiFxSection = ({ track }: MidiFxSectionProps): ReactElement | null => {
    const [showAdd, setShowAdd] = useState(false);

    if (track.kind !== 'midi') {
        return null;
    }

    return (
        <MixerSection label="MIDI FX">
            <div className="max-h-[80px] space-y-0.5 overflow-y-auto overflow-x-hidden scrollbar-thin scrollbar-thumb-white/10">
                {(track as any).midiFx?.map((fx: any) => (
                    <div key={fx.id} className="group relative">
                        <MixerInsetButton
                            className={cn(
                                'shadow-[inset_0_1px_2px_rgba(0,0,0,0.4)]',
                                fx.bypassed && 'opacity-40 line-through'
                            )}
                            tone="accent"
                        >
                            <span className="text-[10px] text-accent-primary/80">♪ {fx.name}</span>
                        </MixerInsetButton>
                    </div>
                ))}
            </div>
            {showAdd ? (
                <div className="space-y-0.5 mt-0.5">
                    {MIDI_FX_TYPES.map((fx) => (
                        <MixerInsetButton
                            key={fx.type}
                            onClick={(event) => {
                                event.stopPropagation();
                                addMidiFx(track.id, fx.type, fx.label);
                                setShowAdd(false);
                            }}
                        >
                            + {fx.label}
                        </MixerInsetButton>
                    ))}
                    <button
                        type="button"
                        className="w-full text-[10px] text-muted-foreground hover:text-foreground"
                        onClick={(event) => {
                            event.stopPropagation();
                            setShowAdd(false);
                        }}
                    >
                        cancel
                    </button>
                </div>
            ) : (
                <MixerInsetButton
                    onClick={(event) => {
                        event.stopPropagation();
                        setShowAdd(true);
                    }}
                >
                    <span className="text-[10px] text-muted-foreground/50">+ add fx</span>
                </MixerInsetButton>
            )}
        </MixerSection>
    );
};

