import { type ReactElement, useState, useEffect, useRef } from 'react';

import { Loader2, Sparkles, GraduationCap } from 'lucide-react';
import ReactMarkdown from 'react-markdown';

import { DawDialogBody } from '#/components/daw/DawDialogBody';
import { DawDialogFooter } from '#/components/daw/DawDialogFooter';
import { DawDialogSection } from '#/components/daw/DawDialogSection';
import { DawHeaderBand } from '#/components/daw/DawHeaderBand';
import { Button } from '#/components/ui/button';
import { Dialog, DialogContent, DialogTitle } from '#/components/ui/dialog';
import { logger } from '#/infra/logger/appLogger';
import { streamCloudChatCompletion } from '#/modules/AiRuntime/useCases';
import { mixHealthAnalysis } from '#/modules/AudioAnalysis/useCases';

type MixHealthDialogProps = {
    open: boolean;
    onOpenChange: (open: boolean) => void;
};

export const MixHealthDialog = ({ open, onOpenChange }: MixHealthDialogProps): ReactElement => {
    const [isAnalyzing, setIsAnalyzing] = useState(false);
    const [report, setReport] = useState('');
    const reportRef = useRef('');

    useEffect(() => {
        if (open) {
            setReport('');
            reportRef.current = '';
            setIsAnalyzing(true);

            const runAnalysis = async () => {
                try {
                    await mixHealthAnalysis((token) => {
                        reportRef.current += token;
                        setReport(reportRef.current);
                    });
                } catch (error) {
                    logger.warn('Mix health analysis failed:', error);
                    setReport('Error generating mix health report. Make sure Cloud AI is connected.');
                } finally {
                    setIsAnalyzing(false);
                }
            };

            void runAnalysis();
        } else {
            setReport('');
        }
    }, [open]);

    const handleELI5 = async () => {
        if (isAnalyzing || !report) {
            return;
        }

        setIsAnalyzing(true);
        const originalReport = report;
        reportRef.current = `${report}\n\n---\n\n### ELI5 Translation\n\n`;
        setReport(reportRef.current);

        try {
            await streamCloudChatCompletion(
                [
                    { role: 'system', content: 'You are a patient music teacher for beginners.' },
                    {
                        role: 'user',
                        content: `Here is a technical mix analysis:\n\n${originalReport}\n\nPlease explain this to me like I am a 5 year old beginner. Focus entirely on simple analogies.`,
                    },
                ],
                (token) => {
                    reportRef.current += token;
                    setReport(reportRef.current);
                }
            );
        } catch (error) {
            logger.warn('ELI5 generation failed:', error);
            reportRef.current += '\n[Error generating ELI5 explanation]';
            setReport(reportRef.current);
        } finally {
            setIsAnalyzing(false);
        }
    };

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent className="max-w-2xl gap-0 overflow-hidden p-0 text-foreground">
                <DialogTitle className="sr-only">AI Music Mentor: Mix Health</DialogTitle>
                <DawHeaderBand
                    className="px-4 py-3"
                    startSlot={<Sparkles className="size-3.5 text-[var(--color-accent-lavender)]" />}
                    title="AI Music Mentor: Mix Health"
                    titleClassName="text-[11px] text-foreground normal-case tracking-normal"
                />

                <DawDialogBody scrollable className="min-h-[200px] max-h-[500px] px-4 py-4 text-sm leading-relaxed">
                    <DawDialogSection
                        title="Analysis"
                        detail={report ? 'Cloud mentor report' : 'Generating a fresh read on the current mix'}
                    >
                        {report ? (
                            <div className="prose prose-invert prose-sm max-w-none">
                                <ReactMarkdown>{report}</ReactMarkdown>
                            </div>
                        ) : null}

                        {isAnalyzing ? (
                            <div className="flex items-center gap-2 pt-4 text-muted-foreground">
                                <Loader2 className="size-4 animate-spin" />
                                <span>Mentor is thinking...</span>
                            </div>
                        ) : null}
                    </DawDialogSection>
                </DawDialogBody>

                <DawDialogFooter>
                    <Button
                        variant="secondary"
                        size="sm"
                        onClick={handleELI5}
                        disabled={isAnalyzing || !report}
                        className="bg-[var(--color-accent-lavender)]/10 text-[var(--color-accent-lavender)] hover:bg-[var(--color-accent-lavender)]/20 border-[var(--color-accent-lavender)]/20"
                    >
                        <GraduationCap className="size-4 mr-2" />
                        Explain Like I'm 5
                    </Button>
                    <Button variant="outline" size="sm" onClick={() => onOpenChange(false)}>
                        Close
                    </Button>
                </DawDialogFooter>
            </DialogContent>
        </Dialog>
    );
};

import { type ReactElement, type ReactNode, useEffect, useRef } from 'react';

import { getTrackPeakLevel, getMasterPeakLevel } from '#/modules/AudioEngine/useCases';
import { animationScheduler } from '#/utils/DOM/AnimationScheduler';
import { cn } from '#/utils/Styles/cn';

import { MixerStripValue } from '../../components/Mixer/MixerStripValue';
import { LevelMeter } from '../Metering/LevelMeter';

type MixerLevelReadoutProps = {
    trackId: string | null;
    control: ReactNode;
    value: ReactNode;
    clusterClassName?: string;
    valueSize?: 'sm' | 'md';
};

const MIN_DB = -60;

const linearToDb = (linear: number): number => {
    if (linear <= 0) {
        return MIN_DB;
    }
    return Math.max(MIN_DB, 20 * Math.log10(linear));
};

export const MixerLevelReadout = ({
    trackId,
    control,
    value,
    clusterClassName,
    valueSize = 'md',
}: MixerLevelReadoutProps): ReactElement => {
    const id = crypto.randomUUID();
    const peakTextRef = useRef<HTMLDivElement>(null);
    const maxPeakRef = useRef<number>(MIN_DB);

    useEffect(() => {
        const tick = () => {
            const rawPeak = trackId ? getTrackPeakLevel(trackId) : getMasterPeakLevel();
            const db = linearToDb(rawPeak);

            if (db > maxPeakRef.current) {
                maxPeakRef.current = db;
                if (peakTextRef.current) {
                    peakTextRef.current.textContent = db <= MIN_DB ? '-∞' : db.toFixed(1);
                    if (db > 0) {
                        peakTextRef.current.classList.add('text-state-error');
                        peakTextRef.current.classList.remove('text-muted-foreground/80');
                    } else {
                        peakTextRef.current.classList.remove('text-state-error');
                        peakTextRef.current.classList.add('text-muted-foreground/80');
                    }
                }
            }
        };

        animationScheduler.register(`peak-readout-${id}`, tick);

        return () => {
            animationScheduler.unregister(`peak-readout-${id}`);
        };
    }, [trackId, id]);

    const handleReset = () => {
        maxPeakRef.current = MIN_DB;
        if (peakTextRef.current) {
            peakTextRef.current.textContent = '-∞';
            peakTextRef.current.classList.remove('text-state-error');
            peakTextRef.current.classList.add('text-muted-foreground/80');
        }
    };

    return (
        <>
            <div className={cn('mt-1 flex shrink-0 flex-col items-center gap-1', clusterClassName)}>
                <div
                    ref={peakTextRef}
                    onClick={handleReset}
                    className="text-[9px] font-mono cursor-pointer text-muted-foreground/80 hover:text-text-primary transition-colors h-3 flex items-center justify-center"
                    title="Click to reset peak"
                >
                    -∞
                </div>
                <div className="flex items-end justify-center h-full">
                    <LevelMeter trackId={trackId} width="w-1.5" />
                </div>
                {control}
            </div>
            <MixerStripValue size={valueSize}>{value}</MixerStripValue>
        </>
    );
};

