source:
import { type ReactElement } from 'react';

import {
    Sparkles,
    Check,
    X,
    Brain,
    Zap,
    History,
    Music,
    Disc3,
    AudioLines,
    Play,
    Layers,
    Piano,
    Cable,
    Wand2,
    LayoutDashboard,
    Sliders,
    GitBranch,
    FolderOpen,
    Users,
    AlertTriangle,
} from 'lucide-react';

import { DawMicroBadge } from '#/components/daw/DawMicroBadge';
import { Button } from '#/components/ui/button';
import { Input } from '#/components/ui/input';
import { toggleAiHistoryPanel } from '#/modules/AiRuntime/stores';
import { describeAction } from '#/modules/Command/useCases';

import { usePromptExecution, type PromptFuzzyResult, type SelectionTag } from '../hooks/usePromptExecution';

import { LlmStatusBadge } from './Prompt/LlmStatusBadge';

// ── Category icons ──────────────────────────────────────────────────────

type PromptPresetCategory = PromptFuzzyResult['preset']['category'];

const CATEGORY_ICONS: Record<PromptPresetCategory, typeof Play> = {
    Transport: Play,
    Track: Layers,
    Clip: Music,
    MIDI: Piano,
    Device: Cable,
    Generate: Wand2,
    Workspace: LayoutDashboard,
    Mix: Sliders,
    Automation: GitBranch,
    File: FolderOpen,
    Collaboration: Users,
};

const TAG_ICONS = {
    track: AudioLines,
    clip: Music,
    clips: Disc3,
} as const;

// ── Sub-components ──────────────────────────────────────────────────────

const SelectionTagChip = ({ tag, onRemove }: { tag: SelectionTag; onRemove: () => void }): ReactElement => {
    const Icon = TAG_ICONS[tag.icon];
    return (
        <DawMicroBadge tone="primary" className="shrink-0 gap-1 text-[10px]">
            <Icon className="size-2.5" aria-hidden="true" />
            <span className="truncate max-w-20">{tag.label}</span>
            <button
                type="button"
                onClick={(event) => {
                    event.preventDefault();
                    event.stopPropagation();
                    onRemove();
                }}
                className="ml-0.5 hover:text-primary transition-colors"
                aria-label={`Remove ${tag.label} from context`}
            >
                <X className="size-2.5" />
            </button>
        </DawMicroBadge>
    );
};

const FuzzyResultItem = ({
    result,
    isSelected,
    onExecute,
}: {
    result: PromptFuzzyResult;
    isSelected: boolean;
    onExecute: () => void;
}): ReactElement => {
    const Icon = CATEGORY_ICONS[result.preset.category] ?? Zap;
    return (
        <button
            type="button"
            className={`w-full flex items-center gap-2.5 px-3 py-1.5 text-xs transition-colors ${
                isSelected
                    ? 'bg-white/[0.08] text-foreground'
                    : 'text-muted-foreground hover:bg-white/[0.06] hover:text-foreground'
            }`}
            onMouseDown={(event) => {
                event.preventDefault();
                onExecute();
            }}
            role="option"
            aria-selected={isSelected}
        >
            <Icon className="size-3.5 shrink-0 opacity-60" aria-hidden="true" />
            <span className="flex-1 text-left truncate">{result.preset.label}</span>
            {result.preset.isDestructive ? (
                <AlertTriangle
                    className="size-3 text-[var(--color-state-warning)] shrink-0"
                    aria-label="Destructive action"
                />
            ) : null}
            <DawMicroBadge>{result.preset.category}</DawMicroBadge>
        </button>
    );
};

// ── Main component ──────────────────────────────────────────────────────

export const PromptBar = (): ReactElement => {
    const prompt = usePromptExecution();

    // ── Preview mode ────────────────────────────────────────────────────
    if (prompt.preview) {
        return (
            <div className="flex items-center gap-2 max-w-lg">
                <Sparkles className="size-3.5 shrink-0 text-[var(--color-accent-peach)]" aria-hidden="true" />
                <div className="flex-1 min-w-0">
                    <div className="flex flex-wrap gap-1">
                        {prompt.preview.actions.map((alpha, index: number) => (
                            <DawMicroBadge key={index} className="text-[10px] text-foreground">
                                {describeAction(alpha)}
                            </DawMicroBadge>
                        ))}
                    </div>
                </div>
                <Button size="icon-xs" variant="ghost" onClick={prompt.confirmPreview} aria-label="Confirm actions">
                    <Check className="size-3 text-[var(--color-state-success)]" />
                </Button>
                <Button size="icon-xs" variant="ghost" onClick={prompt.cancelPreview} aria-label="Cancel actions">
                    <X className="size-3 text-destructive-foreground" />
                </Button>
            </div>
        );
    }

    // ── Main render ─────────────────────────────────────────────────────
    return (
        <div className="relative flex-1 max-w-lg">
            <form
                ref={prompt.formRef}
                onSubmit={prompt.handleSubmit}
                className="daw-readout-well flex items-center gap-1.5 rounded-sm px-2 py-0.5"
            >
                {(() => {
                    if (prompt.isProcessing) {
                        return (
                            <Button
                                size="icon-xs"
                                variant="ghost"
                                type="button"
                                aria-label="Cancel AI processing"
                                onClick={prompt.cancelProcessing}
                            >
                                <X className="size-3 text-destructive-foreground" />
                            </Button>
                        );
                    }
                    if (prompt.willUseLlm) {
                        return <Brain className="size-3.5 shrink-0 text-primary" aria-hidden="true" />;
                    }
                    return <Zap className="size-3.5 shrink-0 text-muted-foreground" aria-hidden="true" />;
                })()}
                {prompt.selectionTags.map((tag) => (
                    <SelectionTagChip key={tag.id} tag={tag} onRemove={() => prompt.dismissTag(tag.id)} />
                ))}
                <Input
                    ref={prompt.inputRef}
                    type="text"
                    value={prompt.value}
                    onChange={(event) => prompt.setValue(event.target.value)}
                    onKeyDown={prompt.handleKeyDown}
                    onFocus={() => prompt.setIsFocused(true)}
                    onBlur={() => {
                        setTimeout(() => prompt.setIsFocused(false), 200);
                    }}
                    placeholder={(() => {
                        if (prompt.isProcessing) {
                            return prompt.llmStatus?.state === 'generating' ? 'AI is thinking...' : 'Processing...';
                        } else {
                            if (prompt.selectionTags.length > 0) {
                                return 'What do you want to do with this?';
                            } else {
                                return 'Type a command... (⌘K for palette)';
                            }
                        }
                    })()}
                    className="h-7 border-0 bg-transparent text-xs shadow-none focus-visible:ring-0 placeholder:text-muted-foreground/60"
                    aria-label="Prompt command input"
                    aria-autocomplete="list"
                    aria-expanded={prompt.fuzzyResults.length > 0}
                    aria-controls="prompt-results"
                    disabled={prompt.isProcessing}
                />
                <Button
                    variant="ghost"
                    size="icon-xs"
                    onClick={toggleAiHistoryPanel}
                    title="AI action history"
                    aria-label="Toggle AI action history"
                    type="button"
                >
                    <History className="size-3.5" />
                </Button>
                <LlmStatusBadge status={prompt.llmStatus ?? { state: 'idle' }} onLoad={prompt.handleLoadModel} />
            </form>
            {(() => {
                if (prompt.fuzzyResults.length > 0) {
                    return (
                        <div
                            id="prompt-results"
                            role="listbox"
                            aria-label="Command suggestions"
                            className="daw-floating-surface absolute top-full left-0 right-0 z-50 mt-1 max-h-80 overflow-y-auto rounded-md py-1"
                        >
                            {prompt.value.trim().length === 0 ? (
                                <div className="px-3 py-1 text-[9px] uppercase tracking-wider text-muted-foreground/50 font-medium">
                                    Available commands
                                </div>
                            ) : null}
                            {prompt.fuzzyResults.map((result, index) => (
                                <FuzzyResultItem
                                    key={result.preset.id}
                                    result={result}
                                    isSelected={index === prompt.selectedIndex}
                                    onExecute={() => void prompt.executePreset(result)}
                                />
                            ))}
                            {prompt.value.trim().length > 0 && prompt.fuzzyResults.length === 0 ? (
                                <div className="px-3 py-2 text-xs text-muted-foreground/60 italic">
                                    No matching commands — press Enter to try AI
                                </div>
                            ) : null}
                        </div>
                    );
                } else {
                    return null;
                }
            })()}
        </div>
    );
};

/**
 * Session / Clip Launcher View.
 * Ableton-style vertical grid of clip slots with scene triggers.
 * Each track has a column of clip slots; each row is a scene.
 */
import { type ReactElement } from 'react';

import { Play, Square, Plus } from 'lucide-react';

import { DawEmptyState } from '#/components/daw/DawEmptyState';
import { DawGridHeaderCell } from '#/components/daw/DawGridHeaderCell';
import { DawHeaderBand } from '#/components/daw/DawHeaderBand';
import { DawPanelSurface } from '#/components/daw/DawPanelSurface';
import { DawSideRail } from '#/components/daw/DawSideRail';
import { Button } from '#/components/ui/button';
import { useStore } from '#/infra/store/useStore';
import { cn } from '#/utils/Styles/cn';

import { type Track } from '../../models/TrackViewTypes';
import { sessionLaunchStore, type SessionLaunchState } from '../../stores/sessionLaunchStore';
import { useTracks } from '../hooks/useTracks';

const SCENE_COUNT = 8;
const emptyState: SessionLaunchState = { activeSlots: {} };

export const SessionView = (): ReactElement => {
    const { tracks } = useTracks();
    // §83.2 — state lives in a module-level store so panel close/reopen
    // no longer discards which clips are launched.
    const state = useStore(sessionLaunchStore, emptyState);
    const activeSlots = state.activeSlots;

    const handleLaunchSlot = (trackId: string, sceneIndex: number): void => {
        const current = sessionLaunchStore.value ?? emptyState;
        const next = { ...current.activeSlots };
        if (next[trackId] === sceneIndex) {
            delete next[trackId];
        } else {
            next[trackId] = sceneIndex;
        }
        sessionLaunchStore.set({ activeSlots: next });
    };

    const handleLaunchScene = (sceneIndex: number): void => {
        const next: Record<string, number> = {};
        for (const time of tracks) {
            next[time.id] = sceneIndex;
        }
        sessionLaunchStore.set({ activeSlots: next });
    };

    const handleStopAll = (): void => {
        sessionLaunchStore.set({ activeSlots: {} });
    };

    // §142.1 — pre-compute the clip-per-slot map once per track during the
    // outer tracks.map rather than re-scanning `tracks` inside the scene
    // inner loop. The previous getClipForSlot(trackId, sceneIndex) did a
    // full tracks.find() per rendered cell → O(tracks × scenes × tracks).

    return (
        <DawPanelSurface>
            <DawHeaderBand
                className="shrink-0"
                title="Session"
                titleClassName="text-[11px] font-semibold text-foreground uppercase tracking-wider"
                actions={
                    <Button
                        variant="ghost"
                        size="icon-xs"
                        onClick={handleStopAll}
                        aria-label="Stop all clips"
                        className="size-5"
                    >
                        <Square className="size-2.5" />
                    </Button>
                }
            />
            {/* Grid */}
            <div className="flex-1 overflow-auto">
                {(() => {
                    if (tracks.length === 0) {
                        return (
                            <div className="flex min-h-full items-center justify-center p-6">
                                <DawEmptyState
                                    title="No session tracks yet"
                                    description="Add a track to start launching clips and scenes from the grid."
                                    className="max-w-sm"
                                />
                            </div>
                        );
                    } else {
                        return (
                            <div className="flex min-w-max">
                                <DawSideRail className="w-10">
                                    <DawGridHeaderCell className="h-6 text-[10px] uppercase tracking-wider text-muted-foreground">
                                        Scene
                                    </DawGridHeaderCell>
                                    {Array.from({ length: SCENE_COUNT }, (_, index) => (
                                        <button
                                            type="button"
                                            key={index}
                                            className="h-10 cursor-pointer border-b border-border-hairline shadow-[inset_0_1px_0_rgba(255,255,255,0.02)] transition-colors hover:bg-surface-raised"
                                            onClick={() => handleLaunchScene(index)}
                                            aria-label={`Launch scene ${index + 1}`}
                                        >
                                            <div className="flex h-full items-center justify-center">
