                                                {track.name}
                                            </DawGridHeaderCell>
                                            {Array.from({ length: SCENE_COUNT }, (_, sceneIndex) => {
                                                const clipId = trackClipIds[sceneIndex] ?? null;
                                                const isActive = activeSlots[track.id] === sceneIndex;

                                                return (
                                                    <div
                                                        key={sceneIndex}
                                                        className={cn(
