import { type ReactElement, useRef, useEffect } from 'react';

import { Tooltip, TooltipContent, TooltipTrigger } from '#/components/ui/tooltip';
import { useStore } from '#/infra/store/useStore';
import { playheadPositionRef, transportStore } from '#/modules/Transport/stores';
import { defaultTransportState } from '#/modules/Transport/useCases';

import { type TimeDisplayMode } from '../../../models/WorkspaceState';
import { toggleTimeDisplayMode } from '../../../useCases/togglePanel/panelToggles/toggleTimeDisplayMode';
import { TransportSegmentedReadout } from '../../components/Transport/TransportSegmentedReadout';

type PlayheadDisplayProps = {
    tempo: number;
    numerator: number;
    timeDisplayMode: TimeDisplayMode;
};

/**
 * PlayheadDisplay reads playhead position from the non-reactive
 * `playheadPositionRef` via a rAF loop and writes directly to the DOM.
 * This avoids ~100 React re-renders/sec during playback.
 */
export const PlayheadDisplay = ({ tempo, numerator, timeDisplayMode }: PlayheadDisplayProps): ReactElement => {
    const isMusical = timeDisplayMode === 'musical';
    const transportState = useStore(transportStore, defaultTransportState);
    const isPlaying = transportState.isPlaying;

    // Refs for direct DOM updates
    const seg1Ref = useRef<HTMLSpanElement>(null);
    const seg2Ref = useRef<HTMLSpanElement>(null);
    const seg3Ref = useRef<HTMLSpanElement>(null);
    const rafRef = useRef(0);
    const tempoRef = useRef(tempo);
    const numeratorRef = useRef(numerator);
    const isMusicalRef = useRef(isMusical);

    // Keep refs in sync with props (avoids stale closures in rAF loop)
    tempoRef.current = tempo;
    numeratorRef.current = numerator;
    isMusicalRef.current = isMusical;

    // Update segments once from current position (initial + on mode toggle)
    const updateOnce = (): void => {
        const position = playheadPositionRef.current;
        if (isMusicalRef.current) {
            const bar = Math.floor(position / numeratorRef.current) + 1;
            const beat = Math.floor(position % numeratorRef.current) + 1;
            const tick = Math.floor((position % 1) * 480);
            if (seg1Ref.current) {
                seg1Ref.current.textContent = String(bar);
            }
            if (seg2Ref.current) {
                seg2Ref.current.textContent = String(beat);
            }
            if (seg3Ref.current) {
                seg3Ref.current.textContent = String(tick).padStart(3, '0');
            }
        } else {
            const seconds = position / (tempoRef.current / 60);
            const mins = Math.floor(seconds / 60);
            const secs = Math.floor(seconds % 60);
            const ms = Math.floor((seconds % 1) * 1000);
            if (seg1Ref.current) {
                seg1Ref.current.textContent = String(mins).padStart(2, '0');
            }
            if (seg2Ref.current) {
                seg2Ref.current.textContent = String(secs).padStart(2, '0');
            }
            if (seg3Ref.current) {
                seg3Ref.current.textContent = String(ms).padStart(3, '0');
            }
        }
    };

    // rAF loop for live updates during playback
    useEffect(() => {
        // Always do an initial update
        updateOnce();

        if (!isPlaying) {
            return undefined;
        }
        const loop = (): void => {
            updateOnce();
            rafRef.current = requestAnimationFrame(loop);
        };
        rafRef.current = requestAnimationFrame(loop);
        return () => cancelAnimationFrame(rafRef.current);
    }, [isPlaying, isMusical]);

    // Compute initial values for SSR / first paint
    const position = playheadPositionRef.current;

    if (isMusical) {
        const bar = Math.floor(position / numerator) + 1;
        const beat = Math.floor(position % numerator) + 1;
        const tick = Math.floor((position % 1) * 480);

        return (
            <Tooltip>
                <TooltipTrigger asChild>
                    <TransportSegmentedReadout
                        label="Bars"
                        segments={[bar, beat, String(tick).padStart(3, '0')]}
                        separators={['.', '.']}
                        segmentRefs={[seg1Ref, seg2Ref, seg3Ref]}
                        active={isPlaying}
                        onClick={toggleTimeDisplayMode}
                        ariaLabel="Playhead position — click to switch to wall-clock time"
                    />
                </TooltipTrigger>
                <TooltipContent>Click to switch to wall-clock time</TooltipContent>
            </Tooltip>
        );
    }

    const seconds = position / (tempo / 60);
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    const ms = Math.floor((seconds % 1) * 1000);

    return (
        <Tooltip>
            <TooltipTrigger asChild>
                <TransportSegmentedReadout
                    label="Time"
                    segments={[
                        String(mins).padStart(2, '0'),
                        String(secs).padStart(2, '0'),
                        String(ms).padStart(3, '0'),
                    ]}
                    separators={[':', '.']}
                    segmentRefs={[seg1Ref, seg2Ref, seg3Ref]}
                    active={isPlaying}
                    onClick={toggleTimeDisplayMode}
                    ariaLabel="Playhead position — click to switch to bars and beats"
                />
            </TooltipTrigger>
            <TooltipContent>Click to switch to bars &amp; beats</TooltipContent>
        </Tooltip>
    );
};

import { type ReactElement } from 'react';

import { Play, Pause, Square, Circle, Repeat, Scissors, ListOrdered, Layers } from 'lucide-react';

import { DawTransportCluster } from '#/components/daw/DawTransportCluster';
import { LatchButton } from '#/components/daw/LatchButton';
import { LED } from '#/components/daw/LED';
import { Button } from '#/components/ui/button';
import { Slider } from '#/components/ui/slider';
import { Tooltip, TooltipContent, TooltipTrigger } from '#/components/ui/tooltip';
import {
    togglePlayback,
    stopPlayback,
    toggleLoop,
    toggleOverdub,
    toggleMetronome,
    setMetronomeVolume,
    toggleRecording,
    togglePunchEnabled,
    toggleCountIn,
    setCountInBars,
} from '#/modules/Transport/useCases';
import { cn } from '#/utils/Styles/cn';

import { TransportValuePill } from '../../components/Transport/TransportValuePill';

type TransportControlsProps = {
    isPlaying: boolean;
    isRecording: boolean;
    isAudioRecording: boolean;
    isLooping: boolean;
    overdubEnabled: boolean;
    showOverdub: boolean;
    anyTrackArmed: boolean;
    metronomeEnabled: boolean;
    metronomeVolume: number;
    punchInEnabled: boolean;
    countInEnabled: boolean;
    countInBars: number;
};

export const TransportControls = ({
    isPlaying,
    isRecording,
    isAudioRecording,
    isLooping,
    overdubEnabled,
    showOverdub,
    anyTrackArmed,
    metronomeEnabled,
    metronomeVolume,
    punchInEnabled,
    countInEnabled,
    countInBars,
}: TransportControlsProps): ReactElement => {
    const cycleCountInBars = (): void => {
        let next: number;
        if (countInBars >= 4) {
            next = 1;
        } else if (countInBars >= 2) {
            next = 4;
        } else if (countInBars >= 1) {
            next = 2;
        } else {
            next = 1;
        }
        setCountInBars(next);
    };

    return (
        <DawTransportCluster tone="well" role="group" aria-label="Playback controls">
            <span className="sr-only" aria-live="polite" role="status">
                {(() => {
                    if (isRecording) {
                        return 'Recording';
                    }
                    if (isPlaying) {
                        return 'Playing';
                    }
                    return 'Stopped';
                })()}
            </span>
            <Tooltip>
                <TooltipTrigger asChild>
                    <LatchButton
                        active={isPlaying}
                        variant="mint"
                        size="icon"
                        aria-label={isPlaying ? 'Pause' : 'Play'}
                        onClick={togglePlayback}
                    >
                        {isPlaying ? (
                            <Pause className="size-4" aria-hidden="true" />
                        ) : (
                            <Play className="size-4" aria-hidden="true" />
                        )}
                    </LatchButton>
                </TooltipTrigger>
                <TooltipContent>{isPlaying ? 'Pause' : 'Play'} (Space)</TooltipContent>
            </Tooltip>

            <Tooltip>
                <TooltipTrigger asChild>
                    <Button variant="transport" size="icon-sm" aria-label="Stop" onClick={stopPlayback}>
                        <Square className="size-3.5 fill-text-secondary" aria-hidden="true" />
                    </Button>
                </TooltipTrigger>
                <TooltipContent>Stop (Esc)</TooltipContent>
            </Tooltip>

            <Tooltip>
                <TooltipTrigger asChild>
                    <LatchButton
                        active={isRecording}
                        variant="red"
                        size="icon"
                        aria-label={isRecording ? 'Stop recording' : 'Record'}
                        aria-pressed={isRecording}
                        onClick={toggleRecording}
                        className={cn(!isRecording && anyTrackArmed && 'ring-1 ring-state-danger')}
                    >
                        <Circle
                            className={cn('size-3.5', isRecording ? 'fill-state-record' : 'text-text-primary')}
                            aria-hidden="true"
                        />
                    </LatchButton>
                </TooltipTrigger>
                <TooltipContent>
                    {(() => {
                        if (isRecording) {
                            return 'Stop Recording';
                        }
                        if (anyTrackArmed) {
                            return 'Record (tracks armed)';
                        }
                        return 'Record';
                    })()}{' '}
                    (R)
                </TooltipContent>
            </Tooltip>
            <LED on={isAudioRecording} variant="red" size="sm" />

            <Tooltip>
                <TooltipTrigger asChild>
                    <LatchButton
                        active={isLooping}
                        variant="amber"
                        size="icon"
                        aria-label="Loop"
                        aria-pressed={isLooping}
                        onClick={toggleLoop}
                    >
                        <Repeat className="size-3.5" aria-hidden="true" />
                    </LatchButton>
                </TooltipTrigger>
                <TooltipContent>Loop (L)</TooltipContent>
            </Tooltip>

            {showOverdub ? (
                <Tooltip>
                    <TooltipTrigger asChild>
                        <LatchButton
                            active={overdubEnabled}
                            variant="cyan"
                            size="icon"
                            aria-label="Overdub"
                            aria-pressed={overdubEnabled}
                            onClick={toggleOverdub}
                        >
                            <Layers className="size-3.5" aria-hidden="true" />
                        </LatchButton>
                    </TooltipTrigger>
                    <TooltipContent>MIDI Overdub (+)</TooltipContent>
                </Tooltip>
            ) : null}

            <Tooltip>
                <TooltipTrigger asChild>
                    <LatchButton
                        active={metronomeEnabled}
                        variant="cyan"
                        size="icon"
                        aria-label="Metronome"
                        aria-pressed={metronomeEnabled}
                        onClick={toggleMetronome}
                    >
                        <svg
                            className="size-3.5"
                            viewBox="0 0 24 24"
                            fill="none"
                            stroke="currentColor"
                            strokeWidth="2"
                            strokeLinecap="round"
                            strokeLinejoin="round"
                            aria-hidden="true"
                        >
                            <path d="M12 2L6 22h12L12 2z" />
                            <path d="M12 12l4-8" />
                        </svg>
                    </LatchButton>
                </TooltipTrigger>
                <TooltipContent>Metronome (M)</TooltipContent>
            </Tooltip>

            {metronomeEnabled ? (
                <Tooltip>
                    <TooltipTrigger asChild>
                        <div className="flex items-center px-2 py-1">
                            <Slider
                                min={0}
                                max={1}
                                step={0.01}
                                value={[metronomeVolume]}
                                onValueChange={(val) => setMetronomeVolume(val[0] ?? 0)}
                                className="w-16 h-3"
                                aria-label={`Metronome volume: ${Math.round(metronomeVolume * 100)}%`}
                            />
                        </div>
                    </TooltipTrigger>
                    <TooltipContent>Metronome volume: {Math.round(metronomeVolume * 100)}%</TooltipContent>
                </Tooltip>
            ) : null}

            <Tooltip>
                <TooltipTrigger asChild>
                    <LatchButton
                        active={punchInEnabled}
                        variant="amber"
                        size="icon"
                        aria-label="Punch in/out"
                        aria-pressed={punchInEnabled}
                        onClick={togglePunchEnabled}
                    >
                        <Scissors className="size-3.5" aria-hidden="true" />
                    </LatchButton>
                </TooltipTrigger>
                <TooltipContent>Punch In/Out (I)</TooltipContent>
            </Tooltip>

            <Tooltip>
                <TooltipTrigger asChild>
                    <LatchButton
                        active={countInEnabled}
                        variant="cyan"
                        size="icon"
                        aria-label="Count-in"
                        aria-pressed={countInEnabled}
                        onClick={toggleCountIn}
                    >
                        <ListOrdered className="size-3.5" aria-hidden="true" />
                    </LatchButton>
                </TooltipTrigger>
                <TooltipContent>Count-in</TooltipContent>
            </Tooltip>
            {countInEnabled ? (
                <Tooltip>
                    <TooltipTrigger asChild>
                        <TransportValuePill
                            active
                            onClick={cycleCountInBars}
                            aria-label={`Count-in bars: ${countInBars}. Click to cycle.`}
                        >
                            {countInBars}
                        </TransportValuePill>
                    </TooltipTrigger>
                    <TooltipContent>Count-in bars (click to cycle 1→2→4)</TooltipContent>
                </Tooltip>
            ) : null}
        </DawTransportCluster>
    );
};

