/**
 * KeyboardSplit — visual keyboard showing held/sounding notes and split zones.
 * Mini keyboard spanning C1-C7 (36-96) with color-coded zones.
 */
import { type ReactElement } from 'react';

type Props = {
    /** Notes currently held (from input). */
    heldNotes?: number[];
    /** Notes currently sounding (from arp/processor output). */
    soundingNotes?: number[];
    /** Low/high split point (MIDI note number). */
    splitPoint?: number;
    width: number;
    height: number;
};

const RANGE_LOW = 36; // C2
const RANGE_HIGH = 96; // C7
function isBlack(note: number): boolean {
    const pc = note % 12;
    return [1, 3, 6, 8, 10].includes(pc);
}

export const KeyboardSplit = ({
    heldNotes = [],
    soundingNotes = [],
    splitPoint,
    width,
    height,
}: Props): ReactElement => {
    const whiteKeys: number[] = [];
    const blackKeys: number[] = [];
    for (let node = RANGE_LOW; node < RANGE_HIGH; node++) {
        if (isBlack(node)) {
            blackKeys.push(node);
        } else {
            whiteKeys.push(node);
        }
    }

    const whiteKeyWidth = width / whiteKeys.length;

    // Map note → x position
    const noteToX = (note: number): number => {
        // Count white keys below this note
        let whiteCount = 0;
        for (let node = RANGE_LOW; node < note; node++) {
            if (!isBlack(node)) {
                whiteCount++;
            }
        }
        if (isBlack(note)) {
            return whiteCount * whiteKeyWidth - whiteKeyWidth * 0.3;
        }
        return whiteCount * whiteKeyWidth;
    };

    const heldSet = new Set(heldNotes);
    const soundingSet = new Set(soundingNotes);

    return (
        <div className="relative rounded overflow-hidden" style={{ width, height, background: '#0a0a0a' }}>
            {/* Split zone overlay */}
            {splitPoint !== undefined ? (
                <div
                    className="absolute top-0 bottom-0 opacity-10"
                    style={{
                        left: 0,
                        width: noteToX(splitPoint),
                        background: 'var(--color-accent-cyan)',
                    }}
                />
            ) : null}

            {/* White keys */}
            {whiteKeys.map((note) => {
                const x = noteToX(note);
                const held = heldSet.has(note);
                const sounding = soundingSet.has(note);
                return (
                    <div
                        key={note}
                        className="absolute bottom-0 border-r border-border/20"
                        style={{
                            left: x,
                            width: whiteKeyWidth - 1,
                            height,
                            background: (() => {
                                if (sounding) {
                                    return 'var(--color-accent-peach)';
                                }
                                if (held) {
                                    return 'var(--color-accent-lavender)';
                                }
                                return '#1a1a1a';
                            })(),
                            opacity: (() => {
                                if (sounding) {
                                    return 0.9;
                                }
                                if (held) {
                                    return 0.7;
                                }
                                return 1;
                            })(),
                            borderRadius: '0 0 2px 2px',
                        }}
                    />
                );
            })}

            {/* Black keys */}
            {blackKeys.map((note) => {
                const x = noteToX(note);
                const held = heldSet.has(note);
                const sounding = soundingSet.has(note);
                return (
                    <div
                        key={note}
                        className="absolute top-0"
                        style={{
                            left: x,
                            width: whiteKeyWidth * 0.6,
                            height: height * 0.6,
                            background: (() => {
                                if (sounding) {
                                    return 'var(--color-accent-peach)';
                                }
                                if (held) {
                                    return 'var(--color-accent-lavender)';
                                }
                                return '#0e0e0e';
                            })(),
                            borderRadius: '0 0 2px 2px',
                            zIndex: 1,
                        }}
                    />
                );
            })}

            {/* Octave labels */}
            {[2, 3, 4, 5, 6].map((oct) => {
                const note = oct * 12 + 12; // Cn
                if (note < RANGE_LOW || note >= RANGE_HIGH) {
                    return null;
                }
                const x = noteToX(note);
                return (
                    <span
                        key={oct}
                        className="absolute text-[5px] text-muted-foreground/30"
                        style={{ left: x + 2, bottom: 1, zIndex: 2 }}
                    >
                        C{oct}
                    </span>
                );
            })}
        </div>
    );
};

/**
 * ProcessorParams — renders parameter controls for a specific Yeast processor.
 * Each processor type gets its own set of knobs/selectors based on its parameters.
 */
import { type ReactElement } from 'react';

import { RotaryKnob } from '#/components/daw/RotaryKnob';

import { type ProcessorType } from '../../useCases/processorFactory';

type OnSetParam = (id: string, name: string, value: number) => void;

type Props = {
    processorId: string;
    processorType: ProcessorType;
    onSetParam: OnSetParam;
};

const K = ({
    id,
    name,
    label,
    value,
    min,
    max,
    step,
    unit,
    onSetParam,
}: {
    id: string;
    name: string;
    label: string;
    value: number;
    min: number;
    max: number;
    step: number;
    unit?: string;
    onSetParam: OnSetParam;
}): ReactElement => (
    <div className="flex flex-col items-center gap-0">
        <RotaryKnob
            value={value}
            onChange={(value1) => onSetParam(id, name, value1)}
            min={min}
            max={max}
            step={step}
            defaultValue={value}
            size="sm"
            tone="rose"
        />
        <span className="text-[6px] text-muted-foreground leading-none">{label}</span>
        {unit ? (
            <span className="text-[5px] text-muted-foreground/40 font-mono">
                {value.toFixed(step < 1 ? 2 : 0)}
                {unit}
            </span>
        ) : null}
    </div>
);

const Sel = ({
    id,
    name,
    label,
    options,
    value,
    onSetParam,
}: {
    id: string;
    name: string;
    label: string;
    options: string[];
    value: number;
    onSetParam: OnSetParam;
}): ReactElement => (
    <div className="flex flex-col items-center gap-0.5">
        <select
            className="h-4 text-[6px] bg-surface-inset border border-border/30 rounded px-0.5 text-foreground cursor-pointer"
            value={value}
            onChange={(event) => onSetParam(id, name, parseInt(event.target.value))}
        >
            {options.map((opt, index) => (
                <option key={index} value={index}>
                    {opt}
                </option>
            ))}
        </select>
        <span className="text-[6px] text-muted-foreground">{label}</span>
    </div>
);

